export var scn_rena = [[0, "蕾娜", "「将臣，小雨！你们刚才是在芳乃房间吗？」", "len414_001.ogg", "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "01"}, "CHAPTER 3-6", null, null], [1, "将臣", "「咦？蕾娜？你不是回去了吗？」", null, "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "01"}, "CHAPTER 3-6", null, null], [2, "", "她白天时说自己还有工作要做，应该是回了一趟志那都庄才对。", null, "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "01"}, "CHAPTER 3-6", null, null], [3, "蕾娜", "「是的！但我听说今晚要一决胜负，就一直放不下心来」", "len414_002.ogg", "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "02"}, "CHAPTER 3-6", null, null], [4, "将臣", "「所以你就特意赶过来了吗」", null, "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "02"}, "CHAPTER 3-6", null, null], [5, "蕾娜", "「咱们是朋友嘛，这点小事是应该的！芳乃她现在没事吗？」", "len414_003.ogg", "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "07"}, "CHAPTER 3-6", null, null], [6, "将臣", "「现在暂时没事。而且她身边还有常陆陪着」", null, "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "07"}, "CHAPTER 3-6", null, null], [7, "丛雨", "「可是蕾娜，你不是也有些耳鸣吗？本座觉得你还是离宿体远一点比较好，耳鸣应该也会轻一些」", "mur414_001.ogg", "朝武_リビングd", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "36"}, "CHAPTER 3-6", null, null], [8, "蕾娜", "「嗯……确实，来到这边之后感觉耳鸣更严重了」", "len414_004.ogg", "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "07"}, "CHAPTER 3-6", null, null], [9, "将臣", "「哎？那你还是不要勉强自己比较好吧」", null, "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "07"}, "CHAPTER 3-6", null, null], [10, "", "这件事牵扯到的人越少越好。", null, "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "07"}, "CHAPTER 3-6", null, null], [11, "蕾娜", "「没事的！我已经差不多习惯了」", "len414_005.ogg", "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "02"}, "CHAPTER 3-6", null, null], [12, "蕾娜", "「倒是将臣，你今早身体状态不太好吧？而且现在脸也有点红」", "len414_006.ogg", "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "29"}, "CHAPTER 3-6", null, null], [13, "蕾娜", "「是不是发烧了呀？」", "len414_007.ogg", "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "06"}, "CHAPTER 3-6", null, null], [14, "将臣", "「我也不知道。傍晚的时候测了下体温，是有一点低烧」", null, "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "06"}, "CHAPTER 3-6", null, null], [15, "蕾娜", "「那你还是再测一遍比较好！来，刚好这有体温计」", "len414_008.ogg", "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "01"}, "CHAPTER 3-6", null, null], [16, "", "蕾娜将手伸向一直放在客厅的急救箱。", null, "朝武_リビングd", "bgm39.opus", null, "CHAPTER 3-6", null, null], [17, "将臣", "「啊，没事的！我没觉得身体不舒服」", null, "朝武_リビングd", "bgm39.opus", null, "CHAPTER 3-6", null, null], [18, "丛雨", "「不，主人，本座也觉得你应该测一测。自己的身体状况可马虎不得」", "mur414_002.ogg", "朝武_リビングd", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "10"}, "CHAPTER 3-6", null, null], [19, "丛雨", "「……不过」", "mur414_003.ogg", "朝武_リビングd", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "10"}, "CHAPTER 3-6", null, null], [20, "蕾娜", "「怎么了，小雨？」", "len414_009.ogg", "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "20"}, "CHAPTER 3-6", null, null], [21, "", "蕾娜一边把温度计递给我，一边望向小雨。", null, "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "20"}, "CHAPTER 3-6", null, null], [22, "丛雨", "「本座在想，芳乃身体状况变差倒还可以理解，毕竟她被直接操控了」", "mur414_004.ogg", "朝武_リビングd", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "36"}, "CHAPTER 3-6", null, null], [23, "丛雨", "「然而主人也头晕加低烧，蕾娜也有些耳鸣」", "mur414_005.ogg", "朝武_リビングd", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "35"}, "CHAPTER 3-6", null, null], [24, "蕾娜", "「将臣，你头晕吗！你真的没有勉强自己吗？！」", "len414_010.ogg", "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "06"}, "CHAPTER 3-6", null, null], [25, "将臣", "「也就一开始有一点头晕而已」", null, "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "06"}, "CHAPTER 3-6", null, null], [26, "将臣", "「小雨怎么突然说起这个？有什么问题吗？」", null, "朝武_リビングd", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "35"}, "CHAPTER 3-6", null, null], [27, "丛雨", "「你想，你们的症状并不相同吧？」", "mur414_006.ogg", "朝武_リビングd", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "11"}, "CHAPTER 3-6", null, null], [28, "丛雨", "「既然都是受了宿体之影响，为何各人的反应差别会如此之大？」", "mur414_007.ogg", "朝武_リビングd", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "26"}, "CHAPTER 3-6", null, null], [29, "", "我和蕾娜不由得对视了一眼。", null, "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "20"}, "CHAPTER 3-6", null, null], [30, "蕾娜", "「这么一说，好像确实有点奇怪……嗯……我也不明白为什么」", "len414_011.ogg", "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "07"}, "CHAPTER 3-6", null, null], [31, "将臣", "「是不是偶然情况，或者是宿体的影响有个人差异？」", null, "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "07"}, "CHAPTER 3-6", null, null], [32, "丛雨", "「也罢，或许并没有什么特殊原因」", "mur414_008.ogg", "朝武_リビングd", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "35"}, "CHAPTER 3-6", null, null], [33, "", "既然连小雨都不知道，那我想再多也是没用的。", null, "朝武_リビングd", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "35"}, "CHAPTER 3-6", null, null], [34, "蕾娜", "「……～！」", "len414_012.ogg", "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "07"}, "CHAPTER 3-6", null, null], [35, "将臣", "「啊，体温计响了。好像已经测完了」", null, "朝武_リビングd", "bgm39.opus", null, "CHAPTER 3-6", null, null], [36, "", "最近的体温计测起来是真的快……", null, "朝武_リビングd", "bgm39.opus", null, "CHAPTER 3-6", null, null], [37, "将臣", "「……啊」", null, "朝武_リビングd", "bgm39.opus", null, "CHAPTER 3-6", null, null], [38, "丛雨", "「怎么了，主人？」", "mur414_009.ogg", "朝武_リビングd", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "03"}, "CHAPTER 3-6", null, null], [39, "", "要是现在撒谎，反而会让她们担心。", null, "朝武_リビングd", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "03"}, "CHAPTER 3-6", null, null], [40, "将臣", "「没什么，就是体温跟刚才一样。都是３７.４度」", null, "朝武_リビングd", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "03"}, "CHAPTER 3-6", null, null], [41, "将臣", "「但我真的没感觉身体不舒服……蕾娜你怎么了？」", null, "朝武_リビングd", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "03"}, "CHAPTER 3-6", null, null], [42, "", "蕾娜紧紧地按着太阳穴，像是在忍耐头痛。", null, "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "18"}, "CHAPTER 3-6", null, null], [43, "蕾娜", "「嗯？啊……你身体没问题吗，但是千万不要勉强哦」", "len414_013.ogg", "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "27"}, "CHAPTER 3-6", null, null], [44, "将臣", "「我不会逞能的。倒是你，耳鸣真的不难受吗？」", null, "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "27"}, "CHAPTER 3-6", null, null], [45, "蕾娜", "「……嗯，已经没事了」", "len414_014.ogg", "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "19"}, "CHAPTER 3-6", null, null], [46, "丛雨", "「还是不要待太久比较好」", "mur414_010.ogg", "朝武_リビングd", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "11"}, "CHAPTER 3-6", null, null], [47, "蕾娜", "「不！我真的已经没事了！就是有那么一瞬间耳鸣加重了而已」", "len414_015.ogg", "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "28"}, "CHAPTER 3-6", null, null], [48, "", "蕾娜握着拳头，表示自己非常精神。", null, "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "02"}, "CHAPTER 3-6", null, null], [49, "", "虽然我还是有点担心她，但我自己还发着低烧，所以也不好多说什么。", null, "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "02"}, "CHAPTER 3-6", null, null], [50, "将臣", "「说起来，朝武是接收到了碎片的信号，所以身体才会在无意识之中动起来吧？」", null, "朝武_リビングd", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "11"}, "CHAPTER 3-6", null, null], [51, "丛雨", "「嗯。主人怎么突然问这个？」", "mur414_011.ogg", "朝武_リビングd", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "17"}, "CHAPTER 3-6", null, null], [52, "将臣", "「那么如果她紧紧抱在怀里的是碎片，那我倒还可以理解。可是，那个……为什么是我呢？」", null, "朝武_リビングd", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "17"}, "CHAPTER 3-6", null, null], [53, "", "今早的事，在蕾娜面前实在是有点难以启齿。", null, "朝武_リビングd", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "17"}, "CHAPTER 3-6", null, null], [54, "", "没必要说的事还是不说为好，免得自掘坟墓。", null, "朝武_リビングd", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "17"}, "CHAPTER 3-6", null, null], [55, "丛雨", "「关于此事，本座也想过」", "mur414_012.ogg", "朝武_リビングd", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "37"}, "CHAPTER 3-6", null, null], [56, "丛雨", "「最坏的情况是，有可能她一个人就跑到山上去了」", "mur414_013.ogg", "朝武_リビングd", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "39"}, "CHAPTER 3-6", null, null], [57, "蕾娜", "「那太危险了。就算山上没有祟神，晚上上山也是很危险的」", "len414_016.ogg", "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "12"}, "CHAPTER 3-6", null, null], [58, "丛雨", "「嗯。然而实际上，她是去了主人的房间」", "mur414_014.ogg", "朝武_リビングd", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "10"}, "CHAPTER 3-6", null, null], [59, "将臣", "「这、这个嘛！你想啊，毕竟宿体和丛雨丸都在我房间里」", null, "朝武_リビングd", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "10"}, "CHAPTER 3-6", null, null], [60, "", "虽然没做什么亏心事，但还是突然有点慌。", null, "朝武_リビングd", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "10"}, "CHAPTER 3-6", null, null], [61, "丛雨", "「不，主人，本座还是得跟你确认一下。你莫非是跟蕾娜一样，身上带着碎片？」", "mur414_015.ogg", "朝武_リビングd", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "14"}, "CHAPTER 3-6", null, null], [62, "丛雨", "「当然，本座不是在怀疑你私藏」", "mur414_016.ogg", "朝武_リビングd", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "24"}, "CHAPTER 3-6", null, null], [63, "丛雨", "「有可能是你自己没有发现，但其实一直带在身上」", "mur414_017.ogg", "朝武_リビングd", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "10"}, "CHAPTER 3-6", null, null], [64, "将臣", "「事到如今，你这么问我也不知道怎么说」", null, "朝武_リビングd", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "10"}, "CHAPTER 3-6", null, null], [65, "蕾娜", "「你可以想想，有没有什么东西是自己一直随身携带的？」", "len414_017.ogg", "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "14"}, "CHAPTER 3-6", null, null], [66, "蕾娜", "「说不定你也跟我一样，把那当成了山妖的护身符」", "len414_018.ogg", "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "27"}, "CHAPTER 3-6", null, null], [67, "", "山妖？这个发音让我想到了游戏或漫画里面出现的巨人型怪物。", null, "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "27"}, "CHAPTER 3-6", null, null], [68, "", "在蕾娜老家那边，是不是那种怪物更像祟神呢？", null, "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "27"}, "CHAPTER 3-6", null, null], [69, "将臣", "「我想想……说实话，我平时很少刻意随身携带什么东西」", null, "朝武_リビングd", "bgm39.opus", null, "CHAPTER 3-6", null, null], [70, "将臣", "「小雨，你是觉得我跟蕾娜一样，因为身上一直带着碎片，所以才会更容易受到影响是吗？」", null, "朝武_リビングd", "bgm39.opus", null, "CHAPTER 3-6", null, null], [71, "丛雨", "「不，本座刚才也说了，你跟蕾娜的症状有所不同」", "mur414_018.ogg", "朝武_リビングd", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "26"}, "CHAPTER 3-6", null, null], [72, "丛雨", "「本座猜想……那说不定正是主人如此特别的原因」", "mur414_019.ogg", "朝武_リビングd", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "11"}, "CHAPTER 3-6", null, null], [73, "将臣", "「啊？」", null, "朝武_リビングd", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "11"}, "CHAPTER 3-6", null, null], [74, "丛雨", "「你不仅被丛雨丸选中，甚至还能触碰本座的身体，不是吗？」", "mur414_020.ogg", "朝武_リビングd", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "24"}, "CHAPTER 3-6", null, null], [75, "丛雨", "「对本座来说，此事一直是个不解之谜」", "mur414_021.ogg", "朝武_リビングd", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "36"}, "CHAPTER 3-6", null, null], [76, "丛雨", "「说不定，你的症状，还有你的特别之处，都是出于同一个原因……虽然这仅仅是猜想」", "mur414_022.ogg", "朝武_リビングd", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "35"}, "CHAPTER 3-6", null, null], [77, "", "可能是由于小雨自己都没有什么把握。", null, "朝武_リビングd", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "35"}, "CHAPTER 3-6", null, null], [78, "", "她说完这些后，似乎也不打算继续说下去了。", null, "朝武_リビングd", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "35"}, "CHAPTER 3-6", null, null], [79, "将臣", "「反正，你说的这些我会留个神的」", null, "朝武_リビングd", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "35"}, "CHAPTER 3-6", null, null], [80, "丛雨", "「拜托了，主人」", "mur414_023.ogg", "朝武_リビングd", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "23"}, "CHAPTER 3-6", null, null], [81, "丛雨", "「……话说回来，这也太慢了」", "mur414_024.ogg", "朝武_リビングd", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "36"}, "CHAPTER 3-6", null, null], [82, "将臣", "「你是说朝武？确实，照理说现在也该睡着了」", null, "朝武_リビングd", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "36"}, "CHAPTER 3-6", null, null], [83, "丛雨", "「嗯，本座去看看情况吧。你们俩在这等着」", "mur414_025.ogg", "朝武_リビングd", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "03"}, "CHAPTER 3-6", null, null], [84, "", "说着，小雨去了朝武的房间。", null, "朝武_リビングd", "bgm39.opus", null, "CHAPTER 3-6", null, null], [85, "", "如果发生了什么，常陆应该会赶来通知的，而且刚才蕾娜耳鸣突然加重，这也确实有点不寻常。", null, "朝武_リビングd", "bgm39.opus", null, "CHAPTER 3-6", null, null], [86, "将臣", "「说起来，蕾娜，刚才你说的山妖的护身符是什么东西？」", null, "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 3-6", null, null], [87, "蕾娜", "「你说那个呀，我们家代代都相信这碎片是山妖的护身符」", "len414_019.ogg", "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "01"}, "CHAPTER 3-6", null, null], [88, "将臣", "「那个山妖，是指祟神吗？」", null, "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "01"}, "CHAPTER 3-6", null, null], [89, "将臣", "「因为你之前没有用过这种说法，所以我有点好奇」", null, "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "01"}, "CHAPTER 3-6", null, null], [90, "蕾娜", "「……该怎么说呢」", "len414_020.ogg", "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "09"}, "CHAPTER 3-6", null, null], [91, "蕾娜", "「日本的话，精灵的种类特别多，比如妖怪、幽灵、吉祥物、八百万神之类的」", "len414_021.ogg", "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 3-6", null, null], [92, "", "震惊！！吉祥物竟然是精灵！", null, "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 3-6", null, null], [93, "蕾娜", "「但是在我们国家，说到精灵，那就是指山妖了」", "len414_022.ogg", "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "01"}, "CHAPTER 3-6", null, null], [94, "将臣", "「真的假的！？」", null, "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "01"}, "CHAPTER 3-6", null, null], [95, "蕾娜", "「有这么不可思议吗？」", "len414_023.ogg", "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "24"}, "CHAPTER 3-6", null, null], [96, "将臣", "「因为……这么说可能有点不礼貌，但你一说山妖，我首先想到的不是精灵，而是怪物」", null, "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "24"}, "CHAPTER 3-6", null, null], [97, "蕾娜", "「哈哈哈！游戏啦电影啦，还有日本的漫画里一般都会把山妖描绘成巨人」", "len414_024.ogg", "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 3-6", null, null], [98, "蕾娜", "「但是在我们国家，它就是个平时住在森林里，喜欢恶作剧的精灵而已」", "len414_025.ogg", "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "02"}, "CHAPTER 3-6", null, null], [99, "蕾娜", "「用游戏或电影中的形象来举例的话，它的形象比较类似于霍比特人那种小矮人」", "len414_026.ogg", "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "02"}, "CHAPTER 3-6", null, null], [100, "", "原来是这样。", null, "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "02"}, "CHAPTER 3-6", null, null], [101, "将臣", "「那为什么到日本来就变成巨人了呢？」", null, "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "01"}, "CHAPTER 3-6", null, null], [102, "蕾娜", "「我猜，应该是和Ｅｄｄａ搞混淆了……Ｅｄｄａ用这里的话说，就是北欧神话里面的泰坦」", "len414_027.ogg", "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "28"}, "CHAPTER 3-6", null, null], [103, "将臣", "「啊，你是北方人吗？」", null, "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "28"}, "CHAPTER 3-6", null, null], [104, "蕾娜", "「是的！……咦？我之前没说过吗？」", "len414_028.ogg", "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "20"}, "CHAPTER 3-6", null, null], [105, "", "毕竟对我这个日本人来说，来自欧洲的都是欧洲人。", null, "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "20"}, "CHAPTER 3-6", null, null], [106, "", "所以之前并没有特别在意蕾娜是哪个国家的。", null, "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "20"}, "CHAPTER 3-6", null, null], [107, "蕾娜", "「我爷爷以前经常给我讲山妖的故事」", "len414_029.ogg", "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 3-6", null, null], [108, "蕾娜", "「然后我爷爷又是从他奶奶那里听来的」", "len414_030.ogg", "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "01"}, "CHAPTER 3-6", null, null], [109, "将臣", "「这样啊……？」", null, "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "01"}, "CHAPTER 3-6", null, null], [110, "", "我记得她爷爷的爷爷是日本人。她爷爷的奶奶，也就是那位日本人的夫人了吧？", null, "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 3-6", null, null], [111, "", "不过，怎么说呢，突然有一种不对劲的感觉。", null, "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 3-6", null, null], [112, "蕾娜", "「他们老一辈的都把碎片当成山妖的馈赠，这么多年一直保护得很好」", "len414_031.ogg", "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "03"}, "CHAPTER 3-6", null, null], [113, "蕾娜", "「毕竟，山妖可是为人们带来幸运的妖精！」", "len414_032.ogg", "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "02"}, "CHAPTER 3-6", null, null], [114, "将臣", "「哎？是这样啊？」", null, "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "02"}, "CHAPTER 3-6", null, null], [115, "", "跟穗织的祟神比起来，给人印象上的差别也真是够大的。", null, "朝武_リビングd", "bgm39.opus", null, "CHAPTER 3-6", null, null], [116, "", "但是我感到不对劲的地方并不是这里。", null, "朝武_リビングd", "bgm39.opus", null, "CHAPTER 3-6", null, null], [117, "", "该怎么说呢？说白了，这种……就是童话故事吧？", null, "朝武_リビングd", "bgm39.opus", null, "CHAPTER 3-6", null, null], [118, "", "总感觉这种故事都是孩子从母亲那里听来的。", null, "朝武_リビングd", "bgm39.opus", null, "CHAPTER 3-6", null, null], [119, "", "但是……也不算很奇怪吧？为什么我会这么在意呢？", null, "朝武_リビングd", "bgm39.opus", null, "CHAPTER 3-6", null, null], [120, "", "也许——", null, "朝武_リビングd", "bgm39.opus", null, "CHAPTER 3-6", null, null], [121, "", "也许是因为蕾娜经常提到自己的爷爷，却从来不提自己的父母。", null, "朝武_リビングd", "bgm39.opus", null, "CHAPTER 3-6", null, null], [122, "蕾娜", "「咦，很奇怪吗？」", "len414_033.ogg", "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 3-6", null, null], [123, "将臣", "「不，也谈不上奇怪……」", null, "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 3-6", null, null], [124, "", "这种私事可以问吗？", null, "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 3-6", null, null], [125, "", "问这种事好像有点干涉隐私了，我不太好意思开口。", null, "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 3-6", null, null], [126, "蕾娜", "「……唔」", "len414_034.ogg", "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "29"}, "CHAPTER 3-6", null, null], [127, "茉子", "「有地，芳乃大人终于睡着了」", "mak414_001.ogg", "朝武_リビングd", "bgm39.opus", {"char": "茉子", "file": "茉子.stand", "dress": "忍者口", "face": "10"}, "CHAPTER 3-6", null, null], [128, "将臣", "「好的，我现在就过去」", null, "朝武_リビングd", "bgm39.opus", {"char": "茉子", "file": "茉子.stand", "dress": "忍者口", "face": "10"}, "CHAPTER 3-6", null, null], [129, "茉子", "「拜托了。不过她似乎并不会立刻就起身……蕾娜？」", "mak414_002.ogg", "朝武_リビングd", "bgm39.opus", {"char": "茉子", "file": "茉子.stand", "dress": "忍者口", "face": "10"}, "CHAPTER 3-6", null, null], [130, "", "我回过头来，发现蕾娜又在按着太阳穴。", null, "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "06"}, "CHAPTER 3-6", null, null], [131, "将臣", "「没、没事吧？又耳鸣了吗？」", null, "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "06"}, "CHAPTER 3-6", null, null], [132, "蕾娜", "「没……没事的！就是，听到比较大的声音时，耳鸣好像就会……略微加重」", "len414_035.ogg", "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "28"}, "CHAPTER 3-6", null, null], [133, "茉子", "「非常抱歉，我开门时应该小点声的」", "mak414_003.ogg", "朝武_リビングd", "bgm39.opus", {"char": "茉子", "file": "茉子.stand", "dress": "忍者口", "face": "07"}, "CHAPTER 3-6", null, null], [134, "蕾娜", "「不，没事的」", "len414_036.ogg", "朝武_リビングd", "bgm39.opus", {"char": "茉子", "file": "茉子.stand", "dress": "忍者口", "face": "07"}, "CHAPTER 3-6", null, null], [135, "蕾娜", "「这、这点小问题，根本不算什么」", "len414_037.ogg", "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "19n"}, "CHAPTER 3-6", null, null], [136, "", "尽管蕾娜努力用笑容面对我们，但眼眶里还是泛出了几滴泪花。", null, "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "19n"}, "CHAPTER 3-6", null, null], [137, "", "她真的没有勉强自己吗？", null, "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "19n"}, "CHAPTER 3-6", null, null], [138, "将臣", "「我觉得还是让蕾娜回志那都庄比较好吧？」", null, "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "19n"}, "CHAPTER 3-6", null, null], [139, "茉子", "「现在让她一个人回去吗？那可能会更危险」", "mak414_004.ogg", "朝武_リビングd", "bgm39.opus", {"char": "茉子", "file": "茉子.stand", "dress": "忍者口", "face": "07"}, "CHAPTER 3-6", null, null], [140, "将臣", "「说得也是」", null, "朝武_リビングd", "bgm39.opus", {"char": "茉子", "file": "茉子.stand", "dress": "忍者口", "face": "07"}, "CHAPTER 3-6", null, null], [141, "蕾娜", "「放、放心！我真的没事，而且给你们添麻烦也不太好」", "len414_038.ogg", "朝武_リビングd", "bgm39.opus", {"char": "茉子", "file": "茉子.stand", "dress": "忍者口", "face": "07"}, "CHAPTER 3-6", null, null], [142, "茉子", "「不用这么客气，这里还有空房，你先过去休息休息吧」", "mak414_005.ogg", "朝武_リビングd", "bgm39.opus", {"char": "茉子", "file": "茉子.stand", "dress": "忍者口", "face": "03"}, "CHAPTER 3-6", null, null], [143, "蕾娜", "「可是……」", "len414_039.ogg", "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "29"}, "CHAPTER 3-6", null, null], [144, "将臣", "「别勉强自己，还是去休息下比较好，蕾娜」", null, "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "29"}, "CHAPTER 3-6", null, null], [145, "", "蕾娜依然在犹豫，但耳鸣似乎又加重了一些。", null, "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "12"}, "CHAPTER 3-6", null, null], [146, "", "她按太阳穴的力道看上去比刚才更强了。", null, "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "18"}, "CHAPTER 3-6", null, null], [147, "蕾娜", "「呜呜，我擅自跑来看看情况，结果却给你们添麻烦了……真是抱歉」", "len414_040.ogg", "朝武_リビングd", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "29"}, "CHAPTER 3-6", null, null], [148, "茉子", "「没事的，有你这份心意就足够了。芳乃大人肯定也会感谢你的」", "mak414_006.ogg", "朝武_リビングd", "bgm39.opus", {"char": "茉子", "file": "茉子.stand", "dress": "忍者口", "face": "02"}, "CHAPTER 3-6", null, null], [149, "将臣", "「我才应该道歉，跟你一起待这么久却没注意到」", null, "朝武_リビングd", "bgm39.opus", {"char": "茉子", "file": "茉子.stand", "dress": "忍者口", "face": "01"}, "CHAPTER 3-6", null, null], [150, "蕾娜", "「哈哈……这种事不用放在心上啦。耳鸣是刚刚才开始加重的」", "len414_041.ogg", "朝武_リビングd", "bgm39.opus", {"char": "茉子", "file": "茉子.stand", "dress": "忍者口", "face": "01"}, "CHAPTER 3-6", null, null], [151, "", "蕾娜似乎已经站不住了，半个身体都靠在常陆身上。", null, "朝武_リビングd", "bgm39.opus", {"char": "茉子", "file": "茉子.stand", "dress": "忍者口", "face": "01"}, "CHAPTER 3-6", null, null], [152, "", "真的没事吗？", null, "朝武_リビングd", "bgm39.opus", {"char": "茉子", "file": "茉子.stand", "dress": "忍者口", "face": "01"}, "CHAPTER 3-6", null, null], [153, "茉子", "「那蕾娜就交给我吧。有地，你不先休息下吗？」", "mak414_007.ogg", "朝武_リビングd", "bgm39.opus", {"char": "茉子", "file": "茉子.stand", "dress": "忍者口", "face": "01"}, "CHAPTER 3-6", null, null], [154, "将臣", "「……嗯，我想想」", null, "朝武_リビングd", "bgm39.opus", {"char": "茉子", "file": "茉子.stand", "dress": "忍者口", "face": "01"}, "CHAPTER 3-6", null, null], [155, "", "这时候让女孩子来照顾她确实更合适吧。", null, "朝武_リビングd", "bgm39.opus", null, "CHAPTER 3-6", null, null], [156, "将臣", "「好的，那就拜托你了。我先去朝武那里看看」", null, "朝武_リビングd", "bgm39.opus", null, "CHAPTER 3-6", null, null], [157, "", "然而，刚一进房间——", null, "朝武_芳乃の部屋d", "bgm39.opus", null, "CHAPTER 3-6", null, null], [158, "芳乃", "「啊，你来了」", "yos414_001.ogg", "朝武_芳乃の部屋d", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服耳", "face": "28"}, "CHAPTER 3-6", null, null], [159, "将臣", "「咦，朝武？你不是已经睡了吗」", null, "朝武_芳乃の部屋d", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服耳", "face": "28"}, "CHAPTER 3-6", null, null], [160, "芳乃", "「这个……刚才好像睡着了一小会儿，但是马上又醒了」", "yos414_002.ogg", "朝武_芳乃の部屋d", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服耳", "face": "09"}, "CHAPTER 3-6", null, null], [161, "", "她看上去有些尴尬。", null, "朝武_芳乃の部屋d", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服耳", "face": "09"}, "CHAPTER 3-6", null, null], [162, "丛雨", "「这也是没办法的事」", "mur414_026.ogg", "朝武_芳乃の部屋d", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "31"}, "CHAPTER 3-6", null, null], [163, "将臣", "「那我们是得再等一会儿，等到朝武睡着吗？」", null, "朝武_芳乃の部屋d", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "31"}, "CHAPTER 3-6", null, null], [164, "芳乃", "「抱歉」", "yos414_003.ogg", "朝武_芳乃の部屋d", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服耳", "face": "09"}, "CHAPTER 3-6", null, null], [165, "将臣", "「没关系的」", null, "朝武_芳乃の部屋d", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服耳", "face": "09"}, "CHAPTER 3-6", null, null], [166, "", "不过，这样也刚好。", null, "朝武_芳乃の部屋d", "bgm39.opus", null, "CHAPTER 3-6", null, null], [167, "", "反正我也挺担心蕾娜的，实在不行的话还是把她送回旅馆比较好。", null, "朝武_芳乃の部屋d", "bgm39.opus", null, "CHAPTER 3-6", null, null], [168, "", "我送她回来之前让朝武先别急着睡，应该就没什么危险了。", null, "朝武_芳乃の部屋d", "bgm39.opus", null, "CHAPTER 3-6", null, null], [169, "将臣", "「那刚好，朝武，小雨，有件事跟你们商量下……」", null, "朝武_芳乃の部屋d", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服耳", "face": "41"}, "CHAPTER 3-6", null, null], [170, "", "就在这时，走廊上传来了慌慌忙忙的脚步声。", null, "朝武_芳乃の部屋d", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服耳", "face": "41"}, "CHAPTER 3-6", null, null], [171, "茉子", "「芳乃大人，您醒了啊！」", "mak414_008.ogg", "朝武_芳乃の部屋d", "bgm39.opus", {"char": "茉子", "file": "茉子.stand", "dress": "忍者口", "face": "04"}, "CHAPTER 3-6", null, null], [172, "芳乃", "「嗯。茉子，你怎么了，怎么这么慌张？」", "yos414_004.ogg", "朝武_芳乃の部屋d", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服耳", "face": "07"}, "CHAPTER 3-6", null, null], [173, "将臣", "「等等，你不是送蕾娜去客房休息了吗？」", null, "朝武_芳乃の部屋d", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服耳", "face": "07"}, "CHAPTER 3-6", null, null], [174, "茉子", "「是的，可是……」", "mak414_009.ogg", "朝武_芳乃の部屋d", "bgm39.opus", {"char": "茉子", "file": "茉子.stand", "dress": "忍者口", "face": "07"}, "CHAPTER 3-6", null, null], [175, "茉子", "「不知道为什么，蕾娜好像先被吸引过去了」", "mak414_010.ogg", "朝武_芳乃の部屋d", "bgm39.opus", {"char": "茉子", "file": "茉子.stand", "dress": "忍者口", "face": "36"}, "CHAPTER 3-6", null, null], [176, "芳乃", "「这是怎么……哎？」", "yos414_005.ogg", "朝武_芳乃の部屋d", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服耳", "face": "31"}, "CHAPTER 3-6", null, null], [177, "", "朝武看了看手中的宿体。", null, "朝武_芳乃の部屋d", "bgm39.opus", null, "CHAPTER 3-6", null, null], [178, "", "不知从何时起，宿体闪烁红光的频率明显变得更加急促了。", null, "朝武_芳乃の部屋d", "bgm39.opus", null, "CHAPTER 3-6", null, null], [179, "", "朝武醒了之后，我们都彻底放松了警惕。", null, "朝武_芳乃の部屋d", "bgm39.opus", null, "CHAPTER 3-6", null, null], [180, "将臣", "「也就是说，现在蕾娜被操控了吗！不是吧，怎么会这样？」", null, "朝武_芳乃の部屋d", "bgm39.opus", null, "CHAPTER 3-6", null, null], [181, "茉子", "「很遗憾，就是这么回事」", "mak414_011.ogg", "朝武_芳乃の部屋d", "bgm39.opus", {"char": "茉子", "file": "茉子.stand", "dress": "忍者口", "face": "39"}, "CHAPTER 3-6", null, null], [182, "芳乃", "「难以置信！为什么被操控的不是我，而是蕾娜！？」", "yos414_006.ogg", "朝武_芳乃の部屋d", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服耳", "face": "12"}, "CHAPTER 3-6", null, null], [183, "丛雨", "「哎，行了，现在讨论这个也没意义！总之赶快去追她」", "mur414_027.ogg", "朝武_芳乃の部屋d", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服耳", "face": "12"}, "CHAPTER 3-6", null, null], [184, "蕾娜", "「…………」", "len414_042.ogg", "山_山道c", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "29"}, "CHAPTER 3-6", null, null], [185, "", "万幸的是，我们马上就追上了蕾娜。", null, "山_山道c", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "29"}, "CHAPTER 3-6", null, null], [186, "", "然而她步履蹒跚地在山间行走的样子，看上去就像断了线的风筝一样。", null, "山_山道c", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "29"}, "CHAPTER 3-6", null, null], [187, "芳乃", "「怎么会这样！蕾娜明明跟诅咒没有直接关系，竟然也会被碎片吸引……这种事也会发生吗？」", "yos414_007.ogg", "山_山道c", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服耳", "face": "28"}, "CHAPTER 3-6", null, null], [188, "丛雨", "「本座也没料到」", "mur414_028.ogg", "山_山道c", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服耳", "face": "28"}, "CHAPTER 3-6", null, null], [189, "丛雨", "「而且她并没有被我们手上的宿体吸引过来，而是被吸引到山上去了」", "mur414_029.ogg", "山_山道c", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "36"}, "CHAPTER 3-6", null, null], [190, "", "也就是说，跟朝武的情况并不一样。", null, "山_山道c", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "29"}, "CHAPTER 3-6", null, null], [191, "将臣", "「必须马上把蕾娜叫醒！」", null, "山_山道c", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "29"}, "CHAPTER 3-6", null, null], [192, "丛雨", "「先等等，这说不定是个好机会」", "mur414_030.ogg", "山_山道c", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "28"}, "CHAPTER 3-6", null, null], [193, "将臣", "「为什么？朝武的兽耳还长在脑袋上，如果这时祟神出现了，我们也没办法知道吧？」", null, "山_山道c", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "10"}, "CHAPTER 3-6", null, null], [194, "将臣", "「虽然我们昨天刚刚祓除掉一只，今天出现的可能性不大」", null, "山_山道c", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "10"}, "CHAPTER 3-6", null, null], [195, "丛雨", "「不，以前也有过连续出现的例子」", "mur414_031.ogg", "山_山道c", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "17"}, "CHAPTER 3-6", null, null], [196, "芳乃", "「那我们更应该把她叫醒！否则我们的打斗可能又会波及到她」", "yos414_008.ogg", "山_山道c", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服耳", "face": "34"}, "CHAPTER 3-6", null, null], [197, "茉子", "「是的……但是目前的情况，跟我们最初的计划一样」", "mak414_012.ogg", "山_山道c", "bgm39.opus", {"char": "茉子", "file": "茉子.stand", "dress": "忍者口", "face": "40"}, "CHAPTER 3-6", null, null], [198, "芳乃", "「茉子！？」", "yos414_009.ogg", "山_山道c", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服耳", "face": "06"}, "CHAPTER 3-6", null, null], [199, "丛雨", "「没错。即便祟神现身，芳乃也可加入战斗，这对我们来说反而是个优势」", "mur414_032.ogg", "山_山道c", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "01"}, "CHAPTER 3-6", null, null], [200, "芳乃", "「等等！丛雨大人，难道您打算把蕾娜当做诱饵吗！」", "yos414_010.ogg", "山_山道c", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服耳", "face": "49"}, "CHAPTER 3-6", null, null], [201, "丛雨", "「都说了，谁也不确定会不会真的出现祟神」", "mur414_033.ogg", "山_山道c", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "14"}, "CHAPTER 3-6", null, null], [202, "丛雨", "「再说了，芳乃，就算把你当成诱饵，也一样很危险」", "mur414_034.ogg", "山_山道c", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "10"}, "CHAPTER 3-6", null, null], [203, "丛雨", "「现在，蕾娜已经多多少少受到宿体的影响了」", "mur414_035.ogg", "山_山道c", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "11"}, "CHAPTER 3-6", null, null], [204, "丛雨", "「就算现在中止计划，下次她甚至有可能会在我们看不见的地方被操控，这个你想过吗？」", "mur414_036.ogg", "山_山道c", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "28"}, "CHAPTER 3-6", null, null], [205, "芳乃", "「这个……虽然确实有这种可能，但是蕾娜……跟诅咒是真的没有任何关系啊」", "yos414_011.ogg", "山_山道c", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服耳", "face": "07"}, "CHAPTER 3-6", null, null], [206, "丛雨", "「这本座当然知道。但是，现在我们已经没有退路了」", "mur414_037.ogg", "山_山道c", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服耳", "face": "07"}, "CHAPTER 3-6", null, null], [207, "丛雨", "「芳乃，做好心理准备吧！出现突发情况时，我们要好好保护她」", "mur414_038.ogg", "山_山道c", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "16"}, "CHAPTER 3-6", null, null], [208, "", "从感情上来说，我是赞同朝武的。", null, "山_山道c", "bgm39.opus", null, "CHAPTER 3-6", null, null], [209, "", "蕾娜从外国远道而来，我也不想因为这件事连累她。", null, "山_山道c", "bgm39.opus", null, "CHAPTER 3-6", null, null], [210, "", "但我也不得不承认，小雨的意见更加合理。", null, "山_山道c", "bgm39.opus", null, "CHAPTER 3-6", null, null], [211, "芳乃", "「啊——真是的……那就按您说的做吧」", "yos414_012.ogg", "山_山道c", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服耳", "face": "46"}, "CHAPTER 3-6", null, null], [212, "芳乃", "「但是我们必须要保护蕾娜到最后一刻！明白了吗？」", "yos414_013.ogg", "山_山道c", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服耳", "face": "28"}, "CHAPTER 3-6", null, null], [213, "将臣", "「那当然」", null, "山_山道c", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服耳", "face": "28"}, "CHAPTER 3-6", null, null], [214, "", "到了这个节骨眼上，我们已经无路可退了。", null, "山_山道c", "bgm39.opus", null, "CHAPTER 3-6", null, null], [215, "", "我用力握紧了丛雨丸。", null, "山_山道c", "bgm39.opus", null, "CHAPTER 3-6", null, null], [216, "", "就这样，我们跟着蕾娜一路走进了山里。", null, "山_山の中１c", "bgm28.opus", null, "CHAPTER 3-6", null, null], [217, "茉子", "「她到底是在往哪走呢？」", "mak414_013.ogg", "山_山の中１c", "bgm28.opus", {"char": "茉子", "file": "茉子.stand", "dress": "忍者口", "face": "07"}, "CHAPTER 3-6", null, null], [218, "芳乃", "「如果跟预想的情况一样，她应该会一个接一个找到碎片……是这样的吧？」", "yos414_014.ogg", "山_山の中１c", "bgm28.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服耳", "face": "17"}, "CHAPTER 3-6", null, null], [219, "", "但蕾娜对我们手里的宿体毫无反应。", null, "山_山の中１c", "bgm28.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服耳", "face": "17"}, "CHAPTER 3-6", null, null], [220, "", "与此同时，宿体的反应也越来越强烈。", null, "山_山の中１c", "bgm28.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服耳", "face": "17"}, "CHAPTER 3-6", null, null], [221, "将臣", "「小雨，你能感知到这附近的碎片吗？」", null, "山_山の中１c", "bgm28.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "36"}, "CHAPTER 3-6", null, null], [222, "丛雨", "「对不住……宿体释放的信号太强了，本座无法感知到其他东西」", "mur414_039.ogg", "山_山の中１c", "bgm28.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "25"}, "CHAPTER 3-6", null, null], [223, "丛雨", "「先不说这个，主人和芳乃的身体状况没什么变化吗？」", "mur414_040.ogg", "山_山の中１c", "bgm28.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "10"}, "CHAPTER 3-6", null, null], [224, "将臣", "「我没事」", null, "山_山の中１c", "bgm28.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "10"}, "CHAPTER 3-6", null, null], [225, "芳乃", "「我也没事……不过」", "yos414_015.ogg", "山_山の中１c", "bgm28.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服耳", "face": "30"}, "CHAPTER 3-6", null, null], [226, "丛雨", "「怎么了，你还在犹豫要不要让蕾娜当诱饵吗？」", "mur414_041.ogg", "山_山の中１c", "bgm28.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服耳", "face": "30"}, "CHAPTER 3-6", null, null], [227, "芳乃", "「虽然确实有一点犹豫，但现在想的不是这个」", "yos414_016.ogg", "山_山の中１c", "bgm28.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服耳", "face": "36"}, "CHAPTER 3-6", null, null], [228, "芳乃", "「我现在越来越想不通了，为什么蕾娜会被控制呢？您不觉得奇怪吗？」", "yos414_017.ogg", "山_山の中１c", "bgm28.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服耳", "face": "30"}, "CHAPTER 3-6", null, null], [229, "丛雨", "「确实」", "mur414_042.ogg", "山_山の中１c", "bgm28.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服耳", "face": "30"}, "CHAPTER 3-6", null, null], [230, "将臣", "「我们是身体变热，但蕾娜却是耳鸣吧？」", null, "山_山の中１c", "bgm28.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服耳", "face": "30"}, "CHAPTER 3-6", null, null], [231, "将臣", "「难道是因为声音之类的吗？比如说是被什么东西呼唤了」", null, "山_山の中１c", "bgm28.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服耳", "face": "30"}, "CHAPTER 3-6", null, null], [232, "芳乃", "「不会吧！你是说碎片在呼唤蕾娜吗？」", "yos414_018.ogg", "山_山の中１c", "bgm28.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服耳", "face": "06"}, "CHAPTER 3-6", null, null], [233, "将臣", "「不，这只是我的猜测而已，我也不确定」", null, "山_山の中１c", "bgm28.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服耳", "face": "06"}, "CHAPTER 3-6", null, null], [234, "茉子", "「各位，先别争了」", "mak414_014.ogg", "山_山の中１c", "bgm28.opus", {"char": "茉子", "file": "茉子.stand", "dress": "忍者口", "face": "21"}, "CHAPTER 3-6", null, null], [235, "茉子", "「这附近好像有什么动静」", "mak414_015.ogg", "山_山の中１c", "bgm28.opus", {"char": "茉子", "file": "茉子.stand", "dress": "忍者口", "face": "19"}, "CHAPTER 3-6", null, null], [236, "", "蕾娜似乎停了下来。", null, "山_山の中１c", "bgm28.opus", null, "CHAPTER 3-6", null, null], [237, "", "难道她脚下掉落着碎片吗？", null, "山_山の中１c", "bgm28.opus", null, "CHAPTER 3-6", null, null], [238, "", "正当我准备上前确认的时候——", null, "山_山の中１c", "bgm28.opus", null, "CHAPTER 3-6", null, null], [239, "将臣", "「唔啊！？」", null, "山_山の中１c", "bgm28.opus", null, "CHAPTER 3-6", null, null], [240, "芳乃", "「怎、怎么回事，刚才那是什么声音？好强烈的耳鸣啊！」", "yos414_019.ogg", "山_山の中１c", "bgm28.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服耳", "face": "07"}, "CHAPTER 3-6", null, null], [241, "茉子", "「好像是从蕾娜那边传来的，丛雨大人知道是怎么回事吗？」", "mak414_016.ogg", "山_山の中１c", "bgm28.opus", {"char": "茉子", "file": "茉子.stand", "dress": "忍者口", "face": "41"}, "CHAPTER 3-6", null, null], [242, "丛雨", "「不知道。但是……」", "mur414_043.ogg", "山_山の中１c", "bgm28.opus", {"char": "茉子", "file": "茉子.stand", "dress": "忍者口", "face": "41"}, "CHAPTER 3-6", null, null], [243, "", "要出什么事了。", null, "山_山の中１c", "bgm12.opus", {"char": "茉子", "file": "茉子.stand", "dress": "忍者口", "face": "41"}, "CHAPTER 3-6", null, null], [244, "", "而且肯定是不好的事。我有种不祥的预感。", null, "山_山の中１c", "bgm12.opus", {"char": "茉子", "file": "茉子.stand", "dress": "忍者口", "face": "41"}, "CHAPTER 3-6", null, null], [245, "将臣", "「小雨！」", null, "山_山の中１c", "bgm12.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "26"}, "CHAPTER 3-6", null, null], [246, "丛雨", "「明白，主人千万要小心啊」", "mur414_044.ogg", "山_山の中１c", "bgm12.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "14"}, "CHAPTER 3-6", null, null], [247, "", "丛雨丸发出了淡淡清光。", null, "山_山の中１c", "bgm12.opus", null, "CHAPTER 3-6", null, null], [248, "", "与此同时，我们三人背靠背围成一圈，３６０°全方位地观察着周边的情况。", null, "山_山の中１c", "bgm12.opus", null, "CHAPTER 3-6", null, null], [249, "茉子", "「那边，草丛后面有动静！」", "mak414_017.ogg", "山_山の中１c", "bgm12.opus", {"char": "茉子", "file": "茉子.stand", "dress": "クナイ", "face": "19"}, "CHAPTER 3-6", null, null], [250, "", "话音刚落，我便看见了黑色触手一样的影子。", null, "山_山の中１c", "bgm12.opus", null, "CHAPTER 3-6", null, null], [251, "", "现在的我是不可能看错的。", null, "山_山の中１c", "bgm12.opus", null, "CHAPTER 3-6", null, null], [252, "将臣", "「常陆，你来掩护我！我打头阵」", null, "山_山の中１c", "bgm29.opus", null, "CHAPTER 3-6", null, null], [253, "", "祟神的攻击方式很单调。", null, "山_山の中１c", "bgm29.opus", null, "CHAPTER 3-6", null, null], [254, "", "我驾轻就熟地躲过了它的触手攻击，一口气冲到了它跟前。", null, "山_山の中１c", "bgm29.opus", null, "CHAPTER 3-6", null, null], [255, "", "只要用丛雨丸击中它们即可，甚至不用劈下去。", null, "山_山の中１c", "bgm29.opus", null, "CHAPTER 3-6", null, null], [256, "", "我尽可能地控制了动作的幅度，用最小的力气击中了祟神的要害。", null, "山_山の中１c", "bgm29.opus", null, "CHAPTER 3-6", null, null], [257, "", "我今天的状态真是不错。", null, "山_山の中１c", "bgm29.opus", null, "CHAPTER 3-6", null, null], [258, "", "要是现在去跟外公比试，说不定能击中他一次？脑海里不禁浮现出这样的自恋妄想。没办法，刚才那一击确实太完美了。", null, "山_山の中１c", "bgm29.opus", null, "CHAPTER 3-6", null, null], [259, "", "一眨眼的功夫，漆黑的泥团就像雾气一样消散。", null, "山_山の中１c", "bgm29.opus", null, "CHAPTER 3-6", null, null], [260, "", "这样一来，碎片就又多了一份。", null, "山_山の中１c", "bgm29.opus", null, "CHAPTER 3-6", null, null], [261, "将臣", "「呼，比想象中的简单不少啊。你们俩有没有受伤……咦？」", null, "山_山の中１c", "bgm29.opus", null, "CHAPTER 3-6", null, null], [262, "", "我明明拜托她们掩护我，但她们却仍然一动不动地站在原地。", null, "山_山の中１c", "bgm29.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服耳", "face": "31"}, "CHAPTER 3-6", null, null], [263, "", "不仅站在原地，甚至根本就没有在看我。", null, "山_山の中１c", "bgm29.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服耳", "face": "31"}, "CHAPTER 3-6", null, null], [264, "将臣", "「你们这是怎么了……？」", null, "山_山の中１c", "bgm29.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服耳", "face": "31"}, "CHAPTER 3-6", null, null], [265, "芳乃", "「……有、有地」", "yos414_020.ogg", "山_山の中１c", "bgm29.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "鉾鈴耳", "face": "07"}, "CHAPTER 3-6", null, null], [266, "", "朝武用这种语气说话真是相当少见。不，我应该是头一次听到？", null, "山_山の中１c", "bgm29.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "鉾鈴耳", "face": "07"}, "CHAPTER 3-6", null, null], [267, "", "她的话语声中充满了恐惧。", null, "山_山の中１c", "bgm29.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "鉾鈴耳", "face": "07"}, "CHAPTER 3-6", null, null], [268, "", "就在她手指所指的方向——", null, "山_山の中１c", "bgm29.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "鉾鈴耳", "face": "07"}, "CHAPTER 3-6", null, null], [269, "丛雨", "『唔，这下糟了』", "mur414_045.ogg", "山_山の中１c", "bgm29.opus", null, "CHAPTER 3-6", null, null], [270, "丛雨", "『真不敢相信，也不愿相信这是真的』", "mur414_046.ogg", "山_山の中１c", "bgm29.opus", null, "CHAPTER 3-6", null, null], [271, "", "就连小雨也说出了这样的话。", null, "山_山の中１c", "bgm29.opus", null, "CHAPTER 3-6", null, null], [272, "", "正面才刚出现一只，竟然又有两只从后面冒了出来！", null, "山_山の中１c", "bgm29.opus", null, "CHAPTER 3-6", null, null], [273, "茉子", "「等、等等，又有新的出现了！山顶那边也有……咦？！」", "mak414_018.ogg", "山_山の中１c", "bgm29.opus", {"char": "茉子", "file": "茉子.stand", "dress": "クナイ", "face": "32"}, "CHAPTER 3-6", null, null], [274, "茉子", "「我看见的大约有五只，这不是我的错觉吧？」", "mak414_019.ogg", "山_山の中１c", "bgm29.opus", {"char": "茉子", "file": "茉子.stand", "dress": "クナイ", "face": "34"}, "CHAPTER 3-6", null, null], [275, "丛雨", "『不，祟神的气息越来越强，越来越浓』", "mur414_047.ogg", "山_山の中１c", "bgm29.opus", null, "CHAPTER 3-6", null, null], [276, "将臣", "「到底有多少只啊？」", null, "山_山の中１c", "bgm29.opus", null, "CHAPTER 3-6", null, null], [277, "丛雨", "『至少是眼前这些的两倍吧』", "mur414_048.ogg", "山_山の中１c", "bgm29.opus", null, "CHAPTER 3-6", null, null], [278, "将臣", "「什么？！」", null, "山_山の中１c", "bgm29.opus", null, "CHAPTER 3-6", null, null], [279, "", "真不该问。", null, "山_山の中１c", "bgm29.opus", null, "CHAPTER 3-6", null, null], [280, "丛雨", "『而且这已经是本座的保守估计了』", "mur414_049.ogg", "山_山の中１c", "bgm29.opus", null, "CHAPTER 3-6", null, null], [281, "茉子", "「说不定还会有更多……」", "mak414_020.ogg", "山_山の中１c", "bgm29.opus", {"char": "茉子", "file": "茉子.stand", "dress": "クナイ", "face": "13"}, "CHAPTER 3-6", null, null], [282, "芳乃", "「再这样下去，我们会被包围的吧……」", "yos414_021.ogg", "山_山の中１c", "bgm29.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "鉾鈴耳", "face": "06"}, "CHAPTER 3-6", null, null], [283, "", "既然如此，那就没别的办法了。", null, "山_山の中１c", "bgm29.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "鉾鈴耳", "face": "06"}, "CHAPTER 3-6", null, null], [284, "将臣", "「快逃吧！」", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 3-6", null, null], [285, "蕾娜", "「…………」", "len414_043.ogg", "山_山の中１c", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "29"}, "CHAPTER 3-6", null, null], [286, "", "我冲向还没恢复意识的蕾娜，一口气把她扛在肩上。", null, "山_山の中１c", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "29"}, "CHAPTER 3-6", null, null], [287, "", "然后立刻如脱兔一般飞奔了出去。", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 3-6", null, null], [288, "", "但是欧美人的骨格似乎跟日本人不太一样，她身体相当结实，比看上去要重得多。", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 3-6", null, null], [289, "", "就在这时，无数条触手向我袭来。", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 3-6", null, null], [290, "将臣", "「唔啊！？我躲！」", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 3-6", null, null], [291, "", "触手接二连三地打向地面，掀起大片土块砸在我背上。我只能加速逃跑。", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 3-6", null, null], [292, "", "要是被触手击中一次，我的骨头恐怕就要断了。", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 3-6", null, null], [293, "", "我一个劲地向前冲，使出了吃奶的力气狂奔。", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 3-6", null, null], [294, "", "只恨敌我数量差异实在太大，就算我今天状态不错，我方战斗人员比原计划多了一人，也是无济于事。", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 3-6", null, null], [295, "", "现在我们根本没有胜算。", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 3-6", null, null], [296, "", "再加上我肩膀上还扛着一个女生，想拉开距离都做不到。", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 3-6", null, null], [297, "", "别说拉开差距了，祟神反而离我们越来越近。", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 3-6", null, null], [298, "丛雨", "『主人，危险！』", "mur414_050.ogg", "山_山の中１c", "bgm30.opus", null, "CHAPTER 3-6", null, null], [299, "将臣", "「哇啊！？」", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 3-6", null, null], [300, "", "两侧的草丛中又窜出来两只！", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 3-6", null, null], [301, "", "我强行扭转身体，勉强躲了过去。", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 3-6", null, null], [302, "", "下一秒，触手就击中了我刚才站立的位置。", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 3-6", null, null], [303, "将臣", "「躲掉了！…………啊」", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 3-6", null, null], [304, "", "然而刚刚躲过一击，立刻又冒出来一只。", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 3-6", null, null], [305, "", "不行，我站还没站稳。", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 3-6", null, null], [306, "", "为了保护蕾娜，我只能用自己的身体接下——", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 3-6", null, null], [307, "芳乃", "「哈啊！！有地，你快跑！」", "yos414_022.ogg", "山_山の中１c", "bgm30.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "鉾鈴耳", "face": "21"}, "CHAPTER 3-6", null, null], [308, "将臣", "「朝武？谢谢！」", null, "山_山の中１c", "bgm30.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "鉾鈴耳", "face": "21"}, "CHAPTER 3-6", null, null], [309, "", "就在千钧一发之际，朝武用她的鉾铃切断了祟神的触手。", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 3-6", null, null], [310, "茉子", "「丛雨丸我来拿着！」", "mak414_021.ogg", "山_山の中１c", "bgm30.opus", {"char": "茉子", "file": "茉子.stand", "dress": "忍者", "face": "22"}, "CHAPTER 3-6", null, null], [311, "将臣", "「拜托了！」", null, "山_山の中１c", "bgm30.opus", {"char": "茉子", "file": "茉子.stand", "dress": "忍者", "face": "22"}, "CHAPTER 3-6", null, null], [312, "", "在这种情况下，我根本没有精力持刀应战。", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 3-6", null, null], [313, "", "小雨似乎也是这么想的，她立刻解除了同化状态。", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 3-6", null, null], [314, "丛雨", "「主人，跑快点！」", "mur414_051.ogg", "山_山の中１c", "bgm30.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "14"}, "CHAPTER 3-6", null, null], [315, "将臣", "「我、我知道……蕾娜！你醒醒啊，蕾娜？」", null, "山_山の中１c", "bgm30.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "14"}, "CHAPTER 3-6", null, null], [316, "蕾娜", "「……嗯……为什么……你们都在？」", "len414_044.ogg", "山_山の中１c", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "29"}, "CHAPTER 3-6", null, null], [317, "", "太好了，终于醒了！", null, "山_山の中１c", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "29"}, "CHAPTER 3-6", null, null], [318, "", "如果一个人跑，应该有办法逃脱……", null, "山_山の中１c", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "29"}, "CHAPTER 3-6", null, null], [319, "蕾娜", "「哇啊……好厉害，全是好吃的……太棒了，唔……」", "len414_045.ogg", "山_山の中１c", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "16"}, "CHAPTER 3-6", null, null], [320, "将臣", "「并没有醒！？」", null, "山_山の中１c", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "16"}, "CHAPTER 3-6", null, null], [321, "", "我刚才扛着蕾娜的时候，明明跌了一跤啊？", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 3-6", null, null], [322, "", "这都没醒也太奇怪了。", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 3-6", null, null], [323, "将臣", "「小雨！」", null, "山_山の中１c", "bgm30.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "鉾鈴耳", "face": "35"}, "CHAPTER 3-6", null, null], [324, "丛雨", "「芳乃，宿体的状况如何？」", "mur414_052.ogg", "山_山の中１c", "bgm30.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "鉾鈴耳", "face": "35"}, "CHAPTER 3-6", null, null], [325, "芳乃", "「哎？宿体还跟之前一样，红光闪个不停」", "yos414_023.ogg", "山_山の中１c", "bgm30.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "鉾鈴耳", "face": "30"}, "CHAPTER 3-6", null, null], [326, "丛雨", "「果然很奇怪」", "mur414_053.ogg", "山_山の中１c", "bgm30.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "26"}, "CHAPTER 3-6", null, null], [327, "丛雨", "「从刚才开始，它们一直在攻击扛着蕾娜的主人，对拿着宿体的芳乃却无动于衷」", "mur414_054.ogg", "山_山の中１c", "bgm30.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "14"}, "CHAPTER 3-6", null, null], [328, "将臣", "「难道，祟神的目标是蕾娜？」", null, "山_山の中１c", "bgm30.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "14"}, "CHAPTER 3-6", null, null], [329, "芳乃", "「这怎么会！之前它们一直是攻击我的啊」", "yos414_024.ogg", "山_山の中１c", "bgm30.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "鉾鈴耳", "face": "07"}, "CHAPTER 3-6", null, null], [330, "丛雨", "「但是蕾娜发出那阵强烈的耳鸣声之后，这些家伙就聚过来了」", "mur414_055.ogg", "山_山の中１c", "bgm30.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "鉾鈴耳", "face": "07"}, "CHAPTER 3-6", null, null], [331, "蕾娜", "「呼呼……就是呀，你们知道吗……志那都庄的厨师长……拿出了所有的本事……」", "len414_046.ogg", "山_山の中１c", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "35"}, "CHAPTER 3-6", null, null], [332, "", "蕾娜对刚刚发生的事情依旧浑然不觉，一脸毫无紧张感的傻笑表情。", null, "山_山の中１c", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "35"}, "CHAPTER 3-6", null, null], [333, "丛雨", "「我们把宿体拿到蕾娜身边试试吧」", "mur414_056.ogg", "山_山の中１c", "bgm30.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "14"}, "CHAPTER 3-6", null, null], [334, "芳乃", "「好的……哇」", "yos414_025.ogg", "山_山の中１c", "bgm30.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "鉾鈴耳", "face": "32"}, "CHAPTER 3-6", null, null], [335, "芳乃", "「反、反应比刚才更强了……哎？！」", "yos414_026.ogg", "山_山の中１c", "bgm30.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "鉾鈴耳", "face": "31"}, "CHAPTER 3-6", null, null], [336, "", "靠近蕾娜之后，宿体发出的光芒甚至开始有些刺眼了。", null, "山_山の中１c", "bgm30.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "鉾鈴耳", "face": "31"}, "CHAPTER 3-6", null, null], [337, "丛雨", "「果然」", "mur414_057.ogg", "山_山の中１c", "bgm30.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "14"}, "CHAPTER 3-6", null, null], [338, "将臣", "「哈啊……哈啊，到底是怎么回事啊，小雨？」", null, "山_山の中１c", "bgm30.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "14"}, "CHAPTER 3-6", null, null], [339, "", "我有点上气不接下气了。", null, "山_山の中１c", "bgm30.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "14"}, "CHAPTER 3-6", null, null], [340, "", "尽管常陆在身后用苦无牵制着祟神，但也只是杯水车薪。", null, "山_山の中１c", "bgm30.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "14"}, "CHAPTER 3-6", null, null], [341, "", "再这样下去，我们肯定会被追上的！", null, "山_山の中１c", "bgm30.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "14"}, "CHAPTER 3-6", null, null], [342, "丛雨", "「本座也不知为何」", "mur414_058.ogg", "山_山の中１c", "bgm30.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "36"}, "CHAPTER 3-6", null, null], [343, "丛雨", "「但随着碎片越集越多，宿体开始有了自己的意识，这是毫无疑问的」", "mur414_059.ogg", "山_山の中１c", "bgm30.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "26"}, "CHAPTER 3-6", null, null], [344, "芳乃", "「我之所以会被操控，也是因为这个吧？」", "yos414_027.ogg", "山_山の中１c", "bgm30.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "鉾鈴耳", "face": "17"}, "CHAPTER 3-6", null, null], [345, "丛雨", "「嗯。但是，你的情况似乎跟蕾娜又有所不同」", "mur414_060.ogg", "山_山の中１c", "bgm30.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "39"}, "CHAPTER 3-6", null, null], [346, "丛雨", "「本座觉得，这宿体想要得到蕾娜是出于自己的意愿」", "mur414_061.ogg", "山_山の中１c", "bgm30.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "10"}, "CHAPTER 3-6", null, null], [347, "将臣", "「想要得到蕾娜？难道说，她的身体可能会被宿体侵占吗？」", null, "山_山の中１c", "bgm30.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "10"}, "CHAPTER 3-6", null, null], [348, "蕾娜", "「哎……不能这样啦……嘻嘻，我可是……这里的服务员……哎？你是说只吃一点点吗，嘿嘿……」", "len414_047.ogg", "山_山の中１c", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "35"}, "CHAPTER 3-6", null, null], [349, "将臣", "「……不会吧？」", null, "山_山の中１c", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "35"}, "CHAPTER 3-6", null, null], [350, "", "毕竟，她现在正在梦里对着一桌子大餐垂涎三尺呢。", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 3-6", null, null], [351, "", "然而小雨的脸色变得十分难看。", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 3-6", null, null], [352, "丛雨", "「…………该不会是」", "mur414_062.ogg", "山_山の中１c", "bgm30.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "28"}, "CHAPTER 3-6", null, null], [353, "将臣", "「呼、呼……怎么了，小雨」", null, "山_山の中１c", "bgm30.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "28"}, "CHAPTER 3-6", null, null], [354, "丛雨", "「要知道，神力或诅咒之力并非万能」", "mur414_063.ogg", "山_山の中１c", "bgm30.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "14"}, "CHAPTER 3-6", null, null], [355, "丛雨", "「就算想侵占活人肉体，也必须有一个最基本的过程」", "mur414_064.ogg", "山_山の中１c", "bgm30.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "14"}, "CHAPTER 3-6", null, null], [356, "将臣", "「既然如此，在她睡着的期间……应该是没事的吧？哈啊、呼」", null, "山_山の中１c", "bgm30.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "14"}, "CHAPTER 3-6", null, null], [357, "丛雨", "「不，主人，你有没有听说过这种事」", "mur414_065.ogg", "山_山の中１c", "bgm30.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "10"}, "CHAPTER 3-6", null, null], [358, "丛雨", "「比如说，如果吃了黄泉之国的食物，就再也回不来了。或者是，碰上神隐的时候，绝对不能吃那里的食物」", "mur414_066.ogg", "山_山の中１c", "bgm30.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "36"}, "CHAPTER 3-6", null, null], [359, "将臣", "「……啊？」", null, "山_山の中１c", "bgm30.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "36"}, "CHAPTER 3-6", null, null], [360, "蕾娜", "「啊，啊——我也想吃……你们还是……给我留一点……唔」", "len414_048.ogg", "山_山の中１c", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "17"}, "CHAPTER 3-6", null, null], [361, "", "别吓我。", null, "山_山の中１c", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "17"}, "CHAPTER 3-6", null, null], [362, "将臣", "「难道做梦的时候也算吗？」", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 3-6", null, null], [363, "丛雨", "「不知道」", "mur414_067.ogg", "山_山の中１c", "bgm30.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "37"}, "CHAPTER 3-6", null, null], [364, "丛雨", "「但是，或许我们确实想得太简单了。说实话，之前完全没料到这种可能性」", "mur414_068.ogg", "山_山の中１c", "bgm30.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "35"}, "CHAPTER 3-6", null, null], [365, "芳乃", "「不、不是吧！有地，你赶快想办法把蕾娜叫醒！」", "yos414_028.ogg", "山_山の中１c", "bgm30.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "鉾鈴耳", "face": "27"}, "CHAPTER 3-6", null, null], [366, "将臣", "「我也想把她叫醒啊……」", null, "山_山の中１c", "bgm30.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "鉾鈴耳", "face": "27"}, "CHAPTER 3-6", null, null], [367, "蕾娜", "「嘻嘻嘻嘻嘻……每道菜看上去都好好吃啊，先吃哪个呢……好纠结啊……嘿嘿」", "len414_049.ogg", "山_山の中１c", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "11"}, "CHAPTER 3-6", null, null], [368, "将臣", "「哇啊啊！千万不能吃啊，蕾娜！蕾娜！！」", null, "山_山の中１c", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "11"}, "CHAPTER 3-6", null, null], [369, "茉子", "「抱歉了各位，我已经顶不住了！！」", "mak414_022.ogg", "山_山の中１c", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "11"}, "CHAPTER 3-6", null, null], [370, "", "常陆发出了惨叫一般的喊声。", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 3-6", null, null], [371, "将臣", "「不是吧……」", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 3-6", null, null], [372, "芳乃", "「祟神，占７分……山，只占３分？」", "yos414_029.ogg", "山_山の中１c", "bgm30.opus", null, "CHAPTER 3-6", null, null], [373, "", "这何止是翻倍。", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 3-6", null, null], [374, "", "现在几乎整座山上都是祟神了啊！", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 3-6", null, null], [375, "芳乃", "「这、这这这、这要怎么打啊！」", "yos414_030.ogg", "山_山の中１c", "bgm30.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "鉾鈴耳", "face": "06"}, "CHAPTER 3-6", null, null], [376, "将臣", "「对了！小雨，你再像之前那样，用闪光！闪光！」", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 3-6", null, null], [377, "丛雨", "「明白！」", "mur414_069.ogg", "山_山の中１c", "bgm30.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "14"}, "CHAPTER 3-6", null, null], [378, "", "一片白光打破了黑暗。", null, "山_山の中１c", "bgm30.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "14"}, "CHAPTER 3-6", null, null], [379, "", "我们趁机冲下坡道。不，说难听点我们就是滑下去的。", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 3-6", null, null], [380, "将臣", "「哇啊！？」", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [381, "", "我连忙用双手护着蕾娜的脑袋，两人一起摔落到了砂石地上。", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [382, "", "这时，两个软绵绵的物体压在我身上。在这情急之际，竟给了我一种我还活着的实感。", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [383, "", "而且，闻起来特别香！", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [384, "蕾娜", "「那么……现在，我来给你们示范下……筷子的……唔」", "len414_050.ogg", "山_川沿いc", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "35"}, "CHAPTER 3-6", null, null], [385, "", "她还在睡觉呢，感觉挺过意不去的！", null, "山_川沿いc", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "35"}, "CHAPTER 3-6", null, null], [386, "将臣", "「呼……哈啊……哈啊……话说回来，都摔成这姿势了都摔不醒」", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [387, "", "要是她能立刻醒过来，就算打我两巴掌我也认了。", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [388, "茉子", "「有地！你赶快起来！」", "mak414_023.ogg", "山_川沿いc", "bgm30.opus", {"char": "茉子", "file": "茉子.stand", "dress": "クナイ", "face": "22"}, "CHAPTER 3-6", null, null], [389, "丛雨", "「是啊，主人，现在必须尽量远离祟神」", "mur414_070.ogg", "山_川沿いc", "bgm30.opus", {"char": "茉子", "file": "茉子.stand", "dress": "クナイ", "face": "22"}, "CHAPTER 3-6", null, null], [390, "丛雨", "「它们数量这么多，可能山上所有的碎片都变成祟神了」", "mur414_071.ogg", "山_川沿いc", "bgm30.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "28"}, "CHAPTER 3-6", null, null], [391, "将臣", "「哈啊……哈啊……你说所有的碎片？」", null, "山_川沿いc", "bgm30.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "28"}, "CHAPTER 3-6", null, null], [392, "", "那只要我们现在打败所有追过来的祟神，就可以把碎片集齐了。", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [393, "", "蕾娜眼看着就要把料理吃进去了。", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [394, "", "没时间了。", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [395, "", "最重要的是，我已经没力气继续跑了。", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [396, "将臣", "「常陆……你还是，把丛雨丸给我吧……哈啊……哈啊」", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [397, "将臣", "「拜托你来看着蕾娜」", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [398, "茉子", "「可以，但是你想做什么？」", "mak414_024.ogg", "山_川沿いc", "bgm30.opus", {"char": "茉子", "file": "茉子.stand", "dress": "クナイ", "face": "36"}, "CHAPTER 3-6", null, null], [399, "将臣", "「开打吧，我来打头阵」", null, "山_川沿いc", "bgm30.opus", {"char": "茉子", "file": "茉子.stand", "dress": "クナイ", "face": "36"}, "CHAPTER 3-6", null, null], [400, "丛雨", "「你不要胡来啊，主人！」", "mur414_072.ogg", "山_川沿いc", "bgm30.opus", {"char": "茉子", "file": "茉子.stand", "dress": "クナイ", "face": "10"}, "CHAPTER 3-6", null, null], [401, "茉子", "「敌众我寡，你还想正面交战，太鲁莽了」", "mak414_025.ogg", "山_川沿いc", "bgm30.opus", {"char": "茉子", "file": "茉子.stand", "dress": "クナイ", "face": "13"}, "CHAPTER 3-6", null, null], [402, "芳乃", "「你可别破罐破摔啊」", "yos414_031.ogg", "山_川沿いc", "bgm30.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "鉾鈴耳", "face": "07"}, "CHAPTER 3-6", null, null], [403, "将臣", "「那要不你们在前面一边跑一边打，我在后面一边追一边打，这样如何？」", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [404, "将臣", "「这样一来，祟神的攻击对象就会分散开，说不定可以招架一会儿」", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [405, "丛雨", "「呃，这个……」", "mur414_073.ogg", "山_川沿いc", "bgm30.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "36"}, "CHAPTER 3-6", null, null], [406, "将臣", "「当然了，如果你们有更好的办法，我就听你们的」", null, "山_川沿いc", "bgm30.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "36"}, "CHAPTER 3-6", null, null], [407, "芳乃", "「可是，这样的话，你的压力是不是太……哎？」", "yos414_032.ogg", "山_川沿いc", "bgm30.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "鉾鈴耳", "face": "26"}, "CHAPTER 3-6", null, null], [408, "芳乃", "「啊啊啊啊！！！！?」", "yos414_033.ogg", "山_川沿いc", "bgm30.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "鉾鈴耳", "face": "27"}, "CHAPTER 3-6", null, null], [409, "", "祟神又追上来了吗？不过事到如今，还有什么好惊讶的。", null, "山_川沿いc", "bgm30.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "鉾鈴耳", "face": "27"}, "CHAPTER 3-6", null, null], [410, "", "你看，追上来的只有一只……哎？", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [411, "", "确实只有一只。", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [412, "", "但是，这一只比之前的祟神都要大一圈，而且外表的轮廓显得更加清晰……", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [413, "", "它并不是刚才那种黑泥——", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [414, "芳乃", "「看上去，有点像狗……」", "yos414_034.ogg", "山_川沿いc", "bgm30.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "鉾鈴耳", "face": "07"}, "CHAPTER 3-6", null, null], [415, "茉子", "「尾巴也很像祟神的触手」", "mak414_026.ogg", "山_川沿いc", "bgm30.opus", {"char": "茉子", "file": "茉子.stand", "dress": "クナイ", "face": "34"}, "CHAPTER 3-6", null, null], [416, "将臣", "「……难道它们，合体了？」", null, "山_川沿いc", "bgm30.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "鉾鈴耳", "face": "07"}, "CHAPTER 3-6", null, null], [417, "丛雨", "「看来不止碎片会合体，就连祟神也会合体变成一只啊」", "mur414_074.ogg", "山_川沿いc", "bgm30.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "26"}, "CHAPTER 3-6", null, null], [418, "茉子", "「丛雨大人，现在可不是感叹的时候！」", "mak414_027.ogg", "山_川沿いc", "bgm30.opus", {"char": "茉子", "file": "茉子.stand", "dress": "クナイ", "face": "13"}, "CHAPTER 3-6", null, null], [419, "丛雨", "「本座知道，它的力量波动十分强大！本座的闪光对它恐怕是没用的」", "mur414_075.ogg", "山_川沿いc", "bgm30.opus", {"char": "茉子", "file": "茉子.stand", "dress": "クナイ", "face": "13"}, "CHAPTER 3-6", null, null], [420, "", "现在更是只能一战了！", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [421, "", "竟然要跟这种怪物对决！说实话，要是能哭的话我真想哭出来。", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [422, "", "但我多少也有点男人的自尊。", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [423, "将臣", "「小雨，拜托了！」", null, "山_川沿いc", "bgm30.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "26"}, "CHAPTER 3-6", null, null], [424, "丛雨", "「唔，虽然不想孤注一掷，但眼下也只能相信主人的武运了」", "mur414_076.ogg", "山_川沿いc", "bgm30.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "28"}, "CHAPTER 3-6", null, null], [425, "", "丛雨丸再次发出淡淡清光。", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", "ev702a", null], [426, "芳乃", "「你们别急啊，现在应该先逃跑，然后仔细想想战术！」", "yos414_035.ogg", "山_川沿いc", "bgm30.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "鉾鈴耳", "face": "17"}, "CHAPTER 3-6", null, null], [427, "丛雨", "『不，祟神合体后只剩一只，这对我们来说是绝佳的机会』", "mur414_077.ogg", "山_川沿いc", "bgm30.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "鉾鈴耳", "face": "17"}, "CHAPTER 3-6", null, null], [428, "将臣", "「没错！而且它的目标依然是蕾娜吧？」", null, "山_川沿いc", "bgm30.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "鉾鈴耳", "face": "34"}, "CHAPTER 3-6", null, null], [429, "将臣", "「你们俩先跟它保持距离，我还是能拖一会儿时间的」", null, "山_川沿いc", "bgm30.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "鉾鈴耳", "face": "34"}, "CHAPTER 3-6", null, null], [430, "芳乃", "「真是的，你动不动就胡来」", "yos414_036.ogg", "山_川沿いc", "bgm30.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "鉾鈴耳", "face": "31"}, "CHAPTER 3-6", null, null], [431, "茉子", "「芳乃大人！现在就按他们说的做吧」", "mak414_028.ogg", "山_川沿いc", "bgm30.opus", {"char": "茉子", "file": "茉子.stand", "dress": "クナイ", "face": "41"}, "CHAPTER 3-6", null, null], [432, "芳乃", "「我知道！可是……行吧！那就这么办」", "yos414_037.ogg", "山_川沿いc", "bgm30.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "鉾鈴耳", "face": "19"}, "CHAPTER 3-6", null, null], [433, "芳乃", "「但是，跟我们会合之前你一定不能有事啊」", "yos414_038.ogg", "山_川沿いc", "bgm30.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "鉾鈴耳", "face": "33"}, "CHAPTER 3-6", null, null], [434, "将臣", "「放心吧，我还不想死呢」", null, "山_川沿いc", "bgm30.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "鉾鈴耳", "face": "33"}, "CHAPTER 3-6", null, null], [435, "", "这样一来作战方针就确定了。", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [436, "", "朝武和常陆先带着蕾娜逃跑。", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [437, "", "在她们逃出一定距离之前，我必须一个人对付这怪物。", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [438, "", "眼前的祟神正像狗一样前肢弯曲，闷声低吼。", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [439, "", "不过它的体型却比普通犬只大上好几倍……", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [440, "", "哈、哈哈……我竟然要单凭一把刀挑战这种巨型的怪物，真是想笑也笑不出来啊。", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [441, "", "突然想到了以前经常玩的《怪物狩猎人》。", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [442, "", "那个游戏的角色可以死３次，但我只要死一次就完蛋了。", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [443, "", "而且我的防具完全是新手套装，对手则是Ｇ级怪物。", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [444, "", "说到底，真要和这种怪兽打架的话，根本就不应该找我这种羸弱的学生，应该去找奥○曼或者自卫队吧。", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [445, "", "哎，算了。逃避现实也没意义。", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [446, "将臣", "「小雨，抱歉让你留下陪我」", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [447, "丛雨", "『这不算什么，毕竟本座和丛雨丸是不会消失的』", "mur414_078.ogg", "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [448, "丛雨", "『而且，你是为了战胜它才留下来的吧？』", "mur414_079.ogg", "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [449, "将臣", "「没错」", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [450, "", "我留下来是为了保护身后的女生。想到这里，心里好受了点。", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [451, "将臣", "「要上了，我们要先发制人！敌我体重差异太大，要是只顾防御，很可能会被一口气干掉」", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [452, "丛雨", "『无论是攻还是守，无非就是一场豪赌』", "mur414_080.ogg", "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [453, "丛雨", "『主人就放开手脚！上吧』", "mur414_081.ogg", "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [454, "", "然而，下一秒我就意识到了自己是多么滑稽——", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [455, "将臣", "「……哎？」", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [456, "", "见我挥刀冲上来后，祟神眨眼间就从我身旁闪了过去。", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [457, "将臣", "「那么大的身体，动作却这么快！？」", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [458, "丛雨", "『不好！他还是冲着蕾娜去的』", "mur414_082.ogg", "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [459, "", "常陆立刻推开朝武和蕾娜，上前应战。", null, "山_川沿いc", "bgm30.opus", {"char": "茉子", "file": "茉子.stand", "dress": "クナイ", "face": "41"}, "CHAPTER 3-6", null, null], [460, "", "然而，她的攻击只挡住了祟神片刻。", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [461, "", "紧接着，朝武又把蕾娜推开。", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [462, "", "厉害！她用鉾铃刺中了祟神的前爪。", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [463, "", "但是，她纤细的身躯没能扛住祟神的冲击，直接被顶开老远。", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [464, "将臣", "「这混蛋！！」", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [465, "", "我立刻追了上去。", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [466, "", "朝武和常陆都没有放下武器，似乎准备继续应战。", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [467, "", "但祟神不停挥舞着的触手让她们自顾不暇。", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [468, "", "那怪物慢慢向着蕾娜走去，朝武和常陆的攻击已经阻挡不了它。", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [469, "", "它抬起了前爪，是准备攻击还在睡梦中的蕾娜？！", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [470, "", "我奋力奔跑着。尽管呼吸十分急促，体力快要透支，我也顾不上了。", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [471, "", "腿断了也无所谓，一定要赶上啊！", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [472, "将臣", "「唔啊啊啊啊啊！！！！」", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [473, "蕾娜", "「咦？这里是哪啊？」", "len414_051.ogg", "朝武_リビングa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "31"}, "CHAPTER 3-6", null, null], [474, "", "——蕾娜突然分不清自己在哪了。", null, "朝武_リビングa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "31"}, "CHAPTER 3-6", null, null], [475, "", "她只隐隐记得……将臣走出房门，屋里只剩下她和茉子时，耳鸣突然加重了。", null, "朝武_リビングa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "31"}, "CHAPTER 3-6", null, null], [476, "", "现在，耳鸣已经停了下来。", null, "朝武_リビングa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "31"}, "CHAPTER 3-6", null, null], [477, "", "然而现在她的双耳却被可怕的寂静包裹着。", null, "朝武_リビングa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "31"}, "CHAPTER 3-6", null, null], [478, "蕾娜", "「对了，将臣哪去了……还有茉子呢？」", "len414_052.ogg", "朝武_リビングa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 3-6", null, null], [479, "蕾娜", "「大家都去哪了呀？」", "len414_053.ogg", "朝武_リビングa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "31"}, "CHAPTER 3-6", null, null], [480, "", "明明已经来过好几次了，可蕾娜心里却有种恐惧感，就好像这个地方她从没来过一样。", null, "朝武_リビングa", "bgm36.opus", null, "CHAPTER 3-6", null, null], [481, "", "最吓人的，莫过于这份寂静。", null, "朝武_リビングa", "bgm36.opus", null, "CHAPTER 3-6", null, null], [482, "", "不仅听不见虫鸣声，就连微风吹拂，树叶摩挲的声响都完全听不见。", null, "朝武_リビングa", "bgm36.opus", null, "CHAPTER 3-6", null, null], [483, "蕾娜", "「啊——！啊——！还是听得见自己的声音的」", "len414_054.ogg", "朝武_リビングa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "30"}, "CHAPTER 3-6", null, null], [484, "", "能听见自己的声音，就说明耳朵没有出问题。", null, "朝武_リビングa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "30"}, "CHAPTER 3-6", null, null], [485, "蕾娜", "「不过这种感觉好奇怪啊……咦？」", "len414_055.ogg", "朝武_リビングa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "04"}, "CHAPTER 3-6", null, null], [486, "", "蕾娜的余光瞥见一团白色的东西从身边窜了过去。", null, "朝武_リビングa", "bgm36.opus", null, "CHAPTER 3-6", null, null], [487, "", "那东西看着像生物，但是身形却隐约有些透明，实在是不可思议。", null, "朝武_リビングa", "bgm36.opus", null, "CHAPTER 3-6", null, null], [488, "蕾娜", "「难道是……山妖？」", "len414_056.ogg", "朝武_リビングa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "24"}, "CHAPTER 3-6", null, null], [489, "", "蕾娜忍不住追了过去，一路追到了山上。", null, "山_山道a", "bgm36.opus", null, "CHAPTER 3-6", null, null], [490, "蕾娜", "「对了，他们说过不能随便上山的！」", "len414_057.ogg", "山_山道a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "31"}, "CHAPTER 3-6", null, null], [491, "蕾娜", "「……也罢，反正现在是做梦」", "len414_058.ogg", "山_山道a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 3-6", null, null], [492, "", "这里是梦境。梦还没醒就意识到自己还在做梦，也是够奇妙的。", null, "山_山道a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 3-6", null, null], [493, "", "但不知为何，蕾娜丝毫没觉得不对劲，理所当然地接受了这一事实。", null, "山_山道a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 3-6", null, null], [494, "蕾娜", "「喔！」", "len414_059.ogg", "山_山道a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "05"}, "CHAPTER 3-6", null, null], [495, "", "那团白色的物体再次从眼前窜了过去。", null, "山_山道a", "bgm36.opus", null, "CHAPTER 3-6", null, null], [496, "", "这一次看得比刚才要清楚不少。那似乎是一只白色的狛犬。", null, "山_山道a", "bgm36.opus", null, "CHAPTER 3-6", null, null], [497, "蕾娜", "「我应该是第一次看见它吧？可是，也不知道为什么」", "len414_060.ogg", "山_山道a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "12"}, "CHAPTER 3-6", null, null], [498, "蕾娜", "「我有一种非常亲切的感觉」", "len414_061.ogg", "山_山道a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "27"}, "CHAPTER 3-6", null, null], [499, "", "不知不觉中，蕾娜的脚步越来越快。", null, "山_山道a", "bgm36.opus", null, "CHAPTER 3-6", null, null], [500, "", "她感觉这段路程似乎极其漫长，又像是掠地飞行般转瞬即至。", null, "山_山の中１a", "bgm36.opus", null, "CHAPTER 3-6", null, null], [501, "", "终于，她追上了那只白狛。", null, "山_山の中１a", "bgm36.opus", null, "CHAPTER 3-6", null, null], [502, "蕾娜", "「——！」", null, "山_山の中１a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "23"}, "CHAPTER 3-6", null, null], [503, "蕾娜", "「（……咦？我刚才好像叫了它的名字？）」", "len414_063.ogg", "山_山の中１a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "30"}, "CHAPTER 3-6", null, null], [504, "", "蕾娜用自己不懂的语言，叫了一个自己没听说过的名字。", null, "山_山の中１a", "bgm36.opus", null, "CHAPTER 3-6", null, null], [505, "", "所以就连蕾娜自己也不清楚到底是怎么回事。", null, "山_山の中１a", "bgm36.opus", null, "CHAPTER 3-6", null, null], [506, "", "但这毕竟是梦，会发生这种事也是难免的。", null, "山_山の中１a", "bgm36.opus", null, "CHAPTER 3-6", null, null], [507, "", "就在这时，白狛垂头丧气地出现在了蕾娜面前。", null, "山_山の中１a", "bgm36.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 3-6", null, null], [508, "蕾娜", "「——————————」", null, "山_山の中１a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "20"}, "CHAPTER 3-6", null, null], [509, "", "蕾娜又用自己不懂的语言，说了一些听不懂的话。", null, "山_山の中１a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "20"}, "CHAPTER 3-6", null, null], [510, "", "听上去似乎是在呵斥白狛。", null, "山_山の中１a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "20"}, "CHAPTER 3-6", null, null], [511, "蕾娜", "「（不过，总感觉语气好高傲啊？）」", "len414_065.ogg", "山_山の中１a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "11"}, "CHAPTER 3-6", null, null], [512, "蕾娜", "「（就像女王大人，或者贵族的大小姐一样）」", "len414_066.ogg", "山_山の中１a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "30"}, "CHAPTER 3-6", null, null], [513, "", "蕾娜心想着，就像在对待别人的事一样。", null, "山_山の中１a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "30"}, "CHAPTER 3-6", null, null], [514, "白狛", "「——」", null, "山_山の中１a", "bgm36.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 3-6", null, null], [515, "蕾娜", "「——！——————————」", null, "山_山の中１a", "bgm36.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 3-6", null, null], [516, "", "白狛似乎顶了几句嘴，两个人开始吵了起来。", null, "山_山の中１a", "bgm36.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 3-6", null, null], [517, "", "然而尽管是从自己嘴里说出去的话语，蕾娜还是搞不清楚自己到底在说什么。", null, "山_山の中１a", "bgm36.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 3-6", null, null], [518, "蕾娜", "「（到底在说些什么呢？）」", "len414_068.ogg", "山_山の中１a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "06"}, "CHAPTER 3-6", null, null], [519, "", "好想知道在吵什么。", null, "山_山の中１a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "06"}, "CHAPTER 3-6", null, null], [520, "", "蕾娜忍不住这么想。", null, "山_山の中１a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "06"}, "CHAPTER 3-6", null, null], [521, "白狛", "「可是姐姐大人，您这样说我也很为难」", "srk414_002.ogg", "山_山の中１a", "bgm36.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 3-6", null, null], [522, "蕾娜", "「姐姐大人？……我、我是它姐姐啊」", "len414_069.ogg", "山_山の中１a", "bgm36.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 3-6", null, null], [523, "白狛", "「…………」", "srk414_003.ogg", "山_山の中１a", "bgm36.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 3-6", null, null], [524, "", "白狛眼睛的颜色突然变了。", null, "山_山の中１a", "bgm36.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 3-6", null, null], [525, "", "它的瞳孔像一团涌动的诡异黑泥，和身上雪白的皮毛一点也不相称。", null, "山_山の中１a", "bgm36.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 3-6", null, null], [526, "蕾娜", "「呃、那个……我说了什么奇怪的话吗？」", "len414_070.ogg", "山_山の中１a", "bgm36.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 3-6", null, null], [527, "白狛", "「你这家伙，不是姐姐大人」", "srk414_004.ogg", "山_山の中１a", "bgm12.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 3-6", null, null], [528, "", "突然，整座山都震动了起来。", null, "山_山の中１a", "bgm12.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 3-6", null, null], [529, "蕾娜", "「这、这是怎么了？！」", "len414_071.ogg", "山_山の中１a", "bgm12.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "03"}, "CHAPTER 3-6", null, null], [530, "", "在这片本来没有声音的世界里，树木开始剧烈地摇晃。", null, "山_山の中１a", "bgm12.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "03"}, "CHAPTER 3-6", null, null], [531, "", "这诡谲的氛围，让人有种整座森林都在向自己逼近一样的错觉。", null, "山_山の中１a", "bgm12.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "03"}, "CHAPTER 3-6", null, null], [532, "蕾娜", "「这是怎么回事……啊哇！」", "len414_072.ogg", "山_山の中１a", "bgm12.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "08"}, "CHAPTER 3-6", null, null], [533, "", "这次，蕾娜又感觉自己突然被某人扛在了肩膀上。", null, "山_山の中１a", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "07"}, "CHAPTER 3-6", null, null], [534, "", "那个人正在奋力奔跑，似乎是想逃脱什么东西的追赶，但蕾娜看不见那个人是谁。", null, "山_山の中１a", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "07"}, "CHAPTER 3-6", null, null], [535, "", "她感觉自己就像被一个透明人带走了一样。", null, "山_山の中１a", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "07"}, "CHAPTER 3-6", null, null], [536, "蕾娜", "「哇啊？呀啊！？到……到底是谁啊！？」", "len414_073.ogg", "山_山の中１a", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "29"}, "CHAPTER 3-6", null, null], [537, "蕾娜", "「哎？…………有一股男人的汗味？」", "len414_074.ogg", "山_山の中１a", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "34"}, "CHAPTER 3-6", null, null], [538, "", "就在这时，刚才那只白狛从透明人身体里探出了脑袋。", null, "山_山の中１a", "bgm30.opus", {"char": "白狛", "file": "白狛.stand", "dress": "犬", "face": "03"}, "CHAPTER 3-6", null, null], [539, "", "白狛露出沾满唾液的獠牙，对准蕾娜的喉管咬了过去！", null, "山_山の中１a", "bgm30.opus", {"char": "白狛", "file": "白狛.stand", "dress": "犬", "face": "03"}, "CHAPTER 3-6", null, null], [540, "蕾娜", "「哇啊啊！？\\n等一等啊————！！？」", "len414_075.ogg", "山_山の中１a", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "21"}, "CHAPTER 3-6", null, null], [541, "蕾娜", "「死之前，我还想痛快地吃一顿不限量的莓果酱肉丸和超大份鲱鱼排……」", "len414_076.ogg", "山_山の中１a", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "22"}, "CHAPTER 3-6", null, null], [542, "蕾娜", "「咦？这里……是、是志那都庄吗？」", "len414_077.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "31"}, "CHAPTER 3-6", null, null], [543, "", "蕾娜缓缓地将蒙着眼睛的双手拿开。", null, "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "31"}, "CHAPTER 3-6", null, null], [544, "", "她好像在不知不觉中移动到了志那都庄的客房。", null, "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "31"}, "CHAPTER 3-6", null, null], [545, "蕾娜", "「对了！我得赶快干活，要不然又要被掌柜的骂了！」", "len414_078.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "31"}, "CHAPTER 3-6", null, null], [546, "祖父", "「你在说什么呢，蕾娜？」", "sof414_001.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "31"}, "CHAPTER 3-6", null, null], [547, "", "突然，一个温柔的声音在耳边响起。", null, "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "31"}, "CHAPTER 3-6", null, null], [548, "蕾娜", "「咦，是爷爷？为什么爷爷在志那都庄啊！」", "len414_079.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "20"}, "CHAPTER 3-6", null, null], [549, "爸爸", "「可不止爷爷哦，蕾娜」", "pap414_001.ogg", "旅館_客室a", "bgm36.opus", null, "CHAPTER 3-6", null, null], [550, "妈妈", "「就是呀，妈妈也请假过来了」", "mam414_001.ogg", "旅館_客室a", "bgm36.opus", null, "CHAPTER 3-6", null, null], [551, "蕾娜", "「爸爸……妈妈，你们也来了！？为什么你们都来了呢？」", "len414_080.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "06"}, "CHAPTER 3-6", null, null], [552, "爸爸", "「哈哈哈，你忘记了吗，蕾娜」", "pap414_002.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "06"}, "CHAPTER 3-6", null, null], [553, "妈妈", "「我们这次是一家人一起来旅游的呀」", "mam414_002.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "04"}, "CHAPTER 3-6", null, null], [554, "祖父", "「你天天说这家旅馆这里好那里好，说得我们特别想过来看一看」", "sof414_002.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "04"}, "CHAPTER 3-6", null, null], [555, "蕾娜", "「爷爷……？确实……我一直都觉得这里很好」", "len414_081.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 3-6", null, null], [556, "祖父", "「你很早以前就这么想了吧？」", "sof414_003.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 3-6", null, null], [557, "蕾娜", "「确实……没错！不管是日本，还是穗织，还是志那都庄，都非常棒！」", "len414_082.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02"}, "CHAPTER 3-6", null, null], [558, "蕾娜", "「我也一直都很想带你们过来玩呢」", "len414_083.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "24"}, "CHAPTER 3-6", null, null], [559, "妈妈", "「噗，谢谢你蕾娜」", "mam414_003.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02"}, "CHAPTER 3-6", null, null], [560, "爸爸", "「快吃吧，一会儿菜就凉了」", "pap414_003.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02"}, "CHAPTER 3-6", null, null], [561, "蕾娜", "「……上菜了吗？」", "len414_084.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "04"}, "CHAPTER 3-6", null, null], [562, "", "蕾娜仔细一看，发现刚才还空无一物的桌子上已经摆满了料理。", null, "旅館_客室a", "bgm36.opus", null, "CHAPTER 3-6", null, null], [563, "", "桌子上摆的，并不是蕾娜刚才心里想到的那些莓果酱肉丸和煎鲱鱼排之类的传统北欧美食——", null, "旅館_客室a", "bgm36.opus", null, "CHAPTER 3-6", null, null], [564, "", "而是寿司、炒面之类的日本料理。蕾娜在日本吃过的美食全部密密麻麻地摆在桌子上。", null, "旅館_客室a", "bgm36.opus", null, "CHAPTER 3-6", null, null], [565, "", "而且，这并不是旅馆的配餐方式。", null, "旅館_客室a", "bgm36.opus", null, "CHAPTER 3-6", null, null], [566, "", "而是蕾娜老家的自助餐形式，料理全都盛在大盘子里。", null, "旅館_客室a", "bgm36.opus", null, "CHAPTER 3-6", null, null], [567, "蕾娜", "「哇啊啊！好多好吃的！？」", "len414_085.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "18"}, "CHAPTER 3-6", null, null], [568, "蕾娜", "「不过，这些都是厨师长亲自做的吗？」", "len414_086.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "34"}, "CHAPTER 3-6", null, null], [569, "蕾娜", "「这煎鱼排……不是像日本产的鲱鱼，长得跟北海地区的波罗的海鲱鱼一模一样」", "len414_087.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "01"}, "CHAPTER 3-6", null, null], [570, "妈妈", "「那当然啦，我们把你最喜欢吃的东西都找来了」", "mam414_004.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "01"}, "CHAPTER 3-6", null, null], [571, "蕾娜", "「……我最喜欢吃的东西？你们都还记得？」", "len414_088.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "22n"}, "CHAPTER 3-6", null, null], [572, "爸爸", "「当然记得啦，蕾娜」", "pap414_004.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "22n"}, "CHAPTER 3-6", null, null], [573, "", "许久没见自己的父母，蕾娜的眼角不禁涌出一汪泪水。", null, "旅館_客室a", "bgm36.opus", null, "CHAPTER 3-6", null, null], [574, "", "爷爷看在眼里，面容慈祥地望着蕾娜。", null, "旅館_客室a", "bgm36.opus", null, "CHAPTER 3-6", null, null], [575, "", "在蕾娜的国家，积累了一定工作经验后跳槽去更好的公司是社会公认的常识。", null, "旅館_客室a", "bgm36.opus", null, "CHAPTER 3-6", null, null], [576, "", "所以像日本这样，旅馆能开１００年以上是根本无法想象的。", null, "旅館_客室a", "bgm36.opus", null, "CHAPTER 3-6", null, null], [577, "", "蕾娜的父母结婚早。他们为了寻找更好的工作，都各自离开了故乡。", null, "旅館_客室a", "bgm36.opus", null, "CHAPTER 3-6", null, null], [578, "", "因此蕾娜从小是被爷爷抚养长大的。", null, "旅館_客室a", "bgm36.opus", null, "CHAPTER 3-6", null, null], [579, "", "蕾娜的故乡有很多外出打工的人，像她这样的家庭并不罕见。", null, "旅館_客室a", "bgm36.opus", null, "CHAPTER 3-6", null, null], [580, "爸爸", "「我爱你，蕾娜」", "pap414_005.ogg", "旅館_客室a", "bgm36.opus", null, "CHAPTER 3-6", null, null], [581, "妈妈", "「我也爱你，蕾娜」", "mam414_005.ogg", "旅館_客室a", "bgm36.opus", null, "CHAPTER 3-6", null, null], [582, "蕾娜", "「嗯！我也爱你们，爸爸，妈妈！」", "len414_089.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "23"}, "CHAPTER 3-6", null, null], [583, "蕾娜", "「因为我爱着你们，所以就算很难见上一面，就算我们相隔千里，我也不觉得寂寞」", "len414_090.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "28"}, "CHAPTER 3-6", null, null], [584, "蕾娜", "「就算我一个人来到了远方的国度，我也能感受到，我们的心是连在一起的」", "len414_091.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02"}, "CHAPTER 3-6", null, null], [585, "妈妈", "「真的吗？」", "mam414_006.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02"}, "CHAPTER 3-6", null, null], [586, "蕾娜", "「……哎？」", "len414_092.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "20"}, "CHAPTER 3-6", null, null], [587, "爸爸", "「真的是这样吗？」", "pap414_006.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "20"}, "CHAPTER 3-6", null, null], [588, "祖父", "「你真的不寂寞吗，蕾娜？」", "sof414_004.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "20"}, "CHAPTER 3-6", null, null], [589, "蕾娜", "「为、为什么这么问？」", "len414_093.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "29"}, "CHAPTER 3-6", null, null], [590, "祖父", "「没什么，因为你性格太温柔，所以我们很担心，怕你习惯忍受寂寞」", "sof414_005.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "06"}, "CHAPTER 3-6", null, null], [591, "爸爸", "「家庭本来就应该是一个整体才对」", "pap414_007.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "06"}, "CHAPTER 3-6", null, null], [592, "妈妈", "「嗯，没错」", "mam414_007.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "06"}, "CHAPTER 3-6", null, null], [593, "祖父・爸爸・妈妈", "『就应该是一个整体』", "sof414_006.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "06"}, "CHAPTER 3-6", null, null], [594, "蕾娜", "「……」", "len414_094.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 3-6", null, null], [595, "", "蕾娜突然感到了一丝不安。", null, "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 3-6", null, null], [596, "", "她觉得哪里有些不太对劲。", null, "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 3-6", null, null], [597, "", "她的家人平时并不会这样。眼前的他们看上去就像假冒的一样。", null, "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 3-6", null, null], [598, "", "不过……也许是因为自己太久没见到家人，所以才会这么觉得。", null, "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 3-6", null, null], [599, "妈妈", "「来，快点吃吧。每一道菜都非常好吃哦」", "mam414_009.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 3-6", null, null], [600, "蕾娜", "「呃，嗯……也是！这可是志那都庄的厨师长拿出所有本事做的菜」", "len414_095.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "28"}, "CHAPTER 3-6", null, null], [601, "爸爸", "「来，蕾娜也快吃吧」", "pap414_009.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "28"}, "CHAPTER 3-6", null, null], [602, "蕾娜", "「可是……」", "len414_096.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "30"}, "CHAPTER 3-6", null, null], [603, "", "不知为何，刚才还那么想吃的饭菜，现在却不太愿意动筷子。", null, "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "30"}, "CHAPTER 3-6", null, null], [604, "蕾娜", "「这样还是不太好吧，我可是服务员呢，要给你们好好服务才行！」", "len414_097.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "23"}, "CHAPTER 3-6", null, null], [605, "蕾娜", "「这是我的工作嘛」", "len414_098.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "22"}, "CHAPTER 3-6", null, null], [606, "祖父", "「但是，咱们好不容易一家人欢聚一堂呢。稍微吃一点也没什么嘛」", "sof414_007.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "22"}, "CHAPTER 3-6", null, null], [607, "蕾娜", "「哎？……只吃一点吗」", "len414_099.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "30"}, "CHAPTER 3-6", null, null], [608, "妈妈", "「嗯，只吃一点」", "mam414_010.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "30"}, "CHAPTER 3-6", null, null], [609, "爸爸", "「你要是不吃的话，爸爸就要全部吃光了哦」", "pap414_010.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "30"}, "CHAPTER 3-6", null, null], [610, "蕾娜", "「等、等等！我也想吃……你们还是稍微给我留一点吧……」", "len414_100.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "17"}, "CHAPTER 3-6", null, null], [611, "爸爸", "「那就对自己诚实一点嘛」", "pap414_011.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "17"}, "CHAPTER 3-6", null, null], [612, "妈妈", "「是呀，你可是服务员，来教教我们怎么用筷子吧」", "mam414_011.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "17"}, "CHAPTER 3-6", null, null], [613, "蕾娜", "「……哎？筷子？」", "len414_101.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "20"}, "CHAPTER 3-6", null, null], [614, "", "虽然蕾娜的家人都喜欢吃日本料理，但是来了日本之后，蕾娜用筷子的本事又提升了不少。", null, "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "20"}, "CHAPTER 3-6", null, null], [615, "", "现在，她肯定是家里最熟练的。", null, "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "20"}, "CHAPTER 3-6", null, null], [616, "", "其实，蕾娜之前就很想在家人面前展示一番了。", null, "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "20"}, "CHAPTER 3-6", null, null], [617, "祖父", "「来吧，给我们看看，蕾娜。你选一份自己喜欢的吃吧」", "sof414_008.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "20"}, "CHAPTER 3-6", null, null], [618, "蕾娜", "「嘿嘿，可是……每道菜看上去都好好吃啊，要先吃哪个呢，好纠结啊」", "len414_102.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "28"}, "CHAPTER 3-6", null, null], [619, "", "就在这时，蕾娜似乎听见远处正有人拼命地呼唤她，告诉她不要吃。", null, "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "28"}, "CHAPTER 3-6", null, null], [620, "蕾娜", "「这是……是谁的声音来着？」", "len414_103.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "30"}, "CHAPTER 3-6", null, null], [621, "妈妈", "「怎么了，我想快点看你用筷子呢」", "mam414_012.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "30"}, "CHAPTER 3-6", null, null], [622, "蕾娜", "「啊，好的。那我现在就来给你们示范一下怎么用筷子……咦？」", "len414_104.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "20"}, "CHAPTER 3-6", null, null], [623, "", "突然，蕾娜闻到了一股奇怪的味道。", null, "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "20"}, "CHAPTER 3-6", null, null], [624, "", "她不由得凑近闻了一闻。", null, "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "20"}, "CHAPTER 3-6", null, null], [625, "蕾娜", "「这是，男人的汗味……还有血的味道？不过，这应该不是这道菜里发出来的味道吧」", "len414_105.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "31"}, "CHAPTER 3-6", null, null], [626, "蕾娜", "「……而且这道菜，好像闻不出任何味道」", "len414_106.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "07"}, "CHAPTER 3-6", null, null], [627, "妈妈", "「你怎么了，蕾娜」", "mam414_013.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "07"}, "CHAPTER 3-6", null, null], [628, "蕾娜", "「没什么……对、对了！我刚才好像看见山妖了」", "len414_107.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "07"}, "CHAPTER 3-6", null, null], [629, "祖父", "「山妖？看见了就看见了嘛，有什么大惊小怪的！」", "sof414_009.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "07"}, "CHAPTER 3-6", null, null], [630, "蕾娜", "「可，可是！在那之后，我突然就回到了志那都庄……咦？来这里之前……呃，我好像是在芳乃家里」", "len414_108.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "31"}, "CHAPTER 3-6", null, null], [631, "蕾娜", "「我在跟将臣说话……对了，这是将臣的气味」", "len414_109.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "05"}, "CHAPTER 3-6", null, null], [632, "蕾娜", "「将臣？将臣你在这附近吗！？」", "len414_110.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "29"}, "CHAPTER 3-6", null, null], [633, "爸爸", "「你闹够了没有，蕾娜！」", "pap414_012.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "29"}, "CHAPTER 3-6", null, null], [634, "蕾娜", "「可、可是，你们，你们都好奇怪啊！」", "len414_111.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "06"}, "CHAPTER 3-6", null, null], [635, "蕾娜", "「……哎？」", "len414_112.ogg", "旅館_客室a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "04"}, "CHAPTER 3-6", null, null], [636, "", "不知不觉，蕾娜的父母和爷爷都变成了漆黑的泥团。", null, "旅館_客室a", "bgm29.opus", null, "CHAPTER 3-6", null, null], [637, "蕾娜", "「祟、祟神！？爷爷去哪了？爸爸和妈妈都去哪了？」", "len414_113.ogg", "旅館_客室a", "bgm29.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "31"}, "CHAPTER 3-6", null, null], [638, "祖父", "「蕾————娜————！！？」", "sof414_010.ogg", "旅館_客室a", "bgm29.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "31"}, "CHAPTER 3-6", null, null], [639, "蕾娜", "「哇啊啊啊！？你、你果然不是爷爷」", "len414_114.ogg", "旅館_客室a", "bgm29.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "22"}, "CHAPTER 3-6", null, null], [640, "", "三只祟神在狭窄的室内挥舞着皮鞭一样的触手。", null, "旅館_客室a", "bgm29.opus", null, "CHAPTER 3-6", null, null], [641, "", "蕾娜吓得坐在了地上。", null, "旅館_客室a", "bgm29.opus", null, "CHAPTER 3-6", null, null], [642, "", "除此之外她根本不知道该如何躲避。就算坐下来当然也只能躲过一时。", null, "旅館_客室a", "bgm29.opus", null, "CHAPTER 3-6", null, null], [643, "蕾娜", "「救……救命啊！谁来救救我啊！！！？」", "len414_115.ogg", "旅館_客室a", "bgm29.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "20"}, "CHAPTER 3-6", null, null], [644, "", "她不由地把交叉的双臂挡在脸上。", null, "旅館_客室a", "bgm29.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "20"}, "CHAPTER 3-6", null, null], [645, "", "随后——所有的触手都被弹飞了。", null, "旅館_客室a", "bgm30.opus", null, "CHAPTER 3-6", null, null], [646, "蕾娜", "「哎……这、这是？」", "len414_116.ogg", "旅館_客室a", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "14"}, "CHAPTER 3-6", null, null], [647, "", "只见一把刀在空中挥舞。", null, "旅館_客室a", "bgm30.opus", null, "CHAPTER 3-6", null, null], [648, "", "一个男生紧紧地握着刀柄。", null, "旅館_客室a", "bgm30.opus", null, "CHAPTER 3-6", null, null], [649, "", "然而他的胳膊正冒着黑烟，就像是被瘴气灼伤了一样，皮肤上冒出越来越多类似烧伤的痕迹。", null, "旅館_客室a", "bgm30.opus", null, "CHAPTER 3-6", null, null], [650, "蕾娜", "「将、将臣！？」", "len414_117.ogg", "旅館_客室a", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "03"}, "CHAPTER 3-6", null, null], [651, "将臣", "「别碰她！你这畜生！！」", null, "旅館_客室a", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "03"}, "CHAPTER 3-6", null, null], [652, "", "——赶上了！？", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [653, "", "就在千钧一发之际，我滑到怪物跟前，护住了蕾娜。", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [654, "", "我举起丛雨丸，狠狠地刺向了正准备一脚踩下的前爪。", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [655, "祟神", "「唔啊啊啊啊啊啊！？」", "srk414_005.ogg", "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [656, "", "伤口处喷出了大量黑泥一般的污秽，就像流血一样。", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [657, "", "当然，我这边也相当不好受。", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [658, "将臣", "「唔……啊……！？要、要被压扁了、要死了……可、可恶」", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [659, "丛雨", "『你这也太乱来了，主人！』", "mur414_083.ogg", "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [660, "丛雨", "『要是没有丛雨丸的神力，你已经被踩扁了』", "mur414_084.ogg", "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [661, "", "但是如果我再不出手，就没有机会了。", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [662, "", "我顶着祟神的蛮力，使劲将丛雨丸连着胳膊一起捅进了它的体内。", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [663, "将臣", "「唔啊啊啊啊啊啊啊！！！！」", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [664, "祟神", "「嗷嗷嗷嗷嗷嗷嗷」", "srk414_006.ogg", "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [665, "", "突然，伤口处喷出了比刚才更多的污秽。", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [666, "", "大量的污秽几乎快要淹没我，我感觉都快要喘不过气了。", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [667, "", "就连丛雨丸的净化，都及不上喷涌而出的污秽。", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [668, "", "『我好恨……好恨……好恨，好恨，好恨，好恨，好恨……』", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [669, "", "『我决不饶你……决不饶你……决不饶你……』", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [670, "", "可恶，这到底是什么？一股势不可当的怒火和憎恶正凶猛地侵蚀着我的身体。", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [671, "", "我的内心几乎都快要被这些负面感情填满了。", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [672, "", "与此同时，我的皮肤上冒起了奇怪的黑烟，如同千针齐下一般的刺痛随之袭来。", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [673, "", "瘴气似乎腐蚀了我的手臂。", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [674, "丛雨", "『振作点啊，主人！还差一点了』", "mur414_085.ogg", "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [675, "蕾娜", "「……」", "len414_118.ogg", "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [676, "", "我听见了小雨的声音，还听见了一丝蕾娜的呼吸声。", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [677, "", "我不能在这里倒下！", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [678, "", "现在我无非就是想在女孩子面前好好表现表现，想争一些不值一提的面子而已。", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [679, "", "但对于男人来说，这样的理由足以让他们挺身而出。", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [680, "将臣", "「离她远点！你这个畜生！！」", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [681, "蕾娜", "「将……将臣？将臣！？」", "len414_119.ogg", "山_川沿いc", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "06"}, "CHAPTER 3-6", null, null], [682, "", "……哎？蕾娜醒了吗？", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [683, "", "而且，她不仅仅醒了。", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [684, "", "她立刻跳了起来，跑到我身边，跟我一起握住了丛雨丸。", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [685, "蕾娜", "「好疼啊啊啊啊啊！？这、这是什么，好疼啊」", "len414_120.ogg", "山_川沿いc", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "22"}, "CHAPTER 3-6", null, null], [686, "将臣", "「蕾……蕾娜，你不要握上来！」", null, "山_川沿いc", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "22"}, "CHAPTER 3-6", null, null], [687, "蕾娜", "「我、我没事的！刚才是你救了我吧？」", "len414_121.ogg", "山_川沿いc", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "28"}, "CHAPTER 3-6", null, null], [688, "蕾娜", "「那现在，轮到我来帮你了」", "len414_122.ogg", "山_川沿いc", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "19"}, "CHAPTER 3-6", null, null], [689, "蕾娜", "「虽然我不太清楚状况，但只要打败这个大家伙就行了吧」", "len414_123.ogg", "山_川沿いc", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "09"}, "CHAPTER 3-6", null, null], [690, "", "蕾娜不可能用得了丛雨丸。", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [691, "", "但她依然陪着我忍住疼痛，将自己的手用力叠在了我的手上。", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [692, "将臣", "「……蕾娜？」", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [693, "丛雨", "『主人！现在只能这样捅进去了』", "mur414_086.ogg", "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [694, "将臣", "「唔，我知道！我才不会输」", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [695, "蕾娜", "「呀啊啊啊啊啊啊啊————！！！」\\n「喔喔喔喔喔喔喔喔喔喔～～～！！！」", "len414_124.ogg", "山_川沿いc", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "16"}, "CHAPTER 3-6", null, null], [696, "", "我把丛雨丸捅得更深了。", null, "山_川沿いc", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "16"}, "CHAPTER 3-6", null, null], [697, "", "与此同时，朝武和常陆似乎正在攻击其他部位。", null, "山_川沿いc", "bgm30.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "鉾鈴耳", "face": "21"}, "CHAPTER 3-6", null, null], [698, "", "祟神的反击变得有些力不从心了。", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [699, "", "快点……快点，还没净化好吗！？", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [700, "", "就这样，不知过了多久。", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [701, "祟神", "「呜嗷嗷嗷嗷嗷……」", "srk414_007.ogg", "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [702, "", "祟神发出了最后一声惨叫，身形终于开始崩塌。", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [703, "将臣", "「成、成功了？……等等，哎？」", null, "山_川沿いc", "bgm30.opus", null, "CHAPTER 3-6", null, null], [704, "", "那巨大的身躯竟向我倒了过来。", null, "山_川沿いc", "bgm13.opus", null, "CHAPTER 3-6", null, null], [705, "", "仔细想想，这也是理所当然的。", null, "山_川沿いc", "bgm13.opus", null, "CHAPTER 3-6", null, null], [706, "", "大概就跟临死前的最后挣扎差不多。", null, "山_川沿いc", "bgm13.opus", null, "CHAPTER 3-6", null, null], [707, "", "不过，这下可糟了……我已经没力气逃跑……", null, "山_川沿いc", "bgm13.opus", null, "CHAPTER 3-6", null, null], [708, "蕾娜", "「将臣！！」", "len414_125.ogg", "山_川沿いc", "bgm13.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "16"}, "CHAPTER 3-6", null, null], [709, "", "什么？蕾娜竟然压在了我身上。", null, "山_川沿いc", "bgm13.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "16"}, "CHAPTER 3-6", null, null], [710, "", "我必须把她推开，不能让她受伤……然而，现在的我……已经没有那么多力气了。", null, "山_川沿いc", "bgm13.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "16"}, "CHAPTER 3-6", null, null], [711, "芳乃", "「有地！蕾娜？！不是吧，你们快回答我」", "yos414_039.ogg", "山_川沿いc", "bgm13.opus", null, "CHAPTER 3-6", null, null], [712, "芳乃", "「有地！！蕾娜！！？」", "yos414_040.ogg", "山_川沿いc", "bgm13.opus", null, "CHAPTER 3-6", null, null], [713, "将臣", "「…………」", null, "山_川沿いc", "bgm13.opus", null, "CHAPTER 3-6", null, null], [714, "蕾娜", "「…………」", "len414_126.ogg", "山_川沿いc", "bgm13.opus", null, "CHAPTER 3-6", null, null], [715, "将臣", "「哇啊啊啊啊！？蕾娜快逃……咦？」", null, "朝武_自室a", "bgm13.opus", null, "CHAPTER 4-1", null, null], [716, "", "本想伸手把蕾娜推开，却什么也没碰到。", null, "朝武_自室a", "bgm13.opus", null, "CHAPTER 4-1", null, null], [717, "", "而且眼前的夜空竟然变成了天花板？", null, "朝武_自室a", "bgm13.opus", null, "CHAPTER 4-1", null, null], [718, "蕾娜", "「啊，你终于醒了，将臣！」", "len415_001.ogg", "朝武_自室a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "25"}, "CHAPTER 4-1", null, null], [719, "将臣", "「哎？蕾娜！？」", null, "朝武_自室a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "25"}, "CHAPTER 4-1", null, null], [720, "蕾娜", "「不过，你还是多睡一会儿比较好」", "len415_002.ogg", "朝武_自室a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "29"}, "CHAPTER 4-1", null, null], [721, "", "蕾娜把我按回了被窝里。", null, "朝武_自室a", "bgm40.opus", null, "CHAPTER 4-1", null, null], [722, "", "她拿起掉在枕头边上的湿毛巾，用洗脸池里的水把毛巾浸湿后拧干。", null, "朝武_自室a", "bgm40.opus", null, "CHAPTER 4-1", null, null], [723, "将臣", "「是不是我昨晚昏迷了，然后被大家抬回来了？」", null, "朝武_自室a", "bgm40.opus", null, "CHAPTER 4-1", null, null], [724, "将臣", "「对了！你没受伤吧？朝武和常陆没事吧？」", null, "朝武_自室a", "bgm40.opus", null, "CHAPTER 4-1", null, null], [725, "蕾娜", "「你冷静一下，不用担心，来敷上这个」", "len415_003.ogg", "朝武_自室a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "27"}, "CHAPTER 4-1", null, null], [726, "", "她把湿毛巾敷到我额头上。", null, "朝武_自室a", "bgm40.opus", null, "CHAPTER 4-1", null, null], [727, "将臣", "「好凉」", null, "朝武_自室a", "bgm40.opus", null, "CHAPTER 4-1", null, null], [728, "蕾娜", "「啊！是不是毛巾太凉了？」", "len415_004.ogg", "朝武_自室a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "06"}, "CHAPTER 4-1", null, null], [729, "将臣", "「没事，凉凉的很舒服」", null, "朝武_自室a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "06"}, "CHAPTER 4-1", null, null], [730, "蕾娜", "「那就好」", "len415_005.ogg", "朝武_自室a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "19"}, "CHAPTER 4-1", null, null], [731, "", "敷完毛巾，她温柔地摸了摸我的头。", null, "朝武_自室a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "27"}, "CHAPTER 4-1", null, null], [732, "蕾娜", "「啊哇哇！我这样是不是有点不太自重？」", "len415_006.ogg", "朝武_自室a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "30"}, "CHAPTER 4-1", null, null], [733, "将臣", "「呃，没有，虽然有些意外……不过还挺舒服的」", null, "朝武_自室a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "30"}, "CHAPTER 4-1", null, null], [734, "蕾娜", "「……真的吗？那我再摸摸」", "len415_007.ogg", "朝武_自室a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "27"}, "CHAPTER 4-1", null, null], [735, "", "蕾娜手指的感触从头上传来。", null, "朝武_自室a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "27"}, "CHAPTER 4-1", null, null], [736, "", "我并不讨厌她这样摸着我的头，只是隐约有些痒痒的感觉。", null, "朝武_自室a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "27"}, "CHAPTER 4-1", null, null], [737, "蕾娜", "「谢谢你，将臣……你能来救我，我心里特别特别开心」", "len415_008.ogg", "朝武_自室a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "24"}, "CHAPTER 4-1", null, null], [738, "将臣", "「哪里，是你救了我吧？」", null, "朝武_自室a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "02"}, "CHAPTER 4-1", null, null], [739, "将臣", "「而且现在还在照顾我」", null, "朝武_自室a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "04"}, "CHAPTER 4-1", null, null], [740, "蕾娜", "「你是为了救我才昏过去的，我当然应该帮你啦」", "len415_009.ogg", "朝武_自室a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "27"}, "CHAPTER 4-1", null, null], [741, "蕾娜", "「现在来照顾你，也只是因为我先醒了而已，这是我应该做的」", "len415_010.ogg", "朝武_自室a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "19"}, "CHAPTER 4-1", null, null], [742, "将臣", "「哎？你也昏迷过去了吗？」", null, "朝武_自室a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "19"}, "CHAPTER 4-1", null, null], [743, "蕾娜", "「呃、啊！是昏过去了一会儿，但我没有受外伤，这个你放心」", "len415_011.ogg", "朝武_自室a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "25"}, "CHAPTER 4-1", null, null], [744, "", "没受外伤？", null, "朝武_自室a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "25"}, "CHAPTER 4-1", null, null], [745, "蕾娜", "「反正，你昨晚救了我那么多次，我帮点小忙不算什么啦」", "len415_012.ogg", "朝武_自室a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "27"}, "CHAPTER 4-1", null, null], [746, "蕾娜", "「我还隐约记得，你昨晚扛着我逃走……而且你是为了保护我，才被祟神踩在脚底的吧？」", "len415_013.ogg", "朝武_自室a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "07"}, "CHAPTER 4-1", null, null], [747, "将臣", "「这没什么大不了的，当时的情况容不得我有别的选择」", null, "朝武_自室a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "07"}, "CHAPTER 4-1", null, null], [748, "", "而且打败祟神之后，蕾娜挡在我身上，也被祟神压在了身下。", null, "朝武_自室a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "30"}, "CHAPTER 4-1", null, null], [749, "", "而我们竟然相安无事，真是侥幸。", null, "朝武_自室a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "30"}, "CHAPTER 4-1", null, null], [750, "蕾娜", "「我能从梦里醒来……也是多亏了你身上的味道」", "len415_014.ogg", "朝武_自室a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "02"}, "CHAPTER 4-1", null, null], [751, "将臣", "「……我身上的味道？不会是我的体臭吧？」", null, "朝武_自室a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "02"}, "CHAPTER 4-1", null, null], [752, "蕾娜", "「不是的！是种男生身上的味道，因为当时在场的只有你一个男生……」", "len415_015.ogg", "朝武_自室a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "25"}, "CHAPTER 4-1", null, null], [753, "蕾娜", "「所以当时我就想，那肯定是你」", "len415_016.ogg", "朝武_自室a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "23"}, "CHAPTER 4-1", null, null], [754, "", "男生身上的味道，是种什么味道啊？", null, "朝武_自室a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "23"}, "CHAPTER 4-1", null, null], [755, "", "不过背着蕾娜的时候，我也觉得她身上很香……不行不行，我在想什么呢。", null, "朝武_自室a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "23"}, "CHAPTER 4-1", null, null], [756, "", "我慌忙移开了视线。", null, "朝武_自室a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "23"}, "CHAPTER 4-1", null, null], [757, "", "不知为什么，蕾娜也扭扭捏捏地望着别处。", null, "朝武_自室a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "05"}, "CHAPTER 4-1", null, null], [758, "将臣", "「呃，后来呢？我昏迷之后都发生了什么？」", null, "朝武_自室a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "05"}, "CHAPTER 4-1", null, null], [759, "蕾娜", "「是这样的，在那之后……」", "len415_017.ogg", "朝武_自室a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "23"}, "CHAPTER 4-1", null, null], [760, "丛雨", "「嗯，你们说了这么久了，可以让本座插句话吗？」", "mur415_001.ogg", "朝武_自室a", "bgm40.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "01"}, "CHAPTER 4-1", null, null], [761, "蕾娜", "「呀！？小、小雨，你一直在听我们讲话吗？」", "len415_018.ogg", "朝武_自室a", "bgm40.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "01"}, "CHAPTER 4-1", null, null], [762, "将臣", "「你在的话就早点吱声啊」", null, "朝武_自室a", "bgm40.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "01"}, "CHAPTER 4-1", null, null], [763, "丛雨", "「本座也是刚回来，再者……本座觉得打扰你们可能不太好」", "mur415_002.ogg", "朝武_自室a", "bgm40.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "15"}, "CHAPTER 4-1", null, null], [764, "将臣", "「打扰我们？」", null, "朝武_自室a", "bgm40.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "15"}, "CHAPTER 4-1", null, null], [765, "蕾娜", "「小、小小小雨！回、回到正题吧，你不是要来帮我说明昨晚后续的事情吗？」", "len415_019.ogg", "朝武_自室a", "bgm40.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "15"}, "CHAPTER 4-1", null, null], [766, "", "蕾娜脸颊涨得通红，神色有些慌张。", null, "朝武_自室a", "bgm40.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "15"}, "CHAPTER 4-1", null, null], [767, "丛雨", "「本座当然是来说明情况的」", "mur415_003.ogg", "朝武_自室a", "bgm40.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "01"}, "CHAPTER 4-1", null, null], [768, "丛雨", "「首先，那个体型巨大的合体祟神，应该是已经被消灭了……大概」", "mur415_004.ogg", "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "35"}, "CHAPTER 4-1", null, null], [769, "将臣", "「……大概？」", null, "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "35"}, "CHAPTER 4-1", null, null], [770, "丛雨", "「就在它快要倒在蕾娜和主人身上的时候，被吸收掉了」", "mur415_005.ogg", "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "26"}, "CHAPTER 4-1", null, null], [771, "蕾娜", "「是的，好像是这样」", "len415_020.ogg", "朝武_自室a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "12"}, "CHAPTER 4-1", null, null], [772, "", "蕾娜一边说着，一边按着自己的腹部。", null, "朝武_自室a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "12"}, "CHAPTER 4-1", null, null], [773, "将臣", "「呃，这是怎么回事？你的意思难道是，祟神被蕾娜吸收了……？」", null, "朝武_自室a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "12"}, "CHAPTER 4-1", null, null], [774, "丛雨", "「不是的，在那个合体祟神的体内，碎片好像已经融合成一块了」", "mur415_006.ogg", "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "28"}, "CHAPTER 4-1", null, null], [775, "丛雨", "「被蕾娜吸收进去的就是那块大的碎片」", "mur415_007.ogg", "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "11"}, "CHAPTER 4-1", null, null], [776, "蕾娜", "「说起来真不好意思……芳乃她们拿着的那块宿体也被我吸收到体内了」", "len415_021.ogg", "朝武_自室a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "29"}, "CHAPTER 4-1", null, null], [777, "将臣", "「什么！？就是说，我们收集起来的那些碎片也都被吸收了？」", null, "朝武_自室a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "29"}, "CHAPTER 4-1", null, null], [778, "丛雨", "「嗯，确实是本座一时疏忽，比起我们收集的那块碎片，合体祟神体内的那块碎片要更大」", "mur415_008.ogg", "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "11"}, "CHAPTER 4-1", null, null], [779, "丛雨", "「芳乃她们架起昏倒的蕾娜时，我们收集的宿体好像反而被那块大的碎片吸收掉了」", "mur415_009.ogg", "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "30"}, "CHAPTER 4-1", null, null], [780, "将臣", "「可是，等、等一下。那些碎片，都是石头吧？」", null, "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "30"}, "CHAPTER 4-1", null, null], [781, "将臣", "「人体真的能吸收石头吗？」", null, "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "17"}, "CHAPTER 4-1", null, null], [782, "", "虽然这里的事情不能用常识来思考，但碎片能被人体吸收也太出乎我的意料了。", null, "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "17"}, "CHAPTER 4-1", null, null], [783, "丛雨", "「人体吸收碎片的情况，本座认为已经有过实例证明了」", "mur415_010.ogg", "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "11"}, "CHAPTER 4-1", null, null], [784, "将臣", "「有过实例了……真的吗？」", null, "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "11"}, "CHAPTER 4-1", null, null], [785, "将臣", "「可是，这东西不会对身体有影响吗？蕾娜有没有哪里不舒服？」", null, "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "11"}, "CHAPTER 4-1", null, null], [786, "丛雨", "「就现在的情况来说，还很难下定论」", "mur415_011.ogg", "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "13"}, "CHAPTER 4-1", null, null], [787, "丛雨", "「不过对身体健康应该不会有影响的，大概」", "mur415_012.ogg", "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "32"}, "CHAPTER 4-1", null, null], [788, "将臣", "「你说得也太含糊了吧」", null, "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "32"}, "CHAPTER 4-1", null, null], [789, "蕾娜", "「将臣，我没觉得不舒服，而且我现在比之前更有精神了」", "len415_022.ogg", "朝武_自室a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "02"}, "CHAPTER 4-1", null, null], [790, "将臣", "「嗯……好吧，这个也只能靠你自己感觉了」", null, "朝武_自室a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "02"}, "CHAPTER 4-1", null, null], [791, "丛雨", "「对了主人，若要说起对身体健康的影响」", "mur415_013.ogg", "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "36"}, "CHAPTER 4-1", null, null], [792, "丛雨", "「当时有大量的瘴气喷在你身体上，这才对健康有害」", "mur415_014.ogg", "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "26"}, "CHAPTER 4-1", null, null], [793, "将臣", "「啊，真的吗？」", null, "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "26"}, "CHAPTER 4-1", null, null], [794, "丛雨", "「可能差点就酿成大祸了」", "mur415_015.ogg", "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "37"}, "CHAPTER 4-1", null, null], [795, "将臣", "「啊？」", null, "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "37"}, "CHAPTER 4-1", null, null], [796, "丛雨", "「祟神倒下时，蕾娜和你一起接下了祟神散发的瘴气，你忘了吗？」", "mur415_016.ogg", "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "10"}, "CHAPTER 4-1", null, null], [797, "丛雨", "「要不是有蕾娜在，主人的身体以后很可能会出问题」", "mur415_017.ogg", "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "28"}, "CHAPTER 4-1", null, null], [798, "将臣", "「这么说，我没什么大碍也是多亏了蕾娜……啊！」", null, "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "28"}, "CHAPTER 4-1", null, null], [799, "将臣", "「蕾娜，你身体真的没事吗！？没有勉强自己吧？」", null, "朝武_自室a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "20"}, "CHAPTER 4-1", null, null], [800, "蕾娜", "「没事，我感觉现在比之前更有精神，没觉得有哪里不舒服」", "len415_023.ogg", "朝武_自室a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "27"}, "CHAPTER 4-1", null, null], [801, "", "虽然现在没什么大碍，但就怕以后她的身体会不会出什么问题。", null, "朝武_自室a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "27"}, "CHAPTER 4-1", null, null], [802, "将臣", "「能不能想个办法，把宿体从蕾娜体内取出来？」", null, "朝武_自室a", "bgm39.opus", null, "CHAPTER 4-1", null, null], [803, "美津叶", "「很遗憾，现在就取出来恐怕不太合适」", "miz415_001.ogg", "朝武_自室a", "bgm39.opus", null, "CHAPTER 4-1", null, null], [804, "将臣", "「驹川大夫！您来了啊」", null, "朝武_自室a", "bgm39.opus", null, "CHAPTER 4-1", null, null], [805, "", "驹川大夫正站在门拉开一半的卧室门口，也不知是什么时候来的。", null, "朝武_自室a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "05"}, "CHAPTER 4-1", null, null], [806, "美津叶", "「你以为是谁给你处理的伤口？听说你醒了，我才来看看你的情况」", "miz415_002.ogg", "朝武_自室a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "21"}, "CHAPTER 4-1", null, null], [807, "蕾娜", "「大夫，芳乃和茉子没事吧？」", "len415_024.ogg", "朝武_自室a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "29"}, "CHAPTER 4-1", null, null], [808, "将臣", "「啊？她们俩都受伤了么？」", null, "朝武_自室a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "29"}, "CHAPTER 4-1", null, null], [809, "美津叶", "「你们昨晚的战斗想必十分激烈，难免会有些擦伤」", "miz415_003.ogg", "朝武_自室a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "23"}, "CHAPTER 4-1", null, null], [810, "美津叶", "「不过伤势最重的是你，你还是尽可能多担心一下自己吧」", "miz415_004.ogg", "朝武_自室a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "16"}, "CHAPTER 4-1", null, null], [811, "丛雨", "「本座也这么觉得。大夫让她们静养，只是以防万一而已」", "mur415_018.ogg", "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "11"}, "CHAPTER 4-1", null, null], [812, "丛雨", "「人体受到剧烈冲击后，就算当时觉得没事，也有可能过一阵子才开始疼痛」", "mur415_019.ogg", "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "39"}, "CHAPTER 4-1", null, null], [813, "", "大概就像有些人遭遇了交通事故后，过了几天才出现颈椎挫伤的症状？", null, "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "39"}, "CHAPTER 4-1", null, null], [814, "", "确实，昨晚的战斗，跟连续遭遇交通事故差不多。", null, "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "39"}, "CHAPTER 4-1", null, null], [815, "将臣", "「情况我都大概了解了，可是现在为什么不能帮蕾娜取出宿体呢？」", null, "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "39"}, "CHAPTER 4-1", null, null], [816, "蕾娜", "「将臣，是这样的。你背着我逃走的时候，我其实一直在做梦」", "len415_025.ogg", "朝武_自室a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "25"}, "CHAPTER 4-1", null, null], [817, "将臣", "「确实，我记得你是梦见了一大桌美味佳肴来着？」", null, "朝武_自室a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "25"}, "CHAPTER 4-1", null, null], [818, "蕾娜", "「啊哈哈，说起来真不好意思」", "len415_026.ogg", "朝武_自室a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "35"}, "CHAPTER 4-1", null, null], [819, "蕾娜", "「不过，梦里的情形我都跟大家说过了――」", "len415_027.ogg", "朝武_自室a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "08"}, "CHAPTER 4-1", null, null], [820, "", "之后，蕾娜详细地描述了她的梦境。", null, "朝武_自室a", "bgm39.opus", null, "CHAPTER 4-1", null, null], [821, "将臣", "「……也就是说，你在梦里追着山妖，也就是那条白色的狗，一直追到山里去了？」", null, "朝武_自室a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "08"}, "CHAPTER 4-1", null, null], [822, "蕾娜", "「是的，可它知道我不是它姐姐之后，就突然开始发怒」", "len415_028.ogg", "朝武_自室a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "07"}, "CHAPTER 4-1", null, null], [823, "蕾娜", "「然后，我就感觉自己好像被谁扛在肩上……那应该就是你吧？」", "len415_029.ogg", "朝武_自室a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "25"}, "CHAPTER 4-1", null, null], [824, "蕾娜", "「紧接着，就突然变成了一桌子山珍海味的梦」", "len415_030.ogg", "朝武_自室a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "25"}, "CHAPTER 4-1", null, null], [825, "", "在哪里，跟谁在一起，餐桌上都摆着什么呢？虽然这些问题并不那么重要。", null, "朝武_自室a", "bgm39.opus", null, "CHAPTER 4-1", null, null], [826, "", "蕾娜似乎也并不打算详细描述这些。", null, "朝武_自室a", "bgm39.opus", null, "CHAPTER 4-1", null, null], [827, "美津叶", "「那只白色的狗，很有可能是被当做祭品的狗」", "miz415_005.ogg", "朝武_自室a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "14"}, "CHAPTER 4-1", null, null], [828, "丛雨", "「它就是祟神的本来面目」", "mur415_020.ogg", "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "11"}, "CHAPTER 4-1", null, null], [829, "美津叶", "「可它却称列支敦瑙尔小姐为姐姐，这点还真是不明所以」", "miz415_006.ogg", "朝武_自室a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "33"}, "CHAPTER 4-1", null, null], [830, "蕾娜", "「嗯，而且我的弟弟也不可能是狗。还是说，当时我也是狗？」", "len415_031.ogg", "朝武_自室a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "11"}, "CHAPTER 4-1", null, null], [831, "蕾娜", "「虽然都是梦里的事」", "len415_032.ogg", "朝武_自室a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "29"}, "CHAPTER 4-1", null, null], [832, "将臣", "「也可能，这单纯就是一场梦而已」", null, "朝武_自室a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "29"}, "CHAPTER 4-1", null, null], [833, "美津叶", "「嗯，我也觉得不能把思维都局限在这上面」", "miz415_007.ogg", "朝武_自室a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "05"}, "CHAPTER 4-1", null, null], [834, "美津叶", "「但通过这次的事件我们可以确认，祟神对列支敦瑙尔小姐有着非同寻常的执念」", "miz415_008.ogg", "朝武_自室a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "14"}, "CHAPTER 4-1", null, null], [835, "", "确实，祟神的行动和以往有着明显的不同。", null, "朝武_自室a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "14"}, "CHAPTER 4-1", null, null], [836, "美津叶", "「至少我们要先查明原因，然后再取出宿体」", "miz415_009.ogg", "朝武_自室a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "25"}, "CHAPTER 4-1", null, null], [837, "美津叶", "「否则，昨晚跟你们交手过的合体祟神还有可能再一次现身」", "miz415_010.ogg", "朝武_自室a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "30"}, "CHAPTER 4-1", null, null], [838, "美津叶", "「现在聚集的碎片比之前更多了，祟神的力量肯定也会更强」", "miz415_011.ogg", "朝武_自室a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "14"}, "CHAPTER 4-1", null, null], [839, "将臣", "「比昨晚那只更强啊……」", null, "朝武_自室a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "14"}, "CHAPTER 4-1", null, null], [840, "", "说实话，我根本想象不出那是什么怪物。", null, "朝武_自室a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "14"}, "CHAPTER 4-1", null, null], [841, "美津叶", "「万幸的是，丛雨大人知道怎么把宿体从人体中分离出来」", "miz415_012.ogg", "朝武_自室a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "17"}, "CHAPTER 4-1", null, null], [842, "美津叶", "「所以我们才决定，先观察一段时间比较好」", "miz415_013.ogg", "朝武_自室a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "05"}, "CHAPTER 4-1", null, null], [843, "丛雨", "「不过，宿体是心甘情愿被蕾娜吸收的」", "mur415_021.ogg", "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "16"}, "CHAPTER 4-1", null, null], [844, "丛雨", "「哪怕把它分离出来，也难保它不会立刻回到蕾娜体内」", "mur415_022.ogg", "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "26"}, "CHAPTER 4-1", null, null], [845, "丛雨", "「无论如何，我们要做的依旧是查清这些事情的原因」", "mur415_023.ogg", "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "36"}, "CHAPTER 4-1", null, null], [846, "将臣", "「那意思就是说……这段时间蕾娜只能保持现状了吗？」", null, "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "36"}, "CHAPTER 4-1", null, null], [847, "蕾娜", "「将臣，你再怎么担心，不清楚的事还是不清楚」", "len415_033.ogg", "朝武_自室a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "23"}, "CHAPTER 4-1", null, null], [848, "将臣", "「哎，这可是你自己的事情，你要想清楚啊」", null, "朝武_自室a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "23"}, "CHAPTER 4-1", null, null], [849, "将臣", "「我不是刻意危言耸听，祟神的诅咒是很恐怖的」", null, "朝武_自室a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "20"}, "CHAPTER 4-1", null, null], [850, "将臣", "「我真的担心得不行，万一你要是出了什么事……哎，蕾娜？」", null, "朝武_自室a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "20"}, "CHAPTER 4-1", null, null], [851, "蕾娜", "「嗯？怎么了，将臣？」", "len415_034.ogg", "朝武_自室a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "27"}, "CHAPTER 4-1", null, null], [852, "将臣", "「你在听吗，怎么一副笑嘻嘻的样子」", null, "朝武_自室a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "27"}, "CHAPTER 4-1", null, null], [853, "将臣", "「我可没有跟你开玩笑哦……」", null, "朝武_自室a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "27"}, "CHAPTER 4-1", null, null], [854, "蕾娜", "「抱、抱歉！我不是没在听你说话」", "len415_035.ogg", "朝武_自室a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "27"}, "CHAPTER 4-1", null, null], [855, "蕾娜", "「就是不知不觉就笑出来了……怎么说呢，因为知道你很认真，所以我反而更想笑」", "len415_036.ogg", "朝武_自室a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "16"}, "CHAPTER 4-1", null, null], [856, "", "难不成我认真说事情的样子看上去很好笑？", null, "朝武_自室a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "03"}, "CHAPTER 4-1", null, null], [857, "", "但好像也不是这么回事……", null, "朝武_自室a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "03"}, "CHAPTER 4-1", null, null], [858, "", "不知为何，蕾娜的言行举止中透着一股酸甜青涩的氛围，以前我还从来没遇到过这种情况。", null, "朝武_自室a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "03"}, "CHAPTER 4-1", null, null], [859, "蕾娜", "「对了对了！碎片还没有全部收集齐吧？」", "len415_037.ogg", "朝武_自室a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "25"}, "CHAPTER 4-1", null, null], [860, "将臣", "「哎！还没收集齐吗？」", null, "朝武_自室a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "25"}, "CHAPTER 4-1", null, null], [861, "美津叶", "「是的，这件事还是让丛雨大人来跟你们说明吧」", "miz415_014.ogg", "朝武_自室a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "14"}, "CHAPTER 4-1", null, null], [862, "美津叶", "「丛雨大人应该就在你身边吧？」", "miz415_015.ogg", "朝武_自室a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "05"}, "CHAPTER 4-1", null, null], [863, "将臣", "「嗯……好吧」", null, "朝武_自室a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "05"}, "CHAPTER 4-1", null, null], [864, "", "虽然小雨时不时就会说上几句，但我差点忘了驹川大夫是听不见的。", null, "朝武_自室a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "05"}, "CHAPTER 4-1", null, null], [865, "将臣", "「小雨，这是怎么回事？」", null, "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "10"}, "CHAPTER 4-1", null, null], [866, "将臣", "「我还以为，所有没找到的碎片在昨晚都变成祟神了」", null, "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "10"}, "CHAPTER 4-1", null, null], [867, "丛雨", "「嗯。本座昨晚不是问过主人吗，问你是不是从很早以前开始就带着碎片」", "mur415_024.ogg", "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "17"}, "CHAPTER 4-1", null, null], [868, "将臣", "「我记得你说，我可能不知不觉中一直带在身上」", null, "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "17"}, "CHAPTER 4-1", null, null], [869, "将臣", "「但我根本想不起来……」", null, "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "17"}, "CHAPTER 4-1", null, null], [870, "丛雨", "「不，看到蕾娜把碎片吸收进体内时，本座确信了」", "mur415_025.ogg", "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "10"}, "CHAPTER 4-1", null, null], [871, "丛雨", "「主人可能也跟她一样，把碎片吸收进体内了」", "mur415_026.ogg", "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "14"}, "CHAPTER 4-1", null, null], [872, "蕾娜", "「将臣也吸收了吗！？」", "len415_038.ogg", "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "14"}, "CHAPTER 4-1", null, null], [873, "将臣", "「不是，先别急啊！那种事我就更没有印象了」", null, "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "14"}, "CHAPTER 4-1", null, null], [874, "将臣", "「我搬过来之前根本就没见过祟神啊」", null, "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "14"}, "CHAPTER 4-1", null, null], [875, "丛雨", "「可是主人，如果你体内没有碎片，那你为什么能摸到本座呢，为什么你的意识会被碎片吸引过去呢？」", "mur415_027.ogg", "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "27"}, "CHAPTER 4-1", null, null], [876, "丛雨", "「如果你确实吸收过碎片，那这些问题就有答案了……蕾娜」", "mur415_028.ogg", "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "24"}, "CHAPTER 4-1", null, null], [877, "", "小雨向蕾娜伸出手。", null, "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "24"}, "CHAPTER 4-1", null, null], [878, "蕾娜", "「嗯，有什么事吗？」", "len415_039.ogg", "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "11"}, "CHAPTER 4-1", null, null], [879, "丛雨", "「能和本座握个手吗？」", "mur415_029.ogg", "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "16"}, "CHAPTER 4-1", null, null], [880, "蕾娜", "「当然可以呀！」", "len415_040.ogg", "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "10"}, "CHAPTER 4-1", null, null], [881, "将臣", "「哎？可是……哎哎哎！？」", null, "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "10"}, "CHAPTER 4-1", null, null], [882, "丛雨", "「哇哦哦哦，本座自己都有些惊讶！蕾娜的手和主人不一样，摸上去软软的」", "mur415_030.ogg", "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "03"}, "CHAPTER 4-1", null, null], [883, "蕾娜", "「嘿嘿，是吗？小雨的手真是又小又温暖」", "len415_041.ogg", "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "03"}, "CHAPTER 4-1", null, null], [884, "丛雨", "「嗯……人的体温，真是令人怀念」", "mur415_031.ogg", "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "20"}, "CHAPTER 4-1", null, null], [885, "", "至今为止，能够触碰到小雨的只有我一个。", null, "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "20"}, "CHAPTER 4-1", null, null], [886, "", "可是小雨现在正在和蕾娜握手，这也就是说……", null, "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "20"}, "CHAPTER 4-1", null, null], [887, "美津叶", "「不好意思……能告诉我发生了什么吗？」", "miz415_016.ogg", "朝武_自室a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "31"}, "CHAPTER 4-1", null, null], [888, "将臣", "「那个……小雨和蕾娜，现在正在握手！」", null, "朝武_自室a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "31"}, "CHAPTER 4-1", null, null], [889, "蕾娜", "「啊，对哦！我本来是摸不到小雨的」", "len415_042.ogg", "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "01"}, "CHAPTER 4-1", null, null], [890, "将臣", "「之前一直都是摸不到的吧？这么说……果然是因为你吸收了宿体，所以就能摸到了？」", null, "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "01"}, "CHAPTER 4-1", null, null], [891, "丛雨", "「应该是这样」", "mur415_032.ogg", "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "40"}, "CHAPTER 4-1", null, null], [892, "", "那么倒推回来，能摸到小雨的我肯定也吸收了碎片吗？", null, "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "40"}, "CHAPTER 4-1", null, null], [893, "将臣", "「可我到底是什么时候吸收进去的？我真的不记得了」", null, "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "40"}, "CHAPTER 4-1", null, null], [894, "丛雨", "「因为某种巧合，身体吸收了碎片……会不会有这种情况？」", "mur415_033.ogg", "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "39"}, "CHAPTER 4-1", null, null], [895, "丛雨", "「比如小时候，在山上玩时摔了一跤，石头扎进了身体里，或者是不小心把石子弄到了嘴里」", "mur415_034.ogg", "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "29"}, "CHAPTER 4-1", null, null], [896, "将臣", "「这个……我也不敢肯定说绝对没有」", null, "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "29"}, "CHAPTER 4-1", null, null], [897, "蕾娜", "「我记得你之前说过，说你小时候有一次不小心溺水了对吧？」", "len415_043.ogg", "朝武_自室a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "30"}, "CHAPTER 4-1", null, null], [898, "将臣", "「嗯……那个时候我脑子一片混乱，只知道在水里拼命挣扎」", null, "朝武_自室a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "30"}, "CHAPTER 4-1", null, null], [899, "", "碎片会不会是和水一起被我喝下去了？", null, "朝武_自室a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "30"}, "CHAPTER 4-1", null, null], [900, "将臣", "「可想来想去，还是难以想象自己真的吞过石头」", null, "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "10"}, "CHAPTER 4-1", null, null], [901, "将臣", "「小雨，就没有什么办法可以直接确认吗？」", null, "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "10"}, "CHAPTER 4-1", null, null], [902, "丛雨", "「很可惜，除了把碎片取出来之外，并没有什么好办法」", "mur415_037.ogg", "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "36"}, "CHAPTER 4-1", null, null], [903, "将臣", "「也是，大夫刚才说有办法取出碎片。那到底是什么办法……应该不会是做手术之类的吧？」", null, "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "36"}, "CHAPTER 4-1", null, null], [904, "丛雨", "「当然不是。吸收碎片的应该并不是肉体，而是灵魂」", "mur415_038.ogg", "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "11"}, "CHAPTER 4-1", null, null], [905, "丛雨", "「话虽如此，它在人体内也依然是异物」", "mur415_039.ogg", "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "14"}, "CHAPTER 4-1", null, null], [906, "丛雨", "「它不可能完全和人体融合在一起，是有办法取出来的」", "mur415_040.ogg", "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "10"}, "CHAPTER 4-1", null, null], [907, "蕾娜", "「既然如此，要不先把将臣体内的碎片取出来怎么样？」", "len415_044.ogg", "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "10"}, "CHAPTER 4-1", null, null], [908, "丛雨", "「不，你们都忘了吗？我们收集的碎片都被蕾娜吸收进去了」", "mur415_041.ogg", "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "36"}, "CHAPTER 4-1", null, null], [909, "丛雨", "「要是现在就从将臣体内取出碎片，很有可能也会被蕾娜吸收进去」", "mur415_042.ogg", "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "13"}, "CHAPTER 4-1", null, null], [910, "蕾娜", "「哦、也是，确实很有可能」", "len415_045.ogg", "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "13"}, "CHAPTER 4-1", null, null], [911, "将臣", "「也就是说，现在还不能随便取出碎片？」", null, "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "13"}, "CHAPTER 4-1", null, null], [912, "丛雨", "「嗯，还有很多事搞不清楚。如果宿体在这种情况下变成了完整的状态，到底会发生什么？」", "mur415_043.ogg", "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "35"}, "CHAPTER 4-1", null, null], [913, "丛雨", "「说实话，本座也根本无法想象」", "mur415_044.ogg", "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "36"}, "CHAPTER 4-1", null, null], [914, "丛雨", "「所以就目前来说，先保持现状静观其变比较好」", "mur415_045.ogg", "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "26"}, "CHAPTER 4-1", null, null], [915, "丛雨", "「虽然这样可能会给蕾娜和主人添些麻烦」", "mur415_046.ogg", "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "25"}, "CHAPTER 4-1", null, null], [916, "蕾娜", "「不会的，我还觉得我给你们添了不少麻烦呢」", "len415_046.ogg", "朝武_自室a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "06"}, "CHAPTER 4-1", null, null], [917, "将臣", "「我也无所谓，反正就算体内有碎片，也是很早以前就有了，事到如今纠结这个也没用」", null, "朝武_自室a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "06"}, "CHAPTER 4-1", null, null], [918, "", "不过，心里多少还是会有些不自在。", null, "朝武_自室a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "06"}, "CHAPTER 4-1", null, null], [919, "蕾娜", "「如果我们调查得差不多了，就可以把碎片取出来了吧？」", "len415_047.ogg", "朝武_自室a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "25"}, "CHAPTER 4-1", null, null], [920, "美津叶", "「那是当然。我也会出一份力，一同调查这件事」", "miz415_017.ogg", "朝武_自室a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "02"}, "CHAPTER 4-1", null, null], [921, "美津叶", "「如果你们发现身体有任何异常，无论多么细小的变化都务必告诉我」", "miz415_018.ogg", "朝武_自室a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "29"}, "CHAPTER 4-1", null, null], [922, "美津叶", "「毕竟我也是个医生」", "miz415_019.ogg", "朝武_自室a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "02"}, "CHAPTER 4-1", null, null], [923, "将臣", "「抱歉，总是给您添麻烦」", null, "朝武_自室a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "02"}, "CHAPTER 4-1", null, null], [924, "美津叶", "「哪里的话，治病救人就是我的工作。而且，第一个发现宿体碎片的是你吧？」", "miz415_020.ogg", "朝武_自室a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "02"}, "CHAPTER 4-1", null, null], [925, "美津叶", "「多亏了你，我们才能取得这么大的进展，你要多拿出点自信来啊」", "miz415_021.ogg", "朝武_自室a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "18"}, "CHAPTER 4-1", null, null], [926, "丛雨", "「看吧，连驹川都这么赏识你。实际上本座也是这么想的」", "mur415_047.ogg", "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "28"}, "CHAPTER 4-1", null, null], [927, "丛雨", "「不过在宿体的事情解决之前，为了以防万一，你们恐怕得留在穗织了」", "mur415_048.ogg", "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "26"}, "CHAPTER 4-1", null, null], [928, "将臣", "「……哎」", null, "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "26"}, "CHAPTER 4-1", null, null], [929, "蕾娜", "「可是我签证到期的时候，必须得回国一趟」", "len415_048.ogg", "朝武_自室a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "25"}, "CHAPTER 4-1", null, null], [930, "", "啊，这种事确实没办法。", null, "朝武_自室a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "25"}, "CHAPTER 4-1", null, null], [931, "美津叶", "「我们肯定不希望拖到那个时候，能尽快解决就尽快解决」", "miz415_022.ogg", "朝武_自室a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "09"}, "CHAPTER 4-1", null, null], [932, "美津叶", "「丛雨大人是什么意见？」", "miz415_023.ogg", "朝武_自室a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "01"}, "CHAPTER 4-1", null, null], [933, "丛雨", "「本座也觉得此事不宜拖得太久。总之，还是得先观察一段时间，然后才能下结论」", "mur415_049.ogg", "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "11"}, "CHAPTER 4-1", null, null], [934, "丛雨", "「毕竟时间拖得越长，发生意外的可能性也就越高」", "mur415_050.ogg", "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "13"}, "CHAPTER 4-1", null, null], [935, "丛雨", "「如果出现了迫不得已的情况，我们也会考虑提前把宿体取出来的」", "mur415_051.ogg", "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "14"}, "CHAPTER 4-1", null, null], [936, "将臣", "「原来如此」", null, "朝武_自室a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "14"}, "CHAPTER 4-1", null, null], [937, "", "我将小雨的话转告给了驹川大夫。", null, "朝武_自室a", "bgm39.opus", null, "CHAPTER 4-1", null, null], [938, "", "其中有一句话，始终在我脑中挥之不去。", null, "朝武_自室a", "bgm39.opus", null, "CHAPTER 4-1", null, null], [939, "", "“恐怕得留在穗织了”。", null, "朝武_自室a", "bgm39.opus", null, "CHAPTER 4-1", null, null], [940, "", "虽然我已经在这里住习惯了，可我说到底还是外地人。", null, "朝武_自室a", "bgm39.opus", null, "CHAPTER 4-1", null, null], [941, "", "诅咒解开、事件解决之后，我是不是终有一天也会离开穗织呢？", null, "朝武_自室a", "bgm39.opus", null, "CHAPTER 4-1", null, null], [942, "蕾娜", "「我明白了……哎呀！」", "len415_049.ogg", "朝武_自室a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "03"}, "CHAPTER 4-1", null, null], [943, "蕾娜", "「我差不多该回去工作了」", "len415_050.ogg", "朝武_自室a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "30"}, "CHAPTER 4-1", null, null], [944, "将臣", "「也是，都这个点了」", null, "朝武_自室a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "30"}, "CHAPTER 4-1", null, null], [945, "", "昨晚遭遇了那么多事，今天还得工作吗。", null, "朝武_自室a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "30"}, "CHAPTER 4-1", null, null], [946, "将臣", "「不好意思，你工作这么忙，还来照顾我」", null, "朝武_自室a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "30"}, "CHAPTER 4-1", null, null], [947, "蕾娜", "「这点小事是我应该做的！」", "len415_051.ogg", "朝武_自室a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "02"}, "CHAPTER 4-1", null, null], [948, "将臣", "「谢谢你，蕾娜。我送你一程吧」", null, "朝武_自室a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "02"}, "CHAPTER 4-1", null, null], [949, "蕾娜", "「不用了不用了！不用送了，你就好好躺着休息吧」", "len415_052.ogg", "朝武_自室a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "28"}, "CHAPTER 4-1", null, null], [950, "将臣", "「没关系，反正我现在身上也不怎么疼」", null, "朝武_自室a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "28"}, "CHAPTER 4-1", null, null], [951, "", "她照顾了我这么长时间，我也该送送她。", null, "朝武_自室a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "28"}, "CHAPTER 4-1", null, null], [952, "", "刚和蕾娜走到院子里，朝武和常陆也追了上来。", null, "神社_境内a", "bgm40.opus", null, "CHAPTER 4-1", null, null], [953, "将臣", "「你们来啦，现在已经可以起来走动了吗？」", null, "神社_境内a", "bgm40.opus", null, "CHAPTER 4-1", null, null], [954, "茉子", "「哈哈，我们没事，也就是把你们抬下山之后累得浑身肌肉酸痛而已」", "mak415_001.ogg", "神社_境内a", "bgm40.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "46"}, "CHAPTER 4-1", null, null], [955, "蕾娜", "「唔，真是不好意思……我会减肥的」", "len415_053.ogg", "神社_境内a", "bgm40.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "46"}, "CHAPTER 4-1", null, null], [956, "茉子", "「你看看你，我当然是跟你开玩笑的啦，你可不要什么话都那么当真」", "mak415_002.ogg", "神社_境内a", "bgm40.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "28"}, "CHAPTER 4-1", null, null], [957, "芳乃", "「蕾娜，是我们连累了你，真不知道该怎么跟你道歉了」", "yos415_001.ogg", "神社_境内a", "bgm40.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "13"}, "CHAPTER 4-1", null, null], [958, "芳乃", "「你本来跟这件事没什么关系的，都怪我们不好」", "yos415_002.ogg", "神社_境内a", "bgm40.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "12"}, "CHAPTER 4-1", null, null], [959, "芳乃", "「所以听见你要回去工作，我们肯定得来送送你啊」", "yos415_003.ogg", "神社_境内a", "bgm40.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "17"}, "CHAPTER 4-1", null, null], [960, "蕾娜", "「芳乃你也真是的，从昨天到现在都说了多少遍啦？这点事，别那么放在心上」", "len415_054.ogg", "神社_境内a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "21"}, "CHAPTER 4-1", null, null], [961, "蕾娜", "「而且我们是朋友呀，朋友的事怎么会跟我没有关系呢！」", "len415_055.ogg", "神社_境内a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "19"}, "CHAPTER 4-1", null, null], [962, "蕾娜", "「其实，我一直都很想帮帮你们呢」", "len415_056.ogg", "神社_境内a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "03"}, "CHAPTER 4-1", null, null], [963, "芳乃", "「蕾娜……」", "yos415_004.ogg", "神社_境内a", "bgm40.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "04"}, "CHAPTER 4-1", null, null], [964, "蕾娜", "「虽然到头来给你们添了不少麻烦」", "len415_057.ogg", "神社_境内a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "17"}, "CHAPTER 4-1", null, null], [965, "将臣", "「蕾娜，你也不用那么放在心上的」", null, "神社_境内a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "17"}, "CHAPTER 4-1", null, null], [966, "将臣", "「要不是因为你在，昨晚我可能就被祟神踩扁了」", null, "神社_境内a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "34"}, "CHAPTER 4-1", null, null], [967, "芳乃", "「可不是么，虽然昨晚也是多亏了有地，我们才能熬过一劫」", "yos415_005.ogg", "神社_境内a", "bgm40.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "30"}, "CHAPTER 4-1", null, null], [968, "芳乃", "「但当时那情况，我真是整个人都吓懵了」", "yos415_006.ogg", "神社_境内a", "bgm40.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "31"}, "CHAPTER 4-1", null, null], [969, "茉子", "「煞有介事地说要帮我们争取时间，结果一瞬间就被祟神甩在身后」", "mak415_003.ogg", "神社_境内a", "bgm40.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "30"}, "CHAPTER 4-1", null, null], [970, "将臣", "「唔……抱歉，我也觉得自己表现得太丢人了」", null, "神社_境内a", "bgm40.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "30"}, "CHAPTER 4-1", null, null], [971, "茉子", "「哈哈，没事，反正最后大家都得救了」", "mak415_004.ogg", "神社_境内a", "bgm40.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "27"}, "CHAPTER 4-1", null, null], [972, "茉子", "「当时若不是你挡在蕾娜面前，她可能就要受伤了，对吧？」", "mak415_005.ogg", "神社_境内a", "bgm40.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "34"}, "CHAPTER 4-1", null, null], [973, "蕾娜", "「…………没、没错」", "len415_058.ogg", "神社_境内a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "29"}, "CHAPTER 4-1", null, null], [974, "", "咦？蕾娜捂着胸口，低下了头。", null, "神社_境内a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "29"}, "CHAPTER 4-1", null, null], [975, "蕾娜", "「能、能把将臣稍微借我一下吗？」", "len415_059.ogg", "神社_境内a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "29"}, "CHAPTER 4-1", null, null], [976, "将臣", "「有什么事……哎！？」", null, "神社_境内a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "29"}, "CHAPTER 4-1", null, null], [977, "", "突然，蕾娜握住了我的手。", null, "神社_境内a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "05"}, "CHAPTER 4-1", null, null], [978, "", "突如其来的异性肢体接触把我吓了一跳，我就这么被蕾娜拉到了稍远的地方。", null, "神社_境内a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "05"}, "CHAPTER 4-1", null, null], [979, "", "感觉心跳有点加快，我……我要冷静。", null, "神社_境内a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "05"}, "CHAPTER 4-1", null, null], [980, "", "蕾娜是外国人，在外国肢体接触是很普遍的，我要是表现得太抗拒或许会比较失礼。", null, "神社_境内a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "05"}, "CHAPTER 4-1", null, null], [981, "将臣", "「呃，有什么事吗？」", null, "神社_境内a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "05"}, "CHAPTER 4-1", null, null], [982, "蕾娜", "「那、那个，将臣，昨晚回来之后，她们告诉我以后不能吃梦里的东西」", "len415_060.ogg", "神社_境内a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "12"}, "CHAPTER 4-1", null, null], [983, "蕾娜", "「其实，当时我在梦里，差一点就吃了」", "len415_061.ogg", "神社_境内a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "29"}, "CHAPTER 4-1", null, null], [984, "将臣", "「是吗，也就是说你听到了我的呼喊？你最后并没有吃梦里的东西吧」", null, "神社_境内a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "29"}, "CHAPTER 4-1", null, null], [985, "蕾娜", "「没有……因为是你让我意识到了那是在做梦」", "len415_062.ogg", "神社_境内a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "27"}, "CHAPTER 4-1", null, null], [986, "将臣", "「是我让你意识到的？原来是这样啊」", null, "神社_境内a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "27"}, "CHAPTER 4-1", null, null], [987, "蕾娜", "「至于具体是怎么意识到的……有点不太好说，总之都是多亏了你」", "len415_063.ogg", "神社_境内a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "02"}, "CHAPTER 4-1", null, null], [988, "将臣", "「呃、嗯……」", null, "神社_境内a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "02"}, "CHAPTER 4-1", null, null], [989, "", "不知为什么，和蕾娜聊着这些，我感觉相当难为情。", null, "神社_境内a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "02"}, "CHAPTER 4-1", null, null], [990, "蕾娜", "「所以我不仅要感谢你从祟神爪下保护了我，还要感谢你把我从梦中唤醒」", "len415_064.ogg", "神社_境内a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "27"}, "CHAPTER 4-1", null, null], [991, "蕾娜", "「真的很谢谢你，将臣」", "len415_065.ogg", "神社_境内a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "19"}, "CHAPTER 4-1", null, null], [992, "将臣", "「朋友之间就应该互相帮助嘛。再说刚才你都已经道过谢了」", null, "神社_境内a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "19"}, "CHAPTER 4-1", null, null], [993, "将臣", "「朝武也说了，这件事说到底是我们把你牵扯进来的」", null, "神社_境内a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "20"}, "CHAPTER 4-1", null, null], [994, "将臣", "「当时情况很紧急，我们怎么叫都叫不醒你，我也顾不上别的，就想至少要让你平安归来」", null, "神社_境内a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "20"}, "CHAPTER 4-1", null, null], [995, "蕾娜", "「…………」", "len415_066.ogg", "神社_境内a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "04"}, "CHAPTER 4-1", null, null], [996, "将臣", "「……咦，蕾娜？」", null, "神社_境内a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "04"}, "CHAPTER 4-1", null, null], [997, "蕾娜", "「将臣……」", "len415_067.ogg", "神社_境内a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "12"}, "CHAPTER 4-1", null, null], [998, "蕾娜", "「如果当时遭遇危险的不是我，而是别人，你也会那样保护她吗？还是说……」", "len415_068.ogg", "神社_境内a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "07"}, "CHAPTER 4-1", null, null], [999, "将臣", "「哎？这个……我觉得，应该会吧？」", null, "神社_境内a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "07"}, "CHAPTER 4-1", null, null], [1000, "将臣", "「毕竟情况紧急，我也没多想，换一种情况就不好说了」", null, "神社_境内a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "34"}, "CHAPTER 4-1", null, null], [1001, "蕾娜", "「……这样啊，嗯……说的也是！」", "len415_069.ogg", "神社_境内a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "28"}, "CHAPTER 4-1", null, null], [1002, "蕾娜", "「愿意帮助所有人才是真正的善良，也许这样才更好！」", "len415_070.ogg", "神社_境内a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "23"}, "CHAPTER 4-1", null, null], [1003, "将臣", "「哎？应该没那么夸张吧……你是在说什么？」", null, "神社_境内a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "23"}, "CHAPTER 4-1", null, null], [1004, "蕾娜", "「嗯？嘿嘿……不告诉你」", "len415_071.ogg", "神社_境内a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "03"}, "CHAPTER 4-1", null, null], [1005, "蕾娜", "「那我先走了，将臣，咱们明天见！」", "len415_072.ogg", "神社_境内a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "02"}, "CHAPTER 4-1", null, null], [1006, "", "蕾娜转过身来，向大家挥手。", null, "神社_境内a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "19"}, "CHAPTER 4-1", null, null], [1007, "", "离开神社的这一小段路，蕾娜连续好几次冲我回头，并向我挥手。", null, "神社_境内a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "19"}, "CHAPTER 4-1", null, null], [1008, "", "难不成我博得了她的好感？", null, "神社_境内a", "bgm40.opus", null, "CHAPTER 4-1", null, null], [1009, "", "要真是这样，那我昨晚拼命保护她也算值了。", null, "神社_境内a", "bgm40.opus", null, "CHAPTER 4-1", null, null], [1010, "茉子", "「你们俩什么时候关系变得这么好了呀」", "mak415_006.ogg", "神社_境内a", "bgm40.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "31"}, "CHAPTER 4-1", null, null], [1011, "将臣", "「哎？你说蕾娜？她只是向我道谢而已」", null, "神社_境内a", "bgm40.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "31"}, "CHAPTER 4-1", null, null], [1012, "芳乃", "「话说回来，真是让人担心啊」", "yos415_007.ogg", "神社_境内a", "bgm40.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "12"}, "CHAPTER 4-1", null, null], [1013, "茉子", "「是挺让人不放心的」", "mak415_007.ogg", "神社_境内a", "bgm40.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "18"}, "CHAPTER 4-1", null, null], [1014, "将臣", "「等一下，你们是不是误会了什么」", null, "神社_境内a", "bgm40.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "12"}, "CHAPTER 4-1", null, null], [1015, "将臣", "「我可没有做什么不该做的事，你们担心什么啊……」", null, "神社_境内a", "bgm40.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "12"}, "CHAPTER 4-1", null, null], [1016, "芳乃", "「有地，你在说什么呢？」", "yos415_008.ogg", "神社_境内a", "bgm40.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "06"}, "CHAPTER 4-1", null, null], [1017, "芳乃", "「蕾娜醒了之后就一直在照顾我和茉子，她昨晚可能一夜都没睡」", "yos415_009.ogg", "神社_境内a", "bgm40.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "13"}, "CHAPTER 4-1", null, null], [1018, "将臣", "「她一晚上都没睡？然后就这么直接回去干活了？」", null, "神社_境内a", "bgm40.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "13"}, "CHAPTER 4-1", null, null], [1019, "芳乃", "「是的，吸收宿体会给她的身体带来什么影响，我们还一无所知」", "yos415_010.ogg", "神社_境内a", "bgm40.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "31"}, "CHAPTER 4-1", null, null], [1020, "茉子", "「我也觉得，我们应该尽量留意蕾娜的身体状况」", "mak415_008.ogg", "神社_境内a", "bgm40.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "01"}, "CHAPTER 4-1", null, null], [1021, "芳乃", "「如果可以的话，我甚至希望她能直接住到我们家来」", "yos415_011.ogg", "神社_境内a", "bgm40.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "39"}, "CHAPTER 4-1", null, null], [1022, "", "蕾娜搬过来一起住的话，遇上突发情况时确实更容易处理。", null, "神社_境内a", "bgm40.opus", null, "CHAPTER 4-1", null, null], [1023, "将臣", "「但是，在旅馆工作一般都得住在那里」", null, "神社_境内a", "bgm40.opus", null, "CHAPTER 4-1", null, null], [1024, "丛雨", "「志那都庄离山更远，应该会更安全一些吧？」", "mur415_052.ogg", "神社_境内a", "bgm40.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "11"}, "CHAPTER 4-1", null, null], [1025, "芳乃", "「嗯，这倒也是」", "yos415_012.ogg", "神社_境内a", "bgm40.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "07"}, "CHAPTER 4-1", null, null], [1026, "美津叶", "「如果只是观察她的健康状况，拜托玄十郎先生就可以了吧」", "miz415_024.ogg", "神社_境内a", "bgm40.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "07"}, "CHAPTER 4-1", null, null], [1027, "将臣", "「要让我外公帮忙吗？」", null, "神社_境内a", "bgm40.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "07"}, "CHAPTER 4-1", null, null], [1028, "美津叶", "「反正，这件事早晚都得告诉他」", "miz415_025.ogg", "神社_境内a", "bgm40.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "14"}, "CHAPTER 4-1", null, null], [1029, "", "确实，现在根本不知道她身上会发生什么，还是有必要让旅馆的工作人员理解这一状况。", null, "神社_境内a", "bgm40.opus", null, "CHAPTER 4-1", null, null], [1030, "", "上学前以及剑道训练之后，我也抽空去看看蕾娜的情况吧，这样比较好。", null, "神社_境内a", "bgm40.opus", null, "CHAPTER 4-1", null, null], [1031, "将臣", "「啊！既然如此，我刚才就应该送她回志那都庄的」", null, "神社_境内a", "bgm40.opus", null, "CHAPTER 4-1", null, null], [1032, "将臣", "「顺便和外公说明一下她的情况……」", null, "神社_境内a", "bgm40.opus", null, "CHAPTER 4-1", null, null], [1033, "美津叶", "「站住！你忘了你才是伤势最重的吗？」", "miz415_026.ogg", "神社_境内a", "bgm40.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "10"}, "CHAPTER 4-1", null, null], [1034, "将臣", "「没事，走个几步路根本不会有什么大碍……吧」", null, "神社_境内a", "bgm40.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "10"}, "CHAPTER 4-1", null, null], [1035, "茉子", "「不行，可不能让大灰狼送小红帽回家」", "mak415_009.ogg", "神社_境内a", "bgm40.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "09"}, "CHAPTER 4-1", null, null], [1036, "芳乃", "「……大灰狼？」", "yos415_013.ogg", "神社_境内a", "bgm40.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "30"}, "CHAPTER 4-1", null, null], [1037, "将臣", "「不会的不会的！朝武，这个词你不用记住！还有常陆，你真的没有误会什么吗？」", null, "神社_境内a", "bgm40.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "30"}, "CHAPTER 4-1", null, null], [1038, "茉子", "「哈哈，总之，蕾娜的事就交给我吧」", "mak415_010.ogg", "神社_境内a", "bgm40.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "01"}, "CHAPTER 4-1", null, null], [1039, "茉子", "「暗中观察也算是我的老本行了」", "mak415_011.ogg", "神社_境内a", "bgm40.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "27"}, "CHAPTER 4-1", null, null], [1040, "美津叶", "「要我说的话，我还是觉得你最好也待在家里安心养病」", "miz415_027.ogg", "神社_境内a", "bgm40.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "32"}, "CHAPTER 4-1", null, null], [1041, "美津叶", "「不过嘛，总比让有地去要好」", "miz415_028.ogg", "神社_境内a", "bgm40.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "13"}, "CHAPTER 4-1", null, null], [1042, "", "我的伤势有那么重吗？", null, "神社_境内a", "bgm40.opus", null, "CHAPTER 4-1", null, null], [1043, "", "我自己倒觉得没什么大碍了。", null, "神社_境内a", "bgm40.opus", null, "CHAPTER 4-1", null, null], [1044, "将臣", "「呼～这里的浴池泡起来就是舒服啊～」", null, "朝武_自室d", "bgm05.opus", null, "CHAPTER 4-1", null, null], [1045, "", "我泡完澡后，拿着毛巾一边擦头发，一边回到了自己房间。", null, "朝武_自室d", "bgm05.opus", null, "CHAPTER 4-1", null, null], [1046, "", "坐在铺好的褥子上，我试了试用手握拳，再把手掌张开。", null, "朝武_自室d", "bgm05.opus", null, "CHAPTER 4-1", null, null], [1047, "将臣", "「……身体能照常活动啊」", null, "朝武_自室d", "bgm05.opus", null, "CHAPTER 4-1", null, null], [1048, "", "不过刚才去洗澡的时候，脱完衣服后我自己都吓了一跳。", null, "朝武_自室d", "bgm05.opus", null, "CHAPTER 4-1", null, null], [1049, "", "身上到处都是青一块紫一块的。", null, "朝武_自室d", "bgm05.opus", null, "CHAPTER 4-1", null, null], [1050, "", "身上这么多伤，可能还是不泡澡好一些，但我明天还要去学校，想了想还是泡了个澡。", null, "朝武_自室d", "bgm05.opus", null, "CHAPTER 4-1", null, null], [1051, "", "泡完澡出来，身上也没什么不舒服的地方，应该没什么大碍了。", null, "朝武_自室d", "bgm05.opus", null, "CHAPTER 4-1", null, null], [1052, "将臣", "「……嗯？」", null, "朝武_自室d", "bgm05.opus", null, "CHAPTER 4-1", null, null], [1053, "", "有邮件？是从不认识的邮箱地址发来的。", null, "朝武_自室d", "bgm05.opus", null, "CHAPTER 4-1", null, null], [1054, "", "不过，邮箱地址里面有“ｌｅｎａ”这几个字。", null, "朝武_自室d", "bgm05.opus", null, "CHAPTER 4-1", null, null], [1055, "", "我看看……果然是蕾娜发来的！", null, "朝武_自室d", "bgm05.opus", null, "CHAPTER 4-1", null, null], [1056, "蕾娜", "『Ｍｏｉ！将臣，这是我第一次给你发邮件』", "len415_073.ogg", "朝武_自室d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "19"}, "CHAPTER 4-1", null, null], [1057, "蕾娜", "『我问茉子要到了你的邮箱地址，你不会介意吧？？：）』", "len415_074.ogg", "朝武_自室d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "27"}, "CHAPTER 4-1", null, null], [1058, "将臣", "「喔，常陆确实说过要帮忙观察蕾娜的情况」", null, "朝武_自室d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "27"}, "CHAPTER 4-1", null, null], [1059, "", "她们女孩子之间已经交换过邮箱地址了吗？", null, "朝武_自室d", "bgm05.opus", null, "CHAPTER 4-1", null, null], [1060, "", "我记得“：）”是外国人常用的颜文字，他们喜欢把笑脸横过来。", null, "朝武_自室d", "bgm05.opus", null, "CHAPTER 4-1", null, null], [1061, "", "我立刻回复了蕾娜，表示不介意她存我的邮箱地址。", null, "朝武_自室d", "bgm05.opus", null, "CHAPTER 4-1", null, null], [1062, "", "还有，Ｍｏｉ是什么意思啊？", null, "朝武_自室d", "bgm05.opus", null, "CHAPTER 4-1", null, null], [1063, "将臣", "「哇！这么快就回我了？」", null, "朝武_自室d", "bgm05.opus", null, "CHAPTER 4-1", null, null], [1064, "蕾娜", "『Ｍｏｉ就是类似于“嘿”、“你好”之类的问候语。顺便一提，Ｍｏｉｍｏｉ就是拜拜的意思！』", "len415_075.ogg", "朝武_自室d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "24"}, "CHAPTER 4-1", null, null], [1065, "将臣", "「是这样啊」", null, "朝武_自室d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "24"}, "CHAPTER 4-1", null, null], [1066, "", "虽然蕾娜时不时会说一些奇怪的日语，但总体来说她的水平还是很高的。", null, "朝武_自室d", "bgm05.opus", null, "CHAPTER 4-1", null, null], [1067, "", "像这样和她文字交流，让她教我一些我不知道的单词，这些从未尝试过的事情似乎让我看到了她崭新的一面。", null, "朝武_自室d", "bgm05.opus", null, "CHAPTER 4-1", null, null], [1068, "", "一想到这些新发现，我就忍不住露出笑容。", null, "朝武_自室d", "bgm05.opus", null, "CHAPTER 4-1", null, null], [1069, "蕾娜", "『对了，我听说你今天没去练剑道』", "len415_076.ogg", "朝武_自室d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "29"}, "CHAPTER 4-1", null, null], [1070, "蕾娜", "『我担心你的伤势是不是恶化了，所以就发短信问候一下』", "len415_077.ogg", "朝武_自室d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "12"}, "CHAPTER 4-1", null, null], [1071, "将臣", "「啊，那是因为驹川大夫让我今天不要去练」", null, "朝武_自室d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "12"}, "CHAPTER 4-1", null, null], [1072, "", "可我要是就这么告诉蕾娜，她说不定又要开始担心我了。", null, "朝武_自室d", "bgm05.opus", null, "CHAPTER 4-1", null, null], [1073, "将臣", "「我只是觉得偶尔也得放松一下」", null, "朝武_自室d", "bgm05.opus", null, "CHAPTER 4-1", null, null], [1074, "将臣", "「你那边没事吧？有什么异常情况吗？」", null, "朝武_自室d", "bgm05.opus", null, "CHAPTER 4-1", null, null], [1075, "蕾娜", "『Ｌｅｎａ一直都很精神！今天甚至比之前还要精神：）』", "len415_078.ogg", "朝武_自室d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "25"}, "CHAPTER 4-1", null, null], [1076, "将臣", "「……蕾娜回消息真是快」", null, "朝武_自室d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "25"}, "CHAPTER 4-1", null, null], [1077, "", "她用手机打日语的速度可能比我还快。", null, "朝武_自室d", "bgm05.opus", null, "CHAPTER 4-1", null, null], [1078, "", "不过，她昨晚通宵照顾我们，今天还直接回旅馆干活了吧？而且估计是一直忙到现在。", null, "朝武_自室d", "bgm05.opus", null, "CHAPTER 4-1", null, null], [1079, "", "旅馆的工作大多是体力活，说实话我很佩服蕾娜能坚持干下来。", null, "朝武_自室d", "bgm05.opus", null, "CHAPTER 4-1", null, null], [1080, "将臣", "「我也不能一直这么歇着了」", null, "朝武_自室d", "bgm05.opus", null, "CHAPTER 4-1", null, null], [1081, "", "据说最坏的情况是——那只巨大的祟神可能会变得更强，然后再次出现在我们面前。", null, "朝武_自室d", "bgm05.opus", null, "CHAPTER 4-1", null, null], [1082, "", "对那种怪物来说，我就算多锻炼几天，恐怕实力上也不会有多大差异。不过，多练练总比不练要强。", null, "朝武_自室d", "bgm05.opus", null, "CHAPTER 4-1", null, null], [1083, "", "『从明天起我会继续练剑道！你也不要太勉强自己，工作加油吧』", null, "朝武_自室d", "bgm05.opus", null, "CHAPTER 4-1", null, null], [1084, "", "我这样回复道。", null, "朝武_自室d", "bgm05.opus", null, "CHAPTER 4-1", null, null], [1085, "蕾娜", "『明天你训练的时候，我可以去参观吗？』", "len415_079.ogg", "朝武_自室d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "01"}, "CHAPTER 4-1", null, null], [1086, "将臣", "「……哎？」", null, "朝武_自室d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "01"}, "CHAPTER 4-1", null, null], [1087, "", "我原本就打算练完之后去看看蕾娜的。", null, "朝武_自室d", "bgm05.opus", null, "CHAPTER 4-1", null, null], [1088, "", "只是来参观一下而已，外公应该也不会介意吧。", null, "朝武_自室d", "bgm05.opus", null, "CHAPTER 4-1", null, null], [1089, "", "『我想应该没问题』", null, "朝武_自室d", "bgm05.opus", null, "CHAPTER 4-1", null, null], [1090, "蕾娜", "『Ｗｏｗ！我超级期待。很早以前开始，我就对日本的剑道很感兴趣！』", "len415_080.ogg", "朝武_自室d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "24"}, "CHAPTER 4-1", null, null], [1091, "蕾娜", "『我会努力给你加油的：）』", "len415_081.ogg", "朝武_自室d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "02"}, "CHAPTER 4-1", null, null], [1092, "", "呃，早上我一般就做简单的体能训练来着……不过，怎么说呢。", null, "朝武_自室d", "bgm05.opus", null, "CHAPTER 4-1", null, null], [1093, "将臣", "「她要特意跑来给我加油吗」", null, "朝武_自室d", "bgm05.opus", null, "CHAPTER 4-1", null, null], [1094, "", "一想到这里，我就特别有干劲。", null, "朝武_自室d", "bgm05.opus", null, "CHAPTER 4-1", null, null], [1095, "", "我自己都觉得，男人真是一种单纯的生物。", null, "朝武_自室d", "bgm05.opus", null, "CHAPTER 4-1", null, null], [1096, "将臣", "「唔……」", null, "画面_黒", "bgm05.opus", null, "CHAPTER 4-2", null, null], [1097, "", "就在睁开睡眼的前一秒。", null, "画面_黒", "bgm05.opus", null, "CHAPTER 4-2", null, null], [1098, "", "身上突然涌起一阵强烈的不适感。", null, "朝武_自室a", "bgm25.opus", null, "CHAPTER 4-2", null, null], [1099, "", "怎么回事……哎？", null, "朝武_自室a", "bgm25.opus", null, "CHAPTER 4-2", null, null], [1100, "", "身体动不了？当然，这种感觉并不是鬼压床。", null, "朝武_自室a", "bgm25.opus", null, "CHAPTER 4-2", null, null], [1101, "", "重新开始练剑道的那段时间，我似乎也体验过类似的感觉……", null, "朝武_自室a", "bgm25.opus", null, "CHAPTER 4-2", null, null], [1102, "将臣", "「…………哎哟」", null, "朝武_自室a", "bgm25.opus", null, "CHAPTER 4-2", null, null], [1103, "", "痛痛痛，好痛！剧烈的疼痛感让我动弹不得。", null, "朝武_自室a", "bgm25.opus", null, "CHAPTER 4-2", null, null], [1104, "", "有点像是严重的肌肉酸痛，但并不一样。这根本就不是一个级别的疼痛！", null, "朝武_自室a", "bgm25.opus", null, "CHAPTER 4-2", null, null], [1105, "将臣", "「怎么会这样？昨天还好好的……啊」", null, "朝武_自室a", "bgm25.opus", null, "CHAPTER 4-2", null, null], [1106, "", "我发现，这些疼痛全都来自于身上的淤青。", null, "朝武_自室a", "bgm25.opus", null, "CHAPTER 4-2", null, null], [1107, "", "难不成是痛觉滞后了吗？", null, "朝武_自室a", "bgm25.opus", null, "CHAPTER 4-2", null, null], [1108, "", "有些人遭遇交通事故时会伤到颈椎，这种情况有可能会过几天才产生疼痛。", null, "朝武_自室a", "bgm25.opus", null, "CHAPTER 4-2", null, null], [1109, "", "我也是类似的情况吗。", null, "朝武_自室a", "bgm25.opus", null, "CHAPTER 4-2", null, null], [1110, "", "不过，要是这种情况的话，那就跟吸收宿体、瘴气灼伤之类的原因无关了吧？", null, "朝武_自室a", "bgm25.opus", null, "CHAPTER 4-2", null, null], [1111, "将臣", "「呼……呼……」", null, "朝武_自室a", "bgm25.opus", null, "CHAPTER 4-2", null, null], [1112, "", "我在被窝里缩成一团，深呼吸了几次。", null, "朝武_自室a", "bgm25.opus", null, "CHAPTER 4-2", null, null], [1113, "", "嗯，感觉好点了……应该不至于动都动不了了。", null, "朝武_自室a", "bgm25.opus", null, "CHAPTER 4-2", null, null], [1114, "将臣", "「还好能动了……昨天才刚下定决心要努力呢」", null, "朝武_自室a", "bgm25.opus", null, "CHAPTER 4-2", null, null], [1115, "", "要是一上来就受挫，那未免太丢人了。", null, "朝武_自室a", "bgm25.opus", null, "CHAPTER 4-2", null, null], [1116, "", "昨晚蕾娜还说今天会来给我加油呢，我要是再请假，肯定又会让她担心。", null, "朝武_自室a", "bgm25.opus", null, "CHAPTER 4-2", null, null], [1117, "", "而且，祟神也不可能乖乖等你养好伤再出现。", null, "朝武_自室a", "bgm25.opus", null, "CHAPTER 4-2", null, null], [1118, "丛雨", "「喂，主人，该起床啦……哦，原来已经醒啦」", "mur416_001.ogg", "朝武_自室a", "bgm25.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "01"}, "CHAPTER 4-2", null, null], [1119, "将臣", "「嗯，我正准备起床洗漱」", null, "朝武_自室a", "bgm25.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "01"}, "CHAPTER 4-2", null, null], [1120, "", "嗯，还是去吧。", null, "朝武_自室a", "bgm25.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "01"}, "CHAPTER 4-2", null, null], [1121, "", "努把力应该能扛过去……大概。", null, "朝武_自室a", "bgm25.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "01"}, "CHAPTER 4-2", null, null], [1122, "蕾娜", "「将臣！我在这里！！」", "len416_001.ogg", "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02"}, "CHAPTER 4-2", null, null], [1123, "将臣", "「蕾、蕾娜，早上好」", null, "学院_学院前a", "bgm34.opus", null, "CHAPTER 4-2", null, null], [1124, "蕾娜", "「嗯！早上好」", "len416_002.ogg", "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "19"}, "CHAPTER 4-2", null, null], [1125, "", "我为了热身，一路小跑来到学校，到达时蕾娜和外公已经在操场上等着我了。", null, "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "19"}, "CHAPTER 4-2", null, null], [1126, "", "蕾娜又蹦又跳，还不停地冲我挥手。而且是刚看到我就开始挥了！", null, "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "19"}, "CHAPTER 4-2", null, null], [1127, "", "她的反应过于夸张，搞得我都有点不好意思了。", null, "学院_学院前a", "bgm34.opus", null, "CHAPTER 4-2", null, null], [1128, "", "不过她这么期待我来，我心里好像还挺开心的？", null, "学院_学院前a", "bgm34.opus", null, "CHAPTER 4-2", null, null], [1129, "玄十郎", "「来了啊。听说你受伤了，不要紧吧？」", "gen416_001.ogg", "学院_学院前a", "bgm34.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "剣道", "face": "07"}, "CHAPTER 4-2", null, null], [1130, "将臣", "「呃……嗯，不打紧，不过最好不要让我做太激烈的运动」", null, "学院_学院前a", "bgm34.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "剣道", "face": "18"}, "CHAPTER 4-2", null, null], [1131, "蕾娜", "「将臣，你身上还是有哪里觉得痛吗！」", "len416_003.ogg", "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "30"}, "CHAPTER 4-2", null, null], [1132, "将臣", "「没有，我是觉得没问题了，不过以防万一，还是先不忙做剧烈运动比较好」", null, "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "30"}, "CHAPTER 4-2", null, null], [1133, "", "我并没有在说谎。", null, "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "30"}, "CHAPTER 4-2", null, null], [1134, "", "刚才慢跑过来的路上，我感觉身上的疼痛基本上都慢慢消失了。", null, "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "30"}, "CHAPTER 4-2", null, null], [1135, "", "……虽然也有可能是我对疼痛麻痹了。", null, "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "30"}, "CHAPTER 4-2", null, null], [1136, "玄十郎", "「我知道了。只跑步的话，应该没问题吧？」", "gen416_002.ogg", "学院_学院前a", "bgm34.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "剣道", "face": "15"}, "CHAPTER 4-2", null, null], [1137, "将臣", "「那应该没问题」", null, "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "30"}, "CHAPTER 4-2", null, null], [1138, "将臣", "「蕾娜，谢谢你专程过来参观。但我看你还穿着工作服，旅馆那边的工作真的不要紧吗？」", null, "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "30"}, "CHAPTER 4-2", null, null], [1139, "蕾娜", "「没事的！掌柜的也同意了」", "len416_004.ogg", "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "17"}, "CHAPTER 4-2", null, null], [1140, "", "也是，毕竟她是跟外公一起来的。", null, "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "17"}, "CHAPTER 4-2", null, null], [1141, "蕾娜", "「为了早点过来，我早上可是急急忙忙地把活都干完了」", "len416_005.ogg", "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "19"}, "CHAPTER 4-2", null, null], [1142, "将臣", "「啊？」", null, "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "19"}, "CHAPTER 4-2", null, null], [1143, "蕾娜", "「无论如何，我今天都很想给你当一回社团经理」", "len416_006.ogg", "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "03"}, "CHAPTER 4-2", null, null], [1144, "蕾娜", "「训练的时候，有什么要求都可以向我提！」", "len416_007.ogg", "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02"}, "CHAPTER 4-2", null, null], [1145, "", "对我这么好……？", null, "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02"}, "CHAPTER 4-2", null, null], [1146, "", "不过，也许只是嘴上说得比较夸张而已，毕竟我来的时候她也表现得过于兴奋。", null, "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02"}, "CHAPTER 4-2", null, null], [1147, "蕾娜", "「运动饮料我都冰好带来了」", "len416_008.ogg", "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "15"}, "CHAPTER 4-2", null, null], [1148, "将臣", "「哇，多谢了！运动完来一口冰镇运动饮料简直太爽了」", null, "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "15"}, "CHAPTER 4-2", null, null], [1149, "蕾娜", "「你也喜欢喝冰的吗？昨天晚上我想起这个，特意帮你准备了」", "len416_009.ogg", "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02"}, "CHAPTER 4-2", null, null], [1150, "蕾娜", "「我还准备了擦汗用的凉毛巾和应急用的供品，冷冻喷雾、绷带还有创伤药之类的都带了」", "len416_010.ogg", "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02"}, "CHAPTER 4-2", null, null], [1151, "将臣", "「喔！」", null, "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02"}, "CHAPTER 4-2", null, null], [1152, "", "她应该是把“备用品”和“供品”搞混了，而且创伤药不读ＳｈｏｕＹａｋｕ……", null, "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02"}, "CHAPTER 4-2", null, null], [1153, "", "不过，这些都是小问题。", null, "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02"}, "CHAPTER 4-2", null, null], [1154, "将臣", "「蕾娜，谢谢你」", null, "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02"}, "CHAPTER 4-2", null, null], [1155, "将臣", "「哎呀……没想到你会为我准备这么多东西，我真的挺开心的」", null, "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "34"}, "CHAPTER 4-2", null, null], [1156, "蕾娜", "「毕竟你昨天保护了我嘛」", "len416_011.ogg", "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27"}, "CHAPTER 4-2", null, null], [1157, "蕾娜", "「所以，我就想今天给你好好加油！」", "len416_012.ogg", "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02"}, "CHAPTER 4-2", null, null], [1158, "", "哎呀，今天硬撑着来训练真是来对了。", null, "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27"}, "CHAPTER 4-2", null, null], [1159, "", "有女孩子给自己加油鼓劲，真是比我想象中的还要开心得多。", null, "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27"}, "CHAPTER 4-2", null, null], [1160, "", "不过，对于蕾娜今天突然来给我加油，外公是怎么想的呢？", null, "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27"}, "CHAPTER 4-2", null, null], [1161, "", "他对此一句话也不说，反而让我有点在意。", null, "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27"}, "CHAPTER 4-2", null, null], [1162, "玄十郎", "「嗯。难得列支敦瑙尔小姐来了，就让她帮你计个时吧」", "gen416_003.ogg", "学院_学院前a", "bgm34.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "剣道", "face": "15"}, "CHAPTER 4-2", null, null], [1163, "将臣", "「哎？呃……好吧，今天就跑步吗？要跑多少圈呢」", null, "学院_学院前a", "bgm34.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "剣道", "face": "15"}, "CHAPTER 4-2", null, null], [1164, "玄十郎", "「跑３０圈就行了」", "gen416_004.ogg", "学院_学院前a", "bgm34.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "剣道", "face": "05"}, "CHAPTER 4-2", null, null], [1165, "将臣", "「我算算……一圈估计至少得有３００米」", null, "学院_学院前a", "bgm34.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "剣道", "face": "05"}, "CHAPTER 4-2", null, null], [1166, "", "总共跑９～１０公里？", null, "学院_学院前a", "bgm34.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "剣道", "face": "05"}, "CHAPTER 4-2", null, null], [1167, "玄十郎", "「跑出最快速度的８０％就可以了。但是，要保持好节奏」", "gen416_005.ogg", "学院_学院前a", "bgm34.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "剣道", "face": "04"}, "CHAPTER 4-2", null, null], [1168, "蕾娜", "「哇喔，一大早就来这种高强度训练呀」", "len416_013.ogg", "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "19"}, "CHAPTER 4-2", null, null], [1169, "将臣", "「哎？今天的训练量跟平时比已经轻松很多了」", null, "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "19"}, "CHAPTER 4-2", null, null], [1170, "蕾娜", "「真的吗！？」", "len416_014.ogg", "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "05"}, "CHAPTER 4-2", null, null], [1171, "将臣", "「嗯……」", null, "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "05"}, "CHAPTER 4-2", null, null], [1172, "", "看来，不知不觉中我的标准已经跟普通人不一样了。", null, "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "34"}, "CHAPTER 4-2", null, null], [1173, "", "不过也是。换成以前，每天早上跑１０公里我想都不敢想。", null, "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "34"}, "CHAPTER 4-2", null, null], [1174, "将臣", "「那就拜托你计时了，我速度要是慢下来了你就及时提醒我吧」", null, "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "34"}, "CHAPTER 4-2", null, null], [1175, "蕾娜", "「好的！计时就交给我吧」", "len416_015.ogg", "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "19"}, "CHAPTER 4-2", null, null], [1176, "", "难得蕾娜来给我加油，我可不能在她面前丢脸。", null, "学院_学院前a", "bgm34.opus", null, "CHAPTER 4-2", null, null], [1177, "", "我稍微给自己鼓了鼓劲，起跑姿势也比平常更低了一些。", null, "学院_学院前a", "bgm34.opus", null, "CHAPTER 4-2", null, null], [1178, "将臣", "「……！」", null, "学院_学院前a", "bgm34.opus", null, "CHAPTER 4-2", null, null], [1179, "", "好疼。弯下身子的那一瞬间，一阵疼痛突然袭来。", null, "学院_学院前a", "bgm34.opus", null, "CHAPTER 4-2", null, null], [1180, "", "紧接着，身上冒出了不少冷汗。", null, "学院_学院前a", "bgm34.opus", null, "CHAPTER 4-2", null, null], [1181, "玄十郎", "「怎么了，将臣？」", "gen416_006.ogg", "学院_学院前a", "bgm34.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "剣道", "face": "09"}, "CHAPTER 4-2", null, null], [1182, "将臣", "「没、没什么，我没事」", null, "学院_学院前a", "bgm34.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "剣道", "face": "09"}, "CHAPTER 4-2", null, null], [1183, "玄十郎", "「没事就好……」", "gen416_007.ogg", "学院_学院前a", "bgm34.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "剣道", "face": "11"}, "CHAPTER 4-2", null, null], [1184, "", "反正我是一路跑过来的，再跑30圈应该也没问题。", null, "学院_学院前a", "bgm34.opus", null, "CHAPTER 4-2", null, null], [1185, "", "而且，也就弯下身子的那一瞬间感觉很疼，现在疼痛正在慢慢减轻。", null, "学院_学院前a", "bgm34.opus", null, "CHAPTER 4-2", null, null], [1186, "", "要真是疼得受不了，停下来休息就是了。现在先能跑多少跑多少吧。", null, "学院_学院前a", "bgm34.opus", null, "CHAPTER 4-2", null, null], [1187, "蕾娜", "「将臣，准备好了吗？预备……跑」", "len416_016.ogg", "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "01"}, "CHAPTER 4-2", null, null], [1188, "将臣", "「出发」", null, "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "01"}, "CHAPTER 4-2", null, null], [1189, "", "我用力蹬地，开始绕着学校跑圈。", null, "学院_学院前a", "bgm34.opus", null, "CHAPTER 4-2", null, null], [1190, "", "看来，伤势的问题是我多虑了。", null, "街_目抜き通りモブa", "bgm34.opus", null, "CHAPTER 4-2", null, null], [1191, "", "快跑完的时候，身体已经找回了原来的感觉。", null, "街_目抜き通りモブa", "bgm34.opus", null, "CHAPTER 4-2", null, null], [1192, "", "现在训练已经结束，我正在送蕾娜回旅馆。", null, "街_目抜き通りモブa", "bgm34.opus", null, "CHAPTER 4-2", null, null], [1193, "", "外公说他约了朋友下围棋，自己一个人去了商店街。", null, "街_目抜き通りモブa", "bgm34.opus", null, "CHAPTER 4-2", null, null], [1194, "蕾娜", "「谢谢你专程送我回来！不过一会儿还要上学呢，不会耽误你时间吗？」", "len416_017.ogg", "街_目抜き通りモブa", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "21"}, "CHAPTER 4-2", null, null], [1195, "将臣", "「送送你是应该的，你不是也帮我准备了冰镇运动饮料嘛」", null, "街_目抜き通りモブa", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "21"}, "CHAPTER 4-2", null, null], [1196, "", "而且蕾娜毕竟吸收了宿体，我还是想尽量多观察下她的情况。", null, "街_目抜き通りモブa", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "21"}, "CHAPTER 4-2", null, null], [1197, "将臣", "「不过，难得你过来参观，我却一直在跑步，会不会觉得很无聊？」", null, "街_目抜き通りモブa", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "21"}, "CHAPTER 4-2", null, null], [1198, "蕾娜", "「不会觉得无聊呀！我在旁边加油鼓劲，可开心了」", "len416_018.ogg", "街_目抜き通りモブa", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27"}, "CHAPTER 4-2", null, null], [1199, "", "确实，蕾娜在一旁给我加油的时候又蹦又跳的。", null, "街_目抜き通りモブa", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27"}, "CHAPTER 4-2", null, null], [1200, "", "于是我也想在女生面前好好表现一下，就跑得很卖力。", null, "街_目抜き通りモブa", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27"}, "CHAPTER 4-2", null, null], [1201, "蕾娜", "「而且你跑步的时候，我一直……都在欣赏你的背影」", "len416_019.ogg", "街_目抜き通りモブa", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "03"}, "CHAPTER 4-2", null, null], [1202, "将臣", "「是、是吗？可是，你不是对剑道感兴趣吗？」", null, "街_目抜き通りモブa", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "03"}, "CHAPTER 4-2", null, null], [1203, "蕾娜", "「嗯？……喔对，我是对剑道挺感兴趣的」", "len416_020.ogg", "街_目抜き通りモブa", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27"}, "CHAPTER 4-2", null, null], [1204, "蕾娜", "「今天早上的训练，确实没什么武士的感觉」", "len416_021.ogg", "街_目抜き通りモブa", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "21"}, "CHAPTER 4-2", null, null], [1205, "", "啊，果然是喜欢那种的吗。", null, "街_目抜き通りモブa", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "21"}, "CHAPTER 4-2", null, null], [1206, "", "外国人喜欢的基本上都是武士和忍者。", null, "街_目抜き通りモブa", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "21"}, "CHAPTER 4-2", null, null], [1207, "蕾娜", "「不过，你努力的样子，我看多久都看不厌」", "len416_022.ogg", "街_目抜き通りモブa", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "19"}, "CHAPTER 4-2", null, null], [1208, "将臣", "「……是吗」", null, "街_目抜き通りモブa", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "19"}, "CHAPTER 4-2", null, null], [1209, "", "蕾娜总是说得这么直接，让我挺难为情的。", null, "街_目抜き通りモブa", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "19"}, "CHAPTER 4-2", null, null], [1210, "将臣", "「我一般只有放学后才会做一些剑道相关的训练」", null, "街_目抜き通りモブa", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "01"}, "CHAPTER 4-2", null, null], [1211, "蕾娜", "「哇，难道你放学之后，还要做那么高强度的训练吗？」", "len416_023.ogg", "街_目抜き通りモブa", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "34"}, "CHAPTER 4-2", null, null], [1212, "将臣", "「嗯，虽然现在说也晚了，其实你想参观的话，可能放学后来参观比较好……」", null, "街_目抜き通りモブa", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "34"}, "CHAPTER 4-2", null, null], [1213, "将臣", "「当、当然了！你愿意过来给我加油鼓劲，我已经非常开心了」", null, "街_目抜き通りモブa", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "34"}, "CHAPTER 4-2", null, null], [1214, "", "我怎么突然变得这么语无伦次。", null, "街_目抜き通りモブa", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "34"}, "CHAPTER 4-2", null, null], [1215, "", "这简直就像在邀请她约会一样啊。", null, "街_目抜き通りモブa", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "34"}, "CHAPTER 4-2", null, null], [1216, "蕾娜", "「嘿嘿，你能觉得开心的话，我也很高兴！」", "len416_024.ogg", "街_目抜き通りモブa", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02"}, "CHAPTER 4-2", null, null], [1217, "蕾娜", "「不过放学之后……还是得先去忙旅馆的工作，可能走不开」", "len416_025.ogg", "街_目抜き通りモブa", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "29"}, "CHAPTER 4-2", null, null], [1218, "将臣", "「……这样啊，说得也是」", null, "街_目抜き通りモブa", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "29"}, "CHAPTER 4-2", null, null], [1219, "", "咦？为什么我会觉得有点失望？", null, "街_目抜き通りモブa", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "06"}, "CHAPTER 4-2", null, null], [1220, "", "难道，我一直在心里期待着蕾娜放学后也能来参观吗？", null, "街_目抜き通りモブa", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "06"}, "CHAPTER 4-2", null, null], [1221, "蕾娜", "「唉，看不到你练剑道的样子，真是太可惜了……」", "len416_026.ogg", "街_目抜き通りモブa", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "29"}, "CHAPTER 4-2", null, null], [1222, "将臣", "「不不！就我那三脚猫功夫，你也没必要费尽心思过来看的」", null, "街_目抜き通りモブa", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "29"}, "CHAPTER 4-2", null, null], [1223, "将臣", "「说实话，我还从来没有真正击中过外公」", null, "街_目抜き通りモブa", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "34"}, "CHAPTER 4-2", null, null], [1224, "蕾娜", "「哇哦，大当家有那么厉害吗？」", "len416_027.ogg", "街_目抜き通りモブa", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "24"}, "CHAPTER 4-2", null, null], [1225, "将臣", "「何止是厉害，就算是外行也能看出来，他的一招一式根本就不是一般老年人能够做到的」", null, "街_目抜き通りモブa", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "24"}, "CHAPTER 4-2", null, null], [1226, "将臣", "「当然，还是因为我太弱了」", null, "街_目抜き通りモブa", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "24"}, "CHAPTER 4-2", null, null], [1227, "将臣", "「你就算来看，也只能看见我被外公打得毫无招架之力的样子，我都有点不好意思让你看」", null, "街_目抜き通りモブa", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "24"}, "CHAPTER 4-2", null, null], [1228, "蕾娜", "「如果你打不过他的话，反而让我更想给你加油了」", "len416_028.ogg", "街_目抜き通りモブa", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27"}, "CHAPTER 4-2", null, null], [1229, "蕾娜", "「而且我觉得你一点都不弱！你都那么拼命地锻炼了」", "len416_029.ogg", "街_目抜き通りモブa", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "19"}, "CHAPTER 4-2", null, null], [1230, "将臣", "「呃、嗯，谢谢你」", null, "街_目抜き通りモブa", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "19"}, "CHAPTER 4-2", null, null], [1231, "", "听到她这么说，我心里很高兴。", null, "街_目抜き通りモブa", "bgm34.opus", null, "CHAPTER 4-2", null, null], [1232, "", "可问题是，我被打得落花流水并不是我自己谦虚，而是事实如此。", null, "街_目抜き通りモブa", "bgm34.opus", null, "CHAPTER 4-2", null, null], [1233, "心子", "「列支敦瑙尔小姐，你回来了啊」", "mot416_001.ogg", "旅館_旅館前a", "bgm34.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "01"}, "CHAPTER 4-2", null, null], [1234, "蕾娜", "「掌柜的！我来帮忙打扫卫生吧」", "len416_030.ogg", "旅館_旅館前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 4-2", null, null], [1235, "心子", "「那就麻烦你了。适当打扫一下就行，再过一会儿你就该去学校了」", "mot416_002.ogg", "旅館_旅館前a", "bgm34.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "13"}, "CHAPTER 4-2", null, null], [1236, "蕾娜", "「谨遵钧命！」", "len416_031.ogg", "旅館_旅館前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "19"}, "CHAPTER 4-2", null, null], [1237, "心子", "「列支敦瑙尔小姐，你跟我说话没必要用这么夸张的敬语。跟平常一样就可以，不用加一些复杂的东西」", "mot416_003.ogg", "旅館_旅館前a", "bgm34.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "09"}, "CHAPTER 4-2", null, null], [1238, "蕾娜", "「喔、喔……日本的敬语好难啊……」", "len416_032.ogg", "旅館_旅館前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "29"}, "CHAPTER 4-2", null, null], [1239, "", "随后，蕾娜立刻开始打扫正门前的位置。", null, "旅館_旅館前a", "bgm34.opus", null, "CHAPTER 4-2", null, null], [1240, "将臣", "「常陆也来了啊」", null, "旅館_旅館前a", "bgm34.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "01"}, "CHAPTER 4-2", null, null], [1241, "茉子", "「是的，你怎么也来了，我还以为观察蕾娜的状况是我的任务呢」", "mak416_001.ogg", "旅館_旅館前a", "bgm34.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "49"}, "CHAPTER 4-2", null, null], [1242, "将臣", "「是这样的，她对剑道比较感兴趣，今天早上去参观我训练了」", null, "旅館_旅館前a", "bgm34.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "49"}, "CHAPTER 4-2", null, null], [1243, "将臣", "「我顺便就把她送回来了」", null, "旅館_旅館前a", "bgm34.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "49"}, "CHAPTER 4-2", null, null], [1244, "茉子", "「她对剑道感兴趣吗？」", "mak416_002.ogg", "旅館_旅館前a", "bgm34.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "03"}, "CHAPTER 4-2", null, null], [1245, "将臣", "「嗯？外国人对剑道感兴趣很正常吧」", null, "旅館_旅館前a", "bgm34.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "03"}, "CHAPTER 4-2", null, null], [1246, "茉子", "「哈哈，我只是在想，她真正感兴趣的到底是剑道还是别的」", "mak416_003.ogg", "旅館_旅館前a", "bgm34.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "31"}, "CHAPTER 4-2", null, null], [1247, "将臣", "「……什么意思啊？」", null, "旅館_旅館前a", "bgm34.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "31"}, "CHAPTER 4-2", null, null], [1248, "茉子", "「没事没事，没什么特别的意思」", "mak416_004.ogg", "旅館_旅館前a", "bgm34.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "25"}, "CHAPTER 4-2", null, null], [1249, "蕾娜", "「将臣！茉子也在？那咱们待会学校见」", "len416_033.ogg", "旅館_旅館前a", "bgm34.opus", null, "CHAPTER 4-2", null, null], [1250, "将臣", "「啊，好的」", null, "旅館_旅館前a", "bgm34.opus", null, "CHAPTER 4-2", null, null], [1251, "", "虽然很在意常陆说的那些话，不过我也该回去收拾一下准备上学了。", null, "旅館_旅館前a", "bgm34.opus", null, "CHAPTER 4-2", null, null], [1252, "将臣", "「那一会儿学校见！蕾娜也注意别忘带东西了」", null, "旅館_旅館前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "01"}, "CHAPTER 4-2", null, null], [1253, "蕾娜", "「好嘞，有供无鬼嘛！」", "len416_034.ogg", "旅館_旅館前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "24"}, "CHAPTER 4-2", null, null], [1254, "心子", "「……啊？」", "mot416_004.ogg", "旅館_旅館前a", "bgm34.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "05"}, "CHAPTER 4-2", null, null], [1255, "将臣", "「你是想说，有备无患？」", null, "旅館_旅館前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 4-2", null, null], [1256, "蕾娜", "「啊！对，就是这个！应该是有备无患」", "len416_035.ogg", "旅館_旅館前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "19"}, "CHAPTER 4-2", null, null], [1257, "将臣", "「这就对了」", null, "旅館_旅館前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "19"}, "CHAPTER 4-2", null, null], [1258, "心子", "「……」", "mot416_005.ogg", "旅館_旅館前a", "bgm34.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "15"}, "CHAPTER 4-2", null, null], [1259, "茉子", "「这你都能立刻反应过来呀」", "mak416_005.ogg", "旅館_旅館前a", "bgm34.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "03"}, "CHAPTER 4-2", null, null], [1260, "将臣", "「有那么难吗？」", null, "旅館_旅館前a", "bgm34.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "03"}, "CHAPTER 4-2", null, null], [1261, "茉子", "「毕竟她连用法也搞错了」", "mak416_006.ogg", "旅館_旅館前a", "bgm34.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "38"}, "CHAPTER 4-2", null, null], [1262, "", "其实，主要还是因为她早上也把备用品说成了供品，所以我才能立刻明白过来。", null, "旅館_旅館前a", "bgm34.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "38"}, "CHAPTER 4-2", null, null], [1263, "", "就在我正准备离开志那都庄的时候――", null, "旅館_旅館前a", "bgm34.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "38"}, "CHAPTER 4-2", null, null], [1264, "心子", "「将臣少爷，请留步！能耽误您一点时间吗？」", "mot416_006.ogg", "旅館_旅館前a", "bgm34.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "07"}, "CHAPTER 4-2", null, null], [1265, "将臣", "「呃，有什么事吗？」", null, "旅館_旅館前a", "bgm34.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "07"}, "CHAPTER 4-2", null, null], [1266, "", "猪谷阿姨竟然有事情找我，还真是意外。", null, "旅館_旅館前a", "bgm34.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "07"}, "CHAPTER 4-2", null, null], [1267, "心子", "「是这样的，我有一个不情之请，能拜托您吗？」", "mot416_007.ogg", "旅館_旅館前a", "bgm34.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "13"}, "CHAPTER 4-2", null, null], [1268, "将臣", "「需要我帮忙？」", null, "旅館_旅館前a", "bgm34.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "13"}, "CHAPTER 4-2", null, null], [1269, "", "这真是意外中的意外。", null, "旅館_旅館前a", "bgm34.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "13"}, "CHAPTER 4-2", null, null], [1270, "蕾娜", "「哇哦，就连掌柜的也这么器重将臣！」", "len416_036.ogg", "旅館_旅館前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 4-2", null, null], [1271, "将臣", "「不，这是猪谷阿姨头一次找我帮忙……请问，是什么事需要我帮忙呢？」", null, "旅館_旅館前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 4-2", null, null], [1272, "将臣", "「只要是我能帮的我一定帮」", null, "旅館_旅館前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 4-2", null, null], [1273, "心子", "「是这样的，这事和列支敦瑙尔小姐有关」", "mot416_008.ogg", "旅館_旅館前a", "bgm34.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "07"}, "CHAPTER 4-2", null, null], [1274, "蕾娜", "「和我有关？」", "len416_037.ogg", "旅館_旅館前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "04"}, "CHAPTER 4-2", null, null], [1275, "茉子", "「原来如此，我懂了」", "mak416_007.ogg", "旅館_旅館前a", "bgm34.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "01"}, "CHAPTER 4-2", null, null], [1276, "将臣", "「常陆，你知道是怎么回事吗？」", null, "旅館_旅館前a", "bgm34.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "01"}, "CHAPTER 4-2", null, null], [1277, "茉子", "「没有没有，你先听猪谷阿姨说吧」", "mak416_008.ogg", "旅館_旅館前a", "bgm34.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "01"}, "CHAPTER 4-2", null, null], [1278, "", "说得也是。", null, "旅館_旅館前a", "bgm34.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "01"}, "CHAPTER 4-2", null, null], [1279, "心子", "「将臣少爷，常陆小姐，你们都是列支敦瑙尔小姐的同班同学吧？」", "mot416_009.ogg", "旅館_旅館前a", "bgm34.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "15"}, "CHAPTER 4-2", null, null], [1280, "心子", "「我想拜托你们在学校的时候，能教列支敦瑙尔小姐一些日本的常识」", "mot416_010.ogg", "旅館_旅館前a", "bgm34.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "09"}, "CHAPTER 4-2", null, null], [1281, "蕾娜", "「哇啊！？掌……掌柜的，我又做、做错什么事了吗？」", "len416_038.ogg", "旅館_旅館前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "06"}, "CHAPTER 4-2", null, null], [1282, "心子", "「虽然列支敦瑙尔小姐的悟性并不算特别优秀」", "mot416_011.ogg", "旅館_旅館前a", "bgm34.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "14"}, "CHAPTER 4-2", null, null], [1283, "心子", "「但是你坚持学习，努力纠正错误的态度还是很值得肯定的」", "mot416_012.ogg", "旅館_旅館前a", "bgm34.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "01"}, "CHAPTER 4-2", null, null], [1284, "蕾娜", "「是、是这样吗？说得我有点不好意思……多谢掌柜的夸奖！」", "len416_039.ogg", "旅館_旅館前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "19"}, "CHAPTER 4-2", null, null], [1285, "心子", "「但是，我话还没有说完」", "mot416_013.ogg", "旅館_旅館前a", "bgm34.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "09"}, "CHAPTER 4-2", null, null], [1286, "心子", "「每次我纠正她一处，过不了多久她又会不知从哪学来一些别的错误用法，这个你们应该也能感觉到吧？」", "mot416_014.ogg", "旅館_旅館前a", "bgm34.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "07"}, "CHAPTER 4-2", null, null], [1287, "心子", "「而且……不知道为什么，她经常把一些旅馆比较忌讳的词语学过来」", "mot416_015.ogg", "旅館_旅館前a", "bgm34.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "09"}, "CHAPTER 4-2", null, null], [1288, "茉子", "「她刚才说到的“供品”和“鬼魂”，确实不应该在旅馆乱说」", "mak416_009.ogg", "旅館_旅館前a", "bgm34.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "35"}, "CHAPTER 4-2", null, null], [1289, "将臣", "「也是，年代久远的旅馆很容易给人一种闹鬼的印象」", null, "旅館_旅館前a", "bgm34.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "35"}, "CHAPTER 4-2", null, null], [1290, "蕾娜", "「喔、喔……真的很抱歉」", "len416_040.ogg", "旅館_旅館前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "12"}, "CHAPTER 4-2", null, null], [1291, "", "蕾娜一下子蔫了下去。", null, "旅館_旅館前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "12"}, "CHAPTER 4-2", null, null], [1292, "将臣", "「不过，常识这个东西，我也不确定自己能不能教好」", null, "旅館_旅館前a", "bgm34.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "09"}, "CHAPTER 4-2", null, null], [1293, "心子", "「没关系，你们平时在学校帮我留个心就行了」", "mot416_016.ogg", "旅館_旅館前a", "bgm34.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "13"}, "CHAPTER 4-2", null, null], [1294, "心子", "「而且，如果将臣少爷能亲自帮她纠正，应该比我说的效果更好」", "mot416_017.ogg", "旅館_旅館前a", "bgm34.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "03"}, "CHAPTER 4-2", null, null], [1295, "将臣", "「哎？真的吗？」", null, "旅館_旅館前a", "bgm34.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "03"}, "CHAPTER 4-2", null, null], [1296, "心子", "「您刚才帮她纠正了一下，她不是立刻就记住了吗？」", "mot416_018.ogg", "旅館_旅館前a", "bgm34.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "01"}, "CHAPTER 4-2", null, null], [1297, "心子", "「要是我的话，指不定得说多少次呢」", "mot416_019.ogg", "旅館_旅館前a", "bgm34.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "13"}, "CHAPTER 4-2", null, null], [1298, "", "说起来，我以前好像见过这一幕。", null, "旅館_旅館前a", "bgm34.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "13"}, "CHAPTER 4-2", null, null], [1299, "将臣", "「不过，刚才那个应该只是巧合吧？」", null, "旅館_旅館前a", "bgm34.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "13"}, "CHAPTER 4-2", null, null], [1300, "蕾娜", "「谁、谁知道呢？好像是巧合……又好像不是巧合……」", "len416_041.ogg", "旅館_旅館前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "12"}, "CHAPTER 4-2", null, null], [1301, "蕾娜", "「不对！刚才肯定不是巧合」", "len416_042.ogg", "旅館_旅館前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02"}, "CHAPTER 4-2", null, null], [1302, "将臣", "「真的吗？」", null, "旅館_旅館前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02"}, "CHAPTER 4-2", null, null], [1303, "蕾娜", "「是的。我觉得，因为那是你说的……所以我记起来才会更容易一些」", "len416_043.ogg", "旅館_旅館前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02"}, "CHAPTER 4-2", null, null], [1304, "", "我怎么感觉谁说都一样。也罢，不纠结了。", null, "旅館_旅館前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02"}, "CHAPTER 4-2", null, null], [1305, "将臣", "「我明白了，如果发现问题了，我会及时跟她说的」", null, "旅館_旅館前a", "bgm34.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "01"}, "CHAPTER 4-2", null, null], [1306, "心子", "「可以麻烦您吗？」", "mot416_020.ogg", "旅館_旅館前a", "bgm34.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "02"}, "CHAPTER 4-2", null, null], [1307, "将臣", "「嗯，毕竟蕾娜在我训练的时候也给我帮过忙」", null, "旅館_旅館前a", "bgm34.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "01"}, "CHAPTER 4-2", null, null], [1308, "", "志那都庄允许她离开岗位过来给我帮忙，那我也应该有所报答才对。", null, "旅館_旅館前a", "bgm34.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "01"}, "CHAPTER 4-2", null, null], [1309, "", "而且，这点小忙也不算什么。", null, "旅館_旅館前a", "bgm34.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "01"}, "CHAPTER 4-2", null, null], [1310, "心子", "「那我也就不跟您客气了，以后就麻烦您费心了」", "mot416_021.ogg", "旅館_旅館前a", "bgm34.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "01"}, "CHAPTER 4-2", null, null], [1311, "蕾娜", "「嘿嘿，将臣，以后在学校里也请多指教了」", "len416_044.ogg", "旅館_旅館前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02"}, "CHAPTER 4-2", null, null], [1312, "将臣", "「你就放心吧，蕾娜！」", null, "旅館_旅館前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02"}, "CHAPTER 4-2", null, null], [1313, "", "答应了猪谷阿姨的请求之后，我们离开了志那都庄。", null, "旅館_旅館前a", "bgm34.opus", null, "CHAPTER 4-2", null, null], [1314, "茉子", "「哈哈，你答应得可真干脆啊」", "mak416_010.ogg", "街_目抜き通りモブa", "bgm34.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "46"}, "CHAPTER 4-2", null, null], [1315, "将臣", "「是吗？应该没那么麻烦吧？」", null, "街_目抜き通りモブa", "bgm34.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "46"}, "CHAPTER 4-2", null, null], [1316, "将臣", "「虽然我还没有想好到底要怎么教」", null, "街_目抜き通りモブa", "bgm34.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "43"}, "CHAPTER 4-2", null, null], [1317, "茉子", "「也就是说，你这边并没有什么别的想法？」", "mak416_011.ogg", "街_目抜き通りモブa", "bgm34.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "03"}, "CHAPTER 4-2", null, null], [1318, "将臣", "「别的想法？……这个嘛，也算是为了感谢她吧」", null, "街_目抜き通りモブa", "bgm34.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "03"}, "CHAPTER 4-2", null, null], [1319, "茉子", "「咦，你是真的没有注意到吗？」", "mak416_012.ogg", "街_目抜き通りモブa", "bgm34.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "49"}, "CHAPTER 4-2", null, null], [1320, "茉子", "「还是说你已经注意到了，但是故意装傻？蕾娜也真是不容易啊」", "mak416_013.ogg", "街_目抜き通りモブa", "bgm34.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "38"}, "CHAPTER 4-2", null, null], [1321, "将臣", "「我说常陆啊，你是不是误会了什么？」", null, "街_目抜き通りモブa", "bgm34.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "38"}, "CHAPTER 4-2", null, null], [1322, "茉子", "「嘿嘿，反正，你是真的接手了一件苦差事」", "mak416_014.ogg", "街_目抜き通りモブa", "bgm34.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "27"}, "CHAPTER 4-2", null, null], [1323, "将臣", "「你可别吓我」", null, "街_目抜き通りモブa", "bgm34.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "27"}, "CHAPTER 4-2", null, null], [1324, "将臣", "「还是说，你知道一些我不了解的情况？」", null, "街_目抜き通りモブa", "bgm34.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "27"}, "CHAPTER 4-2", null, null], [1325, "茉子", "「哈哈，看来，得先让你实际感受一下才行」", "mak416_015.ogg", "街_目抜き通りモブa", "bgm34.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "23"}, "CHAPTER 4-2", null, null], [1326, "茉子", "「机会难得，要不我们多叫几个人一起来帮忙吧？」", "mak416_016.ogg", "街_目抜き通りモブa", "bgm34.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "26"}, "CHAPTER 4-2", null, null], [1327, "将臣", "「呃……嗯，也行吧」", null, "街_目抜き通りモブa", "bgm34.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "26"}, "CHAPTER 4-2", null, null], [1328, "", "反正，常陆肯定是嘴上说得比较夸张而已吧。", null, "街_目抜き通りモブa", "bgm34.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "01"}, "CHAPTER 4-2", null, null], [1329, "", "只是教教常识而已，还能有多辛苦。", null, "街_目抜き通りモブa", "bgm34.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "01"}, "CHAPTER 4-2", null, null], [1330, "茉子", "「我看看，大家都到齐了吧？」", "mak416_017.ogg", "学院_教室休憩a", "bgm25.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "25"}, "CHAPTER 4-2", null, null], [1331, "蕾娜", "「大家都到齐了！」", "len416_045.ogg", "学院_教室休憩a", "bgm25.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 4-2", null, null], [1332, "", "午餐结束后，我让平时聚在一起吃饭的成员们再多留一会儿。", null, "学院_教室休憩a", "bgm25.opus", null, "CHAPTER 4-2", null, null], [1333, "", "遗憾的是，小野同学和柳生同学好像都有事要办。", null, "学院_教室休憩a", "bgm25.opus", null, "CHAPTER 4-2", null, null], [1334, "芳乃", "「是的，我听说你们想商量一些关于蕾娜的事」", "yos416_001.ogg", "学院_教室休憩a", "bgm25.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "17"}, "CHAPTER 4-2", null, null], [1335, "芳乃", "「难道是出了什么问题吗？」", "yos416_002.ogg", "学院_教室休憩a", "bgm25.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "30"}, "CHAPTER 4-2", null, null], [1336, "茉子", "「要说问题，这或许也算是问题吧」", "mak416_018.ogg", "学院_教室休憩a", "bgm25.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "07"}, "CHAPTER 4-2", null, null], [1337, "小春", "「那、那个，该不会是比较麻烦的问题？我待在这里没问题吗？」", "koh416_001.ogg", "学院_教室休憩a", "bgm25.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "29"}, "CHAPTER 4-2", null, null], [1338, "廉太郎", "「应该没问题吧？我这不也在吗，他们也没赶我走」", "ren416_001.ogg", "学院_教室休憩a", "bgm25.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "01"}, "CHAPTER 4-2", null, null], [1339, "小春", "「……确实。如果廉哥都能参与的话，那我应该也没问题吧？」", "koh416_002.ogg", "学院_教室休憩a", "bgm25.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "01"}, "CHAPTER 4-2", null, null], [1340, "蕾娜", "「当然没问题了！我希望你们都能参加的，这对我来说更有帮助」", "len416_046.ogg", "学院_教室休憩a", "bgm25.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "24"}, "CHAPTER 4-2", null, null], [1341, "将臣", "「那常陆，接下来怎么办？是你说要找大家帮忙来着」", null, "学院_教室休憩a", "bgm25.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "01"}, "CHAPTER 4-2", null, null], [1342, "将臣", "「可你到底要让大家怎么帮忙啊？」", null, "学院_教室休憩a", "bgm25.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "01"}, "CHAPTER 4-2", null, null], [1343, "茉子", "「那么，接下来——」", "mak416_019.ogg", "学院_教室休憩a", "bgm25.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "41"}, "CHAPTER 4-2", null, null], [1344, "", "常陆拍了拍桌子，摆出了一副十分正经的模样。", null, "学院_教室休憩a", "bgm25.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "41"}, "CHAPTER 4-2", null, null], [1345, "茉子", "「我宣布，第一届“蕾娜·列支敦瑙尔对日本之误会何其多研讨大会”正式开始」", "mak416_020.ogg", "学院_教室休憩a", "bgm26.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "41"}, "CHAPTER 4-2", null, null], [1346, "蕾娜", "「好的，拜托各位了！」", "len416_047.ogg", "学院_教室休憩a", "bgm26.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 4-2", null, null], [1347, "将臣", "「……」", null, "学院_教室休憩a", "bgm26.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 4-2", null, null], [1348, "", "这、这样的命名，真的没问题吗？", null, "学院_教室休憩a", "bgm44.opus", null, "CHAPTER 4-2", null, null], [1349, "", "也罢，反正本人看上去都不在意，我就不吐槽了。", null, "学院_教室休憩a", "bgm44.opus", null, "CHAPTER 4-2", null, null], [1350, "茉子", "「那首先，会议的主旨可不可以麻烦有地说明一下？」", "mak416_021.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "01"}, "CHAPTER 4-2", null, null], [1351, "将臣", "「哎？喔，行吧……反正本来也是我该做的事」", null, "学院_教室休憩a", "bgm44.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "01"}, "CHAPTER 4-2", null, null], [1352, "将臣", "「是这样的，志那都庄的老板娘，猪谷阿姨拜托我教蕾娜一些日本的常识」", null, "学院_教室休憩a", "bgm44.opus", null, "CHAPTER 4-2", null, null], [1353, "廉太郎", "「啊，原来如此」", "ren416_002.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "31"}, "CHAPTER 4-2", null, null], [1354, "将臣", "「嗯。提议开会讨论的是常陆……不过她说的有道理，只有我一个人的话，很难判断哪些才是常识」", null, "学院_教室休憩a", "bgm44.opus", null, "CHAPTER 4-2", null, null], [1355, "将臣", "「如果各位都能给一些意见，那是最好的」", null, "学院_教室休憩a", "bgm44.opus", null, "CHAPTER 4-2", null, null], [1356, "", "人越多，就越容易判断哪些是常识，这是不言而喻的。", null, "学院_教室休憩a", "bgm44.opus", null, "CHAPTER 4-2", null, null], [1357, "蕾娜", "「是的，我也希望大家可以帮帮忙！你们看可以吗？」", "len416_048.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 4-2", null, null], [1358, "芳乃", "「当然了，这点事不算什么。不过，要、要教常识吗？我、我可以教吗？」", "yos416_003.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "07"}, "CHAPTER 4-2", null, null], [1359, "茉子", "「哈哈，只要您别突然说什么请多几教，那就没问题」", "mak416_022.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "25"}, "CHAPTER 4-2", null, null], [1360, "小春", "「哈哈哈哈，都这年代了，谁还会说那种词语呀」", "koh416_003.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "26"}, "CHAPTER 4-2", null, null], [1361, "芳乃", "「是、是啊……我当然知道……不要再提了，呜呜」", "yos416_004.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "31h"}, "CHAPTER 4-2", null, null], [1362, "芳乃", "「我也会认真参与的，就当是给自己上一课」", "yos416_005.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "09"}, "CHAPTER 4-2", null, null], [1363, "蕾娜", "「嗯？……嗯，咱们一起认真学习吧，芳乃！」", "len416_049.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 4-2", null, null], [1364, "将臣", "「不过常识这个东西，还是太宽泛了，到底该从哪说起比较好啊……」", null, "学院_教室休憩a", "bgm44.opus", null, "CHAPTER 4-2", null, null], [1365, "茉子", "「这个你就交给我吧」", "mak416_023.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "25"}, "CHAPTER 4-2", null, null], [1366, "", "不知为何，常陆一副干劲十足的样子。", null, "学院_教室休憩a", "bgm44.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "25"}, "CHAPTER 4-2", null, null], [1367, "", "她竟然还准备了一块牌子。", null, "学院_教室休憩a", "bgm44.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "25"}, "CHAPTER 4-2", null, null], [1368, "茉子", "「值得纪念的第一次会议，主题就是它了」", "mak416_024.ogg", "学院_教室休憩a", "bgm21.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "02"}, "CHAPTER 4-2", null, null], [1369, "", "牌子上写着“相扑”几个字。", null, "学院_教室休憩a", "bgm21.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "23"}, "CHAPTER 4-2", null, null], [1370, "蕾娜", "「哇——！相扑，我超喜欢！」", "len416_050.ogg", "学院_教室休憩a", "bgm21.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 4-2", null, null], [1371, "将臣", "「原来你知道相扑啊」", null, "学院_教室休憩a", "bgm21.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 4-2", null, null], [1372, "廉太郎", "「知道很正常吧？相扑在国外也很有名啊」", "ren416_003.ogg", "学院_教室休憩a", "bgm21.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "01"}, "CHAPTER 4-2", null, null], [1373, "蕾娜", "「是的！我们阖家上下都非常喜欢相扑」", "len416_051.ogg", "学院_教室休憩a", "bgm21.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 4-2", null, null], [1374, "芳乃", "「茉子，你这个主题是不是选得不太好啊？」", "yos416_006.ogg", "学院_教室休憩a", "bgm21.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "30"}, "CHAPTER 4-2", null, null], [1375, "茉子", "「是吗？蕾娜，能请你给大家说明一下什么是相扑吗？」", "mak416_025.ogg", "学院_教室休憩a", "bgm21.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "25"}, "CHAPTER 4-2", null, null], [1376, "蕾娜", "「好的！所谓的相扑，就是两个胖乎乎的裸体摔跤手在台上展开疯狂大战的日本特色运动，没错吧」", "len416_052.ogg", "学院_教室休憩a", "bgm21.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "25"}, "CHAPTER 4-2", null, null], [1377, "芳乃", "「……？」", "yos416_007.ogg", "学院_教室休憩a", "bgm21.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "26"}, "CHAPTER 4-2", null, null], [1378, "小春", "「呃，这个……」", "koh416_004.ogg", "学院_教室休憩a", "bgm21.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "15"}, "CHAPTER 4-2", null, null], [1379, "", "怎么说呢？有点不知道说什么好。", null, "学院_教室休憩a", "bgm21.opus", null, "CHAPTER 4-2", null, null], [1380, "将臣", "「大致是那么回事，但是总感觉不太对劲。难道只有我一个人这么想吗？」", null, "学院_教室休憩a", "bgm21.opus", null, "CHAPTER 4-2", null, null], [1381, "廉太郎", "「好巧啊。其实我也是这么想的」", "ren416_004.ogg", "学院_教室休憩a", "bgm21.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "16"}, "CHAPTER 4-2", null, null], [1382, "小春", "「是不是……外国人都觉得相扑看上去很疯狂？」", "koh416_005.ogg", "学院_教室休憩a", "bgm21.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "24"}, "CHAPTER 4-2", null, null], [1383, "将臣", "「确实，在国外，那种胖乎乎的身材，以及男人露出屁股的打扮，好像都很难留下什么好印象」", null, "学院_教室休憩a", "bgm21.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "24"}, "CHAPTER 4-2", null, null], [1384, "芳乃", "「相扑本来是从某种祭神仪式演变而来的……外国人真那么想的话，感觉有点受打击」", "yos416_008.ogg", "学院_教室休憩a", "bgm21.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "30"}, "CHAPTER 4-2", null, null], [1385, "廉太郎", "「原来是这样！仔细想想也是啊，相扑确实有点仪式感在里面」", "ren416_005.ogg", "学院_教室休憩a", "bgm21.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "01"}, "CHAPTER 4-2", null, null], [1386, "小春", "「廉哥，你以前都不知道的吗？」", "koh416_006.ogg", "学院_教室休憩a", "bgm21.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "04"}, "CHAPTER 4-2", null, null], [1387, "", "……我也不知道。", null, "学院_教室休憩a", "bgm21.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "04"}, "CHAPTER 4-2", null, null], [1388, "蕾娜", "「哇哦，祭神仪式……原来相扑还具有宗教含义呀！？真是长见识了」", "len416_053.ogg", "学院_教室休憩a", "bgm21.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "18"}, "CHAPTER 4-2", null, null], [1389, "将臣", "「嗯、嗯。不过，蕾娜」", null, "学院_教室休憩a", "bgm21.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 4-2", null, null], [1390, "将臣", "「为什么你会说是“疯狂大战”呢？虽然确实是在打斗」", null, "学院_教室休憩a", "bgm21.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 4-2", null, null], [1391, "", "身为日本人，我还是想确认一下。", null, "学院_教室休憩a", "bgm21.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 4-2", null, null], [1392, "蕾娜", "「哈哈哈，将臣你可是日本人，难道连这都不知道吗？」", "len416_054.ogg", "学院_教室休憩a", "bgm21.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 4-2", null, null], [1393, "蕾娜", "「相扑比赛之前，日本人肯定会说“发狂”这两个字嘛」", "len416_055.ogg", "学院_教室休憩a", "bgm21.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 4-2", null, null], [1394, "将臣", "「哎？」", null, "学院_教室休憩a", "bgm21.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 4-2", null, null], [1395, "", "我忍不住望了望大家。然而朝武正斜着脑袋沉思，廉太郎和小春则是面面相觑。", null, "学院_教室休憩a", "bgm21.opus", null, "CHAPTER 4-2", null, null], [1396, "", "唯独常陆面无表情地观察着大家的反应。", null, "学院_教室休憩a", "bgm21.opus", null, "CHAPTER 4-2", null, null], [1397, "蕾娜", "「嗯？相扑不就是这样的吗？」", "len416_056.ogg", "学院_教室休憩a", "bgm21.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "30"}, "CHAPTER 4-2", null, null], [1398, "", "蕾娜摆出了类似相扑裁判的姿势。", null, "学院_教室休憩a", "bgm21.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 4-2", null, null], [1399, "", "她模仿得还挺像的。", null, "学院_教室休憩a", "bgm21.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 4-2", null, null], [1400, "蕾娜", "「比赛前，裁判会像这样……」", "len416_057.ogg", "学院_教室休憩a", "bgm21.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "15"}, "CHAPTER 4-2", null, null], [1401, "蕾娜", "「发狂————生气啦，生气啦……生气啦，生气啦！」", "len416_058.ogg", "学院_教室休憩a", "bgm22.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "16"}, "CHAPTER 4-2", null, null], [1402, "", "蕾娜是想还原裁判的动作吗？", null, "学院_教室休憩a", "bgm22.opus", null, "CHAPTER 4-2", null, null], [1403, "", "她一边左右横跳，一边说着刚才那句话。", null, "学院_教室休憩a", "bgm22.opus", null, "CHAPTER 4-2", null, null], [1404, "蕾娜", "「生气啦，生气啦……！」", "len416_059.ogg", "学院_教室休憩a", "bgm22.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "16"}, "CHAPTER 4-2", null, null], [1405, "廉太郎", "「……」", "ren416_006.ogg", "学院_教室休憩a", "bgm22.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "10"}, "CHAPTER 4-2", null, null], [1406, "蕾娜", "「……生气啦，生气啦……！」", "len416_060.ogg", "学院_教室休憩a", "bgm22.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "16"}, "CHAPTER 4-2", null, null], [1407, "小春", "「～～～」", "koh416_007.ogg", "学院_教室休憩a", "bgm22.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "08"}, "CHAPTER 4-2", null, null], [1408, "芳乃・廉太郎・小春", "『（这也太扯了）』", "yos416_009.ogg", "学院_教室休憩a", "bgm22.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "11"}, "CHAPTER 4-2", null, null], [1409, "", "这裁判是成心煽风点火吗！！", null, "学院_教室休憩a", "bgm22.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "11"}, "CHAPTER 4-2", null, null], [1410, "", "她难道以为，相扑运动员都是靠发狂获取怒气能量来战斗的吗？", null, "学院_教室休憩a", "bgm22.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "11"}, "CHAPTER 4-2", null, null], [1411, "茉子", "「我先说明一下，不是“发狂”，而是“Ｈａｋｋｅｙｏｉ”。“生气啦”也不对，应该是“Ｎｏｋｏｔｔａ”」", "mak416_026.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "25"}, "CHAPTER 4-2", null, null], [1412, "", "常陆同学在这种情况下依然面不改色地讲解着正确的相扑知识。", null, "学院_教室休憩a", "bgm44.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "25"}, "CHAPTER 4-2", null, null], [1413, "蕾娜", "「是Ｈａｋｋｅｙｏｉ吗？哇喔，我还没听说过这个单词。将臣，你知道是什么意思吗？」", "len416_061.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 4-2", null, null], [1414, "将臣", "「我？……我觉得应该没什么意思，就是单纯的吆喝声吧」", null, "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 4-2", null, null], [1415, "芳乃", "「当然是有含义的，你说是不是，茉子」", "yos416_010.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "02"}, "CHAPTER 4-2", null, null], [1416, "茉子", "「是的，Ｈａｋｋｅｙｏｉ，是由“发挥扬扬”这个日语词汇演变而来的，目的在于鼓舞士气，让双方全力应战」", "mak416_027.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "28"}, "CHAPTER 4-2", null, null], [1417, "茉子", "「用现在的话来说，有点类似于“撸起袖子一起加油吧”」", "mak416_028.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "01"}, "CHAPTER 4-2", null, null], [1418, "芳乃", "「而“Ｎｏｋｏｔｔａ、Ｎｏｋｏｔｔａ”，意思就是胜负未分，两位继续加油」", "yos416_011.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "02"}, "CHAPTER 4-2", null, null], [1419, "廉太郎", "「原来如此，我觉得就算是日本人恐怕也很少知道这些」", "ren416_008.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "01"}, "CHAPTER 4-2", null, null], [1420, "将臣", "「嗯，我还是第一次知道日语有“发挥扬扬”这个词」", null, "学院_教室休憩a", "bgm44.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "04"}, "CHAPTER 4-2", null, null], [1421, "小春", "「感觉我们才是真正受教的一方」", "koh416_009.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "13"}, "CHAPTER 4-2", null, null], [1422, "蕾娜", "「哈哈，原来我不是一个人，有点放心了」", "len416_062.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "23"}, "CHAPTER 4-2", null, null], [1423, "蕾娜", "「我在电视上看过很多次相扑比赛，但一直想不通为什么要让选手发狂」", "len416_063.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 4-2", null, null], [1424, "将臣", "「原来你也感觉到不对劲了啊」", null, "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 4-2", null, null], [1425, "蕾娜", "「是的，我还以为他们跟我们国家的狂战士差不多呢」", "len416_064.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "21"}, "CHAPTER 4-2", null, null], [1426, "", "啊，狂战士也是北欧的吗？", null, "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "21"}, "CHAPTER 4-2", null, null], [1427, "将臣", "「总之，误会消除了就行」", null, "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "21"}, "CHAPTER 4-2", null, null], [1428, "蕾娜", "「嗯！今天学到了很多以前不知道的相扑知识，我很满足」", "len416_065.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 4-2", null, null], [1429, "", "我们确实也长了知识，但是……", null, "学院_教室休憩a", "bgm44.opus", null, "CHAPTER 4-2", null, null], [1430, "", "我有种预感，到了明天恐怕我们只会记得“发狂生气啦”的部分。但愿是我多虑了吧。", null, "学院_教室休憩a", "bgm44.opus", null, "CHAPTER 4-2", null, null], [1431, "蕾娜", "「谢谢你，将臣！今天我学到了不少」", "len416_066.ogg", "街_通学路a", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 4-2", null, null], [1432, "将臣", "「不客气，其实我什么都没做」", null, "街_通学路a", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 4-2", null, null], [1433, "", "放学后，我一路送蕾娜回志那都庄。", null, "街_通学路a", "bgm35.opus", null, "CHAPTER 4-2", null, null], [1434, "", "目前，她的身体状况看上去并无大碍，但她毕竟吸收了那么多碎片。", null, "街_通学路a", "bgm35.opus", null, "CHAPTER 4-2", null, null], [1435, "", "以防万一，还是尽量待在她身边比较好。", null, "街_通学路a", "bgm35.opus", null, "CHAPTER 4-2", null, null], [1436, "将臣", "「先不说这个，蕾娜，你身体没问题吧？」", null, "街_通学路a", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 4-2", null, null], [1437, "将臣", "「驹川大夫也说了，哪怕有一点点情况，也要及时说出来」", null, "街_通学路a", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 4-2", null, null], [1438, "蕾娜", "「我没事的，说不定以后也不会出什么问题啦」", "len416_067.ogg", "街_通学路a", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 4-2", null, null], [1439, "将臣", "「是吗，但千万不要大意啊」", null, "街_通学路a", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 4-2", null, null], [1440, "蕾娜", "「明白，身体不适的话我会立刻告诉你们的！但你也别忘了自己哦，你的身体没大碍吧？」", "len416_068.ogg", "街_通学路a", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 4-2", null, null], [1441, "将臣", "「呃，你是说我身上的伤？我觉得还好吧……」", null, "街_通学路a", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 4-2", null, null], [1442, "蕾娜", "「那些伤也挺让人担心的，不过我指的是身体吸收碎片的事，这一点你也跟我一样吧？」", "len416_069.ogg", "街_通学路a", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "06"}, "CHAPTER 4-2", null, null], [1443, "将臣", "「啊，你是说那个啊……怎么说呢，我吸收的大概只是很小一部分，而且八成是很早以前的事」", null, "街_通学路a", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "06"}, "CHAPTER 4-2", null, null], [1444, "将臣", "「就算身体状况有所变化，我也早就习惯了」", null, "街_通学路a", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 4-2", null, null], [1445, "蕾娜", "「哪怕量很少，在你体内残留的时间也要比我长得多吧？」", "len416_070.ogg", "街_通学路a", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "12"}, "CHAPTER 4-2", null, null], [1446, "蕾娜", "「也就是说，你受到的影响可能比我更大，不是吗？」", "len416_071.ogg", "街_通学路a", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "06"}, "CHAPTER 4-2", null, null], [1447, "将臣", "「这么说的话，好像确实有道理？」", null, "街_通学路a", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "06"}, "CHAPTER 4-2", null, null], [1448, "将臣", "「但我确实没什么异常的感觉」", null, "街_通学路a", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "06"}, "CHAPTER 4-2", null, null], [1449, "蕾娜", "「我也没什么感觉……不过」", "len416_072.ogg", "街_通学路a", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 4-2", null, null], [1450, "", "不知为何，蕾娜看上去有些羞涩。", null, "街_通学路a", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 4-2", null, null], [1451, "蕾娜", "「将臣……你是在担心我吗，害怕我出现什么意外」", "len416_073.ogg", "街_通学路a", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 4-2", null, null], [1452, "将臣", "「哎？呃……嗯，差不多吧，要是你出了什么事，志那都庄肯定也会受到影响的」", null, "街_通学路a", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 4-2", null, null], [1453, "将臣", "「你难得从国外远道而来，我们肯定不希望你留下什么不愉快的回忆」", null, "街_通学路a", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 4-2", null, null], [1454, "", "等等，我干嘛找这么多借口，我在掩饰什么啊。", null, "街_通学路a", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 4-2", null, null], [1455, "将臣", "「总之，什么事都没有肯定是最好的」", null, "街_通学路a", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 4-2", null, null], [1456, "蕾娜", "「嘿嘿……谢谢你，将臣」", "len416_074.ogg", "街_通学路a", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 4-2", null, null], [1457, "蕾娜", "「不过，你真的不用担心我的！倒不如说……现在这样反而更开心」", "len416_075.ogg", "街_通学路a", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "23"}, "CHAPTER 4-2", null, null], [1458, "将臣", "「开心？吸收了碎片很开心吗？」", null, "街_通学路a", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "23"}, "CHAPTER 4-2", null, null], [1459, "将臣", "「也是，毕竟你本来就把碎片当做护身符，觉得开心倒也不难理解」", null, "街_通学路a", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "23"}, "CHAPTER 4-2", null, null], [1460, "蕾娜", "「虽然也有这方面的原因……但主要还是因为，你这么担心我」", "len416_076.ogg", "街_通学路a", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "03"}, "CHAPTER 4-2", null, null], [1461, "", "……哎？", null, "街_通学路a", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "03"}, "CHAPTER 4-2", null, null], [1462, "蕾娜", "「你的身体里有碎片，我的身体里也有碎片……咱们真是难兄难弟呢」", "len416_077.ogg", "街_通学路a", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 4-2", null, null], [1463, "将臣", "「确实……哎？难道你觉得这很开心吗？」", null, "街_通学路a", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 4-2", null, null], [1464, "蕾娜", "「……嗯，可能有点奇怪……但是，能跟你有一些共同点，我就很开心」", "len416_078.ogg", "街_通学路a", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 4-2", null, null], [1465, "", "我是应该提醒她好好认清现实吗？", null, "街_通学路a", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 4-2", null, null], [1466, "", "但是……她愿意这么说，至少说明她并不讨厌我吧？", null, "街_通学路a", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 4-2", null, null], [1467, "", "如果真是这样，那我也挺开心的。", null, "街_通学路a", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 4-2", null, null], [1468, "将臣", "「你、你也真是的，再怎么开心，也要注意身体啊」", null, "街_通学路a", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 4-2", null, null], [1469, "蕾娜", "「你也一样呀，千万要注意身体。你要是出了什么事……那就麻烦了」", "len416_079.ogg", "街_通学路a", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "12"}, "CHAPTER 4-2", null, null], [1470, "将臣", "「这个我知道」", null, "街_通学路a", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "12"}, "CHAPTER 4-2", null, null], [1471, "", "好像每个人都跟我说过类似的话。", null, "街_通学路a", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "12"}, "CHAPTER 4-2", null, null], [1472, "蕾娜", "「唔，你这话好没有说服力呀」", "len416_080.ogg", "街_通学路a", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "09"}, "CHAPTER 4-2", null, null], [1473, "将臣", "「不是吧！？反正，你不用担心我啦，你才是最让人担心的」", null, "街_通学路a", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "09"}, "CHAPTER 4-2", null, null], [1474, "蕾娜", "「不不，你总喜欢把自己的事情放到最后，这一点非常让人不放心」", "len416_081.ogg", "街_通学路a", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "09"}, "CHAPTER 4-2", null, null], [1475, "", "这也太夸张了吧，没想到蕾娜这么担心我。", null, "街_通学路a", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "09"}, "CHAPTER 4-2", null, null], [1476, "蕾娜", "「所以……」", "len416_082.ogg", "街_通学路a", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 4-2", null, null], [1477, "将臣", "「哎？」", null, "街_通学路a", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 4-2", null, null], [1478, "", "突然，蕾娜的手滑进了我的手掌之中。", null, "街_通学路a", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 4-2", null, null], [1479, "蕾娜", "「这……这样一来就放心了」", "len416_083.ogg", "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "22"}, "CHAPTER 4-2", null, null], [1480, "蕾娜", "「就算……突然觉得身体不舒服，也可以马上注意到」", "len416_084.ogg", "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 4-2", null, null], [1481, "将臣", "「啊，嗯，原来如此……哎？」", null, "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 4-2", null, null], [1482, "", "我脑子一片混乱，像个傻子一样慌得连话都不会说了。", null, "街_通学路a", "bgm54.opus", null, "CHAPTER 4-2", null, null], [1483, "", "要、要冷静。", null, "街_通学路a", "bgm54.opus", null, "CHAPTER 4-2", null, null], [1484, "", "外国人比较开放，肢体接触不算什么，我是不是也应该主动握回去？", null, "街_通学路a", "bgm54.opus", null, "CHAPTER 4-2", null, null], [1485, "", "不握回去的话会不会有点失礼……咦？", null, "街_通学路a", "bgm54.opus", null, "CHAPTER 4-2", null, null], [1486, "蕾娜", "「……～～～～～」", "len416_085.ogg", "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "12h"}, "CHAPTER 4-2", null, null], [1487, "", "蕾娜低着头，两颊羞得通红。", null, "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "12h"}, "CHAPTER 4-2", null, null], [1488, "", "她好像确实非常容易害羞，之前只是看了看裸露的图片就羞得整个人怔住了。", null, "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "12h"}, "CHAPTER 4-2", null, null], [1489, "", "那她为什么……等等，我握回去真的没问题吗？", null, "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "12h"}, "CHAPTER 4-2", null, null], [1490, "", "要是我也握紧她的手，很可能就会产生特殊的含义，这让我有些犹豫不决。", null, "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "12h"}, "CHAPTER 4-2", null, null], [1491, "蕾娜", "「嘿嘿，我……我们走吧，将臣」", "len416_086.ogg", "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02h"}, "CHAPTER 4-2", null, null], [1492, "将臣", "「呃、嗯」", null, "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02h"}, "CHAPTER 4-2", null, null], [1493, "", "我们似乎走了很久，又似乎不到片刻。不知不觉中就走到了志那都庄。", null, "旅館_旅館前a", "bgm54.opus", null, "CHAPTER 4-2", null, null], [1494, "蕾娜", "「已……已经到了吗？」", "len416_087.ogg", "旅館_旅館前a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "12"}, "CHAPTER 4-2", null, null], [1495, "将臣", "「好像是的」", null, "旅館_旅館前a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "12"}, "CHAPTER 4-2", null, null], [1496, "", "这一路上，我们并没有谈笑风生，跟平常在一起时并无两样。", null, "旅館_旅館前a", "bgm54.opus", null, "CHAPTER 4-2", null, null], [1497, "", "但尽管如此，我们之间的气氛确实变得比以前更加亲密了。", null, "旅館_旅館前a", "bgm54.opus", null, "CHAPTER 4-2", null, null], [1498, "", "唯一的问题就是，我不知道该在什么时候松开手。", null, "旅館_旅館前a", "bgm54.opus", null, "CHAPTER 4-2", null, null], [1499, "", "话说，我可以主动松手吗？", null, "旅館_旅館前a", "bgm54.opus", null, "CHAPTER 4-2", null, null], [1500, "蕾娜", "「那……那个，将臣？我差不多该去干活了」", "len416_088.ogg", "旅館_旅館前a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "21"}, "CHAPTER 4-2", null, null], [1501, "将臣", "「啊，也是，差点忘了！我接下来也要去训练」", null, "旅館_旅館前a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "21"}, "CHAPTER 4-2", null, null], [1502, "", "到头来，还是慌慌张张地把手松开了。", null, "旅館_旅館前a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "21"}, "CHAPTER 4-2", null, null], [1503, "", "不过——", null, "旅館_旅館前a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "21"}, "CHAPTER 4-2", null, null], [1504, "蕾娜", "「那，我先走了……」", "len416_089.ogg", "旅館_旅館前a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 4-2", null, null], [1505, "将臣", "「哎！？」", null, "旅館_旅館前a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 4-2", null, null], [1506, "", "蕾娜突然张开双臂，向我走了过来。", null, "旅館_旅館前a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 4-2", null, null], [1507, "", "不是吧，她这是要抱上来吗！？", null, "旅館_旅館前a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 4-2", null, null], [1508, "蕾娜", "「啊……喔……差点忘了，在日本说再见的时候不能随便跟人拥抱来着」", "len416_090.ogg", "旅館_旅館前a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 4-2", null, null], [1509, "将臣", "「啊，噢噢，是再见的拥抱啊。原来如此，吓我一跳」", null, "旅館_旅館前a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 4-2", null, null], [1510, "", "刚才她的动作吓得我连忙后仰。", null, "旅館_旅館前a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 4-2", null, null], [1511, "", "看样子，蕾娜是在抱住之前意识到了这个问题。", null, "旅館_旅館前a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 4-2", null, null], [1512, "蕾娜", "「是的，在我们国家，关系亲近的人都会拥抱的」", "len416_091.ogg", "旅館_旅館前a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 4-2", null, null], [1513, "蕾娜", "「刚才一个不注意，差点就抱上去了，抱歉吓到你了」", "len416_092.ogg", "旅館_旅館前a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "28"}, "CHAPTER 4-2", null, null], [1514, "将臣", "「没、没事，我才应该道歉！我没有恶意的」", null, "旅館_旅館前a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "28"}, "CHAPTER 4-2", null, null], [1515, "", "我刚才的反应，可能非常不礼貌。", null, "旅館_旅館前a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 4-2", null, null], [1516, "", "虽然不礼貌，但我本来就答应了要教她日本的常识，刚才的反应说不定正合适？", null, "旅館_旅館前a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 4-2", null, null], [1517, "", "而且她看上去也在克制自己的习惯。", null, "旅館_旅館前a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 4-2", null, null], [1518, "", "不过，如果仅仅只是打招呼的拥抱，应该也没什么……不对！还是不行。毕竟……", null, "旅館_旅館前a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 4-2", null, null], [1519, "", "要是那玩意儿压上来，肯定会一瞬间将我的理智碾得粉碎！！（迫真）", null, "旅館_旅館前a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 4-2", null, null], [1520, "将臣", "「总之，我刚才避开，并不是因为讨厌跟你拥抱！这一点希望你能相信我」", null, "旅館_旅館前a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "34"}, "CHAPTER 4-2", null, null], [1521, "蕾娜", "「那……那你……愿意和我拥抱吗？」", "len416_093.ogg", "旅館_旅館前a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25h"}, "CHAPTER 4-2", null, null], [1522, "将臣", "「哎？等、等、等等，蕾娜！？」", null, "旅館_旅館前a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25h"}, "CHAPTER 4-2", null, null], [1523, "蕾娜", "「还是说……你不太喜欢，和我拥抱吗？」", "len416_094.ogg", "旅館_旅館前a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "06"}, "CHAPTER 4-2", null, null], [1524, "将臣", "「不、不是的！怎么说呢，我只是还没有想好」", null, "旅館_旅館前a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "06"}, "CHAPTER 4-2", null, null], [1525, "", "如果一定要说的话，我当然想拥抱！", null, "旅館_旅館前a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "06"}, "CHAPTER 4-2", null, null], [1526, "", "虽然想抱她，但我毕竟是男人，不可能做到无欲无求的境界，而且我可不希望自己在班上的待遇变得比廉太郎还要差……", null, "旅館_旅館前a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "06"}, "CHAPTER 4-2", null, null], [1527, "心子", "「哎，这不是将臣少爷和列支敦瑙尔小姐吗？」", "mot416_022.ogg", "旅館_旅館前a", "bgm54.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "01"}, "CHAPTER 4-2", null, null], [1528, "将臣", "「哇啊啊！？猪、猪谷阿姨？」", null, "旅館_旅館前a", "bgm54.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "01"}, "CHAPTER 4-2", null, null], [1529, "", "怎么偏偏在这个时候来碍事……不对！不该这么说。她来的正是时候。", null, "旅館_旅館前a", "bgm54.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "01"}, "CHAPTER 4-2", null, null], [1530, "", "真应该谢谢她。", null, "旅館_旅館前a", "bgm54.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "01"}, "CHAPTER 4-2", null, null], [1531, "蕾娜", "「掌、掌柜的！我回来了」", "len416_095.ogg", "旅館_旅館前a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "23"}, "CHAPTER 4-2", null, null], [1532, "心子", "「欢迎回来。你们今天在学校过得怎么样？」", "mot416_023.ogg", "旅館_旅館前a", "bgm54.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "01"}, "CHAPTER 4-2", null, null], [1533, "将臣", "「挺，挺好的，今天我们一起聊了相扑的话题」", null, "旅館_旅館前a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "23"}, "CHAPTER 4-2", null, null], [1534, "心子", "「…………哎？」", "mot416_024.ogg", "旅館_旅館前a", "bgm54.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "04"}, "CHAPTER 4-2", null, null], [1535, "心子", "「这样啊……」", "mot416_025.ogg", "旅館_旅館前a", "bgm54.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "09"}, "CHAPTER 4-2", null, null], [1536, "", "咦？怎么感觉刚才猪谷阿姨的眼睛好像忽然失去了神采，是我的错觉吗？", null, "旅館_旅館前a", "bgm54.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "09"}, "CHAPTER 4-2", null, null], [1537, "", "就在这时，旅馆中传来了一阵哄笑。", null, "旅館_旅館前a", "bgm54.opus", null, "CHAPTER 4-2", null, null], [1538, "", "大概是公司集体旅游的住客，正聚在大厅里看电视。", null, "空_青空", "bgm54.opus", null, "CHAPTER 4-2", null, null], [1539, "", "只听声音的话……应该是相扑直播？但他们为什么会哄笑呢？", null, "空_青空", "bgm54.opus", null, "CHAPTER 4-2", null, null], [1540, "客人", "「笑、笑死我了！发狂——生气啦，现在怎么听都像这个！」", "kka416_001.ogg", "空_青空", "bgm23.opus", null, "CHAPTER 4-2", null, null], [1541, "客人", "「昨……昨天那个服务员真是太有才了，以后我每次看相扑比赛估计都会想起她！」", "kkb416_001.ogg", "空_青空", "bgm23.opus", null, "CHAPTER 4-2", null, null], [1542, "心子", "「……」", "mot416_026.ogg", "旅館_旅館前a", "bgm23.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "08"}, "CHAPTER 4-2", null, null], [1543, "", "难怪常陆今天选了相扑的话题，想必是昨天在旅馆看守的时候她就注意到这个问题了。", null, "旅館_旅館前a", "bgm23.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "08"}, "CHAPTER 4-2", null, null], [1544, "将臣", "「……还是迟了一步啊」", null, "旅館_旅館前a", "bgm23.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "08"}, "CHAPTER 4-2", null, null], [1545, "心子", "「不，并没有客人抱怨这个，所以没什么问题」", "mot416_027.ogg", "旅館_旅館前a", "bgm23.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "13"}, "CHAPTER 4-2", null, null], [1546, "心子", "「列支敦瑙尔小姐，以后你可就要注意了」", "mot416_028.ogg", "旅館_旅館前a", "bgm23.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "13"}, "CHAPTER 4-2", null, null], [1547, "蕾娜", "「好的！我会告诉大家，相扑不是发狂，而是发挥扬扬」", "len416_096.ogg", "旅館_旅館前a", "bgm23.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 4-2", null, null], [1548, "心子", "「嗯，马上要开始干活了，你先去准备一下吧」", "mot416_029.ogg", "旅館_旅館前a", "bgm23.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "01"}, "CHAPTER 4-2", null, null], [1549, "心子", "「将臣少爷，大当家应该也在等您了」", "mot416_030.ogg", "旅館_旅館前a", "bgm23.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "02"}, "CHAPTER 4-2", null, null], [1550, "将臣", "「好的，那我先告辞了。蕾娜，明天见」", null, "旅館_旅館前a", "bgm23.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "01"}, "CHAPTER 4-2", null, null], [1551, "", "我行了个礼，转身准备离开。", null, "旅館_旅館前a", "bgm23.opus", null, "CHAPTER 4-2", null, null], [1552, "蕾娜", "「将臣！等你练完剑道之后，我说不定能过去找你，虽然待不了多久」", "len416_097.ogg", "旅館_旅館前a", "bgm23.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 4-2", null, null], [1553, "将臣", "「哎？你不是还要干活吗？」", null, "旅館_旅館前a", "bgm23.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 4-2", null, null], [1554, "蕾娜", "「你练完的时候，工作应该能告一段落」", "len416_098.ogg", "旅館_旅館前a", "bgm23.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 4-2", null, null], [1555, "将臣", "「是吗。但是不要勉强自己啊」", null, "旅館_旅館前a", "bgm23.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 4-2", null, null], [1556, "蕾娜", "「没事的，你也不要勉强自己哦」", "len416_099.ogg", "旅館_旅館前a", "bgm23.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 4-2", null, null], [1557, "将臣", "「……嗯」", null, "旅館_旅館前a", "bgm23.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 4-2", null, null], [1558, "", "尽管早上起床时身体各处都很疼，但白天活动了筋骨之后，不知不觉间疼痛就消失了。", null, "空_青空", "bgm23.opus", null, "CHAPTER 4-2", null, null], [1559, "", "既然不疼了，应该就没什么问题了吧？", null, "空_青空", "bgm23.opus", null, "CHAPTER 4-2", null, null], [1560, "", "蕾娜同样经历了那场战斗，但她也是一回来就立刻开始工作，并没有休息很久。", null, "空_青空", "bgm23.opus", null, "CHAPTER 4-2", null, null], [1561, "", "她都能做到，那我也更应该努力才行。", null, "空_青空", "bgm23.opus", null, "CHAPTER 4-2", null, null], [1562, "", "然而，我的想法似乎还是太天真了。", null, "空_夕空", "bgm23.opus", null, "CHAPTER 4-2", null, null], [1563, "", "就在我像往常一样，跟外公练挂稽古的时候——", null, "空_夕空", "bgm23.opus", null, "CHAPTER 4-2", null, null], [1564, "将臣", "「哇……哎？唔……！？」", null, "空_夕空", "bgm12.opus", null, "CHAPTER 4-2", null, null], [1565, "", "我明明只是轻轻地挡了一刀。可就在我转动身体的时候，全身激起了一阵剧烈的疼痛。", null, "空_夕空", "bgm12.opus", null, "CHAPTER 4-2", null, null], [1566, "", "这疼痛让我的下盘难以使劲，直接向后倒了下去。", null, "空_夕空", "bgm12.opus", null, "CHAPTER 4-2", null, null], [1567, "玄十郎", "「什么！？将臣……喂，将臣！」", "gen416_008.ogg", "空_夕空", "bgm12.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "剣道", "face": "13"}, "CHAPTER 4-2", null, null], [1568, "", "不，这并不是外公的错。", null, "空_夕空", "bgm12.opus", null, "CHAPTER 4-2", null, null], [1569, "", "本来剑道的防具就保护不到后脑勺，而我又没有摆好招架的姿势。", null, "空_夕空", "bgm12.opus", null, "CHAPTER 4-2", null, null], [1570, "", "正当我感觉这种撞头方式不太妙的时候，果不其然……", null, "空_夕空", "bgm12.opus", null, "CHAPTER 4-2", null, null], [1571, "", "……我就这么……昏了过去……", null, "空_夕空", "bgm12.opus", null, "CHAPTER 4-2", null, null], [1572, "将臣", "「嗯？嗯……嗯？」", null, "街_診療所b", "bgm12.opus", null, "CHAPTER 4-2", null, null], [1573, "", "这里是，驹川大夫的诊所？", null, "街_診療所b", "bgm12.opus", null, "CHAPTER 4-2", null, null], [1574, "", "但是，我感觉有什么地方不太对劲。", null, "街_診療所b", "bgm12.opus", null, "CHAPTER 4-2", null, null], [1575, "", "这种感觉，就像是被包裹在母胎内的羊水里一样，柔软而舒适……", null, "街_診療所b", "bgm12.opus", null, "CHAPTER 4-2", null, null], [1576, "", "软软的，弹弹的。", null, "街_診療所b", "bgm12.opus", null, "CHAPTER 4-2", null, null], [1577, "", "这富有弹力的感触，到底是……！？", null, "街_診療所b", "bgm12.opus", null, "CHAPTER 4-2", null, null], [1578, "蕾娜", "「将臣？你是不是醒了，将臣！？」", "len416_100.ogg", "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1579, "", "这里是天堂吗！！？", null, "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1580, "", "难道我并不在诊所，而是在天堂里！？", null, "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1581, "将臣", "「也、也就是说……我死了？」", null, "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1582, "蕾娜", "「你在说什么呢，将臣？你振作点啊，你现在活得好好的，将臣！」", "len416_101.ogg", "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1583, "", "天使正在对我说话。", null, "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1584, "", "不，有两个巨大又柔软的东西挡住了我的视线，我看不见她的脸……咦？", null, "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1585, "将臣", "「难道是蕾娜？哎！？」", null, "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1586, "蕾娜", "「哎呀！？」", "len416_102.ogg", "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1587, "", "我慌慌张张地准备坐起来，鼻子却撞上了蕾娜的胸部。", null, "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1588, "将臣", "「抱、抱歉」", null, "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1589, "", "我又连忙躺了回去，现在后脑勺又传来了大腿的触感……这里真的不是天堂吗！", null, "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1590, "", "哎，我到底在想些什么啊，冷静点！", null, "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1591, "蕾娜", "「行了，将臣，你就老老实躺着吧」", "len416_103.ogg", "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1592, "蕾娜", "「你摔到脑袋，昏过去了，所以才被抬了过来」", "len416_104.ogg", "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1593, "将臣", "「说起来……我好像确实摔到脑袋了？那外公和驹川大夫呢？」", null, "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1594, "蕾娜", "「驹川大夫好像出诊去了，大当家去找她了」", "len416_105.ogg", "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1595, "蕾娜", "「大当家让我在他回来之前陪着你」", "len416_106.ogg", "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1596, "将臣", "「原来如此，那你也不用让我枕在你腿上吧……我已经可以坐起来了」", null, "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1597, "蕾娜", "「你不要动哦，将臣」", "len416_107.ogg", "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1598, "", "她摸了摸我的头发。", null, "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1599, "蕾娜", "「……我刚才可担心你了」", "len416_108.ogg", "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1600, "将臣", "「啊……抱歉」", null, "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1601, "", "看着她泪眼汪汪的样子，我一下子就心软了。", null, "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1602, "", "但是……", null, "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1603, "蕾娜", "「我都说过了，希望你不要勉强自己，你忘了吗？」", "len416_109.ogg", "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1604, "将臣", "「呃、嗯，你确实说过……」", null, "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1605, "", "但是在我看来，我就像是在隔着两座大山跟她对话一样。", null, "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1606, "", "这导致我很难摆正自己的态度。", null, "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1607, "", "而且只要蕾娜稍微前倾，耸立在她胸前的柔软山脉就会压在我的脸上。", null, "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1608, "", "真是服了，这也太大了吧！？", null, "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1609, "", "以前在漫画或动画里看见这种角色时，我都会觉得这么大的尺寸很不现实。但事实证明我错了。", null, "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1610, "", "我现在觉得以前的自己就是井底之蛙，不知世界之大。", null, "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1611, "蕾娜", "「将臣？你在听我说话吗？」", "len416_110.ogg", "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1612, "将臣", "「唔、唔喔，辣什么……哎？」", null, "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1613, "", "柔软的山脉堵住了嘴，我连话都说不利索了。", null, "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1614, "蕾娜", "「将臣，你脸怎么这么红呀？难道是……」", "len416_111.ogg", "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1615, "", "糟了，被她发现了吗？虽然这是不可抗力，但感觉她可能会生气。", null, "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1616, "蕾娜", "「是不是因为你枕在我腿上，所以很害羞呀！」", "len416_112.ogg", "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1617, "", "差点就答对了！准确地说，我是因为被你的大腿和双峰夹成了三明治，所以又害羞又开心。", null, "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1618, "", "不过想要逃脱的话，就只能趁现在了。", null, "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1619, "", "再这样下去，我会失去理智的。", null, "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1620, "将臣", "「是……是的，所以你能不能让我在床上睡」", null, "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1621, "蕾娜", "「这个嘛，不行」", "len416_113.ogg", "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1622, "将臣", "「哎？为、为什么？你就不觉得难为情吗？」", null, "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1623, "蕾娜", "「呜呜，这个……确实很害羞，但还是不行」", "len416_114.ogg", "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1624, "蕾娜", "「你要先跟我保证才行，否则我就不放开你！」", "len416_115.ogg", "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1625, "将臣", "「保证？」", null, "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1626, "蕾娜", "「你要跟我保证，以后一定不勉强自己了」", "len416_116.ogg", "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1627, "将臣", "「啊……」", null, "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1628, "蕾娜", "「大当家说了，他也觉得你今天训练的时候，动作时不时就有点奇怪」", "len416_117.ogg", "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1629, "蕾娜", "「你大概是太小看事故之后才产生的疼痛了」", "len416_118.ogg", "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1630, "", "外公还是厉害，竟然看得这么准确。", null, "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1631, "", "但既然他看出来了，那为什么不手下留情啊。", null, "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1632, "蕾娜", "「所以，归根结底还是我的错……」", "len416_119.ogg", "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1633, "将臣", "「哎？」", null, "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1634, "蕾娜", "「你跟祟神战斗时留下的伤，都还没好吧？」", "len416_120.ogg", "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1635, "蕾娜", "「可我却给你加油鼓劲……所以你才会那么勉强自己吧？」", "len416_121.ogg", "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1636, "将臣", "「不！不是的，真的不是这样，蕾娜」", null, "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1637, "", "难道她是感觉自己有责任，所以才让我枕在她腿上的吗？", null, "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1638, "将臣", "「你为我加油鼓劲，我是很开心的」", null, "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1639, "将臣", "「这次昏倒完全是因为我自己太蠢，自作自受。我活动了一天，只有某些特殊的姿势才会让我觉得疼，所以我就以为没事了」", null, "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1640, "将臣", "「而且……你不是比我还要努力吗？」", null, "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1641, "蕾娜", "「我比你更努力吗？」", "len416_122.ogg", "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1642, "将臣", "「是的，所以我就有点不服输……不对！你别误会了，我不是说这件事怪你」", null, "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1643, "将臣", "「说白了……我就是想好好表现一下。是不是很蠢」", null, "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1644, "蕾娜", "「……」", "len416_123.ogg", "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1645, "", "蕾娜突然缄口不语。难道是让她失望得说不出话了吗？", null, "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1646, "将臣", "「呃，蕾娜？」", null, "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1647, "蕾娜", "「将臣，你是不是误会了什么？其实我并没有那么努力的」", "len416_124.ogg", "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1648, "蕾娜", "「掌柜的天天都在训我，我也经常出现一些失误」", "len416_125.ogg", "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1649, "蕾娜", "「旅馆的工作虽然很辛苦，但也正因如此，大家都会见缝插针地偷偷休息」", "len416_126.ogg", "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1650, "将臣", "「是这样吗？」", null, "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1651, "蕾娜", "「虽然这种事不值得骄傲，但悄悄告诉你，我偷懒的本事可高了」", "len416_127.ogg", "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1652, "蕾娜", "「说到底，我如果真的是那么靠谱的人」", "len416_128.ogg", "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1653, "蕾娜", "「掌柜的也就不会拜托你教我日本的常识了吧」", "len416_129.ogg", "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1654, "将臣", "「唔……这个倒说不准」", null, "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1655, "", "我总感觉她是故意这么说的。", null, "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1656, "", "如果她真的在偷懒，猪谷阿姨不可能看不出来。", null, "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1657, "蕾娜", "「反正，我明明这么不靠谱，你却一直在努力，这可不行哦」", "len416_130.ogg", "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1658, "将臣", "「其实我也不知道你到底靠不靠谱」", null, "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1659, "将臣", "「但一直麻烦你照顾我肯定是不行的」", null, "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1660, "蕾娜", "「嗯……这个倒没什么啦。我反而觉得……还有点小赚」", "len416_131.ogg", "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1661, "蕾娜", "「毕竟，这样就能好好地欣赏你的睡脸了」", "len416_132.ogg", "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1662, "", "蕾娜再一次温柔地摸了摸我的头。", null, "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1663, "", "感觉有点痒。", null, "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1664, "蕾娜", "「总之，我希望你以后不要再勉强自己了」", "len416_133.ogg", "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1665, "将臣", "「嗯，绝对不会了……这次是真的长记性了」", null, "街_診療所b", "bgm54.opus", null, "CHAPTER 4-2", "ev404a", null], [1666, "美津叶", "「啊……我说你们俩也该聊完了吧？」", "miz416_001.ogg", "街_診療所b", "bgm54.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "18"}, "CHAPTER 4-2", null, null], [1667, "将臣", "「驹、驹川大夫！？」", null, "街_診療所b", "bgm54.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "18"}, "CHAPTER 4-2", null, null], [1668, "蕾娜", "「哇呀！？」", "len416_134.ogg", "街_診療所b", "bgm25.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "20"}, "CHAPTER 4-2", null, null], [1669, "", "我慌慌张张地准备坐起来，结果又撞上了蕾娜的胸部。", null, "街_診療所b", "bgm25.opus", null, "CHAPTER 4-2", null, null], [1670, "", "然后被弹回了大腿上。", null, "街_診療所b", "bgm25.opus", null, "CHAPTER 4-2", null, null], [1671, "", "疼……倒是不疼。感觉很软。", null, "街_診療所b", "bgm25.opus", null, "CHAPTER 4-2", null, null], [1672, "蕾娜", "「真、真是的，你在干什么呀，将臣」", "len416_135.ogg", "街_診療所b", "bgm25.opus", null, "CHAPTER 4-2", "ev404a", null], [1673, "蕾娜", "「跟你拥抱都不愿意……这方面却这么大胆～」", "len416_136.ogg", "街_診療所b", "bgm25.opus", null, "CHAPTER 4-2", "ev404a", null], [1674, "将臣", "「抱……抱歉，我不是故意的」", null, "街_診療所b", "bgm25.opus", null, "CHAPTER 4-2", "ev404a", null], [1675, "美津叶", "「我听说有地撞到脑袋了，所以才立刻赶了回来」", "miz416_002.ogg", "街_診療所b", "bgm25.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "09"}, "CHAPTER 4-2", null, null], [1676, "美津叶", "「可你们这是在演小品吗？」", "miz416_003.ogg", "街_診療所b", "bgm25.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "10"}, "CHAPTER 4-2", null, null], [1677, "", "呃，驹川大夫似乎对我们十分无语。", null, "街_診療所b", "bgm25.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "10"}, "CHAPTER 4-2", null, null], [1678, "将臣", "「咦？话说外公人呢？他不是去叫您了吗？」", null, "街_診療所b", "bgm25.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "31"}, "CHAPTER 4-2", null, null], [1679, "美津叶", "「玄十郎先生刚才看到你们这副样子，就先回去了」", "miz416_004.ogg", "街_診療所b", "bgm25.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "24"}, "CHAPTER 4-2", null, null], [1680, "将臣", "「…………哎？」", null, "街_診療所b", "bgm25.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "24"}, "CHAPTER 4-2", null, null], [1681, "", "难道被外公看见了？", null, "街_診療所b", "bgm25.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "24"}, "CHAPTER 4-2", null, null], [1682, "", "我枕在女孩子大腿上的样子竟然被家里人看见了……啊，我要死了，感觉脸都快烧着了。", null, "街_診療所b", "bgm25.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "24"}, "CHAPTER 4-2", null, null], [1683, "美津叶", "「对了，他有句话让我转告你」", "miz416_005.ogg", "街_診療所b", "bgm25.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "18"}, "CHAPTER 4-2", null, null], [1684, "美津叶", "「他说“莫怪”」", "miz416_006.ogg", "街_診療所b", "bgm25.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "19"}, "CHAPTER 4-2", null, null], [1685, "将臣", "「莫怪什么啊！？受伤的事我并没有怪外公啊！你快回来啊！」", null, "街_診療所b", "bgm25.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "19"}, "CHAPTER 4-2", null, null], [1686, "将臣", "「外公！！外公————！！？」", null, "街_診療所b", "bgm25.opus", null, "CHAPTER 4-2", null, null], [1687, "", "我觉得他八成是误会了什么。\\n不，肯定是误会了什么！", null, "街_診療所b", "bgm25.opus", null, "CHAPTER 4-2", null, null], [1688, "美津叶", "「既然你这么有精神，那应该没什么问题。不过还是帮你检查一下吧」", "miz416_007.ogg", "街_診療所b", "bgm25.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "02"}, "CHAPTER 4-2", null, null], [1689, "美津叶", "「以防万一，列支敦瑙尔小姐也做一下检查」", "miz416_008.ogg", "街_診療所b", "bgm25.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "18"}, "CHAPTER 4-2", null, null], [1690, "蕾娜", "「好的！您是要调查碎片的事吧」", "len416_137.ogg", "街_診療所b", "bgm25.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "01"}, "CHAPTER 4-2", null, null], [1691, "", "检查结果表明，我身上的伤并没有多么严重。", null, "空_夕空", "bgm25.opus", null, "CHAPTER 4-2", null, null], [1692, "", "蕾娜也一样，目前从医学角度检查不出什么问题，姑且是放心了。", null, "空_夕空", "bgm25.opus", null, "CHAPTER 4-2", null, null], [1693, "", "可是……明天我该用什么样的表情面对外公啊？", null, "空_夕空", "bgm25.opus", null, "CHAPTER 4-2", null, null], [1694, "", "不管怎么说，短时间内应该是不用训练了，但愿他能在这段期间把事情忘掉……", null, "空_夕空", "bgm25.opus", null, "CHAPTER 4-2", null, null], [1695, "茉子", "「你回来啦，有地」", "mak416_029.ogg", "朝武_リビングd", "bgm05.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "01"}, "CHAPTER 4-2", null, null], [1696, "将臣", "「我回来了……难道你也听说了吗？我训练中摔跤昏倒的事」", null, "朝武_リビングd", "bgm05.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "01"}, "CHAPTER 4-2", null, null], [1697, "茉子", "「哈哈，看你没什么大碍，我也就放心了」", "mak416_030.ogg", "朝武_リビングd", "bgm05.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "34"}, "CHAPTER 4-2", null, null], [1698, "将臣", "「抱歉，让你担心了」", null, "朝武_リビングd", "bgm05.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "34"}, "CHAPTER 4-2", null, null], [1699, "茉子", "「没事没事，说起来，你今天好像一整天都跟蕾娜在一起呢」", "mak416_031.ogg", "朝武_リビングd", "bgm05.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "01"}, "CHAPTER 4-2", null, null], [1700, "将臣", "「难道是蕾娜联系你了？」", null, "朝武_リビングd", "bgm05.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "01"}, "CHAPTER 4-2", null, null], [1701, "茉子", "「是的，我还听说她一直在诊所陪着你。你们怎么突然变得这么亲近呀」", "mak416_032.ogg", "朝武_リビングd", "bgm05.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "01"}, "CHAPTER 4-2", null, null], [1702, "将臣", "「嗯……蕾娜好像有点自责，她觉得是她害我受了这一身伤」", null, "朝武_リビングd", "bgm05.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "01"}, "CHAPTER 4-2", null, null], [1703, "茉子", "「有地，难不成你真的以为蕾娜去看你训练，也是出于自责吗？」", "mak416_033.ogg", "朝武_リビングd", "bgm05.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "49"}, "CHAPTER 4-2", null, null], [1704, "将臣", "「哎？这个倒不清楚……应该是吧？」", null, "朝武_リビングd", "bgm05.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "49"}, "CHAPTER 4-2", null, null], [1705, "", "虽然我也觉得她可能有其他的想法。", null, "朝武_リビングd", "bgm05.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "49"}, "CHAPTER 4-2", null, null], [1706, "", "但我并不敢肯定，至少不敢在别人前面说出来。", null, "朝武_リビングd", "bgm05.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "49"}, "CHAPTER 4-2", null, null], [1707, "茉子", "「是吗。你这种想法倒也挺有你的特色的」", "mak416_034.ogg", "朝武_リビングd", "bgm05.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "34"}, "CHAPTER 4-2", null, null], [1708, "将臣", "「常陆，你难道知道什么内情吗？」", null, "朝武_リビングd", "bgm05.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "34"}, "CHAPTER 4-2", null, null], [1709, "茉子", "「哈哈，这种问题你不该问我吧？」", "mak416_035.ogg", "朝武_リビングd", "bgm05.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "28"}, "CHAPTER 4-2", null, null], [1710, "将臣", "「……你是让我直接问蕾娜？」", null, "朝武_リビングd", "bgm05.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "28"}, "CHAPTER 4-2", null, null], [1711, "", "常陆只是笑了笑，并未作答。", null, "朝武_リビングd", "bgm05.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "23"}, "CHAPTER 4-2", null, null], [1712, "茉子", "「话说芳乃大人也很担心你」", "mak416_037.ogg", "朝武_リビングd", "bgm05.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "27"}, "CHAPTER 4-2", null, null], [1713, "芳乃", "「……」", "yos416_012.ogg", "朝武_リビングd", "bgm05.opus", null, "CHAPTER 4-2", null, null], [1714, "", "就在这时，门外传来了一阵响声。", null, "朝武_リビングd", "bgm05.opus", null, "CHAPTER 4-2", null, null], [1715, "", "难道是朝武跑来迎接我了？", null, "朝武_リビングd", "bgm05.opus", null, "CHAPTER 4-2", null, null], [1716, "将臣", "「唉，我真的是让大家担心了」", null, "朝武_リビングd", "bgm05.opus", null, "CHAPTER 4-2", null, null], [1717, "茉子", "「哈哈，你终于发现了吗？」", "mak416_038.ogg", "朝武_リビングd", "bgm05.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "34"}, "CHAPTER 4-2", null, null], [1718, "将臣", "「嗯……」", null, "朝武_リビングd", "bgm05.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "34"}, "CHAPTER 4-2", null, null], [1719, "", "反正目前看来状况并不会突然恶化，我就尽量少逞强吧。", null, "朝武_リビングd", "bgm05.opus", null, "CHAPTER 4-2", null, null], [1720, "", "这几天还是乖乖静养比较好。", null, "朝武_リビングd", "bgm05.opus", null, "CHAPTER 4-2", null, null], [1721, "将臣", "「不过，难得有蕾娜来帮我加油鼓劲啊」", null, "朝武_自室d", "bgm05.opus", null, "CHAPTER 4-2", null, null], [1722, "", "等等，我干嘛这么失落啊。", null, "朝武_自室d", "bgm05.opus", null, "CHAPTER 4-2", null, null], [1723, "", "就因为我勉强自己训练，才会让蕾娜那么担心。", null, "朝武_自室d", "bgm05.opus", null, "CHAPTER 4-2", null, null], [1724, "将臣", "「我是真是动不动就会想到蕾娜啊」", null, "朝武_自室d", "bgm05.opus", null, "CHAPTER 4-2", null, null], [1725, "", "这种心理到底代表了什么呢？", null, "朝武_自室d", "bgm05.opus", null, "CHAPTER 4-2", null, null], [1726, "", "我还不是很确定自己是怎么想的。", null, "朝武_自室d", "bgm05.opus", null, "CHAPTER 4-2", null, null], [1727, "", "总之，今天就先睡觉吧。", null, "朝武_自室d", "bgm05.opus", null, "CHAPTER 4-2", null, null], [1728, "", "好好休息，尽快恢复健康，这才是我现在最应该做的事。", null, "朝武_自室d", "bgm05.opus", null, "CHAPTER 4-2", null, null], [1729, "", "……嗯？哎？哎哎哎哎哎哎！！？", null, "空_青空", "bgm05.opus", null, "CHAPTER 5-1", null, null], [1730, "", "忽然，一条冒着黑烟的巨大铁块撞进了我的视野。", null, "空_青空", "bgm05.opus", null, "CHAPTER 5-1", null, null], [1731, "", "当然，我知道它是什么。", null, "空_青空", "bgm05.opus", null, "CHAPTER 5-1", null, null], [1732, "", "蒸汽机车！好像经常简称ＳＬ吧？好壮观啊，我还是第一次见到实物。", null, "空_青空", "bgm05.opus", null, "CHAPTER 5-1", null, null], [1733, "", "等等，这种东西应该早就淘汰了，也就是说我现在肯定是在做梦。", null, "空_青空", "bgm05.opus", null, "CHAPTER 5-1", null, null], [1734, "", "不过，车上的锅炉里烧着煤，空气中飘荡着有些粘腻的焦油味，驾驶员沾着煤黑的脸上也都渗出了汗珠。", null, "空_青空", "bgm05.opus", null, "CHAPTER 5-1", null, null], [1735, "", "看上去就像是制作精良的电影一般逼真。", null, "空_青空", "bgm05.opus", null, "CHAPTER 5-1", null, null], [1736, "", "跟现实不同的是，火车并没有停靠在月台之类的地方，而是让乘客们直接沿铁轨两侧下了车。", null, "空_青空", "bgm05.opus", null, "CHAPTER 5-1", null, null], [1737, "青年", "「列支敦瑙尔技师！列支敦瑙尔技师到了吗！？」", "ksf417_001.ogg", "空_青空", "bgm36.opus", null, "CHAPTER 5-1", null, null], [1738, "", "哎？列支敦瑙尔？", null, "空_青空", "bgm36.opus", null, "CHAPTER 5-1", null, null], [1739, "", "走到青年身前的，是一位蓄着胡须的绅士。", null, "空_青空", "bgm36.opus", null, "CHAPTER 5-1", null, null], [1740, "", "绅士和青年紧紧地握了握手。", null, "空_青空", "bgm36.opus", null, "CHAPTER 5-1", null, null], [1741, "青年", "「感谢您不远万里从德意志来到日本，一路上辛苦您了，列支敦瑙尔技师」", "ksf417_002.ogg", "空_青空", "bgm36.opus", null, "CHAPTER 5-1", null, null], [1742, "", "他是德国人？不是北欧人吗？头发的颜色也和蕾娜不一样，是红褐色的头发。", null, "空_青空", "bgm36.opus", null, "CHAPTER 5-1", null, null], [1743, "", "就算是梦，这梦境未免也太乱七八糟了。", null, "空_青空", "bgm36.opus", null, "CHAPTER 5-1", null, null], [1744, "青年", "「……」", "ksf417_003.ogg", "空_青空", "bgm36.opus", null, "CHAPTER 5-1", null, null], [1745, "", "然而下一刻，我的视线彻底被绅士背后的两位吸引了。", null, "空_青空", "bgm36.opus", null, "CHAPTER 5-1", null, null], [1746, "", "看上去像是绅士的夫人和女儿。", null, "空_青空", "bgm36.opus", null, "CHAPTER 5-1", null, null], [1747, "", "她们不仅是金发碧眼，很多地方还和蕾娜很像。", null, "空_青空", "bgm36.opus", null, "CHAPTER 5-1", null, null], [1748, "", "说起来，蕾娜爷爷的爷爷是日本人吧？而且我记得刚好是这个时代的人。", null, "空_青空", "bgm36.opus", null, "CHAPTER 5-1", null, null], [1749, "青年", "「其实最近工程上稍微出了些问题。您几位先跟我来吧，我们备好了车」", "ksf417_004.ogg", "空_青空", "bgm36.opus", null, "CHAPTER 5-1", null, null], [1750, "", "备好的车竟然是人力车。", null, "空_青空", "bgm36.opus", null, "CHAPTER 5-1", null, null], [1751, "", "上了山路之后，又换乘了马车。", null, "空_青空", "bgm36.opus", null, "CHAPTER 5-1", null, null], [1752, "", "其他旅客还有坐在轿子里的，这东西我以前只在历史剧里面见过。", null, "空_青空", "bgm36.opus", null, "CHAPTER 5-1", null, null], [1753, "", "火车已经开始普及，却还有马车轿子在大路上来来往往，这个时代真是远超我的想象。", null, "空_青空", "bgm36.opus", null, "CHAPTER 5-1", null, null], [1754, "青年", "「刚才提到的问题，其实是这样的……」", "ksf417_005.ogg", "空_青空", "bgm36.opus", null, "CHAPTER 5-1", null, null], [1755, "青年", "「穗织当地的老人们都很反对铁路延伸计划，最近他们每天都在带头举行抗议活动」", "ksf417_006.ogg", "空_青空", "bgm36.opus", null, "CHAPTER 5-1", null, null], [1756, "", "哎？把铁路修到穗织？", null, "空_青空", "bgm36.opus", null, "CHAPTER 5-1", null, null], [1757, "", "直到今天，穗织几乎都还没有固定的公交线路，没想到当年竟然有过修铁路的计划。", null, "空_青空", "bgm36.opus", null, "CHAPTER 5-1", null, null], [1758, "", "不过，青年的表情非常认真。", null, "空_青空", "bgm36.opus", null, "CHAPTER 5-1", null, null], [1759, "", "铺设铁轨就得砍伐森林开辟道路，当地有很多居民都对此表示反对，甚至开始静坐示威。", null, "空_青空", "bgm36.opus", null, "CHAPTER 5-1", null, null], [1760, "", "到最后，搞得工人们都不敢进入森林，一个个都逃了出去。", null, "空_青空", "bgm36.opus", null, "CHAPTER 5-1", null, null], [1761, "青年", "「诅咒这种事虽然非常荒谬无稽，但这一带的居民依然对此深信不疑」", "ksf417_007.ogg", "空_青空", "bgm36.opus", null, "CHAPTER 5-1", null, null], [1762, "青年", "「因为这些事，工程到现在还没有一点进展……」", "ksf417_008.ogg", "空_青空", "bgm36.opus", null, "CHAPTER 5-1", null, null], [1763, "青年", "「很抱歉给您添了这么大的麻烦，我们已经为您准备好了住宿」", "ksf417_009.ogg", "空_青空", "bgm36.opus", null, "CHAPTER 5-1", null, null], [1764, "青年", "「这段时间，能委屈您先住在这里吗？」", "ksf417_010.ogg", "空_青空", "bgm36.opus", null, "CHAPTER 5-1", null, null], [1765, "", "绅士人如其表，颇具风度。", null, "空_青空", "bgm36.opus", null, "CHAPTER 5-1", null, null], [1766, "", "他只是捻了捻胡须，说了句“那也是没办法的事”。", null, "空_青空", "bgm36.opus", null, "CHAPTER 5-1", null, null], [1767, "", "之后，青年一个劲地聊着日本的铁路，说日本这种小小的岛国若要与欧美列强抗衡，构建铁路网乃是当务之急。", null, "空_青空", "bgm36.opus", null, "CHAPTER 5-1", null, null], [1768, "", "他还说自己想出国深造，想拜列支敦瑙尔技师这样的人为师，学习先进的技术。", null, "空_青空", "bgm36.opus", null, "CHAPTER 5-1", null, null], [1769, "", "他主动承担列支敦瑙尔技师的向导工作，似乎也是出于这一想法。", null, "空_青空", "bgm36.opus", null, "CHAPTER 5-1", null, null], [1770, "", "技师的夫人和正值妙龄的女儿也在一旁听着。", null, "空_青空", "bgm36.opus", null, "CHAPTER 5-1", null, null], [1771, "", "女儿看上去有些内向，总是藏在妈妈的身后，怯生生地望着森林。", null, "空_青空", "bgm36.opus", null, "CHAPTER 5-1", null, null], [1772, "", "终于，马车到达了目的地。", null, "空_青空", "bgm36.opus", null, "CHAPTER 5-1", null, null], [1773, "将臣", "「哈、哈哈哈，果然这是在做梦！」", null, "空_青空", "bgm36.opus", null, "CHAPTER 5-1", null, null], [1774, "", "没想到青年和绅士最终到达的地方是志那都庄。", null, "旅館_旅館前a", "bgm36.opus", null, "CHAPTER 5-1", null, null], [1775, "", "门面看上去好像比现在还要新一些，这梦未免太逼真了吧。", null, "旅館_旅館前a", "bgm36.opus", null, "CHAPTER 5-1", null, null], [1776, "蕾娜", "「喔，果然是在梦里吗？」", "len417_001.ogg", "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27"}, "CHAPTER 5-1", null, null], [1777, "将臣", "「应该是这样吧？不过志那都庄从江户时代就有了，在这个年代能看到也不算奇怪就是了」", null, "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27"}, "CHAPTER 5-1", null, null], [1778, "将臣", "「没想到梦境的最后居然出现了我们熟悉的地方……哎？」", null, "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27"}, "CHAPTER 5-1", null, null], [1779, "将臣", "「蕾娜！？你怎么在这？」", null, "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 5-1", null, null], [1780, "蕾娜", "「我才想问呢，你怎么在这里……不过既然是梦里的志那都庄，你出现在这里倒也不奇怪」", "len417_002.ogg", "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 5-1", null, null], [1781, "将臣", "「这么说，这个蕾娜也是我做梦梦到的吧？」", null, "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 5-1", null, null], [1782, "蕾娜", "「哎？不是我梦到的你吗？」", "len417_003.ogg", "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "20"}, "CHAPTER 5-1", null, null], [1783, "将臣", "「？」", null, "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "20"}, "CHAPTER 5-1", null, null], [1784, "蕾娜", "「……？」", "len417_004.ogg", "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "28"}, "CHAPTER 5-1", null, null], [1785, "蕾娜", "「嗯，无所谓啦！嘿嘿，反正可以确定的是……我竟然在梦里也见到你了」", "len417_005.ogg", "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02"}, "CHAPTER 5-1", null, null], [1786, "将臣", "「嗯、嗯，确实」", null, "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02"}, "CHAPTER 5-1", null, null], [1787, "将臣", "「能在梦里见到你，其实我也…………咦？」", null, "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02"}, "CHAPTER 5-1", null, null], [1788, "", "身体突然轻轻地飘了起来。", null, "旅館_旅館前a", "bgm36.opus", null, "CHAPTER 5-1", null, null], [1789, "", "在梦里面，还会发生这种事啊……", null, "旅館_旅館前a", "bgm36.opus", null, "CHAPTER 5-1", null, null], [1790, "蕾娜", "「啊，等我一下！将臣，将臣！？」", "len417_006.ogg", "旅館_旅館前a", "bgm36.opus", null, "CHAPTER 5-1", null, null], [1791, "将臣", "「……哎呀？」", null, "旅館_レナの部屋a", "bgm36.opus", null, "CHAPTER 5-1", null, null], [1792, "", "好像有谁的脚踩到了我的脸上。", null, "旅館_レナの部屋a", "bgm36.opus", null, "CHAPTER 5-1", null, null], [1793, "", "怎么回事？不对，这不是我的房间！？", null, "旅館_レナの部屋a", "bgm36.opus", null, "CHAPTER 5-1", null, null], [1794, "将臣", "「这里，到底是……」", null, "旅館_レナの部屋a", "bgm36.opus", null, "CHAPTER 5-1", null, null], [1795, "将臣", "「……哪里啊？」", null, "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-1", "ev405a", null], [1796, "蕾娜", "「呼……哈……」", "len417_007.ogg", "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-1", "ev405a", null], [1797, "", "突然感觉背上冷汗直冒。", null, "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-1", "ev405a", null], [1798, "", "想都不用想，这里应该是蕾娜的房间……吧？", null, "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-1", "ev405a", null], [1799, "将臣", "「可、可可可是，为、为什么！？为什么我会在蕾娜的房间里？」", null, "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-1", "ev405a", null], [1800, "蕾娜", "「……唔唔，将臣」", "len417_008.ogg", "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-1", "ev405a", null], [1801, "将臣", "「哎？啊，还好只是梦话……什么！？」", null, "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-1", "ev405a", null], [1802, "", "突然，蕾娜轻轻地翻了个身。", null, "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-1", "ev405a", null], [1803, "", "翻身时，睡衣大敞……", null, "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-1", "ev405a", null], [1804, "将臣", "「哇啊啊！？」", null, "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-1", "ev405a", null], [1805, "", "我赶紧帮蕾娜把睡衣整好。", null, "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-1", "ev405a", null], [1806, "", "犯罪啊！", null, "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-1", "ev405a", null], [1807, "", "这场面要是被别人看见了，我肯定会被当成罪犯的。", null, "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-1", "ev405a", null], [1808, "", "可是，为什么会发生这种事……啊！？", null, "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-1", "ev405a", null], [1809, "将臣", "「对了，是梦！我肯定还在做梦」", null, "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-1", "ev405a", null], [1810, "蕾娜", "「咦……爷爷的爷爷……还有爷爷的奶奶，跟照片里一模一样呢……唔……」", "len417_009.ogg", "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-1", "ev405a", null], [1811, "将臣", "「……哎？」", null, "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-1", "ev405a", null], [1812, "", "忽然，我想起了刚才的梦。", null, "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-1", "ev405a", null], [1813, "", "在梦里，德国铁路技师列支敦瑙尔先生带着夫人女儿一起来到了志那都庄。", null, "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-1", "ev405a", null], [1814, "", "迎接他的是一位想要拜他为师的日本青年。", null, "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-1", "ev405a", null], [1815, "", "之后，我还和梦中的蕾娜进行了奇妙的对话……是我想多了吗？", null, "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-1", "ev405a", null], [1816, "", "难不成，蕾娜还在继续做着刚才的梦？", null, "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-1", "ev405a", null], [1817, "将臣", "「对了，之前朝武也钻到过我的被窝里，这次刚好相反」", null, "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-1", "ev405a", null], [1818, "", "我和蕾娜的身体都吸收了碎片，在我睡着的时候确实有可能被她吸引过来。", null, "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-1", "ev405a", null], [1819, "", "说不定就是这么回事？", null, "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-1", "ev405a", null], [1820, "将臣", "「这点日后可以验证一下……」", null, "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-1", "ev405a", null], [1821, "蕾娜", "「…………啊？」", "len417_010.ogg", "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-1", "ev405a", null], [1822, "", "啊。", null, "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-1", "ev405a", null], [1823, "蕾娜", "「咦……将臣你在啊，梦里你突然就不见了……我好担心你的」", "len417_011.ogg", "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-1", "ev405a", null], [1824, "将臣", "「唔、嗯，早上好蕾娜」", null, "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-1", "ev405a", null], [1825, "蕾娜", "「嗯……早上好」", "len417_012.ogg", "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-1", "ev405a", null], [1826, "蕾娜", "「…………」", "len417_013.ogg", "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-1", "ev405a", null], [1827, "蕾娜", "「………………………………」", "len417_014.ogg", "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-1", "ev405a", null], [1828, "蕾娜", "「…………………………………………………………哎？」", "len417_015.ogg", "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-1", "ev405a", null], [1829, "蕾娜", "「将、将臣！？」", "len417_016.ogg", "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-1", "ev405a", null], [1830, "蕾娜", "「哇呀啊啊啊啊啊啊啊啊啊～～！！？」", "len417_017.ogg", "旅館_旅館前a", "bgm25.opus", null, "CHAPTER 5-1", null, null], [1831, "心子", "「列支敦瑙尔小姐，幸好这里离客房比较远」", "mot417_001.ogg", "旅館_レナの部屋a", "bgm22.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "07"}, "CHAPTER 5-1", null, null], [1832, "心子", "「如果你刚才的尖叫让客人听到了，他们会觉得志那都庄是个怎样的地方？」", "mot417_002.ogg", "旅館_レナの部屋a", "bgm22.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "09"}, "CHAPTER 5-1", null, null], [1833, "心子", "「尖叫之前你就不能好好想想吗？」", "mot417_003.ogg", "旅館_レナの部屋a", "bgm22.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "10"}, "CHAPTER 5-1", null, null], [1834, "蕾娜", "「呜呀，真是对不起！真是对不起！」", "len417_018.ogg", "旅館_レナの部屋a", "bgm22.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "22"}, "CHAPTER 5-1", null, null], [1835, "", "听到尖叫声赶来的猪谷阿姨把我们教训了一通。", null, "旅館_レナの部屋a", "bgm22.opus", null, "CHAPTER 5-1", null, null], [1836, "", "老板娘的威严还是不容小觑，随随便便几句话就把我们震慑住了。", null, "旅館_レナの部屋a", "bgm22.opus", null, "CHAPTER 5-1", null, null], [1837, "", "看见蕾娜被吓成那个样子，我也不自觉地摆出了正坐姿势。", null, "旅館_レナの部屋a", "bgm22.opus", null, "CHAPTER 5-1", null, null], [1838, "心子", "「呵呵，还有，将臣少爷」", "mot417_004.ogg", "旅館_レナの部屋a", "bgm22.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "02"}, "CHAPTER 5-1", null, null], [1839, "将臣", "「您、您说」", null, "旅館_レナの部屋a", "bgm22.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "02"}, "CHAPTER 5-1", null, null], [1840, "", "就连我也被吓得音调高了一大截。", null, "旅館_レナの部屋a", "bgm22.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "02"}, "CHAPTER 5-1", null, null], [1841, "心子", "「昨天，我确实拜托您教列支敦瑙尔小姐一些日本的常识」", "mot417_005.ogg", "旅館_レナの部屋a", "bgm22.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "11"}, "CHAPTER 5-1", null, null], [1842, "心子", "「可是，难不成您是准备告诉她半夜幽会也是日本的常识之一吗？」", "mot417_006.ogg", "旅館_レナの部屋a", "bgm22.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "13"}, "CHAPTER 5-1", null, null], [1843, "将臣", "「不、不是这样的，我……我发誓没这打算」", null, "旅館_レナの部屋a", "bgm22.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "13"}, "CHAPTER 5-1", null, null], [1844, "蕾娜", "「是啊，掌柜的！我只是今天早上一醒来，就发现他在我房间而已」", "len417_019.ogg", "旅館_レナの部屋a", "bgm22.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "07"}, "CHAPTER 5-1", null, null], [1845, "蕾娜", "「幽会……我也不知道是什么意思，他还没有教我！真的」", "len417_020.ogg", "旅館_レナの部屋a", "bgm22.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "15"}, "CHAPTER 5-1", null, null], [1846, "将臣", "「蕾、蕾娜，你别往火上浇油啊？」", null, "旅館_レナの部屋a", "bgm22.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "15"}, "CHAPTER 5-1", null, null], [1847, "", "刚才，外公、廉太郎和小春他们听到这边的骚动后也都赶了过来。", null, "旅館_レナの部屋a", "bgm22.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "09"}, "CHAPTER 5-1", null, null], [1848, "", "不、不妙，这已经到开家庭会议的程度了。", null, "旅館_レナの部屋a", "bgm22.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "09"}, "CHAPTER 5-1", null, null], [1849, "", "我要是告诉他们，我是睡着的时候不知不觉间来到了蕾娜的房间，他们会相信我吗？", null, "旅館_レナの部屋a", "bgm22.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "09"}, "CHAPTER 5-1", null, null], [1850, "廉太郎", "「将臣，你竟然……！」", "ren417_001.ogg", "旅館_レナの部屋a", "bgm22.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "23"}, "CHAPTER 5-1", null, null], [1851, "将臣", "「廉、廉太郎」", null, "旅館_レナの部屋a", "bgm22.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "23"}, "CHAPTER 5-1", null, null], [1852, "", "为什么呢？我连自己的兄弟的眼睛都不敢直视。", null, "旅館_レナの部屋a", "bgm22.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "23"}, "CHAPTER 5-1", null, null], [1853, "廉太郎", "「你还记得吗，以前我经常叫上你，还有很多朋友一起来我家开睡衣派对」", "ren417_002.ogg", "旅館_レナの部屋a", "bgm22.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "20"}, "CHAPTER 5-1", null, null], [1854, "将臣", "「哎？啊，好像是有这么回事」", null, "旅館_レナの部屋a", "bgm22.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "20"}, "CHAPTER 5-1", null, null], [1855, "廉太郎", "「但那个时候，除了小春和我妈，其余全都是男生！」", "ren417_003.ogg", "旅館_レナの部屋a", "bgm22.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "22"}, "CHAPTER 5-1", null, null], [1856, "将臣", "「哎？」", null, "旅館_レナの部屋a", "bgm22.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "22"}, "CHAPTER 5-1", null, null], [1857, "廉太郎", "「可你如今却在我家和外国女生……而且是两人单独在一起开睡衣派对，你这个混蛋！」", "ren417_004.ogg", "旅館_レナの部屋a", "bgm22.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "09"}, "CHAPTER 5-1", null, null], [1858, "将臣", "「你听我解释啊，廉太郎，我和蕾娜并没有……」", null, "旅館_レナの部屋a", "bgm22.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "09"}, "CHAPTER 5-1", null, null], [1859, "廉太郎", "「不，别解释了别解释了……你干得漂亮！」", "ren417_006.ogg", "旅館_レナの部屋a", "bgm22.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-1", null, null], [1860, "廉太郎", "「我祝福你们」", "ren417_007.ogg", "旅館_レナの部屋a", "bgm22.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "28"}, "CHAPTER 5-1", null, null], [1861, "", "廉太郎这家伙，竟然最后还给我竖了个大拇指。", null, "旅館_レナの部屋a", "bgm22.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "28"}, "CHAPTER 5-1", null, null], [1862, "将臣", "「拜、拜托了，你们听我解释啊！」", null, "旅館_レナの部屋a", "bgm22.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "28"}, "CHAPTER 5-1", null, null], [1863, "蕾娜", "「就是啊！别这样了，廉哥」", "koh417_001.ogg", "旅館_レナの部屋a", "bgm22.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "29n"}, "CHAPTER 5-1", null, null], [1864, "", "小春眼泪都流出来了。", null, "旅館_レナの部屋a", "bgm22.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "29n"}, "CHAPTER 5-1", null, null], [1865, "蕾娜", "「呜……呜，我相信你，哥哥。你跟廉哥不一样，才不会干这种事呢！」", "koh417_002.ogg", "旅館_レナの部屋a", "bgm22.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "11n"}, "CHAPTER 5-1", null, null], [1866, "将臣", "「哎？你等一下，你指的到底是……」", null, "旅館_レナの部屋a", "bgm22.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "11n"}, "CHAPTER 5-1", null, null], [1867, "蕾娜", "「没关系！我相信哥哥」", "koh417_003.ogg", "旅館_レナの部屋a", "bgm22.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "34n"}, "CHAPTER 5-1", null, null], [1868, "蕾娜", "「我相信你不会像廉哥一样，为了满足自己的欲望，偷偷跑进女孩子的房间」", "koh417_004.ogg", "旅館_レナの部屋a", "bgm22.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "06n"}, "CHAPTER 5-1", null, null], [1869, "", "所有人一齐看向廉太郎。", null, "旅館_レナの部屋a", "bgm22.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "14"}, "CHAPTER 5-1", null, null], [1870, "", "仿佛在看着一只缺乏管教的宠物。", null, "旅館_レナの部屋a", "bgm22.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "14"}, "CHAPTER 5-1", null, null], [1871, "廉太郎", "「没、没这回事！都是胡说八道！！」", "ren417_008.ogg", "旅館_レナの部屋a", "bgm22.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "09"}, "CHAPTER 5-1", null, null], [1872, "廉太郎", "「喂，小春！你别说得我好像有前科一样啊！不要随便污蔑我好吗」", "ren417_009.ogg", "旅館_レナの部屋a", "bgm22.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "13"}, "CHAPTER 5-1", null, null], [1873, "蕾娜", "「因为你很可能干这种事，但哥哥是绝对不会干这种事的！」", "koh417_005.ogg", "旅館_レナの部屋a", "bgm22.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "34"}, "CHAPTER 5-1", null, null], [1874, "蕾娜", "「是吧，哥哥？我相信你……你放心，我是绝对相信你的！」", "koh417_006.ogg", "旅館_レナの部屋a", "bgm22.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "20"}, "CHAPTER 5-1", null, null], [1875, "将臣", "「小春……」", null, "旅館_レナの部屋a", "bgm22.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "20"}, "CHAPTER 5-1", null, null], [1876, "", "强调这么多遍，反而感觉自己根本不受信任啊？", null, "旅館_レナの部屋a", "bgm22.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "20"}, "CHAPTER 5-1", null, null], [1877, "", "说真的，心好痛。", null, "旅館_レナの部屋a", "bgm22.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "20"}, "CHAPTER 5-1", null, null], [1878, "蕾娜", "「嗯……难道说，幽会就是在朋友家开睡衣派对的意思吗？」", "len417_021.ogg", "旅館_レナの部屋a", "bgm22.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 5-1", null, null], [1879, "蕾娜", "「如果是这样的话，那我昨晚确实跟将臣幽会了……」", "len417_022.ogg", "旅館_レナの部屋a", "bgm22.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "20"}, "CHAPTER 5-1", null, null], [1880, "将臣", "「没有！幽会不是这个意思，你别再误会了！」", null, "旅館_レナの部屋a", "bgm22.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "20"}, "CHAPTER 5-1", null, null], [1881, "蕾娜", "「可是……我和将臣，昨晚一直在一起……这是事实吧？」", "len417_023.ogg", "旅館_レナの部屋a", "bgm22.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "34"}, "CHAPTER 5-1", null, null], [1882, "将臣", "「啊，嗯……可是，那是因为……」", null, "旅館_レナの部屋a", "bgm22.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "34"}, "CHAPTER 5-1", null, null], [1883, "蕾娜", "「没想到你竟然半夜来我房间，实在是太有勇气了，吓我一大跳……」", "len417_024.ogg", "旅館_レナの部屋a", "bgm22.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27h"}, "CHAPTER 5-1", null, null], [1884, "蕾娜", "「不过，我其实……并不讨厌跟你开睡衣派对……」", "len417_025.ogg", "旅館_レナの部屋a", "bgm22.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "03h"}, "CHAPTER 5-1", null, null], [1885, "将臣", "「蕾、蕾蕾蕾娜？」", null, "旅館_レナの部屋a", "bgm22.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "03h"}, "CHAPTER 5-1", null, null], [1886, "", "大家看我的视线骤然冰冷了下来。", null, "旅館_レナの部屋a", "bgm22.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "08"}, "CHAPTER 5-1", null, null], [1887, "", "嗯，我知道。道理我都懂。大家的意思是，我至少得拿出一个负责任的态度。", null, "旅館_レナの部屋a", "bgm22.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "08"}, "CHAPTER 5-1", null, null], [1888, "", "可这些真的都是误会啊！", null, "旅館_レナの部屋a", "bgm22.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "08"}, "CHAPTER 5-1", null, null], [1889, "玄十郎", "「行了，大家都先冷静一下」", "gen417_001.ogg", "旅館_レナの部屋a", "bgm22.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "17"}, "CHAPTER 5-1", null, null], [1890, "将臣", "「外公！」", null, "旅館_レナの部屋a", "bgm22.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "17"}, "CHAPTER 5-1", null, null], [1891, "", "对了，外公对祟神和诅咒这些事情也了解一些。", null, "旅館_レナの部屋a", "bgm22.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "05"}, "CHAPTER 5-1", null, null], [1892, "", "他应该听说了，我和蕾娜的身体都吸收了碎片。", null, "旅館_レナの部屋a", "bgm22.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "05"}, "CHAPTER 5-1", null, null], [1893, "", "那么只要让外公明白，我也和朝武一样，是被碎片吸引到这里来的……", null, "旅館_レナの部屋a", "bgm22.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "05"}, "CHAPTER 5-1", null, null], [1894, "玄十郎", "「这种年轻人之间的事情，周围的人不应该说三道四」", "gen417_002.ogg", "旅館_レナの部屋a", "bgm22.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "11"}, "CHAPTER 5-1", null, null], [1895, "将臣", "「…………啥？」", null, "旅館_レナの部屋a", "bgm22.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "11"}, "CHAPTER 5-1", null, null], [1896, "玄十郎", "「这种年轻人之间的事情，周围的人是不应该说三道四的」", "gen417_003.ogg", "旅館_レナの部屋a", "bgm22.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "18"}, "CHAPTER 5-1", null, null], [1897, "将臣", "「为什么要说两遍？」", null, "旅館_レナの部屋a", "bgm22.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "18"}, "CHAPTER 5-1", null, null], [1898, "", "看来外公这副冷静的样子也是装出来的，他只是在努力让自己的言行看上去和平常一样而已。", null, "旅館_レナの部屋a", "bgm22.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "18"}, "CHAPTER 5-1", null, null], [1899, "", "说起来昨天在诊所的时候，他看到我枕在蕾娜腿上，也是一言不发就回去了。", null, "旅館_レナの部屋a", "bgm22.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "18"}, "CHAPTER 5-1", null, null], [1900, "玄十郎", "「如果旁人议论太多，会不利于他们进一步培养感情」", "gen417_004.ogg", "旅館_レナの部屋a", "bgm22.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "05"}, "CHAPTER 5-1", null, null], [1901, "玄十郎", "「掌柜的，不好意思，这件事能交给我来处理吗？」", "gen417_005.ogg", "旅館_レナの部屋a", "bgm22.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "11"}, "CHAPTER 5-1", null, null], [1902, "心子", "「既然您都这么说了，那就拜托您了」", "mot417_007.ogg", "旅館_レナの部屋a", "bgm22.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "13"}, "CHAPTER 5-1", null, null], [1903, "将臣", "「等一下，外公！难道你才是最怀疑我的？」", null, "旅館_レナの部屋a", "bgm22.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "11"}, "CHAPTER 5-1", null, null], [1904, "玄十郎", "「这件事在某种意义上来说也算是家庭问题」", "gen417_006.ogg", "旅館_レナの部屋a", "bgm22.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "14"}, "CHAPTER 5-1", null, null], [1905, "", "终……终究还是逃不过这一劫吗？", null, "旅館_レナの部屋a", "bgm22.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "14"}, "CHAPTER 5-1", null, null], [1906, "廉太郎", "「可、可怕～」", "ren417_010.ogg", "旅館_レナの部屋a", "bgm22.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "13"}, "CHAPTER 5-1", null, null], [1907, "蕾娜", "「哥哥的性命已经是风中残烛了」", "koh417_007.ogg", "旅館_レナの部屋a", "bgm22.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "08"}, "CHAPTER 5-1", null, null], [1908, "", "时隔多年，我再一次想起了小时候外公留给我的可怕回忆。", null, "旅館_レナの部屋a", "bgm22.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "11"}, "CHAPTER 5-1", null, null], [1909, "", "唉，这里都没有一个人愿意帮我说话吗……。", null, "旅館_レナの部屋a", "bgm22.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "11"}, "CHAPTER 5-1", null, null], [1910, "玄十郎", "「嚯，也就是说你整晚都没碰列支敦瑙尔小姐一根汗毛？」", "gen417_007.ogg", "旅館_レナの部屋a", "bgm25.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "18"}, "CHAPTER 5-1", null, null], [1911, "蕾娜", "「你整晚都没碰我吗！」", "len417_026.ogg", "旅館_レナの部屋a", "bgm25.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "19"}, "CHAPTER 5-1", null, null], [1912, "", "大家都离开之后，屋里只剩下我、外公和蕾娜三人。", null, "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-1", null, null], [1913, "", "然后我就先把昨晚的事解释了一边，说自己没有做任何亏心事……", null, "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-1", null, null], [1914, "将臣", "「为什么蕾娜要生气啊？」", null, "旅館_レナの部屋a", "bgm25.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "19"}, "CHAPTER 5-1", null, null], [1915, "蕾娜", "「哎？那是因为……你一下都没碰我啊！那你过来是干什么的」", "len417_027.ogg", "旅館_レナの部屋a", "bgm25.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 5-1", null, null], [1916, "蕾娜", "「你……你难道完全没有产生过那种想法吗？」", "len417_028.ogg", "旅館_レナの部屋a", "bgm25.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "09"}, "CHAPTER 5-1", null, null], [1917, "将臣", "「不、不是！我过来的时候，可能根本就不太清醒」", null, "旅館_レナの部屋a", "bgm25.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "09"}, "CHAPTER 5-1", null, null], [1918, "将臣", "「你忘了吗，宿体的碎片都是会相互吸引的吧？大概就是这种感觉，所以我也会有类似梦游的症状」", null, "旅館_レナの部屋a", "bgm25.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "09"}, "CHAPTER 5-1", null, null], [1919, "", "拿这种理由来解释，我自己都觉得很扯，但意思应该传达到了。", null, "旅館_レナの部屋a", "bgm25.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "09"}, "CHAPTER 5-1", null, null], [1920, "玄十郎", "「首先，还是把你们互相吸引的事情弄清楚比较好」", "gen417_008.ogg", "旅館_レナの部屋a", "bgm25.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "05"}, "CHAPTER 5-1", null, null], [1921, "玄十郎", "「这也是为了证明你的清白」", "gen417_009.ogg", "旅館_レナの部屋a", "bgm25.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-1", null, null], [1922, "将臣", "「外公果然还在怀疑我……」", null, "旅館_レナの部屋a", "bgm25.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-1", null, null], [1923, "玄十郎", "「行了，丛雨大人在这吗？」", "gen417_010.ogg", "旅館_レナの部屋a", "bgm25.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-1", null, null], [1924, "将臣", "「小雨她……啊，对了！」", null, "旅館_レナの部屋a", "bgm25.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-1", null, null], [1925, "将臣", "「如果我是因为碎片之间的共鸣而被吸引过来的，小雨应该知道昨晚到底发生了什么！」", null, "旅館_レナの部屋a", "bgm25.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "18"}, "CHAPTER 5-1", null, null], [1926, "丛雨", "「就知道你差不多该叫本座了，主人」", "mur417_001.ogg", "旅館_レナの部屋a", "bgm25.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "18"}, "CHAPTER 5-1", null, null], [1927, "将臣", "「哇，小……小雨！？」", null, "旅館_レナの部屋a", "bgm25.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "18"}, "CHAPTER 5-1", null, null], [1928, "", "少女突然从天花板探出脑袋，飞了下来。", null, "旅館_レナの部屋a", "bgm25.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "18"}, "CHAPTER 5-1", null, null], [1929, "蕾娜", "「小雨，难不成你一直都在吗？」", "len417_029.ogg", "旅館_レナの部屋a", "bgm25.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-1", null, null], [1930, "丛雨", "「嗯，昨晚主人像梦游病患者一样从房间里走出去的时候，本座就一直跟在身后」", "mur417_002.ogg", "旅館_レナの部屋a", "bgm25.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-1", null, null], [1931, "丛雨", "「顺带一提，芳乃和茉子也知道了」", "mur417_003.ogg", "旅館_レナの部屋a", "bgm25.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-1", null, null], [1932, "将臣", "「……该不会，大家都以为我是来幽会的吧？」", null, "旅館_レナの部屋a", "bgm25.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-1", null, null], [1933, "蕾娜", "「喔……事、事到如今，我只能负起责任娶了将臣……」", "len417_030.ogg", "旅館_レナの部屋a", "bgm25.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-1", null, null], [1934, "丛雨", "「不是的，主人的情况和之前蕾娜被碎片操控时如出一辙」", "mur417_004.ogg", "旅館_レナの部屋a", "bgm25.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "03"}, "CHAPTER 5-1", null, null], [1935, "丛雨", "「本座为了确认主人会被吸引到哪里，所以一直跟在后面」", "mur417_005.ogg", "旅館_レナの部屋a", "bgm25.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "10"}, "CHAPTER 5-1", null, null], [1936, "将臣", "「那么，你应该就能证明我无罪了吧？」", null, "旅館_レナの部屋a", "bgm25.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "10"}, "CHAPTER 5-1", null, null], [1937, "将臣", "「哎呀，那你早点出现帮我说句话不就好了」", null, "旅館_レナの部屋a", "bgm25.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "10"}, "CHAPTER 5-1", null, null], [1938, "丛雨", "「大家都在场，本座要是跟你说话，岂不是只会让场面更加混乱吗？」", "mur417_006.ogg", "旅館_レナの部屋a", "bgm25.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "36"}, "CHAPTER 5-1", null, null], [1939, "丛雨", "「本来我们也想过要不要早点把你叫醒，但本座想来想去还是决定先观察状况再说」", "mur417_007.ogg", "旅館_レナの部屋a", "bgm25.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "11"}, "CHAPTER 5-1", null, null], [1940, "丛雨", "「要是像之前那样怎么叫都叫不醒，那叫了也是白费力气」", "mur417_008.ogg", "旅館_レナの部屋a", "bgm25.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "36"}, "CHAPTER 5-1", null, null], [1941, "丛雨", "「不过，如果是你，本座应该可以用神力唤醒」", "mur417_009.ogg", "旅館_レナの部屋a", "bgm25.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-1", null, null], [1942, "将臣", "「原来如此，所以让我稍微冒点风险问题也不大」", null, "旅館_レナの部屋a", "bgm25.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-1", null, null], [1943, "丛雨", "「对不住了，主人」", "mur417_010.ogg", "旅館_レナの部屋a", "bgm25.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "30"}, "CHAPTER 5-1", null, null], [1944, "丛雨", "「说实话，本座也不知道应不应该冒这险，但还是想尽可能多获取一些信息」", "mur417_011.ogg", "旅館_レナの部屋a", "bgm25.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "25"}, "CHAPTER 5-1", null, null], [1945, "将臣", "「没关系，这也是没办法的事」", null, "旅館_レナの部屋a", "bgm25.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "25"}, "CHAPTER 5-1", null, null], [1946, "", "说起来，之前蕾娜要是把梦里的美食都吃了下去，有可能就回不来了。", null, "旅館_レナの部屋a", "bgm39.opus", null, "CHAPTER 5-1", null, null], [1947, "", "若真是这样，那这也确实算是一种危险的赌博了。", null, "旅館_レナの部屋a", "bgm39.opus", null, "CHAPTER 5-1", null, null], [1948, "将臣", "「啊，差点忘记说了！昨晚我好像做了个奇怪的梦」", null, "旅館_レナの部屋a", "bgm39.opus", null, "CHAPTER 5-1", null, null], [1949, "蕾娜", "「我刚刚也想说这件事」", "len417_031.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "15"}, "CHAPTER 5-1", null, null], [1950, "丛雨", "「什么！难道说，祟神又让你们做梦了吗？」", "mur417_012.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "26"}, "CHAPTER 5-1", null, null], [1951, "将臣", "「不是的，跟之前那种危险的梦不太一样――」", null, "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "26"}, "CHAPTER 5-1", null, null], [1952, "", "在梦里，我第一次知道穗织曾经也有过蒸汽火车的铁路延伸计划。", null, "空_青空", "bgm39.opus", null, "CHAPTER 5-1", null, null], [1953, "", "为了建设铁路，德国技师列支敦瑙尔先生还来到了穗织，住在志那都庄。这些事我都一五一十说了一遍。", null, "空_青空", "bgm39.opus", null, "CHAPTER 5-1", null, null], [1954, "蕾娜", "「将、将臣……你说的，和我做的梦一模一样！」", "len417_032.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "19"}, "CHAPTER 5-1", null, null], [1955, "将臣", "「啊，那我们是不是在梦里也说过话？」", null, "旅館_レナの部屋a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "19"}, "CHAPTER 5-1", null, null], [1956, "蕾娜", "「是的！你当时还说，这肯定是梦」", "len417_033.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 5-1", null, null], [1957, "将臣", "「……果然如此」", null, "旅館_レナの部屋a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 5-1", null, null], [1958, "", "虽然我也考虑过这种可能性，但没想到我们俩竟然真的做了同样的梦。", null, "旅館_レナの部屋a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 5-1", null, null], [1959, "", "而且在梦里，我们的意识都是十分清醒的。", null, "旅館_レナの部屋a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 5-1", null, null], [1960, "将臣", "「感觉就像两个人在看同一场电影一样？」", null, "旅館_レナの部屋a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 5-1", null, null], [1961, "蕾娜", "「喔，我大概也是同样的感觉。你这么一说，我觉得形容得非常恰当」", "len417_034.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "01"}, "CHAPTER 5-1", null, null], [1962, "丛雨", "「果然，那这应该就是身体吸收碎片产生的影响吧」", "mur417_013.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "34"}, "CHAPTER 5-1", null, null], [1963, "蕾娜", "「是这么回事吗！」", "len417_035.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "34"}, "CHAPTER 5-1", null, null], [1964, "丛雨", "「大概是以某件事为契机，碎片中残留的记忆被回放了出来。虽然这只是一种猜测」", "mur417_014.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "11"}, "CHAPTER 5-1", null, null], [1965, "丛雨", "「既然你的祖辈出现了，那这段记忆很可能被保存在了你爷爷传给你的那块碎片里」", "mur417_015.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "17"}, "CHAPTER 5-1", null, null], [1966, "丛雨", "「如何？有没有什么头绪？」", "mur417_016.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "22"}, "CHAPTER 5-1", null, null], [1967, "蕾娜", "「有了！我想起来了，梦里出现的那个人和我爷爷的爷爷年轻时的照片几乎一模一样」", "len417_036.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "15"}, "CHAPTER 5-1", null, null], [1968, "蕾娜", "「还有我爷爷的奶奶也是」", "len417_037.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "07"}, "CHAPTER 5-1", null, null], [1969, "", "这么一说，蕾娜说梦话的时候好像说过这些。", null, "旅館_レナの部屋a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "07"}, "CHAPTER 5-1", null, null], [1970, "将臣", "「不过，既然你见过他们的照片，他们出现在梦里也不算特别奇怪吧？」", null, "旅館_レナの部屋a", "bgm39.opus", null, "CHAPTER 5-1", null, null], [1971, "将臣", "「而且你不是北欧人吗？可梦里出现的那位列支敦瑙尔技师好像是德国人」", null, "旅館_レナの部屋a", "bgm39.opus", null, "CHAPTER 5-1", null, null], [1972, "蕾娜", "「是这样没错……但我家移民到现在所在的国家，刚好是我爷爷的爷爷那一辈的事情」", "len417_038.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "23"}, "CHAPTER 5-1", null, null], [1973, "将臣", "「啊？也就是说，在那之前你家都在德国吗？」", null, "旅館_レナの部屋a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "23"}, "CHAPTER 5-1", null, null], [1974, "蕾娜", "「唔，其实这个我也不清楚……但如果是德国的话，我觉得说得过去」", "len417_039.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "01"}, "CHAPTER 5-1", null, null], [1975, "丛雨", "「为什么这么说？」", "mur417_017.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "03"}, "CHAPTER 5-1", null, null], [1976, "蕾娜", "「因为列支敦瑙尔这个姓很像个德国姓氏」", "len417_040.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "03"}, "CHAPTER 5-1", null, null], [1977, "将臣", "「原来如此……这么说的话，小雨的猜测很有可能是真的」", null, "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "03"}, "CHAPTER 5-1", null, null], [1978, "丛雨", "「怎么了，主人？」", "mur417_018.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "10"}, "CHAPTER 5-1", null, null], [1979, "将臣", "「也有一种可能，就是祟神故意让我们做了这样的梦」", null, "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "10"}, "CHAPTER 5-1", null, null], [1980, "", "说到底，我跟蕾娜能身处同一个梦境，这就已经很不可思议了。", null, "旅館_レナの部屋a", "bgm39.opus", null, "CHAPTER 5-1", null, null], [1981, "", "所以不管发生什么都不算奇怪。", null, "旅館_レナの部屋a", "bgm39.opus", null, "CHAPTER 5-1", null, null], [1982, "", "不过，蕾娜之前被操控时，祟神将她拉入了梦境显然是故意的。", null, "旅館_レナの部屋a", "bgm39.opus", null, "CHAPTER 5-1", null, null], [1983, "将臣", "「外公你听说过吗？穗织以前也有过通蒸汽火车的计划」", null, "旅館_レナの部屋a", "bgm39.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "05"}, "CHAPTER 5-1", null, null], [1984, "将臣", "「当时还有德国人在志那都庄住过一段时间」", null, "旅館_レナの部屋a", "bgm39.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "05"}, "CHAPTER 5-1", null, null], [1985, "玄十郎", "「唔，这些都是列支敦瑙尔小姐的高祖父年轻时候的事情吧？」", "gen417_011.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "09"}, "CHAPTER 5-1", null, null], [1986, "玄十郎", "「也就是说，当时我肯定还没有出生」", "gen417_012.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "17"}, "CHAPTER 5-1", null, null], [1987, "", "啊，这么一想，这确实是很久之前的事了。", null, "旅館_レナの部屋a", "bgm39.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "17"}, "CHAPTER 5-1", null, null], [1988, "玄十郎", "「不过，改善穗织交通状况的计划，应该有过不少次」", "gen417_013.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "09"}, "CHAPTER 5-1", null, null], [1989, "玄十郎", "「其中说不定就有修铁路的计划」", "gen417_014.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "05"}, "CHAPTER 5-1", null, null], [1990, "玄十郎", "「但是……至于当时有没有外国人在志那都庄住过，我就不太清楚了」", "gen417_015.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "17"}, "CHAPTER 5-1", null, null], [1991, "丛雨", "「本座的记忆差不多也是这样」", "mur417_019.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "11"}, "CHAPTER 5-1", null, null], [1992, "蕾娜", "「对喔，小雨很久以前就在穗织了吧！」", "len417_041.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "11"}, "CHAPTER 5-1", null, null], [1993, "丛雨", "「嗯。在过去，时不时就会有些愚昧之徒想要开发穗织的森林」", "mur417_020.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "14"}, "CHAPTER 5-1", null, null], [1994, "丛雨", "「不过每一次，都会因穗织居民强烈的反对而以失败告终」", "mur417_021.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "10"}, "CHAPTER 5-1", null, null], [1995, "将臣", "「那有没有反对过给蒸汽火车修铁路的计划呢？这个你不记得了吗？」", null, "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "10"}, "CHAPTER 5-1", null, null], [1996, "丛雨", "「本座也不太确定。毕竟这些人间俗事与本座的职责并不相关」", "mur417_022.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "35"}, "CHAPTER 5-1", null, null], [1997, "丛雨", "「因此本座从来不主动干预这些事情」", "mur417_023.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "40"}, "CHAPTER 5-1", null, null], [1998, "", "梦境的舞台是穗织和志那都庄，这都是我熟悉的地方，可依然有一堆事情弄不明白。", null, "旅館_レナの部屋a", "bgm39.opus", null, "CHAPTER 5-1", null, null], [1999, "将臣", "「唔……仅仅只是一百多年前发生的事情，没想到现在就无从查证了」", null, "旅館_レナの部屋a", "bgm39.opus", null, "CHAPTER 5-1", null, null], [2000, "", "这真是无可奈何。", null, "旅館_レナの部屋a", "bgm39.opus", null, "CHAPTER 5-1", null, null], [2001, "丛雨", "「单凭本座的记忆，还有很多事情无法确定……但这梦境对我们来说，或许是一线希望」", "mur417_025.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "28"}, "CHAPTER 5-1", null, null], [2002, "蕾娜", "「什么意思呢？」", "len417_042.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "10"}, "CHAPTER 5-1", null, null], [2003, "丛雨", "「如果蕾娜和主人能再现宿体中残存的记忆」", "mur417_026.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "28"}, "CHAPTER 5-1", null, null], [2004, "丛雨", "「那些曾经的未解之谜，或许也就可以弄清了吧？」", "mur417_027.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "02"}, "CHAPTER 5-1", null, null], [2005, "将臣", "「啊，确实！」", null, "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "02"}, "CHAPTER 5-1", null, null], [2006, "丛雨", "「不过，你们之所以会做梦，八成是因为碎片聚合后力量增强了」", "mur417_028.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "10"}, "CHAPTER 5-1", null, null], [2007, "丛雨", "「所以你们一定得小心」", "mur417_029.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "26"}, "CHAPTER 5-1", null, null], [2008, "将臣", "「嗯……」", null, "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "26"}, "CHAPTER 5-1", null, null], [2009, "", "宿体的碎片分别被我和蕾娜的身体吸收了一部分。", null, "旅館_レナの部屋a", "bgm39.opus", null, "CHAPTER 5-1", null, null], [2010, "", "这到底是福还是祸？", null, "旅館_レナの部屋a", "bgm39.opus", null, "CHAPTER 5-1", null, null], [2011, "", "现在宿体碎片几乎已经全部聚合，也就是说我们可能会看到更多藏在其中的记忆。", null, "旅館_レナの部屋a", "bgm39.opus", null, "CHAPTER 5-1", null, null], [2012, "", "但相应地，危险性也会更大。", null, "旅館_レナの部屋a", "bgm39.opus", null, "CHAPTER 5-1", null, null], [2013, "丛雨", "「总之，我们得先调查ＳＬ的事，要尽快弄清它究竟是不是真正发生过的」", "mur417_030.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "11"}, "CHAPTER 5-1", null, null], [2014, "将臣", "「没错，依靠不明确的信息做判断还是很危险的」", null, "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "11"}, "CHAPTER 5-1", null, null], [2015, "", "我向外公说明了这些情况，拜托他帮助我们。", null, "旅館_レナの部屋a", "bgm39.opus", null, "CHAPTER 5-1", null, null], [2016, "玄十郎", "「既然如此，那我这边也来查查看吧……」", "gen417_016.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-1", null, null], [2017, "玄十郎", "「不过，你跟列支敦瑙尔小姐真的只是普通关系？」", "gen417_017.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-1", null, null], [2018, "将臣", "「喔，差点忘了，这件事可以让小雨来为我证明――啊不对，你看不见她」", null, "旅館_レナの部屋a", "bgm39.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-1", null, null], [2019, "玄十郎", "「没事，听你们说了那么多我大致明白了」", "gen417_018.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "09"}, "CHAPTER 5-1", null, null], [2020, "玄十郎", "「但如果这件事是碎片共鸣引起的，那么你很有可能再次干出这种类似半夜幽会的事情吧？」", "gen417_019.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "19"}, "CHAPTER 5-1", null, null], [2021, "玄十郎", "「我得想想，怎么跟旅馆的人说明这个情况……」", "gen417_020.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "17"}, "CHAPTER 5-1", null, null], [2022, "", "乍一听好像不是什么大不了的事，不过仔细想想确实不好说。", null, "旅館_レナの部屋a", "bgm39.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "17"}, "CHAPTER 5-1", null, null], [2023, "", "虽然我这个男生无所谓，但对蕾娜来说肯定是非常头疼的一件事。", null, "旅館_レナの部屋a", "bgm39.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "17"}, "CHAPTER 5-1", null, null], [2024, "将臣", "「对不起蕾娜，我可能会害得你在学校被大家议论」", null, "旅館_レナの部屋a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "34"}, "CHAPTER 5-1", null, null], [2025, "将臣", "「下次我睡觉的时候，我就找个柱子之类的东西，把自己绑在上面睡……」", null, "旅館_レナの部屋a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "34"}, "CHAPTER 5-1", null, null], [2026, "蕾娜", "「不、不用的！我也不好意思让你做到那个份上」", "len417_043.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "03"}, "CHAPTER 5-1", null, null], [2027, "蕾娜", "「都怪我叫得那么大声才把大家都招来了，现在我明白情况了，你再过来就不会那么吃惊了」", "len417_044.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "23"}, "CHAPTER 5-1", null, null], [2028, "将臣", "「可是……」", null, "旅館_レナの部屋a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "23"}, "CHAPTER 5-1", null, null], [2029, "蕾娜", "「而、而且，在梦里说不定可以知道很多目前不知道的事情吧？」", "len417_045.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "01"}, "CHAPTER 5-1", null, null], [2030, "蕾娜", "「那这对我们来说就很重要了，而且你来我的房间，我也不是……那么讨厌」", "len417_046.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "28"}, "CHAPTER 5-1", null, null], [2031, "蕾娜", "「今天晚上，我……我也会不锁门的」", "len417_047.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27h"}, "CHAPTER 5-1", null, null], [2032, "将臣", "「蕾娜…………嗯，我知道了」", null, "旅館_レナの部屋a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27h"}, "CHAPTER 5-1", null, null], [2033, "将臣", "「谢谢你」", null, "旅館_レナの部屋a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27h"}, "CHAPTER 5-1", null, null], [2034, "蕾娜", "「嘿嘿，那我就先去干活了，干完活之后我们一起去学校吧？」", "len417_048.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02"}, "CHAPTER 5-1", null, null], [2035, "将臣", "「好啊，那我等你」", null, "旅館_レナの部屋a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02"}, "CHAPTER 5-1", null, null], [2036, "蕾娜", "「好的！你先吃早饭吧」", "len417_049.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02"}, "CHAPTER 5-1", null, null], [2037, "", "蕾娜走出房门，转身向我挥手告别。紧接着，走廊就传来了她踩着碎步快速离开的声音。", null, "旅館_レナの部屋a", "bgm39.opus", null, "CHAPTER 5-1", null, null], [2038, "", "最终，我还是接受了蕾娜那温柔的善意。", null, "旅館_レナの部屋a", "bgm39.opus", null, "CHAPTER 5-1", null, null], [2039, "将臣", "「蕾娜真是个好人」", null, "旅館_レナの部屋a", "bgm39.opus", null, "CHAPTER 5-1", null, null], [2040, "丛雨", "「……嗯？」", "mur417_031.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "38"}, "CHAPTER 5-1", null, null], [2041, "玄十郎", "「什么？」", "gen417_021.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "08"}, "CHAPTER 5-1", null, null], [2042, "将臣", "「但就算她人再好，我也不能太得寸进尺，一些不该犯的错肯定还是不能犯的」", null, "旅館_レナの部屋a", "bgm39.opus", null, "CHAPTER 5-1", null, null], [2043, "", "可是在面对蕾娜那火辣的身材时，要想没有非分之想，真的很难做到……嗯？", null, "旅館_レナの部屋a", "bgm39.opus", null, "CHAPTER 5-1", null, null], [2044, "玄十郎", "「……」", "gen417_022.ogg", "旅館_レナの部屋a", "bgm25.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "11"}, "CHAPTER 5-1", null, null], [2045, "丛雨", "「……」", "mur417_032.ogg", "旅館_レナの部屋a", "bgm25.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "07"}, "CHAPTER 5-1", null, null], [2046, "将臣", "「怎么了，为什么你们都是一副无奈的表情？」", null, "旅館_レナの部屋a", "bgm25.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "07"}, "CHAPTER 5-1", null, null], [2047, "将臣", "「难道说我就那么不值得信任吗？」", null, "旅館_レナの部屋a", "bgm25.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "07"}, "CHAPTER 5-1", null, null], [2048, "玄十郎", "「不是，你要是不明白的就算了吧……这样可能更好一些」", "gen417_023.ogg", "旅館_レナの部屋a", "bgm25.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "17"}, "CHAPTER 5-1", null, null], [2049, "", "外公抱着胳膊离开了房间。", null, "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-1", null, null], [2050, "将臣", "「外公刚才的话到底是什么意思？」", null, "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-1", null, null], [2051, "丛雨", "「刚才的话嘛，本座只能这么告诉你」", "mur417_033.ogg", "旅館_レナの部屋a", "bgm25.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "29"}, "CHAPTER 5-1", null, null], [2052, "丛雨", "「有些时候，犯错并不是真正的犯错」", "mur417_034.ogg", "旅館_レナの部屋a", "bgm25.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "32"}, "CHAPTER 5-1", null, null], [2053, "", "小雨只留下了一句很有哲学意味的话就消失在了墙壁的另一侧。", null, "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-1", null, null], [2054, "将臣", "「啊？」", null, "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-1", null, null], [2055, "", "本来以为，大家责怪我的原因是我半夜跑到蕾娜房间来了。", null, "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-1", null, null], [2056, "", "但是看现在这气氛，好像我跑过来什么都没做反而才是最不应该的……", null, "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-1", null, null], [2057, "蕾娜", "「将臣～快点快点！」", "len417_050.ogg", "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-1", null, null], [2058, "将臣", "「啊，等我一下，蕾娜」", null, "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-1", null, null], [2059, "", "我小跑着追上蕾娜，和她并肩走在一起。", null, "街_通学路a", "bgm34.opus", null, "CHAPTER 5-1", null, null], [2060, "", "她忙完之后，我们就按照约定，一起走在上学的路上。", null, "街_通学路a", "bgm34.opus", null, "CHAPTER 5-1", null, null], [2061, "", "顺便一提，我的早饭是和志那都庄的工作人员们一起吃的员工餐。", null, "街_通学路a", "bgm34.opus", null, "CHAPTER 5-1", null, null], [2062, "", "廉太郎和小春似乎也从外公那里了解到了事情的经过。", null, "街_通学路a", "bgm34.opus", null, "CHAPTER 5-1", null, null], [2063, "", "不过，外公到底是怎么跟他们说的？", null, "街_通学路a", "bgm34.opus", null, "CHAPTER 5-1", null, null], [2064, "", "他们俩像是在顾虑什么，只说了句“抱歉打搅了”，就先出发去学校了。", null, "街_通学路a", "bgm34.opus", null, "CHAPTER 5-1", null, null], [2065, "将臣", "「哎呀，今天早上吓到你了，真是抱歉」", null, "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-1", null, null], [2066, "蕾娜", "「不用再道歉啦，都是我自己大惊小怪的，而且这也不是你的错」", "len417_051.ogg", "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 5-1", null, null], [2067, "蕾娜", "「会出现这种事，都是因为我们体内吸收了碎片吧？」", "len417_052.ogg", "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "23"}, "CHAPTER 5-1", null, null], [2068, "将臣", "「嗯，应该是。虽然平常感觉不到有什么影响」", null, "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "23"}, "CHAPTER 5-1", null, null], [2069, "", "说真的，感觉就像抱着一颗小小的炸弹一样。", null, "街_通学路a", "bgm34.opus", null, "CHAPTER 5-1", null, null], [2070, "", "如果装上自爆装置的仿生人能梦到电动羊，那他们的心情会不会跟我现在一样呢？", null, "街_通学路a", "bgm34.opus", null, "CHAPTER 5-1", null, null], [2071, "将臣", "「蕾娜，你不会觉得不安吗？」", null, "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "23"}, "CHAPTER 5-1", null, null], [2072, "蕾娜", "「这个嘛，可能是因为我最近才知道诅咒和宿体的事情吧」", "len417_053.ogg", "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "30"}, "CHAPTER 5-1", null, null], [2073, "蕾娜", "「从我的角度来说，我并没有觉得宿体的碎片是多么不祥的东西」", "len417_054.ogg", "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 5-1", null, null], [2074, "将臣", "「你以前好像也说过类似的话」", null, "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 5-1", null, null], [2075, "", "尽管只是以梦境的形式，但碎片已经对身体产生了明确的影响。", null, "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 5-1", null, null], [2076, "", "事到如今，她对碎片的看法依然和以前一样吗？", null, "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 5-1", null, null], [2077, "蕾娜", "「对我来说，碎片本来就像护身符一样」", "len417_055.ogg", "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "26"}, "CHAPTER 5-1", null, null], [2078, "蕾娜", "「也是多亏了它，我才能在梦里了解到爷爷的爷爷经历过的事情！」", "len417_056.ogg", "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-1", null, null], [2079, "蕾娜", "「虽然很意外，但我很开心」", "len417_057.ogg", "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 5-1", null, null], [2080, "将臣", "「你的想法好乐观啊」", null, "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 5-1", null, null], [2081, "蕾娜", "「哈哈，将臣，这种事情再怎么担心也没用啊！」", "len417_058.ogg", "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "23"}, "CHAPTER 5-1", null, null], [2082, "蕾娜", "「日本不是有句俗话说，有富之人不用忙嘛」", "len417_059.ogg", "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-1", null, null], [2083, "将臣", "「你是说，有福之人不用忙吧？」", null, "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-1", null, null], [2084, "蕾娜", "「喔、喔……有富……有褔……有褔！我记住了」", "len417_060.ogg", "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-1", null, null], [2085, "", "这下又教会了她一个常识。", null, "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-1", null, null], [2086, "蕾娜", "「不过，身体吸收了碎片，也并不是只有坏处吧？」", "len417_061.ogg", "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "18"}, "CHAPTER 5-1", null, null], [2087, "将臣", "「确实，我正是因为吸收了碎片才能和大家相遇，才能像今天这样和你一起上学」", null, "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "18"}, "CHAPTER 5-1", null, null], [2088, "将臣", "「我很满意现在的生活。但是……」", null, "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "18"}, "CHAPTER 5-1", null, null], [2089, "将臣", "「我还是很担心。宿体的碎片会孕育出祟神，所以我对它抱有很深的负面印象」", null, "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "20"}, "CHAPTER 5-1", null, null], [2090, "将臣", "「而且，关于宿体的来龙去脉，我们知道的实在是太少了」", null, "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "20"}, "CHAPTER 5-1", null, null], [2091, "蕾娜", "「喔，感觉你考虑得好多呀，真的很厉害！」", "len417_064.ogg", "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-1", null, null], [2092, "将臣", "「哪里，我反倒羡慕你那乐观积极的态度呢」", null, "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-1", null, null], [2093, "蕾娜", "「是吗？」", "len417_065.ogg", "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "34"}, "CHAPTER 5-1", null, null], [2094, "将臣", "「我只是想得多而已，并没有解决问题的知识和智慧」", null, "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "34"}, "CHAPTER 5-1", null, null], [2095, "将臣", "「要想找到答案，最后还是只能麻烦身边的人」", null, "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "34"}, "CHAPTER 5-1", null, null], [2096, "", "既然如此，还是像蕾娜这样时刻挂着笑容比较好，这样大家应该也会更轻松一些吧？", null, "街_通学路a", "bgm34.opus", null, "CHAPTER 5-1", null, null], [2097, "", "不像我，动不动就让别人担心。", null, "街_通学路a", "bgm34.opus", null, "CHAPTER 5-1", null, null], [2098, "将臣", "「简单来说，这种时候还是抱着天不怕地不怕的态度比较好」", null, "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "34"}, "CHAPTER 5-1", null, null], [2099, "将臣", "「就像你现在这样。你现在的状态我就很放心」", null, "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "34"}, "CHAPTER 5-1", null, null], [2100, "蕾娜", "「嗯，嘿嘿……那你可要多向我学习哦，将臣」", "len417_066.ogg", "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-1", null, null], [2101, "", "蕾娜再一次若无其事地牵住了我的手。", null, "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-1", null, null], [2102, "", "光是牵着手，就让我的心跳加快了不少。", null, "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-1", null, null], [2103, "", "昨天因为我躲开了她的拥抱，弄得气氛有些尴尬。", null, "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-1", null, null], [2104, "", "所以，今天我就坦率地接受吧。", null, "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-1", null, null], [2105, "将臣", "「对了，你是哪个国家的来着？」", null, "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-1", null, null], [2106, "蕾娜", "「嗯？你问我的国家吗」", "len417_067.ogg", "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "20"}, "CHAPTER 5-1", null, null], [2107, "将臣", "「嗯，刚才提到了你高祖父的事情，我就有点在意」", null, "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "20"}, "CHAPTER 5-1", null, null], [2108, "将臣", "「他本来是日本人，后来去了德国，最后定居在了北欧是吧？」", null, "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "20"}, "CHAPTER 5-1", null, null], [2109, "蕾娜", "「啊，其实我并不是很了解……我也挺想知道他为什么会定居北欧」", "len417_068.ogg", "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "31"}, "CHAPTER 5-1", null, null], [2110, "将臣", "「反正，你的祖国肯定是个很棒的地方吧？」", null, "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "31"}, "CHAPTER 5-1", null, null], [2111, "将臣", "「会让人忍不住想要定居在那里」", null, "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "34"}, "CHAPTER 5-1", null, null], [2112, "蕾娜", "「哈哈哈，冬天的气温可在零下３０℃以下呢」", "len417_069.ogg", "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "28"}, "CHAPTER 5-1", null, null], [2113, "将臣", "「零、零下，三十度！？」", null, "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "28"}, "CHAPTER 5-1", null, null], [2114, "", "真的假的？这么低的温度，都能用香蕉钉钉子了吧？", null, "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 5-1", null, null], [2115, "", "没想到北欧冷成这样。", null, "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 5-1", null, null], [2116, "蕾娜", "「我老家的村子在拉普兰地区……日语里面，好像是叫北极圈来着？反正是相当偏北的地方」", "len417_070.ogg", "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "17"}, "CHAPTER 5-1", null, null], [2117, "将臣", "「喔，那么远啊，远得我都无法想象」", null, "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "17"}, "CHAPTER 5-1", null, null], [2118, "蕾娜", "「像日本这样一年四季太阳都会照常升起落下，我以前也无法想象」", "len417_071.ogg", "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "03"}, "CHAPTER 5-1", null, null], [2119, "将臣", "「也是，毕竟是北极圈」", null, "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "03"}, "CHAPTER 5-1", null, null], [2120, "", "越说越觉得难以想象了。", null, "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "03"}, "CHAPTER 5-1", null, null], [2121, "蕾娜", "「是的，所以如果要用一句话来概括我的国家……我想想……」", "len417_072.ogg", "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "09"}, "CHAPTER 5-1", null, null], [2122, "蕾娜", "「应该称得上是极光之国了」", "len417_073.ogg", "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-1", null, null], [2123, "将臣", "「啊，你这么说的话我就可以想象了！」", null, "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-1", null, null], [2124, "", "仅仅只是换了个说法，我就感觉那片土地不再遥远，虽然这八成是我的错觉。", null, "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-1", null, null], [2125, "蕾娜", "「夏天的时候，有美丽的森林湖泊和好吃的浆果」", "len417_074.ogg", "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-1", null, null], [2126, "蕾娜", "「不过我最喜欢的，是冬天的北极光！」", "len417_075.ogg", "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-1", null, null], [2127, "将臣", "「哇，说得我也想看一看了」", null, "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-1", null, null], [2128, "蕾娜", "「我也希望有朝一日，能和你一起去我故乡」", "len417_076.ogg", "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-1", null, null], [2129, "蕾娜", "「一起去看北极光……」", "len417_077.ogg", "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "03"}, "CHAPTER 5-1", null, null], [2130, "将臣", "「啊」", null, "学院_学院前a", "bgm34.opus", null, "CHAPTER 5-1", null, null], [2131, "", "走到学校的时候，正好看见了朝武和常陆走在前面。", null, "学院_学院前a", "bgm34.opus", null, "CHAPTER 5-1", null, null], [2132, "", "这种时候还是松开手比较好吧……哎？", null, "学院_学院前a", "bgm34.opus", null, "CHAPTER 5-1", null, null], [2133, "", "我刚想松开手的时候，蕾娜反而用力地握紧了我的手。", null, "学院_学院前a", "bgm34.opus", null, "CHAPTER 5-1", null, null], [2134, "蕾娜", "「哼」", "len417_078.ogg", "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "09"}, "CHAPTER 5-1", null, null], [2135, "", "咦，她生气了吗？刚才她不是还很高兴吗？", null, "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "09"}, "CHAPTER 5-1", null, null], [2136, "", "不过下一秒，她就一下子把手放开了。", null, "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "09"}, "CHAPTER 5-1", null, null], [2137, "蕾娜", "「芳乃！茉子，早上好！」", "len417_079.ogg", "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-1", null, null], [2138, "芳乃", "「蕾娜？……有地也在啊，早上好」", "yos417_001.ogg", "学院_学院前a", "bgm34.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "22"}, "CHAPTER 5-1", null, null], [2139, "茉子", "「两位是直接从志那都庄走到学校来的吗？」", "mak417_001.ogg", "学院_学院前a", "bgm34.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-1", null, null], [2140, "茉子", "「丛雨大人刚才告诉我们了，她说你们好像又梦到了什么？」", "mak417_002.ogg", "学院_学院前a", "bgm34.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "12"}, "CHAPTER 5-1", null, null], [2141, "将臣", "「啊，嗯，这事得跟你们详细说说……」", null, "学院_学院前a", "bgm34.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "12"}, "CHAPTER 5-1", null, null], [2142, "", "我偷偷地看了蕾娜一眼。", null, "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-1", null, null], [2143, "", "不过，她已经变成了平常的样子。", null, "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-1", null, null], [2144, "", "她刚才那副生气的样子，会不会是我看错了？", null, "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-1", null, null], [2145, "", "我和将臣的邂逅――", null, "空_青空", "bgm54.opus", null, "CHAPTER 5-1", null, null], [2146, "蕾娜", "「哈哇——————！请、请让开——————！」", "len006_001_ref.ogg", "空_青空", "bgm54.opus", null, "CHAPTER 5-1", null, null], [2147, "将臣", "「唔哇啊啊啊啊啊啊啊啊！？」", null, "空_青空", "bgm54.opus", null, "CHAPTER 5-1", null, null], [2148, "", "从各种意义上来说都极具冲击力。", null, "空_青空", "bgm54.opus", null, "CHAPTER 5-1", null, null], [2149, "", "当时我被行李箱一路拖下坡道，狠狠地撞在了将臣身上。", null, "空_青空", "bgm54.opus", null, "CHAPTER 5-1", null, null], [2150, "", "可是他完全没有冲我发火。", null, "空_青空", "bgm54.opus", null, "CHAPTER 5-1", null, null], [2151, "", "不仅没发火，反而一直在对我说抱歉、谢谢。", null, "空_青空", "bgm54.opus", null, "CHAPTER 5-1", null, null], [2152, "", "……说实话，当时我是孤身一人来到日本，心里有几分期待，就会有几分不安。", null, "空_青空", "bgm54.opus", null, "CHAPTER 5-1", null, null], [2153, "", "但幸运的是，我在日本认识的第一个人，是个特别温柔的男生，这让我非常有安全感。", null, "空_青空", "bgm54.opus", null, "CHAPTER 5-1", null, null], [2154, "", "我的第一印象并没有错，将臣的确是个对谁都很温柔的男生。", null, "街_目抜き通りa", "bgm54.opus", null, "CHAPTER 5-1", null, null], [2155, "", "能和将臣成为朋友，我非常很开心。", null, "街_目抜き通りa", "bgm54.opus", null, "CHAPTER 5-1", null, null], [2156, "", "不过……当时他对我来说还只是个普通朋友。", null, "街_目抜き通りa", "bgm54.opus", null, "CHAPTER 5-1", null, null], [2157, "", "直到后来――", null, "街_診療所（壊）", "bgm54.opus", null, "CHAPTER 5-1", null, null], [2158, "将臣", "「总之蕾娜你自己先逃走吧！」", null, "街_診療所（壊）", "bgm54.opus", null, "CHAPTER 5-1", null, null], [2159, "蕾娜", "「哎！？我、我完全搞不清状况——」", "len011_030_ref.ogg", "街_診療所（壊）", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "20"}, "CHAPTER 5-1", null, null], [2160, "蕾娜", "「呀！？」", "len011_031_ref.ogg", "街_診療所（壊）", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "14"}, "CHAPTER 5-1", null, null], [2161, "", "我第一次被祟神袭击的时候，是将臣保护了被吓得双腿发软的我。", null, "街_診療所（壊）", "bgm54.opus", null, "CHAPTER 5-1", null, null], [2162, "", "那时他孤身一人对抗祟神，勇敢的身姿与平时温柔的他简直判若两人。", null, "街_診療所（壊）", "bgm54.opus", null, "CHAPTER 5-1", null, null], [2163, "", "后来，当我知道他其实是剑道达人（？）的时候，我真的十分惊讶。", null, "街_診療所（壊）", "bgm54.opus", null, "CHAPTER 5-1", null, null], [2164, "", "在我们国家，并没有他这种类型的男孩子。", null, "街_診療所（壊）", "bgm54.opus", null, "CHAPTER 5-1", null, null], [2165, "", "我们那里的男生都是些硬汉，而且总是想方设法地向女生炫耀自己的男子气概。", null, "街_診療所（壊）", "bgm54.opus", null, "CHAPTER 5-1", null, null], [2166, "", "将臣就绝对不会做这种事。", null, "街_診療所（壊）", "bgm54.opus", null, "CHAPTER 5-1", null, null], [2167, "", "他很谦虚，经常会说自己还差得远。", null, "街_診療所（壊）", "bgm54.opus", null, "CHAPTER 5-1", null, null], [2168, "", "日本人这种谦和而文雅的性格……让我觉得非常可靠，非常帅气。", null, "街_診療所（壊）", "bgm54.opus", null, "CHAPTER 5-1", null, null], [2169, "", "我记得……", null, "街_診療所（壊）", "bgm54.opus", null, "CHAPTER 5-1", null, null], [2170, "", "在诊所的那个时候，祟神袭击的目标是我。", null, "街_診療所（壊）", "bgm54.opus", null, "CHAPTER 5-1", null, null], [2171, "", "本以为这是因为我身上带着碎片，但好像也不仅仅是这个原因？", null, "街_診療所（壊）", "bgm54.opus", null, "CHAPTER 5-1", null, null], [2172, "", "因为在那之后，祟神又一次试图攻击我。", null, "山_川沿いc", "bgm54.opus", null, "CHAPTER 5-1", null, null], [2173, "", "这一次，也是将臣保护了我。", null, "山_川沿いc", "bgm54.opus", null, "CHAPTER 5-1", null, null], [2174, "将臣", "「别碰她！你这畜生！！」", null, "山_川沿いc", "bgm54.opus", null, "CHAPTER 5-1", null, null], [2175, "蕾娜", "「将……将臣？将臣！？」", "len414_119_ref.ogg", "山_川沿いc", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "06"}, "CHAPTER 5-1", null, null], [2176, "", "尽管祟神比自己高了好几个脑袋，将臣也依然毫不畏惧地挡在我身前。看着他那持刀相向的背影——", null, "山_川沿いc", "bgm54.opus", null, "CHAPTER 5-1", null, null], [2177, "", "我就想，这次我一定要帮他。", null, "山_川沿いc", "bgm54.opus", null, "CHAPTER 5-1", null, null], [2178, "蕾娜", "「好疼啊啊啊啊啊！？这、这是什么，好疼啊」", "len414_120_ref.ogg", "山_川沿いc", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "22"}, "CHAPTER 5-1", null, null], [2179, "将臣", "「蕾……蕾娜，你不要握上来！」", null, "山_川沿いc", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "22"}, "CHAPTER 5-1", null, null], [2180, "", "忍着那样的剧痛，他既没有叫苦，也从不摆出一副恩人的态度。", null, "山_川沿いc", "bgm54.opus", null, "CHAPTER 5-1", null, null], [2181, "", "将臣他，只是一心想要救我而已。", null, "山_川沿いc", "bgm54.opus", null, "CHAPTER 5-1", null, null], [2182, "", "剑道达人，克己奉公……他做什么事都拼尽全力……他一定是个武士。", null, "山_川沿いc", "bgm54.opus", null, "CHAPTER 5-1", null, null], [2183, "", "至少对我来说，他是一位武士。", null, "山_川沿いc", "bgm54.opus", null, "CHAPTER 5-1", null, null], [2184, "", "他是……我的武士。", null, "山_川沿いc", "bgm54.opus", null, "CHAPTER 5-1", null, null], [2185, "", "不过，让我有点苦恼的是，这位武士对谁都很温柔。", null, "朝武_自室a", "bgm54.opus", null, "CHAPTER 5-1", null, null], [2186, "", "当然了！我知道这也是他的优点。", null, "朝武_自室a", "bgm54.opus", null, "CHAPTER 5-1", null, null], [2187, "", "而且他这个优点……本来就是最吸引我的地方。", null, "朝武_自室a", "bgm54.opus", null, "CHAPTER 5-1", null, null], [2188, "", "但是现在，他要是只对我一个人温柔就好了……我不禁这样想。", null, "朝武_自室a", "bgm54.opus", null, "CHAPTER 5-1", null, null], [2189, "蕾娜", "「能、能把将臣稍微借我一下吗？」", "len415_059_ref.ogg", "神社_境内a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "29"}, "CHAPTER 5-1", null, null], [2190, "将臣", "「有什么事……哎！？！？」", null, "神社_境内a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "29"}, "CHAPTER 5-1", null, null], [2191, "", "所以在那个时候，我鼓起勇气握住了他的手。", null, "神社_境内a", "bgm54.opus", null, "CHAPTER 5-1", null, null], [2192, "", "那是我第一次握他的手……当时我紧张得腿一直在发抖，真的特别特别害羞。", null, "神社_境内a", "bgm54.opus", null, "CHAPTER 5-1", null, null], [2193, "", "不过对我来说，这么做已经耗尽了我全部的勇气。", null, "神社_境内a", "bgm54.opus", null, "CHAPTER 5-1", null, null], [2194, "", "不这么做的话，我一个外国人，根本就比不过其他女生……", null, "神社_境内a", "bgm54.opus", null, "CHAPTER 5-1", null, null], [2195, "", "实际上，他最近每天陪在我身边，肯定也只是因为担心我出事而已。", null, "神社_境内a", "bgm54.opus", null, "CHAPTER 5-1", null, null], [2196, "", "因为他虽然不会刻意甩开我的手，但他也绝不会主动握紧我的手。", null, "街_通学路a", "bgm54.opus", null, "CHAPTER 5-1", null, null], [2197, "", "刚才他看见芳乃和茉子走在前面，立马就想松开手。", null, "街_通学路a", "bgm54.opus", null, "CHAPTER 5-1", null, null], [2198, "", "我知道，他并不是有其他中意的女孩子，也不是讨厌我。", null, "街_通学路a", "bgm54.opus", null, "CHAPTER 5-1", null, null], [2199, "", "他大概是担心我会被其他人误会。", null, "街_通学路a", "bgm54.opus", null, "CHAPTER 5-1", null, null], [2200, "蕾娜", "「（可这也不是误会啊！）」", "len417_086.ogg", "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "18"}, "CHAPTER 5-1", null, null], [2201, "蕾娜", "「（他昨晚跑到我房间来，竟然连我的一根手指都没碰！！）」", "len417_087.ogg", "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "31"}, "CHAPTER 5-1", null, null], [2202, "蕾娜", "「（这种时候，我就会……稍微有点讨厌他）」", "len417_088.ogg", "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "29"}, "CHAPTER 5-1", null, null], [2203, "蕾娜", "「（……但是，这并不是真正的讨厌……）」", "len417_089.ogg", "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "06"}, "CHAPTER 5-1", null, null], [2204, "", "之前我的身体把整个宿体都吸收了。", null, "街_通学路a", "bgm54.opus", null, "CHAPTER 5-1", null, null], [2205, "", "说实话，我自己也多少有点担心。", null, "街_通学路a", "bgm54.opus", null, "CHAPTER 5-1", null, null], [2206, "", "当然，我并没有说谎。我确实没觉得碎片是多么不祥的东西。", null, "街_通学路a", "bgm54.opus", null, "CHAPTER 5-1", null, null], [2207, "", "如果在将臣的眼里，我看上去非常积极乐观……", null, "街_通学路a", "bgm54.opus", null, "CHAPTER 5-1", null, null], [2208, "", "那一定是因为，我心里觉得自己有点走运。", null, "街_通学路a", "bgm54.opus", null, "CHAPTER 5-1", null, null], [2209, "", "我知道，在碎片的问题解决之前，将臣很可能会一直陪在我的身边。", null, "街_通学路a", "bgm54.opus", null, "CHAPTER 5-1", null, null], [2210, "", "我知道，他就是这种性格的人……", null, "街_通学路a", "bgm54.opus", null, "CHAPTER 5-1", null, null], [2211, "", "我好像心眼儿挺多的。", null, "街_通学路a", "bgm54.opus", null, "CHAPTER 5-1", null, null], [2212, "", "不过，多就多吧，只要能让将臣陪在我身边……", null, "学院_教室休憩a", "bgm54.opus", null, "CHAPTER 5-1", null, null], [2213, "", "啊……到底该怎么做，才能让将臣更加关注我呢？", null, "学院_教室休憩a", "bgm54.opus", null, "CHAPTER 5-1", null, null], [2214, "蕾娜", "「…………唉～」", "len417_090.ogg", "学院_教室休憩a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "29"}, "CHAPTER 5-1", null, null], [2215, "将臣", "「？」", null, "学院_教室休憩a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "29"}, "CHAPTER 5-1", null, null], [2216, "茉子", "「现在我宣布――」", "mak417_003.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "10"}, "CHAPTER 5-1", null, null], [2217, "茉子", "「第２届“蕾娜·列支敦瑙尔对日本之误会何其多研讨大会”正式开始」", "mak417_004.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "21"}, "CHAPTER 5-1", null, null], [2218, "蕾娜", "「今天又要请大家多多指教啦！」", "len417_091.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-1", null, null], [2219, "将臣", "「哎，还要继续开么？」", null, "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 5-1", null, null], [2220, "茉子", "「哈哈，常识这个东西哪里是一朝一夕就能学会的？」", "mak417_005.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "46"}, "CHAPTER 5-1", null, null], [2221, "蕾娜", "「没错！警察就是力量，对吧将臣？」", "len417_092.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "46"}, "CHAPTER 5-1", null, null], [2222, "将臣", "「警察？坚持就是力量吧？」", null, "学院_教室休憩a", "bgm44.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "46"}, "CHAPTER 5-1", null, null], [2223, "蕾娜", "「喔、喔，坚持？是坚持啊，我记住了」", "len417_093.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-1", null, null], [2224, "", "好吧，看来我们确实得继续教她才行。", null, "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-1", null, null], [2225, "茉子", "「你可是答应过了猪谷阿姨，总不能教完相扑的常识就算教完了吧」", "mak417_006.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "34"}, "CHAPTER 5-1", null, null], [2226, "廉太郎", "「哈哈哈！就是昨天那个发狂、生气啦来着？确实不能只教这些就完事」", "ren417_011.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "28"}, "CHAPTER 5-1", null, null], [2227, "蕾娜", "「廉哥你真是的，反正你除了这些什么都记不得了吧？」", "koh417_008.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "35"}, "CHAPTER 5-1", null, null], [2228, "廉太郎", "「才不是，我还记得教了些别的东西……还教过什么来着？」", "ren417_012.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "13"}, "CHAPTER 5-1", null, null], [2229, "蕾娜", "「还教了Ｈａｋｋｅｙｏｉ，Ｎｏｋｏｔｔａ是从那什么词演变来的…………咦？」", "koh417_009.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "31"}, "CHAPTER 5-1", null, null], [2230, "", "果不其然，他们俩除了发狂、生气啦，其它的都不记得了。", null, "学院_教室休憩a", "bgm44.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "31"}, "CHAPTER 5-1", null, null], [2231, "", "其实我也想不起来了。", null, "学院_教室休憩a", "bgm44.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "31"}, "CHAPTER 5-1", null, null], [2232, "芳乃", "「是发挥扬扬」", "yos417_002.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "27"}, "CHAPTER 5-1", null, null], [2233, "廉太郎", "「啊！对了对了，想起来了」", "ren417_013.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-1", null, null], [2234, "将臣", "「我记得你说相扑起源于祭神仪式，所以你也很了解吧？」", null, "学院_教室休憩a", "bgm44.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-1", null, null], [2235, "蕾娜", "「芳乃不愧是巫女大人啊！」", "len417_094.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-1", null, null], [2236, "芳乃", "「哎……嗯，哈哈，这点小事都是常识啦」", "yos417_003.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "21"}, "CHAPTER 5-1", null, null], [2237, "蕾娜", "「那、那这个词的意思，巫女大人能再讲讲吗？」", "koh417_010.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "07"}, "CHAPTER 5-1", null, null], [2238, "芳乃", "「好的，发挥扬扬这个词，指的就是在相扑开始前……………………呃，哎？」", "yos417_004.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "15"}, "CHAPTER 5-1", null, null], [2239, "将臣", "「怎么了？」", null, "学院_教室休憩a", "bgm44.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "15"}, "CHAPTER 5-1", null, null], [2240, "芳乃", "「奇怪了，我、我应该是知道的啊。只是，有点想不起来了」", "yos417_005.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "16"}, "CHAPTER 5-1", null, null], [2241, "芳乃", "「蕾娜说的发狂、生气啦从脑海中闪过之后，其他的事情就都想不起来了……到底是什么意思来着？」", "yos417_006.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "30"}, "CHAPTER 5-1", null, null], [2242, "", "本来知道的东西都给忘掉了，发狂、生气啦真是太恐怖了。", null, "学院_教室休憩a", "bgm44.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "30"}, "CHAPTER 5-1", null, null], [2243, "蕾娜", "「是打起精神继续加油的意思，不是吗？」", "len417_095.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-1", null, null], [2244, "将臣", "「啊，好像确实是这个意思！」", null, "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-1", null, null], [2245, "茉子", "「真是的，我们本来是教蕾娜常识的，现在反而变成人家教我们了」", "mak417_007.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "13"}, "CHAPTER 5-1", null, null], [2246, "茉子", "「尤其是芳乃大人。您刚才一脸自信地说，这都是常识啦，结果不还是忘了吗？」", "mak417_008.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "22"}, "CHAPTER 5-1", null, null], [2247, "芳乃", "「呜呜呜，对不起，我太得意忘形了……我现在都快羞死了，真想找个洞钻进去」", "yos417_007.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "16h"}, "CHAPTER 5-1", null, null], [2248, "蕾娜", "「没事啦，芳乃。谁都有失误的时候」", "len417_096.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "16h"}, "CHAPTER 5-1", null, null], [2249, "芳乃", "「谢谢你，蕾娜……」", "yos417_008.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "24n"}, "CHAPTER 5-1", null, null], [2250, "", "朝武两手遮脸，蕾娜在旁边摸着头安慰她。", null, "学院_教室休憩a", "bgm44.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "24n"}, "CHAPTER 5-1", null, null], [2251, "", "我们班的女生关系真不错。", null, "学院_教室休憩a", "bgm44.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "24n"}, "CHAPTER 5-1", null, null], [2252, "茉子", "「好了，复习就先到这里，接下来进入今天的主题」", "mak417_009.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-1", null, null], [2253, "将臣", "「你每次都会准备新的主题吗？」", null, "学院_教室休憩a", "bgm44.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-1", null, null], [2254, "茉子", "「是的，这次的主题是猪谷阿姨直接拜托我安排的」", "mak417_010.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-1", null, null], [2255, "", "常陆翻开了她提前准备好的图表。", null, "学院_教室休憩a", "bgm44.opus", null, "CHAPTER 5-1", null, null], [2256, "", "『词头加御的词汇』", null, "学院_教室休憩a", "bgm44.opus", null, "CHAPTER 5-1", null, null], [2257, "将臣", "「……御？」", null, "学院_教室休憩a", "bgm44.opus", null, "CHAPTER 5-1", null, null], [2258, "茉子", "「大部分日语词汇，只要开头加了御，就会显得很礼貌、很郑重吧？」", "mak417_011.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-1", null, null], [2259, "蕾娜", "「啊，比如点心、馒头、还有砂糖之类的？」", "koh417_011.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-1", null, null], [2260, "廉太郎", "「……怎么全都是些甜食」", "ren417_014.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "06"}, "CHAPTER 5-1", null, null], [2261, "蕾娜", "「我、我才不是一下子就想到了这些呢」", "koh417_012.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "11"}, "CHAPTER 5-1", null, null], [2262, "蕾娜", "「好啦好啦。不过掌柜的真是一针见血呀，我确实觉得这些词都很不可思议」", "len417_097.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-1", null, null], [2263, "芳乃", "「说起来，我记得外语里面好像都是没有敬语的吧？」", "yos417_009.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-1", null, null], [2264, "蕾娜", "「也有这方面的原因……举个例子吧，我第一次听到“御臀”这个词的时候，就特别吃惊」", "len417_098.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-1", null, null], [2265, "将臣", "「哎？为什么啊？」", null, "学院_教室休憩a", "bgm44.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-1", null, null], [2266, "蕾娜", "「不只是我们国家，在整个欧洲，屁股这个词都没有什么好的含义」", "len417_099.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "30"}, "CHAPTER 5-1", null, null], [2267, "廉太郎", "「啊，好像确实，好莱坞的电影里，就有“我发誓我会用我的靴子狠狠地踢你的屁股”之类的台词吧？」", "ren417_015.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-1", null, null], [2268, "将臣", "「喔，英语好像是Kick-Ass？感觉屁股这个词确实经常在一些骂人的句子里出现」", null, "学院_教室休憩a", "bgm44.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-1", null, null], [2269, "蕾娜", "「没错！可是日本人却会用御臀这种说法来郑重地表达」", "len417_100.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-1", null, null], [2270, "蕾娜", "「从这里我就体会到了日本文化中的侘寂，还有文雅谦和之心！」", "len417_101.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-1", null, null], [2271, "", "还能从这么清奇的角度来解释，我也是很佩服她。", null, "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-1", null, null], [2272, "将臣", "「仔细想想，洗手间、厕所之类的词也有在前面加“御”的说法」", null, "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-1", null, null], [2273, "将臣", "「哪怕是一些听上去不太文雅的事物或者外来语，也可能会在词头加“御”来郑重地表达吧？」", null, "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-1", null, null], [2274, "蕾娜", "「还有笨蛋、粗俗之类的词，加上“御”之后跟原来一比就没那么刺耳了吧？」", "koh417_013.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "13"}, "CHAPTER 5-1", null, null], [2275, "芳乃", "「可是，有些词加了“御”之后反而会听起来有点奇怪吧？」", "yos417_010.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-1", null, null], [2276, "芳乃", "「“蔬菜”前面可以加“御”，但是胡萝卜、菠菜前面加“御”就很奇怪了」", "yos417_011.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "10"}, "CHAPTER 5-1", null, null], [2277, "茉子", "「不过，大葱前面加“御”好像又挺常见的」", "mak417_012.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "13"}, "CHAPTER 5-1", null, null], [2278, "廉太郎", "「确实……话说，加不加“御”的标准到底是什么啊？」", "ren417_016.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "13"}, "CHAPTER 5-1", null, null], [2279, "", "大家都抱着胳膊陷入了沉思。", null, "学院_教室休憩a", "bgm44.opus", null, "CHAPTER 5-1", null, null], [2280, "将臣", "「唔，既然连日本人都是一知半解」", null, "学院_教室休憩a", "bgm44.opus", null, "CHAPTER 5-1", null, null], [2281, "将臣", "「也就是说，这些差异对外国人来说应该是非常难的吧？」", null, "学院_教室休憩a", "bgm44.opus", null, "CHAPTER 5-1", null, null], [2282, "蕾娜", "「这些平常用惯了的词，让我们解释还真解释不清楚」", "koh417_014.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "15"}, "CHAPTER 5-1", null, null], [2283, "蕾娜", "「我以前上日语学校时，像是“御馒头”和馒头，“御大葱”和大葱这些词汇」", "len417_102.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "23"}, "CHAPTER 5-1", null, null], [2284, "蕾娜", "「老师都让我们当做不一样的词汇记下来」", "len417_103.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-1", null, null], [2285, "将臣", "「啊，果然得这么学啊」", null, "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-1", null, null], [2286, "", "只能一个一个分开来记吗？", null, "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-1", null, null], [2287, "", "那记起来真是不容易啊。", null, "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-1", null, null], [2288, "茉子", "「今天咱们也教得差不多了，蕾娜，猪谷阿姨让我转告你，说希望你放学后能去帮忙买点东西」", "mak417_013.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "27"}, "CHAPTER 5-1", null, null], [2289, "蕾娜", "「让我去买东西呀！」", "len417_104.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-1", null, null], [2290, "将臣", "「等一下，为什么要让她去买东西？」", null, "学院_教室休憩a", "bgm44.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-1", null, null], [2291, "将臣", "「我感觉那些加“御”的词汇，她用得都挺熟练的吧」", null, "学院_教室休憩a", "bgm44.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-1", null, null], [2292, "茉子", "「反正，猪谷阿姨拜托我带的口信我已经带到了」", "mak417_014.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-1", null, null], [2293, "茉子", "「可以拜托你们俩一起去吗？」", "mak417_015.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "23"}, "CHAPTER 5-1", null, null], [2294, "将臣", "「哎，我也去？」", null, "学院_教室休憩a", "bgm44.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "23"}, "CHAPTER 5-1", null, null], [2295, "蕾娜", "「嘿嘿，将臣要跟我一起去了吗」", "len417_105.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 5-1", null, null], [2296, "", "好吧，原本答应教她常识的人就是我。", null, "学院_教室休憩a", "bgm44.opus", null, "CHAPTER 5-1", null, null], [2297, "", "而且她看上去也挺开心的……", null, "学院_教室休憩a", "bgm44.opus", null, "CHAPTER 5-1", null, null], [2298, "", "买个东西而已，陪她一起去也无妨吧？", null, "学院_教室休憩a", "bgm44.opus", null, "CHAPTER 5-1", null, null], [2299, "", "放学后，我们立刻来到了镇上。", null, "街_お店モブa", "bgm04.opus", null, "CHAPTER 5-1", null, null], [2300, "", "走着走着，一个小孩子从我们眼前跑了过去，踮起脚把手里拿着的易拉罐放进了垃圾箱里。", null, "街_お店モブa", "bgm04.opus", null, "CHAPTER 5-1", null, null], [2301, "", "蕾娜看着这一幕，脸上露出了微笑。", null, "街_お店モブa", "bgm04.opus", null, "CHAPTER 5-1", null, null], [2302, "蕾娜", "「日本人的环保意识真是好」", "len417_106.ogg", "街_お店モブa", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-1", null, null], [2303, "将臣", "「是吗？我都没怎么留意过」", null, "街_お店モブa", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-1", null, null], [2304, "蕾娜", "「你看，这个垃圾箱都是按易拉罐、玻璃瓶、塑料瓶分类丢弃的」", "len417_107.ogg", "街_お店モブa", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-1", null, null], [2305, "将臣", "「这不是很平常的吗？」", null, "街_お店モブa", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-1", null, null], [2306, "蕾娜", "「是的，但是国外有很多人看见垃圾箱都不会把垃圾往里面放」", "len417_108.ogg", "街_お店モブa", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-1", null, null], [2307, "蕾娜", "「可是日本甚至有很多人会把垃圾专门放在包里带走，这点让我很吃惊」", "len417_109.ogg", "街_お店モブa", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "28"}, "CHAPTER 5-1", null, null], [2308, "蕾娜", "「还有些旅馆的客人，垃圾一律自己带走，根本不往旅馆的垃圾桶里面扔」", "len417_110.ogg", "街_お店モブa", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "21"}, "CHAPTER 5-1", null, null], [2309, "将臣", "「啊，确实，不过最近也很少有人会做到那个地步了」", null, "街_お店モブa", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "21"}, "CHAPTER 5-1", null, null], [2310, "", "这种自己带走垃圾的人，大多是因为不好意思麻烦别人来收拾自己的垃圾。", null, "街_お店モブa", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "21"}, "CHAPTER 5-1", null, null], [2311, "", "我个人并不觉得把垃圾扔公共垃圾箱里有什么不好，但随地乱扔实在是做不到。", null, "街_お店モブa", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "21"}, "CHAPTER 5-1", null, null], [2312, "蕾娜", "「而且买东西的时候，很多人都是用环保袋的」", "len417_111.ogg", "街_お店モブa", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 5-1", null, null], [2313, "将臣", "「是吗，最近很流行吗？」", null, "街_お店モブa", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 5-1", null, null], [2314, "将臣", "「在我的印象中，日本的过度包装好像经常被外国诟病」", null, "街_お店モブa", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 5-1", null, null], [2315, "蕾娜", "「可以不要的嘛，现在的商店都可以自由选择要不要塑料袋」", "len417_112.ogg", "街_お店モブa", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-1", null, null], [2316, "将臣", "「也对，只要带上环保袋，就可以不要塑料袋了」", null, "街_お店モブa", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-1", null, null], [2317, "蕾娜", "「是啊！所以我也会随身带着环保袋」", "len417_113.ogg", "街_お店モブa", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-1", null, null], [2318, "将臣", "「是吗……挺佩服你的」", null, "街_お店モブa", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-1", null, null], [2319, "", "虽然我是日本人，但我就没有自己的环保袋。", null, "街_お店モブa", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-1", null, null], [2320, "", "我是不是也买个环保袋随身带着好一点？", null, "街_お店モブa", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-1", null, null], [2321, "蕾娜", "「啊，我们到了！不好意思将臣，你能稍微等我一会儿吗？」", "len417_114.ogg", "街_お店モブa", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-1", null, null], [2322, "将臣", "「不用我帮忙吗？我本来打算帮你拿东西的」", null, "街_お店モブa", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-1", null, null], [2323, "蕾娜", "「没事啦，等我买完之后再拜托你一起拿！我很快就回来」", "len417_115.ogg", "街_お店モブa", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-1", null, null], [2324, "将臣", "「嗯，那你快去吧」", null, "街_お店モブa", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 5-1", null, null], [2325, "", "蕾娜一边用力向我挥手，一边走进了商店里。", null, "街_お店モブa", "bgm04.opus", null, "CHAPTER 5-1", null, null], [2326, "", "但我到现在还是有点想不通。", null, "街_お店モブa", "bgm04.opus", null, "CHAPTER 5-1", null, null], [2327, "将臣", "「出来买东西，跟前面加“御”的词语到底有什么关联啊？」", null, "街_お店モブa", "bgm04.opus", null, "CHAPTER 5-1", null, null], [2328, "将臣", "「这不就是很普通地来买个东西吗」", null, "街_お店モブa", "bgm04.opus", null, "CHAPTER 5-1", null, null], [2329, "", "也罢，反正我和蕾娜聊得很开心，没什么好抱怨的……", null, "街_お店モブa", "bgm04.opus", null, "CHAPTER 5-1", null, null], [2330, "", "啊，她已经选好了要买的东西，正在收银台前结账。", null, "街_お店モブa", "bgm04.opus", null, "CHAPTER 5-1", null, null], [2331, "蕾娜", "「啊，我不要袋子」", "len417_116.ogg", "街_お店モブa", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 5-1", null, null], [2332, "店员", "「……好、好的」", "tni417_001.ogg", "街_お店モブa", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 5-1", null, null], [2333, "", "用错了！！", null, "街_お店モブa", "bgm04.opus", null, "CHAPTER 5-1", null, null], [2334, "蕾娜", "「哦哇……我以前每次都是这么说的，为什么收银员从来不告诉我啊？」", "len417_117.ogg", "街_お店モブa", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "12"}, "CHAPTER 5-1", null, null], [2335, "蕾娜", "「真没想到“袋子”加了个御意思竟然会变成母亲」", "len417_118.ogg", "街_お店モブa", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "17"}, "CHAPTER 5-1", null, null], [2336, "蕾娜", "「我居然每天都在对店员说，我不要我妈……我真是太失礼了」", "len417_119.ogg", "街_お店モブa", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "18"}, "CHAPTER 5-1", null, null], [2337, "将臣", "「还、还好啦，日语就算说错了一点点也是能明白意思的」", null, "街_お店モブa", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "18"}, "CHAPTER 5-1", null, null], [2338, "", "从店里出来，指出蕾娜的错误之后，她明显变得很沮丧。", null, "街_お店モブa", "bgm37.opus", null, "CHAPTER 5-1", null, null], [2339, "", "本来说好了我来帮她提东西的，可她坚决要自己提一半，于是现在只好两个人一左一右地拎着一个袋子。", null, "街_お店モブa", "bgm37.opus", null, "CHAPTER 5-1", null, null], [2340, "", "虽然和一开始说好的不一样，不过这样也还不错……嗯，就是有点难为情。", null, "街_お店モブa", "bgm37.opus", null, "CHAPTER 5-1", null, null], [2341, "蕾娜", "「在这方面，日本人有点善良过头了」", "len417_120.ogg", "街_お店モブa", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "11"}, "CHAPTER 5-1", null, null], [2342, "蕾娜", "「如果我说错了，那就应该提醒我纠正过来呀」", "len417_121.ogg", "街_お店モブa", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "17"}, "CHAPTER 5-1", null, null], [2343, "将臣", "「哈哈，日本很多人觉得这样纠正别人的错误是不礼貌的，还有些人可能只是不喜欢指出这些」", null, "街_お店モブa", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "17"}, "CHAPTER 5-1", null, null], [2344, "", "大概猪谷阿姨也是觉得，不是在自己眼前犯的错误，想纠正也不知道怎么说合适。", null, "街_お店モブa", "bgm37.opus", null, "CHAPTER 5-1", null, null], [2345, "", "之所以拜托我来陪蕾娜买东西，说不定也是想让我帮她纠正一下。", null, "街_お店モブa", "bgm37.opus", null, "CHAPTER 5-1", null, null], [2346, "芦花", "「哎呀哎呀，这不是阿将嘛！正好蕾娜也在，这真是上天的安排！」", "rok417_001.ogg", "街_お店モブa", "bgm37.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "14"}, "CHAPTER 5-1", null, null], [2347, "将臣", "「有什么事吗，芦花姐……哎？等等，怎么了？」", null, "街_お店モブa", "bgm37.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "14"}, "CHAPTER 5-1", null, null], [2348, "蕾娜", "「呃……发生什么事了？」", "len417_122.ogg", "街_お店モブa", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "06"}, "CHAPTER 5-1", null, null], [2349, "", "经过芦花姐家的店面时，她突然拽住了我们的袖子。", null, "街_お店モブa", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "06"}, "CHAPTER 5-1", null, null], [2350, "芦花", "「你们先别问了！赶紧进来，尝尝我做的芭菲吧」", "rok417_002.ogg", "街_お店モブa", "bgm37.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "02"}, "CHAPTER 5-1", null, null], [2351, "蕾娜", "「可……可是，我是出来买东西的，还得回去工作……」", "len417_123.ogg", "街_お店モブa", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "29"}, "CHAPTER 5-1", null, null], [2352, "芦花", "「你说的是志那都庄的工作吗？既然这样，姐姐就帮你去打个招呼吧，你看行吗？行吗？求你了！」", "rok417_003.ogg", "街_お店モブa", "bgm37.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "21"}, "CHAPTER 5-1", null, null], [2353, "芦花", "「啊！喂喂，请问是猪谷阿姨吗？平日承蒙关照了」", "rok417_004.ogg", "街_甘味処a", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "17"}, "CHAPTER 5-1", null, null], [2354, "芦花", "「不不，其实我想跟您说个事」", "rok417_005.ogg", "街_甘味処a", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "01"}, "CHAPTER 5-1", null, null], [2355, "", "芦花姐真的在给志那都庄打电话。", null, "街_甘味処a", "bgm11.opus", null, "CHAPTER 5-1", null, null], [2356, "蕾娜", "「她、她到底要让我们做什么啊？」", "len417_124.ogg", "街_甘味処a", "bgm11.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "30"}, "CHAPTER 5-1", null, null], [2357, "将臣", "「不知道……今天的芦花姐，看上去和平时的样子不太一样」", null, "街_甘味処a", "bgm11.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "30"}, "CHAPTER 5-1", null, null], [2358, "蕾娜", "「哈哈，抱歉啊哥哥，还有蕾娜学姐……」", "koh417_015.ogg", "街_甘味処a", "bgm11.opus", {"char": "小春", "file": "小春.stand", "dress": "仕事着", "face": "16"}, "CHAPTER 5-1", null, null], [2359, "将臣", "「小春，你知道是怎么回事吗？」", null, "街_甘味処a", "bgm11.opus", {"char": "小春", "file": "小春.stand", "dress": "仕事着", "face": "16"}, "CHAPTER 5-1", null, null], [2360, "蕾娜", "「嗯，事情是这样的……姐姐好像和她爸爸吵架了」", "koh417_016.ogg", "街_甘味処a", "bgm11.opus", {"char": "小春", "file": "小春.stand", "dress": "仕事着", "face": "07"}, "CHAPTER 5-1", null, null], [2361, "将臣", "「和叔叔吵架了？」", null, "街_甘味処a", "bgm11.opus", {"char": "小春", "file": "小春.stand", "dress": "仕事着", "face": "07"}, "CHAPTER 5-1", null, null], [2362, "蕾娜", "「然后姐姐就恼火了，说一定要让叔叔无话可说，所以刚才一直在做新品芭菲」", "koh417_017.ogg", "街_甘味処a", "bgm11.opus", {"char": "小春", "file": "小春.stand", "dress": "仕事着", "face": "17"}, "CHAPTER 5-1", null, null], [2363, "蕾娜", "「她刚才也说让我们尝尝她的芭菲，那我们只要试吃一下就行了吗？」", "len417_125.ogg", "街_甘味処a", "bgm11.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "20"}, "CHAPTER 5-1", null, null], [2364, "蕾娜", "「嗯、嗯，不过……」", "koh417_018.ogg", "街_甘味処a", "bgm11.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "20"}, "CHAPTER 5-1", null, null], [2365, "芦花", "「好了，猪谷阿姨已经同意了！蕾娜你就放心吧」", "rok417_006.ogg", "街_甘味処a", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "02"}, "CHAPTER 5-1", null, null], [2366, "蕾娜", "「好、好的，可是真的没问题吗？」", "len417_126.ogg", "街_甘味処a", "bgm11.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "30"}, "CHAPTER 5-1", null, null], [2367, "将臣", "「我觉得应该没事的」", null, "街_甘味処a", "bgm11.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "30"}, "CHAPTER 5-1", null, null], [2368, "", "刚才，小春是想说什么呢？", null, "街_甘味処a", "bgm11.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "30"}, "CHAPTER 5-1", null, null], [2369, "芦花", "「小春，把我做的芭菲给他们端上来吧」", "rok417_007.ogg", "街_甘味処a", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "14"}, "CHAPTER 5-1", null, null], [2370, "蕾娜", "「可、可是，真的不要紧吗？」", "koh417_019.ogg", "街_甘味処a", "bgm11.opus", {"char": "小春", "file": "小春.stand", "dress": "仕事着", "face": "08"}, "CHAPTER 5-1", null, null], [2371, "芦花", "「没事没事，你要相信我啊」", "rok417_008.ogg", "街_甘味処a", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "17"}, "CHAPTER 5-1", null, null], [2372, "", "放心、没事、相信我，这样的词一个接着一个，可我心里为什么就是这么不安呢？", null, "街_甘味処a", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "17"}, "CHAPTER 5-1", null, null], [2373, "", "小春一脸无奈地端上来了两份和式芭菲。", null, "街_甘味処a", "bgm11.opus", null, "CHAPTER 5-1", null, null], [2374, "蕾娜", "「看上去绿绿的……但好像又不是抹茶」", "len417_127.ogg", "街_甘味処a", "bgm11.opus", null, "CHAPTER 5-1", null, null], [2375, "将臣", "「嗯，这股独特而又刺鼻的味道……该不会是！？」", null, "街_甘味処a", "bgm11.opus", null, "CHAPTER 5-1", null, null], [2376, "芦花", "「两位客人，这是本店新推出的甜品“芥末芭菲”」", "rok417_009.ogg", "街_甘味処a", "bgm11.opus", null, "CHAPTER 5-1", null, null], [2377, "将臣", "「……」", null, "街_甘味処a", "bgm11.opus", null, "CHAPTER 5-1", null, null], [2378, "蕾娜", "「……」", "len417_128.ogg", "街_甘味処a", "bgm11.opus", null, "CHAPTER 5-1", null, null], [2379, "", "你在逗我吗？", null, "街_甘味処a", "bgm11.opus", null, "CHAPTER 5-1", null, null], [2380, "芦花", "「这可是谁都还没尝过的绝密测试版！你们是幸运的测试版用户哦」", "rok417_010.ogg", "街_甘味処a", "bgm22.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "02"}, "CHAPTER 5-1", null, null], [2381, "将臣", "「啊、嗯，原来是这样啊……可我现在肚子有点饱」", null, "街_甘味処a", "bgm22.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "02"}, "CHAPTER 5-1", null, null], [2382, "蕾娜", "「我也有点担心志那都庄那边」", "len417_129.ogg", "街_甘味処a", "bgm22.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "06"}, "CHAPTER 5-1", null, null], [2383, "芦花", "「没问题，真的很好吃的，你们不要一口也不尝就走啊」", "rok417_011.ogg", "街_甘味処a", "bgm22.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "31"}, "CHAPTER 5-1", null, null], [2384, "芦花", "「我真的做得很好吃的，真的真的」", "rok417_012.ogg", "街_甘味処a", "bgm22.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "30"}, "CHAPTER 5-1", null, null], [2385, "将臣", "「放开我啊芦花姐！这看上去真的太诡异了！」", null, "街_甘味処a", "bgm22.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "30"}, "CHAPTER 5-1", null, null], [2386, "芦花", "「阿将，至少你来吃一口，然后把感想告诉我啊！」", "rok417_013.ogg", "街_甘味処a", "bgm22.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "11"}, "CHAPTER 5-1", null, null], [2387, "", "这是要让我当牺牲品？", null, "街_甘味処a", "bgm22.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "11"}, "CHAPTER 5-1", null, null], [2388, "", "竟然做出这么稀奇古怪的料理，我都不知道芦花姐还有这样的兴趣爱好。", null, "街_甘味処a", "bgm22.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "11"}, "CHAPTER 5-1", null, null], [2389, "芦花的父亲", "「你别再胡闹了，芦花」", "rkc417_001.ogg", "街_甘味処a", "bgm11.opus", null, "CHAPTER 5-1", null, null], [2390, "将臣", "「啊，叔叔」", null, "街_甘味処a", "bgm11.opus", null, "CHAPTER 5-1", null, null], [2391, "", "是芦花姐的爸爸。", null, "街_甘味処a", "bgm11.opus", null, "CHAPTER 5-1", null, null], [2392, "", "他平时很少从厨房出来，今天这情况真是不一般。", null, "街_甘味処a", "bgm11.opus", null, "CHAPTER 5-1", null, null], [2393, "芦花的父亲", "「这种东西，就算有人觉得稀奇点了第一次，也不可能再点第二次了」", "rkc417_002.ogg", "街_甘味処a", "bgm11.opus", null, "CHAPTER 5-1", null, null], [2394, "芦花", "「但这款芭菲的目标人群是游客呀！对游客来说，看到了就忍不住想点的噱头也是很重要的吧」", "rok417_014.ogg", "街_甘味処a", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "06"}, "CHAPTER 5-1", null, null], [2395, "芦花", "「我都说了，只要能让游客点一次就行了」", "rok417_015.ogg", "街_甘味処a", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "13"}, "CHAPTER 5-1", null, null], [2396, "芦花的父亲", "「无论如何，我是不会做这种东西的」", "rkc417_003.ogg", "街_甘味処a", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "13"}, "CHAPTER 5-1", null, null], [2397, "芦花", "「什……又来？老爸，之前不是说好了把店里的事情都交给我的吗！」", "rok417_016.ogg", "街_甘味処a", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "15"}, "CHAPTER 5-1", null, null], [2398, "芦花的父亲", "「那也不代表我什么都给你做。我说了不行，就是不行！」", "rkc417_004.ogg", "街_甘味処a", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "15"}, "CHAPTER 5-1", null, null], [2399, "芦花", "「真是的，你这个死脑筋！死脑筋！死脑筋！！」", "rok417_017.ogg", "街_甘味処a", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "30"}, "CHAPTER 5-1", null, null], [2400, "", "原来如此，他们父女俩就是在为这事吵架啊。", null, "街_甘味処a", "bgm11.opus", null, "CHAPTER 5-1", null, null], [2401, "", "不过我觉得，他们俩说的都有道理。", null, "街_甘味処a", "bgm11.opus", null, "CHAPTER 5-1", null, null], [2402, "蕾娜", "「姐姐平常都是想办法哄着叔叔缠着叔叔，直到叔叔答应她的要求为止」", "koh417_020.ogg", "街_甘味処a", "bgm11.opus", {"char": "小春", "file": "小春.stand", "dress": "仕事着", "face": "04"}, "CHAPTER 5-1", null, null], [2403, "蕾娜", "「可这次他们都是为了店里着想，于是就演变成正面冲突了……」", "koh417_021.ogg", "街_甘味処a", "bgm11.opus", {"char": "小春", "file": "小春.stand", "dress": "仕事着", "face": "29"}, "CHAPTER 5-1", null, null], [2404, "将臣", "「嗯，之前也听芦花姐说过类似的抱怨」", null, "街_甘味処a", "bgm11.opus", {"char": "小春", "file": "小春.stand", "dress": "仕事着", "face": "29"}, "CHAPTER 5-1", null, null], [2405, "", "看来芦花姐也是积攒了不少情绪。", null, "街_甘味処a", "bgm11.opus", null, "CHAPTER 5-1", null, null], [2406, "", "既然如此，那就没办法了。", null, "街_甘味処a", "bgm11.opus", null, "CHAPTER 5-1", null, null], [2407, "将臣", "「那个，我会试吃的！如果我觉得还不错的话，你们或许可以再考虑考虑？」", null, "街_甘味処a", "bgm11.opus", null, "CHAPTER 5-1", null, null], [2408, "蕾娜", "「是啊！我也会尝尝的，你们就别吵了嘛」", "len417_130.ogg", "街_甘味処a", "bgm11.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 5-1", null, null], [2409, "将臣", "「哎？你不用勉强自己吃的，我一个人就行」", null, "街_甘味処a", "bgm11.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 5-1", null, null], [2410, "蕾娜", "「没有勉强，其实我也有点好奇这芭菲到底是什么味道」", "len417_131.ogg", "街_甘味処a", "bgm11.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 5-1", null, null], [2411, "芦花", "「阿将，蕾娜……谢谢你们！」", "rok417_018.ogg", "街_甘味処a", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "02"}, "CHAPTER 5-1", null, null], [2412, "", "虽然决定要试吃，但看到这个淡绿色的冰淇淋……", null, "街_甘味処a", "bgm25.opus", null, "CHAPTER 5-1", null, null], [2413, "", "还有似乎撒着芥末粉的白玉团子……搭配在一起真是相当不协调。", null, "街_甘味処a", "bgm25.opus", null, "CHAPTER 5-1", null, null], [2414, "", "如果这盘子里装的不是甜品而是海鲜，看上去可能还好一点。", null, "街_甘味処a", "bgm25.opus", null, "CHAPTER 5-1", null, null], [2415, "", "唉，我现在突然特别想吃寿司或生鱼片。", null, "街_甘味処a", "bgm25.opus", null, "CHAPTER 5-1", null, null], [2416, "", "肯定是因为芥末的这股刺鼻味道，刺激了我对寿司的食欲，而不是什么甜品。", null, "街_甘味処a", "bgm25.opus", null, "CHAPTER 5-1", null, null], [2417, "蕾娜", "「那、那么，将臣，我们俩一起吃一口试试吧？」", "len417_132.ogg", "街_甘味処a", "bgm25.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 5-1", null, null], [2418, "将臣", "「啊，好、好的」", null, "街_甘味処a", "bgm25.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 5-1", null, null], [2419, "", "蕾娜果然是在勉强自己。", null, "街_甘味処a", "bgm25.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 5-1", null, null], [2420, "将臣", "「那就，准备……吃！」", null, "街_甘味処a", "bgm25.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 5-1", null, null], [2421, "蕾娜", "「嗷呜」", "len417_133.ogg", "街_甘味処a", "bgm25.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "18"}, "CHAPTER 5-1", null, null], [2422, "将臣", "「……嗯！？」", null, "街_甘味処a", "bgm25.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "18"}, "CHAPTER 5-1", null, null], [2423, "", "不是吧！？这、这个竟然……", null, "街_甘味処a", "bgm25.opus", null, "CHAPTER 5-1", null, null], [2424, "将臣", "「很好吃？」", null, "街_甘味処a", "bgm21.opus", null, "CHAPTER 5-1", null, null], [2425, "蕾娜", "「哎哎哎哎哎哎！！？」", "koh417_022.ogg", "街_甘味処a", "bgm21.opus", {"char": "小春", "file": "小春.stand", "dress": "仕事着", "face": "19"}, "CHAPTER 5-1", null, null], [2426, "芦花", "「你看吧！都说了我对味道很有信心的，小春你惊讶过头啦！」", "rok417_019.ogg", "街_甘味処a", "bgm21.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "15"}, "CHAPTER 5-1", null, null], [2427, "蕾娜", "「可、可那是……哥哥，你没事吧？该不会是因为味道太猛烈，把你的舌头搞得不正常了吧？」", "koh417_023.ogg", "街_甘味処a", "bgm21.opus", {"char": "小春", "file": "小春.stand", "dress": "仕事着", "face": "04"}, "CHAPTER 5-1", null, null], [2428, "将臣", "「没有，不过我确实很意外……芥末的辛辣和这刺鼻的感觉配上甜品，竟然能进一步引出甜品中的甜味」", null, "街_甘味処a", "bgm21.opus", {"char": "小春", "file": "小春.stand", "dress": "仕事着", "face": "04"}, "CHAPTER 5-1", null, null], [2429, "将臣", "「一口气吃完可能确实有点困难，但总体来说这个味道还不错……」", null, "街_甘味処a", "bgm21.opus", {"char": "小春", "file": "小春.stand", "dress": "仕事着", "face": "04"}, "CHAPTER 5-1", null, null], [2430, "将臣", "「不，应该说相当不错？对吧，蕾娜……」", null, "街_甘味処a", "bgm21.opus", {"char": "小春", "file": "小春.stand", "dress": "仕事着", "face": "04"}, "CHAPTER 5-1", null, null], [2431, "蕾娜", "「呜……呜呜，没、没错，将臣说得没错，真的很好吃，呜呜」", "len417_134.ogg", "街_甘味処a", "bgm23.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "18n"}, "CHAPTER 5-1", null, null], [2432, "", "坐在我身旁的蕾娜，眼泪扑簌扑簌地往下掉。", null, "街_甘味処a", "bgm23.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "18n"}, "CHAPTER 5-1", null, null], [2433, "蕾娜", "「你、你别误会了，我这不是眼泪……是内心的汗水，呜呜呜」", "len417_135.ogg", "街_甘味処a", "bgm23.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "17n"}, "CHAPTER 5-1", null, null], [2434, "蕾娜", "「很好吃的，真的……很好吃的，不……不好意什」", "len417_136.ogg", "街_甘味処a", "bgm23.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "18n"}, "CHAPTER 5-1", null, null], [2435, "将臣", "「不、不用勉强自己啦！给，擦擦鼻子」", null, "街_甘味処a", "bgm23.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "18n"}, "CHAPTER 5-1", null, null], [2436, "蕾娜", "「不好意什……不好意什」", "len417_137.ogg", "街_甘味処a", "bgm23.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "22n"}, "CHAPTER 5-1", null, null], [2437, "", "都搞忘了，蕾娜确实吃不来芥末。", null, "街_甘味処a", "bgm23.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "22n"}, "CHAPTER 5-1", null, null], [2438, "蕾娜", "「是、是不是少放点芥末就好了？」", "koh417_024.ogg", "街_甘味処a", "bgm11.opus", {"char": "小春", "file": "小春.stand", "dress": "仕事着", "face": "07"}, "CHAPTER 5-1", null, null], [2439, "芦花", "「唔……要是芥末少到几乎吃不出来的程度，那就没有做芥末芭菲的意义了……」", "rok417_020.ogg", "街_甘味処a", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "27"}, "CHAPTER 5-1", null, null], [2440, "芦花", "「不过，对于吃不惯芥末的外国人来说……芥末的味道确实太刺激了」", "rok417_021.ogg", "街_甘味処a", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "09"}, "CHAPTER 5-1", null, null], [2441, "将臣", "「唔、嗯」", null, "街_甘味処a", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "09"}, "CHAPTER 5-1", null, null], [2442, "", "在来穗织观光的旅客中，欧美人的比例还是挺高的。", null, "街_甘味処a", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "09"}, "CHAPTER 5-1", null, null], [2443, "芦花", "「……看来，还是行不通啊」", "rok417_022.ogg", "街_甘味処a", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "33"}, "CHAPTER 5-1", null, null], [2444, "蕾娜", "「那、那个，虽然我吃不惯芥末，但我真的觉得很好吃」", "len417_138.ogg", "街_甘味処a", "bgm11.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "22"}, "CHAPTER 5-1", null, null], [2445, "芦花的父亲", "「不必安慰她。你是叫蕾娜吧？」", "rkc417_005.ogg", "街_甘味処a", "bgm11.opus", null, "CHAPTER 5-1", null, null], [2446, "芦花的父亲", "「失败了就是失败了，芦花自己是最清楚的」", "rkc417_006.ogg", "街_甘味処a", "bgm11.opus", null, "CHAPTER 5-1", null, null], [2447, "芦花", "「唔……对、对不起」", "rok417_023.ogg", "街_甘味処a", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "23"}, "CHAPTER 5-1", null, null], [2448, "芦花的父亲", "「笨蛋女儿」", "rkc417_007.ogg", "街_甘味処a", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "23"}, "CHAPTER 5-1", null, null], [2449, "", "叔叔来到心情沮丧的芦花姐身边，摸了摸她的脑袋。", null, "街_甘味処a", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "18"}, "CHAPTER 5-1", null, null], [2450, "芦花的父亲", "「不过，我刚才太过意气用事了，是我不好」", "rkc417_008.ogg", "街_甘味処a", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "18"}, "CHAPTER 5-1", null, null], [2451, "芦花", "「……老爸？」", "rok417_024.ogg", "街_甘味処a", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "04"}, "CHAPTER 5-1", null, null], [2452, "芦花的父亲", "「这种尝试，别的店也做过很多次」", "rkc417_009.ogg", "街_甘味処a", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "04"}, "CHAPTER 5-1", null, null], [2453, "芦花的父亲", "「但是这种稀奇古怪的甜品，必须做到整个地区随处可见的程度，否则是做不了多久的」", "rkc417_010.ogg", "街_甘味処a", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "04"}, "CHAPTER 5-1", null, null], [2454, "将臣", "「哎？必须每家店都得推出一样的甜品才行吗？」", null, "街_甘味処a", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "04"}, "CHAPTER 5-1", null, null], [2455, "蕾娜", "「那样一来，顾客不就分散了吗」", "koh417_025.ogg", "街_甘味処a", "bgm11.opus", {"char": "小春", "file": "小春.stand", "dress": "仕事着", "face": "17"}, "CHAPTER 5-1", null, null], [2456, "芦花的父亲", "「不，这种东西第一次见根本就不知道好不好吃，就算顾客很好奇，一般也是不会愿意买单的」", "rkc417_011.ogg", "街_甘味処a", "bgm11.opus", null, "CHAPTER 5-1", null, null], [2457, "芦花的父亲", "「但如果他们连续看见两三次，就会觉得说不定还挺好吃的」", "rkc417_012.ogg", "街_甘味処a", "bgm11.opus", null, "CHAPTER 5-1", null, null], [2458, "芦花的父亲", "「这时顾客才会愿意花钱点一份试试」", "rkc417_013.ogg", "街_甘味処a", "bgm11.opus", null, "CHAPTER 5-1", null, null], [2459, "蕾娜", "「喔，原来如此」", "len417_139.ogg", "街_甘味処a", "bgm11.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-1", null, null], [2460, "", "叔叔说的确实有道理，在旅游胜地看到这种稀奇古怪的食品时，大家一般都是那种心理。", null, "街_甘味処a", "bgm11.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-1", null, null], [2461, "芦花的父亲", "「所以，如果只在我们店里卖的话，也是卖不了多少的」", "rkc417_014.ogg", "街_甘味処a", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "04"}, "CHAPTER 5-1", null, null], [2462, "芦花", "「如、如果你一开始就知道，那你为什么不早点告诉我啊」", "rok417_025.ogg", "街_甘味処a", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "13"}, "CHAPTER 5-1", null, null], [2463, "芦花的父亲", "「摸索的过程也很重要，我要是一开始就这么说，你岂不是直接就放弃了」", "rkc417_015.ogg", "街_甘味処a", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "13"}, "CHAPTER 5-1", null, null], [2464, "芦花的父亲", "「虽然横竖都是失败，但到底是哪里没做好，为什么会遭到反对」", "rkc417_016.ogg", "街_甘味処a", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "13"}, "CHAPTER 5-1", null, null], [2465, "芦花的父亲", "「这些东西你不亲身经历，是没办法真正学会的」", "rkc417_017.ogg", "街_甘味処a", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "13"}, "CHAPTER 5-1", null, null], [2466, "芦花", "「唉，都什么年代了还在玩那一套工匠精神？现在这些都不流行了好吗」", "rok417_026.ogg", "街_甘味処a", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "29"}, "CHAPTER 5-1", null, null], [2467, "芦花的父亲", "「笨蛋女儿，所以我才说最近的年轻人根本不行啊！」", "rkc417_018.ogg", "街_甘味処a", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "29"}, "CHAPTER 5-1", null, null], [2468, "芦花的父亲", "「我以前学艺的时候，为了学到师父的本事，天天只盯着师父的手看，结果被打了一顿」", "rkc417_019.ogg", "街_甘味処a", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "29"}, "CHAPTER 5-1", null, null], [2469, "芦花", "「所以我才讨厌过去的那些老古板」", "rok417_027.ogg", "街_甘味処a", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "24"}, "CHAPTER 5-1", null, null], [2470, "芦花", "「放到现在，那都是家庭暴力、职权骚扰，是要被告到法院的好吗」", "rok417_028.ogg", "街_甘味処a", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "06"}, "CHAPTER 5-1", null, null], [2471, "蕾娜", "「噗」", "len417_140.ogg", "街_甘味処a", "bgm11.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 5-1", null, null], [2472, "将臣", "「……哎？」", null, "街_甘味処a", "bgm11.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 5-1", null, null], [2473, "", "蕾娜在一旁乐呵呵地笑出了声。", null, "街_甘味処a", "bgm11.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 5-1", null, null], [2474, "蕾娜", "「芦花和芦花的爸爸关系真好！」", "len417_141.ogg", "街_甘味処a", "bgm11.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-1", null, null], [2475, "芦花的父亲", "「……什么？」", "rkc417_020.ogg", "街_甘味処a", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "03"}, "CHAPTER 5-1", null, null], [2476, "芦花", "「哪有哪有，我们刚刚不是才吵完架吗？」", "rok417_029.ogg", "街_甘味処a", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "31"}, "CHAPTER 5-1", null, null], [2477, "蕾娜", "「吵完架能够和好，就不算坏事！」", "len417_142.ogg", "街_甘味処a", "bgm11.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "24"}, "CHAPTER 5-1", null, null], [2478, "蕾娜", "「这说明你们关系很好嘛」", "len417_143.ogg", "街_甘味処a", "bgm11.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 5-1", null, null], [2479, "", "看到蕾娜天真的笑容，叔叔和芦花姐不由得对望了一眼。", null, "街_甘味処a", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "25"}, "CHAPTER 5-1", null, null], [2480, "", "虽然两人立刻把头扭向了一边，但气氛已经缓和了许多。", null, "街_甘味処a", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "10"}, "CHAPTER 5-1", null, null], [2481, "", "我突然想起来，蕾娜几乎没怎么提起过她的父母。", null, "街_甘味処a", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "10"}, "CHAPTER 5-1", null, null], [2482, "", "之前我还担心是不是有什么隐情，不过看到她那天真无邪的笑容，我应该是瞎操心了吧？", null, "街_甘味処a", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "10"}, "CHAPTER 5-1", null, null], [2483, "将臣", "「对了，我想起来了！」", null, "街_甘味処a", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "10"}, "CHAPTER 5-1", null, null], [2484, "芦花", "「嗯？怎么了？」", "rok417_030.ogg", "街_甘味処a", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "18"}, "CHAPTER 5-1", null, null], [2485, "将臣", "「我想问下芦花姐和叔叔，你们知不知道有谁比较熟悉穗织的历史？」", null, "街_甘味処a", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "18"}, "CHAPTER 5-1", null, null], [2486, "将臣", "「大约在一百年前的时候，穗织好像有过通ＳＬ的计划」", null, "街_甘味処a", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "18"}, "CHAPTER 5-1", null, null], [2487, "蕾娜", "「对哦，差点忘了！早上还说要仔细调查一下呢」", "len417_144.ogg", "街_甘味処a", "bgm11.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-1", null, null], [2488, "", "虽然这事拜托了外公，但我们总不能把事情全推给他老人家去办。", null, "街_甘味処a", "bgm11.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-1", null, null], [2489, "芦花的父亲", "「嚯，你说ＳＬ啊！好久没听人提起这个词了」", "rkc417_021.ogg", "街_甘味処a", "bgm11.opus", null, "CHAPTER 5-1", null, null], [2490, "将臣", "「叔叔，你认识了解ＳＬ的人吗？」", null, "街_甘味処a", "bgm11.opus", null, "CHAPTER 5-1", null, null], [2491, "芦花", "「什么认识不认识的，他自己就很了解」", "rok417_031.ogg", "街_甘味処a", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "01"}, "CHAPTER 5-1", null, null], [2492, "", "芦花姐指着的，竟然就是叔叔本人。", null, "街_甘味処a", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "01"}, "CHAPTER 5-1", null, null], [2493, "芦花", "「应该说是铁道宅？还是ＳＬ宅来着？反正我建议你们不要跟他聊这个话题」", "rok417_032.ogg", "街_甘味処a", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "31"}, "CHAPTER 5-1", null, null], [2494, "芦花的父亲", "「你瞎说什么呢？这不是他们先提起来的吗」", "rkc417_022.ogg", "街_甘味処a", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "31"}, "CHAPTER 5-1", null, null], [2495, "芦花", "「你看，他现在已经想说得快憋不住了」", "rok417_033.ogg", "街_甘味処a", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "27"}, "CHAPTER 5-1", null, null], [2496, "芦花", "「你们一时半会儿怕是走不了了」", "rok417_034.ogg", "街_甘味処a", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "20"}, "CHAPTER 5-1", null, null], [2497, "将臣", "「哈哈，那个，所以当时真的有过建铁路的计划吗？」", null, "街_甘味処a", "bgm11.opus", null, "CHAPTER 5-1", null, null], [2498, "芦花的父亲", "「当然有过！当时穗织附近就已经通铁路了，肯定有过的」", "rkc417_023.ogg", "街_甘味処a", "bgm11.opus", null, "CHAPTER 5-1", null, null], [2499, "", "没想到叔叔说得这么斩钉截铁。", null, "街_甘味処a", "bgm11.opus", null, "CHAPTER 5-1", null, null], [2500, "芦花的父亲", "「而且当时准备引进的并不是国营铁路的那种英国老型号，而是最新款的德国机车」", "rkc417_024.ogg", "街_甘味処a", "bgm11.opus", null, "CHAPTER 5-1", null, null], [2501, "蕾娜", "「是德国机车吗！这个您确定吗？」", "len417_145.ogg", "街_甘味処a", "bgm11.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "15"}, "CHAPTER 5-1", null, null], [2502, "芦花的父亲", "「不会有错，国营铁路当时之所以都是英国标准，是因为只有英国允许我们仿制他们的蒸汽机车」", "rkc417_025.ogg", "街_甘味処a", "bgm11.opus", null, "CHAPTER 5-1", null, null], [2503, "芦花的父亲", "「当时的国营铁路正在拼命学习制造技术，就为了能造出梦寐以求的国产ＳＬ」", "rkc417_026.ogg", "街_甘味処a", "bgm11.opus", null, "CHAPTER 5-1", null, null], [2504, "芦花的父亲", "「不过这些和地方运营的私营铁路无关」", "rkc417_027.ogg", "街_甘味処a", "bgm11.opus", null, "CHAPTER 5-1", null, null], [2505, "芦花的父亲", "「德国标准的机车，体积小马力强，价格还便宜」", "rkc417_028.ogg", "街_甘味処a", "bgm11.opus", null, "CHAPTER 5-1", null, null], [2506, "芦花的父亲", "「所以当时的私营铁路基本都是德国机车，这是毫无疑问的」", "rkc417_029.ogg", "街_甘味処a", "bgm11.opus", null, "CHAPTER 5-1", null, null], [2507, "将臣", "「喔……蕾娜，这些事你以前知道吗？」", null, "街_甘味処a", "bgm11.opus", null, "CHAPTER 5-1", null, null], [2508, "蕾娜", "「怎么会，我当然也是头一次听说……」", "len417_146.ogg", "街_甘味処a", "bgm11.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 5-1", null, null], [2509, "", "也就是说，梦里发生的事确实都是我们不知道的事情。", null, "街_甘味処a", "bgm11.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 5-1", null, null], [2510, "芦花", "「不过，为什么你们要突然问起ＳＬ呢？」", "rok417_035.ogg", "街_甘味処a", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "20"}, "CHAPTER 5-1", null, null], [2511, "将臣", "「其实是……蕾娜的祖上，可能曾经参与过穗织的铁路修建计划」", null, "街_甘味処a", "bgm11.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 5-1", null, null], [2512, "蕾娜", "「是的，那是我爷爷的爷爷的岳父」", "len417_147.ogg", "街_甘味処a", "bgm11.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-1", null, null], [2513, "蕾娜", "「当时，他好像在穗织住过一段时间，你们知道关于他的事吗？」", "len417_148.ogg", "街_甘味処a", "bgm11.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-1", null, null], [2514, "芦花的父亲", "「这样啊，那真是够厉害的！但是，那么久之前的事我也不太清楚」", "rkc417_030.ogg", "街_甘味処a", "bgm11.opus", null, "CHAPTER 5-1", null, null], [2515, "芦花的父亲", "「不过，应该是有过这些事的」", "rkc417_031.ogg", "街_甘味処a", "bgm11.opus", null, "CHAPTER 5-1", null, null], [2516, "芦花的父亲", "「不，肯定有过！在那个年代，铁路可是最尖端的技术结晶，工程难度是非常高的」", "rkc417_032.ogg", "街_甘味処a", "bgm11.opus", null, "CHAPTER 5-1", null, null], [2517, "芦花的父亲", "「如果不从外国引进人才，只靠我们自己是肯定没办法建成的」", "rkc417_033.ogg", "街_甘味処a", "bgm11.opus", null, "CHAPTER 5-1", null, null], [2518, "将臣", "「原来如此……」", null, "街_甘味処a", "bgm11.opus", null, "CHAPTER 5-1", null, null], [2519, "", "在梦里，八成是蕾娜高祖父的那位青年也说过类似的话。", null, "街_甘味処a", "bgm11.opus", null, "CHAPTER 5-1", null, null], [2520, "", "刚才说的这些事应该是不会有错了吧？", null, "街_甘味処a", "bgm11.opus", null, "CHAPTER 5-1", null, null], [2521, "", "但尽管知道了这些，我们还是有些没弄清的地方，这实在是让人有些焦虑。", null, "街_甘味処a", "bgm11.opus", null, "CHAPTER 5-1", null, null], [2522, "", "幸运的是，我们马上就收到了新的消息。", null, "旅館_旅館前b", "bgm35.opus", null, "CHAPTER 5-1", null, null], [2523, "玄十郎", "「你们回来了啊！列支敦瑙尔小姐，你能看看这个吗？」", "gen417_024.ogg", "旅館_旅館前b", "bgm35.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "04"}, "CHAPTER 5-1", null, null], [2524, "", "外公似乎已经在门口等候我们多时。他一见我们，就立刻拿出了一本破破烂烂的店簿。", null, "旅館_旅館前b", "bgm35.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "18"}, "CHAPTER 5-1", null, null], [2525, "", "他看上去还有些兴奋，这可真是少见。", null, "旅館_旅館前b", "bgm35.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "18"}, "CHAPTER 5-1", null, null], [2526, "玄十郎", "「你们看，同样的姓氏在这里出现了三个。看着也不太像英语，但这几个字母跟你的名字差不多吧？」", "gen417_025.ogg", "旅館_旅館前b", "bgm35.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-1", null, null], [2527, "玄十郎", "「这应该就读“列支敦瑙尔”吧，你看看是不是？」", "gen417_026.ogg", "旅館_旅館前b", "bgm35.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "09"}, "CHAPTER 5-1", null, null], [2528, "蕾娜", "「大、大当家……这个、最下面的这个名字！和我爷爷的奶奶的名字一模一样」", "len417_149.ogg", "旅館_旅館前b", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "06"}, "CHAPTER 5-1", null, null], [2529, "玄十郎", "「喔喔，上面两个名字应该是技师本人和夫人，最下面这个肯定就是他们女儿了」", "gen417_027.ogg", "旅館_旅館前b", "bgm35.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "15"}, "CHAPTER 5-1", null, null], [2530, "将臣", "「这些大概都是明治时期的东西了吧？这么老的店簿，竟然能留到现在」", null, "旅館_旅館前b", "bgm35.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "15"}, "CHAPTER 5-1", null, null], [2531, "玄十郎", "「我就猜到店簿有可能还留着」", "gen417_028.ogg", "旅館_旅館前b", "bgm35.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "02"}, "CHAPTER 5-1", null, null], [2532, "玄十郎", "「所以就去仓库里面翻了翻，刚刚才好不容易把它找出来」", "gen417_029.ogg", "旅館_旅館前b", "bgm35.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "15"}, "CHAPTER 5-1", null, null], [2533, "", "这下就可以肯定了。", null, "旅館_旅館前b", "bgm35.opus", null, "CHAPTER 5-1", null, null], [2534, "将臣", "「昨天的梦是真实发生过的事」", null, "旅館_旅館前b", "bgm35.opus", null, "CHAPTER 5-1", null, null], [2535, "蕾娜", "「没错……我爷爷的爷爷是穗织人，这我以前就知道」", "len417_150.ogg", "旅館_旅館前b", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-1", null, null], [2536, "蕾娜", "「但我并不了解他所有的事情……」", "len417_151.ogg", "旅館_旅館前b", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "22"}, "CHAPTER 5-1", null, null], [2537, "", "蕾娜一边感慨，一边用手指抚摸着账本上的名字。", null, "旅館_旅館前b", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "22"}, "CHAPTER 5-1", null, null], [2538, "玄十郎", "「真是缘分啊」", "gen417_030.ogg", "旅館_旅館前b", "bgm35.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "03"}, "CHAPTER 5-1", null, null], [2539, "蕾娜", "「这是，缘分吗？」", "len417_152.ogg", "旅館_旅館前b", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "20"}, "CHAPTER 5-1", null, null], [2540, "玄十郎", "「嗯，你祖上曾经住过这里，而你又作为他们的后代，来到这里工作」", "gen417_031.ogg", "旅館_旅館前b", "bgm35.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "09"}, "CHAPTER 5-1", null, null], [2541, "玄十郎", "「这些事谁也不曾预料到」", "gen417_032.ogg", "旅館_旅館前b", "bgm35.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "07"}, "CHAPTER 5-1", null, null], [2542, "玄十郎", "「这若不是缘分，还能是什么呢」", "gen417_033.ogg", "旅館_旅館前b", "bgm35.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "15"}, "CHAPTER 5-1", null, null], [2543, "将臣", "「确实」", null, "旅館_旅館前b", "bgm35.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "15"}, "CHAPTER 5-1", null, null], [2544, "", "这些信息本身，或许并不意味着事情有了多大的进展。", null, "旅館_旅館前b", "bgm35.opus", null, "CHAPTER 5-1", null, null], [2545, "", "但毫无疑问的是，穗织这片土地和蕾娜之间――", null, "旅館_旅館前b", "bgm35.opus", null, "CHAPTER 5-1", null, null], [2546, "", "――确实有着不可思议的缘分。", null, "旅館_旅館前b", "bgm35.opus", null, "CHAPTER 5-1", null, null], [2547, "", "我好像……又来到了那个梦境……", null, "空_青空", "bgm36.opus", null, "CHAPTER 5-2", null, null], [2548, "", "而且这次的梦，始于列支敦瑙尔先生的女儿，也就是蕾娜的爷爷的奶奶。", null, "空_青空", "bgm36.opus", null, "CHAPTER 5-2", null, null], [2549, "", "少女似乎是孤身一人。", null, "空_青空", "bgm36.opus", null, "CHAPTER 5-2", null, null], [2550, "", "她来到穗织之后，大部分时间都是一个人度过的。", null, "空_青空", "bgm36.opus", null, "CHAPTER 5-2", null, null], [2551, "", "少女的父亲将前几天刚认识的日本青年聘为助手，两人每天都会去各个地方讲演，她的母亲也在父亲身边给他帮忙。", null, "空_青空", "bgm36.opus", null, "CHAPTER 5-2", null, null], [2552, "", "他们这么做，都是为了让当地人明白，蒸汽机车有多么厉害、多么安全。", null, "空_青空", "bgm36.opus", null, "CHAPTER 5-2", null, null], [2553, "", "……这些本来不知道的信息，也接连不断地从脑海中涌了出来。", null, "空_青空", "bgm36.opus", null, "CHAPTER 5-2", null, null], [2554, "", "小雨之前说过，这种情况可能是碎片中的记忆被重现了。看来她说的八成是真的。", null, "空_青空", "bgm36.opus", null, "CHAPTER 5-2", null, null], [2555, "", "少女来到穗织之后，时不时就会回头眺望后山的森林。", null, "旅館_旅館前a", "bgm36.opus", null, "CHAPTER 5-2", null, null], [2556, "", "她总觉得，那森林中似乎藏着什么可怕的东西，而且它正在呼唤着自己。这让她感到十分不可思议。", null, "旅館_旅館前a", "bgm36.opus", null, "CHAPTER 5-2", null, null], [2557, "母亲", "『不用害怕。如果你感觉森林里有什么东西，那它一定是山妖』", "khh418_001.ogg", "旅館_旅館前a", "bgm36.opus", null, "CHAPTER 5-2", null, null], [2558, "母亲", "『在妈妈的故乡也有山妖。它们是一种喜欢恶作剧的精灵』", "khh418_002.ogg", "旅館_旅館前a", "bgm36.opus", null, "CHAPTER 5-2", null, null], [2559, "", "……山妖？", null, "旅館_旅館前a", "bgm36.opus", null, "CHAPTER 5-2", null, null], [2560, "", "难道，少女的母亲是北欧人吗？", null, "旅館_旅館前a", "bgm36.opus", null, "CHAPTER 5-2", null, null], [2561, "母亲", "『你能看见山妖，就说明你很幸运，你以后肯定会比任何人都过得更幸福』", "khh418_003.ogg", "旅館_旅館前a", "bgm36.opus", null, "CHAPTER 5-2", null, null], [2562, "", "母亲经常说这些话来安慰少女。", null, "旅館_旅館前a", "bgm36.opus", null, "CHAPTER 5-2", null, null], [2563, "", "少女生来就和别人不太一样，她可以看见一些常人无法看见的东西。", null, "旅館_旅館前a", "bgm36.opus", null, "CHAPTER 5-2", null, null], [2564, "将臣", "「（什么？）」", null, "旅館_旅館前a", "bgm36.opus", null, "CHAPTER 5-2", null, null], [2565, "蕾娜", "「（哇哦！？我也是第一次听说）」", "len418_001.ogg", "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "06"}, "CHAPTER 5-2", null, null], [2566, "", "啊，蕾娜果然是跟我身处同一个梦境之中吗？", null, "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "06"}, "CHAPTER 5-2", null, null], [2567, "将臣", "「（总……总之，先继续看吧）」", null, "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "06"}, "CHAPTER 5-2", null, null], [2568, "蕾娜", "「（好、好的）」", "len418_002.ogg", "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "19"}, "CHAPTER 5-2", null, null], [2569, "", "再加上少女本来就很内向，她始终都没能和日本的小孩们打成一片。", null, "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "19"}, "CHAPTER 5-2", null, null], [2570, "", "而日本的小孩从未见过外国人，自然也不会主动和她搭话。", null, "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "19"}, "CHAPTER 5-2", null, null], [2571, "", "就这样，少女只能远远地看着大家玩耍。在旁人看来，她就像是被大家排斥在外一样。", null, "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "19"}, "CHAPTER 5-2", null, null], [2572, "蕾娜", "「（爷爷的奶奶好可怜啊……）」", "len418_003.ogg", "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "12"}, "CHAPTER 5-2", null, null], [2573, "将臣", "「（嗯，但这可能也是没办法的事）」", null, "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "12"}, "CHAPTER 5-2", null, null], [2574, "将臣", "「（毕竟当时的日本人既没听过，也没见过金发碧眼的女孩子」", null, "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "30"}, "CHAPTER 5-2", null, null], [2575, "蕾娜", "「（可、可是）」", "len418_004.ogg", "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "06"}, "CHAPTER 5-2", null, null], [2576, "", "最主要的是，少女自己也很害怕日本的男性。", null, "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "06"}, "CHAPTER 5-2", null, null], [2577, "", "他们一天到晚都绷着一张脸，很少露出笑容。", null, "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "06"}, "CHAPTER 5-2", null, null], [2578, "", "给父亲帮忙的那位青年就是典型的日本男儿。他那不苟言笑的神情，仿佛时刻都在说“软弱的人才会在妇孺面前露出笑容”。", null, "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "06"}, "CHAPTER 5-2", null, null], [2579, "少女", "「那个人肯定很讨厌我」", "ksb418_001.ogg", "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "06"}, "CHAPTER 5-2", null, null], [2580, "少女", "「可爸爸为什么会看中他呢」", "ksb418_002.ogg", "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "06"}, "CHAPTER 5-2", null, null], [2581, "蕾娜", "「（哎？……怎、怎怎怎么回事啊，将臣！？）」", "len418_005.ogg", "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "03"}, "CHAPTER 5-2", null, null], [2582, "蕾娜", "「（要是爷爷的奶奶不能跟爷爷的爷爷结婚，那我就没办法出生了呀！？」", "len418_006.ogg", "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "13"}, "CHAPTER 5-2", null, null], [2583, "将臣", "「（你冷静点！先别慌！）」", null, "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "13"}, "CHAPTER 5-2", null, null], [2584, "将臣", "「（总之先看看后续吧，看了之后才知道怎么回事）」", null, "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "13"}, "CHAPTER 5-2", null, null], [2585, "蕾娜", "「（可是，我爷爷跟我说，他们老两口关系很好的啊……」", "len418_007.ogg", "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "29"}, "CHAPTER 5-2", null, null], [2586, "少女", "「要是现在回去，那个人肯定还在……我还是先在外面转转吧」", "ksb418_003.ogg", "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "29"}, "CHAPTER 5-2", null, null], [2587, "少女", "「让我跟那个人待在一起，还不如让我一个人」", "ksb418_004.ogg", "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "29"}, "CHAPTER 5-2", null, null], [2588, "", "不……不是吧？蕾娜爷爷的爷爷竟然被讨厌成这样。", null, "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "29"}, "CHAPTER 5-2", null, null], [2589, "", "就连我也开始担心起来了。", null, "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "29"}, "CHAPTER 5-2", null, null], [2590, "少女", "「好想早点回国……」", "ksb418_005.ogg", "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "29"}, "CHAPTER 5-2", null, null], [2591, "少女", "「为什么要让我来这么远的国家啊」", "ksb418_006.ogg", "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "29"}, "CHAPTER 5-2", null, null], [2592, "少女", "「我在老家还有很多朋友呢，为什么偏偏让我跑来这里……」", "ksb418_007.ogg", "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "29"}, "CHAPTER 5-2", null, null], [2593, "", "就在这个时候，少女再一次感觉森林中有什么东西在呼唤自己。", null, "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "29"}, "CHAPTER 5-2", null, null], [2594, "少女", "「……哎？」", "ksb418_008.ogg", "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "29"}, "CHAPTER 5-2", null, null], [2595, "", "不知不觉，她已经朝着森林的方向迈出了步子。", null, "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "29"}, "CHAPTER 5-2", null, null], [2596, "", "她总感觉那边好像有自己的朋友。", null, "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "29"}, "CHAPTER 5-2", null, null], [2597, "", "当然，这是不可能的。", null, "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "29"}, "CHAPTER 5-2", null, null], [2598, "", "她努力克制住自己的好奇心，停下了脚步。然而——", null, "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "29"}, "CHAPTER 5-2", null, null], [2599, "青年", "「喂，你要去哪！」", "ksf418_001.ogg", "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "29"}, "CHAPTER 5-2", null, null], [2600, "少女", "「！！？」", "ksb418_009.ogg", "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "29"}, "CHAPTER 5-2", null, null], [2601, "", "少女吓了一跳，想也不想就冲了出去。", null, "山_山の中１a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "29"}, "CHAPTER 5-2", null, null], [2602, "", "紧接着，那个可怕的青年一边大喊大叫，一边拼命追了上来。", null, "山_山の中１a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "29"}, "CHAPTER 5-2", null, null], [2603, "", "少女什么也顾不上，没头没脑地在森林中四处逃窜。", null, "山_山の中１a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "29"}, "CHAPTER 5-2", null, null], [2604, "青年", "「……！？」", "ksf418_002.ogg", "山_山の中１a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "29"}, "CHAPTER 5-2", null, null], [2605, "", "身后似乎传来一声微弱的惨叫。", null, "山_山の中１a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "29"}, "CHAPTER 5-2", null, null], [2606, "", "然而，少女已经没有工夫去思考这声惨叫意味着什么了。", null, "山_山の中１a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "29"}, "CHAPTER 5-2", null, null], [2607, "", "随后——", null, "山_山の中２a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "29"}, "CHAPTER 5-2", null, null], [2608, "少女", "「啊……这……是哪儿？」", "ksb418_010.ogg", "山_山の中２a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "29"}, "CHAPTER 5-2", null, null], [2609, "", "少女在森林里迷路了。", null, "山_山の中２a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "29"}, "CHAPTER 5-2", null, null], [2610, "", "她在森林中走来走去，想回到村里。可走着走着，她就哭了出来。", null, "山_山の中２a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "29"}, "CHAPTER 5-2", null, null], [2611, "", "好想回去，好想回去…………好想合为一体。", null, "山_山の中２a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "29"}, "CHAPTER 5-2", null, null], [2612, "将臣", "「（嗯？）」", null, "山_山の中２a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "29"}, "CHAPTER 5-2", null, null], [2613, "", "少女的思考中似乎混入了杂音。", null, "山_山の中２a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "29"}, "CHAPTER 5-2", null, null], [2614, "少女", "「好想回去……回到哪？回到我的祖国，回到朋友们身边……」", "ksb418_011.ogg", "山_山の中２a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "29"}, "CHAPTER 5-2", null, null], [2615, "少女", "「想跟大家在一起……想合为一体」", "ksb418_012.ogg", "山_山の中２a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "29"}, "CHAPTER 5-2", null, null], [2616, "", "丛林深处似乎有什么动静。", null, "山_山の中２a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "29"}, "CHAPTER 5-2", null, null], [2617, "", "在这夜色中，那东西的形体并不明确。但是，那副模样就算想忘记也忘不掉。", null, "山_山の中２a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "29"}, "CHAPTER 5-2", null, null], [2618, "", "那是我们非常熟悉的气息。", null, "山_山の中２a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "29"}, "CHAPTER 5-2", null, null], [2619, "蕾娜", "「（是、是祟神！」", "len418_008.ogg", "山_山の中２a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "19"}, "CHAPTER 5-2", null, null], [2620, "少女", "「……山妖？」", "ksb418_013.ogg", "山_山の中２a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "19"}, "CHAPTER 5-2", null, null], [2621, "", "少女竟然伸出了手，想要触摸祟神。", null, "山_山の中２a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "19"}, "CHAPTER 5-2", null, null], [2622, "将臣", "「（啊，危险……哎？）」", null, "山_山の中２a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "19"}, "CHAPTER 5-2", null, null], [2623, "", "祟神不仅没有袭击少女，还允许少女随便触摸自己的身躯。", null, "山_山の中２a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "19"}, "CHAPTER 5-2", null, null], [2624, "", "好想合为一体……好想合为一体……", null, "山_山の中２a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "19"}, "CHAPTER 5-2", null, null], [2625, "少女", "「是吗，原来你也……」", "ksb418_014.ogg", "山_山の中２a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "19"}, "CHAPTER 5-2", null, null], [2626, "蕾娜", "「（爷爷的奶奶！？）」", "len418_009.ogg", "山_山の中２a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 5-2", null, null], [2627, "", "少女的双瞳失去了神采。", null, "山_山の中２a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 5-2", null, null], [2628, "", "难道是要被祟神操控了！？", null, "山_山の中２a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 5-2", null, null], [2629, "", "就在这时，一把十分眼熟的鉾铃贯穿了祟神的身体。", null, "山_山の中２a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 5-2", null, null], [2630, "", "这位手持鉾铃的女子正穿着我们见过多次的巫女服。", null, "山_山の中２a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 5-2", null, null], [2631, "", "难道是朝武！？不，不可能，应该是当时的巫女大人？", null, "山_山の中２a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 5-2", null, null], [2632, "", "跟在巫女大人身后的是一位壮年男子，他的衣着和常陆有几分相似。", null, "山_山の中２a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 5-2", null, null], [2633, "巫女大人", "「（没事了，已经安全了）」", "mkh418_001.ogg", "山_山の中２a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 5-2", null, null], [2634, "少女", "「？……啊，嗯」", "ksb418_015.ogg", "山_山の中２a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 5-2", null, null], [2635, "", "……没事了，已经安全了？", null, "山_山の中２a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 5-2", null, null], [2636, "", "虽然我们知道是什么意思，不过这位少女似乎听不懂日语？", null, "山_山の中２a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 5-2", null, null], [2637, "", "少女就这么在巫女大人的怀里昏了过去。", null, "山_山の中２a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 5-2", null, null], [2638, "", "回到志那都庄后，全村人都聚了过来。", null, "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 5-2", null, null], [2639, "村民", "「（还好没事，唉……这下就放心了）」", "gdb418_001.ogg", "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 5-2", null, null], [2640, "村民", "「（是啊，我们可担心你了）」", "gja418_001.ogg", "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 5-2", null, null], [2641, "少女", "「……？」", "ksb418_016.ogg", "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 5-2", null, null], [2642, "", "大家都一脸笑容，少女感到很不可思议，竟然没有任何人斥责自己。", null, "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 5-2", null, null], [2643, "", "其实穗织的村民们也都很关照来自异国的一家人，只是因为语言不通，所以不太敢主动交流而已。", null, "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 5-2", null, null], [2644, "", "少女终于明白，原来大家都很关心自己。", null, "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 5-2", null, null], [2645, "", "就在这时，那个总是不苟言笑的青年出现了。", null, "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 5-2", null, null], [2646, "", "只见他浑身是伤，还拖着一条绑着木棍的腿。", null, "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 5-2", null, null], [2647, "青年", "「抱歉……我不是想吓唬你。你没事就好……没事就好」", "ksf418_003.ogg", "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 5-2", null, null], [2648, "青年", "「我只是想提醒你，森林里面很危险，不要进去……很抱歉吓到你了」", "ksf418_004.ogg", "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 5-2", null, null], [2649, "少女", "「……～」", "ksb418_017.ogg", "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 5-2", null, null], [2650, "", "青年在追赶少女的途中，从斜坡上滑了下去。", null, "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 5-2", null, null], [2651, "", "尽管摔断了腿，青年还是爬回了村里，叫了人过来救少女。", null, "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 5-2", null, null], [2652, "", "看着青年哭丧着脸给自己道歉的样子，少女才终于明白。", null, "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 5-2", null, null], [2653, "", "原来他也是个心地善良的人。", null, "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 5-2", null, null], [2654, "少女", "「对不起，是我不好…………哎？」", "ksb418_018.ogg", "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 5-2", null, null], [2655, "", "少女张开手掌，发现手心里躺着一块碎片。", null, "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 5-2", null, null], [2656, "将臣", "「（那是宿体的碎片！）」", null, "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 5-2", null, null], [2657, "蕾娜", "「（跟我家代代相传的护身符长得一样呢）」", "len418_010.ogg", "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "15"}, "CHAPTER 5-2", null, null], [2658, "", "这肯定是山妖送给我的礼物。那么，它一定可以带来幸运。", null, "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "15"}, "CHAPTER 5-2", null, null], [2659, "", "自己之所以能和周围的人们打成一片，一定也是多亏了山妖。", null, "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "15"}, "CHAPTER 5-2", null, null], [2660, "", "至少，少女如此坚信。", null, "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "15"}, "CHAPTER 5-2", null, null], [2661, "少女", "「那、那个……这个就送给你了」", "ksb418_019.ogg", "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "15"}, "CHAPTER 5-2", null, null], [2662, "青年", "「……哎？」", "ksf418_005.ogg", "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "15"}, "CHAPTER 5-2", null, null], [2663, "少女", "「虽然是我捡的，但我觉得……这肯定是护身符」", "ksb418_020.ogg", "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "15"}, "CHAPTER 5-2", null, null], [2664, "少女", "「带着它，就一定可以比任何人都过得更幸福」", "ksb418_021.ogg", "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "15"}, "CHAPTER 5-2", null, null], [2665, "", "青年对着月亮，将碎片高高举起。", null, "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "15"}, "CHAPTER 5-2", null, null], [2666, "", "碎片银光闪闪，美得让人屏息。恐怕没人会相信它就是招致诅咒的元凶。", null, "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "15"}, "CHAPTER 5-2", null, null], [2667, "青年", "「嗯，你说的没错」", "ksf418_006.ogg", "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "15"}, "CHAPTER 5-2", null, null], [2668, "少女", "「……嗯」", "ksb418_022.ogg", "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "15"}, "CHAPTER 5-2", null, null], [2669, "", "两个内向的人，生平第一次和异性相视而笑。", null, "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "15"}, "CHAPTER 5-2", null, null], [2670, "蕾娜", "「（……）」", "len418_011.ogg", "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "01"}, "CHAPTER 5-2", null, null], [2671, "将臣", "「（……）」", null, "旅館_旅館前a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "01"}, "CHAPTER 5-2", null, null], [2672, "", "铁路延伸计划最终还是失败了。", null, "空_夜空", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "01"}, "CHAPTER 5-2", null, null], [2673, "", "不想破坏山妖居住的森林。希望穗织这片土地能得到良好的保护。", null, "空_夜空", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "01"}, "CHAPTER 5-2", null, null], [2674, "", "少女将自己的想法告诉了父亲，并说服了他。", null, "空_夜空", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "01"}, "CHAPTER 5-2", null, null], [2675, "", "列支敦瑙尔先生到底是一位绅士。", null, "空_夜空", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "01"}, "CHAPTER 5-2", null, null], [2676, "", "“其实，我也是这么想的。”面对爱女的恳求，他摸了摸自己的胡须回答道。", null, "空_夜空", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "01"}, "CHAPTER 5-2", null, null], [2677, "", "于是，穗织直到今天都还是一片交通不便的土地……", null, "空_夜空", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "01"}, "CHAPTER 5-2", null, null], [2678, "丛雨", "「唔～没想到蕾娜的祖上跟穗织有着如此密切的关系」", "mur418_001.ogg", "旅館_レナの部屋a", "bgm36.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "36"}, "CHAPTER 5-2", null, null], [2679, "", "听完了我的大段解说之后，小雨开始抱臂沉思。", null, "旅館_レナの部屋a", "bgm36.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "36"}, "CHAPTER 5-2", null, null], [2680, "茉子", "「如果当时蒸汽机车能进来，如今穗织应该也有电车了吧？」", "mak418_001.ogg", "旅館_レナの部屋a", "bgm36.opus", {"char": "茉子", "file": "茉子.stand", "dress": "忍者口", "face": "18"}, "CHAPTER 5-2", null, null], [2681, "芳乃", "「虽然想法很美好，不过想要开拓森林还是不太可能」", "yos418_001.ogg", "旅館_レナの部屋a", "bgm36.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "17"}, "CHAPTER 5-2", null, null], [2682, "芳乃", "「我觉得没开通铁路是好事」", "yos418_002.ogg", "旅館_レナの部屋a", "bgm36.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "07"}, "CHAPTER 5-2", null, null], [2683, "茉子", "「那是当然，但作为本地居民，心情还是挺复杂的」", "mak418_002.ogg", "旅館_レナの部屋a", "bgm36.opus", {"char": "茉子", "file": "茉子.stand", "dress": "忍者口", "face": "13"}, "CHAPTER 5-2", null, null], [2684, "将臣", "「……嗯」", null, "旅館_レナの部屋a", "bgm36.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "07"}, "CHAPTER 5-2", null, null], [2685, "", "朝武和常陆连连点头。", null, "旅館_レナの部屋a", "bgm36.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "07"}, "CHAPTER 5-2", null, null], [2686, "", "在她们身旁，我正一个人端正地坐在地上。", null, "旅館_レナの部屋a", "bgm36.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "07"}, "CHAPTER 5-2", null, null], [2687, "蕾娜", "「呼……呼～太好了……爷爷的，爷爷，还有爷爷的……奶奶」", "len418_012.ogg", "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-2", "ev405a", null], [2688, "", "在我身后，蕾娜还沉浸在梦乡之中。", null, "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-2", "ev405a", null], [2689, "", "无论是她那火辣的身材，还是那睡相，都极具视觉冲击力。", null, "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-2", "ev405a", null], [2690, "茉子", "「那么，有地。虽然这次情况跟上次差不多，但我们毕竟无法预料会出现什么状况」", "mak418_003.ogg", "旅館_レナの部屋a", "bgm25.opus", {"char": "茉子", "file": "茉子.stand", "dress": "忍者口", "face": "10"}, "CHAPTER 5-2", null, null], [2691, "茉子", "「所以为了以防万一，我们都跟着你过来了」", "mak418_004.ogg", "旅館_レナの部屋a", "bgm25.opus", {"char": "茉子", "file": "茉子.stand", "dress": "忍者口", "face": "01"}, "CHAPTER 5-2", null, null], [2692, "将臣", "「嗯」", null, "旅館_レナの部屋a", "bgm25.opus", {"char": "茉子", "file": "茉子.stand", "dress": "忍者口", "face": "01"}, "CHAPTER 5-2", null, null], [2693, "芳乃", "「当然了，我们知道这不是你的责任」", "yos418_003.ogg", "旅館_レナの部屋a", "bgm25.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "06"}, "CHAPTER 5-2", null, null], [2694, "芳乃", "「但是每天晚上都来的话，蕾娜也会很为难的吧？」", "yos418_004.ogg", "旅館_レナの部屋a", "bgm25.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "09"}, "CHAPTER 5-2", null, null], [2695, "芳乃", "「人家毕竟是女孩子……有些时候还是不希望被男生看见的」", "yos418_005.ogg", "旅館_レナの部屋a", "bgm25.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "09"}, "CHAPTER 5-2", "ev405a", null], [2696, "将臣", "「你说的我完全同意」", null, "旅館_レナの部屋a", "bgm25.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "09"}, "CHAPTER 5-2", "ev405a", null], [2697, "蕾娜", "「呼……呼……呼……嘿嘿嘿嘿」", "len418_013.ogg", "旅館_レナの部屋a", "bgm25.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "09"}, "CHAPTER 5-2", "ev405a", null], [2698, "", "虽然蕾娜说她并不在意，但她肯定不至于希望有人看见她这副样子。", null, "旅館_レナの部屋a", "bgm25.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "09"}, "CHAPTER 5-2", "ev405a", null], [2699, "芳乃", "「有地！你别盯着人家看啊」", "yos418_006.ogg", "旅館_レナの部屋a", "bgm25.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "17"}, "CHAPTER 5-2", null, null], [2700, "将臣", "「不……不是啊，我不是故意的！」", null, "旅館_レナの部屋a", "bgm25.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "17"}, "CHAPTER 5-2", null, null], [2701, "将臣", "「我睡觉的时候，把我绑在柱子上会不会比较好啊」", null, "旅館_レナの部屋a", "bgm25.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "30"}, "CHAPTER 5-2", null, null], [2702, "丛雨", "「那可不行。那样一来我们可能就无法获取有用的信息了」", "mur418_002.ogg", "旅館_レナの部屋a", "bgm25.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "26"}, "CHAPTER 5-2", null, null], [2703, "茉子", "「那您是让我们对他网开一面吗？」", "mak418_005.ogg", "旅館_レナの部屋a", "bgm25.opus", {"char": "茉子", "file": "茉子.stand", "dress": "忍者口", "face": "18"}, "CHAPTER 5-2", null, null], [2704, "丛雨", "「其实本座觉得你们根本不用担心蕾娜愿不愿意」", "mur418_003.ogg", "旅館_レナの部屋a", "bgm25.opus", {"char": "茉子", "file": "茉子.stand", "dress": "忍者口", "face": "18"}, "CHAPTER 5-2", null, null], [2705, "芳乃", "「丛雨大人，您的意思是……」", "yos418_007.ogg", "旅館_レナの部屋a", "bgm25.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "06"}, "CHAPTER 5-2", null, null], [2706, "蕾娜", "「呼呼……啊……是将臣～嘿」", "len418_014.ogg", "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-2", null, null], [2707, "将臣", "「哇，哎哎！蕾……蕾娜！？」", null, "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-2", null, null], [2708, "", "她突然从身后抱住了我。", null, "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-2", null, null], [2709, "", "虽然从这个角度看不见她，但我的后背感受到了一股宇宙大爆炸级别的压力。", null, "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-2", null, null], [2710, "将臣", "「不、不不、不行啊，蕾娜？你、你顶到我了……！」", null, "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-2", null, null], [2711, "蕾娜", "「嗯～拥抱……只是单纯的打招呼而已啊，呼呼……」", "len418_015.ogg", "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-2", null, null], [2712, "将臣", "「蕾、蕾娜？你别睡过去啊，不要就这样睡过去啊，蕾娜？蕾娜！？」", null, "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-2", null, null], [2713, "蕾娜", "「呼……呼呼～」", "len418_016.ogg", "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-2", null, null], [2714, "", "完了，她抱着我又睡了过去。", null, "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-2", null, null], [2715, "丛雨", "「反正，就是这么一回事」", "mur418_004.ogg", "旅館_レナの部屋a", "bgm25.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "28"}, "CHAPTER 5-2", null, null], [2716, "将臣", "「怎么一回事？」", null, "旅館_レナの部屋a", "bgm25.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "28"}, "CHAPTER 5-2", null, null], [2717, "茉子", "「哈哈，也就是说，我们是电灯泡咯？」", "mak418_006.ogg", "旅館_レナの部屋a", "bgm25.opus", {"char": "茉子", "file": "茉子.stand", "dress": "忍者口", "face": "31"}, "CHAPTER 5-2", null, null], [2718, "芳乃", "「呃，唔……就算如此，我觉得你们这样也不太好」", "yos418_008.ogg", "旅館_レナの部屋a", "bgm25.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "12"}, "CHAPTER 5-2", null, null], [2719, "将臣", "「朝武，如果你这么觉得，那就赶快过来帮忙把蕾娜拉开行吗？」", null, "旅館_レナの部屋a", "bgm25.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "12"}, "CHAPTER 5-2", null, null], [2720, "将臣", "「我一个人不太方便」", null, "旅館_レナの部屋a", "bgm25.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "12"}, "CHAPTER 5-2", null, null], [2721, "芳乃", "「不不，我要是这么做她可能会生气，还是算了吧」", "yos418_009.ogg", "旅館_レナの部屋a", "bgm25.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "27"}, "CHAPTER 5-2", null, null], [2722, "将臣", "「哎？别，等等啊！？」", null, "旅館_レナの部屋a", "bgm25.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "27"}, "CHAPTER 5-2", null, null], [2723, "", "朝武和常陆起身准备离开。", null, "旅館_レナの部屋a", "bgm25.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "42"}, "CHAPTER 5-2", null, null], [2724, "将臣", "「等、等等啊？你们都不帮帮我吗？」", null, "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-2", null, null], [2725, "茉子", "「因为你看上去不像是需要帮忙的样子，所以我们先走了，你们继续吧」", "mak418_007.ogg", "旅館_レナの部屋a", "bgm25.opus", {"char": "茉子", "file": "茉子.stand", "dress": "忍者口", "face": "23"}, "CHAPTER 5-2", null, null], [2726, "", "真的走了……", null, "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-2", null, null], [2727, "", "也罢，蕾娜从身后抱上来，我还是有点……不，还是非常开心的。", null, "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-2", null, null], [2728, "", "而且……大家好像也觉得，蕾娜对我……？", null, "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-2", null, null], [2729, "丛雨", "「主人，本座还有件事要说」", "mur418_005.ogg", "旅館_レナの部屋a", "bgm25.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "16"}, "CHAPTER 5-2", null, null], [2730, "将臣", "「啊，小雨还没走啊」", null, "旅館_レナの部屋a", "bgm25.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "16"}, "CHAPTER 5-2", null, null], [2731, "", "小雨去了蕾娜身后，难道是要帮我吗？", null, "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-2", null, null], [2732, "丛雨", "「喔喔喔，好软！好暖和啊，主人！」", "mur418_006.ogg", "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-2", null, null], [2733, "蕾娜", "「唔唔……嗯～好暖和哦」", "len418_017.ogg", "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-2", null, null], [2734, "将臣", "「喂，小雨，怎么连你也抱在蕾娜身上了」", null, "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-2", null, null], [2735, "", "我现在正支撑着两个人的体重。", null, "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-2", null, null], [2736, "丛雨", "「本座只是觉得，能够触碰到同性的身体，果然还是让人非常心安啊」", "mur418_007.ogg", "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-2", null, null], [2737, "将臣", "「喔……」", null, "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-2", null, null], [2738, "", "也对，现在蕾娜也可以摸到小雨了。", null, "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-2", null, null], [2739, "", "然而小雨并没有像对我一样对蕾娜撒娇，她对蕾娜还有几分客气。", null, "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-2", null, null], [2740, "将臣", "「就算你想抱，也不用趁人家睡觉的时候抱吧」", null, "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-2", null, null], [2741, "丛雨", "「你还好意思说本座」", "mur418_008.ogg", "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-2", null, null], [2742, "将臣", "「不不，我这是意外情况啊……你等她醒了，直接告诉她你想抱抱她不就行了」", null, "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-2", null, null], [2743, "将臣", "「她肯定不会说不情愿的」", null, "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-2", null, null], [2744, "丛雨", "「唔，可本座毕竟是神刀的管理者，还是要保持威严才行」", "mur418_009.ogg", "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-2", null, null], [2745, "", "小雨放开蕾娜，摆正了姿势。", null, "旅館_レナの部屋a", "bgm25.opus", null, "CHAPTER 5-2", null, null], [2746, "丛雨", "「先不说这个，主人，本座觉得这次的梦应该包含着什么重要的信息」", "mur418_010.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "22"}, "CHAPTER 5-2", null, null], [2747, "将臣", "「你抱她之前就是想说这个吗？」", null, "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "22"}, "CHAPTER 5-2", null, null], [2748, "", "小雨抱住蕾娜之前，确实是想跟我说些什么。", null, "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "11"}, "CHAPTER 5-2", null, null], [2749, "", "大概是说到一半看见了蕾娜那不设防的后背，没能抵御住诱惑吧。", null, "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "11"}, "CHAPTER 5-2", null, null], [2750, "丛雨", "「哎，你别打岔！这可是你告诉我们的事啊」", "mur418_011.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "28"}, "CHAPTER 5-2", null, null], [2751, "丛雨", "「你说蕾娜的高祖母也差点被祟神控制了」", "mur418_012.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "26"}, "CHAPTER 5-2", null, null], [2752, "将臣", "「是的」", null, "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "26"}, "CHAPTER 5-2", null, null], [2753, "丛雨", "「也就是说，蕾娜并不是第一个和碎片产生共鸣的人」", "mur418_013.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "14"}, "CHAPTER 5-2", null, null], [2754, "将臣", "「确实，蕾娜被控制时的状态，和她高祖母当时的状态很像」", null, "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "14"}, "CHAPTER 5-2", null, null], [2755, "将臣", "「但是小雨，你当时在哪呢？我在梦里看见巫女大人了，却没看见你」", null, "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "11"}, "CHAPTER 5-2", null, null], [2756, "丛雨", "「……那个巫女，跟芳乃长得很像是吧？」", "mur418_014.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "11"}, "CHAPTER 5-2", null, null], [2757, "丛雨", "「那应该就是７代以前的巫女了」", "mur418_015.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "24"}, "CHAPTER 5-2", null, null], [2758, "将臣", "「７代以前？」", null, "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "24"}, "CHAPTER 5-2", null, null], [2759, "丛雨", "「７代以前刚好差不多是那个时代」", "mur418_016.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "10"}, "CHAPTER 5-2", null, null], [2760, "", "蕾娜的爷爷的爷爷是４代以前……也就是说，朝武家换代的速度比普通家庭快了近一倍。", null, "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "10"}, "CHAPTER 5-2", null, null], [2761, "", "这让我再一次意识到了朝武家的巫女代代短命的现实。", null, "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "10"}, "CHAPTER 5-2", null, null], [2762, "丛雨", "「在那个时代，丛雨丸并没有执刀人」", "mur418_017.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "40"}, "CHAPTER 5-2", null, null], [2763, "丛雨", "「所以，本座可能并没有参加救援」", "mur418_018.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "11"}, "CHAPTER 5-2", null, null], [2764, "丛雨", "「因为就算本座找到了那位少女，也很难立刻通知别人」", "mur418_019.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "26"}, "CHAPTER 5-2", null, null], [2765, "将臣", "「也是，你能知道我的位置，是因为我被丛雨丸选中了」", null, "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "26"}, "CHAPTER 5-2", null, null], [2766, "丛雨", "「再加上语言不通，本座也听不到什么有用的信息」", "mur418_020.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "36"}, "CHAPTER 5-2", null, null], [2767, "将臣", "「原来如此，就算有重要的情报也没办法获取啊……」", null, "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "36"}, "CHAPTER 5-2", null, null], [2768, "", "但多亏了这场梦，我们再一次获取了那个时代的记忆。", null, "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "36"}, "CHAPTER 5-2", null, null], [2769, "丛雨", "「而且，当时就算问清了具体情况，恐怕也做不了什么」", "mur418_021.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "31"}, "CHAPTER 5-2", null, null], [2770, "将臣", "「确实，碎片的事是我们最近才知道的」", null, "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "31"}, "CHAPTER 5-2", null, null], [2771, "丛雨", "「主人，关于那个碎片，本座还有一事不解」", "mur418_022.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "10"}, "CHAPTER 5-2", null, null], [2772, "丛雨", "「那碎片并非是蕾娜祖祖辈辈传下来的，而是从她高祖母那一代传下来的」", "mur418_023.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "16"}, "CHAPTER 5-2", null, null], [2773, "丛雨", "「她高祖母以前没接触过碎片，却和碎片共鸣了」", "mur418_024.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "28"}, "CHAPTER 5-2", null, null], [2774, "将臣", "「啊！也就是说……蕾娜被操控，跟碎片并没有直接关系？」", null, "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "10"}, "CHAPTER 5-2", null, null], [2775, "丛雨", "「想回到原本所在之处，想和朋友们团聚……想合为一体」", "mur418_025.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "40"}, "CHAPTER 5-2", null, null], [2776, "丛雨", "「也许，这样的感情才是共鸣的真正原因？」", "mur418_026.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "14"}, "CHAPTER 5-2", null, null], [2777, "丛雨", "「蕾娜她会不会……心里也想着同样的事情？」", "mur418_027.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "26"}, "CHAPTER 5-2", null, null], [2778, "将臣", "「……」", null, "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "26"}, "CHAPTER 5-2", null, null], [2779, "", "突然我感觉眼前一黑。", null, "旅館_レナの部屋a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [2780, "丛雨", "「如果情况不够乐观，我们或许要考虑让蕾娜离开穗织才行」", "mur418_028.ogg", "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "25"}, "CHAPTER 5-2", null, null], [2781, "将臣", "「……………………」", null, "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "25"}, "CHAPTER 5-2", null, null], [2782, "", "小雨向蕾娜伸出了手，那娇小的指尖显得十分寂寞。", null, "旅館_レナの部屋a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "25"}, "CHAPTER 5-2", null, null], [2783, "", "然而，刚伸出一半，她又收了回来。", null, "旅館_レナの部屋a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [2784, "", "尽管想要触碰，却不能触碰。她的举动似乎正如此诉说着。", null, "旅館_レナの部屋a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [2785, "", "我……不知道该说些什么好。", null, "旅館_レナの部屋a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [2786, "", "小雨的意思是，应该让蕾娜回国吗？那这样一来……我就再也见不到她了？", null, "旅館_レナの部屋a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [2787, "蕾娜", "「呼呼……哎呀，将臣也在呀？」", "len418_018.ogg", "旅館_レナの部屋a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [2788, "将臣", "「蕾、蕾娜，你醒了啊？」", null, "旅館_レナの部屋a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [2789, "", "我尽量不让自己回头。", null, "旅館_レナの部屋a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [2790, "", "那玩意儿顶到我了。而且这触感告诉我，她的睡衣肯定敞开了不少，应该是接近半裸的状态。", null, "旅館_レナの部屋a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [2791, "蕾娜", "「是的……我梦见爷爷的爷爷，终于正式成为了爷爷的奶奶的爸爸的弟子」", "len418_019.ogg", "旅館_レナの部屋a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [2792, "蕾娜", "「他们在德国居住的期间……慢慢地就爱上了对方，嘿嘿嘿」", "len418_020.ogg", "旅館_レナの部屋a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [2793, "将臣", "「原、原来是这样啊……」", null, "旅館_レナの部屋a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [2794, "蕾娜", "「咦，将臣你怎么了？为什么不看着我……哇啊啊！？」", "len418_021.ogg", "旅館_レナの部屋a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [2795, "", "她好像终于意识到了自己现在是什么状态。", null, "旅館_レナの部屋a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [2796, "将臣", "「我、我先出去一会儿！再、再见」", null, "旅館_レナの部屋a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [2797, "蕾娜", "「先、先别走，将臣！」", "len418_022.ogg", "旅館_レナの部屋a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [2798, "", "哇啊，又、又顶上来了！", null, "旅館_レナの部屋a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [2799, "", "正当我准备站起来时，蕾娜又用力抱了上来。", null, "旅館_レナの部屋a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [2800, "将臣", "「怎、怎怎、怎么了？蕾娜」", null, "旅館_レナの部屋a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [2801, "蕾娜", "「你……你不要走」", "len418_023.ogg", "旅館_レナの部屋a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [2802, "", "哎哎哎哎！？不仅半裸着身子抱过来，还让我别走……大清早的就这么刺激吗！？", null, "旅館_レナの部屋a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [2803, "", "突然发现，小雨趁我不注意也溜了。", null, "旅館_レナの部屋a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [2804, "蕾娜", "「今、今天我还想跟你一起去学校」", "len418_024.ogg", "旅館_レナの部屋a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [2805, "蕾娜", "「所以……你先别走，等等我吧」", "len418_025.ogg", "旅館_レナの部屋a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [2806, "将臣", "「啊、喔，是这么回事啊」", null, "旅館_レナの部屋a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [2807, "", "说的也是。我到底在想些什么啊。", null, "旅館_レナの部屋a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [2808, "将臣", "「那我就去外面等你吧？抱歉，刚才又吓到你了」", null, "旅館_レナの部屋a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [2809, "蕾娜", "「嘿嘿，是我不好，刚才睡糊涂了」", "len418_026.ogg", "旅館_レナの部屋a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [2810, "", "我换了衣服，老老实实地在走廊上等她。", null, "旅館_廊下a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [2811, "将臣", "「呼。刚才真是吓到我了……」", null, "旅館_廊下a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [2812, "", "由于蕾娜的突然之举，我和小雨说到一半的话也没能得出什么结论。", null, "旅館_廊下a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [2813, "", "要考虑……让蕾娜回国吗？", null, "旅館_廊下a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [2814, "", "对她来说，回国肯定是最安全的。这我心里非常明白。", null, "旅館_廊下a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [2815, "", "突然，我想到了她爷爷的爷爷。", null, "旅館_廊下a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [2816, "将臣", "「也对，只要我也跟着去国外……」", null, "旅館_廊下a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [2817, "", "等等，不对不对不对！我为什么会思考这种问题啊？", null, "旅館_廊下a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [2818, "", "我都搞不懂自己想干什么了。", null, "旅館_廊下a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [2819, "蕾娜", "「让你久等了，将臣！」", "len418_027.ogg", "旅館_廊下a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "19"}, "CHAPTER 5-2", null, null], [2820, "将臣", "「啊，蕾娜，这么快就准备好了吗？」", null, "旅館_廊下a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "19"}, "CHAPTER 5-2", null, null], [2821, "蕾娜", "「嗯，接下来我还要干活，可能要让你再等一会儿了……」", "len418_028.ogg", "旅館_廊下a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "29"}, "CHAPTER 5-2", null, null], [2822, "蕾娜", "「对了，将臣，我还没对你说呢」", "len418_029.ogg", "旅館_廊下a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 5-2", null, null], [2823, "将臣", "「呃，说什么？」", null, "旅館_廊下a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 5-2", null, null], [2824, "蕾娜", "「早上好，将臣」", "len418_030.ogg", "旅館_廊下a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02"}, "CHAPTER 5-2", null, null], [2825, "将臣", "「噢噢……早上好，蕾娜」", null, "旅館_廊下a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02"}, "CHAPTER 5-2", null, null], [2826, "", "明明仅仅只是互道早安而已，我却感觉十分难为情。", null, "旅館_廊下a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 5-2", null, null], [2827, "", "尽管难为情，我们却依然凝视着对方，谁也不愿移开视线。", null, "旅館_廊下a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "34"}, "CHAPTER 5-2", null, null], [2828, "蕾娜", "「……」", "len418_031.ogg", "旅館_廊下a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "20"}, "CHAPTER 5-2", null, null], [2829, "将臣", "「…………」", null, "旅館_廊下a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "20"}, "CHAPTER 5-2", null, null], [2830, "蕾娜", "「……～～」", "len418_032.ogg", "旅館_廊下a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "04"}, "CHAPTER 5-2", null, null], [2831, "将臣", "「…………」", null, "旅館_廊下a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "04"}, "CHAPTER 5-2", null, null], [2832, "蕾娜", "「对、对了」", "len418_033.ogg", "旅館_廊下a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "03"}, "CHAPTER 5-2", null, null], [2833, "将臣", "「嗯？」", null, "旅館_廊下a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "03"}, "CHAPTER 5-2", null, null], [2834, "蕾娜", "「梦、梦里的事……是不是需要告诉大家？」", "len418_034.ogg", "旅館_廊下a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 5-2", null, null], [2835, "将臣", "「嗯，这、这个你不用担心……你睡醒之前，我已经告诉她们了」", null, "旅館_廊下a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 5-2", null, null], [2836, "蕾娜", "「原来如此……」", "len418_035.ogg", "旅館_廊下a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "17"}, "CHAPTER 5-2", null, null], [2837, "将臣", "「……嗯、嗯」", null, "旅館_廊下a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "17"}, "CHAPTER 5-2", null, null], [2838, "蕾娜", "「……」", "len418_036.ogg", "旅館_廊下a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "20h"}, "CHAPTER 5-2", null, null], [2839, "将臣", "「……」", null, "旅館_廊下a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "20h"}, "CHAPTER 5-2", null, null], [2840, "", "视线再一次交织。", null, "旅館_廊下a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "20h"}, "CHAPTER 5-2", null, null], [2841, "蕾娜", "「我、我差不多该去干活了」", "len418_037.ogg", "旅館_廊下a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "21"}, "CHAPTER 5-2", null, null], [2842, "将臣", "「嗯……嗯，加油啊，蕾娜」", null, "旅館_廊下a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "21"}, "CHAPTER 5-2", null, null], [2843, "蕾娜", "「……嗯，待会儿见」", "len418_038.ogg", "旅館_廊下a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "24"}, "CHAPTER 5-2", null, null], [2844, "", "蕾娜小跑着离开了，就像是要斩断这份不舍一样。", null, "旅館_廊下a", "bgm34.opus", null, "CHAPTER 5-2", null, null], [2845, "", "跑出一些距离后，她又回过头来，有些夸张地冲我挥手。", null, "旅館_廊下a", "bgm34.opus", null, "CHAPTER 5-2", null, null], [2846, "", "我也挥手示意。", null, "旅館_廊下a", "bgm34.opus", null, "CHAPTER 5-2", null, null], [2847, "", "随后，蕾娜终于消失在视线尽头。", null, "旅館_廊下a", "bgm34.opus", null, "CHAPTER 5-2", null, null], [2848, "", "也许我刚才不应该胡思乱想。一想到将来她可能离去，心里就会拂过一丝寂寥。", null, "旅館_廊下a", "bgm34.opus", null, "CHAPTER 5-2", null, null], [2849, "将臣", "「唉，不知不觉间……」", null, "旅館_廊下a", "bgm34.opus", null, "CHAPTER 5-2", null, null], [2850, "", "不知不觉间，她在我的心里已经变得如此重要。", null, "旅館_廊下a", "bgm34.opus", null, "CHAPTER 5-2", null, null], [2851, "茉子", "「大家都到齐了吧！」", "mak418_008.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "40"}, "CHAPTER 5-2", null, null], [2852, "茉子", "「现在我宣布，第１３７届“蕾娜·列支敦瑙尔对日本之误会何其多研讨大会”正式开始」", "mak418_009.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-2", null, null], [2853, "蕾娜", "「正式开始！」", "len418_039.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-2", null, null], [2854, "廉太郎", "「怎么一下子跳这么远啊」", "ren418_001.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "14"}, "CHAPTER 5-2", null, null], [2855, "小春", "「……我们办过这么多次吗？」", "koh418_001.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "11"}, "CHAPTER 5-2", null, null], [2856, "芳乃", "「其中的１３５次我估计也缺席了」", "yos418_010.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "27"}, "CHAPTER 5-2", null, null], [2857, "将臣", "「我说啊，之前我就在想，你这个命名方式是不是对蕾娜太不礼貌了？」", null, "学院_教室休憩a", "bgm44.opus", null, "CHAPTER 5-2", null, null], [2858, "蕾娜", "「嗯？我倒是不介意来着」", "len418_040.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "09"}, "CHAPTER 5-2", null, null], [2859, "蕾娜", "「你们愿意教我各种日本的小知识，我感谢还来不及呢」", "len418_041.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-2", null, null], [2860, "将臣", "「可是，说是让我们教你常识，但总感觉我们自己都没那么了解」", null, "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-2", null, null], [2861, "蕾娜", "「我觉得，这也挺正常的嘛」", "len418_042.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 5-2", null, null], [2862, "蕾娜", "「你要是让我介绍我们国家，我可能也说不清楚」", "len418_043.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "21"}, "CHAPTER 5-2", null, null], [2863, "将臣", "「可能确实是这样，但怎么说呢，总感觉有点不甘心」", null, "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "21"}, "CHAPTER 5-2", null, null], [2864, "芳乃", "「这次我想好好表现下，就当是挽回名誉了」", "yos418_011.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "42"}, "CHAPTER 5-2", null, null], [2865, "蕾娜", "「是、是吗，将臣，芳乃，你们不用这么较真啦」", "len418_044.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "21"}, "CHAPTER 5-2", null, null], [2866, "茉子", "「这么较真说不定也是好事嘛，蕾娜不这么觉得吗」", "mak418_010.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "23"}, "CHAPTER 5-2", null, null], [2867, "蕾娜", "「嗯，你说的有道理」", "len418_045.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "23"}, "CHAPTER 5-2", null, null], [2868, "", "二人相视一笑。", null, "学院_教室休憩a", "bgm44.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "23"}, "CHAPTER 5-2", null, null], [2869, "", "她们俩关系真好啊。", null, "学院_教室休憩a", "bgm44.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "23"}, "CHAPTER 5-2", null, null], [2870, "", "我感觉蕾娜无论对谁都没有隔阂，和每个人都能处好关系。", null, "学院_教室休憩a", "bgm44.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "23"}, "CHAPTER 5-2", null, null], [2871, "蕾娜", "「这一次，是我有个问题想问」", "len418_046.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-2", null, null], [2872, "将臣", "「啊，你有什么疑惑吗？」", null, "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-2", null, null], [2873, "蕾娜", "「是的！但我感觉这种问题问掌柜的可能有点不礼貌」", "len418_047.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "29"}, "CHAPTER 5-2", null, null], [2874, "小春", "「难道是跟志那都庄有关的问题吗？」", "koh418_002.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "05"}, "CHAPTER 5-2", null, null], [2875, "蕾娜", "「不是，我最开始以为只有掌柜的会那样，但后来发现并不是」", "len418_048.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "23"}, "CHAPTER 5-2", null, null], [2876, "蕾娜", "「志那都庄里面的人，还有外面的人，大家都一样」", "len418_049.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "08"}, "CHAPTER 5-2", null, null], [2877, "芳乃", "「那你快说说，到底是什么什么问题呢？」", "yos418_012.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "16"}, "CHAPTER 5-2", null, null], [2878, "", "朝武十分积极，大概是很想挽回名誉吧。", null, "学院_教室休憩a", "bgm44.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "16"}, "CHAPTER 5-2", null, null], [2879, "蕾娜", "「就是，日本人……」", "len418_050.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "20"}, "CHAPTER 5-2", null, null], [2880, "蕾娜", "「为什么在接电话的时候，会不停地鞠躬呢？」", "len418_051.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "07"}, "CHAPTER 5-2", null, null], [2881, "芳乃", "「……」", "yos418_013.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "26"}, "CHAPTER 5-2", null, null], [2882, "小春", "「哎？」", "koh418_003.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "06"}, "CHAPTER 5-2", null, null], [2883, "将臣", "「好像确实有这种情况。如果对方比自己年长，或者是上级领导的话就会这样」", null, "学院_教室休憩a", "bgm44.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "26"}, "CHAPTER 5-2", null, null], [2884, "茉子", "「我也有这个习惯」", "mak418_011.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "48"}, "CHAPTER 5-2", null, null], [2885, "芳乃", "「…………说来有些难为情，我好像也有这个习惯」", "yos418_014.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "30"}, "CHAPTER 5-2", null, null], [2886, "小春", "「呃，这个……我没什么印象来着？我好像，不会那样吧」", "koh418_004.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "07"}, "CHAPTER 5-2", null, null], [2887, "廉太郎", "「你说什么呢，你也经常那样啊」", "ren418_002.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "29"}, "CHAPTER 5-2", null, null], [2888, "小春", "「骗人，廉哥说的肯定都是骗人的！我才没那个习惯」", "koh418_005.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "34"}, "CHAPTER 5-2", null, null], [2889, "将臣", "「抱歉小春，我之前看见过你那样」", null, "学院_教室休憩a", "bgm44.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "34"}, "CHAPTER 5-2", null, null], [2890, "小春", "「竟、竟然连哥哥都这么说！？」", "koh418_006.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "08"}, "CHAPTER 5-2", null, null], [2891, "廉太郎", "「你看吧，你少在那一个人装模作样」", "ren418_003.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "06"}, "CHAPTER 5-2", null, null], [2892, "小春", "「你、你还有脸说我，你以前不也经常一边打电话一边下跪！想都不用想，对方肯定是女孩子吧？」", "koh418_007.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "05"}, "CHAPTER 5-2", null, null], [2893, "廉太郎", "「这……这个不要说出来啊！挖别人的黑历史很有意思吗？」", "ren418_004.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "13"}, "CHAPTER 5-2", null, null], [2894, "蕾娜", "「行啦行啦，你们俩别激动」", "len418_052.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 5-2", null, null], [2895, "小春", "「呜呜，可是为什么会这样呢？我好像完全没有意识到自己有这种习惯」", "koh418_008.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "29"}, "CHAPTER 5-2", null, null], [2896, "将臣", "「这种问题仔细想想还真不知道怎么回答。朝武，你知道是怎么回事吗？」", null, "学院_教室休憩a", "bgm44.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "29"}, "CHAPTER 5-2", null, null], [2897, "芳乃", "「哎？为、为什么问我啊？」", "yos418_015.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "06"}, "CHAPTER 5-2", null, null], [2898, "将臣", "「你不是想要挽回名誉吗？」", null, "学院_教室休憩a", "bgm44.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "06"}, "CHAPTER 5-2", null, null], [2899, "芳乃", "「话是这么说，可是……哎，好吧好吧」", "yos418_016.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "18"}, "CHAPTER 5-2", null, null], [2900, "芳乃", "「鞠躬，都是出于礼节……大概是这样」", "yos418_017.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "47"}, "CHAPTER 5-2", null, null], [2901, "茉子", "「可打电话的时候根本看不见对方吧？」", "mak418_012.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "03"}, "CHAPTER 5-2", null, null], [2902, "蕾娜", "「哪怕别人根本看不见，也绝对不能亏了礼数，是这个意思吗？」", "len418_053.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "03"}, "CHAPTER 5-2", null, null], [2903, "芳乃", "「哎？这个，怎么说呢……」", "yos418_018.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "39"}, "CHAPTER 5-2", null, null], [2904, "廉太郎", "「我觉得，这就是单纯的习惯吧？」", "ren418_005.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "24"}, "CHAPTER 5-2", null, null], [2905, "廉太郎", "「平常说话的时候养成了习惯，所以打电话的时候也难免会那样吧」", "ren418_006.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "18"}, "CHAPTER 5-2", null, null], [2906, "将臣", "「喔，有道理！对于日本人来说，鞠躬确实是一种习惯」", null, "学院_教室休憩a", "bgm44.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "18"}, "CHAPTER 5-2", null, null], [2907, "小春", "「也是，对我们来说鞠躬就是一件稀疏平常的事嘛。但是对外国人来说，可能看上去就比较奇怪了」", "koh418_009.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "07"}, "CHAPTER 5-2", null, null], [2908, "芳乃", "「……～」", "yos418_019.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "34"}, "CHAPTER 5-2", null, null], [2909, "茉子", "「鞍马加一分」", "mak418_013.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "23"}, "CHAPTER 5-2", null, null], [2910, "廉太郎", "「真的！？」", "ren418_007.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "26"}, "CHAPTER 5-2", null, null], [2911, "茉子", "「哈哈，恭喜你」", "mak418_014.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "27"}, "CHAPTER 5-2", null, null], [2912, "蕾娜", "「确实，不仅是打电话的时候，日本人在什么时候都……」", "len418_054.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-2", null, null], [2913, "蕾娜", "「啊，抱歉！我的手机响了」", "len418_055.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 5-2", null, null], [2914, "", "蕾娜拿出手机时，其他人也都一齐把手伸向了自己的手机。", null, "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 5-2", null, null], [2915, "", "仔细想想，这种习惯也挺常见的。", null, "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 5-2", null, null], [2916, "", "然而下一个瞬间，我这些不起眼的小思绪统统都被抛到了九霄云外。", null, "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 5-2", null, null], [2917, "蕾娜", "「啊！是掌柜的啊，嗯，是的，嗯……哇哦，是这样啊！」", "len418_056.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-2", null, null], [2918, "将臣", "「…………」", null, "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-2", null, null], [2919, "", "……咦？", null, "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-2", null, null], [2920, "蕾娜", "「那就麻烦您了，不不！没事的，好的，好的，谢谢」", "len418_057.ogg", "学院_教室休憩a", "bgm22.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "28"}, "CHAPTER 5-2", null, null], [2921, "蕾娜", "「好的！好的，那我先挂了，没事没事……再见」", "len418_058.ogg", "学院_教室休憩a", "bgm22.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-2", null, null], [2922, "", "蕾娜一边打电话，一边像会津若松的红牛玩具一样，不停地点头鞠躬。", null, "学院_教室休憩a", "bgm22.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-2", null, null], [2923, "", "这副样子，那些工薪族看见了肯定都会甘拜下风吧。", null, "学院_教室休憩a", "bgm22.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-2", null, null], [2924, "蕾娜", "「我家里给我寄的国际快递刚才送到了，所以掌柜的打了个电话过来」", "len418_059.ogg", "学院_教室休憩a", "bgm22.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-2", null, null], [2925, "廉太郎", "「哦、哦」", "ren418_008.ogg", "学院_教室休憩a", "bgm22.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "13"}, "CHAPTER 5-2", null, null], [2926, "小春", "「这样啊，里面装的是什么呢」", "koh418_010.ogg", "学院_教室休憩a", "bgm22.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "11"}, "CHAPTER 5-2", null, null], [2927, "蕾娜", "「这个我也不知道，不过还挺期待的！对了，刚才我的话好像还没说完呢，真是不好意思」", "len418_060.ogg", "学院_教室休憩a", "bgm22.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "30"}, "CHAPTER 5-2", null, null], [2928, "蕾娜", "「对日本人来说鞠躬已经是一种习惯了吧？养成了习惯的话，不知不觉中把习惯表现出来，大概也是难免的」", "len418_061.ogg", "学院_教室休憩a", "bgm22.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "28"}, "CHAPTER 5-2", null, null], [2929, "将臣", "「……嗯确实」", null, "学院_教室休憩a", "bgm22.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "28"}, "CHAPTER 5-2", null, null], [2930, "芳乃", "「是、是的，对日本人来说」", "yos418_020.ogg", "学院_教室休憩a", "bgm22.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "22"}, "CHAPTER 5-2", null, null], [2931, "", "对日本人来说鞠躬是一种习惯……真的是只对日本人来说吗？", null, "学院_教室休憩a", "bgm22.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "22"}, "CHAPTER 5-2", null, null], [2932, "茉子", "「毕竟，习惯这个东西是会传染的嘛」", "mak418_015.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-2", null, null], [2933, "将臣", "「原来如此，如果身边的人都有那个习惯，不知不觉中自己也会养成一样的习惯吗？」", null, "学院_教室休憩a", "bgm44.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-2", null, null], [2934, "蕾娜", "「嗯？你们在说什么？」", "len418_062.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-2", null, null], [2935, "将臣", "「没什么……就是在想，你已经完全融入日本社会了」", null, "学院_教室休憩a", "bgm44.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-2", null, null], [2936, "茉子", "「我们大概已经没什么事情可以教你了」", "mak418_016.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "23"}, "CHAPTER 5-2", null, null], [2937, "蕾娜", "「哇哦！你们已经把毕生所学都教给我了吗！？」", "len418_063.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-2", null, null], [2938, "芳乃", "「嗯……我感觉自己已经比不上你了」", "yos418_021.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "27"}, "CHAPTER 5-2", null, null], [2939, "蕾娜", "「嘿嘿嘿，没那回事啦。以后有不懂的我还想多请教请教芳乃呢」", "len418_064.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-2", null, null], [2940, "", "我很想对朝武说，你不要灰心。", null, "学院_教室休憩a", "bgm44.opus", null, "CHAPTER 5-2", null, null], [2941, "", "因为，若要说比不上蕾娜，其实我们在座的所有人都比不上她。", null, "学院_教室休憩a", "bgm44.opus", null, "CHAPTER 5-2", null, null], [2942, "", "放学后，我和蕾娜一同出了学校，准备去诊所。", null, "街_雰囲気モブa", "bgm37.opus", null, "CHAPTER 5-2", null, null], [2943, "蕾娜", "「驹川大夫到底找我们有什么事呢？」", "len418_065.ogg", "街_雰囲気モブa", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "30"}, "CHAPTER 5-2", null, null], [2944, "将臣", "「她听说了我们今早做的梦，所以想直接问我们一些事情」", null, "街_雰囲気モブa", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "30"}, "CHAPTER 5-2", null, null], [2945, "将臣", "「而且，好像还有一些事情要告诉我们」", null, "街_雰囲気モブa", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "30"}, "CHAPTER 5-2", null, null], [2946, "蕾娜", "「哇哦，她是不是有什么新的发现呢？」", "len418_066.ogg", "街_雰囲気モブa", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "20"}, "CHAPTER 5-2", null, null], [2947, "将臣", "「大概吧」", null, "街_雰囲気モブa", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "20"}, "CHAPTER 5-2", null, null], [2948, "", "这也说明驹川大夫平时都在为了我们的事做各种调查。", null, "街_雰囲気モブa", "bgm37.opus", null, "CHAPTER 5-2", null, null], [2949, "", "虽然她的调查专业性太强，我们帮不上忙，但把和我们自己身体有关的事全都交给别人，还是有点过意不去。", null, "街_雰囲気モブa", "bgm37.opus", null, "CHAPTER 5-2", null, null], [2950, "", "如果能安全取出所有碎片……蕾娜应该就没必要离开穗织了。", null, "街_雰囲気モブa", "bgm37.opus", null, "CHAPTER 5-2", null, null], [2951, "蕾娜", "「嗯？怎么了，将臣？」", "len418_067.ogg", "街_雰囲気モブa", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-2", null, null], [2952, "将臣", "「不，没什么」", null, "街_雰囲気モブa", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-2", null, null], [2953, "蕾娜", "「你骗人，你刚才脸上闪了了一丝寂寞的表情」", "len418_068.ogg", "街_雰囲気モブa", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "12"}, "CHAPTER 5-2", null, null], [2954, "将臣", "「……哎？不是吧，我觉得还好啊？」", null, "街_雰囲気モブa", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "12"}, "CHAPTER 5-2", null, null], [2955, "", "我就怕自己的想法反应在脸上，所以一直都很克制自己的表情。", null, "街_雰囲気モブa", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "12"}, "CHAPTER 5-2", null, null], [2956, "蕾娜", "「嘿嘿，因为我每时每刻都在仔细观察你，所以我是不会看错的」", "len418_069.ogg", "街_雰囲気モブa", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-2", null, null], [2957, "将臣", "「……蕾娜？」", null, "街_雰囲気モブa", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-2", null, null], [2958, "蕾娜", "「我懂了，你是想这样，是吧」", "len418_070.ogg", "街_雰囲気モブa", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "17"}, "CHAPTER 5-2", null, null], [2959, "", "蕾娜再一次攥住了我的手。", null, "街_雰囲気モブa", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 5-2", null, null], [2960, "蕾娜", "「是不是因为今天没跟我牵手，所以觉得寂寞啦？」", "len418_071.ogg", "街_雰囲気モブa", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 5-2", null, null], [2961, "将臣", "「啊，嗯……哈哈，这你都看出来了」", null, "街_雰囲気モブa", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 5-2", null, null], [2962, "蕾娜", "「呵呵呵，那是当然了……嘿嘿」", "len418_072.ogg", "街_雰囲気モブa", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "03"}, "CHAPTER 5-2", null, null], [2963, "", "当然事实并不是这样。但是，严格来讲也并不算错。", null, "街_雰囲気モブa", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "03"}, "CHAPTER 5-2", null, null], [2964, "", "因为……我确实越来越舍不得离开蕾娜了。", null, "街_雰囲気モブa", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "03"}, "CHAPTER 5-2", null, null], [2965, "美津叶", "「哟？几天没见，你们都这么亲密了啊」", "miz418_001.ogg", "街_診療所a", "bgm37.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "04"}, "CHAPTER 5-2", null, null], [2966, "将臣", "「啊、啊啊，这个不是……！」", null, "街_診療所a", "bgm37.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "04"}, "CHAPTER 5-2", null, null], [2967, "", "糟了，进了诊所之后我们依然牵着手。", null, "街_診療所a", "bgm37.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "04"}, "CHAPTER 5-2", null, null], [2968, "", "蕾娜低着头，脸颊羞得通红。", null, "街_診療所a", "bgm37.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "04"}, "CHAPTER 5-2", null, null], [2969, "蕾娜", "「……～～～嘿嘿，我们看起来很亲密吗？」", "len418_073.ogg", "街_診療所a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27h"}, "CHAPTER 5-2", null, null], [2970, "美津叶", "「不，就只是感觉你们像关系很好的朋友」", "miz418_002.ogg", "街_診療所a", "bgm37.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "07"}, "CHAPTER 5-2", null, null], [2971, "", "真是一语中的啊。看来姜还是老的辣。", null, "街_診療所a", "bgm37.opus", null, "CHAPTER 5-2", null, null], [2972, "", "不过，蕾娜看上去有些不高兴。", null, "街_診療所a", "bgm37.opus", null, "CHAPTER 5-2", null, null], [2973, "美津叶", "「话是这么说，看你们这样子估计也就是时间问题了」", "miz418_003.ogg", "街_診療所a", "bgm37.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "04"}, "CHAPTER 5-2", null, null], [2974, "将臣", "「啊？」", null, "街_診療所a", "bgm37.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "04"}, "CHAPTER 5-2", null, null], [2975, "蕾娜", "「是、是吗……那我会再接再厉的」", "len418_074.ogg", "街_診療所a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-2", null, null], [2976, "", "……再接再厉什么？如果我真这么问，是不是太不解风情了？", null, "街_診療所a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-2", null, null], [2977, "美津叶", "「行了，先来说正事吧」", "miz418_004.ogg", "街_診療所a", "bgm37.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "16"}, "CHAPTER 5-2", null, null], [2978, "美津叶", "「你们连续两天都做了那个梦吧？可以跟我详细讲讲吗？」", "miz418_005.ogg", "街_診療所a", "bgm37.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "05"}, "CHAPTER 5-2", null, null], [2979, "将臣", "「好的」", null, "街_診療所a", "bgm37.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "05"}, "CHAPTER 5-2", null, null], [2980, "蕾娜", "「没问题！」", "len418_075.ogg", "街_診療所a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "17"}, "CHAPTER 5-2", null, null], [2981, "", "从蕾娜的高祖父和高祖母的邂逅开始，到他们得到碎片的全过程，我和蕾娜一边相互补充，一边详细地讲了一遍。", null, "街_診療所a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [2982, "", "驹川大夫静静地听完了我们讲的所有内容。", null, "街_診療所a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [2983, "美津叶", "「合体祟神出现时列支敦瑙尔小姐也做了梦，可当时的梦和这些梦差别相当大啊」", "miz418_006.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "14"}, "CHAPTER 5-2", null, null], [2984, "将臣", "「确实，现在做的梦几乎全是跟蕾娜的祖上有关的」", null, "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "14"}, "CHAPTER 5-2", null, null], [2985, "美津叶", "「这次的梦，有没有什么地方跟之前的梦有关联呢？」", "miz418_007.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "05"}, "CHAPTER 5-2", null, null], [2986, "蕾娜", "「唔，抱歉……我印象中好像没有」", "len418_076.ogg", "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "12"}, "CHAPTER 5-2", null, null], [2987, "美津叶", "「没事，没有也无妨」", "miz418_008.ogg", "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "12"}, "CHAPTER 5-2", null, null], [2988, "美津叶", "「只是，我今天要告诉你们的事情，是跟第一次的梦有关的」", "miz418_009.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "30"}, "CHAPTER 5-2", null, null], [2989, "将臣", "「啊，原来如此」", null, "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "30"}, "CHAPTER 5-2", null, null], [2990, "美津叶", "「列支敦瑙尔小姐，在你第一次做的梦中出现过一条白色的狗是吧？」", "miz418_010.ogg", "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "34"}, "CHAPTER 5-2", null, null], [2991, "蕾娜", "「对，没错」", "len418_077.ogg", "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "23"}, "CHAPTER 5-2", null, null], [2992, "将臣", "「当时我们猜测，那可能就是被当做祭品的狗」", null, "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "23"}, "CHAPTER 5-2", null, null], [2993, "蕾娜", "「但是那只狗还说话了，看上去不像是普通的狗」", "len418_078.ogg", "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "31"}, "CHAPTER 5-2", null, null], [2994, "美津叶", "「嗯，这件事我也一直很在意」", "miz418_011.ogg", "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "31"}, "CHAPTER 5-2", null, null], [2995, "美津叶", "「在日本，自古以来白色的动物都被当做神的使者来看待」", "miz418_012.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "14"}, "CHAPTER 5-2", null, null], [2996, "将臣", "「您是说，它可能真的是神的使者吗？」", null, "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "14"}, "CHAPTER 5-2", null, null], [2997, "美津叶", "「如果那只圣兽真的被拿来献祭了，诅咒的效力这么强也就不奇怪了吧？」", "miz418_013.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "32"}, "CHAPTER 5-2", null, null], [2998, "美津叶", "「不过，它既然会被区区人类捉来献祭，可能本身也并不是那么厉害的神」", "miz418_014.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "24"}, "CHAPTER 5-2", null, null], [2999, "美津叶", "「总之，你们先看看这个」", "miz418_015.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "05"}, "CHAPTER 5-2", null, null], [3000, "", "照片？仔细一看，照片里是一幅老旧的绘卷。", null, "街_診療所a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [3001, "", "可是，这！这到底是怎么回事！？", null, "街_診療所a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [3002, "蕾娜", "「上面画了一条白色的狗，还有一位女性，可是……将臣，你看这个人……」", "len418_079.ogg", "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-2", null, null], [3003, "将臣", "「嗯、嗯……看上去并不像是最近刚画的吧？」", null, "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-2", null, null], [3004, "美津叶", "「确切的作画时间可能需要拿到大学的实验室里检查一下才知道」", "miz418_016.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "26"}, "CHAPTER 5-2", null, null], [3005, "美津叶", "「但是，原物目前应该就在朝武家的仓库里」", "miz418_017.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "14"}, "CHAPTER 5-2", null, null], [3006, "美津叶", "「可以肯定的是，这东西非常古老，甚至不能轻易让它接触空气」", "miz418_018.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "01"}, "CHAPTER 5-2", null, null], [3007, "美津叶", "「就连这张照片，都是在我出生的很久以前拍摄的」", "miz418_019.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "31"}, "CHAPTER 5-2", null, null], [3008, "美津叶", "「我听说把这绘卷取出的那一瞬间，上面的颜色就掉了大半，所以照片中绘卷的颜色未必是原本的颜色」", "miz418_020.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "32"}, "CHAPTER 5-2", null, null], [3009, "美津叶", "「顺便一提，这张照片的实物也是非常贵重的资料，我是先把照片扫进了电脑里，又打印了出来」", "miz418_021.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "07"}, "CHAPTER 5-2", null, null], [3010, "美津叶", "「你们现在看的就是我打印的版本」", "miz418_022.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "02"}, "CHAPTER 5-2", null, null], [3011, "将臣", "「也就是说，这东西真的非常古老吗？那就更奇怪了吧」", null, "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "02"}, "CHAPTER 5-2", null, null], [3012, "将臣", "「毕竟，您看嘛，这位女子的头发……」", null, "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "02"}, "CHAPTER 5-2", null, null], [3013, "蕾娜", "「是一位金发的，美女」", "len418_080.ogg", "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "06"}, "CHAPTER 5-2", null, null], [3014, "", "难道说在古代的日本，也有过金发的女子吗？", null, "街_診療所a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [3015, "", "至少我从来没在古代的绘卷中见过黑发以外的人物。", null, "街_診療所a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [3016, "美津叶", "「所以刚才也说了，有可能只是掉了色而已」", "miz418_023.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "30"}, "CHAPTER 5-2", null, null], [3017, "美津叶", "「因为太久远了，几乎没留下什么文字资料，所以根本搞不清楚这位女子到底是谁」", "miz418_024.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "32"}, "CHAPTER 5-2", null, null], [3018, "蕾娜", "「不、不过，在梦里……那只白狗，叫我姐姐」", "len418_081.ogg", "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 5-2", null, null], [3019, "美津叶", "「嗯，要是没有你这句话，我可能根本就不会把这绘卷当回事」", "miz418_025.ogg", "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 5-2", null, null], [3020, "美津叶", "「我的想法和有地一样，那么多年前日本应该是不可能有金发女子的」", "miz418_026.ogg", "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 5-2", null, null], [3021, "美津叶", "「但是，你仔细看她身后……虽然颜色很淡，但好像画着一圈光环。说不定，这位女子也是一位神祇」", "miz418_027.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "29"}, "CHAPTER 5-2", null, null], [3022, "", "金发的女子是一位女神，而她的使者或者说她的弟弟，就是这只白犬吗？", null, "街_診療所a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [3023, "将臣", "「难道是因为蕾娜跟这位女神发色一样，所以才被认错了？」", null, "街_診療所a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [3024, "蕾娜", "「可、可是，光说金发女子的话，穗织还经常有海外游客来游玩呢」", "len418_082.ogg", "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-2", null, null], [3025, "将臣", "「但是他们基本上不会半夜上山吧？」", null, "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-2", null, null], [3026, "将臣", "「而且，当时你可能刚好处于容易跟碎片产生共鸣的精神状态之中」", null, "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-2", null, null], [3027, "蕾娜", "「……和精神状态也有关系吗？」", "len418_083.ogg", "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "06"}, "CHAPTER 5-2", null, null], [3028, "", "啊，我这么说是不是有点欠考虑了？", null, "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "06"}, "CHAPTER 5-2", null, null], [3029, "", "小雨今早说过，蕾娜可能心里也有“想回家”“想团聚”的心情。", null, "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "06"}, "CHAPTER 5-2", null, null], [3030, "", "这种事只有本人才知道，但如果真是这样，那我……？", null, "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "06"}, "CHAPTER 5-2", null, null], [3031, "美津叶", "「先就此打住吧，光靠猜测来判断问题也不太好。我想再去找找相关的资料，你们觉得呢？」", "miz418_028.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "27"}, "CHAPTER 5-2", null, null], [3032, "将臣", "「呃，好的」", null, "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "27"}, "CHAPTER 5-2", null, null], [3033, "蕾娜", "「当然了，这样是最好的」", "len418_084.ogg", "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-2", null, null], [3034, "美津叶", "「谢谢。但是，你们也不要抱太高的期望」", "miz418_029.ogg", "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-2", null, null], [3035, "美津叶", "「在过去，越是重要的事情越是习惯于口口相传，而且后来还发生过战乱」", "miz418_030.ogg", "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-2", null, null], [3036, "将臣", "「也就是说，有可能当初什么资料都没留下来，想找也无处可找是吗？」", null, "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-2", null, null], [3037, "美津叶", "「没错」", "miz418_031.ogg", "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-2", null, null], [3038, "美津叶", "「还有可能是那些人为了诅咒穗织，专门去抓了这只狗来当祭品」", "miz418_032.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "14"}, "CHAPTER 5-2", null, null], [3039, "美津叶", "「这只狗的身份，说不定在当时还是有人知道的。这一点也值得我去调查一番」", "miz418_033.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "05"}, "CHAPTER 5-2", null, null], [3040, "", "驹川大夫说的没错。", null, "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "05"}, "CHAPTER 5-2", null, null], [3041, "", "但是这些调查，大概就只能拜托她了。", null, "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "05"}, "CHAPTER 5-2", null, null], [3042, "将臣", "「那就辛苦您了，我们静候您的佳音」", null, "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "05"}, "CHAPTER 5-2", null, null], [3043, "蕾娜", "「拜托您了」", "len418_085.ogg", "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "21"}, "CHAPTER 5-2", null, null], [3044, "美津叶", "「别这样，你们给我鞠躬，我总觉得有点担待不起」", "miz418_034.ogg", "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "21"}, "CHAPTER 5-2", null, null], [3045, "美津叶", "「其实，我现在的心情反而挺激动的」", "miz418_035.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "21"}, "CHAPTER 5-2", null, null], [3046, "将臣", "「是吗？」", null, "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "21"}, "CHAPTER 5-2", null, null], [3047, "美津叶", "「嗯，我甚至激动到都必须尽力克制自己了」", "miz418_036.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "24"}, "CHAPTER 5-2", null, null], [3048, "美津叶", "「怎么说呢……我也不想给你们施加压力，但有些话也就只有我才能说，其他人大都碍于立场或某些原因而不便说出口」", "miz418_037.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "33"}, "CHAPTER 5-2", null, null], [3049, "将臣", "「是吗，您是指哪些事呢？」", null, "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "33"}, "CHAPTER 5-2", null, null], [3050, "美津叶", "「其实，这么多年我们就像是在走钢丝一样」", "miz418_038.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "27"}, "CHAPTER 5-2", null, null], [3051, "蕾娜", "「走钢丝？」", "len418_086.ogg", "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "30"}, "CHAPTER 5-2", null, null], [3052, "美津叶", "「是的，对现代人来说可能难以想象，在这个诅咒刚开始的时候，医学是非常不发达的」", "miz418_039.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "30"}, "CHAPTER 5-2", null, null], [3053, "将臣", "「这么一说，倒也是」", null, "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "30"}, "CHAPTER 5-2", null, null], [3054, "美津叶", "「你真的能想象吗？」", "miz418_040.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "21"}, "CHAPTER 5-2", null, null], [3055, "美津叶", "「过去的女性，平均每１０人里就有１人不孕不育，每１０人里就有１人死于难产」", "miz418_041.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "29"}, "CHAPTER 5-2", null, null], [3056, "蕾娜", "「这、这么多吗……」", "len418_087.ogg", "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-2", null, null], [3057, "", "按最简单的算法，大概接近２０％的概率？", null, "街_診療所a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [3058, "", "真实的概率应该要比这低一些，但也足够高了。", null, "街_診療所a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [3059, "", "毕竟，朝武家的人……", null, "街_診療所a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [3060, "美津叶", "「本来就已经这么艰难了，但朝武家还只有女孩出生，而且——」", "miz418_042.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "14"}, "CHAPTER 5-2", null, null], [3061, "将臣", "「啊！」", null, "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "14"}, "CHAPTER 5-2", null, null], [3062, "蕾娜", "「……她们还会被祟神攻击吧？」", "len418_088.ogg", "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "15"}, "CHAPTER 5-2", null, null], [3063, "", "确实，这也是一个因素。", null, "街_診療所a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [3064, "", "但驹川大夫刚才想说却没说出口的，大概是朝武家的人都短命这件事。", null, "街_診療所a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [3065, "", "这导致他们家传宗接代的速度比普通人家快了近一倍，实在是过于残酷。", null, "街_診療所a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [3066, "", "而且每当有小孩出生时，都只能祈祷不要掉进那２０％的不幸之中。", null, "街_診療所a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [3067, "", "只要有一人出现意外，朝武家就会断了香火。", null, "街_診療所a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [3068, "", "这几百年，她们都是这么坚持过来的吗？", null, "街_診療所a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [3069, "", "仔细想想，这确实非常可怕。", null, "街_診療所a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [3070, "将臣", "「可以说是奇迹了」", null, "街_診療所a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [3071, "美津叶", "「奇迹吗……我倒是感觉，自己就像被迫走在一条永远看不见尽头的钢丝上一样」", "miz418_043.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "24"}, "CHAPTER 5-2", null, null], [3072, "美津叶", "「不过，也许正因为这是走钢丝，我们才坚持了下来」", "miz418_044.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "21"}, "CHAPTER 5-2", null, null], [3073, "", "因为时刻都要与死亡为伴，所以才能维系紧张感吗？", null, "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "21"}, "CHAPTER 5-2", null, null], [3074, "", "但是这也意味着，真正的幸福永远与自己无缘。", null, "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "21"}, "CHAPTER 5-2", null, null], [3075, "美津叶", "「幸运的是，现在我们终于看到了悬崖的对岸」", "miz418_045.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "02"}, "CHAPTER 5-2", null, null], [3076, "美津叶", "「说不定这条永远看不见尽头的钢丝，也还是有终点的」", "miz418_046.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "04"}, "CHAPTER 5-2", null, null], [3077, "蕾娜", "「您是指碎片……以及我们做的梦吗？」", "len418_089.ogg", "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "23"}, "CHAPTER 5-2", null, null], [3078, "", "只要没从钢丝上跌落下去，只要朝武家还有后人，这条钢丝就永无尽头……难道，以前大家都是这么想的吗？", null, "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "02"}, "CHAPTER 5-2", null, null], [3079, "美津叶", "「我这么说可能有点像陈词滥调，但这确实是我们的希望」", "miz418_047.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "04"}, "CHAPTER 5-2", null, null], [3080, "美津叶", "「我猜，像我这样按捺着心中激动的人，可比你想象的要多得多」", "miz418_048.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "23"}, "CHAPTER 5-2", null, null], [3081, "蕾娜", "「……」", "len418_090.ogg", "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "15"}, "CHAPTER 5-2", null, null], [3082, "将臣", "「……」", null, "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "15"}, "CHAPTER 5-2", null, null], [3083, "", "感觉自己肩负的责任非常重大。", null, "街_診療所a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [3084, "", "但我很庆幸驹川大夫能够告诉我。", null, "街_診療所a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [3085, "", "我觉得这些内情我也有责任知道。", null, "街_診療所a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [3086, "美津叶", "「当然，我最开始也说了，我并不想给你施加压力」", "miz418_049.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "21"}, "CHAPTER 5-2", null, null], [3087, "美津叶", "「你们完全可以放松点」", "miz418_050.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "22"}, "CHAPTER 5-2", null, null], [3088, "蕾娜", "「……好的」", "len418_091.ogg", "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "21"}, "CHAPTER 5-2", null, null], [3089, "美津叶", "「好了，那你们还有什么忘了说的，或者是需要补充的事吗？」", "miz418_051.ogg", "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "21"}, "CHAPTER 5-2", null, null], [3090, "美津叶", "「哪怕是一些细枝末节的信息，对我来说也很重要」", "miz418_052.ogg", "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "21"}, "CHAPTER 5-2", null, null], [3091, "将臣", "「这个，我倒没什么好补充的了……嗯？蕾娜？」", null, "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "06"}, "CHAPTER 5-2", null, null], [3092, "蕾娜", "「…………」", "len418_092.ogg", "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "06"}, "CHAPTER 5-2", null, null], [3093, "", "蕾娜低着头，一句话也不说。她这样也是挺少见的。", null, "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "06"}, "CHAPTER 5-2", null, null], [3094, "蕾娜", "「关于最开始的那个梦，我还有一件事没告诉你们。我也不是刻意隐瞒……」", "len418_093.ogg", "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-2", null, null], [3095, "蕾娜", "「就是感觉可能不怎么重要，所以就没说出来」", "len418_094.ogg", "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "12"}, "CHAPTER 5-2", null, null], [3096, "美津叶", "「最开始那个梦，也就是你被祟神操控的时候做的那个梦吗？」", "miz418_053.ogg", "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "12"}, "CHAPTER 5-2", null, null], [3097, "蕾娜", "「是的……梦里的我在志那都庄，差点吃下了那里的饭菜，这其实是有原因的」", "len418_095.ogg", "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-2", null, null], [3098, "蕾娜", "「因为当时我的家人都出现了，不止我爷爷……还有我爸爸妈妈」", "len418_096.ogg", "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-2", null, null], [3099, "将臣", "「！？」", null, "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-2", null, null], [3100, "蕾娜", "「大家都劝我快吃，还问我是不是感觉很寂寞」", "len418_097.ogg", "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-2", null, null], [3101, "蕾娜", "「还说什么“家庭就应该是一个整体”」", "len418_098.ogg", "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "07"}, "CHAPTER 5-2", null, null], [3102, "", "以前蕾娜提到自己的家人时，从来没提过自己的父母。", null, "街_診療所a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [3103, "", "我一直都很好奇她为什么不提。", null, "街_診療所a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [3104, "", "但我最关心的还是……蕾娜心里还是想回家吗？这个问题让我有种说不出的焦虑感。", null, "街_診療所a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [3105, "美津叶", "「问一个可能有点涉及隐私的问题，你的父母大概是什么样的人呢？」", "miz418_054.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "29"}, "CHAPTER 5-2", null, null], [3106, "蕾娜", "「我的家人，都各自住在不一样的地方」", "len418_099.ogg", "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "23"}, "CHAPTER 5-2", null, null], [3107, "蕾娜", "「他们都去了外地工作，有时会因为业绩出色而被挖去更好的公司，有时也会为了提升自己而主动跳槽」", "len418_100.ogg", "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-2", null, null], [3108, "蕾娜", "「可能是因为我从小就和爷爷很亲吧」", "len418_101.ogg", "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-2", null, null], [3109, "蕾娜", "「我爸爸妈妈都认为，哪怕是家人也不应该束缚对方的可能性，所以他们并没有住在一起」", "len418_102.ogg", "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "23"}, "CHAPTER 5-2", null, null], [3110, "", "哪怕是家人，也要各自追求属于自己的幸福。", null, "街_診療所a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [3111, "", "乍一听感觉很像外国人的价值观，但我印象中的外国人好像一般都比日本人更重视家庭。", null, "街_診療所a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [3112, "", "两种想法交织在一起，让我心情有些复杂。", null, "街_診療所a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [3113, "蕾娜", "「但我还是很支持爸爸妈妈的」", "len418_103.ogg", "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-2", null, null], [3114, "蕾娜", "「所以虽然我们没有住在一起，但每次见面的时候我都很开心，大家都是有说有笑的，关系非常和睦」", "len418_104.ogg", "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "24"}, "CHAPTER 5-2", null, null], [3115, "蕾娜", "「可是，梦里他们却说，家庭应该是一个整体」", "len418_105.ogg", "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "12"}, "CHAPTER 5-2", null, null], [3116, "蕾娜", "「当时我就无话可说了……」", "len418_106.ogg", "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "07"}, "CHAPTER 5-2", null, null], [3117, "将臣", "「……蕾娜」", null, "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "07"}, "CHAPTER 5-2", null, null], [3118, "蕾娜", "「梦醒之后，我感觉这些都是我个人的事情，所以就没有全部说出来」", "len418_107.ogg", "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "30"}, "CHAPTER 5-2", null, null], [3119, "蕾娜", "「抱歉……」", "len418_108.ogg", "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "06"}, "CHAPTER 5-2", null, null], [3120, "美津叶", "「没事，你这么想是理所当然的」", "miz418_055.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "21"}, "CHAPTER 5-2", null, null], [3121, "美津叶", "「但那条白狗竟然能唤醒你内心深处的感情，看来它确实不是一条普通的狗」", "miz418_056.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "14"}, "CHAPTER 5-2", null, null], [3122, "美津叶", "「你说它是女神的弟弟，那它自己可能也是一位神祇，而并非神的使者」", "miz418_057.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "30"}, "CHAPTER 5-2", null, null], [3123, "", "驹川大夫并没有进一步询问蕾娜的私事，只是冷静地分析着刚刚获取的信息。", null, "街_診療所a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [3124, "", "不过……就连一直都这么开朗的蕾娜，内心深处也藏着不为人知的孤独感吗？", null, "街_診療所a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [3125, "", "一想到这里，我心里就特别难受。", null, "街_診療所a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [3126, "", "但不管怎么说，我们也不可能立刻把蕾娜送回家。", null, "街_診療所a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [3127, "", "首先得取出她身体里的碎片才行，而且现在对于穗织来说，她可谓是黑暗中的一丝希望。", null, "街_診療所a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [3128, "", "但是，到底怎么做才是正确的呢？", null, "街_診療所a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [3129, "", "还有，究竟要花多长时间才能解决呢？", null, "街_診療所a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [3130, "", "我总是忍不住去思考这些事情。", null, "街_診療所a", "bgm39.opus", null, "CHAPTER 5-2", null, null], [3131, "", "我一路送蕾娜回到了志那都庄。", null, "旅館_旅館前b", "bgm35.opus", null, "CHAPTER 5-2", null, null], [3132, "", "天空已经被晚霞染得泛红，再过一会儿大概就会变成深蓝色了。", null, "旅館_旅館前b", "bgm35.opus", null, "CHAPTER 5-2", null, null], [3133, "蕾娜", "「将臣，谢谢你专程送我回来！」", "len418_109.ogg", "旅館_旅館前b", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-2", null, null], [3134, "将臣", "「这点小事，不算什么。毕竟你也陪着我到了这么晚」", null, "旅館_旅館前b", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-2", null, null], [3135, "蕾娜", "「嘿嘿，你在说什么傻话呢」", "len418_110.ogg", "旅館_旅館前b", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 5-2", null, null], [3136, "蕾娜", "「碎片的事也是我的事，所以不用跟我客气啦」", "len418_111.ogg", "旅館_旅館前b", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 5-2", null, null], [3137, "将臣", "「……嗯，也是」", null, "旅館_旅館前b", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 5-2", null, null], [3138, "", "是不是我想得太复杂了呢？", null, "旅館_旅館前b", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 5-2", null, null], [3139, "", "我一直觉得蕾娜完全是无辜的，都是我们连累了她。", null, "旅館_旅館前b", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 5-2", null, null], [3140, "蕾娜", "「喔，对了！你稍微等我一会儿」", "len418_112.ogg", "旅館_旅館前b", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-2", null, null], [3141, "将臣", "「哎？好的，我在这等你」", null, "旅館_旅館前b", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-2", null, null], [3142, "", "蕾娜跑进了志那都庄。", null, "旅館_旅館前b", "bgm35.opus", null, "CHAPTER 5-2", null, null], [3143, "", "到底是什么事呢？", null, "旅館_旅館前b", "bgm35.opus", null, "CHAPTER 5-2", null, null], [3144, "", "过了不到５分钟她就回来了，然后递给我一个小盒子。", null, "旅館_旅館前b", "bgm35.opus", null, "CHAPTER 5-2", null, null], [3145, "蕾娜", "「这个送给你」", "len418_113.ogg", "旅館_旅館前b", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 5-2", null, null], [3146, "将臣", "「我可以收下吗？我还从来没见过这种盒子，这难道是……零食之类的？」", null, "旅館_旅館前b", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 5-2", null, null], [3147, "蕾娜", "「是的！这是我们国家的零食，里面应该是糖」", "len418_114.ogg", "旅館_旅館前b", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-2", null, null], [3148, "将臣", "「是吗，我看盒子背面也写着外语」", null, "旅館_旅館前b", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-2", null, null], [3149, "将臣", "「可是，你白天打电话时好像说过，这是你家里人给你寄来的东西吧？」", null, "旅館_旅館前b", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-2", null, null], [3150, "将臣", "「我真的可以收下吗？」", null, "旅館_旅館前b", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-2", null, null], [3151, "蕾娜", "「这是感谢你教我有关日本的知识啦」", "len418_115.ogg", "旅館_旅館前b", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-2", null, null], [3152, "将臣", "「哈哈，那不算什么啦，我感觉自己都没怎么帮上忙」", null, "旅館_旅館前b", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-2", null, null], [3153, "蕾娜", "「你教了我很多东西呀，而且…………」", "len418_116.ogg", "旅館_旅館前b", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-2", null, null], [3154, "将臣", "「嗯？」", null, "旅館_旅館前b", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-2", null, null], [3155, "蕾娜", "「……我也希望你能更多地了解一下我们国家」", "len418_117.ogg", "旅館_旅館前b", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 5-2", null, null], [3156, "将臣", "「啊、啊……是吗」", null, "旅館_旅館前b", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 5-2", null, null], [3157, "", "我也很想了解蕾娜的国家。", null, "旅館_旅館前b", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 5-2", null, null], [3158, "", "我发自内心这么想。", null, "旅館_旅館前b", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 5-2", null, null], [3159, "", "既然她说这是谢礼，那我还是收下比较好。回去了之后跟大家分着吃吧。", null, "旅館_旅館前b", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 5-2", null, null], [3160, "将臣", "「好吧，那我就不客气了」", null, "旅館_旅館前b", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 5-2", null, null], [3161, "蕾娜", "「嗯，拿着吧！」", "len418_118.ogg", "旅館_旅館前b", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 5-2", null, null], [3162, "蕾娜", "「我那边还有挺多的，一个人根本吃不完呢」", "len418_119.ogg", "旅館_旅館前b", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "23"}, "CHAPTER 5-2", null, null], [3163, "将臣", "「哈哈，谢谢你送我这么珍贵的零食。那我先走了」", null, "旅館_旅館前b", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "23"}, "CHAPTER 5-2", null, null], [3164, "蕾娜", "「明天见，将臣！」", "len418_120.ogg", "旅館_旅館前b", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "24"}, "CHAPTER 5-2", null, null], [3165, "将臣", "「真是一眨眼的工夫，天就黑起来了」", null, "街_小道c", "bgm35.opus", null, "CHAPTER 5-2", null, null], [3166, "", "我一边快步走向神社，一边烦恼着那个没有答案的问题。", null, "街_小道c", "bgm35.opus", null, "CHAPTER 5-2", null, null], [3167, "", "走着走着，突然看见一个小小的身影飘了过来。", null, "街_小道c", "bgm35.opus", null, "CHAPTER 5-2", null, null], [3168, "丛雨", "「主人，本座就知道你差不多该回来了。你跟驹川已经聊过了吧」", "mur418_029.ogg", "街_小道c", "bgm35.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-2", null, null], [3169, "将臣", "「……小雨」", null, "街_小道c", "bgm35.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-2", null, null], [3170, "", "她可能来的正是时候。", null, "街_小道c", "bgm35.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-2", null, null], [3171, "将臣", "「你今天早上说，可能需要考虑让蕾娜回国，这话你是认真的吗？」", null, "街_小道c", "bgm35.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-2", null, null], [3172, "丛雨", "「不好说，这要看她本人的意思了」", "mur418_030.ogg", "街_小道c", "bgm35.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "40"}, "CHAPTER 5-2", null, null], [3173, "丛雨", "「难道，驹川跟你们说些什么了吗？」", "mur418_031.ogg", "街_小道c", "bgm35.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "26"}, "CHAPTER 5-2", null, null], [3174, "将臣", "「那倒不是……」", null, "街_小道c", "bgm35.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "26"}, "CHAPTER 5-2", null, null], [3175, "", "很显然，小雨也想获取更多关于诅咒的信息。", null, "街_小道c", "bgm35.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "26"}, "CHAPTER 5-2", null, null], [3176, "", "但若是蕾娜离开了，我们就无法再从梦中获取信息了。", null, "街_小道c", "bgm35.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "26"}, "CHAPTER 5-2", null, null], [3177, "", "这么一想，我突然搞不明白小雨为什么会那么说了。", null, "街_小道c", "bgm35.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "26"}, "CHAPTER 5-2", null, null], [3178, "", "可这种事感觉也没必要特意去问她。", null, "街_小道c", "bgm35.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "26"}, "CHAPTER 5-2", null, null], [3179, "", "然而，她只是看了看我，似乎就已经明白我在想什么了。", null, "街_小道c", "bgm35.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "26"}, "CHAPTER 5-2", null, null], [3180, "丛雨", "「主人啊，如果我们只考虑蕾娜的安全」", "mur418_032.ogg", "街_小道c", "bgm35.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "10"}, "CHAPTER 5-2", null, null], [3181, "丛雨", "「那么最妥当的做法，肯定是先想办法把她体内的碎片取出来，然后让她离开穗织」", "mur418_033.ogg", "街_小道c", "bgm35.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "40"}, "CHAPTER 5-2", null, null], [3182, "丛雨", "「这点事，本座也是明白的」", "mur418_034.ogg", "街_小道c", "bgm35.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "35"}, "CHAPTER 5-2", null, null], [3183, "将臣", "「小雨，你真的不会读心术吗？」", null, "街_小道c", "bgm35.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "35"}, "CHAPTER 5-2", null, null], [3184, "丛雨", "「是你的想法太容易看穿了」", "mur418_035.ogg", "街_小道c", "bgm35.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "31"}, "CHAPTER 5-2", null, null], [3185, "丛雨", "「但是啊，主人，我们现在并不敢保证，是不是真的能把碎片从她体内取出来」", "mur418_036.ogg", "街_小道c", "bgm35.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "13"}, "CHAPTER 5-2", null, null], [3186, "将臣", "「这个我明白」", null, "街_小道c", "bgm35.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "13"}, "CHAPTER 5-2", null, null], [3187, "丛雨", "「最重要的是，对于本座来说，很难做到只考虑蕾娜的安全」", "mur418_037.ogg", "街_小道c", "bgm35.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "30"}, "CHAPTER 5-2", null, null], [3188, "丛雨", "「本座总是忍不住会想，你和蕾娜梦里见到的事情，很可能就是解开诅咒的契机」", "mur418_038.ogg", "街_小道c", "bgm35.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "36"}, "CHAPTER 5-2", null, null], [3189, "", "果然，小雨也跟驹川大夫一样啊。", null, "街_小道c", "bgm35.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "36"}, "CHAPTER 5-2", null, null], [3190, "丛雨", "「但是啊，这样下去又可能会给蕾娜带来危险」", "mur418_039.ogg", "街_小道c", "bgm35.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "26"}, "CHAPTER 5-2", null, null], [3191, "丛雨", "「本座一想到这里，心里就很不是滋味。就又会想，是不是把蕾娜的安全放在第一位比较好」", "mur418_040.ogg", "街_小道c", "bgm35.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "10"}, "CHAPTER 5-2", null, null], [3192, "将臣", "「嗯……」", null, "街_小道c", "bgm35.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "10"}, "CHAPTER 5-2", null, null], [3193, "丛雨", "「本座之所以会说可能要让蕾娜回国，也是因为本座心里面很纠结」", "mur418_041.ogg", "街_小道c", "bgm35.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "35"}, "CHAPTER 5-2", null, null], [3194, "丛雨", "「说到底，究竟什么才是正确的，不实际尝试一番是不会知道的」", "mur418_042.ogg", "街_小道c", "bgm35.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "36"}, "CHAPTER 5-2", null, null], [3195, "将臣", "「说的也是，这种事情恐怕不会像数学题那样有个明确的解答」", null, "街_小道c", "bgm35.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "36"}, "CHAPTER 5-2", null, null], [3196, "将臣", "「而且……唉，算了」", null, "街_小道c", "bgm35.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "36"}, "CHAPTER 5-2", null, null], [3197, "丛雨", "「怎么了？还有什么事情让主人在意吗？」", "mur418_043.ogg", "街_小道c", "bgm35.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "24"}, "CHAPTER 5-2", null, null], [3198, "将臣", "「这个，怎么说呢」", null, "街_小道c", "bgm35.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "24"}, "CHAPTER 5-2", null, null], [3199, "丛雨", "「为何不说出来听听？」", "mur418_044.ogg", "街_小道c", "bgm35.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "23"}, "CHAPTER 5-2", null, null], [3200, "丛雨", "「本座并不能看透主人的内心」", "mur418_045.ogg", "街_小道c", "bgm35.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "31"}, "CHAPTER 5-2", null, null], [3201, "将臣", "「哈哈，说的也是」", null, "街_小道c", "bgm35.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "31"}, "CHAPTER 5-2", null, null], [3202, "将臣", "「我之所以会在睡着的时候跑去蕾娜的房间，都是因为碎片在相互吸引吧？」", null, "街_小道c", "bgm35.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "31"}, "CHAPTER 5-2", null, null], [3203, "将臣", "「如果是那样的话，我可能也是受到碎片的影响了」", null, "街_小道c", "bgm35.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "03"}, "CHAPTER 5-2", null, null], [3204, "丛雨", "「这不是很重要的事吗？」", "mur418_046.ogg", "街_小道c", "bgm35.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "10"}, "CHAPTER 5-2", null, null], [3205, "将臣", "「嗯，怎么说呢……我一想到蕾娜可能会回国，心里就很难受」", null, "街_小道c", "bgm35.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "10"}, "CHAPTER 5-2", null, null], [3206, "", "小雨并没有立刻回答我。", null, "街_小道c", "bgm35.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "24"}, "CHAPTER 5-2", null, null], [3207, "", "但她似乎并没有笑话我的意思，也没有露出什么吃惊的表情。", null, "街_小道c", "bgm35.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "24"}, "CHAPTER 5-2", null, null], [3208, "丛雨", "「主人……你现在，只是在对自己的感情视而不见而已」", "mur418_047.ogg", "街_小道c", "bgm35.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "10"}, "CHAPTER 5-2", null, null], [3209, "丛雨", "「跟碎片没有关系」", "mur418_048.ogg", "街_小道c", "bgm35.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "23"}, "CHAPTER 5-2", null, null], [3210, "将臣", "「……真的，是这样吗？」", null, "街_小道c", "bgm35.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "23"}, "CHAPTER 5-2", null, null], [3211, "", "如果真是如此，那我实在是个任性又过分的男人。", null, "街_小道c", "bgm35.opus", null, "CHAPTER 5-2", null, null], [3212, "", "既不是为了安全地帮她取出碎片，也不是为了解开诅咒，只是单纯想让她陪在我身边而已。", null, "街_小道c", "bgm35.opus", null, "CHAPTER 5-2", null, null], [3213, "", "如果我承认了这份感情，会怎样呢？", null, "街_小道c", "bgm35.opus", null, "CHAPTER 5-2", null, null], [3214, "", "这可能会影响到一些重要的决策，一想到这里，我就有些害怕。", null, "街_小道c", "bgm35.opus", null, "CHAPTER 5-2", null, null], [3215, "丛雨", "「主人，愿意思考是一件好事，但如果因为想太多而畏首畏尾，那可就本末倒置了」", "mur418_049.ogg", "街_小道c", "bgm35.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-2", null, null], [3216, "将臣", "「嗯，这个我明白」", null, "街_小道c", "bgm35.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-2", null, null], [3217, "", "算了，不想了不想了。反正想再多也没有结论。", null, "街_小道c", "bgm35.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-2", null, null], [3218, "", "为了不让自己想太多，我随手拿出了两三颗蕾娜送的糖放进了嘴里。", null, "街_小道c", "bgm35.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-2", null, null], [3219, "将臣", "「……嗯？」", null, "街_小道c", "bgm35.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-2", null, null], [3220, "丛雨", "「怎么了，主人？你的表情好奇怪」", "mur418_050.ogg", "街_小道c", "bgm35.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "24"}, "CHAPTER 5-2", null, null], [3221, "将臣", "「没什么，就是感觉这糖的味道跟想象中不太一样……呃、唔！？」", null, "街_小道c", "bgm35.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "24"}, "CHAPTER 5-2", null, null], [3222, "", "突然，一股猛烈的不适感向我的胃袭来，临死前的恐惧瞬间涌上心头。", null, "街_小道c", "bgm22.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "24"}, "CHAPTER 5-2", null, null], [3223, "", "紧接着，我的膝盖开始震颤。", null, "街_小道c", "bgm22.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "24"}, "CHAPTER 5-2", null, null], [3224, "", "哎，不是吧？我只是吃了点糖而已啊，\\n竟然站不住了！？", null, "街_小道c", "bgm22.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "24"}, "CHAPTER 5-2", null, null], [3225, "将臣", "「这、这是什么啊……唔呕呕呕呕呕呕呕！！？」", null, "空_夜空", "bgm22.opus", null, "CHAPTER 5-2", null, null], [3226, "", "我一边惨叫，一边倒在了地上。", null, "空_夜空", "bgm22.opus", null, "CHAPTER 5-2", null, null], [3227, "芳乃", "「啊啊，好厉害！出现了极光，我看到极光了！」", "yos419_001.ogg", "朝武_リビングa", "bgm23.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "15"}, "CHAPTER 5-3", null, null], [3228, "芳乃", "「一股极光的味道在嘴里蔓延……咦？怎么感觉天空离自己越来越近……？」", "yos419_002.ogg", "朝武_リビングa", "bgm23.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "14"}, "CHAPTER 5-3", null, null], [3229, "茉子", "「芳乃大人！芳乃大人您没事吧！？」", "mak419_001.ogg", "朝武_リビングa", "bgm23.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "31"}, "CHAPTER 5-3", null, null], [3230, "芳乃", "「好……好厉害……好漂亮，咕嘟咕嘟……」", "yos419_003.ogg", "朝武_リビングa", "bgm23.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "15"}, "CHAPTER 5-3", null, null], [3231, "茉子", "「这都是幻觉啊！您振作一点」", "mak419_002.ogg", "朝武_リビングa", "bgm23.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "22"}, "CHAPTER 5-3", null, null], [3232, "", "朝武两眼放光，不停地嘀咕着什么好厉害好厉害。", null, "朝武_リビングa", "bgm23.opus", null, "CHAPTER 5-3", null, null], [3233, "", "常陆为了让她清醒过来，正拼命地来回拍打她的脸颊。", null, "朝武_リビングa", "bgm23.opus", null, "CHAPTER 5-3", null, null], [3234, "", "我把昨晚吃了那糖果的感受跟大家说了之后——", null, "朝武_リビングa", "bgm23.opus", null, "CHAPTER 5-3", null, null], [3235, "芳乃", "『有地，那可是人家特意送给你的东西，你这样说也太没礼貌了吧！』", "yos419_004.ogg", "朝武_リビングa", "bgm23.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "33"}, "CHAPTER 5-3", null, null], [3236, "茉子", "『哈哈，你说得未免太夸张了吧』", "mak419_003.ogg", "朝武_リビングa", "bgm23.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "46"}, "CHAPTER 5-3", null, null], [3237, "芳乃", "『再说了，蕾娜怎么可能把那种奇怪的东西送给你吃呢，根本难以置信』", "yos419_005.ogg", "朝武_リビングa", "bgm23.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "33"}, "CHAPTER 5-3", null, null], [3238, "", "说来说去，她们就是不相信我说的。", null, "朝武_リビングa", "bgm23.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "33"}, "CHAPTER 5-3", null, null], [3239, "", "无奈之下，我只好让朝武也试着吃了一颗……于是就引发了刚才的惨案。", null, "朝武_リビングa", "bgm23.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "33"}, "CHAPTER 5-3", null, null], [3240, "芳乃", "「咦……咦，极光呢？奇怪了，爷爷和奶奶都去哪儿了？」", "yos419_006.ogg", "朝武_リビングa", "bgm23.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "47"}, "CHAPTER 5-3", null, null], [3241, "茉子", "「您、您不是在开玩笑吧？」", "mak419_004.ogg", "朝武_リビングa", "bgm23.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "13"}, "CHAPTER 5-3", null, null], [3242, "丛雨", "「这哪是普通的极光，简直就是黄泉路上的极光啊」", "mur419_001.ogg", "朝武_リビングa", "bgm23.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "13"}, "CHAPTER 5-3", null, null], [3243, "", "区区糖果，竟然能让人一只脚踏入黄泉，这东西真的是给人吃的吗？", null, "朝武_リビングa", "bgm23.opus", null, "CHAPTER 5-3", null, null], [3244, "将臣", "「所以，我可以听听你们的意见吗？」", null, "朝武_リビングa", "bgm23.opus", null, "CHAPTER 5-3", null, null], [3245, "将臣", "「蕾娜说是为了报答我，才送了我这盒糖果，你们觉得她到底是什么意思？」", null, "朝武_リビングa", "bgm23.opus", null, "CHAPTER 5-3", null, null], [3246, "芳乃", "「……糖果？这竟然是糖果啊？」", "yos419_007.ogg", "朝武_リビングa", "bgm23.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "08"}, "CHAPTER 5-3", null, null], [3247, "将臣", "「应该是吧？怎么说呢，我们为了教她常识，天天逼她参加奇怪的研讨会，我还时不时就跑到她房间去」", null, "朝武_リビングa", "bgm23.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "08"}, "CHAPTER 5-3", null, null], [3248, "将臣", "「她不会不会心里很反感这些，所以才送了这个表示抗议啊？」", null, "朝武_リビングa", "bgm23.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "08"}, "CHAPTER 5-3", null, null], [3249, "丛雨", "「本座不觉得蕾娜是那样的人」", "mur419_002.ogg", "朝武_リビングa", "bgm23.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "36"}, "CHAPTER 5-3", null, null], [3250, "茉子", "「你先等等，我记得我好像听说过……」", "mak419_005.ogg", "朝武_リビングa", "bgm23.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "32"}, "CHAPTER 5-3", null, null], [3251, "", "常陆拿出手机，打开了搜索引擎。", null, "朝武_リビングa", "bgm23.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "32"}, "CHAPTER 5-3", null, null], [3252, "", "手机真是文明的利器啊。", null, "朝武_リビングa", "bgm23.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "32"}, "CHAPTER 5-3", null, null], [3253, "茉子", "「查到了……蕾娜送的也是这种盒子吧？」", "mak419_006.ogg", "朝武_リビングa", "bgm23.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "10"}, "CHAPTER 5-3", null, null], [3254, "将臣", "「唔，全世界最难吃的糖，Ｓａｌｍｉａｋｋｉ？」", null, "朝武_リビングa", "bgm23.opus", null, "CHAPTER 5-3", null, null], [3255, "芳乃", "「全世界……？确实，这标题没有骗人，呕……」", "yos419_008.ogg", "朝武_リビングa", "bgm23.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "31"}, "CHAPTER 5-3", null, null], [3256, "", "朝武似乎依然很难受。", null, "朝武_リビングa", "bgm23.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "31"}, "CHAPTER 5-3", null, null], [3257, "将臣", "「难道真的是想故意报复我们吗？」", null, "朝武_リビングa", "bgm23.opus", null, "CHAPTER 5-3", null, null], [3258, "茉子", "「不，她们国家还出了世界最难吃的软糖，以及世界最臭的罐头之类的」", "mak419_007.ogg", "朝武_リビングa", "bgm23.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "13"}, "CHAPTER 5-3", null, null], [3259, "茉子", "「负面的世界第一，好像都被她们国家包揽了」", "mak419_008.ogg", "朝武_リビングa", "bgm23.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "34"}, "CHAPTER 5-3", null, null], [3260, "芳乃", "「不……不是吧，在她们国家，大家都吃这种吗？」", "yos419_009.ogg", "朝武_リビングa", "bgm23.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "06"}, "CHAPTER 5-3", null, null], [3261, "将臣", "「……也就是说她并没有恶意，只是不觉得这个难吃而已吗！？」", null, "朝武_リビングa", "bgm23.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "06"}, "CHAPTER 5-3", null, null], [3262, "茉子", "「这网站上写着，她们当地的小孩都会把这当零食吃，应该是没错了」", "mak419_009.ogg", "朝武_リビングa", "bgm23.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "13"}, "CHAPTER 5-3", null, null], [3263, "", "面对如此事实，我震惊了。", null, "朝武_リビングa", "bgm23.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "13"}, "CHAPTER 5-3", null, null], [3264, "芳乃", "「这、这绝对不是真的！要是让小孩吃这种东西，他们肯定会哭出来的！」", "yos419_010.ogg", "朝武_リビングa", "bgm23.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "10"}, "CHAPTER 5-3", null, null], [3265, "丛雨", "「唔，被你们说成这样，说得本座也有点想吃了」", "mur419_003.ogg", "朝武_リビングa", "bgm23.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "10"}, "CHAPTER 5-3", null, null], [3266, "将臣", "「……你别想不开啊，小雨」", null, "朝武_リビングa", "bgm23.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "10"}, "CHAPTER 5-3", null, null], [3267, "茉子", "「哈哈，都已经有两个人壮烈牺牲了，您还不知畏惧，真不愧是丛雨大人」", "mak419_010.ogg", "朝武_リビングa", "bgm23.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "46"}, "CHAPTER 5-3", null, null], [3268, "芳乃", "「…………」", "yos419_011.ogg", "朝武_リビングa", "bgm23.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "28"}, "CHAPTER 5-3", null, null], [3269, "将臣", "「……」", null, "朝武_リビングa", "bgm23.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "28"}, "CHAPTER 5-3", null, null], [3270, "茉子", "「嗯？你们这是怎么了？」", "mak419_011.ogg", "朝武_リビングa", "bgm23.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "26"}, "CHAPTER 5-3", null, null], [3271, "芳乃", "「茉子，你明明没吃过，刚才却笑有地说得太夸张了，我没记错吧？」", "yos419_012.ogg", "朝武_リビングa", "bgm23.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "24"}, "CHAPTER 5-3", null, null], [3272, "将臣", "「人家难得送咱们一盒，只有你不吃，是不是有点不太好啊」", null, "朝武_リビングa", "bgm23.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "24"}, "CHAPTER 5-3", null, null], [3273, "茉子", "「你、你们在说什么呢？我并不……喂，等等，您干什么啊芳乃大人！？」", "mak419_012.ogg", "朝武_リビングa", "bgm23.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "33"}, "CHAPTER 5-3", null, null], [3274, "", "哇哦，朝武从身后对常陆来了个倒剪双臂。", null, "朝武_リビングa", "bgm23.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "33"}, "CHAPTER 5-3", null, null], [3275, "芳乃", "「你休想逃！偶尔也要让你体验一下羞耻失败的滋味才行」", "yos419_013.ogg", "朝武_リビングa", "bgm23.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "33"}, "CHAPTER 5-3", null, null], [3276, "茉子", "「等、等等、您说的这些跟吃糖有什么关系啊？」", "mak419_013.ogg", "朝武_リビングa", "bgm23.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "13"}, "CHAPTER 5-3", null, null], [3277, "丛雨", "「好羡慕你啊，茉子……好羡慕你啊」", "mur419_004.ogg", "朝武_リビングa", "bgm23.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "09"}, "CHAPTER 5-3", null, null], [3278, "茉子", "「丛雨大人，您不要说笑了」", "mak419_014.ogg", "朝武_リビングa", "bgm23.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "21"}, "CHAPTER 5-3", null, null], [3279, "芳乃", "「你刚才不是还夸奖了丛雨大人的勇气吗？有地，趁现在！」", "yos419_014.ogg", "朝武_リビングa", "bgm23.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "14"}, "CHAPTER 5-3", null, null], [3280, "将臣", "「……得令」", null, "朝武_リビングa", "bgm23.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "14"}, "CHAPTER 5-3", null, null], [3281, "", "我抓起一颗糖，一步一步向常陆走去。", null, "朝武_リビングa", "bgm23.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "35"}, "CHAPTER 5-3", null, null], [3282, "", "此时，她才终于慌了神，平时那副从容的模样已是不见踪影。", null, "朝武_リビングa", "bgm23.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "35"}, "CHAPTER 5-3", null, null], [3283, "茉子", "「你、你你你你冷静点啊，有地」", "mak419_015.ogg", "朝武_リビングa", "bgm23.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "24"}, "CHAPTER 5-3", null, null], [3284, "茉子", "「其实今天我忘了准备替身之术……」", "mak419_016.ogg", "朝武_リビングa", "bgm23.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "24"}, "CHAPTER 5-3", null, null], [3285, "将臣", "「是吗」", null, "朝武_リビングa", "bgm23.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "35"}, "CHAPTER 5-3", null, null], [3286, "茉子", "「而、而且我相信，有地你不是会做这种事的人……我相信你嗯唔唔！？」", "mak419_017.ogg", "朝武_リビングa", "bgm23.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "33"}, "CHAPTER 5-3", null, null], [3287, "", "还没等她说完，我就把糖塞进了她嘴里。", null, "朝武_リビングa", "bgm23.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "35"}, "CHAPTER 5-3", null, null], [3288, "", "因为常陆看上去是真的很慌，让人忍不住想要欺负她一下。", null, "朝武_リビングa", "bgm23.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "35"}, "CHAPTER 5-3", null, null], [3289, "丛雨", "「怎么样，茉子？味道如何，说来听听？」", "mur419_005.ogg", "朝武_リビングa", "bgm23.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "33"}, "CHAPTER 5-3", null, null], [3290, "茉子", "「…………」", "mak419_018.ogg", "朝武_リビングa", "bgm23.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "33"}, "CHAPTER 5-3", null, null], [3291, "丛雨", "「怎么了？怎么一句话也不说，你倒是说句话啊！」", "mur419_006.ogg", "朝武_リビングa", "bgm23.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "33"}, "CHAPTER 5-3", null, null], [3292, "芳乃", "「这样一来，茉子也能理解我和有地的痛苦……茉子？」", "yos419_015.ogg", "朝武_リビングa", "bgm23.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "05"}, "CHAPTER 5-3", null, null], [3293, "茉子", "「…………」", "mak419_019.ogg", "朝武_リビングa", "bgm23.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "10"}, "CHAPTER 5-3", null, null], [3294, "茉子", "「……………………」", "mak419_020.ogg", "朝武_リビングa", "bgm23.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "10"}, "CHAPTER 5-3", null, null], [3295, "茉子", "「…………」", "mak419_021.ogg", "朝武_リビングa", "bgm23.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "10"}, "CHAPTER 5-3", null, null], [3296, "将臣", "「咦……咦？常陆？你怎么一点反应都没有？」", null, "朝武_リビングa", "bgm23.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "10"}, "CHAPTER 5-3", null, null], [3297, "茉子", "「…………………………………………」", "mak419_022.ogg", "朝武_リビングa", "bgm23.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "10"}, "CHAPTER 5-3", null, null], [3298, "", "常陆一动不动，仿佛就像时间被静止了一样。", null, "朝武_リビングa", "bgm23.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "10"}, "CHAPTER 5-3", null, null], [3299, "", "难道是升天了！？", null, "朝武_リビングa", "bgm23.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "10"}, "CHAPTER 5-3", null, null], [3300, "", "正当我冒出这个想法时，常陆就像力气被抽干了一样，默默地坐倒在原地。", null, "朝武_リビングa", "bgm23.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "10"}, "CHAPTER 5-3", null, null], [3301, "茉子", "「………………………………………………………唔啊」", "mak419_023.ogg", "朝武_リビングa", "bgm23.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "09"}, "CHAPTER 5-3", null, null], [3302, "芳乃", "「你没事吧，茉子！？对不起，都难吃到让你动都动不了了吗？」", "yos419_016.ogg", "朝武_リビングa", "bgm23.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "07"}, "CHAPTER 5-3", null, null], [3303, "将臣", "「抱歉，不该乱开这种玩笑，给，快来喝点水吧」", null, "朝武_リビングa", "bgm23.opus", null, "CHAPTER 5-3", null, null], [3304, "茉子", "「……唔……唔，抱歉，眼泪……」", "mak419_024.ogg", "朝武_リビングa", "bgm23.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "09n"}, "CHAPTER 5-3", null, null], [3305, "芳乃", "「你别哭，没事的！你还活着，你还活着呢」", "yos419_017.ogg", "朝武_リビングa", "bgm23.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "11"}, "CHAPTER 5-3", null, null], [3306, "", "没想到连平时处事不惊的常陆都如此狼狈。", null, "朝武_リビングa", "bgm23.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "11"}, "CHAPTER 5-3", null, null], [3307, "茉子", "「刚才，丛雨大人还问我……是什么味道，是吧？」", "mak419_025.ogg", "朝武_リビングa", "bgm23.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "13n"}, "CHAPTER 5-3", null, null], [3308, "丛雨", "「喔、喔……」", "mur419_007.ogg", "朝武_リビングa", "bgm23.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "13n"}, "CHAPTER 5-3", null, null], [3309, "茉子", "「入口的那一瞬间，并没有什么甜味，反而觉得非常咸」", "mak419_026.ogg", "朝武_リビングa", "bgm23.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "08"}, "CHAPTER 5-3", null, null], [3310, "茉子", "「但是，那个味道在口中扩散开之后，突然就会冒出一股薄荷一样的清凉感」", "mak419_027.ogg", "朝武_リビングa", "bgm23.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "09"}, "CHAPTER 5-3", null, null], [3311, "茉子", "「与此同时，还会有一股腐烂的鱼内脏一般的臭味拂过鼻腔」", "mak419_028.ogg", "朝武_リビングa", "bgm23.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "41"}, "CHAPTER 5-3", null, null], [3312, "芳乃", "「你描述得这么准确……让我又想起那个味道了，呜呜」", "yos419_018.ogg", "朝武_リビングa", "bgm23.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "31"}, "CHAPTER 5-3", null, null], [3313, "将臣", "「常、常陆，你别说了！是我们错了，你别再说了！」", null, "朝武_リビングa", "bgm23.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "31"}, "CHAPTER 5-3", null, null], [3314, "茉子", "「啊……啊……最恐怖的还是这股余味……那股腐烂的味道始终萦绕在舌尖，仿佛自己的舌头也腐烂掉了一样」", "mak419_029.ogg", "朝武_リビングa", "bgm23.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "09"}, "CHAPTER 5-3", null, null], [3315, "茉子", "「我现在浑身都能感受到这股恶心的味道……呵、呵呵」", "mak419_030.ogg", "朝武_リビングa", "bgm23.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "27d"}, "CHAPTER 5-3", null, null], [3316, "茉子", "「这种传遍浑身上下的感觉，没有实际吃过的人是绝对无法……」", "mak419_031.ogg", "朝武_リビングa", "bgm23.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "13d"}, "CHAPTER 5-3", null, null], [3317, "将臣", "「够了！不要再说了，常陆」", null, "朝武_リビングa", "bgm23.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "13d"}, "CHAPTER 5-3", null, null], [3318, "丛雨", "「抱……抱歉，本座不该觉得好玩就捉弄你」", "mur419_008.ogg", "朝武_リビングa", "bgm23.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "32"}, "CHAPTER 5-3", null, null], [3319, "", "随后，常陆依然没能恢复过来，还是一副被打垮了的样子。", null, "朝武_リビングa", "bgm23.opus", null, "CHAPTER 5-3", null, null], [3320, "", "现在，她就这么瘫坐在椅子上，用湿毛巾盖着眼睛。", null, "朝武_リビングa", "bgm23.opus", null, "CHAPTER 5-3", null, null], [3321, "将臣", "「至今为止，我们也教了蕾娜不少日本的知识了，可是她们国家的事，我们好像还一无所知吧？」", null, "朝武_リビングa", "bgm23.opus", null, "CHAPTER 5-3", null, null], [3322, "芳乃", "「嗯……难以想象她在老家到底是吃什么长大的……」", "yos419_019.ogg", "朝武_リビングa", "bgm23.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "09"}, "CHAPTER 5-3", null, null], [3323, "芳乃", "「她在日本的这段时间，我们是不是应该尽量让她多吃点好的呢？」", "yos419_020.ogg", "朝武_リビングa", "bgm23.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "30"}, "CHAPTER 5-3", null, null], [3324, "", "这句话让有些人听了可能会觉得不太礼貌。", null, "朝武_リビングa", "bgm23.opus", null, "CHAPTER 5-3", null, null], [3325, "", "但朝武应该是真的很担心她。毕竟，那个糖的味道实在是太糟糕了……简直就是灾难级的。", null, "朝武_リビングa", "bgm23.opus", null, "CHAPTER 5-3", null, null], [3326, "", "就算它被定义为鬼级灾害，我大概也不会吃惊。", null, "朝武_リビングa", "bgm23.opus", null, "CHAPTER 5-3", null, null], [3327, "丛雨", "「唔，毕竟人的味觉喜好各有不同」", "mur419_009.ogg", "朝武_リビングa", "bgm23.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "18"}, "CHAPTER 5-3", null, null], [3328, "芳乃", "「这已经远超喜好的范畴了！」", "yos419_021.ogg", "朝武_リビングa", "bgm23.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "27"}, "CHAPTER 5-3", null, null], [3329, "丛雨", "「可……可是，这种事若不问她本人，我们也不好随便判断吧？」", "mur419_010.ogg", "朝武_リビングa", "bgm23.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "27"}, "CHAPTER 5-3", null, null], [3330, "将臣", "「确实」", null, "朝武_リビングa", "bgm23.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "27"}, "CHAPTER 5-3", null, null], [3331, "将臣", "「那好，今天我们就让蕾娜给我们讲讲她们国家的事吧」", null, "朝武_リビングa", "bgm23.opus", null, "CHAPTER 5-3", null, null], [3332, "安晴", "「各位早上好……哎？我听见你们在说话，还以为早饭已经做好了」", "yas419_001.ogg", "朝武_リビングa", "bgm23.opus", {"char": "安晴", "file": "安晴.stand", "dress": "私服", "face": "09"}, "CHAPTER 5-3", null, null], [3333, "芳乃", "「爸爸！抱歉，早饭……啊」", "yos419_022.ogg", "朝武_リビングa", "bgm23.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "06"}, "CHAPTER 5-3", null, null], [3334, "", "负责做饭的常陆依然是一副瘫软的样子。", null, "朝武_リビングa", "bgm23.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "06"}, "CHAPTER 5-3", null, null], [3335, "茉子", "「没、没事的，我这就来做饭……唔」", "mak419_032.ogg", "朝武_リビングa", "bgm23.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "14d"}, "CHAPTER 5-3", null, null], [3336, "芳乃", "「行了，你就好好休息吧！呃，那就……」", "yos419_023.ogg", "朝武_リビングa", "bgm23.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "07"}, "CHAPTER 5-3", null, null], [3337, "将臣", "「那我来做吧！简单的早餐我还是会做的」", null, "朝武_リビングa", "bgm23.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "07"}, "CHAPTER 5-3", null, null], [3338, "芳乃", "「我……我也来帮忙」", "yos419_024.ogg", "朝武_リビングa", "bgm23.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "06"}, "CHAPTER 5-3", null, null], [3339, "安晴", "「出什么事了吗？虽然搞不清楚状况，但你们不用太急的」", "yas419_002.ogg", "朝武_リビングa", "bgm23.opus", {"char": "安晴", "file": "安晴.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-3", null, null], [3340, "安晴", "「我一边吃糖一边等你们」", "yas419_003.ogg", "朝武_リビングa", "bgm23.opus", {"char": "安晴", "file": "安晴.stand", "dress": "私服", "face": "13"}, "CHAPTER 5-3", null, null], [3341, "", "……糖？", null, "朝武_リビングa", "bgm23.opus", null, "CHAPTER 5-3", null, null], [3342, "安晴", "「嗯？这糖的味道不太对劲啊」", "yas419_004.ogg", "朝武_リビングa", "bgm23.opus", {"char": "安晴", "file": "安晴.stand", "dress": "私服", "face": "12"}, "CHAPTER 5-3", null, null], [3343, "芳乃", "「爸、爸爸！？不行啊，赶快吐出来！！」", "yos419_025.ogg", "朝武_リビングa", "bgm23.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "11"}, "CHAPTER 5-3", null, null], [3344, "安晴", "「哈哈，抱歉抱歉，早餐之前吃糖确实太不像话……咕唔！？」", "yas419_005.ogg", "朝武_リビングa", "bgm23.opus", {"char": "安晴", "file": "安晴.stand", "dress": "私服", "face": "05"}, "CHAPTER 5-3", null, null], [3345, "芳乃", "「爸爸————！！！？」", "yos419_026.ogg", "朝武_リビングa", "bgm23.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "27"}, "CHAPTER 5-3", null, null], [3346, "", "这糖最恐怖的地方就在于，那股可怕的味道要过一会儿才袭来。", null, "朝武_リビングa", "bgm23.opus", null, "CHAPTER 5-3", null, null], [3347, "", "糖里面包含的萃取物在口中溶化并扩散开之后，那股味道就会突然直击大脑。", null, "朝武_リビングa", "bgm23.opus", null, "CHAPTER 5-3", null, null], [3348, "", "就和延迟发作的毒药是一个道理。", null, "朝武_リビングa", "bgm23.opus", null, "CHAPTER 5-3", null, null], [3349, "将臣", "「这已经不是食物了，完全是凶器……」", null, "朝武_リビングa", "bgm23.opus", null, "CHAPTER 5-3", null, null], [3350, "蕾娜", "「哈哈哈哈、哈哈哈哈哈哈！茉子，芳乃，还有芳乃爸爸竟然都……哈哈哈哈哈哈！」", "len419_001.ogg", "学院_教室休憩a", "bgm22.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "28"}, "CHAPTER 5-3", null, null], [3351, "", "我们把今早发生的事跟蕾娜说了之后，她笑得一个劲敲桌子。", null, "学院_教室休憩a", "bgm22.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "28"}, "CHAPTER 5-3", null, null], [3352, "", "看她这反应，应该是没有恶意的。", null, "学院_教室休憩a", "bgm22.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "28"}, "CHAPTER 5-3", null, null], [3353, "芳乃", "「真是的……这可一点都不好笑」", "yos419_027.ogg", "学院_教室休憩a", "bgm22.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "12"}, "CHAPTER 5-3", null, null], [3354, "蕾娜", "「抱歉、抱歉，但是……哈哈哈哈哈！我真的没想到会把你们吃成那样」", "len419_002.ogg", "学院_教室休憩a", "bgm22.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "12"}, "CHAPTER 5-3", null, null], [3355, "将臣", "「那什么，我听说在你们国家这就是普通糖果，这是真的吗？」", null, "学院_教室休憩a", "bgm22.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "12"}, "CHAPTER 5-3", null, null], [3356, "蕾娜", "「怎么会呢，一点都不普通」", "len419_003.ogg", "学院_教室休憩a", "bgm22.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "21"}, "CHAPTER 5-3", null, null], [3357, "茉子", "「喔，并不普通吗？」", "mak419_033.ogg", "学院_教室休憩a", "bgm22.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "04"}, "CHAPTER 5-3", null, null], [3358, "蕾娜", "「算是味道有点奇怪的糖果吧」", "len419_004.ogg", "学院_教室休憩a", "bgm22.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "04"}, "CHAPTER 5-3", null, null], [3359, "芳乃", "「这竟然……只是有点奇怪？」", "yos419_028.ogg", "学院_教室休憩a", "bgm22.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "07"}, "CHAPTER 5-3", null, null], [3360, "蕾娜", "「我是送给将臣之后才意识到，那种味道可能对日本人来说非常难以接受」", "len419_005.ogg", "学院_教室休憩a", "bgm22.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "21"}, "CHAPTER 5-3", null, null], [3361, "将臣", "「哎，原来你意识到了啊！」", null, "学院_教室休憩a", "bgm22.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "21"}, "CHAPTER 5-3", null, null], [3362, "", "那你怎么不早点告诉我。", null, "学院_教室休憩a", "bgm22.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "21"}, "CHAPTER 5-3", null, null], [3363, "蕾娜", "「因为我一打开包裹就看到了那盒糖，所以就拿过来了」", "len419_006.ogg", "学院_教室休憩a", "bgm22.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 5-3", null, null], [3364, "蕾娜", "「我本来以为，如果你觉得难吃的话会立刻跟我说的」", "len419_007.ogg", "学院_教室休憩a", "bgm22.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-3", null, null], [3365, "茉子", "「确实，有地是第一个吃下去的人，如果你当时就好好确认一下，就不会导致今天的惨案了」", "mak419_034.ogg", "学院_教室休憩a", "bgm22.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "34"}, "CHAPTER 5-3", null, null], [3366, "将臣", "「呃……抱歉」", null, "学院_教室休憩a", "bgm22.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "34"}, "CHAPTER 5-3", null, null], [3367, "廉太郎", "「话说，这东西有那么难吃吗？」", "ren419_001.ogg", "学院_教室休憩a", "bgm22.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "13"}, "CHAPTER 5-3", null, null], [3368, "小春", "「唔……闻这气味就感觉很危险」", "koh419_001.ogg", "学院_教室休憩a", "bgm22.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "28"}, "CHAPTER 5-3", null, null], [3369, "", "我们把世界第一难吃的糖——Ｓａｌｍｉａｋｋｉ——带到学校来了。", null, "学院_教室休憩a", "bgm22.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "28"}, "CHAPTER 5-3", null, null], [3370, "", "毕竟今早安晴叔叔也中招了，我们觉得放在家里还是太危险。", null, "学院_教室休憩a", "bgm22.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "28"}, "CHAPTER 5-3", null, null], [3371, "小春", "「你们吃之前怎么不闻一闻呢」", "koh419_002.ogg", "学院_教室休憩a", "bgm22.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "08"}, "CHAPTER 5-3", null, null], [3372, "小春", "「怎么说呢，这东西……有一股难以用语言描述的异味」", "koh419_003.ogg", "学院_教室休憩a", "bgm22.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "18"}, "CHAPTER 5-3", null, null], [3373, "茉子", "「我听说，这里面添加的有工业合成的氯化铵」", "mak419_035.ogg", "学院_教室休憩a", "bgm22.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "08"}, "CHAPTER 5-3", null, null], [3374, "小春", "「为什么要添加啊！？」", "koh419_004.ogg", "学院_教室休憩a", "bgm22.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "19"}, "CHAPTER 5-3", null, null], [3375, "", "内脏腐烂的味道原来是因为这个！", null, "学院_教室休憩a", "bgm22.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "19"}, "CHAPTER 5-3", null, null], [3376, "芳乃", "「这种东西吃了真的没事吗？」", "yos419_029.ogg", "学院_教室休憩a", "bgm22.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "30"}, "CHAPTER 5-3", null, null], [3377, "蕾娜", "「我们国家很多人都吃过，我觉得应该没事的」", "len419_008.ogg", "学院_教室休憩a", "bgm22.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "30"}, "CHAPTER 5-3", null, null], [3378, "廉太郎", "「是吗，那我也吃一个试试吧」", "ren419_002.ogg", "学院_教室休憩a", "bgm22.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-3", null, null], [3379, "将臣", "「别开玩笑！你是想自杀吗！？」", null, "学院_教室休憩a", "bgm22.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-3", null, null], [3380, "茉子", "「吃之前建议你先写好遗书」", "mak419_036.ogg", "学院_教室休憩a", "bgm22.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "41"}, "CHAPTER 5-3", null, null], [3381, "廉太郎", "「哈哈，再怎么难吃也不可能出人命吧？」", "ren419_003.ogg", "学院_教室休憩a", "bgm22.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "28"}, "CHAPTER 5-3", null, null], [3382, "", "这家伙没听我们刚才说的话吗？", null, "学院_教室休憩a", "bgm22.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "41"}, "CHAPTER 5-3", null, null], [3383, "廉太郎", "「我反而很好奇这到底有多么难吃」", "ren419_004.ogg", "学院_教室休憩a", "bgm22.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "06"}, "CHAPTER 5-3", null, null], [3384, "芳乃", "「那个，真的建议你不要尝试」", "yos419_030.ogg", "学院_教室休憩a", "bgm22.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "27"}, "CHAPTER 5-3", null, null], [3385, "将臣", "「你这个玩笑一点都不好笑，结局太显而易见了！你会白白送命的！」", null, "学院_教室休憩a", "bgm22.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "28"}, "CHAPTER 5-3", null, null], [3386, "廉太郎", "「哈哈，我不听我不听。你们越是阻止我，我越是想试试啊」", "ren419_005.ogg", "学院_教室休憩a", "bgm22.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "28"}, "CHAPTER 5-3", null, null], [3387, "小春", "「廉哥死了就死了吧，我不拦你」", "koh419_005.ogg", "学院_教室休憩a", "bgm22.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-3", null, null], [3388, "廉太郎", "「就你话多！我来尝尝……嗯？？」", "ren419_006.ogg", "学院_教室休憩a", "bgm22.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "33"}, "CHAPTER 5-3", null, null], [3389, "廉太郎", "「就这啊，感觉根本没那么难吃啊？你们说得也太夸张了吧」", "ren419_007.ogg", "学院_教室休憩a", "bgm22.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "24"}, "CHAPTER 5-3", null, null], [3390, "", "我们就这么眼睁睁地看着廉太郎自取灭亡。", null, "学院_教室休憩a", "bgm22.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "24"}, "CHAPTER 5-3", null, null], [3391, "小春", "「是吗，真的不难吃？」", "koh419_006.ogg", "学院_教室休憩a", "bgm22.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "04"}, "CHAPTER 5-3", null, null], [3392, "廉太郎", "「是啊，虽然这糖咸得发苦，但完全是在容忍范围……啊？…………唔喔喔喔！！？」", "ren419_008.ogg", "学院_教室休憩a", "bgm22.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "09"}, "CHAPTER 5-3", null, null], [3393, "小春", "「廉哥！廉哥————！！？」", "koh419_007.ogg", "学院_教室休憩a", "bgm22.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "19"}, "CHAPTER 5-3", null, null], [3394, "", "廉太郎一下子从椅子上摔到了地上，但也就只有小春被吓得慌了神。", null, "学院_教室休憩a", "bgm22.opus", null, "CHAPTER 5-3", null, null], [3395, "", "因为我们都彻底习惯了。", null, "学院_教室休憩a", "bgm22.opus", null, "CHAPTER 5-3", null, null], [3396, "蕾娜", "「唔……看来这糖确实不太合日本人的口味」", "len419_009.ogg", "学院_教室休憩a", "bgm22.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "30"}, "CHAPTER 5-3", null, null], [3397, "小春", "「这何止是不合口味啊！」", "koh419_008.ogg", "学院_教室休憩a", "bgm22.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "19"}, "CHAPTER 5-3", null, null], [3398, "廉太郎", "「极、极光……好漂亮的极光，好厉害……咦？」", "ren419_009.ogg", "学院_教室休憩a", "bgm22.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "22"}, "CHAPTER 5-3", null, null], [3399, "廉太郎", "「奶奶……还有太爷爷……太奶奶，喂……你们等等我啊～」", "ren419_010.ogg", "学院_教室休憩a", "bgm22.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-3", null, null], [3400, "小春", "「廉哥，你清醒点啊！快醒醒！廉哥，廉哥要死了！！」", "koh419_009.ogg", "学院_教室休憩a", "bgm22.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "10"}, "CHAPTER 5-3", null, null], [3401, "", "尽管亲眼目睹了这美好的兄妹之情，但我一丁点也感动不起来。", null, "学院_教室休憩a", "bgm22.opus", null, "CHAPTER 5-3", null, null], [3402, "芳乃", "「不过，为什么会看见极光呢？」", "yos419_031.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "10"}, "CHAPTER 5-3", null, null], [3403, "将臣", "「我记得蕾娜的祖国是极光之国吧？」", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "20"}, "CHAPTER 5-3", null, null], [3404, "蕾娜", "「是的……只是，在我们国家有一种迷信，说是极光的另一端就是死者的世界」", "len419_010.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "08"}, "CHAPTER 5-3", null, null], [3405, "将臣", "「原来真的是黄泉路上的极光啊！？」", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "08"}, "CHAPTER 5-3", null, null], [3406, "小春", "「这果然不是人吃的东西啊！」", "koh419_010.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "08"}, "CHAPTER 5-3", null, null], [3407, "蕾娜", "「那应该不至于吧……」", "len419_011.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "07"}, "CHAPTER 5-3", null, null], [3408, "芳乃", "「说到底，你们为什么要吃这种东西呢？」", "yos419_032.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "07"}, "CHAPTER 5-3", null, null], [3409, "蕾娜", "「这个我也不太清楚，我只知道我们国家以前的糖果一般都不是用糖，而是用甘草做的」", "len419_012.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-3", null, null], [3410, "蕾娜", "「所以虽然味道很特别，但以前的人们都是这么吃过来的」", "len419_013.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "21"}, "CHAPTER 5-3", null, null], [3411, "将臣", "「等等，甘草是什么？」", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "21"}, "CHAPTER 5-3", null, null], [3412, "蕾娜", "「就是一种有甜味的草。听说在亚洲很多国家，甘草被当做一种药来着？」", "len419_014.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-3", null, null], [3413, "茉子", "「你这么一说，确实感觉吃的时候有一股药味」", "mak419_037.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "20"}, "CHAPTER 5-3", null, null], [3414, "廉太郎", "「啊，是的……有点像是把正露丸和鱼的内脏混在一起磨碎之后的味道，再加上香草一样的清凉感」", "ren419_011.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "16"}, "CHAPTER 5-3", null, null], [3415, "", "廉太郎似乎终于复活了，他扒着椅子慢慢站了起来。", null, "学院_教室休憩a", "bgm04.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "16"}, "CHAPTER 5-3", null, null], [3416, "芳乃", "「原来是这么回事！也就是说，吃这东西对身体好啊」", "yos419_033.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-3", null, null], [3417, "小春", "「对哦，俗话说良药苦口利于病嘛」", "koh419_011.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "15"}, "CHAPTER 5-3", null, null], [3418, "茉子", "「如果是保健食品的话，那肯定越苦效果越好吧」", "mak419_038.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "22"}, "CHAPTER 5-3", null, null], [3419, "廉太郎", "「原来如此，那么难吃都是因为对身体好啊！也就是说我并没有白白受罪咯」", "ren419_012.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-3", null, null], [3420, "将臣", "「没错！肯定是这样，是不是啊蕾娜？」", null, "学院_教室休憩a", "bgm04.opus", null, "CHAPTER 5-3", null, null], [3421, "蕾娜", "「……………………唔」", "len419_015.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "18"}, "CHAPTER 5-3", null, null], [3422, "将臣", "「……蕾娜？」", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "18"}, "CHAPTER 5-3", null, null], [3423, "蕾娜", "「是的！你们说得没错」", "len419_016.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-3", null, null], [3424, "", "骗人！你刚才的表情分明就是在说“我怎么没听说过对身体好”。", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-3", null, null], [3425, "蕾娜", "「行、行啦，我家里给我寄了很多零食，今天我还带了一些别的过来！」", "len419_017.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 5-3", null, null], [3426, "芳乃・茉子", "「…………哎？」\\n「…………」", "yos419_034.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "31"}, "CHAPTER 5-3", null, null], [3427, "", "朝武突然脸色苍白，常陆开始小腿发抖。", null, "学院_教室休憩a", "bgm04.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "31"}, "CHAPTER 5-3", null, null], [3428, "蕾娜", "「别这样，没事的啦，生姜饼干很多外国人吃了都说好吃呢」", "len419_018.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "23"}, "CHAPTER 5-3", null, null], [3429, "小春", "「是、是吗，这里面放了生姜啊？那我吃一块试试吧」", "koh419_012.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-3", null, null], [3430, "廉太郎", "「你真有勇气啊」", "ren419_013.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "13"}, "CHAPTER 5-3", null, null], [3431, "小春", "「只是饼干而已嘛，趁她还没拿出更诡异的食物，我还是先赶快吃饱比较好」", "koh419_013.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "16"}, "CHAPTER 5-3", null, null], [3432, "廉太郎", "「老谋深算啊！你也太狡猾了吧，小春」", "ren419_014.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "10"}, "CHAPTER 5-3", null, null], [3433, "", "竟然还有这一手！", null, "学院_教室休憩a", "bgm04.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "10"}, "CHAPTER 5-3", null, null], [3434, "蕾娜", "「你们没必要这么害怕的，真的，这饼干还是挺好吃的……你们看」", "len419_019.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-3", null, null], [3435, "", "蕾娜说着，自己也吃了一块。", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-3", null, null], [3436, "", "但很显然，在场没有一个人相信她说的话。", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-3", null, null], [3437, "茉子", "「但愿你不要聪明反被聪明误啊」", "mak419_040.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "07"}, "CHAPTER 5-3", null, null], [3438, "小春", "「没……没事的，只是饼干而已，不会有事的」", "koh419_014.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "09"}, "CHAPTER 5-3", null, null], [3439, "", "小春一边说给自己听，一边咬了一口。", null, "学院_教室休憩a", "bgm04.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "15"}, "CHAPTER 5-3", null, null], [3440, "小春", "「啊！这个能吃，完全可以吃啊！」", "koh419_015.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "20"}, "CHAPTER 5-3", null, null], [3441, "小春", "「虽然有点干，吃多了可能会很渴，但吃下去完全没问题的！」", "koh419_016.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-3", null, null], [3442, "蕾娜", "「是的，这种饼干在我们国家一般是配着咖啡吃」", "len419_020.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-3", null, null], [3443, "小春", "「确实，跟咖啡应该很搭！」", "koh419_017.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-3", null, null], [3444, "将臣", "「看样子好像真的可以吃」", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-3", null, null], [3445, "", "但令人在意的是，小春一直在说能吃，却根本不说好不好吃。", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-3", null, null], [3446, "将臣", "「这个有点像蓝莓的是什么？看上去干干的，也不太像普通的果酱」", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-3", null, null], [3447, "蕾娜", "「这个是莓果酱」", "len419_021.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-3", null, null], [3448, "蕾娜", "「不过它不是零食，是用来浇在菜上的」", "len419_022.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-3", null, null], [3449, "廉太郎", "「好，那我先来一点！」", "ren419_015.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-3", null, null], [3450, "", "廉太郎把果酱瓶子抢了过去。", null, "学院_教室休憩a", "bgm04.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-3", null, null], [3451, "廉太郎", "「刚好今天是吃面包，面包配蓝莓的话总不会有问题吧？」", "ren419_016.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-3", null, null], [3452, "将臣", "「你下手太快了吧，廉太郎！」", null, "学院_教室休憩a", "bgm04.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-3", null, null], [3453, "廉太郎", "「谁让你们磨磨蹭蹭的啊，我尝尝看……嗯？」", "ren419_017.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "24"}, "CHAPTER 5-3", null, null], [3454, "廉太郎", "「嗯……」", "ren419_018.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "33"}, "CHAPTER 5-3", null, null], [3455, "蕾娜", "「哎？怎么了？」", "len419_023.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "30"}, "CHAPTER 5-3", null, null], [3456, "廉太郎", "「呃，倒也不是说难吃，就是跟我想象的味道不太一样」", "ren419_019.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "13"}, "CHAPTER 5-3", null, null], [3457, "将臣", "「什么意思？」", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "30"}, "CHAPTER 5-3", null, null], [3458, "廉太郎", "「本来以为是甜的，结果是咸的」", "ren419_020.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "38"}, "CHAPTER 5-3", null, null], [3459, "廉太郎", "「就好比，把鸡排配的番茄酱里面的番茄换成了蓝莓，这个味道你能想象吗？」", "ren419_021.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "37"}, "CHAPTER 5-3", null, null], [3460, "", "听上去……好像不那么好吃。", null, "学院_教室休憩a", "bgm04.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "37"}, "CHAPTER 5-3", null, null], [3461, "蕾娜", "「确实是咸的，这种莓果酱我们一般都拿来配肉类或者鱼类料理」", "len419_024.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-3", null, null], [3462, "蕾娜", "「因为我们国家盛产浆果，每天都可以吃」", "len419_025.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-3", null, null], [3463, "蕾娜", "「虽然不像日本的大米那样百搭，但也可以搭配各种各样的东西」", "len419_026.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-3", null, null], [3464, "将臣", "「原来如此，只要吃习惯了应该也会觉得好吃吧」", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-3", null, null], [3465, "", "我用手指沾了点果酱尝了尝，感觉味道能接受，有些人说不定会很喜欢。", null, "学院_教室休憩a", "bgm04.opus", null, "CHAPTER 5-3", null, null], [3466, "", "可为什么偏偏那个糖就那么难吃呢，真是不可思议。", null, "学院_教室休憩a", "bgm04.opus", null, "CHAPTER 5-3", null, null], [3467, "", "我作为日本人，还是更喜欢吃甜咸分明的食物。", null, "学院_教室休憩a", "bgm04.opus", null, "CHAPTER 5-3", null, null], [3468, "蕾娜", "「还有松饼，我们每天都吃，日本人好像也很喜欢吧？」", "len419_027.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-3", null, null], [3469, "小春", "「松、松饼饼！？」", "koh419_018.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "06"}, "CHAPTER 5-3", null, null], [3470, "芳乃", "「在你们国家，每天都可以吃到松饼饼吗？」", "yos419_035.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "19"}, "CHAPTER 5-3", null, null], [3471, "", "小春和朝武激动得连话都不会说了！", null, "学院_教室休憩a", "bgm04.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "19"}, "CHAPTER 5-3", null, null], [3472, "蕾娜", "「是的，还有很多其他种类的面食，但我们最经常吃的还是松饼」", "len419_028.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-3", null, null], [3473, "蕾娜", "「一般都是在盘子上叠一大堆，大家想吃多少拿多少」", "len419_029.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-3", null, null], [3474, "芳乃", "「……我有点想去北欧住住了」", "yos419_036.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "35"}, "CHAPTER 5-3", null, null], [3475, "茉子", "「您冷静点，那颗糖的味道难道您已经忘了吗？」", "mak419_041.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "13"}, "CHAPTER 5-3", null, null], [3476, "廉太郎", "「女孩子好像都很喜欢吃松饼啊。就连巫女大人也这么喜欢吃」", "ren419_022.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "29"}, "CHAPTER 5-3", null, null], [3477, "将臣", "「我甚至不知道松饼和热香饼有什么区别」", null, "学院_教室休憩a", "bgm04.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "29"}, "CHAPTER 5-3", null, null], [3478, "蕾娜", "「我们吃松饼的时候，一般会夹着鹿肉或熏制三文鱼一起吃」", "len419_030.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-3", null, null], [3479, "小春", "「……哎？」", "koh419_019.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "09"}, "CHAPTER 5-3", null, null], [3480, "芳乃", "「啊？你们那里不是盛产浆果吗？」", "yos419_037.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "30"}, "CHAPTER 5-3", null, null], [3481, "蕾娜", "「是的，但松饼一般不就是夹着三文鱼吃的吗？」", "len419_031.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-3", null, null], [3482, "小春", "「竟然不配果酱或者奶油的吗……」", "koh419_020.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "29"}, "CHAPTER 5-3", null, null], [3483, "", "怎么还是搭配咸的东西一起吃啊！", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-3", null, null], [3484, "", "好吧，大概这就是北欧的饮食文化吧。", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-3", null, null], [3485, "廉太郎", "「在我印象中不是只有英国的饭菜难吃吗」", "ren419_023.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "15"}, "CHAPTER 5-3", null, null], [3486, "茉子", "「你在说什么呢？」", "mak419_042.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "13"}, "CHAPTER 5-3", null, null], [3487, "茉子", "「英国并不是饭菜难吃，只是没有好吃的东西而已」", "mak419_043.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "32"}, "CHAPTER 5-3", null, null], [3488, "将臣", "「你们真是嘴下不留情啊」", null, "学院_教室休憩a", "bgm04.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "32"}, "CHAPTER 5-3", null, null], [3489, "廉太郎", "「你还说呢，将来受罪的是你自己好吗」", "ren419_024.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "29"}, "CHAPTER 5-3", null, null], [3490, "将臣", "「为……为什么？」", null, "学院_教室休憩a", "bgm04.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "29"}, "CHAPTER 5-3", null, null], [3491, "廉太郎", "「做饭难吃可是很痛苦的，因为你每天都要吃她做的黑暗料理」", "ren419_025.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "37"}, "CHAPTER 5-3", null, null], [3492, "将臣", "「这、这跟我有什么关系……」", null, "学院_教室休憩a", "bgm04.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "37"}, "CHAPTER 5-3", null, null], [3493, "蕾娜", "「将臣，黑暗料理是什么意思啊？」", "len419_032.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "28"}, "CHAPTER 5-3", null, null], [3494, "将臣", "「没、没什么！你不用管这个」", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "28"}, "CHAPTER 5-3", null, null], [3495, "将臣", "「每个国家的饮食文化不一样，口味当然也是不一样的」", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "28"}, "CHAPTER 5-3", null, null], [3496, "", "用我们的标准来评判他国的料理，这就跟把自己的喜好强加给别人一样。", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "28"}, "CHAPTER 5-3", null, null], [3497, "蕾娜", "「我觉得没那回事吧？」", "len419_033.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "17"}, "CHAPTER 5-3", null, null], [3498, "蕾娜", "「在我们国家，日本料理最近特别流行」", "len419_034.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-3", null, null], [3499, "", "搞了半天还是因为当地料理太难吃了吗！？", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-3", null, null], [3500, "", "本来打算帮她说句话的，竟然被她自己否定了。不过，外国人喜欢吃日本料理，我还是挺高兴的。", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-3", null, null], [3501, "蕾娜", "「哎？你们这是怎么了？」", "len419_035.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-3", null, null], [3502, "将臣", "「没、没什么，就是有种果不其然的感觉」", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-3", null, null], [3503, "茉子", "「日本料理果然很流行啊」", "mak419_044.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "10"}, "CHAPTER 5-3", null, null], [3504, "芳乃", "「我觉得……还是让蕾娜多吃点好吃的吧……」", "yos419_038.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "31n"}, "CHAPTER 5-3", null, null], [3505, "", "朝武现在的心情大概就像当妈的一样吧。", null, "学院_教室休憩a", "bgm04.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "31n"}, "CHAPTER 5-3", null, null], [3506, "", "她几乎都快要哭出来了。", null, "学院_教室休憩a", "bgm04.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "31n"}, "CHAPTER 5-3", null, null], [3507, "将臣", "「嗯？蕾娜，你吃的是什么啊？」", null, "学院_教室休憩a", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-3", null, null], [3508, "蕾娜", "「啊，这个可不是零食，这只是土豆面包而已」", "len419_036.ogg", "学院_教室休憩a", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 5-3", null, null], [3509, "将臣", "「还能用土豆烤面包！？」", null, "学院_教室休憩a", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 5-3", null, null], [3510, "", "面包大概有手掌那么大，扁扁的，乍一看有点像饼干，但质感确实很像面包。", null, "学院_教室休憩a", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 5-3", null, null], [3511, "蕾娜", "「家里还给我寄了很多特产，我越吃越怀念老家的土豆面包，就借用厨房自己烤了一些」", "len419_037.ogg", "学院_教室休憩a", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-3", null, null], [3512, "蕾娜", "「这种面包其实就是以前小麦短缺的时候穷人们吃的东西，虽然我还挺喜欢的」", "len419_038.ogg", "学院_教室休憩a", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 5-3", null, null], [3513, "将臣", "「这样啊，你自己特意烤的吗？」", null, "学院_教室休憩a", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 5-3", null, null], [3514, "", "竟然自己亲自烤，看来蕾娜是真的很喜欢吃土豆面包。", null, "学院_教室休憩a", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 5-3", null, null], [3515, "将臣", "「我可不可以吃一口？我也想尝尝是什么味道」", null, "学院_教室休憩a", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-3", null, null], [3516, "蕾娜", "「可以倒是可以，但是怎么说呢，这味道挺朴素的，并不是那么好吃，所以不是很推荐」", "len419_039.ogg", "学院_教室休憩a", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "29"}, "CHAPTER 5-3", null, null], [3517, "将臣", "「但你是很喜欢吃的吧？」", null, "学院_教室休憩a", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "29"}, "CHAPTER 5-3", null, null], [3518, "蕾娜", "「嗯……可是……你真的不要抱太高的期待哦」", "len419_040.ogg", "学院_教室休憩a", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "12"}, "CHAPTER 5-3", null, null], [3519, "蕾娜", "「这其实就像日本的粗点心一样」", "len419_041.ogg", "学院_教室休憩a", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 5-3", null, null], [3520, "将臣", "「没事，我最喜欢吃粗点心了」", null, "学院_教室休憩a", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 5-3", null, null], [3521, "", "在我的强烈要求下，蕾娜给我撕了一点。", null, "学院_教室休憩a", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 5-3", null, null], [3522, "蕾娜", "「很多日本人都吃不惯我们国家的料理，所以我就不太敢给你吃」", "len419_042.ogg", "学院_教室休憩a", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "06"}, "CHAPTER 5-3", null, null], [3523, "蕾娜", "「而且黑暗料理的意思我大概也猜到了」", "len419_043.ogg", "学院_教室休憩a", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "17"}, "CHAPTER 5-3", null, null], [3524, "将臣", "「呃……没事，这个的味道还说不定呢」", null, "学院_教室休憩a", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "17"}, "CHAPTER 5-3", null, null], [3525, "", "到底还是被她猜到了。", null, "学院_教室休憩a", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "17"}, "CHAPTER 5-3", null, null], [3526, "", "不过，只要这个面包确实好吃，就能扭转现在这气氛了！", null, "学院_教室休憩a", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "17"}, "CHAPTER 5-3", null, null], [3527, "将臣", "「我要吃了……嗯？唔」", null, "学院_教室休憩a", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "30"}, "CHAPTER 5-3", null, null], [3528, "蕾娜", "「啊，啊啊，将臣！你不用勉强自己的」", "len419_044.ogg", "学院_教室休憩a", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "08"}, "CHAPTER 5-3", null, null], [3529, "蕾娜", "「呜呜呜……果然连将臣也嫌弃爱做黑暗料理的女孩子吗……」", "len419_045.ogg", "学院_教室休憩a", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "06"}, "CHAPTER 5-3", null, null], [3530, "将臣", "「不，这个很好吃啊！」", null, "学院_教室休憩a", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "06"}, "CHAPTER 5-3", null, null], [3531, "蕾娜", "「哎？」", "len419_046.ogg", "学院_教室休憩a", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "24"}, "CHAPTER 5-3", null, null], [3532, "小春", "「哥哥……你不要勉强自己啊，现在说实话还来得及」", "koh419_021.ogg", "学院_教室休憩a", "bgm05.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "10"}, "CHAPTER 5-3", null, null], [3533, "廉太郎", "「你该不会是想骗我们，然后拉我们当垫背的吧？」", "ren419_026.ogg", "学院_教室休憩a", "bgm05.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "38"}, "CHAPTER 5-3", null, null], [3534, "将臣", "「你们不相信就算了，反正这个东西也要看个人的喜好」", null, "学院_教室休憩a", "bgm05.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "10"}, "CHAPTER 5-3", null, null], [3535, "蕾娜", "「……将臣，你是说真的吗？你真的觉得，这个好吃吗？」", "len419_047.ogg", "学院_教室休憩a", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "06"}, "CHAPTER 5-3", null, null], [3536, "将臣", "「嗯，虽然确实算不上非常好吃，但这个味道还挺让人上瘾的」", null, "学院_教室休憩a", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "06"}, "CHAPTER 5-3", null, null], [3537, "将臣", "「我能再吃一口吗？……呃，算了吧，我再吃一口你就没得吃了」", null, "学院_教室休憩a", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "34"}, "CHAPTER 5-3", null, null], [3538, "", "这样还是有点太厚脸皮了。", null, "学院_教室休憩a", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "34"}, "CHAPTER 5-3", null, null], [3539, "", "我把刚伸出去的手收了回来。", null, "学院_教室休憩a", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "34"}, "CHAPTER 5-3", null, null], [3540, "蕾娜", "「没、没事的！全都给你吃吧」", "len419_048.ogg", "学院_教室休憩a", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "03"}, "CHAPTER 5-3", null, null], [3541, "将臣", "「呃，可是」", null, "学院_教室休憩a", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "03"}, "CHAPTER 5-3", null, null], [3542, "蕾娜", "「反正我随时都可以自己烤……而且，难得你说喜欢吃我烤的面包」", "len419_049.ogg", "学院_教室休憩a", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "18"}, "CHAPTER 5-3", null, null], [3543, "蕾娜", "「我真的非常、非常开心」", "len419_050.ogg", "学院_教室休憩a", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-3", null, null], [3544, "蕾娜", "「所以……我希望你能多吃点！」", "len419_051.ogg", "学院_教室休憩a", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 5-3", null, null], [3545, "将臣", "「是、是吗？那我就不客气地吃了」", null, "学院_教室休憩a", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 5-3", null, null], [3546, "", "怎么感觉这么难为情啊。", null, "学院_教室休憩a", "bgm05.opus", null, "CHAPTER 5-3", null, null], [3547, "", "土豆面包的味道是真的很朴素，吃起来会让人很想喝牛奶。", null, "学院_教室休憩a", "bgm05.opus", null, "CHAPTER 5-3", null, null], [3548, "", "但对我来说，这个味道就像是蕾娜本人特有的味道。", null, "学院_教室休憩a", "bgm05.opus", null, "CHAPTER 5-3", null, null], [3549, "蕾娜", "「嘿嘿……有种不可思议的感觉」", "len419_052.ogg", "学院_教室休憩a", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "21"}, "CHAPTER 5-3", null, null], [3550, "将臣", "「什么意思？」", null, "学院_教室休憩a", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "21"}, "CHAPTER 5-3", null, null], [3551, "蕾娜", "「土豆面包在我们国家也是有很多人不太喜欢吃的，但没想到你会这么喜欢」", "len419_053.ogg", "学院_教室休憩a", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 5-3", null, null], [3552, "蕾娜", "「总感觉，呵呵呵……嘿嘿嘿」", "len419_054.ogg", "学院_教室休憩a", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "16"}, "CHAPTER 5-3", null, null], [3553, "蕾娜", "「……我也不知道该怎么说」", "len419_055.ogg", "学院_教室休憩a", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "03"}, "CHAPTER 5-3", null, null], [3554, "将臣", "「呃，嗯」", null, "学院_教室休憩a", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "03"}, "CHAPTER 5-3", null, null], [3555, "", "这个味道真的就是蕾娜本人特有的味道。", null, "学院_教室休憩a", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "03"}, "CHAPTER 5-3", null, null], [3556, "", "不知不觉，大家都变成了一副无话可说，但是又只能无奈接受现实的表情。", null, "学院_教室休憩a", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "03"}, "CHAPTER 5-3", null, null], [3557, "蕾娜", "「如果你喜欢吃的话，下次我再烤给你吃」", "len419_056.ogg", "学院_教室休憩a", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-3", null, null], [3558, "将臣", "「真的可以吗？」", null, "学院_教室休憩a", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-3", null, null], [3559, "蕾娜", "「可以的……你愿意吃我烤的面包，我还是挺开心的」", "len419_057.ogg", "学院_教室休憩a", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 5-3", null, null], [3560, "", "本来口感有些干燥的面包，现在吃起来却带着一丝甜味。", null, "学院_教室休憩a", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 5-3", null, null], [3561, "将臣", "「那我可以拜托你多做一些吗？」", null, "学院_教室休憩a", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 5-3", null, null], [3562, "蕾娜", "「好的！」", "len419_058.ogg", "学院_教室休憩a", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-3", null, null], [3563, "", "回家路上，我们再一次并肩走在一起。", null, "街_通学路a", "bgm54.opus", null, "CHAPTER 5-3", null, null], [3564, "", "总感觉大家是在迁就我们，给我们创造独处的机会。", null, "街_通学路a", "bgm54.opus", null, "CHAPTER 5-3", null, null], [3565, "", "现在的我，已经不敢一口咬定说这只是他们的误会了。", null, "街_通学路a", "bgm54.opus", null, "CHAPTER 5-3", null, null], [3566, "蕾娜", "「今天发生了好多有趣的事，真的很开心」", "len419_059.ogg", "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-3", null, null], [3567, "将臣", "「哈哈，虽然也出了几件挺倒霉的事」", null, "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-3", null, null], [3568, "", "蕾娜再一次牵住我的手。", null, "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-3", null, null], [3569, "", "而我，似乎也正在等待这一刻。", null, "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-3", null, null], [3570, "蕾娜", "「是呀，我今天讲了好多我们国家的事，聊得挺欢乐的」", "len419_060.ogg", "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "28"}, "CHAPTER 5-3", null, null], [3571, "蕾娜", "「但遗憾的是，我们国家的食物都不怎么对日本人的胃口」", "len419_061.ogg", "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 5-3", null, null], [3572, "将臣", "「不不，我觉得能聊这些话题还是很有意思的」", null, "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 5-3", null, null], [3573, "", "虽然那个叫Ｓａｌｍｉａｋｋｉ的糖我是不想再吃了。", null, "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 5-3", null, null], [3574, "将臣", "「而且今天了解了很多关于你的事，我也蛮开心的」", null, "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 5-3", null, null], [3575, "蕾娜", "「……听到将臣这么说，我也超开心」", "len419_062.ogg", "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 5-3", null, null], [3576, "将臣", "「对了！有件事我一直都想问你」", null, "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 5-3", null, null], [3577, "蕾娜", "「嗯？是什么事呀？」", "len419_063.ogg", "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-3", null, null], [3578, "将臣", "「你们国家到底是个什么样的地方呢？我还想再多了解一些」", null, "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-3", null, null], [3579, "将臣", "「你能再给我讲讲吗？」", null, "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-3", null, null], [3580, "蕾娜", "「当然可以啦！不过你具体是想知道哪些方面的事呢？」", "len419_064.ogg", "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-3", null, null], [3581, "将臣", "「什么都行……我想想，比如，你的故乡是个什么样的地方呢？」", null, "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-3", null, null], [3582, "蕾娜", "「我的故乡在我们国家的北部……也就是拉普兰地区，位于北极圈」", "len419_065.ogg", "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-3", null, null], [3583, "将臣", "「嗯，这个你之前说过」", null, "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-3", null, null], [3584, "蕾娜", "「是的，所以有时候会出一整天太阳，有时也会一整天见不到太阳」", "len419_066.ogg", "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-3", null, null], [3585, "将臣", "「也就是极昼和极夜吧？」", null, "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-3", null, null], [3586, "蕾娜", "「极昼和极夜？极昼、极夜……我记住了」", "len419_067.ogg", "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 5-3", null, null], [3587, "蕾娜", "「还有就是，每到冬天，就会有很多游客来看极光」", "len419_068.ogg", "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-3", null, null], [3588, "将臣", "「毕竟是极光之国嘛」", null, "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-3", null, null], [3589, "蕾娜", "「是的，夏天的森林和湖泊非常美丽，而且只要是没人住的地方，浆果都可以随便采摘」", "len419_069.ogg", "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-3", null, null], [3590, "蕾娜", "「法律上也规定了，我们都有自由采摘浆果的权利」", "len419_070.ogg", "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-3", null, null], [3591, "将臣", "「是吗，感觉挺棒的」", null, "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-3", null, null], [3592, "蕾娜", "「就算在欧洲，这可能也算比较少见的」", "len419_071.ogg", "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-3", null, null], [3593, "蕾娜", "「不过我们国家到处都长着浆果，所以大家都会随便摘」", "len419_072.ogg", "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 5-3", null, null], [3594, "将臣", "「到处都有？意思就是，哪怕全国人民天天都吃也吃不光吗？」", null, "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 5-3", null, null], [3595, "将臣", "「感觉自然资源好丰富啊」", null, "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 5-3", null, null], [3596, "", "穗织已经算是很乡下了，但对我这个日本人来说还是难以想象她老家的情况。", null, "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 5-3", null, null], [3597, "蕾娜", "「说到自然，峡湾也是我们那里的一大特色，很多旅客都会来看」", "len419_073.ogg", "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "18"}, "CHAPTER 5-3", null, null], [3598, "将臣", "「峡湾是什么？」", null, "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "18"}, "CHAPTER 5-3", null, null], [3599, "蕾娜", "「这个……说明起来可能有点难，反正就是在很久很久以前，我们那片土地还是一片冰原」", "len419_074.ogg", "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-3", null, null], [3600, "将臣", "「很久很久以前，是指冰河期吗？」", null, "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-3", null, null], [3601, "蕾娜", "「冰河期……原来是这么说的呀……就在那个时候，能覆盖整座大陆的大冰块削开了山峰和海洋」", "len419_075.ogg", "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "26"}, "CHAPTER 5-3", null, null], [3602, "蕾娜", "「然后，就产生了峡湾」", "len419_076.ogg", "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-3", null, null], [3603, "将臣", "「这样啊，有点难以想象……不过听上去就感觉很壮观」", null, "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-3", null, null], [3604, "蕾娜", "「虽然以前对我来说是每天都能看见的景色，但现在离开家乡之后还挺怀念的」", "len419_077.ogg", "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "26"}, "CHAPTER 5-3", null, null], [3605, "蕾娜", "「有朝一日，我希望带着你一起去看」", "len419_078.ogg", "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-3", null, null], [3606, "将臣", "「哈哈，我还得去看极光呢，感觉有得逛了」", null, "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-3", null, null], [3607, "蕾娜", "「还有就是……对了，我们村子里还养了很多驯鹿」", "len419_079.ogg", "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "24"}, "CHAPTER 5-3", null, null], [3608, "蕾娜", "「要是把盆栽之类的植物都放到室外，有时就会被驯鹿吃掉」", "len419_080.ogg", "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "21"}, "CHAPTER 5-3", null, null], [3609, "将臣", "「是吗，驯鹿也是随处可见的吗？我一听到驯鹿，只能想到它拉着圣诞老人的雪橇的样子」", null, "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "21"}, "CHAPTER 5-3", null, null], [3610, "蕾娜", "「哈哈，虽然驯鹿力气很大，但是走路特别慢」", "len419_081.ogg", "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-3", null, null], [3611, "蕾娜", "「圣诞老人的旅途肯定也是相当悠闲的吧」", "len419_082.ogg", "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "26"}, "CHAPTER 5-3", null, null], [3612, "", "我开始在脑海中想象。想象一座十分宁静的村庄。", null, "街_通学路a", "bgm54.opus", null, "CHAPTER 5-3", null, null], [3613, "", "想着想着，我脑中就浮现出了一座跟蕾娜的印象很搭的村庄。", null, "街_通学路a", "bgm54.opus", null, "CHAPTER 5-3", null, null], [3614, "将臣", "「真的好想去看看」", null, "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-3", null, null], [3615, "蕾娜", "「来就对啦！要看极光的话，来我们村庄是最适合的」", "len419_083.ogg", "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 5-3", null, null], [3616, "", "在那万里雪飘的极北之地，我和蕾娜并肩而坐，仰望星空。", null, "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 5-3", null, null], [3617, "", "一听她这么说，我忍不住开始想象。", null, "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 5-3", null, null], [3618, "蕾娜", "「在我们国家，驯鹿是非常重要的动物」", "len419_084.ogg", "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 5-3", null, null], [3619, "蕾娜", "「驯鹿的角和毛皮，还有骨头都会被分毫不剩地拿去制作道具，它们身上每个部位的肉我们都会吃」", "len419_085.ogg", "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-3", null, null], [3620, "", "我又想象了一下驯鹿骨做的传统工艺品。", null, "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-3", null, null], [3621, "蕾娜", "「日本料理流行起来之后，我们还学日本的干制鲣鱼，做了干制驯鹿肉」", "len419_086.ogg", "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-3", null, null], [3622, "将臣", "「好厉害！居然还能根据自己的口味喜好，研发出新的食材」", null, "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-3", null, null], [3623, "将臣", "「话说我好想尝尝看啊！很好奇是什么味道」", null, "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-3", null, null], [3624, "蕾娜", "「嘿嘿，在我们国家也挺少见的啦」", "len419_087.ogg", "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 5-3", null, null], [3625, "", "仔细想想，这种连骨头都要全部利用的精神，跟日本的传统价值观挺像的。", null, "街_通学路a", "bgm54.opus", null, "CHAPTER 5-3", null, null], [3626, "", "她们国家跟日本的相似之处似乎还挺多。", null, "街_通学路a", "bgm54.opus", null, "CHAPTER 5-3", null, null], [3627, "", "现在，我大概能明白为什么会有用土豆代替面粉做的面包，以及那种味道十分不可思议的糖果了。", null, "街_通学路a", "bgm54.opus", null, "CHAPTER 5-3", null, null], [3628, "", "由于地处大陆的最北端，想必食材并不那么丰富。", null, "街_通学路a", "bgm54.opus", null, "CHAPTER 5-3", null, null], [3629, "", "当地人利用有限的材料，发挥最大的智慧，才诞生了北欧料理。", null, "街_通学路a", "bgm54.opus", null, "CHAPTER 5-3", null, null], [3630, "", "他们用智慧将贫困变成了富足。", null, "街_通学路a", "bgm54.opus", null, "CHAPTER 5-3", null, null], [3631, "", "过去的日本其实也一样，或许每个国家都是这样。", null, "街_通学路a", "bgm54.opus", null, "CHAPTER 5-3", null, null], [3632, "蕾娜", "「啊，说得我突然好想见爷爷，好想见爸爸妈妈，已经好久没见她们了」", "len419_088.ogg", "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "03"}, "CHAPTER 5-3", null, null], [3633, "将臣", "「……」", null, "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "03"}, "CHAPTER 5-3", null, null], [3634, "", "对蕾娜来说，这或许只是一句表达情绪的无心之语。", null, "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "03"}, "CHAPTER 5-3", null, null], [3635, "", "但对我来说，这句话让我感到无比焦虑，就好像好不容易才接近的东西忽然又要一溜烟飞走一样。", null, "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "03"}, "CHAPTER 5-3", null, null], [3636, "蕾娜", "「……哎？」", "len419_089.ogg", "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "04"}, "CHAPTER 5-3", null, null], [3637, "将臣", "「呃，那什么」", null, "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "04"}, "CHAPTER 5-3", null, null], [3638, "", "我不禁握紧了蕾娜的手。", null, "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "04"}, "CHAPTER 5-3", null, null], [3639, "", "就像是在说，“不要离开我”。", null, "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "04"}, "CHAPTER 5-3", null, null], [3640, "", "虽然动作很小，却让我脸颊羞得发烫。我根本不敢直视蕾娜的脸。", null, "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "04"}, "CHAPTER 5-3", null, null], [3641, "", "而蕾娜似乎也跟我一样。", null, "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "04"}, "CHAPTER 5-3", null, null], [3642, "蕾娜", "「这……这还是你第一次……主、主动握紧我的手呢」", "len419_090.ogg", "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27h"}, "CHAPTER 5-3", null, null], [3643, "将臣", "「是、是吗？」", null, "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27h"}, "CHAPTER 5-3", null, null], [3644, "蕾娜", "「是的……以前，虽然你不反感……但是从来没有主动握紧过」", "len419_091.ogg", "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "21h"}, "CHAPTER 5-3", null, null], [3645, "", "这么一说，好像确实是。", null, "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "21h"}, "CHAPTER 5-3", null, null], [3646, "蕾娜", "「……～～～～」", "len419_092.ogg", "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "04h"}, "CHAPTER 5-3", null, null], [3647, "将臣", "「～」", null, "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "04h"}, "CHAPTER 5-3", null, null], [3648, "", "我们好不容易紧紧牵住对方的手，却羞得根本不好意思看对方。", null, "街_通学路a", "bgm54.opus", null, "CHAPTER 5-3", null, null], [3649, "", "情急之下，我竟然没话找话又说了一件令人害羞的事。", null, "街_通学路a", "bgm54.opus", null, "CHAPTER 5-3", null, null], [3650, "将臣", "「对、对了，要不我们办一次睡衣派对吧？」", null, "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "06h"}, "CHAPTER 5-3", null, null], [3651, "蕾娜", "「哎？将、将臣！？这、这个……」", "len419_093.ogg", "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "08h"}, "CHAPTER 5-3", null, null], [3652, "将臣", "「不、不是你想的那样！只是叫上大家一起，晚上在志那都庄过夜而已」", null, "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "08h"}, "CHAPTER 5-3", null, null], [3653, "将臣", "「以前我和廉太郎还有小春，经常像这样把朋友叫到一起玩」", null, "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "20"}, "CHAPTER 5-3", null, null], [3654, "蕾娜", "「……唔」", "len419_094.ogg", "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "09"}, "CHAPTER 5-3", null, null], [3655, "", "不知为何，她看上去意见很大。", null, "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "09"}, "CHAPTER 5-3", null, null], [3656, "", "不过，我说出这话也并非完全没有考虑过。", null, "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "09"}, "CHAPTER 5-3", null, null], [3657, "将臣", "「因为，你想嘛，你一时半会儿也不能离开穗织」", null, "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "09"}, "CHAPTER 5-3", null, null], [3658, "将臣", "「就算现在想见家人，也很难见到吧？」", null, "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "09"}, "CHAPTER 5-3", null, null], [3659, "蕾娜", "「哎？」", "len419_095.ogg", "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "20"}, "CHAPTER 5-3", null, null], [3660, "将臣", "「虽然我们可能没办法代替你的家人，但可以多陪陪你」", null, "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "20"}, "CHAPTER 5-3", null, null], [3661, "将臣", "「……不，也不能这么说」", null, "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "20"}, "CHAPTER 5-3", null, null], [3662, "将臣", "「我是想让你痛痛快快地开心一次，让你更加喜欢穗织这个地方！」", null, "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "20"}, "CHAPTER 5-3", null, null], [3663, "", "想要团聚。", null, "街_通学路a", "bgm54.opus", null, "CHAPTER 5-3", null, null], [3664, "", "如果被祟神操控的原因，都在于内心的思乡之情……", null, "街_通学路a", "bgm54.opus", null, "CHAPTER 5-3", null, null], [3665, "", "那么只要让她觉得待在这里才是最开心的，应该就可以防止再次被操控了吧？", null, "街_通学路a", "bgm54.opus", null, "CHAPTER 5-3", null, null], [3666, "", "我希望穗织能成为蕾娜的一片乐土。", null, "街_通学路a", "bgm54.opus", null, "CHAPTER 5-3", null, null], [3667, "蕾娜", "「噗，将臣你也真是的，我本来就超喜欢穗织啦」", "len419_096.ogg", "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-3", null, null], [3668, "将臣", "「啊、啊，是吗」", null, "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-3", null, null], [3669, "蕾娜", "「要开睡衣派对的话，我双手赞成！」", "len419_097.ogg", "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "24"}, "CHAPTER 5-3", null, null], [3670, "蕾娜", "「本来还以为，我在志那都庄工作是没办法叫朋友过来玩的」", "len419_098.ogg", "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 5-3", null, null], [3671, "蕾娜", "「所以如果可以叫朋友过来玩，那一定非常开心！」", "len419_099.ogg", "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 5-3", null, null], [3672, "将臣", "「嗯！那我这就去跟大家商量下吧」", null, "街_通学路a", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 5-3", null, null], [3673, "", "首先，我们必须征得老板娘猪谷阿姨的同意。", null, "旅館_廊下a", "bgm37.opus", null, "CHAPTER 5-3", null, null], [3674, "", "我送蕾娜回来时，顺便问了问她。", null, "旅館_廊下a", "bgm37.opus", null, "CHAPTER 5-3", null, null], [3675, "心子", "「可以的，只要你们别闹到深夜就行」", "mot419_001.ogg", "旅館_廊下a", "bgm37.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "02"}, "CHAPTER 5-3", null, null], [3676, "心子", "「朋友小聚一下还是没问题的」", "mot419_002.ogg", "旅館_廊下a", "bgm37.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "03"}, "CHAPTER 5-3", null, null], [3677, "", "猪谷阿姨很干脆地就答应了。", null, "旅館_廊下a", "bgm37.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "01"}, "CHAPTER 5-3", null, null], [3678, "", "之前她还怀疑我半夜偷偷跑来幽会，外公到底有没有帮我解释清楚呢？", null, "旅館_廊下a", "bgm37.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "01"}, "CHAPTER 5-3", null, null], [3679, "将臣", "「真的可以吗？」", null, "旅館_廊下a", "bgm37.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "01"}, "CHAPTER 5-3", null, null], [3680, "心子", "「最近客人并不那么多，我们刚好正在安排各位员工轮流休假呢」", "mot419_003.ogg", "旅館_廊下a", "bgm37.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "01"}, "CHAPTER 5-3", null, null], [3681, "心子", "「毕竟列支敦瑙尔小姐是住在我们这里工作」", "mot419_004.ogg", "旅館_廊下a", "bgm37.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "12"}, "CHAPTER 5-3", null, null], [3682, "心子", "「偶尔放松一下，对身心都有好处」", "mot419_005.ogg", "旅館_廊下a", "bgm37.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "14"}, "CHAPTER 5-3", null, null], [3683, "", "原来如此，这也是员工福利的一环啊。", null, "旅館_廊下a", "bgm37.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "14"}, "CHAPTER 5-3", null, null], [3684, "蕾娜", "「谢谢掌柜的！」", "len419_100.ogg", "旅館_廊下a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 5-3", null, null], [3685, "心子", "「嗯，但这次是破例」", "mot419_006.ogg", "旅館_廊下a", "bgm37.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "05"}, "CHAPTER 5-3", null, null], [3686, "心子", "「自从你跟将臣少爷亲近起来，工作都比以前更卖力了，这一点还是值得夸奖的」", "mot419_007.ogg", "旅館_廊下a", "bgm37.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "03"}, "CHAPTER 5-3", null, null], [3687, "将臣", "「哎，是吗？」", null, "旅館_廊下a", "bgm37.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "03"}, "CHAPTER 5-3", null, null], [3688, "蕾娜", "「掌、掌、掌柜的！不、不要多说那些有的没的啦」", "len419_101.ogg", "旅館_廊下a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "18h"}, "CHAPTER 5-3", null, null], [3689, "心子", "「哈哈，是我失礼了。但是，如果你太得意忘形，耽误了工作」", "mot419_008.ogg", "旅館_廊下a", "bgm37.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "10"}, "CHAPTER 5-3", null, null], [3690, "心子", "「我可就不会再同意了，这个你要记好了」", "mot419_009.ogg", "旅館_廊下a", "bgm37.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "13"}, "CHAPTER 5-3", null, null], [3691, "蕾娜", "「唔，我……我明白了」", "len419_102.ogg", "旅館_廊下a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "15"}, "CHAPTER 5-3", null, null], [3692, "", "总之，睡衣派对的事算是定了，地点就在蕾娜的房间。", null, "旅館_廊下a", "bgm37.opus", null, "CHAPTER 5-3", null, null], [3693, "蕾娜", "「太好了，将臣！现在就可以招待大家了」", "len419_103.ogg", "旅館_廊下a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-3", null, null], [3694, "将臣", "「哇，喔！？蕾、蕾娜？」", null, "旅館_廊下a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 5-3", null, null], [3695, "", "她竟然一下子抱了上来。", null, "旅館_廊下a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 5-3", null, null], [3696, "", "具体是哪个部位我就不说了，反正威力非常强悍！", null, "旅館_廊下a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 5-3", null, null], [3697, "蕾娜", "「喔、喔，差点忘了，日本人不习惯拥抱」", "len419_104.ogg", "旅館_廊下a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-3", null, null], [3698, "将臣", "「抱歉，我就是吓到了」", null, "旅館_廊下a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 5-3", null, null], [3699, "蕾娜", "「嗯……不过，我还是希望……你能习惯一下」", "len419_105.ogg", "旅館_廊下a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 5-3", null, null], [3700, "蕾娜", "「拥抱只是打招呼而已啦」", "len419_106.ogg", "旅館_廊下a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-3", null, null], [3701, "", "说实话，就算想要习惯，也还是挺难的。", null, "旅館_廊下a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-3", null, null], [3702, "", "但要是让她单方面地配合日本人的习惯，我觉得也不太好。", null, "旅館_廊下a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-3", null, null], [3703, "将臣", "「明白了，我会尽量努力的」", null, "旅館_廊下a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 5-3", null, null], [3704, "蕾娜", "「嗯……嘿嘿，希望以后能天天拥抱」", "len419_107.ogg", "旅館_廊下a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19h"}, "CHAPTER 5-3", null, null], [3705, "将臣", "「呃、嗯」", null, "旅館_廊下a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19h"}, "CHAPTER 5-3", null, null], [3706, "", "感觉蕾娜现在变得比以前更主动了。", null, "旅館_廊下a", "bgm37.opus", null, "CHAPTER 5-3", null, null], [3707, "", "大概是特别期待睡衣派对，所以心情很激动吧。", null, "旅館_廊下a", "bgm37.opus", null, "CHAPTER 5-3", null, null], [3708, "", "好了，现在地点也确定了，要赶快邀请大家才行。", null, "街_甘味処b", "bgm11.opus", null, "CHAPTER 5-3", null, null], [3709, "", "我首先来到了最近的地方，也就是芦花姐家的甜品屋。", null, "街_甘味処b", "bgm11.opus", null, "CHAPTER 5-3", null, null], [3710, "小春", "「哇，大家要一起开睡衣派对吗！」", "koh419_022.ogg", "街_甘味処b", "bgm11.opus", {"char": "小春", "file": "小春.stand", "dress": "仕事着", "face": "20"}, "CHAPTER 5-3", null, null], [3711, "廉太郎", "「好怀念啊，这次也是像我们小时候那样吗？」", "ren419_027.ogg", "街_甘味処b", "bgm11.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-3", null, null], [3712, "将臣", "「是的，大概就是那种感觉，你们觉得如何？」", null, "街_甘味処b", "bgm11.opus", {"char": "小春", "file": "小春.stand", "dress": "仕事着", "face": "01"}, "CHAPTER 5-3", null, null], [3713, "小春", "「哥哥难得邀请我一次！我明天没有排班，一定会去的」", "koh419_023.ogg", "街_甘味処b", "bgm11.opus", {"char": "小春", "file": "小春.stand", "dress": "仕事着", "face": "02"}, "CHAPTER 5-3", null, null], [3714, "廉太郎", "「我肯定也会参加的」", "ren419_028.ogg", "街_甘味処b", "bgm11.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "私服", "face": "25"}, "CHAPTER 5-3", null, null], [3715, "将臣", "「谢谢！那明天志那都庄见了」", null, "街_甘味処b", "bgm11.opus", {"char": "小春", "file": "小春.stand", "dress": "仕事着", "face": "01"}, "CHAPTER 5-3", null, null], [3716, "将臣", "「话说，廉太郎竟然跑来甜品屋，真是稀奇啊」", null, "街_甘味処b", "bgm11.opus", {"char": "小春", "file": "小春.stand", "dress": "仕事着", "face": "01"}, "CHAPTER 5-3", null, null], [3717, "廉太郎", "「我就是想偶尔视察下妹妹工作的样子」", "ren419_029.ogg", "街_甘味処b", "bgm11.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "私服", "face": "06"}, "CHAPTER 5-3", null, null], [3718, "小春", "「又在骗人」", "koh419_024.ogg", "街_甘味処b", "bgm11.opus", {"char": "小春", "file": "小春.stand", "dress": "仕事着", "face": "10"}, "CHAPTER 5-3", null, null], [3719, "小春", "「肯定是因为女孩子们都不理你，再加上最近哥哥也没时间陪你，你闲得没事做吧」", "koh419_025.ogg", "街_甘味処b", "bgm11.opus", {"char": "小春", "file": "小春.stand", "dress": "仕事着", "face": "12"}, "CHAPTER 5-3", null, null], [3720, "将臣", "「哈哈……那芦花姐，你要来参加吗？」", null, "街_甘味処b", "bgm11.opus", null, "CHAPTER 5-3", null, null], [3721, "芦花", "「抱歉啦，我也很想去，但是我得忙店里的工作」", "rok419_001.ogg", "街_甘味処b", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "11"}, "CHAPTER 5-3", null, null], [3722, "将臣", "「啊，也是」", null, "街_甘味処b", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "11"}, "CHAPTER 5-3", null, null], [3723, "芦花", "「有工作的人可是很辛苦的」", "rok419_002.ogg", "街_甘味処b", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "09"}, "CHAPTER 5-3", null, null], [3724, "芦花", "「不过机会难得，我可以给你们做点好吃的送过去吗？」", "rok419_003.ogg", "街_甘味処b", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "17"}, "CHAPTER 5-3", null, null], [3725, "将臣", "「可以麻烦你吗？」", null, "街_甘味処b", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "17"}, "CHAPTER 5-3", null, null], [3726, "芦花", "「当然了。蕾娜之前也帮我试吃了芭菲，我得好好感谢感谢你们呢」", "rok419_004.ogg", "街_甘味処b", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "01"}, "CHAPTER 5-3", null, null], [3727, "廉太郎", "「哇，真的吗！」", "ren419_030.ogg", "街_甘味処b", "bgm11.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "私服", "face": "26"}, "CHAPTER 5-3", null, null], [3728, "小春", "「谢谢姐姐！」", "koh419_026.ogg", "街_甘味処b", "bgm11.opus", {"char": "小春", "file": "小春.stand", "dress": "仕事着", "face": "02"}, "CHAPTER 5-3", null, null], [3729, "将臣", "「你说得我好期待」", null, "街_甘味処b", "bgm11.opus", {"char": "小春", "file": "小春.stand", "dress": "仕事着", "face": "02"}, "CHAPTER 5-3", null, null], [3730, "芦花", "「嘿嘿，你们就好好期待吧」", "rok419_005.ogg", "街_甘味処b", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "03"}, "CHAPTER 5-3", null, null], [3731, "", "好吃的更多了，派对肯定能办得更开心。", null, "街_甘味処b", "bgm11.opus", {"char": "芦花", "file": "芦花.stand", "dress": "仕事着", "face": "03"}, "CHAPTER 5-3", null, null], [3732, "小春", "「不过志那都庄就跟我们家差不多，我们睡的时候最好还是回自己房间睡吧？」", "koh419_027.ogg", "街_甘味処b", "bgm11.opus", {"char": "小春", "file": "小春.stand", "dress": "仕事着", "face": "14"}, "CHAPTER 5-3", null, null], [3733, "廉太郎", "「哎？大家一起睡不好吗？」", "ren419_031.ogg", "街_甘味処b", "bgm11.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-3", null, null], [3734, "小春", "「那可不行，有你在，绝对不行！」", "koh419_028.ogg", "街_甘味処b", "bgm11.opus", {"char": "小春", "file": "小春.stand", "dress": "仕事着", "face": "14"}, "CHAPTER 5-3", null, null], [3735, "小春", "「怎么能让廉哥跟女孩子们睡在一个房间呢」", "koh419_029.ogg", "街_甘味処b", "bgm11.opus", {"char": "小春", "file": "小春.stand", "dress": "仕事着", "face": "06"}, "CHAPTER 5-3", null, null], [3736, "将臣", "「哈哈……」", null, "街_甘味処b", "bgm11.opus", {"char": "小春", "file": "小春.stand", "dress": "仕事着", "face": "06"}, "CHAPTER 5-3", null, null], [3737, "", "我也跟廉太郎一起去他房间睡吧，还是这样比较合适。", null, "街_甘味処b", "bgm11.opus", null, "CHAPTER 5-3", null, null], [3738, "将臣", "「——大概就是这样，大家一起睡，若是祟神那边发生什么情况也能及时应对」", null, "朝武_リビングd", "bgm05.opus", null, "CHAPTER 5-3", null, null], [3739, "将臣", "「你们觉得如何呢？这次睡衣派对能来参加吗？」", null, "朝武_リビングd", "bgm05.opus", null, "CHAPTER 5-3", null, null], [3740, "芳乃", "「…………～」", "yos419_039.ogg", "朝武_リビングd", "bgm05.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "08"}, "CHAPTER 5-3", null, null], [3741, "", "随后，我来到朝武家，跟另外三个人打招呼。", null, "朝武_リビングd", "bgm05.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "08"}, "CHAPTER 5-3", null, null], [3742, "丛雨", "「这个想法不错，主人」", "mur419_011.ogg", "朝武_リビングd", "bgm05.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-3", null, null], [3743, "丛雨", "「如果蕾娜思乡之情太过强烈，万一再次被祟神操控」", "mur419_012.ogg", "朝武_リビングd", "bgm05.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "22"}, "CHAPTER 5-3", null, null], [3744, "丛雨", "「有可能会变得不可控制」", "mur419_013.ogg", "朝武_リビングd", "bgm05.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "14"}, "CHAPTER 5-3", null, null], [3745, "茉子", "「确实，丛雨大人说的有道理」", "mak419_045.ogg", "朝武_リビングd", "bgm05.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "26"}, "CHAPTER 5-3", null, null], [3746, "茉子", "「可是，有地，你办这个睡衣派对真的没有其他目的吗？」", "mak419_046.ogg", "朝武_リビングd", "bgm05.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "31"}, "CHAPTER 5-3", null, null], [3747, "将臣", "「哈、哈哈哈，我就是单纯想跟大家一起度过一段开心的时光而已」", null, "朝武_リビングd", "bgm05.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "31"}, "CHAPTER 5-3", null, null], [3748, "将臣", "「虽然我确实想跟蕾娜进一步培养感情」", null, "朝武_リビングd", "bgm05.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "31"}, "CHAPTER 5-3", null, null], [3749, "丛雨", "「是吗」", "mur419_014.ogg", "朝武_リビングd", "bgm05.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "03"}, "CHAPTER 5-3", null, null], [3750, "茉子", "「哈哈，现在都变得这么诚实了呀」", "mak419_047.ogg", "朝武_リビングd", "bgm05.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "23"}, "CHAPTER 5-3", null, null], [3751, "将臣", "「不、不是，最主要的目的当然还是大家一起开开心心地玩耍，真的」", null, "朝武_リビングd", "bgm05.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "23"}, "CHAPTER 5-3", null, null], [3752, "", "好吧，就算我这么说，也没什么说服力。", null, "朝武_リビングd", "bgm05.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "23"}, "CHAPTER 5-3", null, null], [3753, "茉子", "「嗯，我明白」", "mak419_048.ogg", "朝武_リビングd", "bgm05.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-3", null, null], [3754, "茉子", "「其实我也一直想跟蕾娜加深下感情」", "mak419_049.ogg", "朝武_リビングd", "bgm05.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "25"}, "CHAPTER 5-3", null, null], [3755, "将臣", "「那我就算你一个了？」", null, "朝武_リビングd", "bgm05.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "25"}, "CHAPTER 5-3", null, null], [3756, "将臣", "「朝武呢，你能来吗？……朝武？」", null, "朝武_リビングd", "bgm05.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "39"}, "CHAPTER 5-3", null, null], [3757, "芳乃", "「……～～……～」", "yos419_040.ogg", "朝武_リビングd", "bgm05.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "12"}, "CHAPTER 5-3", null, null], [3758, "", "朝武一会儿抬起胳膊，一会儿放下去，一会儿看左，一会儿看右，最后又突然转了个身，看上去就跟在跳某种神秘舞蹈似的。", null, "朝武_リビングd", "bgm05.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "46"}, "CHAPTER 5-3", null, null], [3759, "", "难道是在模仿可疑人士吗？", null, "朝武_リビングd", "bgm05.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "46"}, "CHAPTER 5-3", null, null], [3760, "", "过了一会儿，她瞪大了眼睛，畏畏缩缩地指了指自己。", null, "朝武_リビングd", "bgm05.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "25"}, "CHAPTER 5-3", null, null], [3761, "芳乃", "「难、难道……你是在邀请我吗？」", "yos419_041.ogg", "朝武_リビングd", "bgm05.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "09"}, "CHAPTER 5-3", null, null], [3762, "芳乃", "「是蕾娜希望我去参加吗！？」", "yos419_042.ogg", "朝武_リビングd", "bgm05.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "17"}, "CHAPTER 5-3", null, null], [3763, "将臣", "「她说要叫上所有朋友一起，那当然也包括你吧？」", null, "朝武_リビングd", "bgm05.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "17"}, "CHAPTER 5-3", null, null], [3764, "芳乃", "「……～～～～」", "yos419_043.ogg", "朝武_リビングd", "bgm05.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "31n"}, "CHAPTER 5-3", null, null], [3765, "", "不知为何，朝武突然两眼含泪，一脸感激。", null, "朝武_リビングd", "bgm05.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "31n"}, "CHAPTER 5-3", null, null], [3766, "芳乃", "「我好幸福……」", "yos419_044.ogg", "朝武_リビングd", "bgm05.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "27n"}, "CHAPTER 5-3", null, null], [3767, "芳乃", "「我、我长这么大，这、这还是第一次……有朋友邀请我参加睡衣派对！」", "yos419_045.ogg", "朝武_リビングd", "bgm05.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "23n"}, "CHAPTER 5-3", null, null], [3768, "将臣", "「啊、啊，是吗」", null, "朝武_リビングd", "bgm05.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "23n"}, "CHAPTER 5-3", null, null], [3769, "茉子", "「恭喜芳乃大人，您多年的夙愿终于实现了」", "mak419_050.ogg", "朝武_リビングd", "bgm05.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "25"}, "CHAPTER 5-3", null, null], [3770, "芳乃", "「嗯……嗯，谢谢你，茉子」", "yos419_046.ogg", "朝武_リビングd", "bgm05.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "03n"}, "CHAPTER 5-3", null, null], [3771, "芳乃", "「其实我的梦想就是，有朝一日能有朋友来邀请我参加睡衣派对」", "yos419_047.ogg", "朝武_リビングd", "bgm05.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "29"}, "CHAPTER 5-3", null, null], [3772, "芳乃", "「我本以为，到了现在的年龄，这个梦想已经永远不会实现了……」", "yos419_048.ogg", "朝武_リビングd", "bgm05.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "31"}, "CHAPTER 5-3", null, null], [3773, "将臣", "「没必要这么夸张啦，放自然点就行」", null, "朝武_リビングd", "bgm05.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "31"}, "CHAPTER 5-3", null, null], [3774, "芳乃", "「可是，这对我来说……啊！」", "yos419_049.ogg", "朝武_リビングd", "bgm05.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "06"}, "CHAPTER 5-3", null, null], [3775, "", "话刚说到一半，朝武突然脸色苍白。", null, "朝武_リビングd", "bgm05.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "06"}, "CHAPTER 5-3", null, null], [3776, "芳乃", "「那、那个，我……真的非常，非常想去……」", "yos419_050.ogg", "朝武_リビングd", "bgm05.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "13"}, "CHAPTER 5-3", null, null], [3777, "将臣", "「嗯，我看出来了……难道是不太方便吗？」", null, "朝武_リビングd", "bgm05.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "13"}, "CHAPTER 5-3", null, null], [3778, "芳乃", "「……………………是的」", "yos419_051.ogg", "朝武_リビングd", "bgm05.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "31"}, "CHAPTER 5-3", null, null], [3779, "芳乃", "「我毕竟是朝武家的巫女，每天的职责还是不能懈怠的」", "yos419_052.ogg", "朝武_リビングd", "bgm05.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "30"}, "CHAPTER 5-3", null, null], [3780, "", "啊，朝武的情况确实跟无拘无束的普通学生不一样。", null, "朝武_リビングd", "bgm05.opus", null, "CHAPTER 5-3", null, null], [3781, "", "但看到她这副无比失落的样子，我心里也很不好受。难道就真的没有办法了吗？", null, "朝武_リビングd", "bgm05.opus", null, "CHAPTER 5-3", null, null], [3782, "安晴", "「你就答应呗？偶尔去一次挺好的」", "yas419_006.ogg", "朝武_リビングd", "bgm05.opus", {"char": "安晴", "file": "安晴.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-3", null, null], [3783, "将臣", "「安晴叔叔！」", null, "朝武_リビングd", "bgm05.opus", {"char": "安晴", "file": "安晴.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-3", null, null], [3784, "芳乃", "「爸、爸爸，那怎么能行呢！我要是在志那都庄过夜，第二天的早课就来不及了」", "yos419_053.ogg", "朝武_リビングd", "bgm05.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "30"}, "CHAPTER 5-3", null, null], [3785, "安晴", "「确实，在那过夜可能有点困难，但你可以陪大家一起玩到睡觉之前嘛」", "yas419_007.ogg", "朝武_リビングd", "bgm05.opus", {"char": "安晴", "file": "安晴.stand", "dress": "私服", "face": "14"}, "CHAPTER 5-3", null, null], [3786, "安晴", "「那天你可以晚点再回来」", "yas419_008.ogg", "朝武_リビングd", "bgm05.opus", {"char": "安晴", "file": "安晴.stand", "dress": "私服", "face": "13"}, "CHAPTER 5-3", null, null], [3787, "芳乃", "「可、可是……」", "yos419_054.ogg", "朝武_リビングd", "bgm05.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "06"}, "CHAPTER 5-3", null, null], [3788, "将臣", "「偶尔放松一下也挺好的！你看安晴叔叔都这么说了，是不是」", null, "朝武_リビングd", "bgm05.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "13"}, "CHAPTER 5-3", null, null], [3789, "茉子", "「就是呀，芳乃大人，人家难得邀请您，您要是拒绝的话未免有点失礼吧」", "mak419_051.ogg", "朝武_リビングd", "bgm05.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "28"}, "CHAPTER 5-3", null, null], [3790, "芳乃", "「也……也是，这样确实不太好」", "yos419_055.ogg", "朝武_リビングd", "bgm05.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "28"}, "CHAPTER 5-3", null, null], [3791, "芳乃", "「……对了，我带一些好吃的过去吧！」", "yos419_056.ogg", "朝武_リビングd", "bgm05.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "21"}, "CHAPTER 5-3", null, null], [3792, "芳乃", "「我想让蕾娜吃很多很多好吃的」", "yos419_057.ogg", "朝武_リビングd", "bgm05.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "20"}, "CHAPTER 5-3", null, null], [3793, "将臣", "「我觉得可以」", null, "朝武_リビングd", "bgm05.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "20"}, "CHAPTER 5-3", null, null], [3794, "将臣", "「啊，但是芦花姐可能也要送点吃的过来」", null, "朝武_リビングd", "bgm05.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "20"}, "CHAPTER 5-3", null, null], [3795, "芳乃", "「马庭姐也要送东西？……那要不我还是别带了吧……可、可是」", "yos419_058.ogg", "朝武_リビングd", "bgm05.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "12"}, "CHAPTER 5-3", null, null], [3796, "芳乃", "「我也想送谢礼给她，可带点什么比较好呢？」", "yos419_059.ogg", "朝武_リビングd", "bgm05.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "09"}, "CHAPTER 5-3", null, null], [3797, "茉子", "「反正是派对，就算带的东西跟别人重了也没事的吧」", "mak419_052.ogg", "朝武_リビングd", "bgm05.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-3", null, null], [3798, "茉子", "「派对的乐趣之一不就是带很多零食过去吃吗」", "mak419_053.ogg", "朝武_リビングd", "bgm05.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "25"}, "CHAPTER 5-3", null, null], [3799, "芳乃", "「大、大家一起带零食……～～～～说得没错！」", "yos419_060.ogg", "朝武_リビングd", "bgm05.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "03"}, "CHAPTER 5-3", null, null], [3800, "芳乃", "「我觉得这样会很有意思！」", "yos419_061.ogg", "朝武_リビングd", "bgm05.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "24"}, "CHAPTER 5-3", null, null], [3801, "芳乃", "「那我这就去找找看应该带些什么……啊，是不是去买一点比较好！」", "yos419_062.ogg", "朝武_リビングd", "bgm05.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "03"}, "CHAPTER 5-3", null, null], [3802, "", "看到朝武高兴成这样，我心里也很舒畅。", null, "朝武_リビングd", "bgm05.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "03"}, "CHAPTER 5-3", null, null], [3803, "将臣", "「感谢安晴叔叔的理解，这样一来睡衣派对肯定能办得非常开心」", null, "朝武_リビングd", "bgm05.opus", {"char": "安晴", "file": "安晴.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-3", null, null], [3804, "安晴", "「哈哈，我也希望自己的女儿偶尔能像普通人一样开开心心玩一场嘛」", "yas419_010.ogg", "朝武_リビングd", "bgm05.opus", {"char": "安晴", "file": "安晴.stand", "dress": "私服", "face": "13"}, "CHAPTER 5-3", null, null], [3805, "茉子", "「不过，如果芳乃大人要中途回家的话，我也跟您一起回来吧」", "mak419_054.ogg", "朝武_リビングd", "bgm05.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "47"}, "CHAPTER 5-3", null, null], [3806, "芳乃", "「你在说什么呢，茉子！这样很失礼的吧，你刚才还说我呢」", "yos419_064.ogg", "朝武_リビングd", "bgm05.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "28"}, "CHAPTER 5-3", null, null], [3807, "芳乃", "「你就留下过夜吧。但是，我走了之后大家都玩了什么，你第二天要跟我好好讲讲哦」", "yos419_065.ogg", "朝武_リビングd", "bgm05.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "03"}, "CHAPTER 5-3", null, null], [3808, "茉子", "「嗯，这个您放心」", "mak419_055.ogg", "朝武_リビングd", "bgm05.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "27"}, "CHAPTER 5-3", null, null], [3809, "", "朝武自己大概也是很想留下过夜的。", null, "朝武_リビングd", "bgm05.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "24"}, "CHAPTER 5-3", null, null], [3810, "将臣", "「对了，小雨呢？我都忘记问你了」", null, "朝武_リビングd", "bgm05.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-3", null, null], [3811, "丛雨", "「毕竟还有人看不见本座，总不能跑去从头玩到尾吧」", "mur419_015.ogg", "朝武_リビングd", "bgm05.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "19"}, "CHAPTER 5-3", null, null], [3812, "丛雨", "「不过，稍微露个脸还是可以的」", "mur419_016.ogg", "朝武_リビングd", "bgm05.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "18"}, "CHAPTER 5-3", null, null], [3813, "将臣", "「那就先暂定所有人参加，我去跟蕾娜说一声」", null, "朝武_リビングd", "bgm05.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "18"}, "CHAPTER 5-3", null, null], [3814, "", "当天晚上，我估摸着蕾娜差不多忙完的时候给她打了个电话。", null, "朝武_自室d", "bgm05.opus", null, "CHAPTER 5-3", null, null], [3815, "蕾娜", "『哇哦！大家都愿意来吗？』", "len419_108.ogg", "朝武_自室d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 5-3", null, null], [3816, "蕾娜", "『嘿嘿，没想到芳乃高兴成那样』", "len419_109.ogg", "朝武_自室d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "28"}, "CHAPTER 5-3", null, null], [3817, "将臣", "「哈哈，可惜的是她不能留下过夜」", null, "朝武_自室d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "28"}, "CHAPTER 5-3", null, null], [3818, "蕾娜", "『既然大家都要来，那我也得好好露一手，做很多好吃的才行啊』", "len419_110.ogg", "朝武_自室d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "19"}, "CHAPTER 5-3", null, null], [3819, "", "突然，我感觉脊背一凉。", null, "朝武_自室d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "19"}, "CHAPTER 5-3", null, null], [3820, "将臣", "「…………啊？」", null, "朝武_自室d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "19"}, "CHAPTER 5-3", null, null], [3821, "蕾娜", "『将～臣，你是不是不相信我的手艺？』", "len419_111.ogg", "朝武_自室d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 5-3", null, null], [3822, "将臣", "「不是，那个……真的没问题吗？」", null, "朝武_自室d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 5-3", null, null], [3823, "蕾娜", "『我会跟厨师长好好商量下，选一些日本人喜欢吃的食材，你真的不用担心的』", "len419_112.ogg", "朝武_自室d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27"}, "CHAPTER 5-3", null, null], [3824, "蕾娜", "『而且……我还希望你吃了我做的料理之后，能多夸夸我呢』", "len419_113.ogg", "朝武_自室d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27"}, "CHAPTER 5-3", null, null], [3825, "将臣", "「呃……是、是吗」", null, "朝武_自室d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27"}, "CHAPTER 5-3", null, null], [3826, "将臣", "「那我就等着吃好吃的了！」", null, "朝武_自室d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27"}, "CHAPTER 5-3", null, null], [3827, "蕾娜", "『嗯，我都有点等不及了！』", "len419_114.ogg", "朝武_自室d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "19"}, "CHAPTER 5-3", null, null], [3828, "将臣", "「那晚安了，蕾娜」", null, "朝武_自室d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "19"}, "CHAPTER 5-3", null, null], [3829, "蕾娜", "『晚安，将臣……Ｍｕａ～』", "len419_115.ogg", "朝武_自室d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "26"}, "CHAPTER 5-3", null, null], [3830, "", "挂电话前的那一声，难道是飞吻？", null, "朝武_自室d", "bgm54.opus", null, "CHAPTER 5-3", null, null], [3831, "", "外国人还是不一样啊。", null, "朝武_自室d", "bgm54.opus", null, "CHAPTER 5-3", null, null], [3832, "", "我突然发现自己正盯着手机咧嘴傻笑。真希望明天快点来。", null, "朝武_自室d", "bgm54.opus", null, "CHAPTER 5-3", null, null], [3833, "丛雨", "「能跟你说点事吗，主人」", "mur419_017.ogg", "朝武_自室d", "bgm54.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-3", null, null], [3834, "将臣", "「哇啊，小雨？……难道我们说话你听见了？」", null, "朝武_自室d", "bgm54.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-3", null, null], [3835, "丛雨", "「本座可是估计你该打完电话了才出来的」", "mur419_018.ogg", "朝武_自室d", "bgm54.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "31"}, "CHAPTER 5-3", null, null], [3836, "丛雨", "「只是没想到，你打完电话之后依然在那一个人傻笑」", "mur419_019.ogg", "朝武_自室d", "bgm54.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "30"}, "CHAPTER 5-3", null, null], [3837, "", "傻笑的场面竟然被人看见了。", null, "朝武_自室d", "bgm54.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "30"}, "CHAPTER 5-3", null, null], [3838, "丛雨", "「这也没办法，毕竟本座无法敲门，你就原谅本座吧」", "mur419_020.ogg", "朝武_自室d", "bgm54.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "31"}, "CHAPTER 5-3", null, null], [3839, "将臣", "「好吧，那你是要跟我说什么呢？」", null, "朝武_自室d", "bgm54.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "31"}, "CHAPTER 5-3", null, null], [3840, "丛雨", "「为慎重起见，本座先确认一下」", "mur419_021.ogg", "朝武_自室d", "bgm54.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "17"}, "CHAPTER 5-3", null, null], [3841, "丛雨", "「主人，你今早应该是在自己房间醒过来的吧？」", "mur419_022.ogg", "朝武_自室d", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "24"}, "CHAPTER 5-3", null, null], [3842, "将臣", "「嗯，但我也并没有做什么跟平常不一样的事」", null, "朝武_自室d", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "10"}, "CHAPTER 5-3", null, null], [3843, "将臣", "「也许不一定是每天都会被吸引过去……不过也对」", null, "朝武_自室d", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "10"}, "CHAPTER 5-3", null, null], [3844, "将臣", "「要过夜的话，大家就有可能看到我像梦游病人一样到处乱跑」", null, "朝武_自室d", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "10"}, "CHAPTER 5-3", null, null], [3845, "", "我也不知道自己是怎么梦游的，毕竟在那期间我的大脑还在睡眠。", null, "朝武_自室d", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "10"}, "CHAPTER 5-3", null, null], [3846, "丛雨", "「说不定，你们能看见的记忆仅限于跟蕾娜有关的部分」", "mur419_023.ogg", "朝武_自室d", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "11"}, "CHAPTER 5-3", null, null], [3847, "丛雨", "「有可能上一次看完之后就没有了」", "mur419_024.ogg", "朝武_自室d", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "39"}, "CHAPTER 5-3", null, null], [3848, "将臣", "「原来如此，确实有这种可能」", null, "朝武_自室d", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "39"}, "CHAPTER 5-3", null, null], [3849, "", "我既觉得有点遗憾，同时也松了一口气。这样一来就不用担心梦境的风险了。", null, "朝武_自室d", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "11"}, "CHAPTER 5-3", null, null], [3850, "", "虽然现在一切都只是猜测。", null, "朝武_自室d", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "11"}, "CHAPTER 5-3", null, null], [3851, "丛雨", "「还是得先观察一阵子，否则也不好判断」", "mur419_025.ogg", "朝武_自室d", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "35"}, "CHAPTER 5-3", null, null], [3852, "丛雨", "「为慎重起见，本座会彻夜守在你们身边的，应该不会有问题」", "mur419_026.ogg", "朝武_自室d", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-3", null, null], [3853, "将臣", "「嗯，谢谢你，给你添麻烦了」", null, "朝武_自室d", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-3", null, null], [3854, "丛雨", "「哪里的话，本座早就习惯了」", "mur419_027.ogg", "朝武_自室d", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "18"}, "CHAPTER 5-3", null, null], [3855, "", "小雨微微一笑，遁去了身形。", null, "朝武_自室d", "bgm39.opus", null, "CHAPTER 5-3", null, null], [3856, "", "原来小雨一直在默默守护着我们。", null, "朝武_自室d", "bgm39.opus", null, "CHAPTER 5-3", null, null], [3857, "", "所以当我被吸引到蕾娜房间去的时候，朝武和常陆才能立刻追上来。", null, "朝武_自室d", "bgm39.opus", null, "CHAPTER 5-3", null, null], [3858, "", "……平时添了那么多麻烦，睡衣派对一定要让大家玩得开心才行。", null, "朝武_自室d", "bgm39.opus", null, "CHAPTER 5-3", null, null], [3859, "", "我默默地在心里下定了决心。", null, "朝武_自室d", "bgm39.opus", null, "CHAPTER 5-3", null, null], [3860, "蕾娜", "「哇哦，将臣！」", "len420_001.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "02"}, "CHAPTER 5-4", null, null], [3861, "将臣", "「啊，蕾娜……哇啊！？」", null, "旅館_旅館前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "19"}, "CHAPTER 5-4", null, null], [3862, "", "第二天，我刚来到志那都庄，蕾娜就抱了上来。", null, "旅館_旅館前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "19"}, "CHAPTER 5-4", null, null], [3863, "蕾娜", "「今天你竟然一大早就来了，我好开心！」", "len420_002.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "27"}, "CHAPTER 5-4", null, null], [3864, "将臣", "「呃、嗯，毕竟昨天约好了……」", null, "旅館_旅館前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "27"}, "CHAPTER 5-4", null, null], [3865, "", "那什么，我也可以抱住她吗？", null, "旅館_旅館前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "27"}, "CHAPTER 5-4", null, null], [3866, "", "哎，我在犹豫什么呢，昨天都说了要习惯的。", null, "旅館_旅館前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "27"}, "CHAPTER 5-4", null, null], [3867, "蕾娜", "「呀啊！？将、将臣？」", "len420_003.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "07h"}, "CHAPTER 5-4", null, null], [3868, "将臣", "「早上好，蕾娜……嗯？」", null, "旅館_旅館前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "07h"}, "CHAPTER 5-4", null, null], [3869, "", "我鼓起勇气抱住她之后，她的表情变得有些奇怪。", null, "旅館_旅館前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "13h"}, "CHAPTER 5-4", null, null], [3870, "", "不仅满脸通红，看上去好像还有点惊慌失措。", null, "旅館_旅館前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "13h"}, "CHAPTER 5-4", null, null], [3871, "将臣", "「啊、哎？抱歉，你不喜欢这样吗？」", null, "旅館_旅館前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "13h"}, "CHAPTER 5-4", null, null], [3872, "蕾娜", "「不、不、不是！不是不喜欢……我就是没想到，你也会抱过来」", "len420_004.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "04h"}, "CHAPTER 5-4", null, null], [3873, "蕾娜", "「所以吓了我一跳……」", "len420_005.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "23h"}, "CHAPTER 5-4", null, null], [3874, "", "说罢，她抱住我的手臂比刚才更加用力了。", null, "旅館_旅館前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "23h"}, "CHAPTER 5-4", null, null], [3875, "", "这时我才明白，原来她最开始的拥抱是拿捏过分寸的。", null, "旅館_旅館前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "23h"}, "CHAPTER 5-4", null, null], [3876, "蕾娜", "「……我不是不喜欢这样」", "len420_006.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "19h"}, "CHAPTER 5-4", null, null], [3877, "蕾娜", "「你愿意抱上来……我哪有不喜欢的道理」", "len420_007.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "27h"}, "CHAPTER 5-4", null, null], [3878, "将臣", "「呃……嗯，那就好」", null, "旅館_旅館前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "27h"}, "CHAPTER 5-4", null, null], [3879, "", "嗯？不过……打招呼时的拥抱，不是轻轻抱一下就可以松手了吗？", null, "旅館_旅館前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "27h"}, "CHAPTER 5-4", null, null], [3880, "", "但我们却一直这样抱着。由于我不习惯，也不知道应该什么时候松手。", null, "旅館_旅館前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "27h"}, "CHAPTER 5-4", null, null], [3881, "蕾娜", "「将臣……」", "len420_008.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "19h"}, "CHAPTER 5-4", null, null], [3882, "将臣", "「呃……蕾娜？」", null, "旅館_旅館前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "19h"}, "CHAPTER 5-4", null, null], [3883, "芳乃", "「那个，我们好像变成了电灯泡」", "yos420_001.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "19h"}, "CHAPTER 5-4", null, null], [3884, "蕾娜", "「……哎？」", "len420_009.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "20"}, "CHAPTER 5-4", null, null], [3885, "将臣", "「等……等等！这、这只是国际交流而已」", null, "旅館_旅館前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "20"}, "CHAPTER 5-4", null, null], [3886, "茉子", "「哈哈，如果没人打扰你们，那你们的国际交流肯定会更有激情」", "mak420_001.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "20"}, "CHAPTER 5-4", null, null], [3887, "将臣", "「你、你说什么呢。不是你想的那样啊……」", null, "旅館_旅館前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "20"}, "CHAPTER 5-4", null, null], [3888, "蕾娜", "「就、就是呀，什么叫更有激情……真是的，说出来也不害臊！是吧，将臣」", "len420_010.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "28h"}, "CHAPTER 5-4", null, null], [3889, "将臣", "「好疼、好疼！你干嘛拍我后背啊」", null, "旅館_旅館前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "28h"}, "CHAPTER 5-4", null, null], [3890, "将臣", "「蕾娜，你真的知道常陆说的是什么意思吗？」", null, "旅館_旅館前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "28h"}, "CHAPTER 5-4", null, null], [3891, "蕾娜", "「嗨，我当然知道啦！我这就来给你示范一下」", "len420_011.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "25"}, "CHAPTER 5-4", null, null], [3892, "将臣", "「示、示范……蕾娜！？」", null, "旅館_旅館前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "25"}, "CHAPTER 5-4", null, null], [3893, "蕾娜", "「芳乃……」", "len420_012.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-4", null, null], [3894, "芳乃", "「哎？怎、怎么了……啊！？」", "yos420_002.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "19"}, "CHAPTER 5-4", null, null], [3895, "", "蕾娜给朝武也来了个大大的拥抱。", null, "旅館_旅館前a", "bgm44.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "19"}, "CHAPTER 5-4", null, null], [3896, "蕾娜", "「早上好，芳乃！你愿意参加派对，我很开心」", "len420_013.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "19"}, "CHAPTER 5-4", null, null], [3897, "芳乃", "「啊、嗯！感谢你的盛情邀请……」", "yos420_003.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "30"}, "CHAPTER 5-4", null, null], [3898, "芳乃", "「（本来还特意准备了问候语呢，没想到这……这真的太震撼了」", "yos420_004.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "07"}, "CHAPTER 5-4", null, null], [3899, "芳乃", "「（这就是世界之大？）」", "yos420_005.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "34"}, "CHAPTER 5-4", null, null], [3900, "蕾娜", "「还有茉子，感谢你的参加！」", "len420_014.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "24"}, "CHAPTER 5-4", null, null], [3901, "茉子", "「不客气，你愿意邀请我，是我的荣幸……唔！？」", "mak420_002.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "33"}, "CHAPTER 5-4", null, null], [3902, "茉子", "「（我本来对自己还挺有信心的，但是这酥软的弹性……完全不是一个级别的啊！」", "mak420_003.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "33"}, "CHAPTER 5-4", null, null], [3903, "茉子", "「（这就是世界之大）」", "mak420_004.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "11"}, "CHAPTER 5-4", null, null], [3904, "", "这时，廉太郎和小春也带着芦花姐一起过来了。", null, "旅館_旅館前a", "bgm44.opus", null, "CHAPTER 5-4", null, null], [3905, "小春", "「啊，哥哥，你们已经到了啊！」", "koh420_001.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "小春", "file": "小春.stand", "dress": "私服", "face": "02"}, "CHAPTER 5-4", null, null], [3906, "芦花", "「这是之前说好的点心，快拿着吧」", "rok420_001.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "17"}, "CHAPTER 5-4", null, null], [3907, "蕾娜", "「哇啊！小春，芦花，我的感激之情如滔滔江水，雷鸣不绝！」", "len420_015.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "02"}, "CHAPTER 5-4", null, null], [3908, "小春", "「喔唔！我只是帮姐姐拿了点东西而已啦」", "koh420_002.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "小春", "file": "小春.stand", "dress": "私服", "face": "26"}, "CHAPTER 5-4", null, null], [3909, "小春", "「（这、这触感跟以前体验过的完全不同！）」", "koh420_003.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "小春", "file": "小春.stand", "dress": "私服", "face": "07"}, "CHAPTER 5-4", null, null], [3910, "芦花", "「喔，耶！不用客气，蕾娜」", "rok420_002.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "17"}, "CHAPTER 5-4", null, null], [3911, "芦花", "「（我的天，这哪个男生顶得住啊，连我都想把脸埋进去了」", "rok420_003.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "03"}, "CHAPTER 5-4", null, null], [3912, "", "蕾娜一个接一个地和大家拥抱。这确实挺激烈的。", null, "旅館_旅館前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "02"}, "CHAPTER 5-4", null, null], [3913, "芳乃", "「啊……啊……感觉心脏都要跳出来了」", "yos420_006.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "29"}, "CHAPTER 5-4", null, null], [3914, "茉子", "「是啊，蕾娜明明是同性……可我感觉自己的心已经彻底被她俘获了，我的意思是肉体方面的」", "mak420_005.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "28"}, "CHAPTER 5-4", null, null], [3915, "将臣", "「别，等等，你是说真的？」", null, "旅館_旅館前a", "bgm44.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "29"}, "CHAPTER 5-4", null, null], [3916, "", "不知为何，我突然很慌。", null, "旅館_旅館前a", "bgm44.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "29"}, "CHAPTER 5-4", null, null], [3917, "蕾娜", "「还有廉太郎，也谢谢你啦！」", "len420_016.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "25"}, "CHAPTER 5-4", null, null], [3918, "廉太郎", "「哎，还……还有我！？」", "ren420_001.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "私服", "face": "04h"}, "CHAPTER 5-4", null, null], [3919, "", "不、不是吧！？", null, "旅館_旅館前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "25"}, "CHAPTER 5-4", null, null], [3920, "", "然而，蕾娜仅仅只是跟廉太郎握了握手。", null, "旅館_旅館前a", "bgm44.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "私服", "face": "04h"}, "CHAPTER 5-4", null, null], [3921, "廉太郎", "「啊、啊，吓死我了，哈哈……」", "ren420_002.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "私服", "face": "22"}, "CHAPTER 5-4", null, null], [3922, "心子", "「大家都到齐了吧」", "mot420_001.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "01"}, "CHAPTER 5-4", null, null], [3923, "蕾娜", "「掌柜的！」", "len420_017.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-4", null, null], [3924, "蕾娜", "「感谢您允许我们开睡衣派对，真的非常感谢！」", "len420_018.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "02"}, "CHAPTER 5-4", null, null], [3925, "心子", "「……」", "mot420_002.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "05"}, "CHAPTER 5-4", null, null], [3926, "蕾娜", "「掌柜的？」", "len420_019.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "34"}, "CHAPTER 5-4", null, null], [3927, "心子", "「这……这就是世界之大？」", "mot420_003.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "07"}, "CHAPTER 5-4", null, null], [3928, "", "哎？", null, "旅館_旅館前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "34"}, "CHAPTER 5-4", null, null], [3929, "心子", "「没、没什么，欢迎各位来我们旅馆做客」", "mot420_004.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "02"}, "CHAPTER 5-4", null, null], [3930, "心子", "「希望各位今天都玩得开心，玩得尽兴」", "mot420_005.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "03"}, "CHAPTER 5-4", null, null], [3931, "芳乃", "「谢谢，今天要给你们添麻烦了」", "yos420_007.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "20"}, "CHAPTER 5-4", null, null], [3932, "心子", "「巫女大人，您客气了，今天您可以随意使用我们这里的大浴堂」", "mot420_006.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "01"}, "CHAPTER 5-4", null, null], [3933, "心子", "「请各位好好放松身心，加深友谊吧」", "mot420_007.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "03"}, "CHAPTER 5-4", null, null], [3934, "", "朝武家的浴池虽然也相当大，但是跟志那都庄的大浴堂比起来就是小巫见大巫了。", null, "旅館_旅館前a", "bgm44.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "02"}, "CHAPTER 5-4", null, null], [3935, "心子", "「不过，请允许我再啰嗦一句……虽然年轻人聚在一起，想要安静很困难」", "mot420_008.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "09"}, "CHAPTER 5-4", null, null], [3936, "心子", "「但是为了不影响其他住客，请各位一定不要在深夜喧闹」", "mot420_009.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "07"}, "CHAPTER 5-4", null, null], [3937, "蕾娜", "「好的！我明白」", "len420_020.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-4", null, null], [3938, "心子", "「嗯，列支敦瑙尔小姐应该是非常清楚的」", "mot420_010.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "02"}, "CHAPTER 5-4", null, null], [3939, "心子", "「还请各位听从她的安排」", "mot420_011.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "01"}, "CHAPTER 5-4", null, null], [3940, "小春", "「好的」", "koh420_004.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "小春", "file": "小春.stand", "dress": "私服", "face": "02"}, "CHAPTER 5-4", null, null], [3941, "茉子", "「我们会听她安排的」", "mak420_006.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "27"}, "CHAPTER 5-4", null, null], [3942, "", "我们都不希望给志那都庄添麻烦。", null, "旅館_旅館前a", "bgm44.opus", null, "CHAPTER 5-4", null, null], [3943, "", "不过猪谷阿姨刚才的言行很像学校的老师，看上去还挺有趣的。", null, "旅館_旅館前a", "bgm44.opus", null, "CHAPTER 5-4", null, null], [3944, "廉太郎", "「这气氛搞得跟修学旅行一样」", "ren420_003.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-4", null, null], [3945, "将臣", "「哈哈，确实……不过，志那都庄对你来说就跟自己家一样吧？」", null, "旅館_旅館前a", "bgm44.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-4", null, null], [3946, "廉太郎", "「话是这么说，但这确实有种修学旅行的感觉啊」", "ren420_004.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "私服", "face": "25"}, "CHAPTER 5-4", null, null], [3947, "廉太郎", "「……而且」", "ren420_005.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "私服", "face": "06"}, "CHAPTER 5-4", null, null], [3948, "", "廉太郎突然凑到我耳边来。", null, "旅館_旅館前a", "bgm44.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "私服", "face": "06"}, "CHAPTER 5-4", null, null], [3949, "廉太郎", "「蕾娜应该是对你有意思吧？」", "ren420_006.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "私服", "face": "28"}, "CHAPTER 5-4", null, null], [3950, "将臣", "「……是、是吗？」", null, "旅館_旅館前a", "bgm44.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "私服", "face": "28"}, "CHAPTER 5-4", null, null], [3951, "廉太郎", "「肯定啊，她刚才只跟你一个男的拥抱了吧？」", "ren420_007.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "私服", "face": "29"}, "CHAPTER 5-4", null, null], [3952, "将臣", "「你看见了啊？」", null, "旅館_旅館前a", "bgm44.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "私服", "face": "29"}, "CHAPTER 5-4", null, null], [3953, "廉太郎", "「是你们太显眼了好吗。大老远就能看出来你们关系不一般」", "ren420_008.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-4", null, null], [3954, "", "要真是这样，那我当然高兴。", null, "旅館_旅館前a", "bgm44.opus", null, "CHAPTER 5-4", null, null], [3955, "", "对我来说，蕾娜她……", null, "旅館_旅館前a", "bgm44.opus", null, "CHAPTER 5-4", null, null], [3956, "蕾娜", "「那就开始吧，将臣。大家快进来，我带你们去我房间！」", "len420_021.ogg", "旅館_旅館前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "24"}, "CHAPTER 5-4", null, null], [3957, "", "进了蕾娜的房间之后，我们首先打开了芦花姐送的点心。", null, "旅館_レナの部屋a", "bgm04.opus", null, "CHAPTER 5-4", null, null], [3958, "芳乃", "「小泡芙！小泡芙金字塔！」", "yos420_008.ogg", "旅館_レナの部屋a", "bgm04.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "17"}, "CHAPTER 5-4", null, null], [3959, "小春", "「这就是姐姐准备的点心」", "koh420_005.ogg", "旅館_レナの部屋a", "bgm04.opus", {"char": "小春", "file": "小春.stand", "dress": "私服", "face": "02"}, "CHAPTER 5-4", null, null], [3960, "蕾娜", "「哇，将臣你快看！好壮观啊」", "len420_022.ogg", "旅館_レナの部屋a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "24"}, "CHAPTER 5-4", null, null], [3961, "将臣", "「确实，这有点厉害啊！这是芦花姐她爸做的吗？」", null, "旅館_レナの部屋a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "24"}, "CHAPTER 5-4", null, null], [3962, "小春", "「不是，这是姐姐自己做的……」", "koh420_006.ogg", "旅館_レナの部屋a", "bgm04.opus", {"char": "小春", "file": "小春.stand", "dress": "私服", "face": "26"}, "CHAPTER 5-4", null, null], [3963, "蕾娜", "「哇哦，真希望芦花也能来参加啊」", "len420_023.ogg", "旅館_レナの部屋a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "29"}, "CHAPTER 5-4", null, null], [3964, "将臣", "「她还有工作，没办法啦」", null, "旅館_レナの部屋a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "29"}, "CHAPTER 5-4", null, null], [3965, "蕾娜", "「可是，我真没想到她会送来这么丰盛的甜点……这可让我怎么报答她呀」", "len420_024.ogg", "旅館_レナの部屋a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "12"}, "CHAPTER 5-4", null, null], [3966, "将臣", "「以后咱们多去她店里买点东西不就行了嘛」", null, "旅館_レナの部屋a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "12"}, "CHAPTER 5-4", null, null], [3967, "蕾娜", "「你这主意不错！到时候我要点一大堆吃的！」", "len420_025.ogg", "旅館_レナの部屋a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "19"}, "CHAPTER 5-4", null, null], [3968, "小春", "「呃、嗯……那什么……」", "koh420_007.ogg", "旅館_レナの部屋a", "bgm04.opus", {"char": "小春", "file": "小春.stand", "dress": "私服", "face": "15"}, "CHAPTER 5-4", null, null], [3969, "芳乃", "「虽然我也买了很多零食过来」", "yos420_009.ogg", "旅館_レナの部屋a", "bgm04.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "12"}, "CHAPTER 5-4", null, null], [3970, "芳乃", "「但是完全比不上她这个」", "yos420_010.ogg", "旅館_レナの部屋a", "bgm04.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "31"}, "CHAPTER 5-4", null, null], [3971, "蕾娜", "「没事啦，这些小泡芙，还有芳乃带来的零食，我都想吃！」", "len420_026.ogg", "旅館_レナの部屋a", "bgm04.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "31"}, "CHAPTER 5-4", null, null], [3972, "芳乃", "「呃，是吗，既然如此，那我就……先尝尝小泡芙？……不，不行！」", "yos420_011.ogg", "旅館_レナの部屋a", "bgm04.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "06"}, "CHAPTER 5-4", null, null], [3973, "芳乃", "「这太不成体统了，忘了我刚才说的这些吧」", "yos420_012.ogg", "旅館_レナの部屋a", "bgm04.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "23"}, "CHAPTER 5-4", null, null], [3974, "茉子", "「哈哈，可是芳乃大人，人家难得送了这么多，要是吃不完可就太失礼了」", "mak420_007.ogg", "旅館_レナの部屋a", "bgm04.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "41"}, "CHAPTER 5-4", null, null], [3975, "蕾娜", "「就是呀！俗话说得好，跟江户人不讲客气！」", "len420_027.ogg", "旅館_レナの部屋a", "bgm04.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-4", null, null], [3976, "芳乃", "「是、是吗？确实……吃不完的话，是挺失礼的」", "yos420_013.ogg", "旅館_レナの部屋a", "bgm04.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "24"}, "CHAPTER 5-4", null, null], [3977, "小春", "「啊，巫女大人，先等等！有些事情要先说明一下……」", "koh420_008.ogg", "旅館_レナの部屋a", "bgm04.opus", {"char": "小春", "file": "小春.stand", "dress": "私服", "face": "08"}, "CHAPTER 5-4", null, null], [3978, "廉太郎", "「最上面这个就先归我了！」", "ren420_009.ogg", "旅館_レナの部屋a", "bgm04.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "私服", "face": "02"}, "CHAPTER 5-4", null, null], [3979, "小春", "「啊」", "koh420_009.ogg", "旅館_レナの部屋a", "bgm04.opus", {"char": "小春", "file": "小春.stand", "dress": "私服", "face": "06"}, "CHAPTER 5-4", null, null], [3980, "", "一个不留神，廉太郎就拿走了最顶上的那一块小泡芙，放进了自己嘴里。", null, "旅館_レナの部屋a", "bgm04.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "私服", "face": "25"}, "CHAPTER 5-4", null, null], [3981, "", "刚入口，他就倒在了榻榻米上。", null, "旅館_レナの部屋a", "bgm04.opus", null, "CHAPTER 5-4", null, null], [3982, "廉太郎", "「这、这是什么啊！……好冲啊，好冲鼻子啊！」", "ren420_010.ogg", "旅館_レナの部屋a", "bgm04.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "私服", "face": "10"}, "CHAPTER 5-4", null, null], [3983, "芳乃", "「哎？……哎？这是什么情况？」", "yos420_014.ogg", "旅館_レナの部屋a", "bgm04.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "34"}, "CHAPTER 5-4", null, null], [3984, "将臣", "「……这是怎么了？虽然这种情况好像有点眼熟」", null, "旅館_レナの部屋a", "bgm04.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "34"}, "CHAPTER 5-4", null, null], [3985, "小春", "「啊、哈哈……其实，之前我们做芥末芭菲时，剩了一大堆芥末粉」", "koh420_010.ogg", "旅館_レナの部屋a", "bgm04.opus", {"char": "小春", "file": "小春.stand", "dress": "私服", "face": "30"}, "CHAPTER 5-4", null, null], [3986, "小春", "「所以就用芥末粉做了很多聚会游戏惩罚用的小泡芙」", "koh420_011.ogg", "旅館_レナの部屋a", "bgm04.opus", {"char": "小春", "file": "小春.stand", "dress": "私服", "face": "16"}, "CHAPTER 5-4", null, null], [3987, "蕾娜", "「是、是吗……是用之前的芥末粉做的吗？」", "len420_028.ogg", "旅館_レナの部屋a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "25"}, "CHAPTER 5-4", null, null], [3988, "芳乃", "「我的小泡芙…………」", "yos420_015.ogg", "旅館_レナの部屋a", "bgm04.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "13"}, "CHAPTER 5-4", null, null], [3989, "", "能让生不如死的食材远远不止甘草。", null, "旅館_レナの部屋a", "bgm04.opus", null, "CHAPTER 5-4", null, null], [3990, "小春", "「也就是说，只要你们运气不好，就会变成这样」", "koh420_012.ogg", "旅館_レナの部屋a", "bgm04.opus", {"char": "小春", "file": "小春.stand", "dress": "私服", "face": "26"}, "CHAPTER 5-4", null, null], [3991, "廉太郎", "「你、你啊，我吃之前你怎么不说清楚！」", "ren420_011.ogg", "旅館_レナの部屋a", "bgm04.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "私服", "face": "09"}, "CHAPTER 5-4", null, null], [3992, "小春", "「我刚准备说的啊，而且你跟我一起去取甜点的时候，姐姐不是跟我们说了吗」", "koh420_013.ogg", "旅館_レナの部屋a", "bgm04.opus", {"char": "小春", "file": "小春.stand", "dress": "私服", "face": "13"}, "CHAPTER 5-4", null, null], [3993, "小春", "「你肯定压根没听吧？」", "koh420_014.ogg", "旅館_レナの部屋a", "bgm04.opus", {"char": "小春", "file": "小春.stand", "dress": "私服", "face": "33"}, "CHAPTER 5-4", null, null], [3994, "茉子", "「噗，还是马庭姐会玩。聚会时吃什么最有意思，她心里再清楚不过了」", "mak420_008.ogg", "旅館_レナの部屋a", "bgm04.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "27"}, "CHAPTER 5-4", null, null], [3995, "", "常陆不知从哪拿出了一副扑克牌，在手中铺成了扇形。", null, "旅館_レナの部屋a", "bgm04.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-4", null, null], [3996, "茉子", "「我们来玩抽鬼牌吧，谁输了，谁就先吃一粒，怎么样？」", "mak420_009.ogg", "旅館_レナの部屋a", "bgm04.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-4", null, null], [3997, "将臣", "「我觉得可以，应该很有意思」", null, "旅館_レナの部屋a", "bgm04.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-4", null, null], [3998, "芳乃", "「只要运气好，就能吃到普通的小泡芙了吧？那我会加油的，为了吃到小泡芙」", "yos420_016.ogg", "旅館_レナの部屋a", "bgm04.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "14"}, "CHAPTER 5-4", null, null], [3999, "蕾娜", "「茉子？……抽鬼牌是什么？」", "len420_029.ogg", "旅館_レナの部屋a", "bgm04.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-4", null, null], [4000, "茉子", "「啊，这个游戏国外应该也有……但我忘记在国外是怎么说的了」", "mak420_010.ogg", "旅館_レナの部屋a", "bgm04.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "20"}, "CHAPTER 5-4", null, null], [4001, "茉子", "「要不就换成你会玩的游戏？」", "mak420_011.ogg", "旅館_レナの部屋a", "bgm04.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-4", null, null], [4002, "蕾娜", "「不，没事的！我想试试日本的纸牌游戏」", "len420_030.ogg", "旅館_レナの部屋a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-4", null, null], [4003, "", "蕾娜在我身边坐了下来。", null, "旅館_レナの部屋a", "bgm04.opus", null, "CHAPTER 5-4", null, null], [4004, "蕾娜", "「嘿嘿，而且我知道将臣肯定会教我的」", "len420_031.ogg", "旅館_レナの部屋a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "02"}, "CHAPTER 5-4", null, null], [4005, "将臣", "「嗯，没问题。你先跟我一起玩两局试试吧」", null, "旅館_レナの部屋a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "02"}, "CHAPTER 5-4", null, null], [4006, "蕾娜", "「好的！请多指教啦，将臣」", "len420_032.ogg", "旅館_レナの部屋a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "25"}, "CHAPTER 5-4", null, null], [4007, "", "我们决定让蕾娜先跟我共用一组牌，其他人则是各抽各的牌。", null, "旅館_レナの部屋a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "25"}, "CHAPTER 5-4", null, null], [4008, "茉子", "「嘿嘿，那么各位都准备好了吗？」", "mak420_012.ogg", "旅館_レナの部屋a", "bgm04.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "26"}, "CHAPTER 5-4", null, null], [4009, "茉子", "「我可是不会手下留情的！」", "mak420_013.ogg", "旅館_レナの部屋a", "bgm04.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "02"}, "CHAPTER 5-4", null, null], [4010, "", "就这样，今天的派对正式开始了。虽然没有酒，但我们喝着饮料，又唱又跳，还是十分快活。", null, "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4011, "", "小雨也在一旁享受着这样的气氛。", null, "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4012, "", "虽然她没有发出声音，但她浮在空中，脸上挂满了笑意。", null, "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4013, "芳乃", "「嗯～～甜甜的奶油入口即化，这是幸福的味道……」", "yos420_017.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4014, "蕾娜", "「哇，芳乃运气也这么好啊！泡芙真是太好吃了」", "len420_033.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4015, "芳乃", "「是的，能参加派对……我真是太幸福了……」", "yos420_018.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4016, "蕾娜", "「嘿嘿，你太夸张啦」", "len420_034.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4017, "廉太郎", "「唔啊！？怎么又吃到芥末泡芙了，我运气也太差了吧」", "ren420_012.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4018, "将臣", "「我吃到的是正常的，不过芦花姐也真是手下不留情啊，她好像用了非常多的芥末」", null, "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4019, "小春", "「廉哥，你肯定是平时作恶太多了吧」", "koh420_015.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4020, "茉子", "「平时……作恶太多…………………………唔」", "mak420_014.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4021, "蕾娜", "「啊，茉子！？你没事吧」", "len420_035.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4022, "蕾娜", "「你别客气，难受的话就多喝点饮料」", "len420_036.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4023, "茉子", "「谢谢……咦？这味道我还是第一次喝」", "mak420_015.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4024, "蕾娜", "「这是我爷爷从我们国家寄过来的越橘果汁」", "len420_037.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4025, "蕾娜", "「你不喜欢这个味道吗？」", "len420_038.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4026, "茉子", "「我是第一次喝，所以有点惊讶……不过我觉得味道还不错」", "mak420_016.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4027, "茉子", "「嗯，这个还是很好喝的」", "mak420_017.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4028, "", "看来她们国家也还是有一些味道不错的东西。", null, "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4029, "茉子", "「那么……现在开始第二局！」", "mak420_018.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4030, "廉太郎", "「好，这次我一定要吃到正常的泡芙！」", "ren420_013.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4031, "将臣", "「哎？还要玩啊？」", null, "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4032, "茉子", "「当然了，我也想尝尝正常的泡芙是什么味道的嘛」", "mak420_019.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4033, "芳乃", "「哈哈。蕾娜，咱们就给他们点颜色看看吧！」", "yos420_019.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4034, "蕾娜", "「没问题！」", "len420_039.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4035, "", "不管是输是赢，仅仅只会影响到吃泡芙的顺序而已，并不会让谁变得更倒霉。", null, "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4036, "", "但只要有了一些赌注在里面，单纯的纸牌游戏竟然也会变得这么有意思，真是不可思议。", null, "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4037, "", "不知不觉间，我感觉大家的距离越来越近了。", null, "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4038, "蕾娜", "「噗，哈哈哈」", "len420_040.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4039, "将臣", "「嗯？你怎么了，蕾娜」", null, "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4040, "蕾娜", "「今天大家都愿意过来捧场，我真的很开心」", "len420_041.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4041, "芳乃", "「这不是你邀请我们过来的嘛……这张牌，我要抽走了哦」", "yos420_020.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4042, "蕾娜", "「在欧洲，这种轰趴是很常见的啦……我要这张」", "len420_042.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4043, "蕾娜", "「哇！数字凑够了」", "len420_043.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4044, "将臣", "「确实，感觉欧美人很喜欢开轰趴……我要这个」", null, "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4045, "廉太郎", "「日本人一般就不怎么搞这种活动……嗯？啊！？」", "ren420_014.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4046, "", "廉太郎似乎是抽到鬼牌了。", null, "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4047, "茉子", "「噗，大家这样聚在一起玩，确实有点像欧美的轰趴」", "mak420_020.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4048, "蕾娜", "「是的！搬家之后，只要有人邀请你参加轰趴」", "len420_044.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4049, "蕾娜", "「那就说明当地居民已经把你当成自己人了」", "len420_045.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4050, "小春", "「是吗，听上去很有意思啊……啊！我也凑齐一组了」", "koh420_016.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4051, "蕾娜", "「所以，将臣说要开睡衣派对时……虽然吓了我一跳，但我还是非常开心的」", "len420_046.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4052, "蕾娜", "「当时我就觉得，大家终于把我当成自己人了」", "len420_047.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4053, "芳乃", "「对咱们穗织的居民来说，你早就是我们自己人了……咱、咱们是朋友嘛」", "yos420_021.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4054, "蕾娜", "「芳乃……」", "len420_048.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4055, "廉太郎", "「巫女大人都这么说了，那肯定没错了！」", "ren420_015.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4056, "茉子", "「嗯，蕾娜当然是我们的朋友」", "mak420_021.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4057, "小春", "「那个，我跟蕾娜学姐不是一个班的，也可以跟你做朋友吗？」", "koh420_017.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4058, "蕾娜", "「那当然啦！谢谢小春，谢谢大家！」", "len420_049.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4059, "蕾娜", "「今天我准备了很多料理，希望大家都能吃得饱饱的！」", "len420_050.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4060, "将臣", "「呃、嗯」", null, "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4061, "廉太郎", "「……好的」", "ren420_016.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4062, "", "除了小泡芙之外，桌子上还摆着很多其他料理，但是谁都没敢吃。", null, "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4063, "", "这时我发现，大家都在望着我。", null, "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4064, "将臣", "「哎？怎么了？」", null, "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4065, "廉太郎", "「不要逃避现实。来吧，轮到你抽牌了」", "ren420_017.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4066, "将臣", "「嗯……呃」", null, "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4067, "", "我不小心抽到了廉太郎的鬼牌。", null, "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4068, "茉子", "「有地，人家好不容易做了这么多，你就先来尝尝吧」", "mak420_022.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4069, "芳乃", "「是……是啊，这样最好」", "yos420_022.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4070, "小春", "「哥哥，打头阵的任务就交给你了」", "koh420_018.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4071, "", "大家果然是希望我先下筷子。", null, "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4072, "", "我就知道。我早就知道会这样。", null, "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4073, "蕾娜", "「将臣，其实……我也希望你能第一个尝尝，可以吗？」", "len420_051.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4074, "将臣", "「这、这个……嗯」", null, "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4075, "将臣", "「我记得这些菜你都是跟厨师长商量着做的吧？」", null, "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4076, "蕾娜", "「是的，为了避免做成黑暗料理，我做得可用心了！」", "len420_052.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4077, "", "既然如此，那我就应该检验一下她努力的成果才行。", null, "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4078, "", "而且她指名道姓让我先吃，我应该感到荣幸才对。", null, "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4079, "", "我首先夹起了一块肉丸子。毕竟是肉，应该不会有太大问题。", null, "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4080, "将臣", "「哎！我的天，这也太好吃了吧！？」", null, "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4081, "蕾娜", "「哇哦，太好了！其实，这种肉丸子在我们国家是随处可见的家常菜」", "len420_053.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4082, "将臣", "「不是吧！竟然是家常菜，这也太好吃了」", null, "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4083, "将臣", "「但是这上面浇的都是昨天的莓果酱吧？真的太好吃了，简直不敢相信用的是同一种酱料」", null, "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4084, "廉太郎", "「真、真的吗？」", "ren420_018.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4085, "将臣", "「你就狠下心尝尝看呗？那莓果酱配面包可能不太好吃，但是跟肉类真的是绝配」", null, "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4086, "将臣", "「莓果的酸味，跟肉脂混在一起特别提味」", null, "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4087, "廉太郎", "「喔……真的耶，太好吃了！虽然说番茄酱的味道可能更清爽一些」", "ren420_019.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4088, "廉太郎", "「但如果用了很多香辛料，那应该是浇莓果酱更好吃」", "ren420_020.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4089, "小春", "「是、是吗」", "koh420_019.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4090, "将臣", "「这个是炸鱼吗？这炸鱼也是外酥里嫩，感觉吃多少都吃不腻」", null, "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4091, "蕾娜", "「这不是炸鱼，是用鲱鱼做的香煎鱼排，我最喜欢吃这个了！」", "len420_054.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4092, "蕾娜", "「为了煎出这种外酥里嫩的口感，我裹了一层面粉，用很多油煎了很久」", "len420_055.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4093, "茉子", "「这味道确实不错……」", "mak420_023.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4094, "芳乃", "「嗯～～我也喜欢这个味道」", "yos420_023.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4095, "茉子", "「下次能教教我怎么做吗？」", "mak420_024.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4096, "蕾娜", "「当然了！我也希望你们能教我做日本料理」", "len420_056.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4097, "", "见我吃得津津有味，大家也都开始动筷子了。", null, "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4098, "", "今天的料理每一样都非常好吃，昨天的惨剧就像一场梦一样。", null, "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4099, "", "这说明，只要按照日本人的喜好稍稍调整一下口味，北欧料理也是非常好吃的。", null, "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4100, "蕾娜", "「……太好了，大家都觉得好吃，我就放心了」", "len420_057.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4101, "将臣", "「你别这么说，是我们之前误会你了」", null, "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4102, "芳乃", "「都怪那盒糖果，害得我们都心里有了成见」", "yos420_024.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4103, "蕾娜", "「哈哈，那盒糖果的味道比较特殊而已啦」", "len420_058.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4104, "蕾娜", "「不过，有些料理我虽然想做，但是因为没有材料，实在是做不了」", "len420_059.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4105, "将臣", "「看来料理在材料上确实会有限制」", null, "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4106, "蕾娜", "「是的，驯鹿肉实在是怎么也买不到」", "len420_060.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4107, "芳乃", "「驯鹿……你是说圣诞老人的驯鹿吗？」", "yos420_025.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4108, "小春", "「你们还吃驯鹿？」", "koh420_020.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4109, "茉子", "「说起来，圣诞老人的故乡好像就是北欧？」", "mak420_025.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4110, "蕾娜", "「是的，我们那里还有个圣诞老人村呢，去了就能坐上驯鹿雪橇」", "len420_061.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4111, "小春", "「这都能坐啊」", "koh420_021.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4112, "蕾娜", "「还能去饭店吃到驯鹿排」", "len420_062.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4113, "小春", "「你们真的吃驯鹿啊！？」", "koh420_022.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4114, "将臣", "「不管是肉还是毛皮，甚至连鹿角和骨头，都会拿来加工使用」", null, "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4115, "茉子", "「原来如此，对于蕾娜的国家来说，驯鹿应该是一种不可或缺的动物吧」", "mak420_026.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4116, "蕾娜", "「不过我们国家有很多素食主义者，不吃驯鹿的人也是非常多的」", "len420_063.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4117, "蕾娜", "「只要去了圣诞老人村，随时都可以跟圣诞老人合影，还能直接通过邮局向全世界寄礼物呢」", "len420_064.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4118, "芳乃", "「是吗……」", "yos420_026.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4119, "将臣", "「哎，听起来好梦幻啊」", null, "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4120, "芳乃", "「等等，还……还能跟圣诞老人一起合影吗？」", "yos420_027.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4121, "蕾娜", "「是的，还能拍视频呢，价格好像是４０欧元」", "len420_065.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4122, "蕾娜", "「付钱之后，他们就会给你一个二维码，直接用手机扫码就能下载视频了」", "len420_066.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4123, "廉太郎", "「这年头的圣诞老人这么先进的吗！？」", "ren420_021.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4124, "茉子", "「而且，还要４０欧元……也就是６０００日元左右吧」", "mak420_027.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4125, "茉子", "「这圣人赚起钱来真是不马虎」", "mak420_028.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4126, "将臣", "「呃、嗯……圣诞老人应该也有人家的苦衷嘛，理解万岁」", null, "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4127, "芳乃", "「就是呀，人家圣诞老人可忙了！」", "yos420_028.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4128, "茉子", "「哈哈，毕竟他每年都要给世界各地的孩子们送礼物，可能确实很忙」", "mak420_029.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4129, "芳乃", "「是啊，不过真的没想到……竟然还有圣诞老人村，去了还能见到圣诞老人……」", "yos420_029.ogg", "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4130, "将臣", "「朝武……？」", null, "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4131, "", "不是吧，难道她现在依然相信有圣诞老人？", null, "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, "sd402aa"], [4132, "蕾娜", "「哈哈，真希望有一天能带大家一起去我们村玩，然后再开一场睡衣派对」", "len420_067.ogg", "旅館_レナの部屋a", "bgm38.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "03"}, "CHAPTER 5-4", null, null], [4133, "将臣", "「是啊……」", null, "旅館_レナの部屋a", "bgm38.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "03"}, "CHAPTER 5-4", null, null], [4134, "", "我觉得这个主意非常不错。", null, "旅館_レナの部屋a", "bgm38.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "03"}, "CHAPTER 5-4", null, null], [4135, "芳乃", "「嗯，是挺想去的……」", "yos420_030.ogg", "旅館_レナの部屋a", "bgm38.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "29"}, "CHAPTER 5-4", null, null], [4136, "茉子", "「……但愿能够实现」", "mak420_030.ogg", "旅館_レナの部屋a", "bgm38.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "27"}, "CHAPTER 5-4", null, null], [4137, "", "朝武、常陆、还有小雨恐怕都不能离开穗织。", null, "旅館_レナの部屋a", "bgm38.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "29"}, "CHAPTER 5-4", null, null], [4138, "", "除非我们能解开这片土地的诅咒。", null, "旅館_レナの部屋a", "bgm38.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "29"}, "CHAPTER 5-4", null, null], [4139, "", "如果有一天……", null, "旅館_レナの部屋a", "bgm38.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "29"}, "CHAPTER 5-4", null, null], [4140, "", "我们真的解除了诅咒……那么我们的愿望，或许就能实现了。", null, "旅館_レナの部屋a", "bgm38.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "29"}, "CHAPTER 5-4", null, null], [4141, "小春", "「那、那个，如果要去的话，可不可以去趟圣诞老人村呢？」", "koh420_023.ogg", "旅館_レナの部屋a", "bgm38.opus", {"char": "小春", "file": "小春.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-4", null, null], [4142, "蕾娜", "「当然啦，本来就是顺路的，想去肯定可以去！我们村就在圣诞老人村的北边」", "len420_068.ogg", "旅館_レナの部屋a", "bgm38.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "25"}, "CHAPTER 5-4", null, null], [4143, "廉太郎", "「你都几岁了，还相信圣诞老人啊？」", "ren420_022.ogg", "旅館_レナの部屋a", "bgm38.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "私服", "face": "24"}, "CHAPTER 5-4", null, null], [4144, "芳乃", "「……哎？」", "yos420_031.ogg", "旅館_レナの部屋a", "bgm38.opus", {"char": "小春", "file": "小春.stand", "dress": "私服", "face": "13"}, "CHAPTER 5-4", null, null], [4145, "小春", "「不、不是啊，我就是想见见圣诞老人嘛」", "koh420_024.ogg", "旅館_レナの部屋a", "bgm38.opus", {"char": "小春", "file": "小春.stand", "dress": "私服", "face": "11"}, "CHAPTER 5-4", null, null], [4146, "小春", "「你不想去的话，那你就别来呗！」", "koh420_025.ogg", "旅館_レナの部屋a", "bgm38.opus", {"char": "小春", "file": "小春.stand", "dress": "私服", "face": "33"}, "CHAPTER 5-4", null, null], [4147, "廉太郎", "「那怎么行，难得去一趟北欧，怎么可能不去圣诞老人村啊」", "ren420_023.ogg", "旅館_レナの部屋a", "bgm38.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "私服", "face": "25"}, "CHAPTER 5-4", null, null], [4148, "廉太郎", "「我也想体验下驯鹿雪橇，看看它是不是真的能飞在天上」", "ren420_024.ogg", "旅館_レナの部屋a", "bgm38.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "私服", "face": "28"}, "CHAPTER 5-4", null, null], [4149, "小春", "「你在说什么啊？你怎么比我还幼稚」", "koh420_026.ogg", "旅館_レナの部屋a", "bgm38.opus", {"char": "小春", "file": "小春.stand", "dress": "私服", "face": "04"}, "CHAPTER 5-4", null, null], [4150, "蕾娜", "「噗，这个还真不好说，说不定真的能飞呢」", "len420_069.ogg", "旅館_レナの部屋a", "bgm38.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "19"}, "CHAPTER 5-4", null, null], [4151, "", "但愿有朝一日，我们能解除诅咒，然后一起去圣诞老人村旅游。", null, "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, null], [4152, "", "只是想想就觉得十分美好。", null, "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, null], [4153, "", "而且，只要我们想去，说不定就真的能去。一想到这里，内心就充满希望。", null, "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, null], [4154, "", "但愿有朝一日，这个愿望能够实现。", null, "旅館_レナの部屋a", "bgm38.opus", null, "CHAPTER 5-4", null, null], [4155, "将臣", "「呼，太爽了……」", null, "旅館_廊下d", "bgm05.opus", null, "CHAPTER 5-4", null, null], [4156, "", "闹腾了几个小时之后，我们来到了温泉浴堂。", null, "旅館_廊下d", "bgm05.opus", null, "CHAPTER 5-4", null, null], [4157, "", "廉太郎似乎早就习惯了这样的大浴池，他只泡了一会儿就出去了。", null, "旅館_廊下d", "bgm05.opus", null, "CHAPTER 5-4", null, null], [4158, "", "但是这样的机会对我来说并不多，我还是想悠闲地多泡一会儿。", null, "旅館_廊下d", "bgm05.opus", null, "CHAPTER 5-4", null, null], [4159, "", "不过，我是不是泡得太久了？", null, "旅館_廊下d", "bgm05.opus", null, "CHAPTER 5-4", null, null], [4160, "", "现在太阳已经下山，普通客人的酒席差不多要开始了。", null, "旅館_廊下d", "bgm05.opus", null, "CHAPTER 5-4", null, null], [4161, "将臣", "「接下来，我们就要安静点才行了」", null, "旅館_廊下d", "bgm05.opus", null, "CHAPTER 5-4", null, null], [4162, "将臣", "「但是毕竟这么多人，想要安静还是有点困难」", null, "旅館_廊下d", "bgm05.opus", null, "CHAPTER 5-4", null, null], [4163, "", "而且朝武再过一会儿就要回去了，也需要考虑下怎么让她玩得开心。", null, "旅館_廊下d", "bgm05.opus", null, "CHAPTER 5-4", null, null], [4164, "", "正当我思考接下来的安排时，蕾娜走了过来。", null, "旅館_廊下d", "bgm05.opus", null, "CHAPTER 5-4", null, null], [4165, "蕾娜", "「啊，将臣！原来你在这里」", "len420_070.ogg", "旅館_廊下d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "01"}, "CHAPTER 5-4", null, null], [4166, "将臣", "「咦，蕾娜，你要去哪啊？」", null, "旅館_廊下d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "01"}, "CHAPTER 5-4", null, null], [4167, "蕾娜", "「嗯？怎么啦？」", "len420_071.ogg", "旅館_廊下d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "20"}, "CHAPTER 5-4", null, null], [4168, "将臣", "「你们刚才也去泡澡了吧」", null, "旅館_廊下d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "20"}, "CHAPTER 5-4", null, null], [4169, "", "但是她穿的却并不是浴袍。", null, "旅館_廊下d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "20"}, "CHAPTER 5-4", null, null], [4170, "蕾娜", "「嗯……嘿嘿，咱们的夜晚才刚刚开始呢，将臣」", "len420_072.ogg", "旅館_廊下d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "02"}, "CHAPTER 5-4", null, null], [4171, "将臣", "「我知道啊，怎么啦？」", null, "旅館_廊下d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "02"}, "CHAPTER 5-4", null, null], [4172, "蕾娜", "「我刚才去找掌柜的借了几盘ＤＶＤ过来」", "len420_073.ogg", "旅館_廊下d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "01"}, "CHAPTER 5-4", null, null], [4173, "将臣", "「啊！ＤＶＤ，原来如此」", null, "旅館_廊下d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "01"}, "CHAPTER 5-4", null, null], [4174, "", "这是个好主意。不仅大家可以一起看，而且我们的声音也不可能比电视更大。", null, "旅館_廊下d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "01"}, "CHAPTER 5-4", null, null], [4175, "将臣", "「志那都庄还有租借ＤＶＤ的服务啊？」", null, "旅館_廊下d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "01"}, "CHAPTER 5-4", null, null], [4176, "蕾娜", "「是的，虽然租借的客人并不多……」", "len420_074.ogg", "旅館_廊下d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "23"}, "CHAPTER 5-4", null, null], [4177, "", "没办法，这种地方租借的ＤＶＤ全都是一些早就看腻了的大众电影。", null, "旅館_廊下d", "bgm05.opus", null, "CHAPTER 5-4", null, null], [4178, "", "都出来旅游了，没人会专门借这种电影来看。", null, "旅館_廊下d", "bgm05.opus", null, "CHAPTER 5-4", null, null], [4179, "", "但是对我们来说，这样的租借服务刚好满足我们的需求。", null, "旅館_廊下d", "bgm05.opus", null, "CHAPTER 5-4", null, null], [4180, "将臣", "「那你都借了哪些电影？毕竟是你主办的派对，就由你来决定吧」", null, "旅館_廊下d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "01"}, "CHAPTER 5-4", null, null], [4181, "蕾娜", "「嗯……我还想让你给我点建议呢」", "len420_075.ogg", "旅館_廊下d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "27"}, "CHAPTER 5-4", null, null], [4182, "将臣", "「你找我就是为了商量这个吗」", null, "旅館_廊下d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "27"}, "CHAPTER 5-4", null, null], [4183, "蕾娜", "「哈哈，差不多吧」", "len420_076.ogg", "旅館_廊下d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "03"}, "CHAPTER 5-4", null, null], [4184, "蕾娜", "「不过，怎么说呢……只要你不在我身边，我就忍不住想去找你」", "len420_077.ogg", "旅館_廊下d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "23"}, "CHAPTER 5-4", null, null], [4185, "将臣", "「哎？我们刚才不是一直在一起吗」", null, "旅館_廊下d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "23"}, "CHAPTER 5-4", null, null], [4186, "蕾娜", "「……是呀，我也觉得自己有点奇怪，哈哈」", "len420_078.ogg", "旅館_廊下d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "35"}, "CHAPTER 5-4", null, null], [4187, "蕾娜", "「就因为今天我们待在一起太久了……所以突然分开之后，我可能就会觉得有点不自在」", "len420_079.ogg", "旅館_廊下d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "28"}, "CHAPTER 5-4", null, null], [4188, "将臣", "「是、是吗」", null, "旅館_廊下d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "28"}, "CHAPTER 5-4", null, null], [4189, "", "说得我有点难为情。", null, "旅館_廊下d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "03"}, "CHAPTER 5-4", null, null], [4190, "将臣", "「对……对了，我们要看哪部电影？」", null, "旅館_廊下d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "03"}, "CHAPTER 5-4", null, null], [4191, "蕾娜", "「对、对哦，差点忘了！」", "len420_080.ogg", "旅館_廊下d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "21"}, "CHAPTER 5-4", null, null], [4192, "", "蕾娜拿来的纸袋里装的是《极道之妻》系列。", null, "旅館_廊下d", "bgm05.opus", null, "CHAPTER 5-4", null, null], [4193, "", "那封面不管怎么看都很明显是黑道电影。", null, "旅館_廊下d", "bgm05.opus", null, "CHAPTER 5-4", null, null], [4194, "将臣", "「这个系列好像出了很多部了……到底是多少年前的电影啊？」", null, "旅館_廊下d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "20"}, "CHAPTER 5-4", null, null], [4195, "蕾娜", "「哇哦，每个男人身上都有和风刺青，每个女人都穿着和服！」", "len420_081.ogg", "旅館_廊下d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "18"}, "CHAPTER 5-4", null, null], [4196, "蕾娜", "「而且，妻这个字，是夫人的意思吧？」", "len420_082.ogg", "旅館_廊下d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 5-4", null, null], [4197, "蕾娜", "「这肯定是宣扬日本传统文化的合家欢电影」", "len420_083.ogg", "旅館_廊下d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "24"}, "CHAPTER 5-4", null, null], [4198, "", "你指的到底是普通人的“家”还是黑手党的“家族”啊！", null, "旅館_廊下d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "24"}, "CHAPTER 5-4", null, null], [4199, "", "至少我不敢拿这种电影给小孩子看。", null, "旅館_廊下d", "bgm05.opus", null, "CHAPTER 5-4", null, null], [4200, "", "而且，万一蕾娜又学会了一些奇怪的词语，那可就麻烦了。", null, "旅館_廊下d", "bgm05.opus", null, "CHAPTER 5-4", null, null], [4201, "", "猪谷阿姨到底是怎么想的啊？应该是不小心放错了吧。", null, "旅館_廊下d", "bgm05.opus", null, "CHAPTER 5-4", null, null], [4202, "蕾娜", "「将臣，将臣！可以让我来选吗？」", "len420_084.ogg", "旅館_廊下d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "01"}, "CHAPTER 5-4", null, null], [4203, "将臣", "「哎？刚才是准备让你选，但你该不会……！」", null, "旅館_廊下d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "01"}, "CHAPTER 5-4", null, null], [4204, "蕾娜", "「嗯！这个电影我挺感兴趣的，封面上这个女的好帅，还拿着一把武士刀……」", "len420_085.ogg", "旅館_廊下d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "02"}, "CHAPTER 5-4", null, null], [4205, "", "蕾娜拿出了一个ＤＶＤ盒，上面印着一位十分霸气的女性，背上画满了菩萨刺青，手里还握着一把长腰刀……", null, "旅館_廊下d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "02"}, "CHAPTER 5-4", null, null], [4206, "将臣", "「还是我来选吧！？」", null, "旅館_廊下d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "02"}, "CHAPTER 5-4", null, null], [4207, "蕾娜", "「是、是吗，那也行吧」", "len420_086.ogg", "旅館_廊下d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "07"}, "CHAPTER 5-4", null, null], [4208, "蕾娜", "「本来还想感受下日本的传统文化……有点可惜……」", "len420_087.ogg", "旅館_廊下d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "29"}, "CHAPTER 5-4", null, null], [4209, "", "在某种意义上，这种黑帮电影确实算是日本的传统，但我是不是帮她纠正下错误认知比较好？", null, "旅館_廊下d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "29"}, "CHAPTER 5-4", null, null], [4210, "蕾娜", "「而且……写作“妻”，读作“女人”的这种标题，对我来说也挺新奇的」", "len420_088.ogg", "旅館_廊下d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "27"}, "CHAPTER 5-4", null, null], [4211, "将臣", "「啊，就好比写作宇宙，读作天空这种？」", null, "旅館_廊下d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "27"}, "CHAPTER 5-4", null, null], [4212, "蕾娜", "「是的，日语学校里面就没有教过这种读法」", "len420_089.ogg", "旅館_廊下d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "21"}, "CHAPTER 5-4", null, null], [4213, "", "那肯定是不会教的。", null, "旅館_廊下d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "21"}, "CHAPTER 5-4", null, null], [4214, "", "不过，该怎么跟她解释呢？", null, "旅館_廊下d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "21"}, "CHAPTER 5-4", null, null], [4215, "将臣", "「唔……如果单说读作“女人”的这种情况」", null, "旅館_廊下d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "21"}, "CHAPTER 5-4", null, null], [4216, "将臣", "「这应该是因为，过去的人可能会把自己的女朋友说成“我的女人”」", null, "旅館_廊下d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "20"}, "CHAPTER 5-4", null, null], [4217, "将臣", "「所以说自己妻子的时候，可能也会这么说。虽然现在已经很少有人这么说了」", null, "旅館_廊下d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "20"}, "CHAPTER 5-4", null, null], [4218, "蕾娜", "「……～～～」", "len420_090.ogg", "旅館_廊下d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "27"}, "CHAPTER 5-4", null, null], [4219, "", "不知为何，我刚解释完，蕾娜脸就红了。", null, "旅館_廊下d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "27"}, "CHAPTER 5-4", null, null], [4220, "蕾娜", "「也就是说……」", "len420_091.ogg", "旅館_廊下d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "17h"}, "CHAPTER 5-4", null, null], [4221, "蕾娜", "「你的女人，就是指你的伴侣，是这个意思吗？」", "len420_092.ogg", "旅館_廊下d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "21h"}, "CHAPTER 5-4", null, null], [4222, "将臣", "「呃、唔，可以这么说吧……」", null, "旅館_廊下d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "21h"}, "CHAPTER 5-4", null, null], [4223, "", "“我的女人”这种说法听起来并不怎么文雅……", null, "旅館_廊下d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "21h"}, "CHAPTER 5-4", null, null], [4224, "", "但是听到这种说法，心里好像有一丝喜悦，又好像有一丝羞涩……有一种酸酸甜甜的感觉。", null, "旅館_廊下d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "21h"}, "CHAPTER 5-4", null, null], [4225, "", "最终，我们还是选择了某知名动画电影。", null, "旅館_廊下d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "21h"}, "CHAPTER 5-4", null, null], [4226, "", "记得讲的是一个遭遇神隐的女孩子被迫在一座有神灵造访的温泉旅馆工作，最后慢慢成长克服困难的故事。", null, "旅館_廊下d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "21h"}, "CHAPTER 5-4", null, null], [4227, "蕾娜", "「哇，我知道这部！日本的动画，在我们国家也很流行」", "len420_093.ogg", "旅館_廊下d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "02"}, "CHAPTER 5-4", null, null], [4228, "将臣", "「果然如此」", null, "旅館_廊下d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "02"}, "CHAPTER 5-4", null, null], [4229, "", "虽然早有耳闻，不过现在看来是真的在全世界都很有名。", null, "旅館_廊下d", "bgm05.opus", null, "CHAPTER 5-4", null, null], [4230, "", "总之，只要看这个，无论是我们日本人还是外国人，应该都能看得开心。", null, "旅館_廊下d", "bgm05.opus", null, "CHAPTER 5-4", null, null], [4231, "", "日本的动画真是厉害啊……", null, "旅館_廊下d", "bgm05.opus", null, "CHAPTER 5-4", null, null], [4232, "", "短短两个小时一眨眼就过去了。", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 5-4", null, null], [4233, "蕾娜", "「啊啊，太好看了」", "len420_094.ogg", "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "16"}, "CHAPTER 5-4", null, null], [4234, "芳乃", "「……嗯，感觉挺新奇的」", "yos420_032.ogg", "旅館_レナの部屋d", "bgm44.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "27"}, "CHAPTER 5-4", null, null], [4235, "小春", "「嗯……虽然已经在电视上看过很多遍，早就知道剧情了，但还是觉得好看」", "koh420_027.ogg", "旅館_レナの部屋d", "bgm44.opus", {"char": "小春", "file": "小春.stand", "dress": "私服", "face": "15"}, "CHAPTER 5-4", null, null], [4236, "茉子", "「今天看的这次，比以前看的时候开心多了」", "mak420_031.ogg", "旅館_レナの部屋d", "bgm44.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "35"}, "CHAPTER 5-4", null, null], [4237, "", "电影我们已经看完了。", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 5-4", null, null], [4238, "", "现在，大家正坐在一起交流各自的感想。", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 5-4", null, null], [4239, "蕾娜", "「啊，肯定是因为大家坐在一起看，所以才比平时更有意思！」", "len420_095.ogg", "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "19"}, "CHAPTER 5-4", null, null], [4240, "将臣", "「嗯，肯定是这样」", null, "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "19"}, "CHAPTER 5-4", null, null], [4241, "", "不过，大家之所以觉得新奇，多半是因为蕾娜。", null, "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "19"}, "CHAPTER 5-4", null, null], [4242, "蕾娜", "「哇噢噢噢噢噢！太厉害了，刚才那一幕你看见了吗，看见了吗，将臣？」", "len420_096.ogg", "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "19"}, "CHAPTER 5-4", null, "sd401aa"], [4243, "", "怎么说呢，如果看的是爆炸场面特别多的好莱坞电影，那我能理解。", null, "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "19"}, "CHAPTER 5-4", null, "sd401aa"], [4244, "", "但如果我没记错的话，这部电影里面应该没有那么多华丽的动作戏。", null, "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "19"}, "CHAPTER 5-4", null, "sd401aa"], [4245, "蕾娜", "「……喔喔喔喔喔喔，刚才好险啊」", "len420_097.ogg", "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "19"}, "CHAPTER 5-4", null, "sd401ab"], [4246, "", "然而，哪怕是非常普通的场面，蕾娜也会激动得大呼小叫。", null, "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "19"}, "CHAPTER 5-4", null, "sd401ab"], [4247, "蕾娜", "「哈哈哈哈，哈哈哈哈哈哈！我就知道……我就知道会这样，哈哈哈哈哈哈哈」", "len420_098.ogg", "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "19"}, "CHAPTER 5-4", null, "sd401ac"], [4248, "", "电影里稍微有点风吹草动，她的反应都会十分夸张。", null, "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "19"}, "CHAPTER 5-4", null, "sd401ac"], [4249, "蕾娜", "「好可惜啊！啊啊，就差一点了……好不甘心」", "len420_099.ogg", "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "19"}, "CHAPTER 5-4", null, "sd401ad"], [4250, "", "她一个人的反应，快抵上我们四个人了。", null, "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "19"}, "CHAPTER 5-4", null, "sd401ad"], [4251, "", "而且她的反应还很自然。", null, "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "19"}, "CHAPTER 5-4", null, "sd401ad"], [4252, "蕾娜", "「啊……看上去好臭啊……」", "len420_100.ogg", "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "19"}, "CHAPTER 5-4", null, "sd401ba"], [4253, "", "就连那些不太美观的画面，她的反应也是我们的四倍。", null, "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "19"}, "CHAPTER 5-4", null, "sd401ba"], [4254, "", "外国人到底是外国人。这么夸张的反应我肯定做不来。", null, "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "19"}, "CHAPTER 5-4", null, "sd401ba"], [4255, "", "不过，多亏她这么激动，这样一部早就看腻的作品我们看才能看得这么津津有味。", null, "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "19"}, "CHAPTER 5-4", null, "sd401ba"], [4256, "", "正因为她的反应十分夸张，我们的兴致才会一直那么高昂。", null, "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "19"}, "CHAPTER 5-4", null, "sd401ba"], [4257, "", "说实话，看她的反应，甚至比看电影更有意思。", null, "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "19"}, "CHAPTER 5-4", null, "sd401ba"], [4258, "将臣", "「……真是不管看多少次都看不腻」", null, "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "19"}, "CHAPTER 5-4", null, null], [4259, "蕾娜", "「噗，将臣，你这么喜欢这部动画电影吗？」", "len420_101.ogg", "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 5-4", null, null], [4260, "", "糟了，我竟然说出口了。", null, "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 5-4", null, null], [4261, "将臣", "「那倒也不至于……」", null, "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 5-4", null, null], [4262, "将臣", "「不过，今天跟大家一起看了之后，我更加喜欢这部电影了」", null, "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 5-4", null, null], [4263, "芳乃", "「我也是。以后电视再重播时，我肯定会想起今天的事」", "yos420_033.ogg", "旅館_レナの部屋d", "bgm44.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "24"}, "CHAPTER 5-4", null, null], [4264, "茉子", "「哈哈，看的时候不仅能体验到作品本身的乐趣，说不定还能从这段回忆中获得快乐」", "mak420_032.ogg", "旅館_レナの部屋d", "bgm44.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "27"}, "CHAPTER 5-4", null, null], [4265, "蕾娜", "「我懂！如果我以后每次看这部电影时」", "len420_102.ogg", "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "18"}, "CHAPTER 5-4", null, null], [4266, "蕾娜", "「都能想起各位，想起在日本的这些日子，那一定是一件很幸福的事」", "len420_103.ogg", "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "02"}, "CHAPTER 5-4", null, null], [4267, "", "的确，那一定很幸福。", null, "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "02"}, "CHAPTER 5-4", null, null], [4268, "廉太郎", "「那么，接下来我们干什么？现在睡觉还有点早，要不要再看一盘ＤＶＤ？」", "ren420_025.ogg", "旅館_レナの部屋d", "bgm44.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-4", null, null], [4269, "小春", "「但是，蕾娜学姐明天还要早起吧？」", "koh420_028.ogg", "旅館_レナの部屋d", "bgm44.opus", {"char": "小春", "file": "小春.stand", "dress": "私服", "face": "17"}, "CHAPTER 5-4", null, null], [4270, "将臣", "「确实，要是再看一盘，看完就很晚了」", null, "旅館_レナの部屋d", "bgm44.opus", {"char": "小春", "file": "小春.stand", "dress": "私服", "face": "17"}, "CHAPTER 5-4", null, null], [4271, "蕾娜", "「现在这个时间不早不晚，也不知道做什么好」", "len420_104.ogg", "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "30"}, "CHAPTER 5-4", null, null], [4272, "", "现在还不想睡觉。还想继续跟大家一起玩。", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 5-4", null, null], [4273, "", "但是，这个点也不能大声喧闹。", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 5-4", null, null], [4274, "", "思前想后，心里不免有些着急。", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 5-4", null, null], [4275, "芳乃", "「唉……要是今天永远都不结束该多好，那样我就能一直陪你们了」", "yos420_034.ogg", "旅館_レナの部屋d", "bgm44.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "29"}, "CHAPTER 5-4", null, null], [4276, "茉子", "「是啊，我们从上午一直玩到现在，还是感觉没玩够」", "mak420_033.ogg", "旅館_レナの部屋d", "bgm44.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "46"}, "CHAPTER 5-4", null, null], [4277, "", "看来，我们的心情都是一样的。", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 5-4", null, null], [4278, "", "狂欢之后的淡淡寂寞正撩动着我们的内心。", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 5-4", null, null], [4279, "蕾娜", "「以后有空再聚就行了嘛！而且，我们还能再玩一会儿……」", "len420_105.ogg", "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "01"}, "CHAPTER 5-4", null, null], [4280, "", "就在这时，突然有人敲门。\\n打开门后，猪谷阿姨正站在门口。", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 5-4", null, null], [4281, "心子", "「抱歉，打扰各位了」", "mot420_012.ogg", "旅館_レナの部屋d", "bgm44.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "13"}, "CHAPTER 5-4", null, null], [4282, "蕾娜", "「掌柜的！难道是我们太吵了？」", "len420_106.ogg", "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "06"}, "CHAPTER 5-4", null, null], [4283, "心子", "「不，那倒不是……巫女大人，您能来一趟吗」", "mot420_013.ogg", "旅館_レナの部屋d", "bgm44.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "12"}, "CHAPTER 5-4", null, null], [4284, "芳乃", "「我？」", "yos420_035.ogg", "旅館_レナの部屋d", "bgm44.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-4", null, null], [4285, "心子", "「是的，您父亲刚才过来了，一直坐在大厅等您，所以我过来通知一下」", "mot420_014.ogg", "旅館_レナの部屋d", "bgm44.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "13"}, "CHAPTER 5-4", null, null], [4286, "芳乃", "「哎，我爸爸来了？」", "yos420_036.ogg", "旅館_レナの部屋d", "bgm44.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "06"}, "CHAPTER 5-4", null, null], [4287, "", "难道是发生什么事了吗？", null, "旅館_レナの部屋d", "bgm44.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "06"}, "CHAPTER 5-4", null, null], [4288, "", "朝武似乎也是这么想的。", null, "旅館_レナの部屋d", "bgm44.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "06"}, "CHAPTER 5-4", null, null], [4289, "安晴", "「这么早就出来了，不玩了吗？」", "yas420_001.ogg", "旅館_廊下d", "bgm37.opus", {"char": "安晴", "file": "安晴.stand", "dress": "私服", "face": "09"}, "CHAPTER 5-4", null, null], [4290, "", "然而，安晴叔叔手里正拿着报刊架上的杂志，看上去十分悠闲。", null, "旅館_廊下d", "bgm37.opus", {"char": "安晴", "file": "安晴.stand", "dress": "私服", "face": "09"}, "CHAPTER 5-4", null, null], [4291, "芳乃", "「爸爸，我听说你来找我，还以为有什么事呢！」", "yos420_037.ogg", "旅館_廊下d", "bgm37.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "48"}, "CHAPTER 5-4", null, null], [4292, "安晴", "「啊，抱歉，我本来不想打扰你的」", "yas420_002.ogg", "旅館_廊下d", "bgm37.opus", {"char": "安晴", "file": "安晴.stand", "dress": "私服", "face": "17"}, "CHAPTER 5-4", null, null], [4293, "安晴", "「我就是觉得时间不早了，让你一个人走夜路回去可能不太安全」", "yas420_003.ogg", "旅館_廊下d", "bgm37.opus", {"char": "安晴", "file": "安晴.stand", "dress": "私服", "face": "09"}, "CHAPTER 5-4", null, null], [4294, "安晴", "「我本来就过来有点事，办完事之后就一直坐在这等你，本想等你玩尽兴了再回去的」", "yas420_004.ogg", "旅館_廊下d", "bgm37.opus", {"char": "安晴", "file": "安晴.stand", "dress": "私服", "face": "13"}, "CHAPTER 5-4", null, null], [4295, "芳乃", "「爸爸……」", "yos420_038.ogg", "旅館_廊下d", "bgm37.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "05"}, "CHAPTER 5-4", null, null], [4296, "安晴", "「所以，你还没玩尽兴的话就回去继续玩吧，不用管我」", "yas420_005.ogg", "旅館_廊下d", "bgm37.opus", {"char": "安晴", "file": "安晴.stand", "dress": "私服", "face": "11"}, "CHAPTER 5-4", null, null], [4297, "安晴", "「再多玩一会儿也没事的」", "yas420_006.ogg", "旅館_廊下d", "bgm37.opus", {"char": "安晴", "file": "安晴.stand", "dress": "私服", "face": "13"}, "CHAPTER 5-4", null, null], [4298, "", "安晴叔叔并不是那种喜欢抛头露面的人。", null, "旅館_廊下d", "bgm37.opus", null, "CHAPTER 5-4", null, null], [4299, "", "但是他为人宽厚，一直都在背后默默支持着我们。", null, "旅館_廊下d", "bgm37.opus", null, "CHAPTER 5-4", null, null], [4300, "", "朝武心里应该也很明白。", null, "旅館_廊下d", "bgm37.opus", null, "CHAPTER 5-4", null, null], [4301, "芳乃", "「没事，我们也刚好玩得差不多了」", "yos420_039.ogg", "旅館_廊下d", "bgm37.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "20"}, "CHAPTER 5-4", null, null], [4302, "安晴", "「不再待一会儿吗？」", "yas420_007.ogg", "旅館_廊下d", "bgm37.opus", {"char": "安晴", "file": "安晴.stand", "dress": "私服", "face": "09"}, "CHAPTER 5-4", null, null], [4303, "芳乃", "「嗯……蕾娜」", "yos420_040.ogg", "旅館_廊下d", "bgm37.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "02"}, "CHAPTER 5-4", null, null], [4304, "蕾娜", "「芳乃……」", "len420_107.ogg", "旅館_廊下d", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 5-4", null, null], [4305, "芳乃", "「今天能收到邀请我真的很开心，而且跟大家在一起我也玩得非常尽兴」", "yos420_041.ogg", "旅館_廊下d", "bgm37.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "04"}, "CHAPTER 5-4", null, null], [4306, "芳乃", "「真的……这可能是我从小到大过得最开心的一天」", "yos420_042.ogg", "旅館_廊下d", "bgm37.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "02"}, "CHAPTER 5-4", null, null], [4307, "芳乃", "「所以，那个……今后，你也能继续做我的朋友吗？」", "yos420_043.ogg", "旅館_廊下d", "bgm37.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "22"}, "CHAPTER 5-4", null, null], [4308, "蕾娜", "「当然了！你今天不是也说了吗，咱们是朋友」", "len420_108.ogg", "旅館_廊下d", "bgm37.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "22"}, "CHAPTER 5-4", null, null], [4309, "芳乃", "「是的……但是，我的朋友真的很少」", "yos420_044.ogg", "旅館_廊下d", "bgm37.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "13"}, "CHAPTER 5-4", null, null], [4310, "芳乃", "「现在却突然交到了一位外国朋友……这对我来说简直就像做梦一样」", "yos420_045.ogg", "旅館_廊下d", "bgm37.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "24"}, "CHAPTER 5-4", null, null], [4311, "蕾娜", "「哈哈，你愿意这么说，是我的荣幸」", "len420_109.ogg", "旅館_廊下d", "bgm37.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "24"}, "CHAPTER 5-4", null, null], [4312, "", "说罢，蕾娜直接抱了上去。", null, "旅館_廊下d", "bgm37.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "24"}, "CHAPTER 5-4", null, null], [4313, "蕾娜", "「现在还觉得是梦吗？」", "len420_110.ogg", "旅館_廊下d", "bgm37.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "04"}, "CHAPTER 5-4", null, null], [4314, "芳乃", "「嗯，现在不觉得了」", "yos420_046.ogg", "旅館_廊下d", "bgm37.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "24"}, "CHAPTER 5-4", null, null], [4315, "芳乃", "「那我就先走了，你们不要介意，继续玩吧」", "yos420_047.ogg", "旅館_廊下d", "bgm37.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "20"}, "CHAPTER 5-4", null, null], [4316, "", "朝武和安晴叔叔一同走出了志那都庄的大门。", null, "旅館_廊下d", "bgm37.opus", null, "CHAPTER 5-4", null, null], [4317, "", "出门后，他们也依然在向我们挥手，直到自动门关闭。", null, "旅館_廊下d", "bgm37.opus", null, "CHAPTER 5-4", null, null], [4318, "", "门静静地关上之后，他们的身影也越走越远……直到消失在视野尽头时，我才终于意识到，今天马上就要结束了。", null, "旅館_廊下d", "bgm37.opus", null, "CHAPTER 5-4", null, null], [4319, "蕾娜", "「……」", "len420_111.ogg", "旅館_廊下d", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "06"}, "CHAPTER 5-4", null, null], [4320, "将臣", "「……？」", null, "旅館_廊下d", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "06"}, "CHAPTER 5-4", null, null], [4321, "", "这时，蕾娜的手又溜进了我的手掌之中。", null, "旅館_廊下d", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "06"}, "CHAPTER 5-4", null, null], [4322, "", "我默默地握住了她的手。", null, "旅館_廊下d", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "06"}, "CHAPTER 5-4", null, null], [4323, "丛雨", "「那么，主人，本座就先回芳乃那边了」", "mur420_001.ogg", "旅館_廊下d", "bgm03.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-4", null, null], [4324, "将臣", "「嗯，今天没怎么陪你，抱歉了」", null, "旅館_廊下d", "bgm03.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-4", null, null], [4325, "", "我用只有小雨能听见的音量轻声说道。", null, "旅館_廊下d", "bgm03.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-4", null, null], [4326, "丛雨", "「不必介意，今天的聚会足够有趣，在一旁看着也并不无聊」", "mur420_002.ogg", "旅館_廊下d", "bgm03.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "28"}, "CHAPTER 5-4", null, null], [4327, "茉子", "「嗯……既然如此，我也去送芳乃大人一程吧」", "mak420_034.ogg", "旅館_廊下d", "bgm03.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-4", null, null], [4328, "蕾娜", "「难道茉子也要回去了！？」", "len420_112.ogg", "旅館_廊下d", "bgm03.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-4", null, null], [4329, "茉子", "「放心吧，我只是去送她一程，一会儿还会回来的」", "mak420_035.ogg", "旅館_廊下d", "bgm03.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "34"}, "CHAPTER 5-4", null, null], [4330, "茉子", "「我要是敢不回来，芳乃大人肯定会生气的」", "mak420_036.ogg", "旅館_廊下d", "bgm03.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "27"}, "CHAPTER 5-4", null, null], [4331, "茉子", "「而且……」", "mak420_037.ogg", "旅館_廊下d", "bgm03.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-4", null, null], [4332, "", "嗯？不知为何，常陆突然向小春和廉太郎使了个眼色。", null, "旅館_廊下d", "bgm03.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "01"}, "CHAPTER 5-4", null, null], [4333, "廉太郎", "「哎？什么？」", "ren420_026.ogg", "旅館_廊下d", "bgm03.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "私服", "face": "07"}, "CHAPTER 5-4", null, null], [4334, "小春", "「啊，对了对了！我作业还没写呢」", "koh420_029.ogg", "旅館_廊下d", "bgm03.opus", {"char": "小春", "file": "小春.stand", "dress": "私服", "face": "24"}, "CHAPTER 5-4", null, null], [4335, "小春", "「我先暂时回趟自己的房间吧。廉哥，你也过来」", "koh420_030.ogg", "旅館_廊下d", "bgm03.opus", {"char": "小春", "file": "小春.stand", "dress": "私服", "face": "02"}, "CHAPTER 5-4", null, null], [4336, "廉太郎", "「呃，我倒是没什么……」", "ren420_027.ogg", "旅館_廊下d", "bgm03.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "私服", "face": "14"}, "CHAPTER 5-4", null, null], [4337, "小春", "「少废话！你赶紧跟我过来……哥哥，蕾娜学姐，你们加油哦」", "koh420_031.ogg", "旅館_廊下d", "bgm03.opus", {"char": "小春", "file": "小春.stand", "dress": "私服", "face": "12"}, "CHAPTER 5-4", null, null], [4338, "将臣", "「啊？」", null, "旅館_廊下d", "bgm03.opus", {"char": "小春", "file": "小春.stand", "dress": "私服", "face": "12"}, "CHAPTER 5-4", null, null], [4339, "茉子", "「哈哈，虽然大家一起玩很开心，但你们也要珍惜难得的二人时光啊」", "mak420_038.ogg", "旅館_廊下d", "bgm03.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "27"}, "CHAPTER 5-4", null, null], [4340, "蕾娜", "「茉子……不用这么照顾我们的啦」", "len420_113.ogg", "旅館_廊下d", "bgm03.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "21h"}, "CHAPTER 5-4", null, null], [4341, "蕾娜", "「不过，还是谢谢你了！」", "len420_114.ogg", "旅館_廊下d", "bgm03.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "02h"}, "CHAPTER 5-4", null, null], [4342, "茉子", "「嗯，路上我会走慢点的，你们就尽情享受二人时光吧」", "mak420_039.ogg", "旅館_廊下d", "bgm03.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "23"}, "CHAPTER 5-4", null, null], [4343, "", "留下一句耐人寻味的话之后，常陆走出了大门。", null, "旅館_廊下d", "bgm03.opus", null, "CHAPTER 5-4", null, null], [4344, "", "现在，只剩下我跟蕾娜了。", null, "旅館_廊下d", "bgm03.opus", null, "CHAPTER 5-4", null, null], [4345, "将臣", "「呃、那个……这是什么情况？」", null, "旅館_廊下d", "bgm03.opus", null, "CHAPTER 5-4", null, null], [4346, "蕾娜", "「将臣，你也太不解风情了吧」", "len420_115.ogg", "旅館_廊下d", "bgm03.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "27"}, "CHAPTER 5-4", null, null], [4347, "", "不，其实我知道是怎么回事。", null, "旅館_廊下d", "bgm03.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "27"}, "CHAPTER 5-4", null, null], [4348, "", "但我毕竟没有确认过，就怕自己想太多了。", null, "旅館_廊下d", "bgm03.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "27"}, "CHAPTER 5-4", null, null], [4349, "蕾娜", "「将臣，其实……我想带你去一个地方」", "len420_116.ogg", "旅館_廊下d", "bgm03.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "27"}, "CHAPTER 5-4", null, null], [4350, "将臣", "「可以啊，要去哪？」", null, "旅館_廊下d", "bgm03.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "27"}, "CHAPTER 5-4", null, null], [4351, "蕾娜", "「嘿嘿，是我的秘密据点」", "len420_117.ogg", "旅館_廊下d", "bgm03.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "02"}, "CHAPTER 5-4", null, null], [4352, "将臣", "「我们真的可以随便来这里吗？」", null, "空_夜空", "bgm03.opus", null, "CHAPTER 5-4", null, null], [4353, "蕾娜", "「哈哈，你一定要跟掌柜的保密啊」", "len420_118.ogg", "空_夜空", "bgm03.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "10"}, "CHAPTER 5-4", null, null], [4354, "蕾娜", "「对了，你先看着下面，一定不要先往上看啊」", "len420_119.ogg", "空_夜空", "bgm03.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "27"}, "CHAPTER 5-4", null, null], [4355, "", "我们就这样牵着走，走在志那都庄的屋顶上。", null, "空_夜空", "bgm03.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "27"}, "CHAPTER 5-4", null, null], [4356, "", "为了避免打扰到屋顶下面的客人，我们尽量压低了脚步声。", null, "空_夜空", "bgm03.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "27"}, "CHAPTER 5-4", null, null], [4357, "蕾娜", "「好了，差不多就是这附近了。快看」", "len420_120.ogg", "空_夜空", "bgm03.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "02"}, "CHAPTER 5-4", null, null], [4358, "将臣", "「哇哦」", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4359, "", "我们并排坐在屋顶上，眺望着璀璨的星空。", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4360, "", "来到穗织之后，我经常会觉得星空很美，但是从这里观赏到的星空更是美不胜收。", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4361, "蕾娜", "「怎么样？这是只有志那都庄的员工才知道的地方，也是我最喜欢的一个地方」", "len420_121.ogg", "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4362, "将臣", "「……嗯，毕竟连我这个外孙都不知道」", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4363, "", "难怪她说这是她的秘密据点，她大概真的很喜欢这里。", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4364, "", "蕾娜把身子靠了过来。", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4365, "", "我故作镇定，静静地仰望着星空。", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4366, "蕾娜", "「在日本，北极星的位置确实很低啊」", "len420_122.ogg", "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4367, "将臣", "「是吗，这你都能看出来？」", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4368, "蕾娜", "「是的！但是，在日本也能看到很多我以前没见过的星星」", "len420_123.ogg", "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4369, "蕾娜", "「那边的星星，我就没什么印象」", "len420_124.ogg", "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4370, "将臣", "「这里能看到的星星跟你们国家那边差异大吗？」", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4371, "蕾娜", "「哈哈，不是我吹牛，我们那边能看到的星星比穗织这里多得多」", "len420_125.ogg", "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4372, "将臣", "「不是吧，比穗织还多？」", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4373, "", "在我家那边，猎户座以外的星座基本上全都看不见。", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4374, "蕾娜", "「毕竟我住的村庄比穗织还要偏僻，居民也少。就连流星也能经常看见」", "len420_126.ogg", "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4375, "蕾娜", "「我们那儿的流星是真的多，思索愿望的速度都没流星出现的速度快」", "len420_127.ogg", "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4376, "蕾娜", "「下雪的时候，甚至都分不清哪些是雪，哪些是流星」", "len420_128.ogg", "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4377, "将臣", "「哈哈，这也太夸张了吧？」", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4378, "蕾娜", "「真的，你可别不信。以后有机会了，我会让你亲眼见识见识我们那的极光」", "len420_129.ogg", "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4379, "蕾娜", "「到时候吓得找不着北，可别怪我没提醒过你哦」", "len420_130.ogg", "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4380, "将臣", "「嗯，说得我越来越期待了……」", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4381, "", "欧洲真的很远。", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4382, "", "远得连天空都会看起来不一样，远得让我不得不正视这一段距离。", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4383, "", "刚才和大家闲聊时，还说以后有机会了要去圣诞老人村。当时觉得，只要想去应该就能去。", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4384, "", "然而，现在我必须直面现实。", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4385, "", "单纯去旅游可能并不难，但是……如果要考虑定居呢？", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4386, "", "这对我来说实在是太过遥远了。", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4387, "蕾娜", "「谢谢你，将臣」", "len420_131.ogg", "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4388, "将臣", "「嗯？」", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4389, "蕾娜", "「今天我过得非常开心。这都要感谢你，是你提出要开睡衣派对，才会有这么开心的一天」", "len420_132.ogg", "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4390, "蕾娜", "「而且……你这么做，也都是为了我吧？」", "len420_133.ogg", "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4391, "将臣", "「不用客气啦。我也玩得很开心」", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4392, "蕾娜", "「哈哈。其实，辨认星星的方法，是我爷爷教我的」", "len420_134.ogg", "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4393, "蕾娜", "「我爷爷的爷爷教会了我爷爷，然后我爸爸又教会了我妈妈」", "len420_135.ogg", "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4394, "将臣", "「是吗」", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4395, "", "之前她说自己想念家人时，我脑子里首先冒出的想法是，希望她不要走。", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4396, "", "之所以开睡衣派对，也是为了这个。", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4397, "蕾娜", "「所以，我和我爷爷，还有爸爸妈妈」", "len420_136.ogg", "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4398, "蕾娜", "「我们随时都可以仰望同一片星空，找到同一颗星星」", "len420_137.ogg", "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4399, "将臣", "「蕾娜……」", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4400, "蕾娜", "「我们国家确实离日本有点远，夜晚的星空也有所不同」", "len420_138.ogg", "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4401, "蕾娜", "「但是，这里依然能看见许多我认识的星星」", "len420_139.ogg", "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4402, "蕾娜", "「有时候可能会觉得寂寞，但也并不是那么寂寞」", "len420_140.ogg", "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4403, "蕾娜", "「你之前好像有点担心我，所以我说这些，还是希望你能放心」", "len420_141.ogg", "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4404, "将臣", "「蕾娜……你真坚强」", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4405, "", "我忍不住说出了自己的真心话。", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4406, "", "换成是我，我肯定会寂寞。", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4407, "", "让我跟蕾娜相隔万里，哪有不寂寞的道理。", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4408, "蕾娜", "「……将臣？」", "len420_142.ogg", "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4409, "将臣", "「唉，我是完全不会辨认星星」", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4410, "将臣", "「甚至连哪个是北极星都不知道」", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4411, "蕾娜", "「那要不我来教你？」", "len420_143.ogg", "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4412, "蕾娜", "「这样一来，以后你也能轻松辨认星星了」", "len420_144.ogg", "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4413, "将臣", "「……我也能做到吗？」", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4414, "蕾娜", "「肯定能做到」", "len420_145.ogg", "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4415, "蕾娜", "「因为，就算是阴天，或者下雨，星星的位置也是不变的」", "len420_146.ogg", "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4416, "", "蕾娜的爷爷八成也是这么教她的。", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4417, "", "可是就算她和穗织的朋友们关系再好……", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4418, "", "在她老家，肯定也有很多人关心她，想念她。", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4419, "", "毕竟她这么漂亮，而且温柔又善良。", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4420, "", "所以，无论这个国家的人再怎么接纳她……她也早晚有一天要回到自己的故乡。", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4421, "", "如果我们再进一步加深关系，离别时肯定会非常难过。", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4422, "", "会比现在更加痛苦。", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4423, "", "那还不如现在就……可是……", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4424, "将臣", "「蕾娜，我喜欢你」", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4425, "蕾娜", "「……」", "len420_147.ogg", "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4426, "", "一个不留神，我已经说出了口。", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4427, "", "哪怕等待我的是各种艰难险阻，这也是我现在最真实的感情。", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4428, "将臣", "「就算我们有朝一日不得不分开，我也想和你仰望同一片星空」", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4429, "将臣", "「……你刚才说，就算去了地球另一端，星星的位置也是不变的」", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4430, "将臣", "「那你能不能教教我，该怎么辨认星星？我希望无论何时，我们都能找到同一颗星星」", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4431, "蕾娜", "「…………」", "len420_148.ogg", "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4432, "", "然而，蕾娜却愣住了。", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4433, "", "咦？难道是我自作多情了？还是说，她没听懂我的意思？", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4434, "将臣", "「呃，哎？那个……我刚才说的……并不是普通的喜欢」", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4435, "将臣", "「我说的是……对于异性的喜欢」", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4436, "将臣", "「我的意思是……希望你能做我的女朋友」", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4437, "蕾娜", "「抱歉……」", "len420_149.ogg", "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4438, "将臣", "「……哎？」", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4439, "", "她的手越来越用力了。", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4440, "蕾娜", "「我明白你的意思……我只是吓了一跳，愣住了而已……哈哈」", "len420_150.ogg", "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4441, "蕾娜", "「这就是日本的告白吧……听说必须举行这个仪式，才能成为恋人」", "len420_151.ogg", "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4442, "将臣", "「仪式……这说得有点太夸张了」", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4443, "蕾娜", "「其实欧洲国家没有告白这种文化……其他国家可能也没有」", "len420_152.ogg", "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4444, "蕾娜", "「我们每次在日本的影像作品中看到告白场景时，都会感觉很不可思议」", "len420_153.ogg", "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4445, "将臣", "「是、是吗？外国人都不告白的吗」", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4446, "", "真是令人震惊的事实。我还以为外国人在这方面都很积极呢。", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4447, "将臣", "「可是……不告白的话，要怎么成为恋人呢？」", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4448, "蕾娜", "「自己喜欢的人喜不喜欢自己，看态度就能明白的啦」", "len420_154.ogg", "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4449, "", "原来如此，正因为外国人很积极，所以单看态度就知道了。", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4450, "蕾娜", "「昨天……我牵你手的时候，你第一次主动握紧了我的手」", "len420_155.ogg", "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4451, "蕾娜", "「当时，我就明白你的心意了」", "len420_156.ogg", "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4452, "将臣", "「蕾娜……」", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4453, "将臣", "「原、原来是这样啊」", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4454, "", "就连我自己都不是那么明白自己的感情。", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4455, "", "但是蕾娜却敏锐地察觉到了。", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4456, "", "想到这里，我就感觉胸口暖暖的。", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4457, "蕾娜", "「不过……」", "len420_157.ogg", "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4458, "将臣", "「嗯？」", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4459, "蕾娜", "「虽然我昨天就明白了你的心意……但你刚才向我告白的时候」", "len420_158.ogg", "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4460, "蕾娜", "「我高兴得连话都说不出来了」", "len420_159.ogg", "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4461, "蕾娜", "「真希望这种文化能传播到全世界」", "len420_160.ogg", "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4462, "将臣", "「……告白的文化吗？」", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4463, "蕾娜", "「告白真的很棒」", "len420_161.ogg", "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4464, "蕾娜", "「这个仪式让我心里充满了幸福和喜悦。我相信，告白一定会给全世界的人们带来幸福」", "len420_162.ogg", "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4465, "将臣", "「嗯，蕾娜……我现在就非常幸福」", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4466, "蕾娜", "「嗯，将臣……」", "len420_163.ogg", "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4467, "", "蕾娜轻轻地闭上了眼睛。", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4468, "", "我也想用行动来表明我的态度，而不仅仅是语言。", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4469, "", "就用蕾娜她们国家的做派吧。", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4470, "", "我们的心意，早已无须多言。", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", "ev406a", null], [4471, "", "接下来发生的事，只有繁星看在眼里。", null, "空_夜空", "bgm07.opus", null, "CHAPTER 5-4", null, null], [4472, "", "突然，我发现自己正在山上快步追赶着那只白狛。", null, "山_山道a", "bgm36.opus", null, "CHAPTER 6-1", null, null], [4473, "", "我明明是在走路，却能渐渐追上向前奔逃的白狛，这种感觉也是够神奇的。", null, "山_山道a", "bgm36.opus", null, "CHAPTER 6-1", null, null], [4474, "", "现在我八成是在梦中，眼前看到的都是宿体的记忆。", null, "山_山道a", "bgm36.opus", null, "CHAPTER 6-1", null, null], [4475, "将臣", "「（不过，这究竟是……？）」", null, "山_山道a", "bgm36.opus", null, "CHAPTER 6-1", null, null], [4476, "蕾娜", "「（是的……这跟我以前被祟神操控时做的梦一样）」", "len421_001.ogg", "山_山道a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "19"}, "CHAPTER 6-1", null, null], [4477, "", "蕾娜似乎就在我身边。", null, "山_山道a", "bgm36.opus", null, "CHAPTER 6-1", null, null], [4478, "", "由于我们体内的宿体碎片能够产生共鸣，所以我们在梦中也可以对话。", null, "山_山道a", "bgm36.opus", null, "CHAPTER 6-1", null, null], [4479, "", "当我明确注意到她的存在，并认清自己的意识时，我的视角已经切到了半空中。", null, "山_山道a", "bgm36.opus", null, "CHAPTER 6-1", null, null], [4480, "", "这果然是跟以前一样的梦境。", null, "山_山道a", "bgm36.opus", null, "CHAPTER 6-1", null, null], [4481, "", "但是……这样的体验实在是让我倍感惊讶。", null, "山_山道a", "bgm36.opus", null, "CHAPTER 6-1", null, null], [4482, "将臣", "「（啊！那位就是绘卷里的金发女神吧！？）」", null, "山_山道a", "bgm36.opus", null, "CHAPTER 6-1", null, null], [4483, "", "刚才，我似乎一直用的是她的视角。", null, "山_山道a", "bgm36.opus", null, "CHAPTER 6-1", null, null], [4484, "", "她那一头淡如奶油的浅金色长发，乍一看就跟蕾娜一模一样。", null, "山_山道a", "bgm36.opus", null, "CHAPTER 6-1", null, null], [4485, "蕾娜", "「（……哎呀？喔）」", "len421_002.ogg", "山_山道a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "08"}, "CHAPTER 6-1", null, null], [4486, "", "哎！？我刚这么想，那位女神就突然变成了蕾娜的模样。", null, "山_山道a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "女神", "face": "15"}, "CHAPTER 6-1", null, null], [4487, "蕾娜", "「（难道说，这位女神其实就是我吗？」", "len421_003.ogg", "山_山道a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 6-1", null, null], [4488, "将臣", "「（不，不知道……难道是因为我心里觉得你们长得像，所以你就变成她了？）」", null, "山_山道a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 6-1", null, null], [4489, "蕾娜", "「（这么说的话，在之前的梦境里也是，我上一秒还在想他们到底在说什么，下一秒就突然能听懂他们说话了」", "len421_004.ogg", "山_山道a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "08"}, "CHAPTER 6-1", null, null], [4490, "将臣", "「（……原来如此，这种事确实有可能在梦中发生）」", null, "山_山道a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "08"}, "CHAPTER 6-1", null, null], [4491, "", "但这也可能引发一些危险的事情。", null, "山_山道a", "bgm36.opus", null, "CHAPTER 6-1", null, null], [4492, "", "以后要留个心才行。", null, "山_山道a", "bgm36.opus", null, "CHAPTER 6-1", null, null], [4493, "", "这时，我看见刚才的白狛迅速地钻进了草丛之中。", null, "山_山道a", "bgm36.opus", null, "CHAPTER 6-1", null, null], [4494, "蕾娜", "「（哇啊，我的身体要去追它了）」", "len421_005.ogg", "山_山道a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "06"}, "CHAPTER 6-1", null, null], [4495, "将臣", "「（看来并不单纯是她变成了你的模样，连你的意识都进到她身体里去了吗？）」", null, "山_山道a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "06"}, "CHAPTER 6-1", null, null], [4496, "蕾娜", "「（啊、嗯，好像是这样……哇啊，她走得好快）」", "len421_006.ogg", "山_山道a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "21"}, "CHAPTER 6-1", null, null], [4497, "", "糟了，再不快点会被她甩掉。", null, "山_山道a", "bgm36.opus", null, "CHAPTER 6-1", null, null], [4498, "", "要是在梦境中迷了路，天知道会发生什么。", null, "山_山道a", "bgm36.opus", null, "CHAPTER 6-1", null, null], [4499, "蕾娜", "「小狛！」", "len421_007.ogg", "山_山の中１a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "女神", "face": "16"}, "CHAPTER 6-1", null, null], [4500, "", "哎？在这梦境之中，之前我跟蕾娜都是在心里对话，但刚才，我明确地听见她开口说话了。", null, "山_山の中１a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "女神", "face": "15"}, "CHAPTER 6-1", null, null], [4501, "", "我们一直在追的白狛听见女神大人一声呵斥之后也吓了一跳，站在原地不动了。", null, "山_山の中１a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "女神", "face": "15"}, "CHAPTER 6-1", null, null], [4502, "蕾娜", "「（刚才那是女神大人说的话吧？）」", "len421_008.ogg", "山_山の中１a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "30"}, "CHAPTER 6-1", null, null], [4503, "将臣", "「（也就是说，刚才那句话跟你的意志无关？）」", null, "山_山の中１a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "30"}, "CHAPTER 6-1", null, null], [4504, "", "被祟神操控的原理说不定也跟这种现象有关。", null, "山_山の中１a", "bgm36.opus", null, "CHAPTER 6-1", null, null], [4505, "女神", "「我早就教过你，不能一味地憎恶人类」", "lem421_001.ogg", "山_山の中１a", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "15"}, "CHAPTER 6-1", null, null], [4506, "白狛", "「又开始说教了吗」", "srk421_001.ogg", "山_山の中１a", "bgm36.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 6-1", null, null], [4507, "女神", "「不要顶嘴！难道你连姐姐的话也听不进去了吗」", "lem421_002.ogg", "山_山の中１a", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "09"}, "CHAPTER 6-1", null, null], [4508, "", "现在又发生了一种奇妙的现象。", null, "山_山の中１a", "bgm36.opus", null, "CHAPTER 6-1", null, null], [4509, "", "实际上，女神和白狛说的都是古文课上学的那种类似文言文的句子，非常难懂。", null, "山_山の中１a", "bgm36.opus", null, "CHAPTER 6-1", null, null], [4510, "", "但是，我却能听懂他们在说什么。", null, "山_山の中１a", "bgm36.opus", null, "CHAPTER 6-1", null, null], [4511, "蕾娜", "「（哇哦，不知道为什么，他们俩的对话……我这边听起来就像是母语一样）」", "len421_009.ogg", "山_山の中１a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 6-1", null, null], [4512, "将臣", "「（母语？也就是说蕾娜听到的是外语吗？）」", null, "山_山の中１a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 6-1", null, null], [4513, "蕾娜", "「（是的，但实际上，她的口吻应该更有气势，命令的语气也更强吧？）」", "len421_010.ogg", "山_山の中１a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "30"}, "CHAPTER 6-1", null, null], [4514, "将臣", "「（确实）」", null, "山_山の中１a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "30"}, "CHAPTER 6-1", null, null], [4515, "", "难道是因为变成了蕾娜的模样，所以语气也受到了影响？", null, "山_山の中１a", "bgm36.opus", null, "CHAPTER 6-1", null, null], [4516, "", "我们的感受和实际情况似乎也有一些出入，真是越来越觉得不可思议了。", null, "山_山の中１a", "bgm36.opus", null, "CHAPTER 6-1", null, null], [4517, "白狛", "「姐姐大人，您这样说我也很为难」", "srk421_002.ogg", "山_山の中１a", "bgm36.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 6-1", null, null], [4518, "白狛", "「虽说我们同为山神，皆生于这穗织崇山之上，可姐姐大人生于玉石，我则是生于野兽」", "srk421_003.ogg", "山_山の中１a", "bgm36.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 6-1", null, null], [4519, "女神", "「所以，姐姐说的话你就听不进去了吗，小狛！」", "lem421_003.ogg", "山_山の中１a", "bgm36.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 6-1", null, null], [4520, "白狛", "「那是当然」", "srk421_004.ogg", "山_山の中１a", "bgm36.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 6-1", null, null], [4521, "白狛", "「姐姐大人，玉石供人观赏，受人喜爱，您当然会对人们更加宽容」", "srk421_005.ogg", "山_山の中１a", "bgm36.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 6-1", null, null], [4522, "白狛", "「但是兽类，却终日遭人猎捕」", "srk421_006.ogg", "山_山の中１a", "bgm36.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 6-1", null, null], [4523, "白狛", "「前几日，我还见有好几人给野犬架上靶子，骑马追赶并且用弓箭射它」", "srk421_007.ogg", "山_山の中１a", "bgm36.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 6-1", null, null], [4524, "女神", "「你说的是“犬追物”吧」", "lem421_004.ogg", "山_山の中１a", "bgm36.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 6-1", null, null], [4525, "白狛", "「既然您知道，那就请您理解我的愤怒」", "srk421_008.ogg", "山_山の中１a", "bgm36.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 6-1", null, null], [4526, "白狛", "「还有，也请您不要再用乳名叫我了」", "srk421_009.ogg", "山_山の中１a", "bgm36.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 6-1", null, null], [4527, "女神", "「听好了，小狛」", "lem421_005.ogg", "山_山の中１a", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "15"}, "CHAPTER 6-1", null, null], [4528, "", "女神大人一字一顿地叫了白狛的名字。", null, "山_山の中１a", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "15"}, "CHAPTER 6-1", null, null], [4529, "", "这种威慑力，是平时的蕾娜完全没有的。", null, "山_山の中１a", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "15"}, "CHAPTER 6-1", null, null], [4530, "女神", "「人类有人类的生活」", "lem421_006.ogg", "山_山の中１a", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "08"}, "CHAPTER 6-1", null, null], [4531, "女神", "「肉食野兽，会吃掉草食野兽，而草食野兽，也会吃掉花木和果实」", "lem421_007.ogg", "山_山の中１a", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "23"}, "CHAPTER 6-1", null, null], [4532, "女神", "「因此，人类只是自然的一部分而已」", "lem421_008.ogg", "山_山の中１a", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "15"}, "CHAPTER 6-1", null, null], [4533, "女神", "「且不说这些，人类常年开山凿石，我岂会不觉痛痒？」", "lem421_009.ogg", "山_山の中１a", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "15"}, "CHAPTER 6-1", null, null], [4534, "女神", "「但是，我并不会过分憎恶，也不会格外庇护」", "lem421_010.ogg", "山_山の中１a", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "33"}, "CHAPTER 6-1", null, null], [4535, "女神", "「可你呢，你都干了些什么……」", "lem421_011.ogg", "山_山の中１a", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "12"}, "CHAPTER 6-1", null, null], [4536, "白狛", "「我明白了，明白了！请您不要再说了」", "srk421_010.ogg", "山_山の中１a", "bgm36.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 6-1", null, null], [4537, "女神", "「不，你最近颇有些傲慢，不说不行！」", "lem421_012.ogg", "山_山の中１a", "bgm36.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 6-1", null, null], [4538, "白狛", "「难道，您神色不悦也是因为这个……」", "srk421_011.ogg", "山_山の中１a", "bgm36.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 6-1", null, null], [4539, "女神", "「住嘴，给我坐下，坐下！」", "lem421_013.ogg", "山_山の中１a", "bgm36.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 6-1", null, null], [4540, "白狛", "「……啊！？」", "srk421_012.ogg", "山_山の中１a", "bgm36.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 6-1", null, null], [4541, "", "白狛就像条件反射似的一屁股坐在地面上。", null, "山_山の中１a", "bgm36.opus", null, "CHAPTER 6-1", null, null], [4542, "", "那滑稽的模样，看上去根本就不像那个恐怖的祟神。", null, "山_山の中１a", "bgm36.opus", null, "CHAPTER 6-1", null, null], [4543, "", "这个白狛似乎一直都拗不过它姐姐。", null, "山_山の中１a", "bgm36.opus", null, "CHAPTER 6-1", null, null], [4544, "", "尽管姐姐性格有些强硬，但那美丽的容貌对当弟弟的来说也是一份骄傲。", null, "山_山の中１a", "bgm36.opus", null, "CHAPTER 6-1", null, null], [4545, "", "毕竟，这位女神乃是生自玉石之神。", null, "山_山の中１a", "bgm36.opus", null, "CHAPTER 6-1", null, null], [4546, "", "肌肤生于白菱石，骨骼生于铁，血肉生于石灰、玛瑙，眼瞳生于天蓝石——", null, "山_山の中１a", "bgm36.opus", null, "CHAPTER 6-1", null, null], [4547, "", "而那一头金发，则是生于黄翡翠。", null, "山_山の中１a", "bgm36.opus", null, "CHAPTER 6-1", null, null], [4548, "", "尽管那如萤石般耀眼的外貌与其他神祇大为不同，但白狛相信，姐姐大人是最美的。", null, "山_山の中１a", "bgm36.opus", null, "CHAPTER 6-1", null, null], [4549, "", "而自己毕竟是雄性，在美貌面前实在是难以违拗，哪怕对方是自己的姐姐。", null, "山_山の中１a", "bgm36.opus", null, "CHAPTER 6-1", null, null], [4550, "", "白狛一直都是这么说服自己的。", null, "山_山の中１a", "bgm36.opus", null, "CHAPTER 6-1", null, null], [4551, "女神", "「……你在听吗，小狛！听见了就回句话」", "lem421_014.ogg", "山_山の中１a", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "15"}, "CHAPTER 6-1", null, null], [4552, "白狛", "「我明白了，姐姐大人……」", "srk421_013.ogg", "山_山の中１a", "bgm36.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 6-1", null, null], [4553, "白狛", "「反正我就是说不过姐姐大人」", "srk421_014.ogg", "山_山の中１a", "bgm36.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 6-1", null, null], [4554, "", "白狛说罢，女神大人立刻绽开了笑容。", null, "山_山の中１a", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "01"}, "CHAPTER 6-1", null, null], [4555, "女神", "「你明白就好」", "lem421_015.ogg", "山_山の中１a", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "19"}, "CHAPTER 6-1", null, null], [4556, "女神", "「我说这么多，都是为了你好。我可不希望你变成遭人憎恶的荒神」", "lem421_016.ogg", "山_山の中１a", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "12"}, "CHAPTER 6-1", null, null], [4557, "", "真没想到，她这么轻易地就说服了祟神。", null, "山_山の中１a", "bgm36.opus", null, "CHAPTER 6-1", null, null], [4558, "", "说不定，穗织的诅咒也可以找她帮忙……？", null, "山_山の中１a", "bgm36.opus", null, "CHAPTER 6-1", null, null], [4559, "蕾娜", "「（……）」", "len421_011.ogg", "山_山の中１a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "15"}, "CHAPTER 6-1", null, null], [4560, "将臣", "「（……）」", null, "山_山の中１a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "15"}, "CHAPTER 6-1", null, null], [4561, "", "刚才给我使眼色的应该是蕾娜。", null, "山_山の中１a", "bgm36.opus", null, "CHAPTER 6-1", null, null], [4562, "", "这些事我们得尽快告诉大家才行。", null, "山_山の中１a", "bgm36.opus", null, "CHAPTER 6-1", null, null], [4563, "", "想着想着，我的身体开始上浮，有种即将睡醒的感觉……", null, "山_山の中１a", "bgm36.opus", null, "CHAPTER 6-1", null, null], [4564, "", "——睡衣派对结束后，又过去了好几天。", null, "旅館_旅館前c", "bgm35.opus", null, "CHAPTER 6-1", null, null], [4565, "", "顺便一提，大家都回到蕾娜房间之后，我就把我们开始交往的事告诉大家了。", null, "旅館_旅館前c", "bgm35.opus", null, "CHAPTER 6-1", null, null], [4566, "", "但这对大家来说似乎是意料之中的事，每个人都是一脸哭笑不得的表情为我们献上了祝福。", null, "旅館_旅館前c", "bgm35.opus", null, "CHAPTER 6-1", null, null], [4567, "", "常陆也把我们的事转达给了朝武。", null, "旅館_旅館前c", "bgm35.opus", null, "CHAPTER 6-1", null, null], [4568, "", "那天晚上，最后大家还是在同一个房间里睡下了。刚才的梦，就是我们那天晚上做的。", null, "旅館_旅館前c", "bgm35.opus", null, "CHAPTER 6-1", null, null], [4569, "将臣", "「上次做梦之后，又没有新的梦了」", null, "旅館_廊下d", "bgm35.opus", null, "CHAPTER 6-1", null, null], [4570, "", "我背着木刀袋子，长叹了一口气。", null, "旅館_廊下d", "bgm35.opus", null, "CHAPTER 6-1", null, null], [4571, "", "本以为可以趁机会了解更多祟神相关的信息……结果等了这么多天也没进入新的梦境。", null, "旅館_廊下d", "bgm35.opus", null, "CHAPTER 6-1", null, null], [4572, "", "但我还是重新开始了剑道的训练。", null, "旅館_廊下d", "bgm35.opus", null, "CHAPTER 6-1", null, null], [4573, "", "我必须能在关键时刻保护蕾娜才行。", null, "旅館_廊下d", "bgm35.opus", null, "CHAPTER 6-1", null, null], [4574, "", "既然我们梦见了更深层次的内容，也就是说以后的梦境可能会更加危险。", null, "旅館_廊下d", "bgm35.opus", null, "CHAPTER 6-1", null, null], [4575, "", "虽然自从跟合体祟神决战之后，普通的祟神就再也没出现过了。", null, "旅館_廊下d", "bgm35.opus", null, "CHAPTER 6-1", null, null], [4576, "", "但正因如此，我总是有种预感，感觉还有一场最终决战等着我们。", null, "旅館_廊下d", "bgm35.opus", null, "CHAPTER 6-1", null, null], [4577, "将臣", "「这种不好的预感，我当然是希望它不要成真……喔！」", null, "旅館_廊下d", "bgm35.opus", null, "CHAPTER 6-1", null, null], [4578, "将臣", "「蕾娜！」", null, "旅館_廊下d", "bgm44.opus", null, "CHAPTER 6-1", "ev407a", null], [4579, "蕾娜", "「将臣」", "len421_012.ogg", "旅館_廊下d", "bgm44.opus", null, "CHAPTER 6-1", "ev407a", null], [4580, "", "看见蕾娜后，我小跑着来到她身边。", null, "旅館_廊下d", "bgm44.opus", null, "CHAPTER 6-1", "ev407a", null], [4581, "将臣", "「抱歉，你还在忙吗？」", null, "旅館_廊下d", "bgm44.opus", null, "CHAPTER 6-1", "ev407a", null], [4582, "蕾娜", "「没事啦，你刚训练完，也累了吧」", "len421_013.ogg", "旅館_廊下d", "bgm44.opus", null, "CHAPTER 6-1", "ev407a", null], [4583, "", "最近每次训练完之后，我都会借用旅馆的澡堂，洗完澡后就直接去蕾娜的房间。", null, "旅館_廊下d", "bgm44.opus", null, "CHAPTER 6-1", "ev407a", null], [4584, "", "今天回来得似乎有点早了。", null, "旅館_廊下d", "bgm44.opus", null, "CHAPTER 6-1", "ev407a", null], [4585, "蕾娜", "「我这边马上就忙完了，你先去房间等我吧」", "len421_014.ogg", "旅館_廊下d", "bgm44.opus", null, "CHAPTER 6-1", "ev407a", null], [4586, "将臣", "「好的。不过你也真厉害啊，竟然能一次性搬这么多」", null, "旅館_廊下d", "bgm44.opus", null, "CHAPTER 6-1", "ev407a", null], [4587, "将臣", "「应该很重吧？」", null, "旅館_廊下d", "bgm44.opus", null, "CHAPTER 6-1", "ev407a", null], [4588, "蕾娜", "「是的，一开始可辛苦了，但时间长了就习惯了」", "len421_015.ogg", "旅館_廊下d", "bgm44.opus", null, "CHAPTER 6-1", "ev407a", null], [4589, "", "尽管蕾娜正在跟我说话，但她并没有停下脚步。", null, "旅館_廊下d", "bgm44.opus", null, "CHAPTER 6-1", "ev407a", null], [4590, "", "我以前一直以为她干活没那么灵巧，现在看来她还是相当厉害的。", null, "旅館_廊下d", "bgm44.opus", null, "CHAPTER 6-1", "ev407a", null], [4591, "蕾娜", "「我还差得远呢，能有现在的水平，都是多亏了掌柜的教导有方」", "len421_016.ogg", "旅館_廊下d", "bgm44.opus", null, "CHAPTER 6-1", "ev407a", null], [4592, "", "蕾娜显得十分自豪。", null, "旅館_廊下d", "bgm44.opus", null, "CHAPTER 6-1", "ev407a", null], [4593, "将臣", "「你肯定也下了很大的功夫吧？所以，蕾娜……」", null, "旅館_廊下d", "bgm44.opus", null, "CHAPTER 6-1", "ev407a", null], [4594, "蕾娜", "「嗯？……啊」", "len421_017.ogg", "旅館_廊下d", "bgm44.opus", null, "CHAPTER 6-1", "ev407a", null], [4595, "", "我轻轻地吻了吻她的脸颊。", null, "旅館_廊下d", "bgm44.opus", null, "CHAPTER 6-1", "ev407a", null], [4596, "", "我能变得这么积极主动，八成也是受了她的影响。", null, "旅館_廊下d", "bgm44.opus", null, "CHAPTER 6-1", "ev407a", null], [4597, "将臣", "「……我、我想给你点奖励」", null, "旅館_廊下d", "bgm44.opus", null, "CHAPTER 6-1", "ev407a", null], [4598, "", "我不行了。这话说出来实在是太难为情了。", null, "旅館_廊下d", "bgm44.opus", null, "CHAPTER 6-1", "ev407a", null], [4599, "", "而且还叫得这么亲昵……", null, "旅館_廊下d", "bgm44.opus", null, "CHAPTER 6-1", "ev407a", null], [4600, "蕾娜", "「呃、嘿嘿嘿嘿」", "len421_018.ogg", "旅館_廊下d", "bgm44.opus", null, "CHAPTER 6-1", "ev407a", null], [4601, "", "尽管我的爱意表现得如此笨拙，蕾娜也依然露出了一副心荡神迷的幸福笑容。", null, "旅館_廊下d", "bgm44.opus", null, "CHAPTER 6-1", "ev407a", null], [4602, "", "……那笑容太过耀眼，看上去甚至有点傻乎乎的。", null, "旅館_廊下d", "bgm44.opus", null, "CHAPTER 6-1", "ev407a", null], [4603, "蕾娜", "「我……我马上就忙完了，你稍微等我一会儿吧？」", "len421_019.ogg", "旅館_廊下d", "bgm44.opus", null, "CHAPTER 6-1", "ev407a", null], [4604, "蕾娜", "「我马上就弄完了」", "len421_020.ogg", "旅館_廊下d", "bgm44.opus", null, "CHAPTER 6-1", "ev407a", null], [4605, "将臣", "「哎？蕾、蕾娜，你不用这么慌的……」", null, "旅館_廊下d", "bgm44.opus", null, "CHAPTER 6-1", "ev407a", null], [4606, "", "蕾娜搬着叠了五层的菜盘，加速跑了出去。", null, "旅館_廊下d", "bgm44.opus", null, "CHAPTER 6-1", null, null], [4607, "", "她脚步实在太快，一转眼就把我甩在身后了。", null, "旅館_廊下d", "bgm44.opus", null, "CHAPTER 6-1", null, null], [4608, "", "但是菜盘却没有丝毫倾斜，这功夫的确够厉害的。", null, "旅館_廊下d", "bgm44.opus", null, "CHAPTER 6-1", null, null], [4609, "蕾娜", "「我马上就弄完了，马上」", "len421_021.ogg", "旅館_廊下d", "bgm44.opus", null, "CHAPTER 6-1", null, null], [4610, "蕾娜", "「……嘿嘿嘿嘿，耶♪」", "len421_022.ogg", "旅館_廊下d", "bgm44.opus", null, "CHAPTER 6-1", null, null], [4611, "", "她走过拐角之后，似乎还在自言自语。", null, "旅館_廊下d", "bgm44.opus", null, "CHAPTER 6-1", null, null], [4612, "", "大概是一个人在那高兴得又蹦又跳。", null, "旅館_廊下d", "bgm44.opus", null, "CHAPTER 6-1", null, null], [4613, "将臣", "「有点担心啊，不过应该没事吧？」", null, "旅館_廊下d", "bgm44.opus", null, "CHAPTER 6-1", null, null], [4614, "", "随后，我提前来到了蕾娜的房间，在这里等她。", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 6-1", null, null], [4615, "", "我把木刀靠在墙上，自己泡了茶，自己喝了起来。", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 6-1", null, null], [4616, "", "擅自做这种事也不会有什么罪恶感，因为我已经习惯了我们的关系。", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 6-1", null, null], [4617, "将臣", "「不过，一个人独处时，还是会忍不住想到那件事」", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 6-1", null, null], [4618, "", "也就是前几天的做的那个梦。", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 6-1", null, null], [4619, "", "虽然梦境很短，但梦的内容让大家都震惊不已。", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 6-1", null, null], [4620, "安晴", "「竟然是这样……！」", "yas421_001.ogg", "神社_神社内a", "bgm39.opus", {"char": "安晴", "file": "安晴.stand", "dress": "神主", "face": "07"}, "CHAPTER 6-1", null, null], [4621, "芳乃", "「也就是说，还有一位女神是站在人类这边的，是吗？」", "yos421_001.ogg", "神社_神社内a", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "17"}, "CHAPTER 6-1", null, null], [4622, "蕾娜", "「是的！在梦中，姐姐似乎也更有话语权」", "len421_023.ogg", "神社_神社内a", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "17"}, "CHAPTER 6-1", null, null], [4623, "蕾娜", "「只要能找到那位女神大人，说不定就能平定祸祟了」", "len421_024.ogg", "神社_神社内a", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "17"}, "CHAPTER 6-1", null, null], [4624, "将臣", "「我也觉得，这些信息说不定能帮我们找到解除诅咒的方法」", null, "神社_神社内a", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "17"}, "CHAPTER 6-1", null, null], [4625, "芳乃", "「…………」", "yos421_002.ogg", "神社_神社内a", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "37"}, "CHAPTER 6-1", null, null], [4626, "蕾娜", "「芳乃？」", "len421_025.ogg", "神社_神社内a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "34"}, "CHAPTER 6-1", null, null], [4627, "", "但是，朝武听完之后，十分冷静。", null, "神社_神社内a", "bgm39.opus", null, "CHAPTER 6-1", null, null], [4628, "", "甚至可以说是冷淡。", null, "神社_神社内a", "bgm39.opus", null, "CHAPTER 6-1", null, null], [4629, "芳乃", "「你们觉得呢？」", "yos421_003.ogg", "神社_神社内a", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "35"}, "CHAPTER 6-1", null, null], [4630, "茉子", "「这个嘛，我个人会尽量慎重一点」", "mak421_001.ogg", "神社_神社内a", "bgm39.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "07"}, "CHAPTER 6-1", null, null], [4631, "将臣", "「呃，常陆，为什么这么说？」", null, "神社_神社内a", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "35"}, "CHAPTER 6-1", null, null], [4632, "茉子", "「那只白狛本来就憎恶人类，这一点也是不能忽视的吧？」", "mak421_002.ogg", "神社_神社内a", "bgm39.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "34"}, "CHAPTER 6-1", null, null], [4633, "芳乃", "「是的。它甚至可能还主动为诅咒提供过帮助」", "yos421_004.ogg", "神社_神社内a", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "17"}, "CHAPTER 6-1", null, null], [4634, "蕾娜", "「这个……确实有这种可能」", "len421_026.ogg", "神社_神社内a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "12"}, "CHAPTER 6-1", null, null], [4635, "蕾娜", "「但至少还是值得我们去调查一下的吧？」", "len421_027.ogg", "神社_神社内a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "25"}, "CHAPTER 6-1", null, null], [4636, "", "尽管我们这么说，朝武的表情依然很严肃。", null, "神社_神社内a", "bgm39.opus", null, "CHAPTER 6-1", null, null], [4637, "", "本以为前一天的睡衣派对让我们加深了感情，但是我们之间似乎又突然出现了一道深深的沟壑。", null, "神社_神社内a", "bgm39.opus", null, "CHAPTER 6-1", null, null], [4638, "安晴", "「我还是对此抱有希望的」", "yas421_002.ogg", "神社_神社内a", "bgm39.opus", {"char": "安晴", "file": "安晴.stand", "dress": "神主", "face": "08"}, "CHAPTER 6-1", null, null], [4639, "芳乃", "「……爸爸」", "yos421_005.ogg", "神社_神社内a", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "12"}, "CHAPTER 6-1", null, null], [4640, "安晴", "「不过，怎么说呢。丛雨大人是什么意见？」", "yas421_003.ogg", "神社_神社内a", "bgm39.opus", {"char": "安晴", "file": "安晴.stand", "dress": "神主", "face": "04"}, "CHAPTER 6-1", null, null], [4641, "丛雨", "「抱歉，本座也认为慎重点比较好」", "mur421_001.ogg", "神社_神社内a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "27"}, "CHAPTER 6-1", null, null], [4642, "蕾娜", "「不是吧，连小雨都这么说！」", "len421_028.ogg", "神社_神社内a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "25"}, "CHAPTER 6-1", null, null], [4643, "将臣", "「你之前不是说想要找到解除诅咒的线索吗？」", null, "神社_神社内a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "25"}, "CHAPTER 6-1", null, null], [4644, "丛雨", "「当然，本座现在也是这么想的」", "mur421_002.ogg", "神社_神社内a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "26"}, "CHAPTER 6-1", null, null], [4645, "丛雨", "「但是你想想，在传说中，丛雨丸不也是穗织的土地神赐予的神刀吗？」", "mur421_003.ogg", "神社_神社内a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "11"}, "CHAPTER 6-1", null, null], [4646, "将臣", "「嗯，确实是这么流传的」", null, "神社_神社内a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "11"}, "CHAPTER 6-1", null, null], [4647, "蕾娜", "「那既然如此，只要我们拜托土地神，他应该也会帮我们的吧？」", "len421_029.ogg", "神社_神社内a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "11"}, "CHAPTER 6-1", null, null], [4648, "丛雨", "「不，恐怕事情没那么容易」", "mur421_004.ogg", "神社_神社内a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "36"}, "CHAPTER 6-1", null, null], [4649, "丛雨", "「哪怕是丛雨丸，也并不是突然从天而降的」", "mur421_005.ogg", "神社_神社内a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "35"}, "CHAPTER 6-1", null, null], [4650, "丛雨", "「无非是人们刚好找到了这么一把有来历的神刀，所以解释成了“上天赐予”的神刀」", "mur421_006.ogg", "神社_神社内a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "10"}, "CHAPTER 6-1", null, null], [4651, "丛雨", "「就连本座，也从来没亲眼见过土地神大人」", "mur421_007.ogg", "神社_神社内a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "30"}, "CHAPTER 6-1", null, null], [4652, "将臣", "「这……但是，你和丛雨丸都确实存在，这种现象是无法用常识来解释的吧」", null, "神社_神社内a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "30"}, "CHAPTER 6-1", null, null], [4653, "丛雨", "「当然了，本座和丛雨丸肯定受到了神力的庇佑」", "mur421_008.ogg", "神社_神社内a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "10"}, "CHAPTER 6-1", null, null], [4654, "丛雨", "「但是事到如今，你说我们还能得到神力相助……这实在是让人难以相信」", "mur421_009.ogg", "神社_神社内a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "35"}, "CHAPTER 6-1", null, null], [4655, "芳乃", "「抱歉，我也是一样的感受」", "yos421_006.ogg", "神社_神社内a", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "30"}, "CHAPTER 6-1", null, null], [4656, "芳乃", "「对于土地神大人来说，赐予我们丛雨丸应该就是他所能做到的最大的协助了吧」", "yos421_007.ogg", "神社_神社内a", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "46"}, "CHAPTER 6-1", null, null], [4657, "芳乃", "「之后的问题，就只能靠我们自己解决了，我有这种感觉」", "yos421_008.ogg", "神社_神社内a", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "09"}, "CHAPTER 6-1", null, null], [4658, "蕾娜", "「这、这个，现在还不好说吧？」", "len421_030.ogg", "神社_神社内a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "25"}, "CHAPTER 6-1", null, null], [4659, "芳乃", "「嗯……但事实上，这个诅咒已经持续了５００多年……」", "yos421_009.ogg", "神社_神社内a", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "47"}, "CHAPTER 6-1", null, null], [4660, "将臣", "「……！！」", null, "神社_神社内a", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "47"}, "CHAPTER 6-1", null, null], [4661, "", "朝武家一直走在一条望不见尽头的钢丝上。", null, "神社_神社内a", "bgm08.opus", null, "CHAPTER 6-1", null, null], [4662, "", "不仅要避免事故和伤病，还要避免难产等问题。可谓是历经了千辛万苦，才延续到这一代。", null, "神社_神社内a", "bgm08.opus", null, "CHAPTER 6-1", null, null], [4663, "", "我再一次想到了这些事情。", null, "神社_神社内a", "bgm08.opus", null, "CHAPTER 6-1", null, null], [4664, "芳乃", "「都过了这么多年了，你突然说可能会有神灵出来帮忙……」", "yos421_010.ogg", "神社_神社内a", "bgm08.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "12"}, "CHAPTER 6-1", null, null], [4665, "芳乃", "「这我们一时半会儿也难以相信」", "yos421_011.ogg", "神社_神社内a", "bgm08.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "47"}, "CHAPTER 6-1", null, null], [4666, "芳乃", "「如果真的能帮忙，那为什么……为什么不早点出来呢」", "yos421_012.ogg", "神社_神社内a", "bgm08.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "16"}, "CHAPTER 6-1", null, null], [4667, "将臣", "「朝武？」", null, "神社_神社内a", "bgm08.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "16"}, "CHAPTER 6-1", null, null], [4668, "芳乃", "「……没事，我想一个人安静一会儿」", "yos421_013.ogg", "神社_神社内a", "bgm08.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "30"}, "CHAPTER 6-1", null, null], [4669, "", "朝武朝着正殿的方向快步走了过去。", null, "神社_神社内a", "bgm08.opus", null, "CHAPTER 6-1", null, null], [4670, "茉子", "「说实话，芳乃大人的感受我十分理解」", "mak421_003.ogg", "神社_神社内a", "bgm08.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "07"}, "CHAPTER 6-1", null, null], [4671, "将臣", "「……可以想象，她的心情应该很复杂」", null, "神社_神社内a", "bgm08.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "07"}, "CHAPTER 6-1", null, null], [4672, "茉子", "「芳乃大人生性善良，肯定会想到那些没能获救的人们」", "mak421_004.ogg", "神社_神社内a", "bgm08.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "36"}, "CHAPTER 6-1", null, null], [4673, "茉子", "「毕竟，她的母亲、祖母，还有从前的那些祖祖辈辈们，都是因为诅咒……」", "mak421_005.ogg", "神社_神社内a", "bgm08.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "38"}, "CHAPTER 6-1", null, null], [4674, "蕾娜", "「唔，这个…………确实……」", "len421_031.ogg", "神社_神社内a", "bgm08.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "12"}, "CHAPTER 6-1", null, null], [4675, "茉子", "「很抱歉。如果真的有哪位很强的神灵能够拯救朝武家」", "mak421_006.ogg", "神社_神社内a", "bgm08.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "08"}, "CHAPTER 6-1", null, null], [4676, "茉子", "「那也就说明，这几百年间他一直对我们视而不见，见死不救」", "mak421_007.ogg", "神社_神社内a", "bgm08.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "07"}, "CHAPTER 6-1", null, null], [4677, "茉子", "「这样的神，我们是很难信任的，希望你们能理解芳乃大人的心情」", "mak421_008.ogg", "神社_神社内a", "bgm08.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "35"}, "CHAPTER 6-1", null, null], [4678, "美津叶", "「毕竟巫女大人也只是一介学生」", "miz421_001.ogg", "神社_神社内a", "bgm08.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "26"}, "CHAPTER 6-1", null, null], [4679, "美津叶", "「如果你觉得她刚才很冷漠，那其实只是她在刻意让自己冷静下来而已」", "miz421_002.ogg", "神社_神社内a", "bgm08.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "27"}, "CHAPTER 6-1", null, null], [4680, "美津叶", "「如果不那么做，她大概是冷静不下来的」", "miz421_003.ogg", "神社_神社内a", "bgm08.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "09"}, "CHAPTER 6-1", null, null], [4681, "蕾娜", "「……」", "len421_032.ogg", "神社_神社内a", "bgm08.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "07"}, "CHAPTER 6-1", null, null], [4682, "", "虽然早就料到梦境里的事情会让大家感到惊讶。", null, "神社_神社内a", "bgm08.opus", null, "CHAPTER 6-1", null, null], [4683, "", "但这时我才意识到，这些事带给大家的震惊比我想象中的要强烈得多。", null, "神社_神社内a", "bgm08.opus", null, "CHAPTER 6-1", null, null], [4684, "茉子", "「不过，既然有希望，我还是觉得应该调查一下」", "mak421_009.ogg", "神社_神社内a", "bgm08.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "01"}, "CHAPTER 6-1", null, null], [4685, "茉子", "「关于这件事，芳乃大人应该也是同样的看法。那我先告辞了」", "mak421_010.ogg", "神社_神社内a", "bgm08.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "13"}, "CHAPTER 6-1", null, null], [4686, "", "说罢，常陆也离开了房间。", null, "神社_神社内a", "bgm08.opus", null, "CHAPTER 6-1", null, null], [4687, "", "大概是准备去朝武那边吧。", null, "神社_神社内a", "bgm08.opus", null, "CHAPTER 6-1", null, null], [4688, "", "关门的声音显得格外刺耳。在场的所有人都沉默不语。", null, "神社_神社内a", "bgm08.opus", null, "CHAPTER 6-1", null, null], [4689, "", "这时，安晴叔叔抬起了头。", null, "神社_神社内a", "bgm08.opus", null, "CHAPTER 6-1", null, null], [4690, "安晴", "「美津叶大夫，你是不是有什么发现？」", "yas421_004.ogg", "神社_神社内a", "bgm39.opus", {"char": "安晴", "file": "安晴.stand", "dress": "神主", "face": "04"}, "CHAPTER 6-1", null, null], [4691, "安晴", "「我看你几乎还没有发表自己的意见」", "yas421_005.ogg", "神社_神社内a", "bgm39.opus", {"char": "安晴", "file": "安晴.stand", "dress": "神主", "face": "06"}, "CHAPTER 6-1", null, null], [4692, "美津叶", "「嗯，确实是有一些」", "miz421_004.ogg", "神社_神社内a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "01"}, "CHAPTER 6-1", null, null], [4693, "将臣", "「哎！真的吗，驹川大夫？」", null, "神社_神社内a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "01"}, "CHAPTER 6-1", null, null], [4694, "蕾娜", "「那是不是也把芳乃她们叫过来听听比较好？」", "len421_033.ogg", "神社_神社内a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "25"}, "CHAPTER 6-1", null, null], [4695, "美津叶", "「不，这些事情我自己也没那么确定」", "miz421_005.ogg", "神社_神社内a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "25"}, "CHAPTER 6-1", null, null], [4696, "美津叶", "「所以，我觉得最好不要让她们抱太大的希望」", "miz421_006.ogg", "神社_神社内a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "25"}, "CHAPTER 6-1", null, null], [4697, "安晴", "「好的，那就先给我们讲讲你想到了什么吧」", "yas421_006.ogg", "神社_神社内a", "bgm39.opus", {"char": "安晴", "file": "安晴.stand", "dress": "神主", "face": "11"}, "CHAPTER 6-1", null, null], [4698, "美津叶", "「你们刚才说，那个女神生于玉石」", "miz421_007.ogg", "神社_神社内a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "06"}, "CHAPTER 6-1", null, null], [4699, "美津叶", "「我猜，她说不定是生于大理石」", "miz421_008.ogg", "神社_神社内a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "29"}, "CHAPTER 6-1", null, null], [4700, "将臣", "「大……大理石？为什么这么说」", null, "神社_神社内a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "29"}, "CHAPTER 6-1", null, null], [4701, "蕾娜", "「梦里面出现了很多难懂的矿石名称，但好像并没有出现“大理石”」", "len421_034.ogg", "神社_神社内a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "30"}, "CHAPTER 6-1", null, null], [4702, "美津叶", "「大理石是由各种各样的矿物混合而成的」", "miz421_009.ogg", "神社_神社内a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "01"}, "CHAPTER 6-1", null, null], [4703, "美津叶", "「其中大部分都是石灰石，也就是白色的部分」", "miz421_010.ogg", "神社_神社内a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "06"}, "CHAPTER 6-1", null, null], [4704, "美津叶", "「黑色的部分，则是玛瑙」", "miz421_011.ogg", "神社_神社内a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "14"}, "CHAPTER 6-1", null, null], [4705, "", "啊！我记得梦里说，血肉生于石灰、玛瑙。", null, "神社_神社内a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "14"}, "CHAPTER 6-1", null, null], [4706, "将臣", "「梦里还说，肌肤生于白菱石……」", null, "神社_神社内a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "14"}, "CHAPTER 6-1", null, null], [4707, "美津叶", "「白菱石应该就是方解石了」", "miz421_012.ogg", "神社_神社内a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "25"}, "CHAPTER 6-1", null, null], [4708, "美津叶", "「那也是大理石不可或缺的成分之一」", "miz421_013.ogg", "神社_神社内a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "30"}, "CHAPTER 6-1", null, null], [4709, "安晴", "「也就是说！那位女神出生的地方就是……」", "yas421_007.ogg", "神社_神社内a", "bgm39.opus", {"char": "安晴", "file": "安晴.stand", "dress": "神主", "face": "07"}, "CHAPTER 6-1", null, null], [4710, "", "一直都很冷静的安晴叔叔突然兴奋地叫了起来。", null, "神社_神社内a", "bgm39.opus", {"char": "安晴", "file": "安晴.stand", "dress": "神主", "face": "07"}, "CHAPTER 6-1", null, null], [4711, "将臣", "「您知道在哪吗？」", null, "神社_神社内a", "bgm39.opus", {"char": "安晴", "file": "安晴.stand", "dress": "神主", "face": "04"}, "CHAPTER 6-1", null, null], [4712, "安晴", "「是的！虽然离穗织有一点距离，但也属于同一座山脉」", "yas421_008.ogg", "神社_神社内a", "bgm39.opus", {"char": "安晴", "file": "安晴.stand", "dress": "神主", "face": "11"}, "CHAPTER 6-1", null, null], [4713, "安晴", "「那个地方现存着一座采石场」", "yas421_009.ogg", "神社_神社内a", "bgm39.opus", {"char": "安晴", "file": "安晴.stand", "dress": "神主", "face": "13"}, "CHAPTER 6-1", null, null], [4714, "安晴", "「而且，那里的大理石还挺罕见的……我记得是一种黄色的大理石吧？」", "yas421_010.ogg", "神社_神社内a", "bgm39.opus", {"char": "安晴", "file": "安晴.stand", "dress": "神主", "face": "05"}, "CHAPTER 6-1", null, null], [4715, "美津叶", "「应该是的」", "miz421_014.ogg", "神社_神社内a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "05"}, "CHAPTER 6-1", null, null], [4716, "蕾娜", "「女神大人的发色也是因为这个吧？」", "len421_035.ogg", "神社_神社内a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "19"}, "CHAPTER 6-1", null, null], [4717, "蕾娜", "「这么说的话，应、应该就没错了！」", "len421_036.ogg", "神社_神社内a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "03"}, "CHAPTER 6-1", null, null], [4718, "美津叶", "「可是，就算知道了这些，也算不上什么天大的进展吧？」", "miz421_016.ogg", "神社_神社内a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "31"}, "CHAPTER 6-1", null, null], [4719, "美津叶", "「所以我刚才就没有说出来」", "miz421_017.ogg", "神社_神社内a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "32"}, "CHAPTER 6-1", null, null], [4720, "将臣", "「这、这个……好像确实」", null, "神社_神社内a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "32"}, "CHAPTER 6-1", null, null], [4721, "安晴", "「美津叶大夫，你是觉得这个线索值得我们去查一查，是吗？」", "yas421_011.ogg", "神社_神社内a", "bgm39.opus", {"char": "安晴", "file": "安晴.stand", "dress": "神主", "face": "04"}, "CHAPTER 6-1", null, null], [4722, "美津叶", "「是的，在那座采石场附近说不定还留有一些没有传到穗织的民间传说」", "miz421_018.ogg", "神社_神社内a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "06"}, "CHAPTER 6-1", null, null], [4723, "美津叶", "「我觉得可能性并非是零」", "miz421_019.ogg", "神社_神社内a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "14"}, "CHAPTER 6-1", null, null], [4724, "", "唉。现在想找线索都要开始依赖传说了吗。", null, "神社_神社内a", "bgm39.opus", null, "CHAPTER 6-1", null, null], [4725, "", "而且我们甚至无法判断，那些传说到底有没有流传到现在。", null, "神社_神社内a", "bgm39.opus", null, "CHAPTER 6-1", null, null], [4726, "", "毕竟这事本身就很神秘，还过去了这么多年。", null, "神社_神社内a", "bgm39.opus", null, "CHAPTER 6-1", null, null], [4727, "", "这样不确定的事情，确实不应该让她们抱有期待。", null, "神社_神社内a", "bgm39.opus", null, "CHAPTER 6-1", null, null], [4728, "美津叶", "「总之，我会去当地看看」", "miz421_020.ogg", "神社_神社内a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "05"}, "CHAPTER 6-1", null, null], [4729, "美津叶", "「诊所那边就只能叫人来帮忙了……既然能去，还是去碰碰运气比较好」", "miz421_021.ogg", "神社_神社内a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "02"}, "CHAPTER 6-1", null, null], [4730, "美津叶", "「这样总比什么都不做好强」", "miz421_022.ogg", "神社_神社内a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "18"}, "CHAPTER 6-1", null, null], [4731, "将臣", "「好的，拜托您了」", null, "神社_神社内a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "18"}, "CHAPTER 6-1", null, null], [4732, "", "本以为能有什么大的收获，结果却事与愿违。现在，我们只能等着驹川大夫的消息。", null, "旅館_レナの部屋d", "bgm39.opus", null, "CHAPTER 6-1", null, null], [4733, "", "但遗憾的是，她的消息总是断断续续的，也许是因为一直在山间行走吧。", null, "旅館_レナの部屋d", "bgm39.opus", null, "CHAPTER 6-1", null, null], [4734, "", "而且，调查本身似乎也不怎么顺利。", null, "旅館_レナの部屋d", "bgm39.opus", null, "CHAPTER 6-1", null, null], [4735, "", "她每次发来的消息，都是“并没有什么值得一提的收获”。", null, "旅館_レナの部屋d", "bgm39.opus", null, "CHAPTER 6-1", null, null], [4736, "将臣", "「当时驹川大夫没有把自己的想法告诉所有人，现在看来她的判断应该是正确的」", null, "旅館_レナの部屋d", "bgm39.opus", null, "CHAPTER 6-1", null, null], [4737, "将臣", "「大人考虑得还是更全面一些啊」", null, "旅館_レナの部屋d", "bgm39.opus", null, "CHAPTER 6-1", null, null], [4738, "", "如果换成我，我大概会想到什么就立刻说什么。", null, "旅館_レナの部屋d", "bgm39.opus", null, "CHAPTER 6-1", null, null], [4739, "", "这时，我听见一个熟悉的脚步声正在靠近。", null, "旅館_レナの部屋d", "bgm39.opus", null, "CHAPTER 6-1", null, null], [4740, "蕾娜", "「让你久等了，将臣！」", "len421_037.ogg", "旅館_レナの部屋d", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02"}, "CHAPTER 6-1", null, null], [4741, "将臣", "「喔，是蕾娜啊」", null, "旅館_レナの部屋d", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02"}, "CHAPTER 6-1", null, null], [4742, "", "她进来后，我立刻站了起来，向她张开了双臂。", null, "旅館_レナの部屋d", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02"}, "CHAPTER 6-1", null, null], [4743, "蕾娜", "「将臣，我爱你……Ｍｕａ♪」", "len421_038.ogg", "旅館_レナの部屋d", "bgm54.opus", null, "CHAPTER 6-1", "ev403a", null], [4744, "将臣", "「我也爱你，蕾娜」", null, "旅館_レナの部屋d", "bgm54.opus", null, "CHAPTER 6-1", "ev403a", null], [4745, "", "我们刚见面就开始拥抱，亲吻。", null, "旅館_レナの部屋d", "bgm54.opus", null, "CHAPTER 6-1", "ev403a", null], [4746, "", "还不忘加上一句我爱你。", null, "旅館_レナの部屋d", "bgm54.opus", null, "CHAPTER 6-1", "ev403a", null], [4747, "", "这对于以前的我来说，是完全无法想象的。", null, "旅館_レナの部屋d", "bgm54.opus", null, "CHAPTER 6-1", "ev403a", null], [4748, "蕾娜", "「嘿嘿，你是说真的吗？」", "len421_039.ogg", "旅館_レナの部屋d", "bgm54.opus", null, "CHAPTER 6-1", "ev403a", null], [4749, "将臣", "「你在怀疑我？」", null, "旅館_レナの部屋d", "bgm54.opus", null, "CHAPTER 6-1", "ev403a", null], [4750, "蕾娜", "「不是啦，只是觉得……你应该用行动来证明」", "len421_040.ogg", "旅館_レナの部屋d", "bgm54.opus", null, "CHAPTER 6-1", "ev403a", null], [4751, "将臣", "「好……我明白了，那你先闭上眼睛吧」", null, "旅館_レナの部屋d", "bgm54.opus", null, "CHAPTER 6-1", "ev403a", null], [4752, "", "这大概就跟蕾娜打电话时不停地鞠躬是一个道理吧。", null, "旅館_レナの部屋d", "bgm54.opus", null, "CHAPTER 6-1", "ev403a", null], [4753, "", "我似乎也受到了她的影响，日常的行为举止都变得夸张起来了。", null, "旅館_レナの部屋d", "bgm54.opus", null, "CHAPTER 6-1", "ev403a", null], [4754, "蕾娜", "「唔……嗯嗯……♪」", "len421_041.ogg", "旅館_レナの部屋d", "bgm54.opus", null, "CHAPTER 6-1", "ev403a", null], [4755, "蕾娜", "「……嘿嘿，那么……接下来就轮到我了」", "len421_042.ogg", "旅館_レナの部屋d", "bgm54.opus", null, "CHAPTER 6-1", "ev403a", null], [4756, "将臣", "「嗯、嗯……」", null, "旅館_レナの部屋d", "bgm54.opus", null, "CHAPTER 6-1", "ev403a", null], [4757, "蕾娜", "「将臣，唔……嗯～」", "len421_043.ogg", "旅館_レナの部屋d", "bgm54.opus", null, "CHAPTER 6-1", "ev403a", null], [4758, "", "深吻的同时，蕾娜的柔软双峰也紧紧地压在我胸前，每一秒都在考验着我身为男性的理智。", null, "旅館_レナの部屋d", "bgm54.opus", null, "CHAPTER 6-1", "ev403a", null], [4759, "", "我也不清楚……自己到底能绅士到什么时候。", null, "旅館_レナの部屋d", "bgm54.opus", null, "CHAPTER 6-1", "ev403a", null], [4760, "蕾娜", "「呼……嘿嘿，差不多了，再这样下去就停不下来了」", "len421_044.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "10h"}, "CHAPTER 6-1", null, null], [4761, "将臣", "「啊、嗯，也是」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "10h"}, "CHAPTER 6-1", null, null], [4762, "蕾娜", "「难道说，将臣……你还没满足吗？」", "len421_045.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "03h"}, "CHAPTER 6-1", null, null], [4763, "将臣", "「这个……怎么说呢？」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "03h"}, "CHAPTER 6-1", null, null], [4764, "", "当然，我肯定想继续和她拥抱在一起。", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "03h"}, "CHAPTER 6-1", null, null], [4765, "", "但我并不是故意掖着不说。", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "03h"}, "CHAPTER 6-1", null, null], [4766, "", "我只是在想，我们放松成这样真的好吗？我内心的某个角落依然留着一抹不安。", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "03h"}, "CHAPTER 6-1", null, null], [4767, "蕾娜", "「嗯？……将臣，你是不是在想什么事？」", "len421_046.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "28"}, "CHAPTER 6-1", null, null], [4768, "将臣", "「呃，你、你为什么会这么觉得？」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "28"}, "CHAPTER 6-1", null, null], [4769, "蕾娜", "「你刚才没有直视我的眼睛吧？感觉你现在好像有点迷茫」", "len421_047.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27"}, "CHAPTER 6-1", null, null], [4770, "将臣", "「……你太厉害了，蕾娜」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27"}, "CHAPTER 6-1", null, null], [4771, "蕾娜", "「嘿嘿，毕竟是自己喜欢的人，这点事还是能看出来的」", "len421_048.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "03"}, "CHAPTER 6-1", null, null], [4772, "蕾娜", "「来吧来吧，有什么烦恼全都说出来」", "len421_049.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "01"}, "CHAPTER 6-1", null, null], [4773, "蕾娜", "「恋人之间有事隐瞒可不是什么好事哦」", "len421_050.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "23"}, "CHAPTER 6-1", null, null], [4774, "", "确实，我应该说出来。", null, "旅館_レナの部屋d", "bgm54.opus", null, "CHAPTER 6-1", null, null], [4775, "", "我也不想对蕾娜有所隐瞒。", null, "旅館_レナの部屋d", "bgm54.opus", null, "CHAPTER 6-1", null, null], [4776, "将臣", "「其实，就是关于我们做的梦」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "20"}, "CHAPTER 6-1", null, null], [4777, "将臣", "「我害怕直到最后都没取得什么进展，只是让大家白忙活了一阵」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "20"}, "CHAPTER 6-1", null, null], [4778, "蕾娜", "「……驹川大夫，现在都还没回来」", "len421_051.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "29"}, "CHAPTER 6-1", null, null], [4779, "将臣", "「与其让朝武和常陆她们空欢喜一场，还不如一开始就慎重一点，你觉得呢？」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "29"}, "CHAPTER 6-1", null, null], [4780, "将臣", "「说到底，那些梦境也可能仅仅就是一场梦而已，跟现实无关」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 6-1", null, null], [4781, "将臣", "「这种可能性也还是有的吧？」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 6-1", null, null], [4782, "蕾娜", "「唔，但要是我们大家都这么慎重，就没办法取得任何进展了吧」", "len421_052.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "30"}, "CHAPTER 6-1", null, null], [4783, "将臣", "「啊，你说的也是」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "30"}, "CHAPTER 6-1", null, null], [4784, "", "这确实很像外国人的思维方式。", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "30"}, "CHAPTER 6-1", null, null], [4785, "蕾娜", "「我觉得，正因为我们不是本地人，所以有些事情才不用去想那么多」", "len421_053.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 6-1", null, null], [4786, "蕾娜", "「就算有时会误解，有时会搞砸，但这也并不是什么可耻的事」", "len421_054.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "01"}, "CHAPTER 6-1", null, null], [4787, "将臣", "「嗯……」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "01"}, "CHAPTER 6-1", null, null], [4788, "蕾娜", "「也就是说，有些事虽然芳乃和茉子做不到，但是我们可以做到」", "len421_055.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02"}, "CHAPTER 6-1", null, null], [4789, "", "没想到蕾娜也这么认真地考虑过。", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "19"}, "CHAPTER 6-1", null, null], [4790, "", "不，自从那件事发生后，蕾娜或许一直都在思考关于诅咒的事情。", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "19"}, "CHAPTER 6-1", null, null], [4791, "", "所以，她才能毫不犹豫地说出这些话。", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "19"}, "CHAPTER 6-1", null, null], [4792, "蕾娜", "「而且，我觉得梦里发生的事情应该都是真的！」", "len421_056.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 6-1", null, null], [4793, "将臣", "「你说得这么肯定，是有什么依据吗？」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 6-1", null, null], [4794, "蕾娜", "「毕竟是我们俩一起做的梦嘛，肯定是有什么意义在里面的」", "len421_057.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02"}, "CHAPTER 6-1", null, null], [4795, "将臣", "「……哎？」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02"}, "CHAPTER 6-1", null, null], [4796, "", "她一脸笑容，如此断言道。", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02"}, "CHAPTER 6-1", null, null], [4797, "蕾娜", "「那个小狛说它讨厌人类，但我觉得它看上去也不坏」", "len421_058.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27"}, "CHAPTER 6-1", null, null], [4798, "将臣", "「嗯……确实不像是那种真心想要杀掉某个人的样子」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27"}, "CHAPTER 6-1", null, null], [4799, "将臣", "「而且听他们俩的对话，就像是姐弟吵架一样」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27"}, "CHAPTER 6-1", null, null], [4800, "蕾娜", "「是的！吵完架还能和好，就证明关系很好」", "len421_059.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27"}, "CHAPTER 6-1", null, null], [4801, "", "但是，诅咒和祟神也是确实存在的。", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27"}, "CHAPTER 6-1", null, null], [4802, "", "梦境和现实之间存在着巨大的反差，让人不知该如何判断，这就是最困扰我们的问题。", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27"}, "CHAPTER 6-1", null, null], [4803, "将臣", "「嗯，也是！现在想再多可能也没用」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "01"}, "CHAPTER 6-1", null, null], [4804, "将臣", "「现在线索还是太少，不足以得出结论，就算想再多也只能凭空臆测」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "01"}, "CHAPTER 6-1", null, null], [4805, "蕾娜", "「就是呀，胸无妙计，不如蚯蚓」", "len421_060.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02"}, "CHAPTER 6-1", null, null], [4806, "将臣", "「哈哈，是不如休息吧？胸无妙计，不如休息」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02"}, "CHAPTER 6-1", null, null], [4807, "蕾娜", "「休息……休息……嗯，我记住了」", "len421_061.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02"}, "CHAPTER 6-1", null, null], [4808, "", "我摸了摸蕾娜的头，她笑嘻嘻地扭起了身子。", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02"}, "CHAPTER 6-1", null, null], [4809, "蕾娜", "「嘿嘿，再多摸摸」", "len421_062.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "26h"}, "CHAPTER 6-1", null, null], [4810, "将臣", "「好啊」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "26h"}, "CHAPTER 6-1", null, null], [4811, "蕾娜", "「嘻嘻嘻嘻，这种被人摸头的感觉真是停不下来」", "len421_063.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "19h"}, "CHAPTER 6-1", null, null], [4812, "", "蕾娜看上去越来越高兴了。", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "19h"}, "CHAPTER 6-1", null, null], [4813, "将臣", "「总之，要是能再梦见后续的内容就好了」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "01"}, "CHAPTER 6-1", null, null], [4814, "将臣", "「要是能不停地获取新的信息，我们也就不用想来想去，天天烦恼了」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "01"}, "CHAPTER 6-1", null, null], [4815, "蕾娜", "「……说的也是」", "len421_064.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "28"}, "CHAPTER 6-1", null, null], [4816, "蕾娜", "「我们最后一次进入梦境，是睡衣派对的那天晚上吧？」", "len421_065.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "23"}, "CHAPTER 6-1", null, null], [4817, "将臣", "「对，那晚大家都睡在一起，所以我们也是一开始就睡在一起……嗯？」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "23"}, "CHAPTER 6-1", null, null], [4818, "", "只有来蕾娜的房间的那天，我们才会做梦。", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "23"}, "CHAPTER 6-1", null, null], [4819, "", "睡衣派对之前的那几次，我都是因为碎片共鸣，半夜被吸引到了蕾娜那边去……", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "23"}, "CHAPTER 6-1", null, null], [4820, "将臣", "「难道说，我们其实不需要等碎片产生共鸣，只要我们睡在一起就行了？」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "23"}, "CHAPTER 6-1", null, null], [4821, "蕾娜", "「不……不清楚，这、这个不实际试一试谁也不知道」", "len421_066.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "07h"}, "CHAPTER 6-1", null, null], [4822, "", "不知为何，蕾娜满脸通红，两手抱在在一起，忸忸怩怩的。", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "12h"}, "CHAPTER 6-1", null, null], [4823, "将臣", "「但是，这还是值得一试的吧？」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "12h"}, "CHAPTER 6-1", null, null], [4824, "蕾娜", "「…………是、是的，可是」", "len421_067.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "30h"}, "CHAPTER 6-1", null, null], [4825, "将臣", "「怎么了？你刚才不是说了吗，太慎重的话，就无法取得任何进展了」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "30h"}, "CHAPTER 6-1", null, null], [4826, "蕾娜", "「话、话是这么说…………」", "len421_068.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "06h"}, "CHAPTER 6-1", null, null], [4827, "蕾娜", "「那个，你想啊」", "len421_069.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "07h"}, "CHAPTER 6-1", null, null], [4828, "蕾娜", "「这次……大家都不在，是吧？」", "len421_070.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "12h"}, "CHAPTER 6-1", null, null], [4829, "蕾娜", "「也就是说，这次的睡衣派对……只有我和你两个人」", "len421_071.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25h"}, "CHAPTER 6-1", null, null], [4830, "将臣", "「……」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25h"}, "CHAPTER 6-1", null, null], [4831, "将臣", "「…………」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25h"}, "CHAPTER 6-1", null, null], [4832, "将臣", "「……」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25h"}, "CHAPTER 6-1", null, null], [4833, "蕾娜", "「……将臣？」", "len421_072.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "30"}, "CHAPTER 6-1", null, null], [4834, "将臣", "「我……我绝对不会做什么不该做的事，一起睡一晚吧！」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "30"}, "CHAPTER 6-1", null, null], [4835, "", "蕾娜一脸不满地瞪了我一眼。", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "11"}, "CHAPTER 6-1", null, null], [4836, "将臣", "「不、不是那个意思！我刚才没表达清楚，我是想说……」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "11"}, "CHAPTER 6-1", null, null], [4837, "蕾娜", "「我明白……我知道你对那方面的事没那么积极，这些我都明白」", "len421_073.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "12"}, "CHAPTER 6-1", null, null], [4838, "将臣", "「……呃，我觉得还好吧」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "12"}, "CHAPTER 6-1", null, null], [4839, "", "我现在已经尽了最大的努力让自己变得更积极了。", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "12"}, "CHAPTER 6-1", null, null], [4840, "", "但是在外国人眼里，我可能还是很被动。", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "12"}, "CHAPTER 6-1", null, null], [4841, "", "但我又觉得，这种事不能拿民族文化的差异来当借口。", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "12"}, "CHAPTER 6-1", null, null], [4842, "将臣", "「这话自己说出来有点那什么，但是你对我来说真的很重要，我想好好珍惜你」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "12"}, "CHAPTER 6-1", null, null], [4843, "将臣", "「怎么说呢，我不希望对自己的欲望太过于忠实」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "34"}, "CHAPTER 6-1", null, null], [4844, "蕾娜", "「唔——」", "len421_074.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 6-1", null, null], [4845, "将臣", "「呃……那个，蕾娜小姐？」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 6-1", null, null], [4846, "蕾娜", "「……唔————」", "len421_075.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "09"}, "CHAPTER 6-1", null, null], [4847, "", "我用手指戳了戳她那因为生气而故意鼓起的脸颊。", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "09"}, "CHAPTER 6-1", null, null], [4848, "蕾娜", "「唔……哼，将臣！你也真是的，我可是在生气呢」", "len421_076.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "09"}, "CHAPTER 6-1", null, null], [4849, "将臣", "「你这哪里是生气，明明就是为了掩饰心里的高兴，故意装出来的吧？」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "09"}, "CHAPTER 6-1", null, null], [4850, "", "说是生气，可嘴角和眼角却还微微挂着笑意。", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "24"}, "CHAPTER 6-1", null, null], [4851, "", "这种情况下，还是神态举止更夸张的女孩子比较好懂。", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "24"}, "CHAPTER 6-1", null, null], [4852, "蕾娜", "「那还不是因为……你说你要好好珍惜我」", "len421_077.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "12h"}, "CHAPTER 6-1", null, null], [4853, "将臣", "「那是我的真心话」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "12h"}, "CHAPTER 6-1", null, null], [4854, "蕾娜", "「……唔————可是问题并不在这里呀」", "len421_078.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "06"}, "CHAPTER 6-1", null, null], [4855, "将臣", "「那你要我怎么做，才能原谅我呢？」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "06"}, "CHAPTER 6-1", null, null], [4856, "蕾娜", "「……」", "len421_079.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 6-1", null, null], [4857, "", "蕾娜使劲摇了摇头，然后直勾勾地看着我的脸。", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 6-1", null, null], [4858, "", "蕾娜的举动真是好懂。", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 6-1", null, null], [4859, "蕾娜", "「你是说愿意陪我做任何事吗？」", "len421_080.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "29"}, "CHAPTER 6-1", null, null], [4860, "将臣", "「……嗯，算是吧」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "29"}, "CHAPTER 6-1", null, null], [4861, "蕾娜", "「既然如此……」", "len421_081.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "15"}, "CHAPTER 6-1", null, null], [4862, "蕾娜", "「那你就陪我约会吧」", "len421_082.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "22"}, "CHAPTER 6-1", null, null], [4863, "", "哎？仔细想想也是，我们还从来没约会过。", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "22"}, "CHAPTER 6-1", null, null], [4864, "蕾娜", "「…………只要你愿意陪我约会，我就跟你一起睡」", "len421_083.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27"}, "CHAPTER 6-1", null, null], [4865, "将臣", "「这、这个……」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27"}, "CHAPTER 6-1", null, null], [4866, "蕾娜", "「不愿意吗？」", "len421_084.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "30"}, "CHAPTER 6-1", null, null], [4867, "将臣", "「那倒不是……只是约会就够了吗？说实话，这怎么想都是我占便宜」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "30"}, "CHAPTER 6-1", null, null], [4868, "蕾娜", "「……是的」", "len421_085.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "23"}, "CHAPTER 6-1", null, null], [4869, "蕾娜", "「其实，就算被你突然推倒……我也没什么意见」", "len421_086.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "04"}, "CHAPTER 6-1", null, null], [4870, "蕾娜", "「但是，我……我毕竟是第一次，所、所以还是想一步步来……希望你，尽量温柔点」", "len421_087.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "12h"}, "CHAPTER 6-1", null, null], [4871, "将臣", "「等、等等！虽然是说要一起睡，但是……哎！？」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "12h"}, "CHAPTER 6-1", null, null], [4872, "蕾娜", "「哎，你就不要再让我继续说下去了，人家好歹也是个女生呀」", "len421_088.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25h"}, "CHAPTER 6-1", null, null], [4873, "蕾娜", "「……你虽然说你要好好珍惜我」", "len421_089.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "29h"}, "CHAPTER 6-1", null, null], [4874, "蕾娜", "「但是，都已经告了白……成了名正言顺的恋人了，要是还像以前那么拘谨，就太奇怪了」", "len421_090.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "29h"}, "CHAPTER 6-1", null, null], [4875, "将臣", "「是、是吗……？」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "29h"}, "CHAPTER 6-1", null, null], [4876, "蕾娜", "「就是啊！女生其实也不希望，自己最……最喜欢的人对自己这么拘谨」", "len421_091.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "22h"}, "CHAPTER 6-1", null, null], [4877, "", "我也不知道一般情况下应该怎样。", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "22h"}, "CHAPTER 6-1", null, null], [4878, "", "但至少，蕾娜说的这些肯定都是真心话。", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "22h"}, "CHAPTER 6-1", null, null], [4879, "", "可是我至今为止一直都在克制着自己，现在让我突然切换，还真挺难的。", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "22h"}, "CHAPTER 6-1", null, null], [4880, "蕾娜", "「难道……我说这些让你很为难吗？」", "len421_092.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "12"}, "CHAPTER 6-1", null, null], [4881, "将臣", "「怎、怎么可能呢！我当然很高兴了，只是……呃，怎么说呢」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "12"}, "CHAPTER 6-1", null, null], [4882, "将臣", "「嗯，我只需要对自己诚实一点就行了？」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "12"}, "CHAPTER 6-1", null, null], [4883, "", "蕾娜高兴的时候，肯定会毫无保留地表现自己的喜悦。", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "12"}, "CHAPTER 6-1", null, null], [4884, "将臣", "「说实话，我也非常高兴！只是没想到会这么快而已，为难肯定不至于的」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "12"}, "CHAPTER 6-1", null, null], [4885, "蕾娜", "「将臣……你是说真的吗？」", "len421_093.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "20"}, "CHAPTER 6-1", null, null], [4886, "将臣", "「当然了，所以，也让我再正式邀请你吧」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "20"}, "CHAPTER 6-1", null, null], [4887, "将臣", "「蕾娜，跟我一起去约会吧！」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "20"}, "CHAPTER 6-1", null, null], [4888, "蕾娜", "「好的！我非常愿意」", "len421_094.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02"}, "CHAPTER 6-1", null, null], [4889, "", "就这样，我们喜笑颜开地拥抱在一起。果然，还是这样坦诚相待比较舒服。", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "19"}, "CHAPTER 6-1", null, null], [4890, "", "话虽如此，这种时候还是会觉得穗织很不方便。", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "19"}, "CHAPTER 6-1", null, null], [4891, "将臣", "「可是，这里真的有什么适合约会的地方吗？」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "19"}, "CHAPTER 6-1", null, null], [4892, "将臣", "「还要先查查看有什么好地方才行」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "19"}, "CHAPTER 6-1", null, null], [4893, "蕾娜", "「……嘿嘿，我要求没那么高的啦」", "len421_095.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27"}, "CHAPTER 6-1", null, null], [4894, "蕾娜", "「对我来说，只要能在一起享受二人世界就足够了」", "len421_096.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "24"}, "CHAPTER 6-1", null, null], [4895, "将臣", "「真的吗？仅仅这样就够了？」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "24"}, "CHAPTER 6-1", null, null], [4896, "蕾娜", "「是的，而且之前我才刚休息过呢」", "len421_097.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "21"}, "CHAPTER 6-1", null, null], [4897, "蕾娜", "「毕竟在旅馆工作，休息日总是不固定的」", "len421_098.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "10"}, "CHAPTER 6-1", null, null], [4898, "", "这么说也是。", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "23"}, "CHAPTER 6-1", null, null], [4899, "", "我再一次意识到在旅馆工作是一件多么辛苦的事。", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "23"}, "CHAPTER 6-1", null, null], [4900, "将臣", "「但是这样一来，我们能做的事就很有限了」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "23"}, "CHAPTER 6-1", null, null], [4901, "将臣", "「先让我想想看能做些什么吧」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "23"}, "CHAPTER 6-1", null, null], [4902, "蕾娜", "「嗯……嘿嘿，已经开始有点期待了」", "len421_099.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27"}, "CHAPTER 6-1", null, null], [4903, "将臣", "「嗯，我也是」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27"}, "CHAPTER 6-1", null, null], [4904, "", "而且，我们不仅仅是约会。", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27"}, "CHAPTER 6-1", null, null], [4905, "", "约会完之后，我们……哎，现在已经期待得不行了。", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27"}, "CHAPTER 6-1", null, null], [4906, "", "看来，我根本就没有当绅士的潜质。", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27"}, "CHAPTER 6-1", null, null], [4907, "蕾娜", "「将臣！」", "len421_100.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02h"}, "CHAPTER 6-1", null, null], [4908, "", "蕾娜再一次抱了上来。", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02h"}, "CHAPTER 6-1", null, null], [4909, "将臣", "「哈哈，你今天真热情啊……难道不应该把这份力气留到约会那天吗？」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "19h"}, "CHAPTER 6-1", null, null], [4910, "蕾娜", "「没事的啦，这并不是打招呼的拥抱……是表达爱意的拥抱」", "len421_101.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27h"}, "CHAPTER 6-1", null, null], [4911, "蕾娜", "「充满爱意的拥抱，想抱几次就抱几次」", "len421_102.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "01h"}, "CHAPTER 6-1", null, null], [4912, "蕾娜", "「将臣……」", "len421_103.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "19h"}, "CHAPTER 6-1", null, null], [4913, "将臣", "「……蕾娜」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "19h"}, "CHAPTER 6-1", null, null], [4914, "", "我们闭上双眼，亲吻着对方。", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "19h"}, "CHAPTER 6-1", null, null], [4915, "蕾娜", "「唔……」", "len421_104.ogg", "旅館_レナの部屋d", "bgm54.opus", null, "CHAPTER 6-1", "ev403a", null], [4916, "将臣", "「这……这也不是打招呼的亲吻」", null, "旅館_レナの部屋d", "bgm54.opus", null, "CHAPTER 6-1", "ev403a", null], [4917, "将臣", "「这是表达爱意的吻哦，蕾娜」", null, "旅館_レナの部屋d", "bgm54.opus", null, "CHAPTER 6-1", "ev403a", null], [4918, "蕾娜", "「噗、哈哈哈……你是不是在强迫自己说这些呀，将臣」", "len421_105.ogg", "旅館_レナの部屋d", "bgm54.opus", null, "CHAPTER 6-1", "ev403a", null], [4919, "将臣", "「呃，但这是我的真实想法」", null, "旅館_レナの部屋d", "bgm54.opus", null, "CHAPTER 6-1", "ev403a", null], [4920, "蕾娜", "「我知道……我知道你为了配合我，在努力地改变自己」", "len421_106.ogg", "旅館_レナの部屋d", "bgm54.opus", null, "CHAPTER 6-1", "ev403a", null], [4921, "蕾娜", "「一想到这里，我就非常开心」", "len421_107.ogg", "旅館_レナの部屋d", "bgm54.opus", null, "CHAPTER 6-1", "ev403a", null], [4922, "蕾娜", "「……将臣，我最喜欢你了」", "len421_108.ogg", "旅館_レナの部屋d", "bgm54.opus", null, "CHAPTER 6-1", "ev403a", null], [4923, "", "她的双唇再一次压了上来。", null, "旅館_レナの部屋d", "bgm54.opus", null, "CHAPTER 6-1", "ev403a", null], [4924, "", "穗织的诅咒能否解开，如今只能依靠我们的线索。虽然这并非我们所愿。", null, "旅館_レナの部屋d", "bgm54.opus", null, "CHAPTER 6-1", "ev403a", null], [4925, "", "但尽管如此，现在我们也做不了别的事。", null, "旅館_レナの部屋d", "bgm54.opus", null, "CHAPTER 6-1", "ev403a", null], [4926, "", "既然这样，那还不如把宝贵的时间花在自己最重要的人身上。", null, "旅館_レナの部屋d", "bgm54.opus", null, "CHAPTER 6-1", "ev403a", null], [4927, "", "这样总比整天闷闷不乐要健康得多。", null, "旅館_レナの部屋d", "bgm54.opus", null, "CHAPTER 6-1", "ev403a", null], [4928, "", "晨练结束后，我按照昨晚的约定，在上学路上和蕾娜会合。", null, "街_通学路a", "bgm54.opus", null, "CHAPTER 6-2", null, null], [4929, "蕾娜", "「将臣——！早上好」", "len422_001.ogg", "街_通学路a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 6-2", null, null], [4930, "", "到达约定的地点后，蕾娜使劲挥着双手，一蹦一跳地来迎接我。", null, "街_通学路a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 6-2", null, null], [4931, "", "我也小跑着赶了过去，刚走到跟前就是一个充满激情的拥抱。", null, "街_通学路a", "bgm44.opus", null, "CHAPTER 6-2", null, null], [4932, "将臣", "「早上好，蕾娜」", null, "街_通学路a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 6-2", null, null], [4933, "蕾娜", "「嘿嘿，今天我也很爱你哦，将臣」", "len422_002.ogg", "街_通学路a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 6-2", null, null], [4934, "将臣", "「我也爱你」", null, "街_通学路a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 6-2", null, null], [4935, "", "紧接着就是清晨的热吻。这一从拥抱到接吻的流程已经成为我们互道早安时的日常流程了。", null, "街_通学路a", "bgm44.opus", null, "CHAPTER 6-2", "ev403a", null], [4936, "", "她的一举一动依然像个好莱坞电影的出场角色一样。但没办法，毕竟我的女朋友就是连好莱坞女星也比不上。", null, "街_通学路a", "bgm44.opus", null, "CHAPTER 6-2", "ev403a", null], [4937, "蕾娜", "「Ｍｕａ……嘿嘿，今天好期待哦」", "len422_003.ogg", "街_通学路a", "bgm44.opus", null, "CHAPTER 6-2", "ev403a", null], [4938, "将臣", "「虽然我也很期待，但真的这样就可以了吗？」", null, "街_通学路a", "bgm44.opus", null, "CHAPTER 6-2", "ev403a", null], [4939, "", "昨晚，我们就约会的事商量了一番。", null, "街_通学路a", "bgm44.opus", null, "CHAPTER 6-2", "ev403a", null], [4940, "", "商量的结果就是，今天我们就像约会一样碰头，然后以约会一样的心情度过一整天。", null, "街_通学路a", "bgm44.opus", null, "CHAPTER 6-2", "ev403a", null], [4941, "蕾娜", "「放学之后我要去干活，你得去练剑道吧？」", "len422_004.ogg", "街_通学路a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 6-2", null, null], [4942, "将臣", "「嗯，而且今天也不是周末，还得像平常一样去上学」", null, "街_通学路a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 6-2", null, null], [4943, "蕾娜", "「……跟平常不一样的」", "len422_005.ogg", "街_通学路a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 6-2", null, null], [4944, "蕾娜", "「至少对我来说，只要能跟你在一起……就跟平时大有不同了，更谈不上理所当然」", "len422_006.ogg", "街_通学路a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 6-2", null, null], [4945, "蕾娜", "「这对我来说就是特别的日子」", "len422_007.ogg", "街_通学路a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19h"}, "CHAPTER 6-2", null, null], [4946, "", "啊，原来她这么喜欢我啊。", null, "街_通学路a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19h"}, "CHAPTER 6-2", null, null], [4947, "", "我既觉得高兴，又觉得自己有点配不上她。但与此同时，心里也涌出一股斗志，告诫我无论如何都要好好珍惜她才行。", null, "街_通学路a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19h"}, "CHAPTER 6-2", null, null], [4948, "", "因为……", null, "街_通学路a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19h"}, "CHAPTER 6-2", null, null], [4949, "将臣", "「自从我们关系亲近了之后，我感觉每天对我来说都很特别」", null, "街_通学路a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19h"}, "CHAPTER 6-2", null, null], [4950, "蕾娜", "「嘿嘿，真的吗？我倒是觉得，最开始你根本就没把我当女孩子看」", "len422_008.ogg", "街_通学路a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 6-2", null, null], [4951, "将臣", "「我觉得应该不至于吧，不过，现在回想起来」", null, "街_通学路a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 6-2", null, null], [4952, "将臣", "「每一份回忆，对我们来说似乎都有着特别的含义」", null, "街_通学路a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 6-2", null, null], [4953, "", "我们的初次相遇，竟然是在坡道上相撞，这简直跟烂俗的恋爱喜剧一样。", null, "街_通学路a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 6-2", null, null], [4954, "", "命运……这种更加烂俗的词汇甚至能直接拿来形容我们的邂逅。", null, "街_通学路a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 6-2", null, null], [4955, "蕾娜", "「将臣……也许真的是那样吧。不，肯定是那样！」", "len422_009.ogg", "街_通学路a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "18"}, "CHAPTER 6-2", null, null], [4956, "蕾娜", "「我能这么喜欢你，这其中肯定有一些特别的意义！」", "len422_010.ogg", "街_通学路a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 6-2", null, null], [4957, "将臣", "「哈哈，是吧」", null, "街_通学路a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 6-2", null, null], [4958, "将臣", "「那我们差不多该走了」", null, "街_通学路a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 6-2", null, null], [4959, "", "我就像平常一样，准备牵手……咦？", null, "街_通学路a", "bgm44.opus", null, "CHAPTER 6-2", null, null], [4960, "", "正准备牵的时候，蕾娜躲开了我的手。", null, "街_通学路a", "bgm44.opus", null, "CHAPTER 6-2", null, null], [4961, "", "紧接着，她把胳膊挽了过来。", null, "街_通学路a", "bgm44.opus", null, "CHAPTER 6-2", null, null], [4962, "蕾娜", "「都已经是恋人了……仅仅牵手是不够的」", "len422_011.ogg", "街_通学路a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 6-2", null, null], [4963, "将臣", "「可、可是，这里是乡下，上学路上就这样是不是太惹眼了啊？」", null, "街_通学路a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 6-2", null, null], [4964, "蕾娜", "「唔，将臣？今天咱们不是约好了，要像约会一样度过一整天吗？」", "len422_012.ogg", "街_通学路a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 6-2", null, null], [4965, "将臣", "「……确实」", null, "街_通学路a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 6-2", null, null], [4966, "", "虽然非常难为情，但说实话，我也挺想试试这种的。", null, "街_通学路a", "bgm44.opus", null, "CHAPTER 6-2", null, null], [4967, "", "而且……今晚，我说不定就要和蕾娜共度良宵了。", null, "街_通学路a", "bgm44.opus", null, "CHAPTER 6-2", null, null], [4968, "", "想想就觉得又开心又羞涩，感觉情绪都要变得不正常了。", null, "街_通学路a", "bgm44.opus", null, "CHAPTER 6-2", null, null], [4969, "", "毕竟，现在顶在我胳膊上的触感就是……", null, "街_通学路a", "bgm44.opus", null, "CHAPTER 6-2", null, null], [4970, "", "啊，现在的我实在是太过幸福，幸福到想要感谢母亲的养育之恩，想要感谢世间万物。", null, "街_通学路a", "bgm44.opus", null, "CHAPTER 6-2", null, null], [4971, "蕾娜", "「对了对了，今天我给你做了便当！」", "len422_013.ogg", "街_通学路a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 6-2", null, null], [4972, "将臣", "「真的吗！？是你亲手做的？」", null, "街_通学路a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 6-2", null, null], [4973, "蕾娜", "「那当然啦」", "len422_014.ogg", "街_通学路a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "15"}, "CHAPTER 6-2", null, null], [4974, "", "感谢有女孩子为我亲手做便当！", null, "街_通学路a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "15"}, "CHAPTER 6-2", null, null], [4975, "将臣", "「嗯？说起来，今早常陆还跟我说什么做不了便当了，难道……？」", null, "街_通学路a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "15"}, "CHAPTER 6-2", null, null], [4976, "蕾娜", "「……是的，我提前跟她商量了」", "len422_015.ogg", "街_通学路a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 6-2", null, null], [4977, "", "感谢！", null, "街_通学路a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 6-2", null, null], [4978, "蕾娜", "「我为了做好日本料理，不仅找了厨师长，还向大家都讨教了一番」", "len422_016.ogg", "街_通学路a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "17"}, "CHAPTER 6-2", null, null], [4979, "蕾娜", "「便当的做法我也偷偷学习了一段时间……就为了有朝一日能让你吃上我做的便当」", "len422_017.ogg", "街_通学路a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 6-2", null, null], [4980, "将臣", "「原来是这样！」", null, "街_通学路a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 6-2", null, null], [4981, "", "谢谢大家！", null, "街_通学路a", "bgm44.opus", null, "CHAPTER 6-2", null, null], [4982, "", "最应该感谢的还是蕾娜。", null, "街_通学路a", "bgm44.opus", null, "CHAPTER 6-2", null, null], [4983, "", "感谢你成为我的女朋友！", null, "街_通学路a", "bgm44.opus", null, "CHAPTER 6-2", null, null], [4984, "", "现在我的心里全都是感激之情。", null, "街_通学路a", "bgm44.opus", null, "CHAPTER 6-2", null, null], [4985, "蕾娜", "「那个，将臣……？」", "len422_018.ogg", "学院_学院前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 6-2", null, null], [4986, "蕾娜", "「你……有多么喜欢我？」", "len422_019.ogg", "学院_学院前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 6-2", null, null], [4987, "", "正当我们看见教学楼时，蕾娜突然抛出了一个所有女朋友都会问的问题。", null, "学院_学院前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 6-2", null, null], [4988, "", "但是今天的我跟平时并不一样。", null, "学院_学院前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 6-2", null, null], [4989, "将臣", "「那还用问吗，我当然是全球第一爱你了！」", null, "学院_学院前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 6-2", null, null], [4990, "蕾娜", "「嘿嘿嘿，那我就是……太阳系第一爱你」", "len422_020.ogg", "学院_学院前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "18"}, "CHAPTER 6-2", null, null], [4991, "将臣", "「那我就是银河系第一」", null, "学院_学院前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "18"}, "CHAPTER 6-2", null, null], [4992, "", "换成平时，就算是开玩笑我应该也不会这么说。", null, "学院_学院前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "18"}, "CHAPTER 6-2", null, null], [4993, "", "但是现在，我大概是一副非常认真的表情。", null, "学院_学院前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "18"}, "CHAPTER 6-2", null, null], [4994, "蕾娜", "「那我就是宇宙第一爱你！」", "len422_021.ogg", "学院_学院前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "24"}, "CHAPTER 6-2", null, null], [4995, "将臣", "「唔……宇宙啊，那我……呃，还有比宇宙更大的东西吗？」", null, "学院_学院前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "24"}, "CHAPTER 6-2", null, null], [4996, "蕾娜", "「嘿嘿，认输了吧，将臣」", "len422_022.ogg", "学院_学院前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "15"}, "CHAPTER 6-2", null, null], [4997, "", "……原来这还有输赢的吗？", null, "学院_学院前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "15"}, "CHAPTER 6-2", null, null], [4998, "", "我在心里默默地吐槽。但是现在的我，当然是本性比理性更胜一筹。", null, "学院_学院前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "15"}, "CHAPTER 6-2", null, null], [4999, "将臣", "「好不甘心啊，我可不觉得自己输了」", null, "学院_学院前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "15"}, "CHAPTER 6-2", null, null], [5000, "蕾娜", "「既然如此，那我就承认你也是宇宙第一爱我吧」", "len422_023.ogg", "学院_学院前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 6-2", null, null], [5001, "将臣", "「哎，我也是？」", null, "学院_学院前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 6-2", null, null], [5002, "蕾娜", "「嗯，这样一来……我们就一样了。咱们都是宇宙第一！」", "len422_024.ogg", "学院_学院前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 6-2", null, null], [5003, "将臣", "「是吗，我们都是宇宙第一啊」", null, "学院_学院前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 6-2", null, null], [5004, "蕾娜", "「将臣……我宇宙第一爱你哦」", "len422_025.ogg", "学院_学院前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 6-2", null, null], [5005, "将臣", "「我也宇宙第一爱你……」", null, "学院_学院前a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 6-2", null, null], [5006, "玄十郎", "「…………」", "gen422_001.ogg", "学院_学院前a", "bgm44.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "01"}, "CHAPTER 6-2", null, null], [5007, "", "咦？刚才好像有个认识的人背着脸走了过去……？", null, "学院_学院前a", "bgm25.opus", null, "CHAPTER 6-2", null, null], [5008, "将臣", "「外公！你怎么还在学校啊！？」", null, "学院_学院前a", "bgm25.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "17"}, "CHAPTER 6-2", null, null], [5009, "蕾娜", "「大、大当家！？」", "len422_026.ogg", "学院_学院前a", "bgm25.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "05"}, "CHAPTER 6-2", null, null], [5010, "玄十郎", "「那……那什么，陪你练完之后，几位老师过来找我」", "gen422_002.ogg", "学院_学院前a", "bgm25.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "17"}, "CHAPTER 6-2", null, null], [5011, "玄十郎", "「我刚才一直在跟他们下围棋呢」", "gen422_003.ogg", "学院_学院前a", "bgm25.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "10"}, "CHAPTER 6-2", null, null], [5012, "将臣", "「……难道，刚才那些，你都看见了，听见了？」", null, "学院_学院前a", "bgm25.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "10"}, "CHAPTER 6-2", null, null], [5013, "玄十郎", "「放松点，不要紧的」", "gen422_004.ogg", "学院_学院前a", "bgm25.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "07"}, "CHAPTER 6-2", null, null], [5014, "将臣", "「什么不要紧！？」", null, "学院_学院前a", "bgm25.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "07"}, "CHAPTER 6-2", null, null], [5015, "玄十郎", "「年轻人有各种事情是很正常的」", "gen422_005.ogg", "学院_学院前a", "bgm25.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "03"}, "CHAPTER 6-2", null, null], [5016, "", "……杀了我吧。", null, "学院_学院前a", "bgm25.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "03"}, "CHAPTER 6-2", null, null], [5017, "玄十郎", "「咳咳，总之，将臣啊」", "gen422_006.ogg", "学院_学院前a", "bgm25.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "01"}, "CHAPTER 6-2", null, null], [5018, "玄十郎", "「那个……你也是个男人，要么就对自己的行为负责，要么就不要做负不起责任的事情」", "gen422_007.ogg", "学院_学院前a", "bgm25.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "09"}, "CHAPTER 6-2", null, null], [5019, "将臣", "「……」", null, "学院_学院前a", "bgm25.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "05"}, "CHAPTER 6-2", null, null], [5020, "蕾娜", "「……」", "len422_027.ogg", "学院_学院前a", "bgm25.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "30h"}, "CHAPTER 6-2", null, null], [5021, "", "说实话，我根本无法直视外公的眼睛。", null, "学院_学院前a", "bgm25.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "17"}, "CHAPTER 6-2", null, null], [5022, "玄十郎", "「将臣，难道你……」", "gen422_008.ogg", "学院_学院前a", "bgm25.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "07"}, "CHAPTER 6-2", null, null], [5023, "将臣", "「没，还没！现在还没啊」", null, "学院_学院前a", "bgm25.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "07"}, "CHAPTER 6-2", null, null], [5024, "蕾娜", "「将……将臣，你、你这样越说越容易被怀疑啊」", "len422_028.ogg", "学院_学院前a", "bgm25.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 6-2", null, null], [5025, "", "最恐怖的是，比刚才这些更加羞耻的样子之前可能也被外公看到了。", null, "学院_学院前a", "bgm25.opus", null, "CHAPTER 6-2", null, null], [5026, "", "事到如今，这也不算什么了。", null, "学院_学院前a", "bgm25.opus", null, "CHAPTER 6-2", null, null], [5027, "", "真没想到会被外公看见，这可不是闹着玩的。", null, "学院_学院前a", "bgm25.opus", null, "CHAPTER 6-2", null, null], [5028, "玄十郎", "「虽然还有些事想提醒你……不过也罢」", "gen422_009.ogg", "学院_学院前a", "bgm25.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "18"}, "CHAPTER 6-2", null, null], [5029, "玄十郎", "「我们老年人也不应该对你们年轻人的恋爱说三道四」", "gen422_010.ogg", "学院_学院前a", "bgm25.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "15"}, "CHAPTER 6-2", null, null], [5030, "", "看来，外公好像是决定不再深究了？", null, "学院_学院前a", "bgm25.opus", null, "CHAPTER 6-2", null, null], [5031, "", "不过，外公刚才说了……要么就对自己的行为负责，要么就不要做负不起责任的事情。", null, "学院_学院前a", "bgm25.opus", null, "CHAPTER 6-2", null, null], [5032, "", "确实，他说的很对。", null, "学院_学院前a", "bgm25.opus", null, "CHAPTER 6-2", null, null], [5033, "", "虽然我觉得现在的情况已经发展得让我负不起责任了。", null, "学院_学院前a", "bgm25.opus", null, "CHAPTER 6-2", null, null], [5034, "", "尽管刚开场就挨了一记痛入心脾的反击拳，但上午的时光还是安稳地过去了。", null, "学院_教室休憩a", "bgm25.opus", null, "CHAPTER 6-2", null, null], [5035, "", "当我终于从重创中恢复时，刚好到了中午。", null, "学院_教室休憩a", "bgm25.opus", null, "CHAPTER 6-2", null, null], [5036, "蕾娜", "「将臣！现在是吃便当的时间了」", "len422_029.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 6-2", null, null], [5037, "将臣", "「嗯，我们一起吃吧」", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 6-2", null, null], [5038, "", "说实话，我一直都在等待这一刻！", null, "学院_教室休憩a", "bgm04.opus", null, "CHAPTER 6-2", null, null], [5039, "", "今早听说蕾娜为我做了便当时，我其实心里期待得不得了。", null, "学院_教室休憩a", "bgm04.opus", null, "CHAPTER 6-2", null, null], [5040, "廉太郎", "「喔，怎么了？今天不跟我们一起吃吗？」", "ren422_001.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "32"}, "CHAPTER 6-2", null, null], [5041, "将臣", "「抱歉，没跟你说吗？」", null, "学院_教室休憩a", "bgm04.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "32"}, "CHAPTER 6-2", null, null], [5042, "蕾娜", "「嗯……我跟将臣说好了，今天我们要像约会一样度过」", "len422_030.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 6-2", null, null], [5043, "廉太郎", "「还有这么新颖的玩法啊」", "ren422_002.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "29"}, "CHAPTER 6-2", null, null], [5044, "廉太郎", "「难道女孩子们都突然不见了，也是因为这个吗？」", "ren422_003.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "07"}, "CHAPTER 6-2", null, null], [5045, "", "还真是。朝武和常陆已经不在教室里了。", null, "学院_教室休憩a", "bgm04.opus", null, "CHAPTER 6-2", null, null], [5046, "", "她们难道是为了我们着想，所以特意跑到别处去吃午饭了吗？", null, "学院_教室休憩a", "bgm04.opus", null, "CHAPTER 6-2", null, null], [5047, "廉太郎", "「哎呀，以后跟你吃午饭的机会就要越来越少了吗？」", "ren422_004.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "27"}, "CHAPTER 6-2", null, null], [5048, "将臣", "「对不住啊」", null, "学院_教室休憩a", "bgm04.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "27"}, "CHAPTER 6-2", null, null], [5049, "蕾娜", "「嘿嘿，将臣不在，廉太郎很寂寞吗？」", "len422_031.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "12"}, "CHAPTER 6-2", null, null], [5050, "蕾娜", "「不过，就算你们是铁哥们，我也不会把将臣交给你的」", "len422_032.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "15"}, "CHAPTER 6-2", null, null], [5051, "", "蕾娜的胳膊突然挽了过来。", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "15"}, "CHAPTER 6-2", null, null], [5052, "廉太郎", "「哈哈哈，你说什么呢！糙汉子你要几个我给你几个」", "ren422_005.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "06"}, "CHAPTER 6-2", null, null], [5053, "将臣", "「嗯，我差不多也是这种心情」", null, "学院_教室休憩a", "bgm04.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "06"}, "CHAPTER 6-2", null, null], [5054, "廉太郎", "「只是，唉……你不在了，我中午都没办法跟女孩子一起吃饭了」", "ren422_006.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "22"}, "CHAPTER 6-2", null, null], [5055, "", "这家伙对自己的欲望真是够诚实的啊……嗯？", null, "学院_教室休憩a", "bgm04.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "22"}, "CHAPTER 6-2", null, null], [5056, "廉太郎", "「怎么了？有什么……唔啊！？」", "ren422_007.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "10"}, "CHAPTER 6-2", null, null], [5057, "小春", "「那、那什么……哈哈，你们继续」", "koh422_001.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "16"}, "CHAPTER 6-2", null, null], [5058, "廉太郎", "「喂、喂，小春！你不要抓我后颈，很难受的啊！」", "ren422_008.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "14"}, "CHAPTER 6-2", null, null], [5059, "小春", "「真是的，你不要再说一些丢人的话，打扰哥哥他们了」", "koh422_002.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "34"}, "CHAPTER 6-2", null, null], [5060, "", "小春直接把廉太郎拖到教室外面去了。", null, "学院_教室休憩a", "bgm04.opus", null, "CHAPTER 6-2", null, null], [5061, "", "这时，在门口偷看的常陆和朝武也连忙把脑袋缩了回去，但还是被我们看见了。", null, "学院_教室休憩a", "bgm04.opus", null, "CHAPTER 6-2", null, null], [5062, "", "……难道，大家正在观察我们？", null, "学院_教室休憩a", "bgm04.opus", null, "CHAPTER 6-2", null, null], [5063, "蕾娜", "「嘿嘿，机会难得，就让他们好好看看吧」", "len422_033.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 6-2", null, null], [5064, "蕾娜", "「我也想让大家好好看看我们亲密的样子」", "len422_034.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 6-2", null, null], [5065, "将臣", "「哎？」", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 6-2", null, null], [5066, "蕾娜", "「……将臣不希望让大家看吗？」", "len422_035.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "30"}, "CHAPTER 6-2", null, null], [5067, "将臣", "「倒也不是不希望」", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "30"}, "CHAPTER 6-2", null, null], [5068, "", "这难道也是文化差异吗？故意让别人看自己跟恋人打情骂俏的样子，这种感觉有点难以理解。", null, "学院_教室休憩a", "bgm04.opus", null, "CHAPTER 6-2", null, null], [5069, "", "说起来……", null, "学院_教室休憩a", "bgm04.opus", null, "CHAPTER 6-2", null, null], [5070, "", "之前被外公看见时，蕾娜虽然很惊讶，但是好像没有特别不情愿？", null, "学院_学院前a", "bgm04.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "01"}, "CHAPTER 6-2", null, null], [5071, "蕾娜", "「那我们就赶快开吃吧……」", "len422_036.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "18"}, "CHAPTER 6-2", null, null], [5072, "将臣", "「哇！这次做的一看就是日本的便当啊」", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "18"}, "CHAPTER 6-2", null, null], [5073, "蕾娜", "「是的，我是严格按照大家教的方法做的」", "len422_037.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 6-2", null, null], [5074, "", "一边是饭团、肉丸、厚蛋烧、煎三文鱼这些便当必备菜品，另一边则是青椒上面撒了小杂鱼干，似乎是做成了金平？", null, "学院_教室休憩a", "bgm04.opus", null, "CHAPTER 6-2", null, null], [5075, "", "而且，下面还铺着红叶生菜，四周还装饰着小番茄。", null, "学院_教室休憩a", "bgm04.opus", null, "CHAPTER 6-2", null, null], [5076, "", "蕾娜的料理手艺还是很高的，只是由于文化差异，偶尔会拿出一些不得了的食物而已。", null, "学院_教室休憩a", "bgm04.opus", null, "CHAPTER 6-2", null, null], [5077, "", "这份便当也是严格按照烹饪法做的，这也说明了她的手艺不错。", null, "学院_教室休憩a", "bgm04.opus", null, "CHAPTER 6-2", null, null], [5078, "", "越是不会做饭的人，越是喜欢自己加一些乱七八糟的东西。", null, "学院_教室休憩a", "bgm04.opus", null, "CHAPTER 6-2", null, null], [5079, "将臣", "「你这便当做得就跟大部分的日本母亲做的一样，真是个惊喜」", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 6-2", null, null], [5080, "蕾娜", "「嘿嘿……也不知道比不比得上你妈妈做的便当」", "len422_038.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 6-2", null, null], [5081, "蕾娜", "「我不希望差得太远，所以是尽全力做的」", "len422_039.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 6-2", null, null], [5082, "将臣", "「别这么说，你愿意给我做，我就已经非常感动了」", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 6-2", null, null], [5083, "蕾娜", "「不过日本的便当，无论是配菜的种类，还是外观，都非常讲究呢」", "len422_040.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "30"}, "CHAPTER 6-2", null, null], [5084, "蕾娜", "「做的时候压力可大了」", "len422_041.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 6-2", null, null], [5085, "将臣", "「啊，外国人好像不怎么做便当？」", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 6-2", null, null], [5086, "蕾娜", "「是的……一切对我来说都是初次挑战」", "len422_042.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "21"}, "CHAPTER 6-2", null, null], [5087, "蕾娜", "「为了不让各种菜品串味，我做的时候还尽量减少了水分」", "len422_043.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 6-2", null, null], [5088, "蕾娜", "「就连肉丸也并不是做好之后浇上酱汁，而是一开始就把酱汁混进肉里面做成的」", "len422_044.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 6-2", null, null], [5089, "将臣", "「是吗，原来是这样」", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 6-2", null, null], [5090, "", "我没有做过便当，所以也不知道还有这种细致的讲究。", null, "学院_教室休憩a", "bgm04.opus", null, "CHAPTER 6-2", null, null], [5091, "", "我妈给我做便当时，是不是也考虑了这么多呢？", null, "学院_教室休憩a", "bgm04.opus", null, "CHAPTER 6-2", null, null], [5092, "将臣", "「那我们就快点开始吃吧？」", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 6-2", null, null], [5093, "蕾娜", "「好的，那么……」", "len422_045.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 6-2", null, null], [5094, "", "蕾娜拿着筷子的手向我伸了过来。", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 6-2", null, null], [5095, "", "我本来准备接过她的筷子……", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 6-2", null, null], [5096, "蕾娜", "「张嘴，啊～」", "len422_046.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "18"}, "CHAPTER 6-2", null, null], [5097, "", "啊？", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "18"}, "CHAPTER 6-2", null, null], [5098, "蕾娜", "「……你怎么了，将臣？」", "len422_047.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "20"}, "CHAPTER 6-2", null, null], [5099, "蕾娜", "「按照日本的传统……吃便当的时候，女孩子不是应该这样喂男孩子吃吗？」", "len422_048.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 6-2", null, null], [5100, "将臣", "「谁告诉你的啊！？」", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 6-2", null, null], [5101, "", "我猛地一扭头，教室里的所有同学都赶紧移开了视线。", null, "学院_教室休憩a", "bgm04.opus", null, "CHAPTER 6-2", null, null], [5102, "", "而教室门口那边，常陆正在望着我。", null, "学院_教室休憩a", "bgm04.opus", null, "CHAPTER 6-2", null, null], [5103, "茉子", "『哈哈，我的助攻你不满意吗？』", "mak422_001.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "26"}, "CHAPTER 6-2", null, null], [5104, "", "常陆肯定在这么想，看她那眼神就知道！", null, "学院_教室休憩a", "bgm04.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "26"}, "CHAPTER 6-2", null, null], [5105, "蕾娜", "「很奇怪吗？可是……」", "len422_049.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "30"}, "CHAPTER 6-2", null, null], [5106, "蕾娜", "「我是想把我们的关系……明确地告诉大家」", "len422_050.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "12"}, "CHAPTER 6-2", null, null], [5107, "将臣", "「啊、啊啊，是这样啊」", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "12"}, "CHAPTER 6-2", null, null], [5108, "", "原来如此，难道在国外都是用这种方式表明关系的吗。", null, "学院_教室休憩a", "bgm04.opus", null, "CHAPTER 6-2", null, null], [5109, "", "确实，感觉外国人一般都不怎么隐瞒自己和恋人的关系。", null, "学院_教室休憩a", "bgm04.opus", null, "CHAPTER 6-2", null, null], [5110, "", "可、可是，这也太……", null, "学院_教室休憩a", "bgm04.opus", null, "CHAPTER 6-2", null, null], [5111, "蕾娜", "「怎么了，将臣？……你不太喜欢这样吗？」", "len422_051.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "06"}, "CHAPTER 6-2", null, null], [5112, "将臣", "「不是！我当然喜欢！虽然喜欢……但是」", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "06"}, "CHAPTER 6-2", null, null], [5113, "将臣", "「还是很难为情的嘛」", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "06"}, "CHAPTER 6-2", null, null], [5114, "蕾娜", "「噗、哈哈哈……将臣，你真是可爱」", "len422_052.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 6-2", null, null], [5115, "", "难道我这样很孩子气吗？", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 6-2", null, null], [5116, "", "不过，嗯……好吧。", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 6-2", null, null], [5117, "将臣", "「蕾娜，在大家面前秀恩爱……你会觉得很开心吗？」", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 6-2", null, null], [5118, "蕾娜", "「……我当然也很难为情呀」", "len422_053.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "16"}, "CHAPTER 6-2", null, null], [5119, "蕾娜", "「虽然很难为情，但还是比不上这份开心」", "len422_054.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 6-2", null, null], [5120, "蕾娜", "「这样的事……我还是很愿意多多尝试的，毕竟你是我男朋友嘛」", "len422_055.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 6-2", null, null], [5121, "将臣", "「蕾娜……」", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 6-2", null, null], [5122, "", "嗯，好。", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 6-2", null, null], [5123, "将臣", "「我明白了……那，我们就试试吧」", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 6-2", null, null], [5124, "蕾娜", "「嘿嘿，将臣，你想吃什么？」", "len422_056.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "18"}, "CHAPTER 6-2", null, null], [5125, "将臣", "「我看看，那就先吃个肉丸吧。这是你们国家的家常菜吧？」", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "18"}, "CHAPTER 6-2", null, null], [5126, "蕾娜", "「哇哦！其实这味道是日式的，而且是我最有自信的一道菜！」", "len422_057.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "17"}, "CHAPTER 6-2", null, null], [5127, "将臣", "「是吗，那味道肯定很不错」", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "17"}, "CHAPTER 6-2", null, null], [5128, "蕾娜", "「嘿嘿……快来尝尝吧，将臣」", "len422_058.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 6-2", null, null], [5129, "蕾娜", "「来，张开嘴巴」", "len422_059.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 6-2", null, null], [5130, "将臣", "「啊，啊～」", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 6-2", null, null], [5131, "", "蕾娜把肉丸夹到了我嘴边。", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 6-2", null, null], [5132, "", "突然，教室里掀起了一阵嘈杂声。", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 6-2", null, null], [5133, "", "但不可思议的是，我并没有觉得那么难为情。", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 6-2", null, null], [5134, "蕾娜", "「好吃吗，将臣？」", "len422_060.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 6-2", null, null], [5135, "将臣", "「嗯……」", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 6-2", null, null], [5136, "", "看见蕾娜那含羞带笑的表情，其他任何事都显得不那么重要了。", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 6-2", null, null], [5137, "", "我果然也变得有点反常。", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 6-2", null, null], [5138, "将臣", "「超级好吃！」", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 6-2", null, null], [5139, "蕾娜", "「哇哦，真的吗？太好了，也不枉我费尽心思做了那么久」", "len422_061.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 6-2", null, null], [5140, "蕾娜", "「那么，接下来……」", "len422_062.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "26"}, "CHAPTER 6-2", null, null], [5141, "将臣", "「等等，蕾娜，我怎么好意思自己一个人吃呢」", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "26"}, "CHAPTER 6-2", null, null], [5142, "", "我双手握住蕾娜的右手，轻轻地拿走了筷子。", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "26"}, "CHAPTER 6-2", null, null], [5143, "蕾娜", "「啊……将臣」", "len422_063.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "04"}, "CHAPTER 6-2", null, null], [5144, "将臣", "「现在轮到我喂你了」", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "04"}, "CHAPTER 6-2", null, null], [5145, "", "教室里再次掀起一阵嘈杂声。", null, "学院_教室休憩a", "bgm04.opus", null, "CHAPTER 6-2", null, null], [5146, "", "但是这次，我已经对此没有任何感觉了。", null, "学院_教室休憩a", "bgm04.opus", null, "CHAPTER 6-2", null, null], [5147, "蕾娜", "「哎？可、可是……这是我为了你做的便当呀」", "len422_064.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "21"}, "CHAPTER 6-2", null, null], [5148, "将臣", "「我也想让你开心一下，难道说你不喜欢这样吗？」", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "21"}, "CHAPTER 6-2", null, null], [5149, "蕾娜", "「怎……怎么会呢！但是，这还是……有点难为情的」", "len422_065.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "28h"}, "CHAPTER 6-2", null, null], [5150, "将臣", "「刚才你不是也喂了我嘛。来吧，张嘴」", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "28h"}, "CHAPTER 6-2", null, null], [5151, "蕾娜", "「……可，可是，要是你也喂我的话……」", "len422_066.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "30h"}, "CHAPTER 6-2", null, null], [5152, "将臣", "「别客气啦，来吧……啊～」", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "30h"}, "CHAPTER 6-2", null, null], [5153, "蕾娜", "「呜，呜呜……啊，啊～」", "len422_067.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "30h"}, "CHAPTER 6-2", null, null], [5154, "", "刚才还很强硬的蕾娜现在忸忸怩怩地张开了嘴巴。", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "30h"}, "CHAPTER 6-2", null, null], [5155, "", "我夹起一块厚蛋烧，送进了她的嘴里。", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "30h"}, "CHAPTER 6-2", null, null], [5156, "将臣", "「自己做的料理味道如何？」", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "30h"}, "CHAPTER 6-2", null, null], [5157, "蕾娜", "「唔，太难为情了……根本没尝出味道」", "len422_068.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 6-2", null, null], [5158, "蕾娜", "「……不过」", "len422_069.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 6-2", null, null], [5159, "蕾娜", "「虽然没尝出味道，但是全身心都感受到了你的爱」", "len422_070.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 6-2", null, null], [5160, "将臣", "「啊，嗯」", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 6-2", null, null], [5161, "", "这次又轮到我难为情了。", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 6-2", null, null], [5162, "将臣", "「蕾娜，你真可爱」", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 6-2", null, null], [5163, "蕾娜", "「嘿嘿，你也是……脸颊红红的，真可爱」", "len422_071.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "15"}, "CHAPTER 6-2", null, null], [5164, "", "不知不觉，我们都把胳膊肘放在了桌子上，变成了一副身体前倾的姿势。", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "15"}, "CHAPTER 6-2", null, null], [5165, "", "只为了更加靠近对方。", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "15"}, "CHAPTER 6-2", null, null], [5166, "", "啊，我是真心喜欢蕾娜。", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "15"}, "CHAPTER 6-2", null, null], [5167, "", "但与此同时，外公的话语也开始在耳边回响。", null, "学院_学院前a", "bgm04.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "09"}, "CHAPTER 6-2", null, null], [5168, "", "『要么就对自己的行为负责，要么就不要做负不起责任的事情』", null, "学院_学院前a", "bgm04.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "09"}, "CHAPTER 6-2", null, null], [5169, "", "……说实话，交往之前，我心里还是很没底的。", null, "学院_学院前a", "bgm04.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "09"}, "CHAPTER 6-2", null, null], [5170, "", "因为有朝一日，蕾娜很可能要回到她的故乡。", null, "学院_学院前a", "bgm04.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "09"}, "CHAPTER 6-2", null, null], [5171, "", "小雨也说了，如果要把蕾娜的安全放在第一位的话——", null, "街_小道a", "bgm04.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "11"}, "CHAPTER 6-2", null, null], [5172, "", "就应该暂时不管解除诅咒的方法，先查清怎么把碎片从她体内取出来，然后让她离开穗织。", null, "街_小道a", "bgm04.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "11"}, "CHAPTER 6-2", null, null], [5173, "", "要是我们进一步深入梦境，就可能会伴随更大的风险。", null, "街_小道a", "bgm04.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "11"}, "CHAPTER 6-2", null, null], [5174, "", "但是，我喜欢她，我无法违逆自己的感情。", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 6-2", null, null], [5175, "", "我是不是已经做了负不起责任的事呢？这种想法似乎依然残留在我心底里。", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 6-2", null, null], [5176, "蕾娜", "「你怎么了，将臣」", "len422_072.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "04"}, "CHAPTER 6-2", null, null], [5177, "将臣", "「没事……我在想，接下来让你喂我什么比较好」", null, "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "04"}, "CHAPTER 6-2", null, null], [5178, "蕾娜", "「嘿嘿，这个嘛，我希望你能多吃点蔬菜……」", "len422_073.ogg", "学院_教室休憩a", "bgm04.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "03"}, "CHAPTER 6-2", null, null], [5179, "", "完全依照自己的欲望行事，可能还是不太好。", null, "学院_教室休憩a", "bgm04.opus", null, "CHAPTER 6-2", null, null], [5180, "", "正因为我喜欢她，所以才应该更加慎重一点。", null, "学院_教室休憩a", "bgm04.opus", null, "CHAPTER 6-2", null, null], [5181, "", "我说我宇宙第一喜欢她，这其实也并不夸张，我是真的这么觉得。", null, "学院_教室休憩a", "bgm04.opus", null, "CHAPTER 6-2", null, null], [5182, "", "放学后，我们暂时分开，她去忙工作，我去练剑道。等各自忙完后，再去志那都庄会合。", null, "旅館_旅館前c", "bgm04.opus", null, "CHAPTER 6-2", null, null], [5183, "将臣", "「……外公丝毫没提今早的事啊」", null, "旅館_旅館前c", "bgm04.opus", null, "CHAPTER 6-2", null, null], [5184, "", "看来，他是真的不打算对我们的恋爱说三道四。", null, "旅館_旅館前c", "bgm04.opus", null, "CHAPTER 6-2", null, null], [5185, "", "但是，我总感觉他今天下手比以往更重了。", null, "旅館_旅館前c", "bgm04.opus", null, "CHAPTER 6-2", null, null], [5186, "", "但我毕竟练了这么久，这点程度倒不至于让我难受得动都动不了。", null, "旅館_旅館前c", "bgm04.opus", null, "CHAPTER 6-2", null, null], [5187, "", "人的适应力还是很恐怖的。", null, "旅館_旅館前c", "bgm04.opus", null, "CHAPTER 6-2", null, null], [5188, "将臣", "「不过，多亏了今天的训练，让我想到了接下来该玩些什么」", null, "旅館_旅館前c", "bgm04.opus", null, "CHAPTER 6-2", null, null], [5189, "蕾娜", "「将臣！我想死你了」", "len422_074.ogg", "旅館_廊下d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "01"}, "CHAPTER 6-2", null, null], [5190, "将臣", "「蕾娜」", null, "旅館_廊下d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "01"}, "CHAPTER 6-2", null, null], [5191, "", "刚一走进志那都庄，在此等待许久的蕾娜就抱了上来。", null, "旅館_廊下d", "bgm44.opus", null, "CHAPTER 6-2", "ev403a", null], [5192, "蕾娜", "「Ｍｕａ♪嘿嘿，３个小时不见，我可寂寞了」", "len422_075.ogg", "旅館_廊下d", "bgm44.opus", null, "CHAPTER 6-2", "ev403a", null], [5193, "将臣", "「哈哈……我也很想你」", null, "旅館_廊下d", "bgm44.opus", null, "CHAPTER 6-2", "ev403a", null], [5194, "蕾娜", "「话说，你已经练完了吗？」", "len422_076.ogg", "旅館_廊下d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "01"}, "CHAPTER 6-2", null, null], [5195, "将臣", "「嗯，你这边也忙完了吗？」", null, "旅館_廊下d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "01"}, "CHAPTER 6-2", null, null], [5196, "蕾娜", "「是的……因为我想快点跟你约会，所以很快就把工作做完了」", "len422_077.ogg", "旅館_廊下d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02"}, "CHAPTER 6-2", null, null], [5197, "将臣", "「真厉害……」", null, "旅館_廊下d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02"}, "CHAPTER 6-2", null, null], [5198, "", "我再一次与她相吻。", null, "旅館_廊下d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02"}, "CHAPTER 6-2", null, null], [5199, "蕾娜", "「唔……嗯……那我们接下来干什么？」", "len422_078.ogg", "旅館_廊下d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "01"}, "CHAPTER 6-2", null, null], [5200, "将臣", "「我想想，要不先去泡个温泉冲下汗吧？」", null, "旅館_廊下d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "01"}, "CHAPTER 6-2", null, null], [5201, "蕾娜", "「啊……将臣，这么快就要开始了吗……」", "len422_079.ogg", "旅館_廊下d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27h"}, "CHAPTER 6-2", null, null], [5202, "将臣", "「不、不是！主要是因为训练时出了一身汗，而且你忙了那么久肯定也出了不少汗吧？」", null, "旅館_廊下d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27h"}, "CHAPTER 6-2", null, null], [5203, "将臣", "「洗完澡之后，我们就再来这里集合吧」", null, "旅館_廊下d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27h"}, "CHAPTER 6-2", null, null], [5204, "蕾娜", "「好啊，不过，不用在我房间集合吗？」", "len422_080.ogg", "旅館_廊下d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "20"}, "CHAPTER 6-2", null, null], [5205, "将臣", "「其实我有个好主意」", null, "旅館_廊下d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "20"}, "CHAPTER 6-2", null, null], [5206, "将臣", "「今天可是难得的约会，所以咱们要不要试试平时没做过的事？」", null, "旅館_廊下d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "20"}, "CHAPTER 6-2", null, null], [5207, "蕾娜", "「……嗯，也行吧」", "len422_081.ogg", "旅館_廊下d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "04"}, "CHAPTER 6-2", null, null], [5208, "蕾娜", "「嘿呀！接招————！」", "len422_082.ogg", "画面_黒", "bgm44.opus", null, "CHAPTER 6-2", "ev408a", null], [5209, "将臣", "「哇啊！」", null, "画面_黒", "bgm44.opus", null, "CHAPTER 6-2", "ev408a", null], [5210, "", "蕾娜突然来了个猛烈的扣杀。", null, "画面_黒", "bgm44.opus", null, "CHAPTER 6-2", "ev408a", null], [5211, "", "我的球拍仅仅只跟乒乓球擦了个边，到底还是没能挡住它的去路。", null, "画面_黒", "bgm44.opus", null, "CHAPTER 6-2", "ev408a", null], [5212, "蕾娜", "「太棒了，我又得了一分」", "len422_083.ogg", "画面_黒", "bgm44.opus", null, "CHAPTER 6-2", "ev408a", null], [5213, "将臣", "「唉……真是吓我一跳，没想到你技术这么好」", null, "画面_黒", "bgm44.opus", null, "CHAPTER 6-2", "ev408a", null], [5214, "", "乒乓球也算是温泉旅馆常见的游戏了。", null, "画面_黒", "bgm44.opus", null, "CHAPTER 6-2", "ev408a", null], [5215, "", "志那都庄当然也是有乒乓球台的。", null, "画面_黒", "bgm44.opus", null, "CHAPTER 6-2", "ev408a", null], [5216, "", "……多运动运动，出点汗，就可以清空烦恼了。", null, "画面_黒", "bgm44.opus", null, "CHAPTER 6-2", "ev408a", null], [5217, "蕾娜", "「嘿嘿嘿，我们国家也玩乒乓球的啦」", "len422_084.ogg", "画面_黒", "bgm44.opus", null, "CHAPTER 6-2", "ev408a", null], [5218, "蕾娜", "「不过，我听说日本的温泉都有乒乓球台，这是为什么呢？」", "len422_085.ogg", "画面_黒", "bgm44.opus", null, "CHAPTER 6-2", "ev408a", null], [5219, "将臣", "「我也不知道，大概是因为这是室内游戏，而且不占空间吧」", null, "画面_黒", "bgm44.opus", null, "CHAPTER 6-2", "ev408a", null], [5220, "将臣", "「其实台球也挺常见的」", null, "画面_黒", "bgm44.opus", null, "CHAPTER 6-2", "ev408a", null], [5221, "蕾娜", "「哇哦，志那都庄也有台球，下次要不要来比试比试呀」", "len422_086.ogg", "画面_黒", "bgm44.opus", null, "CHAPTER 6-2", "ev408a", null], [5222, "将臣", "「行啊，不过今天先比乒乓球！」", null, "画面_黒", "bgm44.opus", null, "CHAPTER 6-2", "ev408a", null], [5223, "蕾娜", "「那是当然，我要上了！嘿！」", "len422_087.ogg", "画面_黒", "bgm44.opus", null, "CHAPTER 6-2", "ev408a", null], [5224, "", "蕾娜把球拍压成锐角，重新发球。", null, "画面_黒", "bgm44.opus", null, "CHAPTER 6-2", "ev408a", null], [5225, "", "顺便一提，我们现在穿的都是浴衣。", null, "画面_黒", "bgm44.opus", null, "CHAPTER 6-2", "ev408a", null], [5226, "", "这不仅是因为我们刚洗完澡，也是因为如果她穿着工作人员的衣服跟我打球，会影响旅馆的形象。", null, "画面_黒", "bgm44.opus", null, "CHAPTER 6-2", "ev408a", null], [5227, "将臣", "「哈！」", null, "画面_黒", "bgm44.opus", null, "CHAPTER 6-2", "ev408a", null], [5228, "蕾娜", "「……我接！」", "len422_088.ogg", "画面_黒", "bgm44.opus", null, "CHAPTER 6-2", "ev408a", null], [5229, "", "（波涛汹涌）", null, "画面_黒", "bgm44.opus", null, "CHAPTER 6-2", "ev408a", null], [5230, "将臣", "「唔……！」", null, "画面_黒", "bgm44.opus", null, "CHAPTER 6-2", "ev408a", null], [5231, "蕾娜", "「嗬！」", "len422_089.ogg", "画面_黒", "bgm44.opus", null, "CHAPTER 6-2", "ev408a", null], [5232, "", "（波涛汹涌～～♪）", null, "画面_黒", "bgm44.opus", null, "CHAPTER 6-2", "ev408a", null], [5233, "", "不行了！根本无法集中精力打球。", null, "画面_黒", "bgm44.opus", null, "CHAPTER 6-2", "ev408a", null], [5234, "", "只要蕾娜剧烈运动，她的胸前就会荡起一阵我从未见过的惊涛骇浪。", null, "画面_黒", "bgm44.opus", null, "CHAPTER 6-2", "ev408a", null], [5235, "蕾娜", "「怎么了，将臣？你怎么越打越没劲了」", "len422_090.ogg", "画面_黒", "bgm44.opus", null, "CHAPTER 6-2", "ev408a", null], [5236, "将臣", "「可、可恶！」", null, "画面_黒", "bgm44.opus", null, "CHAPTER 6-2", "ev408a", null], [5237, "", "再这样下去，我都不敢直起腰了。", null, "画面_黒", "bgm44.opus", null, "CHAPTER 6-2", "ev408a", null], [5238, "", "没想到打个乒乓球还得承受这样的精神攻击！", null, "画面_黒", "bgm44.opus", null, "CHAPTER 6-2", "ev408a", null], [5239, "", "我还指望清空杂念呢，现在简直是……", null, "画面_黒", "bgm44.opus", null, "CHAPTER 6-2", "ev408a", null], [5240, "将臣", "「……啊！」", null, "画面_黒", "bgm44.opus", null, "CHAPTER 6-2", "ev408a", null], [5241, "", "糟了，球打飘了！？", null, "画面_黒", "bgm44.opus", null, "CHAPTER 6-2", "ev408a", null], [5242, "蕾娜", "「机会来了！看我的超级扣杀————！！」", "len422_091.ogg", "画面_黒", "bgm44.opus", null, "CHAPTER 6-2", "ev408a", null], [5243, "", "（惊涛骇浪～～♪）", null, "画面_黒", "bgm44.opus", null, "CHAPTER 6-2", "ev408a", null], [5244, "", "本世纪最猛烈的乳摇向我发起了进攻！", null, "画面_黒", "bgm44.opus", null, "CHAPTER 6-2", "ev408a", null], [5245, "将臣", "「混蛋！」", null, "画面_黒", "bgm44.opus", null, "CHAPTER 6-2", "ev408a", null], [5246, "蕾娜", "「喔喔，打得不错哦，将臣」", "len422_092.ogg", "画面_黒", "bgm44.opus", null, "CHAPTER 6-2", "ev408a", null], [5247, "", "我的球拍勉强够到了球。", null, "画面_黒", "bgm44.opus", null, "CHAPTER 6-2", "ev408a", null], [5248, "", "但是，却再一次把球打飘了……", null, "画面_黒", "bgm44.opus", null, "CHAPTER 6-2", "ev408a", null], [5249, "蕾娜", "「很遗憾，你这都是无谓的挣扎」", "len422_093.ogg", "画面_黒", "bgm44.opus", null, "CHAPTER 6-2", "ev408a", null], [5250, "", "（惊涛骇浪～～♪）", null, "画面_黒", "bgm44.opus", null, "CHAPTER 6-2", "ev408a", null], [5251, "将臣", "「喔……喔喔喔喔喔喔————！！？」", null, "画面_黒", "bgm44.opus", null, "CHAPTER 6-2", "ev408a", null], [5252, "", "这究竟是爆发小宇宙时的呐喊，还是乐极生悲时的惨叫？", null, "画面_黒", "bgm44.opus", null, "CHAPTER 6-2", "ev408a", null], [5253, "", "无论如何，只要这段激烈的对攻结束，我就看不到乳摇……不！要是输了，就不能清空杂念了。", null, "画面_黒", "bgm44.opus", null, "CHAPTER 6-2", "ev408a", null], [5254, "蕾娜", "「什么！这球你都能接住，那再试试我这招如何！」", "len422_094.ogg", "画面_黒", "bgm44.opus", null, "CHAPTER 6-2", "ev408a", null], [5255, "将臣", "「哈啊！！」", null, "画面_黒", "bgm44.opus", null, "CHAPTER 6-2", "ev408a", null], [5256, "蕾娜", "「哈哈哈，将臣，刚才玩得真是太痛快了」", "len422_095.ogg", "画面_黒", "bgm44.opus", null, "CHAPTER 6-2", "ev408a", null], [5257, "", "我们的激战最终白热化，一个不注意就玩到了深夜。", null, "空_夜空", "bgm44.opus", null, "CHAPTER 6-2", null, null], [5258, "", "打完之后，我们不得不又泡了一次温泉。", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 6-2", null, null], [5259, "将臣", "「呼，不过，既然都出了这么多汗，大概也没力气想别的了……」", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 6-2", null, null], [5260, "", "不，应该也不至于。", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 6-2", null, null], [5261, "", "稍微回想下刚才的激战，我就有点受不了了。", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 6-2", null, null], [5262, "", "蕾娜的爆乳实在是太犯规了。", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 6-2", null, null], [5263, "", "这么长时间我能一直管住自己的手，我觉得我已经很努力了。", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 6-2", null, null], [5264, "", "男人都很单纯，对自己的欲望也很诚实。", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 6-2", null, null], [5265, "", "但正因如此，我们才应该努力做个绅士。", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 6-2", null, null], [5266, "", "不过，蕾娜好像是主动想跟我进一步加深感情……这种应该可以按特殊情况处理？", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 6-2", null, null], [5267, "", "不不，越是这种时候，男性越是应该理性一点吧？", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 6-2", null, null], [5268, "将臣", "「嗯？……啊，请进」", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 6-2", null, null], [5269, "", "这是蕾娜的房间，我随便回应真的没事吗？", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 6-2", null, null], [5270, "", "不过，进门的并不是别人。", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 6-2", null, null], [5271, "蕾娜", "「……将臣，让你久等了」", "len422_096.ogg", "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 6-2", null, null], [5272, "将臣", "「蕾娜！怎么了，为什么进自己的房间还要敲门啊」", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 6-2", null, null], [5273, "将臣", "「而且，你怎么穿着这身衣服……？」", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 6-2", null, null], [5274, "", "这明显不是室内穿的衣服。", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 6-2", null, null], [5275, "", "之前一起去屋顶上看星星的时候，她穿的倒是这一身……", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 6-2", null, null], [5276, "", "我记得那时候，她还说什么，夜晚才刚刚开始之类的……哎？", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 6-2", null, null], [5277, "蕾娜", "「我……我可以坐在你旁边吗？」", "len422_097.ogg", "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "05"}, "CHAPTER 6-2", null, null], [5278, "将臣", "「嗯，当然可以」", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "05"}, "CHAPTER 6-2", null, null], [5279, "蕾娜", "「……嗯」", "len422_098.ogg", "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "27"}, "CHAPTER 6-2", null, null], [5280, "", "她坐在我旁边之前，竟然还特意打了个招呼。", null, "旅館_レナの部屋d", "bgm09.opus", null, "CHAPTER 6-2", null, null], [5281, "", "而且她现在并不像之前那样紧紧地贴在我身上，而是缩着肩膀坐在我身边。", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "03"}, "CHAPTER 6-2", null, null], [5282, "", "咦、咦？我是不是应该就这样抱住她的肩膀？", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "03"}, "CHAPTER 6-2", null, null], [5283, "", "现在的她明明比平时更端庄，但为什么我感觉气氛这么不可描述呢？", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "03"}, "CHAPTER 6-2", null, null], [5284, "蕾娜", "「嘿嘿，怎么说呢……感觉好紧张呀」", "len422_099.ogg", "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "27h"}, "CHAPTER 6-2", null, null], [5285, "将臣", "「啊、嗯，确实」", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "27h"}, "CHAPTER 6-2", null, null], [5286, "", "糟了，连我也开始紧张了。", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "27h"}, "CHAPTER 6-2", null, null], [5287, "将臣", "「对……对了，最近过得怎么样啊？」", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "27h"}, "CHAPTER 6-2", null, null], [5288, "蕾娜", "「啊？」", "len422_100.ogg", "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "20"}, "CHAPTER 6-2", null, null], [5289, "将臣", "「啊，就是，有没有很想念家里人之类的」", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "20"}, "CHAPTER 6-2", null, null], [5290, "将臣", "「另外你有没有跟家里人好好联系呢」", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "20"}, "CHAPTER 6-2", null, null], [5291, "蕾娜", "「哈哈，没事的啦」", "len422_101.ogg", "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "19"}, "CHAPTER 6-2", null, null], [5292, "蕾娜", "「只要有你在，我就是想患上思乡病也是很难的」", "len422_102.ogg", "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "16"}, "CHAPTER 6-2", null, null], [5293, "将臣", "「……呃、嗯，是吗」", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "16"}, "CHAPTER 6-2", null, null], [5294, "蕾娜", "「那你呢？」", "len422_103.ogg", "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "34"}, "CHAPTER 6-2", null, null], [5295, "将臣", "「我？」", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "34"}, "CHAPTER 6-2", null, null], [5296, "蕾娜", "「我好像从来没见你和家人联系过」", "len422_104.ogg", "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "20"}, "CHAPTER 6-2", null, null], [5297, "将臣", "「毕竟我在国内嘛……不过，我确实没怎么意识过这个问题」", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "20"}, "CHAPTER 6-2", null, null], [5298, "蕾娜", "「哈哈，你自己都不怎么联系，还担心我呢」", "len422_105.ogg", "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "26"}, "CHAPTER 6-2", null, null], [5299, "将臣", "「哈、哈哈，说的也是，连我自己都这么久没联系了」", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "26"}, "CHAPTER 6-2", null, null], [5300, "蕾娜", "「日本还有句俗语说，没有消息就说明平平安安」", "len422_106.ogg", "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 6-2", null, null], [5301, "", "大概是想说，久疏问候便是平平安安？用法应该是没什么问题。", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 6-2", null, null], [5302, "蕾娜", "「那个，将臣……」", "len422_107.ogg", "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "30"}, "CHAPTER 6-2", null, null], [5303, "将臣", "「嗯？」", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "30"}, "CHAPTER 6-2", null, null], [5304, "蕾娜", "「……～～」", "len422_108.ogg", "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "18h"}, "CHAPTER 6-2", null, null], [5305, "", "蕾娜突然把头靠在了我的肩膀上，似乎是下了很大的决心。", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "18h"}, "CHAPTER 6-2", null, null], [5306, "蕾娜", "「至今为止……我学了各种各样的日语」", "len422_109.ogg", "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "14h"}, "CHAPTER 6-2", null, null], [5307, "蕾娜", "「这种情况下，是不是应该说……月色真美？」", "len422_110.ogg", "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25h"}, "CHAPTER 6-2", null, null], [5308, "将臣", "「……现、现在窗子关得严严实实的」", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25h"}, "CHAPTER 6-2", null, null], [5309, "蕾娜", "「我知道……但月色，还是很美呀」", "len422_111.ogg", "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "19h"}, "CHAPTER 6-2", null, null], [5310, "", "我记得当初夏目漱石翻译＂Ｉ　ｌＯＶＥ　ＹＯＵ＂时，好像就是这么翻译的？", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "19h"}, "CHAPTER 6-2", null, null], [5311, "", "那我或许应该回一句“我这条命是你的了”。", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "19h"}, "CHAPTER 6-2", null, null], [5312, "将臣", "「对、对、对了，之前，在学校里……」", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "19h"}, "CHAPTER 6-2", null, null], [5313, "蕾娜", "「……啊？」", "len422_112.ogg", "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "04"}, "CHAPTER 6-2", null, null], [5314, "将臣", "「呃，好像是发生了什么事来着？我想想」", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "04"}, "CHAPTER 6-2", null, null], [5315, "蕾娜", "「…………」", "len422_113.ogg", "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "10"}, "CHAPTER 6-2", null, null], [5316, "", "蕾娜一脸无语地瞪了我一眼。", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "10"}, "CHAPTER 6-2", null, null], [5317, "蕾娜", "「将——臣——，你是故意破坏气氛吗！」", "len422_114.ogg", "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "11"}, "CHAPTER 6-2", null, null], [5318, "将臣", "「不、不是，抱歉！我不是那个意思，只是……」", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "11"}, "CHAPTER 6-2", null, null], [5319, "将臣", "「……我感觉对我们来说是不是太早了？」", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "11"}, "CHAPTER 6-2", null, null], [5320, "蕾娜", "「难道，你家是非常严格的基督教家庭吗？」", "len422_115.ogg", "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "20"}, "CHAPTER 6-2", null, null], [5321, "将臣", "「哎？……我家应该只信佛教吧」", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "20"}, "CHAPTER 6-2", null, null], [5322, "蕾娜", "「难道佛教的人在结婚之前……月色就不能真美了吗？」", "len422_116.ogg", "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "30"}, "CHAPTER 6-2", null, null], [5323, "将臣", "「应、应该不是，我没听说过」", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "30"}, "CHAPTER 6-2", null, null], [5324, "", "她应该就是那个意思了吧？", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "30"}, "CHAPTER 6-2", null, null], [5325, "蕾娜", "「唔——」", "len422_117.ogg", "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "11"}, "CHAPTER 6-2", null, null], [5326, "将臣", "「你……你想嘛，今早外公还专门告诫过我们呢」", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "11"}, "CHAPTER 6-2", null, null], [5327, "蕾娜", "「……你说大当家？」", "len422_118.ogg", "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "04"}, "CHAPTER 6-2", null, null], [5328, "将臣", "「是的，他说要么就负责，要么就别做负不起责任的事情」", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "04"}, "CHAPTER 6-2", null, null], [5329, "蕾娜", "「难道……你不准备负责的吗！」", "len422_119.ogg", "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "13"}, "CHAPTER 6-2", null, null], [5330, "蕾娜", "「你这个负心汉！？」", "len422_120.ogg", "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "21"}, "CHAPTER 6-2", null, null], [5331, "将臣", "「好疼……不、不是那样啦，好疼好疼！」", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "21"}, "CHAPTER 6-2", null, null], [5332, "", "她就像小孩子撒娇一样拿小拳拳锤我胸口。", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "21"}, "CHAPTER 6-2", null, null], [5333, "将臣", "「蕾娜，你也是有家人的吧？」", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "21"}, "CHAPTER 6-2", null, null], [5334, "蕾娜", "「……是啊，那又怎么样」", "len422_121.ogg", "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 6-2", null, null], [5335, "将臣", "「那也就是说……你不可能永远跟你的家人分开吧？」", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 6-2", null, null], [5336, "", "早晚有一天，她得回到自己的国家。", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 6-2", null, null], [5337, "", "踏出这一步之前，我难道不应该慎重地考虑下今后能不能负起责任吗？", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 6-2", null, null], [5338, "蕾娜", "「……那我们，不用一起睡了吗……也不用管能不能进入梦境了吗？」", "len422_122.ogg", "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "30"}, "CHAPTER 6-2", null, null], [5339, "将臣", "「抱歉……其实，这件事我之前跟小雨商量过」", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "30"}, "CHAPTER 6-2", null, null], [5340, "", "如果没有什么有益的信息，就先把碎片从蕾娜体内取出来，然后让她离开穗织。", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "30"}, "CHAPTER 6-2", null, null], [5341, "", "如果要把蕾娜的安全放在第一位，这才是最优解。我把这些全都向她说明了。", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "30"}, "CHAPTER 6-2", null, null], [5342, "将臣", "「就算我们在梦里收集信息，那些信息也并不一定能派上用场，所以……」", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "30"}, "CHAPTER 6-2", null, null], [5343, "蕾娜", "「……所以，你想说什么？」", "len422_123.ogg", "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "23"}, "CHAPTER 6-2", null, null], [5344, "将臣", "「抱歉，之前一直没跟你说。这些事，可能应该提前告诉你，让你自己考虑的……」", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "23"}, "CHAPTER 6-2", null, null], [5345, "蕾娜", "「所以你到底想说什么？」", "len422_124.ogg", "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "16"}, "CHAPTER 6-2", null, null], [5346, "蕾娜", "「你是觉得，我干脆回国比较好吗！」", "len422_125.ogg", "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "23"}, "CHAPTER 6-2", null, null], [5347, "将臣", "「不是……我就是觉得，我不能太任性了」", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "23"}, "CHAPTER 6-2", null, null], [5348, "", "我不想让蕾娜回去，我想要解开诅咒。", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "23"}, "CHAPTER 6-2", null, null], [5349, "", "这些都是我的愿望。我真的没有把这些强加给她吗？", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "23"}, "CHAPTER 6-2", null, null], [5350, "", "这些事情我至今都没能得到答案。所以，事到如今我才会如此犹豫不决。", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "23"}, "CHAPTER 6-2", null, null], [5351, "将臣", "「我现在依然不知道什么才是最优解」", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "23"}, "CHAPTER 6-2", null, null], [5352, "将臣", "「在这种情况下……要是有人问我能不能负起责任，我就有点……」", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "23"}, "CHAPTER 6-2", null, null], [5353, "蕾娜", "「将——臣——！」", "len422_126.ogg", "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "11"}, "CHAPTER 6-2", null, null], [5354, "将臣", "「……哇啊！？」", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "11"}, "CHAPTER 6-2", null, null], [5355, "", "她突然捏起了我的脸颊。", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "11"}, "CHAPTER 6-2", null, null], [5356, "蕾娜", "「我的安全？只顾我自己的安全怎么可能是最优解呢」", "len422_127.ogg", "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "16"}, "CHAPTER 6-2", null, null], [5357, "蕾娜", "「朋友有难的时候，让我弃之不顾，自己逃跑，这算什么最优解啊！」", "len422_128.ogg", "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "08"}, "CHAPTER 6-2", null, null], [5358, "将臣", "「……！！」", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "08"}, "CHAPTER 6-2", null, null], [5359, "蕾娜", "「解开芳乃家的诅咒，然后我和你都平安无事，这才是最优解，难道不是吗？」", "len422_129.ogg", "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "06"}, "CHAPTER 6-2", null, null], [5360, "将臣", "「这、这个……」", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "06"}, "CHAPTER 6-2", null, null], [5361, "蕾娜", "「我一开始就是这么想的」", "len422_130.ogg", "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "23"}, "CHAPTER 6-2", null, null], [5362, "蕾娜", "「难道你不是吗？」", "len422_131.ogg", "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "30"}, "CHAPTER 6-2", null, null], [5363, "", "……我当然也是。", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "30"}, "CHAPTER 6-2", null, null], [5364, "", "但是，我似乎还是迷茫了很久。", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "30"}, "CHAPTER 6-2", null, null], [5365, "蕾娜", "「再说了，你一口一个责任，你说的责任到底是什么？」", "len422_132.ogg", "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "28"}, "CHAPTER 6-2", null, null], [5366, "将臣", "「哎？」", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "28"}, "CHAPTER 6-2", null, null], [5367, "蕾娜", "「这明明是我们两个人的事，你为什么会觉得全部都是你一个人的责任，这很奇怪！真的太奇怪了」", "len422_133.ogg", "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "07"}, "CHAPTER 6-2", null, null], [5368, "蕾娜", "「你难道觉得，我是个不能自己做决定的小孩子吗！」", "len422_134.ogg", "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "15"}, "CHAPTER 6-2", null, null], [5369, "将臣", "「不是，那个……哎？」", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "15"}, "CHAPTER 6-2", null, null], [5370, "蕾娜", "「我应该怎么做，我会自己做决定，自己负责」", "len422_135.ogg", "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "23"}, "CHAPTER 6-2", null, null], [5371, "蕾娜", "「你不能无视我的心情，说让我回国就让我回国，任何人都没有权利这么做！」", "len422_136.ogg", "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "06"}, "CHAPTER 6-2", null, null], [5372, "", "啊……", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "06"}, "CHAPTER 6-2", null, null], [5373, "", "我不禁抱紧了蕾娜。", null, "旅館_レナの部屋d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "06"}, "CHAPTER 6-2", null, null], [5374, "蕾娜", "「呀……啊？将、将臣？」", "len422_137.ogg", "旅館_レナの部屋d", "bgm07.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "20"}, "CHAPTER 6-2", null, null], [5375, "将臣", "「抱歉，是我错了」", null, "旅館_レナの部屋d", "bgm07.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "20"}, "CHAPTER 6-2", null, null], [5376, "将臣", "「因为我非常不希望你离开穗织……所以一直没敢跟你说」", null, "旅館_レナの部屋d", "bgm07.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "20"}, "CHAPTER 6-2", null, null], [5377, "蕾娜", "「将臣……」", "len422_138.ogg", "旅館_レナの部屋d", "bgm07.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "05"}, "CHAPTER 6-2", null, null], [5378, "将臣", "「可我却偏偏选在这个时候说了出来，我真是脑子进水了」", null, "旅館_レナの部屋d", "bgm07.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "05"}, "CHAPTER 6-2", null, null], [5379, "", "蕾娜的双臂也抱住了我。", null, "旅館_レナの部屋d", "bgm07.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "05"}, "CHAPTER 6-2", null, null], [5380, "蕾娜", "「……没事，我知道，大家都是在为我着想」", "len422_139.ogg", "旅館_レナの部屋d", "bgm07.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 6-2", null, null], [5381, "蕾娜", "「但是，光让大家为我着想，这肯定是不行的」", "len422_140.ogg", "旅館_レナの部屋d", "bgm07.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "21"}, "CHAPTER 6-2", null, null], [5382, "蕾娜", "「我也想为大家着想……最重要的是，我也想好好珍惜你」", "len422_141.ogg", "旅館_レナの部屋d", "bgm07.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "02"}, "CHAPTER 6-2", null, null], [5383, "将臣", "「真的可以吗？」", null, "旅館_レナの部屋d", "bgm07.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "02"}, "CHAPTER 6-2", null, null], [5384, "", "只要卸下了理性的枷锁，我肯定会变得无法克制自己。", null, "旅館_レナの部屋d", "bgm07.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "02"}, "CHAPTER 6-2", null, null], [5385, "", "我肯定会渴望蕾娜的一切。", null, "旅館_レナの部屋d", "bgm07.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "02"}, "CHAPTER 6-2", null, null], [5386, "将臣", "「……哪怕以后你想回去，我恐怕也是不愿意让你回去的」", null, "旅館_レナの部屋d", "bgm07.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "02"}, "CHAPTER 6-2", null, null], [5387, "蕾娜", "「将臣，你真是个笨蛋」", "len422_142.ogg", "旅館_レナの部屋d", "bgm07.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "22"}, "CHAPTER 6-2", null, null], [5388, "蕾娜", "「咱们不是约好了吗，我要教你怎么看星星」", "len422_143.ogg", "旅館_レナの部屋d", "bgm07.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "27"}, "CHAPTER 6-2", null, null], [5389, "将臣", "「为了让我们能永远望着同一片星空？」", null, "旅館_レナの部屋d", "bgm07.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "27"}, "CHAPTER 6-2", null, null], [5390, "蕾娜", "「是的，所以，没事的……你不用担心」", "len422_144.ogg", "旅館_レナの部屋d", "bgm07.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "01"}, "CHAPTER 6-2", null, null], [5391, "蕾娜", "「将臣……」", "len422_145.ogg", "旅館_レナの部屋d", "bgm07.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "26"}, "CHAPTER 6-2", null, null], [5392, "", "蕾娜轻轻地闭上了双眼。", null, "旅館_レナの部屋d", "bgm07.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "26"}, "CHAPTER 6-2", null, null], [5393, "", "现在，我已经不会再犹豫了。", null, "旅館_レナの部屋d", "bgm07.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "26"}, "CHAPTER 6-2", null, null], [5394, "", "我们急不可待地互相摸索着彼此的身体，等我回过神来，她已经在我的下半身前做好准备了。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5395, "蕾娜", "「将臣……将臣……你已经……这么硬了啊……」", "len422_146.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5396, "蕾娜", "「啊……用我的奶子……来把它捂住吧」", "len422_147.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5397, "将臣", "「蕾，蕾娜……你从哪里学会这招的？」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5398, "", "她居然用乳房从左右两边夹住了我的阴茎。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5399, "蕾娜", "「……之前……在你的房间里有本色色的书……上面画了的。呼～」", "len422_148.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5400, "将臣", "「啊……确实有一本」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5401, "", "虽然那并不是我的书。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5402, "将臣", "「我记得，那时候蕾娜看到黄书就昏过去了」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5403, "蕾娜", "「那、那又说明什么？」", "len422_149.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5404, "将臣", "「……难道说你其实仔细看过了？」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5405, "蕾娜", "「将、将臣。那是……嗯，因为……哈，哈……我是……出生以来」", "len422_150.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5406, "蕾娜", "「第一次看……那种色色的书……啊，嗯，那时候……我还在想……哈，唔」", "len422_151.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5407, "蕾娜", "「做这种事……不觉得害羞吗……嗯……嗯，嗯！」", "len422_152.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5408, "", "她用大尺寸的胸部夹住我的阴茎，轻轻地前后摇晃身体。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5409, "", "龟头冠勾住她柔软的乳房，不由得让我的阴茎跳动了一下。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5410, "蕾娜", "「哈……哈……你这里真可爱，嗯……嘿嘿，我看的时候……明明是那么地害羞」", "len422_153.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5411, "蕾娜", "「虽然现在也很害羞……但我更开心，因为……将臣……用我的身体……感觉这么舒服，啊！」", "len422_154.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5412, "蕾娜", "「……将臣，你又跳动了一下吧？呵呵呵……嗯，嗯」", "len422_155.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5413, "蕾娜", "「感觉……非常惹人怜爱……哈，哈……啊，将臣……将臣」", "len422_156.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5414, "", "蕾娜加大了胸部的压力，让我进一步感觉到胸部包裹住阴茎的柔软触感。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5415, "", "……一般来说，乳交是用乳房夹住平行于自己身体的阴茎。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5416, "", "但是，她连垂直于她身体的阴茎都能夹住，是因为这对超大尺寸的胸部吗？", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5417, "蕾娜", "「啊……嗯嗯……将臣……将臣……哈，哈」", "len422_157.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5418, "将臣", "「等、等等……蕾娜！你动得那么激烈的话，我就要……」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5419, "", "我好像马上会被弄得射精了。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5420, "", "我听说乳交其实并没有那么舒服，现在看来这话绝对是骗人的。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5421, "蕾娜", "「啊，嗯……抱歉……难道说，你觉得有点疼吗？」", "len422_158.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5422, "蕾娜", "「慢点动的话还疼吗？……将臣，啊……啊」", "len422_159.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5423, "", "又白又软的年糕，在轻轻地慢慢地揉搓我的阴茎。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5424, "", "是因为接触面积和刚才不一样了吗？光是这样做我也感觉好舒服。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5425, "蕾娜", "「啊！嗯，你的小兄弟一边颤动……啊，一边流出……还有黏黏的透明液体……这是什么？」", "len422_160.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5426, "将臣", "「嗯，嗯，是因为我觉得很舒服……我说精前液的话你估计不会懂」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5427, "将臣", "「我想想……叫它考珀液你懂吗？」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5428, "蕾娜", "「是叫……考珀液啊，嗯……嗯，啊」", "len422_161.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5429, "", "蕾娜先是愣了一下，然后似乎终于想明白了，脸色也肉眼可见地红了起来。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5430, "蕾娜", "「哦，哦……并不是弄疼你了吗？」", "len422_162.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5431, "将臣", "「怎么会疼呢……」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5432, "将臣", "「就算你慢慢地动也舒服得不得了，让我都不知道该怎么办了」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5433, "蕾娜", "「呵呵，那样的话……嗯……嗯，那我暂时就慢慢地动哦。哈，哈」", "len422_163.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5434, "蕾娜", "「因为我想让……嗯，将臣……觉得更舒服」", "len422_164.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5435, "", "但是，仔细一看这真是无比色情的场景。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5436, "", "硬硬的阴茎在软乎乎的乳房之间进进出出。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5437, "", "况且那还是我的阴茎……在蕾娜的乳房之间……", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5438, "蕾娜", "「那……那个，将臣？哈……哈，嗯，你的……这个，该怎么称呼才好？」", "len422_165.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5439, "将臣", "「……哎？这个是指性器官？」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5440, "蕾娜", "「对……嗯，嗯……因为这类词汇……学校是不会教我的」", "len422_166.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5441, "蕾娜", "「……就算想要……学习，嗯嗯，怎样能让……将臣舒服起来，不知道名字怎么叫怎么学，哈，哈」", "len422_167.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5442, "将臣", "「蕾娜……我想想」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5443, "将臣", "「叫阴茎、阴道不行吗？」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5444, "蕾娜", "「将，将臣！……那可不行，那种词……实在太露骨了，啊，嗯」", "len422_168.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5445, "将臣", "「哎？」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5446, "蕾娜", "「可以的话……我想用日语来说，哈，呼……不然的话，实在太羞人了」", "len422_169.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5447, "将臣", "「虽然对我来说那样反而更加露骨了」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5448, "", "我也没办法用英语仔细说明龟头、系带这类细节部分。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5449, "蕾娜", "「呜呜呜……请用对我来说不那么羞耻的词来说，啊」", "len422_170.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5450, "将臣", "「那，男性性器官……叫大●鸡怎样？」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5451, "蕾娜", "「哦，日语中……就连性器官前面都要加上“御”字啊，嗯……嗯，唔」", "len422_171.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5452, "将臣", "「还有……女人的那个叫小●穴」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5453, "蕾娜", "「……小●穴啊，哈……嗯……嗯，小●穴……我学会了！」", "len422_172.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5454, "", "蕾娜天真无邪地从口中轻易说出了如此下流的词汇。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5455, "", "让我的心脏都突然跳了一下。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5456, "蕾娜", "「啊！……呵呵，将臣，你的大●鸡，哈……哈……刚才跳了一下吧？」", "len422_173.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5457, "蕾娜", "「嗯，嗯……明明只有在……慢慢动，哈……你觉得有那么舒服吗？」", "len422_174.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5458, "将臣", "「嗯，好像快射了」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5459, "", "其实，只要她稍微加快点腰部的动作我就随时都可能射精。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5460, "蕾娜", "「呵呵……为了感谢你教我这些词语……嗯，嗯，我得赶快让……你的大●鸡，舒服起来呢？」", "len422_175.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5461, "", "蕾娜加快了速度，用力将充满弹性的乳房推过来。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5462, "", "我刚才说了，她光是这样我就受不了了。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5463, "蕾娜", "「哈，哈……将臣，将臣！嗯，嗯……感觉怎样？不会痛吗？嗯嗯」", "len422_176.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5464, "将臣", "「啊，连根部……都埋进去了，唔！蕾娜，你的奶子真的好大啊」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5465, "蕾娜", "「啊！你也是啊……嗯，嗯，被奶子夹着……又变得更大了，啊啊！」", "len422_177.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5466, "", "蕾娜的奶子上下揉搓着我的阴茎。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5467, "", "每动一次都摇晃个不停。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5468, "蕾娜", "「嗯，嗯！将臣，将臣……哈，哈，从你身上传来色色的气味，嗯！」", "len422_178.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5469, "", "不行，不行了！被她这样一弄我已经要！", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5470, "将臣", "「……嗯，已经要射了！蕾娜，我要射了」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5471, "蕾娜", "「好……好的，那么……就这样射出来！哈，啊……从你的，你的……大●鸡里，啊，啊！」", "len422_179.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5472, "蕾娜", "「……射出好多的……好多的精液来。将臣，将臣！」", "len422_180.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5473, "蕾娜", "「啊，啊啊！哈……呀！？」", "len422_181.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5474, "", "阴茎在乳房的包裹下不停地跳动着。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5475, "蕾娜", "「啊……嗯，啊哇哇，你的大●鸡……在乱动着，嗯嗯！热热的东西在不停射出来」", "len422_182.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5476, "蕾娜", "「射出来……好多，啊……啊，这就是……\\n嗯～」", "len422_183.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5477, "", "精液像是泉水一样从蕾娜的山谷间满溢出来。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5478, "", "啊，对我来说……蕾娜的乳交让我第一次体会到被女孩子弄到射精的感觉。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5479, "", "这种感觉大概我一辈子都不会忘记。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5480, "蕾娜", "「哈……哈……这好厉害……这些，全都是你的子子孙孙吧。啊哈」", "len422_184.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5481, "蕾娜", "「……这个东西，叫什么名字？」", "len422_185.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5482, "将臣", "「精液……射出精液这件事叫做射精」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5483, "", "我一边这样说，一边摸了摸蕾娜的头。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5484, "将臣", "「你弄得我非常舒服，蕾娜」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5485, "蕾娜", "「呵呵……我也是，看到你射了这么多出来……我也很开心？而且，嗯」", "len422_186.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5486, "蕾娜", "「……将臣，你还是这么硬……嗯，嗯……我能感觉到你刚才非常舒服，啊」", "len422_187.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5487, "将臣", "「嗯……确实是那样，蕾娜……蕾娜」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5488, "", "我不由得伸出手揉起了蕾娜的乳房。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5489, "", "就连双手都没法握住的重量感和无与伦比的柔软，让我的神经更加兴奋起来。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5490, "蕾娜", "「啊，啊……不要随便摸哦，将臣。嗯」", "len422_188.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5491, "将臣", "「嗯，但是……以前我都尽量让自己不去看它，不去用它想一些色色的事情」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5492, "将臣", "「所以现在能堂堂正正地触摸它让我高兴得不得了」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5493, "蕾娜", "「真是的……这种事情，嗯……你想摸随时都可以摸，我的胸部，是只属于你一个人的！」", "len422_189.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5494, "", "我在不知不觉之中开始在乳房里抽插起来。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5495, "", "蕾娜也配合我的动作，慢慢地前后摇晃身体。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5496, "蕾娜", "「啊，啊！……嗯，比刚才湿滑了不少……啊，连我都有点……色色的感觉了」", "len422_190.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5497, "将臣", "「我也是……感觉比刚才更舒服」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5498, "", "本来用乳房摩擦就已经很舒服了，现在又有了精液当润滑油。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5499, "", "光是看到阴茎在柔软的肉谷之间上下滑动，我就已经受不了了。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5500, "蕾娜", "「哈，啊……嗯，啊！将臣……连你自己也在抽动腰部了，啊！」", "len422_191.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5501, "蕾娜", "「你每次插进来，啊！……乳、乳头也会碰到你的肚子……啊！」", "len422_192.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5502, "蕾娜", "「一边发出……啊，那种搅拌的啾啾声……呼！一边还有那种撞击的啪啪声，哈唔！」", "len422_193.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5503, "", "是不是有点粗暴了？其实我是明白的。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5504, "", "虽然脑子里明白，但身体已经管不住了。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5505, "蕾娜", "「将臣？请……稍微冷静一点？啊，接下来……还有……嗯嗯」", "len422_194.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5506, "蕾娜", "「……接下来要有小●穴哦。呼，啊……我可不要，只用奶子……就结束了，啊！」", "len422_195.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5507, "将臣", "「那，那大概是没问题的……就这样，就这样再射一次」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5508, "蕾娜", "「嘿嘿……嗯，嗯！真拿你没办法……哈，啊！啊！」", "len422_196.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5509, "", "说实话，今晚我已经兴奋到无论几次都能射出来的程度了。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5510, "", "我一边被射精冲动侵蚀着。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5511, "", "一边在心里祈祷，希望能和蕾娜一次又一次地交合。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5512, "蕾娜", "「嗯，嗯……啊，啊！将臣，将臣……那你就不要客气……不要忍耐了」", "len422_197.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5513, "蕾娜", "「尽情地……尽情地舒服起来吧，将臣……将臣，哈啊！？」", "len422_198.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5514, "", "我，我已经……", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5515, "蕾娜", "「啊，啊！将臣……啊，啊，你腰动得那么快的话，啊！」", "len422_199.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5516, "", "我无法忘记刚才的快感。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5517, "", "只想再一次，再一次沉浸在快感的海洋中。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5518, "蕾娜", "「嗯，嗯！啊，啊……我，我也是……乳头被不停地摩擦，啊！变得越来越舒服了」", "len422_200.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5519, "将臣", "「真的吗？蕾娜也觉得舒服吗？蕾娜，蕾娜！」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5520, "蕾娜", "「是的……我也是，我也觉得好舒服！将臣，将臣！嗯，啊！呼啊」", "len422_201.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5521, "", "好舒服，好舒服！", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5522, "", "粗重的呼吸互相重叠，我们两个人一起舒服起来了！", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5523, "蕾娜", "「啊，啊，啊！哈，将臣，将臣！又……又在奶子之间变粗了！」", "len422_202.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5524, "将臣", "「啊，射了！又要射了，又要射了，接住它。蕾娜！蕾娜！」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5525, "蕾娜", "「好，好的……我会接住你的子孙们……接住你的精液的，啊，啊！」", "len422_203.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5526, "蕾娜", "「多点……再多点！快点射出来吧，将臣！将臣，啊，唔啊！？」", "len422_204.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5527, "", "我一口气将阴茎推进蕾娜乳房的山谷间！", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5528, "蕾娜", "「呀，啊！唔啊……将臣的，将臣的……大●鸡，又要……啊，啊」", "len422_205.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5529, "蕾娜", "「多点……多射一点哦，哈，啊……」", "len422_206.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5530, "", "阴茎在山谷间激烈地跳动着。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5531, "", "每跳动一次，就有大滴的白浊液从乳房下方牵着丝滴下来，就像是蕾娜的奶子在射精一样。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5532, "蕾娜", "「哈……哈……都第二次了，依然……会射出这么多来吗？」", "len422_207.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5533, "将臣", "「不，我自己也是……吓了一跳，因为你看」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5534, "蕾娜", "「呼，啊！……哎？将臣的，依然……这么大？」", "len422_208.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5535, "", "我将依然保持着硬度的阴茎再一次在她的奶子上面蹭。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5536, "蕾娜", "「啊，啊！将臣……你插得，嗯！那么深的话，啊！头……头部都露出来了！」", "len422_209.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5537, "", "从我的腰部深处传来的酸麻感越来越重。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5538, "", "就算我想停下，也已经不能制止了。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5539, "蕾娜", "「哈，啊啊……将臣，你的、你的……嗯！那里、居然变得这么大，哈」", "len422_210.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5540, "将臣", "「咕，唔！蕾娜……你的脸靠得好近！？」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5541, "蕾娜", "「因为……哈，哈！大●鸡……在奶子里面好像很舒服地……颤抖着，哈！」", "len422_211.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5542, "", "快感，快感带着滚烫的高温，即将像岩浆一样爆发出来，。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5543, "", "已经止不住了！没法停止了！！", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5544, "蕾娜", "「我也是……我也是！色色的感觉变得越来越……越来越强，啊，哈！啊！」", "len422_212.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5545, "将臣", "「……你也是？咕，我也是……我也要射了！要射了，蕾娜！」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5546, "蕾娜", "「好的……哈，哈！我能感觉到。你的……你的小兄弟要是能够……能够」", "len422_213.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5547, "蕾娜", "「变得很舒服的话……我，我也是，啊，啊！啊，唔啊！」", "len422_214.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5548, "蕾娜", "「哎？……呀！啊，哈啊啊！？」", "len422_215.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5549, "", "我忍不住向蕾娜的脸上射精了。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5550, "蕾娜", "「嗯，嗯……嗯！」", "len422_216.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5551, "", "每当火热的激情从阴茎里穿过，就有大块的白浊液弄脏蕾娜的脸。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5552, "", "连我都没想到第二次居然会有这样的浓度和量。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5553, "蕾娜", "「哈，哈……这就是日本的……“颜射”吗？」", "len422_217.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5554, "将臣", "「抱歉，蕾娜！你肯定不喜欢这种吧？」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5555, "蕾娜", "「不……这种……哈……哈……没有想象中……那么抵触……」", "len422_218.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5556, "蕾娜", "「因为是喜欢的人的……精液，所以我才会这么开心吧」", "len422_219.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5557, "将臣", "「蕾娜……那么，大概我也是一样」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5558, "", "我将依然保持着硬度的阴茎轻轻地摆在了她的眼前。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5559, "将臣", "「看起来依然完全没有消下去」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5560, "蕾娜", "「……哇，将臣，你的……大●鸡，实在是太有精神了」", "len422_220.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5561, "将臣", "「毕竟有你在我眼前嘛」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5562, "", "我弯下腰，轻轻地亲了下她的额头。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5563, "", "这下仿佛成了一个信号。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5564, "", "让蕾娜准备改变体位。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5565, "蕾娜", "「将臣……将臣……你能不能躺到那边去」", "len422_221.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5566, "将臣", "「哎？嗯」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev411a", null], [5567, "蕾娜", "「哈……啊，你的那个……非常大啊，它碰到我的身上了……嗯，嗯嗯」", "len422_222.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5568, "", "等我躺到床上之后，蕾娜跨坐到我身上。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5569, "", "我记得蕾娜应该是第一次吧？", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5570, "将臣", "「难道说……你要在上面？没问题吗？」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5571, "蕾娜", "「……是的，听说……由自己来做会没有那么痛，嗯，而且……」", "len422_223.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5572, "蕾娜", "「嘿嘿，我想要……让你更舒服一些」", "len422_224.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5573, "将臣", "「我觉得我已经舒服过头了」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5574, "蕾娜", "「没关系的……嗯，嗯，你也是……第一次吧？既然如此……」", "len422_225.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5575, "蕾娜", "「……我也想要夺走你的处男哦」", "len422_226.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5576, "", "原来是肉食系啊。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5577, "", "我切身体会到，蕾娜明明那么容易害羞，骨子里却有着肉食系的一面。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5578, "", "这样的话，这次或许任由她摆布比较好。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5579, "将臣", "「那……你不要再吊我胃口了，已经可以插入了吗？」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5580, "蕾娜", "「好的，嗯……在用奶子做的时候……我好像也有感觉了！」", "len422_227.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5581, "", "蕾娜那凉凉的手指摸上了我的性器官。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5582, "蕾娜", "「呵呵呵，将臣……你的这里变得好热哦」", "len422_228.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5583, "将臣", "「……嗯，它好像想要尽快进入你身体里面」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5584, "", "事到如今，我已经没必要掩饰自己的欲望了。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5585, "", "因为现在，我确确实实正在被蕾娜玩弄于手掌之中。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5586, "蕾娜", "「那，那么……我要开始了哦。哈！？」", "len422_229.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5587, "将臣", "「啊，唔！」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5588, "", "龟头碰到了又软又湿的东西。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5589, "", "那里和我一样，也变得火热。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5590, "蕾娜", "「你的小兄弟……嗯，好大，哈，啊……感觉明显比我的那里更大」", "len422_230.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5591, "将臣", "「没关系吧？要是你受不了的话就停下吧」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5592, "蕾娜", "「不，没关系！我绝对不要……停下……好不容易能和你一起，嗯」", "len422_231.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5593, "", "她的腰稍微向下沉了一点。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5594, "", "龟头的尖端部分被吞进了蕾娜身体里面。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5595, "将臣", "「……～」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5596, "", "仅仅只是这样，就瞬间给我带来了让我无法呼吸的，无法形容的快感。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5597, "", "不是吧？仅仅只是碰到一下，就这么厉害？", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5598, "蕾娜", "「哈，啊？没问题……似乎能随着你的插入自己张大，嗯」", "len422_232.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5599, "将臣", "「……唔，嗯」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5600, "", "这一声回答已经让我倾尽全力了。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5601, "", "等下这种感觉要传遍整个阴茎吗？", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5602, "蕾娜", "「哈……哈……啊，将臣？」", "len422_233.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5603, "", "蕾娜红着脸，回头看向我。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5604, "蕾娜", "「我爱你，将臣」", "len422_234.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5605, "将臣", "「啊……嗯」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5606, "将臣", "「我也爱你，蕾娜」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5607, "", "下一个瞬间，我的阴茎被一口气吞进去了。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5608, "蕾娜", "「哈……啊呜呜呜呜～～～！！？」", "len422_235.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5609, "将臣", "「……～～～」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5610, "", "伴随着像是顶破了某种柔软的胶皮一样的感觉，我的龟头击中了蕾娜最深处的肉壁。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5611, "", "我连关照她一声的余力都没有，现在依然是连呼吸都困难。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5612, "", "要是刚才没有射过两次的话，刚才这一下绝对会让我射精！", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5613, "蕾娜", "「嗯，嗯嗯……好痛，好痛啊，但是……啊，这样就，嗯！」", "len422_236.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5614, "蕾娜", "「我和你……和你合二为一了」", "len422_237.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5615, "将臣", "「啊，啊……我也能明确感觉到……你的触感」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5616, "", "破瓜的鲜血滴了下来，看着都觉得疼。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5617, "", "可尽管如此，我还是舒服得忍不住擅自挺起了腰身。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5618, "蕾娜", "「啊，啊！将……将臣？你暂时不要动……哈，唔啊」", "len422_238.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5619, "将臣", "「不，不是，但是这种……！」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5620, "", "看起来，像是蕾娜正在用阴道把我吸进去一样。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5621, "", "一片片肉褶紧紧贴着阴茎，紧包着像是要把它拉进深处一样。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5622, "将臣", "「你的里面……夹得好紧，一般女人都是这样吗？」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5623, "蕾娜", "「哎？那……那种事我哪知道……我哪知道，但是……哈，啊」", "len422_239.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5624, "蕾娜", "「……明明还很痛，嗯，嗯……但是用身体的深处……感受到你的那里，哈，哈」", "len422_240.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5625, "蕾娜", "「感觉好像都麻了……有种非常温暖的感觉……嗯」", "len422_241.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5626, "", "蕾娜轻轻地开始摇晃腰部。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5627, "", "我也配合着她的节奏，慢慢地开始抽插。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5628, "蕾娜", "「哈，哈……嗯，啊！果然……果然还是好痛，却又感觉好舒服。将臣，将臣！」", "len422_242.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5629, "", "看起来她并不像是在硬撑。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5630, "", "所以我也从她背后把手伸向她的乳房。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5631, "蕾娜", "「啊，啊～！那个……感觉好色哦，啊，啊！哈啊」", "len422_243.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5632, "将臣", "「唔，蕾娜……你要是继续收紧的话」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5633, "蕾娜", "「哎？呵呵……难道说我的小●穴……有那么舒服吗？哈，啊！」", "len422_244.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5634, "蕾娜", "「你舒服得……啊！啊，快要……射精了吗？将臣……将臣？」", "len422_245.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5635, "", "蕾娜居然开始加速腰部运动。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5636, "", "为了忍耐快感，我只能紧紧抓住乳房。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5637, "蕾娜", "「哈啊！将臣……不要忍耐哦？你要是多射一点的话，我也会开心的，啊，啊！」", "len422_246.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5638, "蕾娜", "「而且……快一点射出来的话，啊，啊！我也比较有……拿了你的处男的感觉，哈啊啊！」", "len422_247.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5639, "", "就算你这样说，我都已经射了两次了，实在不想再这么快射了。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5640, "", "所以要忍耐。想忍耐，明明打算忍耐的……", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5641, "", "不管我的意志有多坚固，在这种能让我整个人都融化的快感面前，也是毫无用处。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5642, "蕾娜", "「啊，啊！嗯，嗯……啊！你的小兄弟，在我的里面又变粗了……这是？哈唔」", "len422_248.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5643, "将臣", "「求……求你了，让我歇会」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5644, "", "这样的话，我还能坚持住！明明还能坚持住的。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5645, "蕾娜", "「这可不行哦。不要忍耐，啊啊啊！要尽量多射一点哦，将臣。啊」", "len422_249.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5646, "", "啊，我在忍耐！明明在忍耐的。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5647, "", "这种情况根本忍耐不住！", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5648, "蕾娜", "「嗯，嗯，嗯！啊……我也是，嗯！我也是，麻麻的感觉……越来越强了，啊！」", "len422_250.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5649, "将臣", "「咕，要……要射了，要射了哦，蕾娜！快让开。咕，唔唔！」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5650, "蕾娜", "「哈，啊！没事的……我特地选的安全的日子了，啊，啊！啊啊」", "len422_251.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5651, "蕾娜", "「所……所以，我希望你，嗯！在我里面……在我的小●穴里射精，啊！」", "len422_252.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5652, "蕾娜", "「在我里面。永远在我的里面……射个痛快，将臣！将臣！嗯咕」", "len422_253.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5653, "蕾娜", "「啊，嗯！？唔啊啊……啊？」", "len422_254.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5654, "", "我无法抵抗快感，将龟头顶住蕾娜的子宫，尽情地射精了。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5655, "蕾娜", "「嗯……在里面一跳一跳的……啊，果然……是射了吧。啊啊」", "len422_255.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5656, "蕾娜", "「在小●穴里面……你的子子孙孙们，嗯嗯……射了……好多好多，哈啊……」", "len422_256.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5657, "", "刚才还是处女的阴道现在已经被我的雄性体液给填满，导致液体都溢了出来。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5658, "", "就连纯洁之证也被白浊液冲了出来。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5659, "", "然而蕾娜却是一脸爱意地抚摸着她的下腹部。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5660, "蕾娜", "「哈……哈……呵呵，你的……第一次，全部……进到我的里面了」", "len422_257.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5661, "蕾娜", "「好……好高兴……你的一切都是我的东西哦」", "len422_258.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5662, "将臣", "「嗯，但是……你还没有满足吧？」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5663, "蕾娜", "「……满足？你是指性高潮吗？」", "len422_259.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5664, "将臣", "「我也是……想要把蕾娜的一切都变成我的东西」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5665, "", "这次轮到我从下面顶起蕾娜了。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5666, "", "连我自己都吓到了，我居然还保持着足够的硬度。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5667, "蕾娜", "「哈，哈！啊……哎？将臣……你都射了那么多了，居然……还这么硬，哈啊啊！」", "len422_260.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5668, "将臣", "「嗯，所以这次……我要让你也高潮」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5669, "蕾娜", "「将臣，我……我！啊，啊！唔啊啊，怎么会……这么粗暴，嗯？啊」", "len422_261.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5670, "", "我从她后面抓住她的双手，有点粗暴地顶着她。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5671, "", "虽然是第一次，但蕾娜已经不再喊疼了。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5672, "蕾娜", "「哈！啊？……好舒服。嗯，啊！跟刚才比，跟刚才比，完全不一样，啊！？」", "len422_262.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5673, "", "蕾娜向后弓着身体，大声叫了起来。随着她的动作，巨大的乳房也摇晃着。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5674, "", "我正在带给蕾娜快感！", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5675, "蕾娜", "「哈，啊！啊啊……将臣，将臣！好舒服，我也好舒服，啊～！」", "len422_263.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5676, "将臣", "「我能感觉到。蕾娜……在不停地夹紧我」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5677, "蕾娜", "「嗯～！因为，将臣你才是……明明都做了这么多次了，啊！」", "len422_264.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5678, "蕾娜", "「居然比刚才，比刚才……更硬了，啊！啊，啊～！？」", "len422_265.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5679, "", "果然，蕾娜的里面太舒服了。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5680, "", "无论多少次我都能做。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5681, "蕾娜", "「将臣，将臣！比刚才更深了，啊！子宫被顶起来了啊，啊唔！」", "len422_266.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5682, "将臣", "「……难道不是你的子宫降下来了吗？」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5683, "将臣", "「你没听说过吗，有感觉的话就会变成那样？」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5684, "蕾娜", "「哈，嗯，那么……是我的子宫，啊，啊！正在准备……嗯」", "len422_267.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5685, "蕾娜", "「……正在准备迎接你的精液吗？哈，唔……啊！」", "len422_268.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5686, "", "射精冲动再一次提高了。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5687, "", "被这么紧紧包住，我坚持不了多久！", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5688, "蕾娜", "「啊，啊！嗯，啊啊啊，越来越……麻麻的感觉……越来越强了，啊唔！」", "len422_269.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5689, "蕾娜", "「身体，身体自说自话……啊，唔！啊，浮起来了，浮起来了，啊！？」", "len422_270.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5690, "将臣", "「没……没关系的，你也抓紧我的手臂。一起，一起高潮吧！」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5691, "蕾娜", "「好、好的……将臣！将臣，我也要……我也要第一次高潮了，啊啊！」", "len422_271.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5692, "蕾娜", "「和将臣一起……被将臣弄得高潮了，啊，啊！将臣，将臣！」", "len422_272.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5693, "", "我要……", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5694, "蕾娜", "「将臣！将臣，那么深……啊！在不停地亲吻我的子宫，啊！」", "len422_273.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5695, "", "我也无法抗拒本能。也没有必要抗拒。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5696, "", "我想要把精液注入蕾娜，注入我最喜欢的人的子宫里！", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5697, "蕾娜", "「哈，啊啊！嗯，啊……哈，啊～！好像真的……有什么，要来了，哈啊！？」", "len422_274.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5698, "将臣", "「就快了，还差一点了，蕾娜！蕾娜，我喜欢你蕾娜！」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5699, "蕾娜", "「将臣？将臣，我也是……我也好喜欢你，喜欢，喜欢喜欢喜欢，啊啊！？」", "len422_275.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5700, "", "我们带着同一种感情，紧紧地，紧紧地握住了彼此的手。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5701, "", "已经无法思考了！现在我的大脑除了蕾娜以外什么都容不下！", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5702, "蕾娜", "「啊，啊！啊，哈啊！？……身体，身体真的浮起来了，要去了！要去了，去了，我要去了啊」", "len422_276.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5703, "将臣", "「我也是，我也是！蕾娜，蕾娜！」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5704, "蕾娜", "「哈，啊！我也……我也是，将臣！将臣让我，将臣让我，啊啊啊！？」", "len422_277.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5705, "蕾娜", "「……第一次、第一次高潮了！！啊，哈啊！」", "len422_278.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5706, "蕾娜", "「将臣，我要去了！将臣，将臣，啊，哈啊啊啊！！」", "len422_279.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5707, "蕾娜", "「唔啊啊啊啊啊啊啊～～～！！！」", "len422_280.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5708, "", "蕾娜整个人往后仰，将身体向后翘曲到极限。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5709, "", "几乎在那同一时刻，我在蕾娜的阴道内，射出了最后的精液。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5710, "蕾娜", "「哈，啊……啊啊啊，你又……又射了吧？啊，啊……将臣，你的……精液，啊啊啊……」", "len422_281.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5711, "", "我的阴茎紧贴着蕾娜的子宫的入口，在她体内不停地跳动着。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5712, "", "蕾娜也贪婪地紧包着我，榨干了我最后的一滴精液。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5713, "蕾娜", "「嗯，嗯啊……哈……啊，啊啊……呵呵，刚才的……就是高潮吧？」", "len422_282.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5714, "蕾娜", "「当你射在我里面的时候，嗯嗯……我也第一次高潮了哦」", "len422_283.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5715, "将臣", "「嗯……你的里面也包得好紧，非常舒服哦」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5716, "蕾娜", "「呵呵……我也是一样……是一样的哦，将臣……嗯～」", "len422_284.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5717, "蕾娜", "「哈，啊！好舒服，好舒服啊，将臣！我能感受到，能感受到你的触感」", "len422_285.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5718, "", "我的腰部深处再一次热了起来，狂暴的冲动变得更加强烈。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5719, "", "而且，就连蕾娜也和我一样，因为相同的冲动兴奋了起来。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5720, "蕾娜", "「哈，啊，啊！啊……我，我也要……去了！要去了，将臣！将臣！」", "len422_286.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5721, "将臣", "「我也马上要去了！蕾娜，蕾娜！」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5722, "蕾娜", "「一起……我们一起去吧，将臣？我也是，想要将我的一切……都变成你的东西，哈啊啊！」", "len422_287.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5723, "", "只要有蕾娜在，只要有蕾娜在，我的内心就能被填满。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5724, "", "我也想要就这样，就这样将蕾娜的一切都变成自己的东西！", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5725, "蕾娜", "「哈，啊！我喜欢你哦，将臣。喜欢，喜欢喜欢喜欢……最喜欢你了，哈，啊！」", "len422_288.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5726, "将臣", "「我也是，我也是蕾娜！蕾娜，我要射了，这次要射在你的身体上！」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5727, "蕾娜", "「啊，啊啊，好的……给我留下，嗯嗯，我属于你的证据吧，啊，啊！」", "len422_289.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5728, "蕾娜", "「……希望、你能给我留下好多好多的记号，将臣，将臣！」", "len422_290.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5729, "蕾娜", "「啊，啊，啊！啊，啊，啊啊，哈……嗯，啊唔！？」", "len422_291.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5730, "蕾娜", "「嗯啊啊啊啊啊～～～！！！」", "len422_292.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5731, "", "蕾娜激烈地颤抖着身体。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5732, "", "随后我马上拔出阴茎，向着她射出精液。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5733, "蕾娜", "「啊，啊……好多，这么多……喷出了这么多！将臣……好厉害，好厉害，啊啊……」", "len422_293.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5734, "", "阴茎猛地弹出来，像是在击打着蕾娜的下腹部一样，一跳一跳地喷洒着白浊液。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5735, "", "就这样，我将蕾娜的身体完全染成了我的颜色。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5736, "蕾娜", "「哈……哈……嗯，刚才……好舒服啊，将臣」", "len422_294.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5737, "蕾娜", "「我的一切真的完全……都变成你的东西了呢……哈，嗯」", "len422_295.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5738, "将臣", "「我的一切也完全变成你的东西了哦？」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5739, "蕾娜", "「嘿嘿……我们现在……都属于对方，啊」", "len422_296.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 6-2", "ev412a", null], [5740, "", "这时，蕾娜好像用尽了力气一样倒向了我。", null, "旅館_レナの部屋d", "bgm40.opus", null, "CHAPTER 6-2", null, null], [5741, "", "我从蕾娜背后接住她，然后沉浸在无法言喻的满足感中。", null, "旅館_レナの部屋d", "bgm40.opus", null, "CHAPTER 6-2", null, null], [5742, "", "这世界上有个能接受我的女孩子。", null, "旅館_レナの部屋d", "bgm40.opus", null, "CHAPTER 6-2", null, null], [5743, "", "虽然这样说有点夸张，但这让我强烈而明确地感受到我还活着。", null, "旅館_レナの部屋d", "bgm40.opus", null, "CHAPTER 6-2", null, null], [5744, "", "……因为这点事就感触良多，是因为我太单纯了吗？", null, "旅館_レナの部屋d", "bgm40.opus", null, "CHAPTER 6-2", null, null], [5745, "", "但是就在这时，蕾娜用力地握住了我的手。", null, "旅館_レナの部屋d", "bgm40.opus", null, "CHAPTER 6-2", null, null], [5746, "蕾娜", "「我爱你，将臣」", "len422_297.ogg", "空_夜空", "bgm40.opus", null, "CHAPTER 6-2", null, null], [5747, "将臣", "「啊……」", null, "空_夜空", "bgm40.opus", null, "CHAPTER 6-2", null, null], [5748, "", "只是，我突然明白，蕾娜心情其实也和我一样。", null, "空_夜空", "bgm40.opus", null, "CHAPTER 6-2", null, null], [5749, "", "我十分确信。", null, "空_夜空", "bgm40.opus", null, "CHAPTER 6-2", null, null], [5750, "将臣", "「我也爱你，蕾娜」", null, "空_夜空", "bgm40.opus", null, "CHAPTER 6-2", null, null], [5751, "蕾娜", "「……啾，呵呵～我知道的啦」", "len422_298.ogg", "空_夜空", "bgm40.opus", null, "CHAPTER 6-2", null, null], [5752, "", "所以我们亲吻着对方，紧紧地抱在一起。", null, "空_夜空", "bgm40.opus", null, "CHAPTER 6-2", null, null], [5753, "", "不一会儿，我们就甜甜地入睡了。", null, "空_夜空", "bgm40.opus", null, "CHAPTER 6-2", null, null], [5754, "将臣", "「（嗯？……喔！）」", null, "山_川沿いa", "bgm36.opus", null, "CHAPTER 7-1", null, null], [5755, "", "看来，我们好像真的成功进入到宿体的记忆中了。", null, "山_川沿いa", "bgm36.opus", null, "CHAPTER 7-1", null, null], [5756, "", "刚才我应该是和蕾娜睡在同一个被窝里。", null, "山_川沿いa", "bgm36.opus", null, "CHAPTER 7-1", null, null], [5757, "", "现在怀里还能感受到她的体温。", null, "山_川沿いa", "bgm36.opus", null, "CHAPTER 7-1", null, null], [5758, "", "在现实中，恐怕我们依然紧紧抱在一起睡着。", null, "山_川沿いa", "bgm36.opus", null, "CHAPTER 7-1", null, null], [5759, "蕾娜", "「（将臣？将臣，你也在吗）」", "len423_001.ogg", "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "04"}, "CHAPTER 7-1", null, null], [5760, "将臣", "「（果然蕾娜也来了啊）」", null, "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "04"}, "CHAPTER 7-1", null, null], [5761, "蕾娜", "「（看来是成功了！）」", "len423_002.ogg", "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 7-1", null, null], [5762, "将臣", "「（没想到能够这么顺利……这里是哪里？）」", null, "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 7-1", null, null], [5763, "蕾娜", "「（我觉得应该是在穗织的后山上……啊！将臣，那边有人）」", "len423_003.ogg", "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "14"}, "CHAPTER 7-1", null, null], [5764, "将臣", "「（真的啊）」", null, "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "14"}, "CHAPTER 7-1", null, null], [5765, "", "有一名男性正在河边一言不发地用木刀练习素振。", null, "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "14"}, "CHAPTER 7-1", null, null], [5766, "", "我想他应该是在锻炼剑术。", null, "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "14"}, "CHAPTER 7-1", null, null], [5767, "", "也就是说，他是武士吗？真是武士的话，他穿得未免太寒酸了。", null, "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "14"}, "CHAPTER 7-1", null, null], [5768, "蕾娜", "「（……将臣，那个人看起来是不是和你长得很像？）」", "len423_004.ogg", "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "23"}, "CHAPTER 7-1", null, null], [5769, "将臣", "「（哎！？没有吧，等等，我才没有那么……咦？）」", null, "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "23"}, "CHAPTER 7-1", null, null], [5770, "将臣", "「（哇哇哇，怎么了！？）」", null, "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "23"}, "CHAPTER 7-1", null, null], [5771, "", "我突然有种被那个男人吸进去的感觉。", null, "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "23"}, "CHAPTER 7-1", null, null], [5772, "蕾娜", "「（哇！那个男人变成将臣了！？）」", "len423_005.ogg", "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "19"}, "CHAPTER 7-1", null, null], [5773, "将臣", "「（难道说和之前做的梦一样？就是蕾娜变成女神的那次……）」", null, "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "19"}, "CHAPTER 7-1", null, null], [5774, "将臣", "「……那个女人又来了啊」", null, "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "19"}, "CHAPTER 7-1", null, null], [5775, "", "哎？刚才我的嘴动了？", null, "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "19"}, "CHAPTER 7-1", null, null], [5776, "", "不对，是这个人自己在说话吗？好混乱啊。", null, "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "19"}, "CHAPTER 7-1", null, null], [5777, "", "但是当我注意到他视野中的那个人时，不由得吓了一跳。", null, "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "19"}, "CHAPTER 7-1", null, null], [5778, "将臣", "「（啊！是之前那位女神大……）」", null, "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "19"}, "CHAPTER 7-1", null, null], [5779, "将臣", "「（……人？）」", null, "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "01"}, "CHAPTER 7-1", null, null], [5780, "", "女神大人又变成了蕾娜的样子。", null, "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "01"}, "CHAPTER 7-1", null, null], [5781, "蕾娜", "「（哦哦，看来在梦中扮演的角色只要确定一次，接下来每次都会扮演同一个人）」", "len423_006.ogg", "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "27"}, "CHAPTER 7-1", null, null], [5782, "", "也就是说，今后我也要继续扮演这个武士的角色吗？", null, "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "27"}, "CHAPTER 7-1", null, null], [5783, "", "不过话说回来，女神大人的样子看起来不太对劲。", null, "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "27"}, "CHAPTER 7-1", null, null], [5784, "女神", "「……～～」", "lem423_001.ogg", "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "06"}, "CHAPTER 7-1", null, null], [5785, "", "她注意到男人的视线，慌忙低下头藏在了树后。", null, "山_川沿いa", "bgm36.opus", null, "CHAPTER 7-1", null, null], [5786, "将臣", "「您找在下有什么事情吗？」", null, "山_川沿いa", "bgm36.opus", null, "CHAPTER 7-1", null, null], [5787, "女神", "「……哎？没事」", "lem423_002.ogg", "山_川沿いa", "bgm36.opus", null, "CHAPTER 7-1", null, null], [5788, "", "女神大人摆正了姿势，想要保持自己的威严。", null, "山_川沿いa", "bgm36.opus", null, "CHAPTER 7-1", null, null], [5789, "女神", "「你每次都到这么偏僻的地方来做些什么呢？」", "lem423_003.ogg", "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "23"}, "CHAPTER 7-1", null, null], [5790, "将臣", "「如您所见，在下正在练习剑术」", null, "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "23"}, "CHAPTER 7-1", null, null], [5791, "女神", "「我是想问，你为什么要练习剑术」", "lem423_004.ogg", "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "08"}, "CHAPTER 7-1", null, null], [5792, "将臣", "「在下乃是清和源氏旗下，义忠大人之郎党」", null, "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "08"}, "CHAPTER 7-1", null, null], [5793, "将臣", "「平日理应坚持锻炼，以备主公有命之时，即刻奔赴战场」", null, "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "08"}, "CHAPTER 7-1", null, null], [5794, "", "郎党？我记得这是家臣之类的意思吧？", null, "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "08"}, "CHAPTER 7-1", null, null], [5795, "", "虽然有一些不明所以的地方，总之他是想说自己是个底层武士。", null, "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "08"}, "CHAPTER 7-1", null, null], [5796, "", "……之前的梦里还出现过犬追物那种东西，这让我脑子里不由得浮现出平安末期到镰仓初期那个时代的景色。", null, "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "08"}, "CHAPTER 7-1", null, null], [5797, "女神", "「原来如此……你果然是这附近的居民啊」", "lem423_005.ogg", "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "32"}, "CHAPTER 7-1", null, null], [5798, "将臣", "「……是的，您说的没错」", null, "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "32"}, "CHAPTER 7-1", null, null], [5799, "将臣", "「恕我失礼，我看您像是高贵人家的千金」", null, "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "32"}, "CHAPTER 7-1", null, null], [5800, "将臣", "「您不带随从在这样的山中行走想必非常危险」", null, "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "32"}, "CHAPTER 7-1", null, null], [5801, "将臣", "「若是不嫌弃在下，在下愿意送您回去，还是请您尽快回家吧」", null, "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "32"}, "CHAPTER 7-1", null, null], [5802, "女神", "「不必了」", "lem423_006.ogg", "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "33"}, "CHAPTER 7-1", null, null], [5803, "将臣", "「但是……」", null, "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "33"}, "CHAPTER 7-1", null, null], [5804, "女神", "「我说不必了」", "lem423_007.ogg", "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "14"}, "CHAPTER 7-1", null, null], [5805, "女神", "「此处有一位刚健勇武之人，日复一日默默练习剑术，若有不测，他自会保护我」", "lem423_008.ogg", "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "03"}, "CHAPTER 7-1", null, null], [5806, "将臣", "「在下尚未熟习，自然不能缺少锻炼」", null, "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "03"}, "CHAPTER 7-1", null, null], [5807, "", "骗人。看你素振的样子我就知道，你至少比我厉害多了。", null, "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "03"}, "CHAPTER 7-1", null, null], [5808, "将臣", "「请问，您真的不打算回家吗？」", null, "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "03"}, "CHAPTER 7-1", null, null], [5809, "女神", "「…………」", "lem423_009.ogg", "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "08"}, "CHAPTER 7-1", null, null], [5810, "将臣", "「……这位小姐？」", null, "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "08"}, "CHAPTER 7-1", null, null], [5811, "女神", "「我不能在此处观看吗？」", "lem423_010.ogg", "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "23"}, "CHAPTER 7-1", null, null], [5812, "将臣", "「啊，哦……那倒是无妨」", null, "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "23"}, "CHAPTER 7-1", null, null], [5813, "", "男人本来觉得有她在会分心，一开始是打算把她赶走的。", null, "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "23"}, "CHAPTER 7-1", null, null], [5814, "", "但最终他并没有那么做。", null, "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "23"}, "CHAPTER 7-1", null, null], [5815, "将臣", "「这些锻炼，在一旁观看可并不有趣」", null, "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "23"}, "CHAPTER 7-1", null, null], [5816, "女神", "「即便如此……我也想看看」", "lem423_011.ogg", "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "06"}, "CHAPTER 7-1", null, null], [5817, "", "之后，男人也就不再说什么了。", null, "山_川沿いa", "bgm36.opus", null, "CHAPTER 7-1", null, null], [5818, "", "女神大人也把半边身体藏在树后，没有继续接近他。", null, "山_川沿いa", "bgm36.opus", null, "CHAPTER 7-1", null, null], [5819, "蕾娜", "「（哇哦，难道说这是一段爱情故事？）」", "len423_007.ogg", "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 7-1", null, null], [5820, "将臣", "「（真的吗？……也许，真的是吧）」", null, "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 7-1", null, null], [5821, "蕾娜", "「（怎么了？）」", "len423_008.ogg", "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "34"}, "CHAPTER 7-1", null, null], [5822, "将臣", "「（我在想，他看到女神大人的金发居然不会惊讶）」", null, "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "34"}, "CHAPTER 7-1", null, null], [5823, "蕾娜", "「（啊，这个嘛。其实她戴着边上有布的竹编斗笠那样的东西）」", "len423_009.ogg", "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 7-1", null, null], [5824, "蕾娜", "「（女神大人是故意不让他看见头发的）」", "len423_010.ogg", "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "01"}, "CHAPTER 7-1", null, null], [5825, "将臣", "「（……原来如此）」", null, "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "01"}, "CHAPTER 7-1", null, null], [5826, "", "在梦里她整个都变成蕾娜的样子了。这下更容易搞混了。", null, "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "01"}, "CHAPTER 7-1", null, null], [5827, "", "在那之后，无数个日夜过去了，男人一直都在努力锻炼。", null, "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "01"}, "CHAPTER 7-1", null, null], [5828, "", "女神大人也每天眺望着他。然而突然有一天——", null, "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "01"}, "CHAPTER 7-1", null, null], [5829, "女神", "「……打仗？你是说你也要出去打仗吗？」", "lem423_012.ogg", "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "15"}, "CHAPTER 7-1", null, null], [5830, "将臣", "「只是去讨伐贼人」", null, "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "15"}, "CHAPTER 7-1", null, null], [5831, "", "最近，乡下有一群和山贼差不多的无主武士在闹事，动不动就袭击村庄。", null, "山_川沿いa", "bgm36.opus", null, "CHAPTER 7-1", null, null], [5832, "", "那些山贼不知从什么时候开始在穗织这块地方安营扎寨，村民们无计可施，只好向主公求救。", null, "山_川沿いa", "bgm36.opus", null, "CHAPTER 7-1", null, null], [5833, "", "现在主公终于下定决心要讨伐他们，于是下达了出击命令。", null, "山_川沿いa", "bgm36.opus", null, "CHAPTER 7-1", null, null], [5834, "", "虽说对手是山贼，但我方也不是什么正规军，这个时代的武士基本上和山贼是半斤八两。", null, "山_川沿いa", "bgm36.opus", null, "CHAPTER 7-1", null, null], [5835, "", "也就是说，被打得惨败然后逃回来也不是什么少见的事情。", null, "山_川沿いa", "bgm36.opus", null, "CHAPTER 7-1", null, null], [5836, "将臣", "「没事，您不必担心」", null, "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "12"}, "CHAPTER 7-1", null, null], [5837, "将臣", "「只要能赶跑那群山贼，小姐今后也可以安心生活了」", null, "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "12"}, "CHAPTER 7-1", null, null], [5838, "女神", "「嗯……」", "lem423_013.ogg", "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "07"}, "CHAPTER 7-1", null, null], [5839, "", "但是，女神大人的表情并不开心。", null, "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "07"}, "CHAPTER 7-1", null, null], [5840, "", "她作为一方山神，自然知道盘踞在这里的山贼并没有那么好对付。", null, "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "07"}, "CHAPTER 7-1", null, null], [5841, "", "然而她身为神，也不可能代替人类去讨伐山贼。", null, "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "07"}, "CHAPTER 7-1", null, null], [5842, "女神", "「你能否在此稍候片刻？」", "lem423_014.ogg", "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "23"}, "CHAPTER 7-1", null, null], [5843, "将臣", "「那自然是没问题」", null, "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "23"}, "CHAPTER 7-1", null, null], [5844, "", "女神大人暂时离开了男人身边。", null, "山_川沿いa", "bgm36.opus", null, "CHAPTER 7-1", null, null], [5845, "", "我和男人化为一体，本来应该是不会知道到底发生了什么事的……", null, "山_川沿いa", "bgm36.opus", null, "CHAPTER 7-1", null, null], [5846, "蕾娜", "「（啊哇哇哇！你在做什么啊！？）」", "len423_011.ogg", "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "07"}, "CHAPTER 7-1", null, null], [5847, "将臣", "「（怎么了？）」", null, "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "07"}, "CHAPTER 7-1", null, null], [5848, "蕾娜", "「（这、这个…………哎？）」", "len423_012.ogg", "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "05"}, "CHAPTER 7-1", null, null], [5849, "", "女神大人若无其事地回来了。", null, "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "05"}, "CHAPTER 7-1", null, null], [5850, "女神", "「请带上这个」", "lem423_015.ogg", "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "08"}, "CHAPTER 7-1", null, null], [5851, "女神", "「这是我家代代相传的护身刀」", "lem423_016.ogg", "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "15"}, "CHAPTER 7-1", null, null], [5852, "", "……刀？看起来像是刀身较长的太刀。", null, "山_川沿いa", "bgm36.opus", null, "CHAPTER 7-1", null, null], [5853, "蕾娜", "「（她的骨头……全部是铁构成的）」", "len423_013.ogg", "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "23"}, "CHAPTER 7-1", null, null], [5854, "将臣", "「（什么？）」", null, "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "23"}, "CHAPTER 7-1", null, null], [5855, "蕾娜", "「（……女神大人用自己的骨头做出了这把神刀）」", "len423_014.ogg", "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "33"}, "CHAPTER 7-1", null, null], [5856, "", "确实，铁也是一种矿石。", null, "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "33"}, "CHAPTER 7-1", null, null], [5857, "", "不过她用的居然是自己的骨头。", null, "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "33"}, "CHAPTER 7-1", null, null], [5858, "将臣", "「（听起来就觉得好痛）」", null, "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "33"}, "CHAPTER 7-1", null, null], [5859, "蕾娜", "「（所以她是从心底里……想要守护这个男人……）」", "len423_015.ogg", "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "29"}, "CHAPTER 7-1", null, null], [5860, "", "蕾娜似乎能理解女神大人的心情。", null, "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "29"}, "CHAPTER 7-1", null, null], [5861, "", "她这样的付出确实很令人动容。但她竟然能做到这种程度，也就是说，她是真的……", null, "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "15"}, "CHAPTER 7-1", null, null], [5862, "将臣", "「这么好的东西！在下不能收下」", null, "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "15"}, "CHAPTER 7-1", null, null], [5863, "将臣", "「（什么！？）」", null, "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "15"}, "CHAPTER 7-1", null, null], [5864, "蕾娜", "「（你怎么不要，将臣！？）」", "len423_016.ogg", "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "21"}, "CHAPTER 7-1", null, null], [5865, "将臣", "「（不是我说的！是这个长得和我一样的人说的）」", null, "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "21"}, "CHAPTER 7-1", null, null], [5866, "", "为什么不能收下啊？", null, "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "21"}, "CHAPTER 7-1", null, null], [5867, "将臣", "「就算是在下，也能一眼看出这是把名刀！」", null, "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "15"}, "CHAPTER 7-1", null, null], [5868, "将臣", "「在下不过是一介郎党，实在是配不上如此贵重的东西」", null, "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "15"}, "CHAPTER 7-1", null, null], [5869, "女神", "「我都已经说了可以了，那自然就是可以」", "lem423_017.ogg", "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "08"}, "CHAPTER 7-1", null, null], [5870, "将臣", "「不行，在下不能没有任何理由就收下这么贵重的东西！」", null, "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "08"}, "CHAPTER 7-1", null, null], [5871, "", "说什么呢！明明是有理由的吧？", null, "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "08"}, "CHAPTER 7-1", null, null], [5872, "", "连我都看出来了，难道这个人还不明白女神大人的心意吗？", null, "山_川沿いa", "bgm36.opus", null, "CHAPTER 7-1", null, null], [5873, "蕾娜", "「（……我记得就在昨天我们也说过类似的话）」", "len423_017.ogg", "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "11"}, "CHAPTER 7-1", null, null], [5874, "", "哎？说过类似的话吗？", null, "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "11"}, "CHAPTER 7-1", null, null], [5875, "女神", "「……既然如此，那就当做是借给你的」", "lem423_018.ogg", "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "14"}, "CHAPTER 7-1", null, null], [5876, "将臣", "「嗯？」", null, "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "14"}, "CHAPTER 7-1", null, null], [5877, "女神", "「你现在的武艺还差得远，若不拿一把好点的武器，恐怕会战死沙场」", "lem423_019.ogg", "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "21"}, "CHAPTER 7-1", null, null], [5878, "女神", "「但是……你必须和我保证，一定要回来还给我」", "lem423_020.ogg", "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "14"}, "CHAPTER 7-1", null, null], [5879, "女神", "「…………这样还不行吗？」", "lem423_021.ogg", "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "06"}, "CHAPTER 7-1", null, null], [5880, "将臣", "「……」", null, "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "06"}, "CHAPTER 7-1", null, null], [5881, "", "男人看着拔出来的刀身，沉默不语。", null, "山_川沿いa", "bgm36.opus", null, "CHAPTER 7-1", null, null], [5882, "将臣", "「可以斗胆问问小姐的芳名吗？」", null, "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "12"}, "CHAPTER 7-1", null, null], [5883, "女神", "「……」", "lem423_022.ogg", "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "33"}, "CHAPTER 7-1", null, null], [5884, "丛云", "「丛云」", "lem423_023.ogg", "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "32"}, "CHAPTER 7-1", null, null], [5885, "", "在那个时代，身份高贵的女性一般不会把真名告诉丈夫之外的人。", null, "山_川沿いa", "bgm36.opus", null, "CHAPTER 7-1", null, null], [5886, "", "所以，问女性的名字这件事本身就非常失礼。", null, "山_川沿いa", "bgm36.opus", null, "CHAPTER 7-1", null, null], [5887, "", "然而男人问了，女人答了。", null, "山_川沿いa", "bgm36.opus", null, "CHAPTER 7-1", null, null], [5888, "", "对当事人来说，这段对话有着更深层的含义。这样的知识不知从哪灌入了我的脑袋。", null, "山_川沿いa", "bgm36.opus", null, "CHAPTER 7-1", null, null], [5889, "将臣", "「丛云……丛云」", null, "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "23"}, "CHAPTER 7-1", null, null], [5890, "将臣", "「其实不知为何，在下看着这把刀，总感觉它就像是从您身上生出来的一样」", null, "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "23"}, "CHAPTER 7-1", null, null], [5891, "丛云", "「…………嗯」", "lem423_024.ogg", "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "14"}, "CHAPTER 7-1", null, null], [5892, "将臣", "「丛云集聚，乃生丛雨，在下想给此刀命名为“丛雨”，您看如何？」", null, "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "14"}, "CHAPTER 7-1", null, null], [5893, "", "丛雨……居然是丛雨！？", null, "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "14"}, "CHAPTER 7-1", null, null], [5894, "蕾娜", "「（难道说，那把刀就是小雨的丛雨丸吗？）」", "len423_018.ogg", "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "04"}, "CHAPTER 7-1", null, null], [5895, "将臣", "「（不，我记得丛雨丸是打刀！这把丛雨是太刀，也就是说长度不一样）」", null, "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "04"}, "CHAPTER 7-1", null, null], [5896, "", "也可能是因为太刀太长了，后人为了方便使用，把它重新打造成了打刀。", null, "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "04"}, "CHAPTER 7-1", null, null], [5897, "", "我记得有很多这类事例。", null, "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "04"}, "CHAPTER 7-1", null, null], [5898, "", "之前就连小雨都说她不知道丛雨丸是从哪里来的，原来是这样来的吗！", null, "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "04"}, "CHAPTER 7-1", null, null], [5899, "丛云", "「随……随你喜欢就好」", "lem423_025.ogg", "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "30"}, "CHAPTER 7-1", null, null], [5900, "丛云", "「只是，你必须记得把丛雨还给我！如果你不还的话」", "lem423_026.ogg", "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "33"}, "CHAPTER 7-1", null, null], [5901, "丛云", "「我是不会原谅你的」", "lem423_027.ogg", "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "15"}, "CHAPTER 7-1", null, null], [5902, "", "女神大人连他的脸都不敢看，就那样跑掉了。", null, "山_山の中１a", "bgm36.opus", null, "CHAPTER 7-1", null, null], [5903, "", "于是我也可以从男人的身体里溜出来，跟着她一起走了。", null, "山_山の中１a", "bgm36.opus", null, "CHAPTER 7-1", null, null], [5904, "", "这次的梦里恐怕那个武士已经不会再登场了吧。", null, "山_山の中１a", "bgm36.opus", null, "CHAPTER 7-1", null, null], [5905, "白狛", "「姐姐大人，您居然做了这样的蠢事」", "srk423_001.ogg", "山_山の中１a", "bgm36.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 7-1", null, null], [5906, "丛云", "「小……小狛！难道你看见了？」", "lem423_028.ogg", "山_山の中１a", "bgm36.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 7-1", null, null], [5907, "丛云", "「居然偷看，真是坏」", "lem423_029.ogg", "山_山の中１a", "bgm36.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 7-1", null, null], [5908, "白狛", "「只不过是偶然看到」", "srk423_002.ogg", "山_山の中１a", "bgm36.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 7-1", null, null], [5909, "白狛", "「但是，您身为高贵的媛神，居然把真名告诉凡人，简直难以置信」", "srk423_003.ogg", "山_山の中１a", "bgm36.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 7-1", null, null], [5910, "丛云", "「你烦不烦」", "lem423_030.ogg", "山_山の中１a", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "15"}, "CHAPTER 7-1", null, null], [5911, "", "女神大人捡起一根小树枝砸了过去。", null, "山_山の中１a", "bgm36.opus", null, "CHAPTER 7-1", null, null], [5912, "", "虽然这对白狛来说不痛不痒，但它还是露出了不高兴的表情。", null, "山_山の中１a", "bgm36.opus", null, "CHAPTER 7-1", null, null], [5913, "白狛", "「姐姐大人……那个凡人一定无法想象」", "srk423_004.ogg", "山_山の中１a", "bgm36.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 7-1", null, null], [5914, "白狛", "「凡人怎么能想象得到，那把刀居然是您削开自己的身体做出来的」", "srk423_005.ogg", "山_山の中１a", "bgm36.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 7-1", null, null], [5915, "丛云", "「……我明白」", "lem423_031.ogg", "山_山の中１a", "bgm36.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 7-1", null, null], [5916, "白狛", "「那您为什么这么做？」", "srk423_006.ogg", "山_山の中１a", "bgm36.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 7-1", null, null], [5917, "丛云", "「…………」", "lem423_032.ogg", "山_山の中１a", "bgm36.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 7-1", null, null], [5918, "白狛", "「真是的。姐姐大人，您再怎么偏袒人类，这也做得也未免太过了」", "srk423_007.ogg", "山_山の中１a", "bgm36.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 7-1", null, null], [5919, "丛云", "「不要再说了……连我自己都没想到自己居然会做到那个地步」", "lem423_033.ogg", "山_山の中１a", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "06"}, "CHAPTER 7-1", null, null], [5920, "丛云", "「连我自己都对自己的行为吓了一跳」", "lem423_034.ogg", "山_山の中１a", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "30"}, "CHAPTER 7-1", null, null], [5921, "白狛", "「……」", "srk423_008.ogg", "山_山の中１a", "bgm36.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 7-1", null, null], [5922, "武士団", "「扬我军威！扬我军威！」", "bsd423_001.ogg", "空_青空", "bgm36.opus", null, "CHAPTER 7-1", null, null], [5923, "", "在那之后，山贼被打得一败涂地，这场战斗取得了难得一见的大胜。", null, "空_青空", "bgm36.opus", null, "CHAPTER 7-1", null, null], [5924, "", "武士团意气洋洋地凯旋了。", null, "空_青空", "bgm36.opus", null, "CHAPTER 7-1", null, null], [5925, "丛云", "「那个人呢？那个人也回来了吗！？你不是去看了吗！」", "lem423_035.ogg", "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "30"}, "CHAPTER 7-1", null, null], [5926, "白狛", "「嗯，既然他带着姐姐大人的刀，那自然是回来了」", "srk423_009.ogg", "山_川沿いa", "bgm36.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 7-1", null, null], [5927, "白狛", "「听说，他漂亮地斩下了敌方大将的首级，立了大功……」", "srk423_010.ogg", "山_川沿いa", "bgm36.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 7-1", null, null], [5928, "丛云", "「先不说这个，他没有受伤吧？\\n他是不是平安无事，一点伤都没受！？」", "lem423_036.ogg", "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "15"}, "CHAPTER 7-1", null, null], [5929, "白狛", "「……我记得并没有受伤的气味」", "srk423_011.ogg", "山_川沿いa", "bgm36.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 7-1", null, null], [5930, "丛云", "「太好了……」", "lem423_037.ogg", "山_川沿いa", "bgm36.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 7-1", null, null], [5931, "", "女神大人按住胸口，从心底里松了一口气。", null, "山_川沿いa", "bgm36.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 7-1", null, null], [5932, "丛云", "「……太好了」", "lem423_038.ogg", "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "03"}, "CHAPTER 7-1", null, null], [5933, "白狛", "「（看来，我没猜错）」", "srk423_012.ogg", "山_川沿いa", "bgm36.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 7-1", null, null], [5934, "白狛", "「（姐姐大人……居然爱上了人类）」", "srk423_013.ogg", "山_川沿いa", "bgm36.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 7-1", null, null], [5935, "将臣", "「感觉好像出现了意料之外的剧情」", null, "街_小道a", "bgm34.opus", null, "CHAPTER 7-1", null, null], [5936, "蕾娜", "「是啊，没想到后面居然变成浪漫爱情剧了」", "len423_019.ogg", "街_小道a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 7-1", null, null], [5937, "将臣", "「就是啊。毕竟从时代背景来看，这大概是——」", null, "街_小道a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 7-1", null, null], [5938, "将臣", "「——一千年前的爱情故事了」", null, "街_小道a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 7-1", null, null], [5939, "蕾娜", "「真是浪漫啊」", "len423_020.ogg", "街_小道a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "12"}, "CHAPTER 7-1", null, null], [5940, "蕾娜", "「这件事得赶快跟大家汇报下！」", "len423_021.ogg", "街_小道a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 7-1", null, null], [5941, "", "为此，我们两人现在正赶往建实神社。", null, "街_小道a", "bgm34.opus", null, "CHAPTER 7-1", null, null], [5942, "", "不过，去之前我给朝武家打了个电话，安晴叔叔说这件事应该先告诉他和小雨。", null, "街_小道a", "bgm34.opus", null, "CHAPTER 7-1", null, null], [5943, "安晴", "『因为我不希望芳乃她们空欢喜一场』", "yas423_001.ogg", "旅館_レナの部屋a", "bgm34.opus", {"char": "安晴", "file": "安晴.stand", "dress": "私服", "face": "13"}, "CHAPTER 7-1", null, null], [5944, "", "考虑到她们上一次的反应，安晴叔叔的顾虑也是理所当然的。", null, "旅館_レナの部屋a", "bgm34.opus", {"char": "安晴", "file": "安晴.stand", "dress": "私服", "face": "13"}, "CHAPTER 7-1", null, null], [5945, "", "而且驹川大夫那里暂时也没有值得一提的报告。", null, "街_小道a", "bgm34.opus", {"char": "安晴", "file": "安晴.stand", "dress": "私服", "face": "13"}, "CHAPTER 7-1", null, null], [5946, "", "这些事情我也向蕾娜说了。", null, "街_小道a", "bgm34.opus", {"char": "安晴", "file": "安晴.stand", "dress": "私服", "face": "13"}, "CHAPTER 7-1", null, null], [5947, "蕾娜", "「喔，这件事要先瞒着芳乃她们吗？」", "len423_022.ogg", "街_小道a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "30"}, "CHAPTER 7-1", null, null], [5948, "将臣", "「虽然我们获得了不少新的信息，但依然没有找到解除诅咒的办法」", null, "街_小道a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "30"}, "CHAPTER 7-1", null, null], [5949, "", "这种不够全面的信息反而会让她们担惊受怕。", null, "街_小道a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "30"}, "CHAPTER 7-1", null, null], [5950, "将臣", "「而且，从上次开始你就在梦里扮演着女神大人的角色了吧？」", null, "街_小道a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "30"}, "CHAPTER 7-1", null, null], [5951, "蕾娜", "「而你扮演的是武士的角色」", "len423_023.ogg", "街_小道a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 7-1", null, null], [5952, "将臣", "「嗯，在那之前，一直是一种在高处眺望整个世界的感觉」", null, "街_小道a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 7-1", null, null], [5953, "将臣", "「现在却给了我们角色来扮演，让我有些想不通」", null, "街_小道a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 7-1", null, null], [5954, "蕾娜", "「确实有点。那你觉得这是为什么呢？」", "len423_024.ogg", "街_小道a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "34"}, "CHAPTER 7-1", null, null], [5955, "将臣", "「嗯，比如说是因为我们和我们体内的碎片进一步融合了？」", null, "街_小道a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "34"}, "CHAPTER 7-1", null, null], [5956, "", "说不定这种现象是某种不太好的征兆。", null, "街_小道a", "bgm34.opus", null, "CHAPTER 7-1", null, null], [5957, "", "我尤其担心和女神大人融合在一起的蕾娜。", null, "街_小道a", "bgm34.opus", null, "CHAPTER 7-1", null, null], [5958, "", "把这件事告诉朝武她们的话，反而可能会让她们更加挂心。", null, "街_小道a", "bgm34.opus", null, "CHAPTER 7-1", null, null], [5959, "蕾娜", "「肯定没问题的」", "len423_025.ogg", "街_小道a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 7-1", null, null], [5960, "将臣", "「你还是这么乐观」", null, "街_小道a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 7-1", null, null], [5961, "蕾娜", "「将臣，我们之所以能得知我爷爷的爷爷的事情」", "len423_026.ogg", "街_小道a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "03"}, "CHAPTER 7-1", null, null], [5962, "蕾娜", "「是因为在碎片的记忆中，那部分与我们的关联最大，没错吧？」", "len423_027.ogg", "街_小道a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 7-1", null, null], [5963, "将臣", "「哎？嗯，我记得有谁提到过这个说法」", null, "街_小道a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 7-1", null, null], [5964, "蕾娜", "「也就是说，现在之所以能看见浪漫爱情剧……说不定是因为我们正在演出一场浪漫爱情剧」", "len423_028.ogg", "街_小道a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 7-1", null, null], [5965, "将臣", "「啊，嗯」", null, "街_小道a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 7-1", null, null], [5966, "蕾娜", "「所以肯定不会是多么不好的事情！」", "len423_029.ogg", "街_小道a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "24"}, "CHAPTER 7-1", null, null], [5967, "蕾娜", "「因为一个人和另一个人相爱，是非常美妙的事情」", "len423_030.ogg", "街_小道a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 7-1", null, null], [5968, "", "好像说得通，又好像说不通。", null, "街_小道a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 7-1", null, null], [5969, "", "但是听蕾娜这么一说，我也开始有那种感觉了，真是奇妙。", null, "街_小道a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 7-1", null, null], [5970, "将臣", "「也对！老是担心这担心那的，还怎么继续前进」", null, "街_小道a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 7-1", null, null], [5971, "蕾娜", "「就是这么一回事」", "len423_031.ogg", "街_小道a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "11"}, "CHAPTER 7-1", null, null], [5972, "蕾娜", "「话说啊，将臣」", "len423_032.ogg", "街_小道a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 7-1", null, null], [5973, "", "蕾娜又握住了我的手。", null, "街_小道a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 7-1", null, null], [5974, "蕾娜", "「先不说这些了……咱们的关系又上升了一个台阶，难道你就没有什么要对女朋友说的吗？」", "len423_033.ogg", "街_小道a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 7-1", null, null], [5975, "将臣", "「哎？我想想……」", null, "街_小道a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 7-1", null, null], [5976, "蕾娜", "「今天早上，我们还是紧紧抱着对方醒过来的呢」", "len423_034.ogg", "街_小道a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "07"}, "CHAPTER 7-1", null, null], [5977, "蕾娜", "「将臣你也真是的，净说些梦里的事情，却对可爱的恋人一句话都不说……这是不是有点不应该呀？」", "len423_035.ogg", "街_小道a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 7-1", null, null], [5978, "将臣", "「啊！对，你说的没错」", null, "街_小道a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 7-1", null, null], [5979, "将臣", "「……我想想」", null, "街_小道a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 7-1", null, null], [5980, "将臣", "「以、以后也请多多指教了」", null, "街_小道a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 7-1", null, null], [5981, "", "我慌慌张张地想出来了一句毫无味道的话。", null, "街_小道a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 7-1", null, null], [5982, "", "至少要说声我爱你才对吧？", null, "街_小道a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 7-1", null, null], [5983, "", "但出乎我意料的是，蕾娜满意地笑了。", null, "街_小道a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 7-1", null, null], [5984, "蕾娜", "「好的！今后也请多多指教啦，将臣！」", "len423_036.ogg", "街_小道a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 7-1", null, null], [5985, "", "我们一到神社，就按计划向小雨和安晴叔叔汇报了梦中的情况。", null, "神社_神社内a", "bgm39.opus", null, "CHAPTER 7-1", null, null], [5986, "丛雨", "「原来如此，虽然本座早就觉得丛雨丸不是凡人造出来的东西」", "mur423_001.ogg", "神社_神社内a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "03"}, "CHAPTER 7-1", null, null], [5987, "丛雨", "「但没想到，它居然是神灵身体的一部分」", "mur423_002.ogg", "神社_神社内a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "31"}, "CHAPTER 7-1", null, null], [5988, "丛雨", "「怪不得它能祓除妖怪，甚至就算折断也能复原」", "mur423_003.ogg", "神社_神社内a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "19"}, "CHAPTER 7-1", null, null], [5989, "将臣", "「我都习以为常了，但仔细一想丛雨丸的存在本身就是一件超乎想象的东西」", null, "神社_神社内a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "19"}, "CHAPTER 7-1", null, null], [5990, "", "不知不觉，丛雨丸的存在对我来说已经是理所当然的了，但它终究是个完全超越人类常识的东西。", null, "神社_神社内a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "19"}, "CHAPTER 7-1", null, null], [5991, "安晴", "「……我记得古书上好像记载了。当年举行仪式让丛雨大人成为管理者的时候」", "yas423_002.ogg", "神社_神社内a", "bgm39.opus", {"char": "安晴", "file": "安晴.stand", "dress": "神主", "face": "06"}, "CHAPTER 7-1", null, null], [5992, "安晴", "「人们为了让丛雨丸用起来更方便，把刀身缩短了」", "yas423_003.ogg", "神社_神社内a", "bgm39.opus", {"char": "安晴", "file": "安晴.stand", "dress": "神主", "face": "02"}, "CHAPTER 7-1", null, null], [5993, "丛雨", "「本座也只知道缩短之后的样子，所以都忘记这些了」", "mur423_004.ogg", "神社_神社内a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "30"}, "CHAPTER 7-1", null, null], [5994, "蕾娜", "「那么也就是说，丛雨丸果然是丛云女神用自己的身体造的！」", "len423_037.ogg", "神社_神社内a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 7-1", null, null], [5995, "安晴", "「虽然不知道丛雨大人是怎么说的，但恐怕确实是那样」", "yas423_004.ogg", "神社_神社内a", "bgm39.opus", {"char": "安晴", "file": "安晴.stand", "dress": "神主", "face": "03"}, "CHAPTER 7-1", null, null], [5996, "将臣", "「没事，小雨也说了同样的话」", null, "神社_神社内a", "bgm39.opus", {"char": "安晴", "file": "安晴.stand", "dress": "神主", "face": "03"}, "CHAPTER 7-1", null, null], [5997, "", "也就是说，这件事已经确定了。", null, "神社_神社内a", "bgm39.opus", null, "CHAPTER 7-1", null, null], [5998, "", "为了祓除化身为祟神的白狛，我们居然一直用的是以她姐姐身体的一部分铸造的刀。", null, "山_川沿いa", "bgm39.opus", null, "CHAPTER 7-1", null, null], [5999, "", "这么重要的事情居然之前都没人知道。", null, "山_川沿いa", "bgm39.opus", null, "CHAPTER 7-1", null, null], [6000, "", "以前驹川大夫好像说过，她得知这些新的信息时非常兴奋。", null, "神社_神社内a", "bgm39.opus", null, "CHAPTER 7-1", null, null], [6001, "", "现在，我能理解那种心情了。", null, "神社_神社内a", "bgm39.opus", null, "CHAPTER 7-1", null, null], [6002, "", "很多事情已经渐渐明了起来，却依然没有找到决定性的信息。", null, "神社_神社内a", "bgm39.opus", null, "CHAPTER 7-1", null, null], [6003, "", "连我自己都产生了一种急不可待的感觉。", null, "神社_神社内a", "bgm39.opus", null, "CHAPTER 7-1", null, null], [6004, "丛雨", "「话说回来，你说自己可能正在进一步跟碎片融合，这个本座有点在意」", "mur423_005.ogg", "神社_神社内a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "17"}, "CHAPTER 7-1", null, null], [6005, "将臣", "「那只是我的感觉，蕾娜似乎有不同的意见」", null, "神社_神社内a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "17"}, "CHAPTER 7-1", null, null], [6006, "丛雨", "「不，我们也应该考虑到最坏的可能性」", "mur423_006.ogg", "神社_神社内a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "34"}, "CHAPTER 7-1", null, null], [6007, "", "但是我能感觉到，小雨也在忍耐她兴奋的心情，努力想要冷静下来。", null, "神社_神社内a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "34"}, "CHAPTER 7-1", null, null], [6008, "蕾娜", "「小雨说的蛮有道理的，那么你觉得应该怎么办比较好？」", "len423_038.ogg", "神社_神社内a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "24"}, "CHAPTER 7-1", null, null], [6009, "丛雨", "「嗯，自从击败了那个合体祟神之后，就再也没有出现新的祟神了吧？」", "mur423_007.ogg", "神社_神社内a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "19"}, "CHAPTER 7-1", null, null], [6010, "将臣", "「这么一说，感觉确实已经很久没见过祟神了」", null, "神社_神社内a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "19"}, "CHAPTER 7-1", null, null], [6011, "丛雨", "「虽然还不能肯定，但从现状来看，蕾娜和主人身体里的碎片就已经是宿体的全部了」", "mur423_008.ogg", "神社_神社内a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "22"}, "CHAPTER 7-1", null, null], [6012, "丛雨", "「本座觉得这种可能性非常高」", "mur423_009.ogg", "神社_神社内a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "24"}, "CHAPTER 7-1", null, null], [6013, "将臣", "「也就是说，从我们身体里取出碎片的话，就能拼出完整的宿体了」", null, "神社_神社内a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "24"}, "CHAPTER 7-1", null, null], [6014, "丛雨", "「恐怕是的，而且有可能拼完之后就能结束这一切」", "mur423_010.ogg", "神社_神社内a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "36"}, "CHAPTER 7-1", null, null], [6015, "", "她的意思是也有可能不会再发生意外了？", null, "神社_神社内a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "36"}, "CHAPTER 7-1", null, null], [6016, "", "但是想想迄今为止发生过的那些事，总觉得不会那么顺利。", null, "神社_神社内a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "36"}, "CHAPTER 7-1", null, null], [6017, "丛雨", "「我们不得不做出选择了！这件事主人也向安晴转达一下吧」", "mur423_011.ogg", "神社_神社内a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "10"}, "CHAPTER 7-1", null, null], [6018, "丛雨", "「是进是退，现在就是分歧点」", "mur423_012.ogg", "神社_神社内a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "40"}, "CHAPTER 7-1", null, null], [6019, "丛雨", "「所以，在这之后希望大家不要再改变方针了」", "mur423_013.ogg", "神社_神社内a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "22"}, "CHAPTER 7-1", null, null], [6020, "将臣", "「我明白了」", null, "神社_神社内a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "22"}, "CHAPTER 7-1", null, null], [6021, "安晴", "「……？」", "yas423_005.ogg", "神社_神社内a", "bgm39.opus", {"char": "安晴", "file": "安晴.stand", "dress": "神主", "face": "06"}, "CHAPTER 7-1", null, null], [6022, "丛雨", "「现在马上硬把碎片取出来也好，就这样继续观察也好，这两种都有危险的」", "mur423_014.ogg", "神社_神社内a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "34"}, "CHAPTER 7-1", null, null], [6023, "丛雨", "「没有哪条路安全」", "mur423_015.ogg", "神社_神社内a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "17"}, "CHAPTER 7-1", null, null], [6024, "丛雨", "「就我们在场的几个人先做出选择吧，可以吗？」", "mur423_016.ogg", "神社_神社内a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "10"}, "CHAPTER 7-1", null, null], [6025, "", "我把小雨的话转告给了安晴叔叔。", null, "神社_神社内a", "bgm39.opus", null, "CHAPTER 7-1", null, null], [6026, "", "但是不管怎么说，当事人也是我和蕾娜，安晴叔叔肯定会说任由我们选择的。", null, "神社_神社内a", "bgm39.opus", null, "CHAPTER 7-1", null, null], [6027, "", "我本来是这样认为的。", null, "神社_神社内a", "bgm39.opus", null, "CHAPTER 7-1", null, null], [6028, "安晴", "「这样啊……确实，从现在开始已经不能回头了」", "yas423_006.ogg", "神社_神社内a", "bgm39.opus", {"char": "安晴", "file": "安晴.stand", "dress": "神主", "face": "02"}, "CHAPTER 7-1", null, null], [6029, "蕾娜", "「……叔叔？」", "len423_039.ogg", "神社_神社内a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "14"}, "CHAPTER 7-1", null, null], [6030, "", "安晴叔叔一次又一次扶住下颚，似乎非常犹豫。", null, "神社_神社内a", "bgm39.opus", {"char": "安晴", "file": "安晴.stand", "dress": "神主", "face": "04"}, "CHAPTER 7-1", null, null], [6031, "", "他的指尖还在不停地颤抖。", null, "神社_神社内a", "bgm39.opus", {"char": "安晴", "file": "安晴.stand", "dress": "神主", "face": "04"}, "CHAPTER 7-1", null, null], [6032, "丛雨", "「他应该是有什么话要说吧」", "mur423_017.ogg", "神社_神社内a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "16"}, "CHAPTER 7-1", null, null], [6033, "将臣", "「……哎？」", null, "神社_神社内a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "16"}, "CHAPTER 7-1", null, null], [6034, "", "我们心里想得太简单了。", null, "神社_神社内a", "bgm39.opus", null, "CHAPTER 7-1", null, null], [6035, "", "我们总以为大人不会在意这些细节，会相信我们。", null, "神社_神社内a", "bgm39.opus", null, "CHAPTER 7-1", null, null], [6036, "", "我们总以为，他们比小孩子要更加从容。", null, "神社_神社内a", "bgm39.opus", null, "CHAPTER 7-1", null, null], [6037, "", "然而，安晴叔叔却是眉头紧锁，似乎内心十分纠葛。他还从来没在我们面前露出过这样的表情。", null, "神社_神社内a", "bgm39.opus", null, "CHAPTER 7-1", null, null], [6038, "安晴", "「抱歉……我实在是没法冷静地做出判断」", "yas423_007.ogg", "神社_神社内a", "bgm08.opus", {"char": "安晴", "file": "安晴.stand", "dress": "神主", "face": "16"}, "CHAPTER 7-1", null, null], [6039, "安晴", "「我接下来要跟你们说的这些话……我根本不敢告诉芳乃」", "yas423_008.ogg", "神社_神社内a", "bgm08.opus", {"char": "安晴", "file": "安晴.stand", "dress": "神主", "face": "04"}, "CHAPTER 7-1", null, null], [6040, "", "我在脑海中回想起今早的事。安晴叔叔在电话中说，希望把事情先告诉他。", null, "神社_神社内a", "bgm08.opus", {"char": "安晴", "file": "安晴.stand", "dress": "神主", "face": "04"}, "CHAPTER 7-1", null, null], [6041, "安晴", "「我女儿是绝对不可能向朋友提出这种请求的」", "yas423_009.ogg", "神社_神社内a", "bgm08.opus", {"char": "安晴", "file": "安晴.stand", "dress": "神主", "face": "10"}, "CHAPTER 7-1", null, null], [6042, "蕾娜", "「请您说出来吧」", "len423_040.ogg", "神社_神社内a", "bgm08.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "08"}, "CHAPTER 7-1", null, null], [6043, "", "即便如此，安晴叔叔也依然在犹豫着。", null, "神社_神社内a", "bgm08.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "08"}, "CHAPTER 7-1", null, null], [6044, "", "蕾娜没有催促他，只是静静地等待着。", null, "神社_神社内a", "bgm08.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "08"}, "CHAPTER 7-1", null, null], [6045, "安晴", "「几百年来，对于这片土地的诅咒，从来没有人了解得像我们现在这样详细」", "yas423_010.ogg", "神社_神社内a", "bgm08.opus", {"char": "安晴", "file": "安晴.stand", "dress": "神主", "face": "17"}, "CHAPTER 7-1", null, null], [6046, "安晴", "「……所以…………」", "yas423_011.ogg", "神社_神社内a", "bgm08.opus", {"char": "安晴", "file": "安晴.stand", "dress": "神主", "face": "08"}, "CHAPTER 7-1", null, null], [6047, "安晴", "「如果能解除诅咒的话，就算有危险……我也想获得更多信息。这是我的真心话」", "yas423_012.ogg", "神社_神社内a", "bgm08.opus", {"char": "安晴", "file": "安晴.stand", "dress": "神主", "face": "16"}, "CHAPTER 7-1", null, null], [6048, "", "安晴叔叔已经失去了妻子，现在还需要忍耐可能失去女儿的恐惧。但他对待我们一直都保持着冷静而中立的态度。", null, "神社_神社内a", "bgm08.opus", {"char": "安晴", "file": "安晴.stand", "dress": "神主", "face": "08"}, "CHAPTER 7-1", null, null], [6049, "", "我记得安晴叔叔以前说过，他想看到女儿的笑容。", null, "神社_神社内a", "bgm08.opus", {"char": "安晴", "file": "安晴.stand", "dress": "神主", "face": "08"}, "CHAPTER 7-1", null, null], [6050, "", "他从来都不用语言，而是用态度来传达对女儿的爱意。", null, "神社_神社内a", "bgm08.opus", {"char": "安晴", "file": "安晴.stand", "dress": "神主", "face": "08"}, "CHAPTER 7-1", null, null], [6051, "安晴", "「我知道，需要冒险的人并不是我……」", "yas423_013.ogg", "神社_神社内a", "bgm08.opus", {"char": "安晴", "file": "安晴.stand", "dress": "神主", "face": "08"}, "CHAPTER 7-1", null, null], [6052, "安晴", "「我也知道，我不应该向从外地来的你们提出这样的请求，而且你们俩好不容易才刚刚成为恋人」", "yas423_014.ogg", "神社_神社内a", "bgm08.opus", {"char": "安晴", "file": "安晴.stand", "dress": "神主", "face": "16"}, "CHAPTER 7-1", null, null], [6053, "安晴", "「我自己也觉得说这种话很自私……我可能根本就不算是个合格的大人」", "yas423_015.ogg", "神社_神社内a", "bgm08.opus", {"char": "安晴", "file": "安晴.stand", "dress": "神主", "face": "16"}, "CHAPTER 7-1", null, null], [6054, "安晴", "「但是，我还是希望你们考虑下……」", "yas423_016.ogg", "神社_神社内a", "bgm08.opus", {"char": "安晴", "file": "安晴.stand", "dress": "神主", "face": "10"}, "CHAPTER 7-1", null, null], [6055, "蕾娜", "「没问题的！您什么都不用担心」", "len423_041.ogg", "神社_神社内a", "bgm08.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 7-1", null, null], [6056, "安晴", "「……哎？」", "yas423_017.ogg", "神社_神社内a", "bgm08.opus", {"char": "安晴", "file": "安晴.stand", "dress": "神主", "face": "10"}, "CHAPTER 7-1", null, null], [6057, "", "蕾娜那乐观的语气，和现在的气氛形成了鲜明的对比。", null, "神社_神社内a", "bgm08.opus", {"char": "安晴", "file": "安晴.stand", "dress": "神主", "face": "10"}, "CHAPTER 7-1", null, null], [6058, "", "但是，她应该仅仅只是把真心话说出来了而已。", null, "神社_神社内a", "bgm08.opus", {"char": "安晴", "file": "安晴.stand", "dress": "神主", "face": "10"}, "CHAPTER 7-1", null, null], [6059, "蕾娜", "「我从一开始就不打算退缩」", "len423_042.ogg", "神社_神社内a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 7-1", null, null], [6060, "蕾娜", "「只要是为了朋友，不管来多少危险我都不怕！」", "len423_043.ogg", "神社_神社内a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "11"}, "CHAPTER 7-1", null, null], [6061, "将臣", "「我也是一样的想法」", null, "神社_神社内a", "bgm40.opus", {"char": "安晴", "file": "安晴.stand", "dress": "神主", "face": "06"}, "CHAPTER 7-1", null, null], [6062, "将臣", "「在解除诅咒的同时，也保证我们自己的安全。我们之前就已经说过了，这才是最棒的结局」", null, "神社_神社内a", "bgm40.opus", {"char": "安晴", "file": "安晴.stand", "dress": "神主", "face": "06"}, "CHAPTER 7-1", null, null], [6063, "安晴", "「两位真的……」", "yas423_018.ogg", "神社_神社内a", "bgm40.opus", {"char": "安晴", "file": "安晴.stand", "dress": "神主", "face": "13"}, "CHAPTER 7-1", null, null], [6064, "", "如果是和其他女孩一起，我肯定会说需要一些时间考虑。", null, "神社_神社内a", "bgm40.opus", {"char": "安晴", "file": "安晴.stand", "dress": "神主", "face": "13"}, "CHAPTER 7-1", null, null], [6065, "", "但是蕾娜她并不只是单纯的乐观。", null, "神社_神社内a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 7-1", null, null], [6066, "", "她是那种很有自己主见的女孩，甚至对我这个男朋友也能说出“你没有权利无视我的心情”这种话。", null, "神社_神社内a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 7-1", null, null], [6067, "", "在有主见的同时，还能这么乐观，这也证明了她内心的强大。", null, "神社_神社内a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 7-1", null, null], [6068, "安晴", "「……或许我有点小看你们了」", "yas423_019.ogg", "神社_神社内a", "bgm40.opus", {"char": "安晴", "file": "安晴.stand", "dress": "神主", "face": "01"}, "CHAPTER 7-1", null, null], [6069, "安晴", "「不过……谢谢你们」", "yas423_020.ogg", "神社_神社内a", "bgm40.opus", {"char": "安晴", "file": "安晴.stand", "dress": "神主", "face": "03"}, "CHAPTER 7-1", null, null], [6070, "安晴", "「这份恩情我不会忘记的，谢谢你们……」", "yas423_021.ogg", "神社_神社内a", "bgm40.opus", {"char": "安晴", "file": "安晴.stand", "dress": "神主", "face": "13"}, "CHAPTER 7-1", null, null], [6071, "蕾娜", "「您说得太夸张了，我们只不过是想要帮助有困难的朋友而已」", "len423_044.ogg", "神社_神社内a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 7-1", null, null], [6072, "蕾娜", "「就连穗织的诅咒，也已经不是与我们完全无关的事情了……对吧，将臣？」", "len423_045.ogg", "神社_神社内a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 7-1", null, null], [6073, "将臣", "「毕竟都牵扯得这么深了」", null, "神社_神社内a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 7-1", null, null], [6074, "", "而且，我也是凭自己的意愿被牵扯进来的。", null, "神社_神社内a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 7-1", null, null], [6075, "丛雨", "「既然如此，本座也会遵守大家定下来的方针」", "mur423_018.ogg", "神社_神社内a", "bgm40.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "01"}, "CHAPTER 7-1", null, null], [6076, "将臣", "「小雨，你想说的应该也跟安晴叔叔一样吧？」", null, "神社_神社内a", "bgm40.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "01"}, "CHAPTER 7-1", null, null], [6077, "丛雨", "「毕竟本座是跟诅咒关系最深的当事人」", "mur423_019.ogg", "神社_神社内a", "bgm40.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "31"}, "CHAPTER 7-1", null, null], [6078, "丛雨", "「在某种意义上，关系比芳乃和安晴更深」", "mur423_020.ogg", "神社_神社内a", "bgm40.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "33"}, "CHAPTER 7-1", null, null], [6079, "蕾娜", "「小雨……」", "len423_046.ogg", "神社_神社内a", "bgm40.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "35"}, "CHAPTER 7-1", null, null], [6080, "丛雨", "「好了，你们是不是该去学校了？」", "mur423_021.ogg", "神社_神社内a", "bgm40.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "19"}, "CHAPTER 7-1", null, null], [6081, "将臣", "「都已经这个点了吗？」", null, "神社_神社内a", "bgm40.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "19"}, "CHAPTER 7-1", null, null], [6082, "", "不走快点的话恐怕会迟到。", null, "神社_神社内a", "bgm40.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "19"}, "CHAPTER 7-1", null, null], [6083, "将臣", "「那么我们就告辞了」", null, "神社_神社内a", "bgm40.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "19"}, "CHAPTER 7-1", null, null], [6084, "安晴", "「嗯……美津叶大夫那边就由我去说明吧，虽然不知道能不能联系上她」", "yas423_022.ogg", "神社_神社内a", "bgm40.opus", {"char": "安晴", "file": "安晴.stand", "dress": "神主", "face": "03"}, "CHAPTER 7-1", null, null], [6085, "安晴", "「她那边也差不多应该有点进展了」", "yas423_023.ogg", "神社_神社内a", "bgm40.opus", {"char": "安晴", "file": "安晴.stand", "dress": "神主", "face": "01"}, "CHAPTER 7-1", null, null], [6086, "将臣", "「嗯，拜托您了」", null, "神社_神社内a", "bgm40.opus", {"char": "安晴", "file": "安晴.stand", "dress": "神主", "face": "01"}, "CHAPTER 7-1", null, null], [6087, "", "说不定驹川大夫的发现有可能又会让我们进展一大步。", null, "神社_神社内a", "bgm40.opus", null, "CHAPTER 7-1", null, null], [6088, "", "不对，这么想未免太心急了。", null, "神社_神社内a", "bgm40.opus", null, "CHAPTER 7-1", null, null], [6089, "", "就在我来到神社院内的时候，突然遇见了朝武。", null, "神社_境内a", "bgm40.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "13"}, "CHAPTER 7-1", null, null], [6090, "芳乃", "「……」", "yos423_001.ogg", "神社_境内a", "bgm40.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "33"}, "CHAPTER 7-1", null, null], [6091, "将臣", "「朝武？」", null, "神社_境内a", "bgm40.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "33"}, "CHAPTER 7-1", null, null], [6092, "", "咦？她应该看到我了吧？", null, "神社_境内a", "bgm40.opus", null, "CHAPTER 7-1", null, null], [6093, "", "但她却没向我打招呼，而是穿过院内走了出去。", null, "神社_境内a", "bgm40.opus", null, "CHAPTER 7-1", null, null], [6094, "", "难道说是因为快迟到了吗？", null, "神社_境内a", "bgm40.opus", null, "CHAPTER 7-1", null, null], [6095, "", "还是说…………我们谈话被她听到了？", null, "神社_境内a", "bgm40.opus", null, "CHAPTER 7-1", null, null], [6096, "蕾娜", "「怎么了，将臣？」", "len423_047.ogg", "神社_境内a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "24"}, "CHAPTER 7-1", null, null], [6097, "将臣", "「不，没事」", null, "神社_境内a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "24"}, "CHAPTER 7-1", null, null], [6098, "茉子", "「哈哈，我觉得你没必要那么介意」", "mak423_001.ogg", "神社_境内a", "bgm40.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "01"}, "CHAPTER 7-1", null, null], [6099, "将臣", "「哇！？常陆，你在啊？」", null, "神社_境内a", "bgm40.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "01"}, "CHAPTER 7-1", null, null], [6100, "蕾娜", "「茉子，早上好！」", "len423_048.ogg", "神社_境内a", "bgm40.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "01"}, "CHAPTER 7-1", null, null], [6101, "茉子", "「嗯，蕾娜，有地，早上好」", "mak423_002.ogg", "神社_境内a", "bgm40.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "26"}, "CHAPTER 7-1", null, null], [6102, "", "常陆还是那样神出鬼没，几乎完全感觉不到她的气息。", null, "神社_境内a", "bgm40.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "26"}, "CHAPTER 7-1", null, null], [6103, "将臣", "「话说，刚才是怎么回事？」", null, "神社_境内a", "bgm40.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "01"}, "CHAPTER 7-1", null, null], [6104, "茉子", "「嘿嘿嘿，你还是不要介意比较好」", "mak423_003.ogg", "神社_境内a", "bgm40.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "01"}, "CHAPTER 7-1", null, null], [6105, "茉子", "「她不过是因为你们把她撇在一旁，在闹别扭而已」", "mak423_004.ogg", "神社_境内a", "bgm40.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "38"}, "CHAPTER 7-1", null, null], [6106, "茉子", "「那么，我先走一步了……两位请慢走」", "mak423_005.ogg", "神社_境内a", "bgm40.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "26"}, "CHAPTER 7-1", null, null], [6107, "", "看样子她是追赶朝武去了。", null, "神社_境内a", "bgm40.opus", null, "CHAPTER 7-1", null, null], [6108, "", "虽然不太明白，总之交给常陆应该就不用担心了。", null, "神社_境内a", "bgm40.opus", null, "CHAPTER 7-1", null, null], [6109, "蕾娜", "「嘻嘻……难道说，她是故意不打扰我们？」", "len423_049.ogg", "神社_境内a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 7-1", null, null], [6110, "将臣", "「哈哈，也许吧？总之我们也得快点走了」", null, "神社_境内a", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 7-1", null, null], [6111, "", "这时，我突然想起一件事。", null, "神社_境内a", "bgm40.opus", null, "CHAPTER 7-1", null, null], [6112, "", "在蕾娜刚吸收了碎片之后的那段时间，常陆也会经常去蕾娜身边观察她的情况。", null, "神社_境内a", "bgm40.opus", null, "CHAPTER 7-1", null, null], [6113, "", "现在这已经完全变成我的任务了。", null, "神社_境内a", "bgm40.opus", null, "CHAPTER 7-1", null, null], [6114, "", "如果继续进入梦境会遇到危险的话，由我来保护蕾娜就行了。", null, "神社_境内a", "bgm40.opus", null, "CHAPTER 7-1", null, null], [6115, "", "我发誓我说到做到。", null, "神社_境内a", "bgm40.opus", null, "CHAPTER 7-1", null, null], [6116, "蕾娜", "「来，将臣，张开嘴巴♪」", "len423_050.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "18"}, "CHAPTER 7-1", null, null], [6117, "将臣", "「啊、啊～」", null, "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "18"}, "CHAPTER 7-1", null, null], [6118, "", "今天午休时，我又和蕾娜坐在一起吃午饭。", null, "学院_教室休憩a", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6119, "", "我们这样似乎有点太没危机感了，但也许正因为我们感情越来越深，所以才能看到梦境的后续。", null, "学院_教室休憩a", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6120, "", "既然如此，哪怕在一起卿卿我我也是有意义的。", null, "学院_教室休憩a", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6121, "", "……大概是这样的。", null, "学院_教室休憩a", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6122, "", "反正，就当是这么回事吧。", null, "学院_教室休憩a", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6123, "蕾娜", "「要是整天那么愁眉苦脸，能办好的事也办不好了」", "len423_051.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 7-1", null, null], [6124, "蕾娜", "「怎么想也想不出自己能做什么的时候，放松身心才是最重要的！」", "len423_052.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "15"}, "CHAPTER 7-1", null, null], [6125, "将臣", "「嗯，我最近也越来越觉得你说的有道理了」", null, "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "15"}, "CHAPTER 7-1", null, null], [6126, "", "这种思想上的巨大变化，还有转换思维的速度，也算是一种成长吧？", null, "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "15"}, "CHAPTER 7-1", null, null], [6127, "蕾娜", "「是吗？既、既然如此，将臣……」", "len423_053.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27h"}, "CHAPTER 7-1", null, null], [6128, "将臣", "「怎么了，干嘛这么扭捏」", null, "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27h"}, "CHAPTER 7-1", null, null], [6129, "蕾娜", "「……可不可以让我喂你吃点甜品？」", "len423_054.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "17"}, "CHAPTER 7-1", null, null], [6130, "将臣", "「就这点小事呀。不过，便当里面好像没有甜品吧？」", null, "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "17"}, "CHAPTER 7-1", null, null], [6131, "蕾娜", "「嘿嘿，其实我偷偷准备了一点甜品」", "len423_055.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "12"}, "CHAPTER 7-1", null, null], [6132, "", "但是在甜品、糖果这方面，蕾娜是有前科的。", null, "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "12"}, "CHAPTER 7-1", null, null], [6133, "", "所以她一说甜品，我就有点慌。虽然就一点点。", null, "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "12"}, "CHAPTER 7-1", null, null], [6134, "蕾娜", "「那么，我要喂你了……你先闭上眼睛吧」", "len423_056.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "15"}, "CHAPTER 7-1", null, null], [6135, "将臣", "「哎？」", null, "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "15"}, "CHAPTER 7-1", null, null], [6136, "蕾娜", "「闭上眼睛嘛」", "len423_057.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "03"}, "CHAPTER 7-1", null, null], [6137, "", "这要是那种烂俗的言情剧，她大概会直接吻上来吧？", null, "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "03"}, "CHAPTER 7-1", null, null], [6138, "", "但她也可能是故意让我这么想，实际上正准备给我投入一些令人震撼的味道。", null, "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "03"}, "CHAPTER 7-1", null, null], [6139, "", "我现在的心情简直就跟扔骰子赌博一样。", null, "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "03"}, "CHAPTER 7-1", null, null], [6140, "蕾娜", "「将臣，你怎么了？你怎么还不闭上眼睛呢」", "len423_058.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "05"}, "CHAPTER 7-1", null, null], [6141, "将臣", "「啊、不是，我正准备闭上眼睛」", null, "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "05"}, "CHAPTER 7-1", null, null], [6142, "", "我相信蕾娜！", null, "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "05"}, "CHAPTER 7-1", null, null], [6143, "", "我就只有那么一点点慌而已，所以最终还是闭上了眼睛。", null, "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "05"}, "CHAPTER 7-1", null, null], [6144, "蕾娜", "「闭紧了吗？什么都看不见了吗？」", "len423_059.ogg", "画面_黒", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "05"}, "CHAPTER 7-1", null, null], [6145, "将臣", "「……嗯」", null, "画面_黒", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "05"}, "CHAPTER 7-1", null, null], [6146, "", "来吧，是死是活全看你了。", null, "画面_黒", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "05"}, "CHAPTER 7-1", null, null], [6147, "", "给我个痛快吧。", null, "画面_黒", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "05"}, "CHAPTER 7-1", null, null], [6148, "蕾娜", "「那我要上啦。将臣，张开嘴巴」", "len423_060.ogg", "画面_黒", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "05"}, "CHAPTER 7-1", null, null], [6149, "将臣", "「啊……啊」", null, "画面_黒", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "05"}, "CHAPTER 7-1", null, null], [6150, "", "感觉有什么东西正在靠近嘴唇。", null, "画面_黒", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "05"}, "CHAPTER 7-1", null, null], [6151, "", "这是！", null, "画面_黒", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "05"}, "CHAPTER 7-1", null, null], [6152, "蕾娜", "「……Ｍｕａ♪」", "len423_061.ogg", "画面_黒", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "05"}, "CHAPTER 7-1", null, null], [6153, "", "我猜对了——————！！！", null, "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "05"}, "CHAPTER 7-1", null, null], [6154, "蕾娜", "「这份甜品……味道如何呀？」", "len423_062.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "16h"}, "CHAPTER 7-1", null, null], [6155, "将臣", "「太棒了——！！」", null, "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "16h"}, "CHAPTER 7-1", null, null], [6156, "", "我不禁站了起来，做了个振臂握拳的姿势。", null, "学院_教室休憩a", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6157, "", "但紧接着，我就发现教室里所有人都在冲我翻白眼。", null, "学院_教室休憩a", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6158, "将臣", "「……哎？」", null, "学院_教室休憩a", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6159, "廉太郎", "「你以前……是这种性格吗？」", "ren423_001.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "13"}, "CHAPTER 7-1", null, null], [6160, "小春", "「自从哥哥开始跟蕾娜学姐交往之后，偶尔就会做出一些类似欧美人的夸张举动」", "koh423_001.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "25"}, "CHAPTER 7-1", null, null], [6161, "", "嗯，我知道。", null, "学院_教室休憩a", "bgm44.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "25"}, "CHAPTER 7-1", null, null], [6162, "", "但是刚才这个是不是有点太蠢了？嗯，确实……真的好蠢啊！", null, "学院_教室休憩a", "bgm44.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "25"}, "CHAPTER 7-1", null, null], [6163, "", "哇啊啊，太羞耻了！", null, "学院_教室休憩a", "bgm44.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "25"}, "CHAPTER 7-1", null, null], [6164, "蕾娜", "「没……没事的啦，将臣。做人还是对自己诚实点比较好」", "len423_063.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 7-1", null, null], [6165, "蕾娜", "「看到你这么高兴……我心里也是非常开心的」", "len423_064.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "17"}, "CHAPTER 7-1", null, null], [6166, "将臣", "「嗯、嗯」", null, "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "17"}, "CHAPTER 7-1", null, null], [6167, "", "见我蒙着脸趴在桌子上，蕾娜便开始安慰我。", null, "学院_教室休憩a", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6168, "", "不过，要是蕾娜觉得我刚才的举动没什么问题，那她的想法可能跟日本人还是有很大差别的。", null, "学院_教室休憩a", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6169, "蕾娜", "「行啦，快打起精神吧」", "len423_065.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 7-1", null, null], [6170, "蕾娜", "「……放心吧将臣，我会为你负责的」", "len423_066.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 7-1", null, null], [6171, "将臣", "「负责？」", null, "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 7-1", null, null], [6172, "蕾娜", "「你之前不是也对我说了嘛」", "len423_067.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 7-1", null, null], [6173, "蕾娜", "「无论发生什么……我都会负起责任，让你幸福的」", "len423_068.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 7-1", null, null], [6174, "", "呃，你之前不是说只让某一个人负责任这种想法很奇怪吗？", null, "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 7-1", null, null], [6175, "", "不过，也是。", null, "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 7-1", null, null], [6176, "将臣", "「只要我们俩一起为对方负责就行了吧？」", null, "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 7-1", null, null], [6177, "蕾娜", "「是的！我想说的就是这个意思」", "len423_069.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 7-1", null, null], [6178, "", "激动之余，我们的手已经握在了一起。", null, "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 7-1", null, null], [6179, "", "啊，仅仅只是十指交合，我的内心就已经感到如此温暖，小小的糗事已经完全无所谓了。", null, "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 7-1", null, null], [6180, "", "不过，过于夸张的举动以后还是注意下吧，嗯。", null, "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 7-1", null, null], [6181, "蕾娜", "「对了对了，你还记得吗？之前我说过，要教你怎么辨认星星」", "len423_070.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 7-1", null, null], [6182, "将臣", "「嗯，当然记得」", null, "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 7-1", null, null], [6183, "", "当时我还以为那只是个浪漫的比喻而已。", null, "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 7-1", null, null], [6184, "蕾娜", "「也让你等了这么久了，我马上就能兑现承诺了」", "len423_071.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 7-1", null, null], [6185, "蕾娜", "「这几天应该就可以送到了」", "len423_072.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "15"}, "CHAPTER 7-1", null, null], [6186, "将臣", "「哎，是吗！你这说得我有点期待了」", null, "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "15"}, "CHAPTER 7-1", null, null], [6187, "", "她应该是买了望远镜之类的东西吧。", null, "学院_教室休憩a", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6188, "", "也就是说，再过几天我就能和蕾娜一起观测星空了？", null, "学院_教室休憩a", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6189, "", "这种约会或许也挺不错的。", null, "学院_教室休憩a", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6190, "", "当时，我对自己的猜想深信不疑。", null, "学院_教室休憩a", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6191, "", "在那之后，我们上完了下午的课，迎来了放学。", null, "学院_学院前a", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6192, "将臣", "「啊」", null, "学院_教室休憩a", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6193, "", "我突然想起来今早和朝武目光对视却没打招呼的事。", null, "学院_教室休憩a", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6194, "", "我还什么都没跟她说呢。", null, "学院_教室休憩a", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6195, "", "虽然心里一直有点犹豫，但还是跟她说一下比较好吧。", null, "学院_教室休憩a", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6196, "蕾娜", "「将臣，你怎么了？不回去吗？」", "len423_073.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 7-1", null, null], [6197, "将臣", "「嗯，回去之前有点事……」", null, "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 7-1", null, null], [6198, "", "就在这时，手机突然响了。", null, "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 7-1", null, null], [6199, "", "而且这个号码是……！", null, "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 7-1", null, null], [6200, "将臣", "「驹川大夫打来的！」", null, "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 7-1", null, null], [6201, "蕾娜", "「真的吗！她查出什么结果了吗？」", "len423_074.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 7-1", null, null], [6202, "将臣", "「目前还不知道，不过你现在得回志那都庄吧？」", null, "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 7-1", null, null], [6203, "将臣", "「这个电话可能会打很久，你就先走吧，我听完了回去告诉你」", null, "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 7-1", null, null], [6204, "蕾娜", "「……喔、喔，也是」", "len423_075.ogg", "学院_教室休憩a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 7-1", null, null], [6205, "", "不知不觉，朝武和常陆已经不见了。", null, "学院_教室休憩a", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6206, "", "也罢，反正随时都有机会跟她们说话。", null, "学院_教室休憩a", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6207, "将臣", "「请问是驹川大夫吗？」", null, "学院_廊下a", "bgm39.opus", null, "CHAPTER 7-1", null, null], [6208, "美津叶", "『是有地吧？抱歉突然给你打电话，现在方便说话吗？』", "miz423_001.ogg", "学院_廊下a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "05"}, "CHAPTER 7-1", null, null], [6209, "将臣", "「嗯，我现在去没人的地方，请稍等一会儿」", null, "学院_廊下a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "05"}, "CHAPTER 7-1", null, null], [6210, "", "这种事还是不要让别人听见比较好。", null, "学院_廊下a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "05"}, "CHAPTER 7-1", null, null], [6211, "", "我随便转了转，来到了一个人少的角落。", null, "学院_廊下a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "05"}, "CHAPTER 7-1", null, null], [6212, "丛雨", "「主人，本座可以跟你一起吗」", "mur423_022.ogg", "学院_廊下a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "01"}, "CHAPTER 7-1", null, null], [6213, "将臣", "「小雨，你来了啊」", null, "学院_廊下a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "01"}, "CHAPTER 7-1", null, null], [6214, "丛雨", "「安晴刚才也接到了驹川的电话」", "mur423_023.ogg", "学院_廊下a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "01"}, "CHAPTER 7-1", null, null], [6215, "丛雨", "「所以本座就猜到她肯定也会给你打」", "mur423_024.ogg", "学院_廊下a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "29"}, "CHAPTER 7-1", null, null], [6216, "", "原来如此，毕竟驹川大夫和安晴叔叔都看不见小雨。", null, "学院_廊下a", "bgm39.opus", null, "CHAPTER 7-1", null, null], [6217, "", "如果小雨要听这种比较复杂的话题，还是跟我一起听比较好。", null, "学院_廊下a", "bgm39.opus", null, "CHAPTER 7-1", null, null], [6218, "美津叶", "『丛雨大人也跟你在一起吗？』", "miz423_002.ogg", "学院_廊下a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "01"}, "CHAPTER 7-1", null, null], [6219, "将臣", "「是的，她说想一起听听」", null, "学院_廊下a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "01"}, "CHAPTER 7-1", null, null], [6220, "", "小雨把耳朵凑了过来，准备一起听驹川大夫的汇报。", null, "学院_廊下a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "10"}, "CHAPTER 7-1", null, null], [6221, "将臣", "「那么，请问进展如何？那个大理石的采石场您已经去过了吧？」", null, "学院_廊下a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "01"}, "CHAPTER 7-1", null, null], [6222, "美津叶", "『准确来说，那一带的村落我每个都去调查了一遍』", "miz423_003.ogg", "学院_廊下a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "02"}, "CHAPTER 7-1", null, null], [6223, "美津叶", "『但是调查的结果始终没有想的那么顺利。我明天应该就能回去了，现在才来跟你说这些，挺抱歉的』", "miz423_004.ogg", "学院_廊下a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "26"}, "CHAPTER 7-1", null, null], [6224, "将臣", "「您就要回来了吗！」", null, "学院_廊下a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "26"}, "CHAPTER 7-1", null, null], [6225, "将臣", "「也就是说，成果还是有的是吗？」", null, "学院_廊下a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "26"}, "CHAPTER 7-1", null, null], [6226, "美津叶", "『嗯，你们刚做的那个梦，安晴先生也跟我说了』", "miz423_005.ogg", "学院_廊下a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "06"}, "CHAPTER 7-1", null, null], [6227, "美津叶", "『我的调查结果跟你们那个梦似乎也有关系』", "miz423_006.ogg", "学院_廊下a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "01"}, "CHAPTER 7-1", null, null], [6228, "", "我并没有多问什么，让驹川大夫继续说了下去。", null, "学院_廊下a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "01"}, "CHAPTER 7-1", null, null], [6229, "美津叶", "『说实话，为了打听类似的传说，我就已经花了非常大的工夫』", "miz423_007.ogg", "学院_廊下a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "26"}, "CHAPTER 7-1", null, null], [6230, "美津叶", "『等我终于打听到时，又发现不同的地方、不同的人，讲述的故事和人物也都有所不同』", "miz423_008.ogg", "学院_廊下a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "23"}, "CHAPTER 7-1", null, null], [6231, "美津叶", "『反正就是很模糊』", "miz423_009.ogg", "学院_廊下a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "01"}, "CHAPTER 7-1", null, null], [6232, "美津叶", "『不过，如果以你们做的梦为原点把这个传说拼凑起来，大概就是这样的』", "miz423_010.ogg", "学院_廊下a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "02"}, "CHAPTER 7-1", null, null], [6233, "将臣", "「……嗯」", null, "学院_廊下a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "02"}, "CHAPTER 7-1", null, null], [6234, "美津叶", "『从前，山神有两个孩子，一个叫山之女，一个叫山之子』", "miz423_011.ogg", "学院_廊下a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "05"}, "CHAPTER 7-1", null, null], [6235, "将臣", "「山之女和山之子？也就是姐姐和弟弟吗？」", null, "学院_廊下a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "05"}, "CHAPTER 7-1", null, null], [6236, "美津叶", "『这个众说纷纭，有的地方说是姐弟，有的地方说是兄妹』", "miz423_012.ogg", "学院_廊下a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "16"}, "CHAPTER 7-1", null, null], [6237, "美津叶", "『反正，那个山之女后来爱上了一位凡人男子』", "miz423_013.ogg", "学院_廊下a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "26"}, "CHAPTER 7-1", null, null], [6238, "美津叶", "『这一部分，不同的人讲的内容也有所不同』", "miz423_014.ogg", "学院_廊下a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "24"}, "CHAPTER 7-1", null, null], [6239, "美津叶", "『但有一点是共通的，那就是山之女最终没能和那位男子在一起，于是选择了跳崖自尽』", "miz423_015.ogg", "学院_廊下a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "14"}, "CHAPTER 7-1", null, null], [6240, "将臣", "「……哎？」", null, "学院_廊下a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "14"}, "CHAPTER 7-1", null, null], [6241, "美津叶", "『她死后，她的身体就变成了现在的大理石矿床。听着跟童话故事一样』", "miz423_016.ogg", "学院_廊下a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "21"}, "CHAPTER 7-1", null, null], [6242, "", "我之前就在想，神和人是很难终成眷属的……", null, "学院_廊下a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "21"}, "CHAPTER 7-1", null, null], [6243, "", "那位武士和女神最终还是迎来了悲恋的结局吗？", null, "学院_廊下a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "21"}, "CHAPTER 7-1", null, null], [6244, "", "而且竟然跳崖自杀，那山之子他……", null, "学院_廊下a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "21"}, "CHAPTER 7-1", null, null], [6245, "美津叶", "『矿山附近的人们所说的山神，应该就是指穗织的土地神了吧』", "miz423_017.ogg", "学院_廊下a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "01"}, "CHAPTER 7-1", null, null], [6246, "美津叶", "『那么对土地神来说，丛雨丸就是自己女儿的遗物了』", "miz423_018.ogg", "学院_廊下a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "05"}, "CHAPTER 7-1", null, null], [6247, "丛雨", "「唔，原来如此」", "mur423_025.ogg", "学院_廊下a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "24"}, "CHAPTER 7-1", null, null], [6248, "美津叶", "『而山之子毕竟失去了至亲，他会憎恶人类也就丝毫不奇怪了』", "miz423_019.ogg", "学院_廊下a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "14"}, "CHAPTER 7-1", null, null], [6249, "将臣", "「……确实」", null, "学院_廊下a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "14"}, "CHAPTER 7-1", null, null], [6250, "", "果然，并不是随便调查一下就能轻易找到解决办法的。", null, "学院_廊下a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "14"}, "CHAPTER 7-1", null, null], [6251, "", "我本来还以为那位女神或许可以阻止祟神，但没想到她已经不在了。", null, "学院_廊下a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "14"}, "CHAPTER 7-1", null, null], [6252, "", "虽然现在还不能断定，但实在是有点震惊。", null, "学院_廊下a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "14"}, "CHAPTER 7-1", null, null], [6253, "丛雨", "「无论如何，驹川说的这些，本座觉得可信度很高」", "mur423_026.ogg", "学院_廊下a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "01"}, "CHAPTER 7-1", null, null], [6254, "丛雨", "「按她的调查结果，祟神和那位女神，以及土地神都是分别存在的，这点尤其令人信服」", "mur423_027.ogg", "学院_廊下a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "03"}, "CHAPTER 7-1", null, null], [6255, "将臣", "「这样啊……小雨说，她支持驹川大夫的看法」", null, "学院_廊下a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "01"}, "CHAPTER 7-1", null, null], [6256, "美津叶", "『既然这样，那就说明我这么辛苦也算值了』", "miz423_020.ogg", "学院_廊下a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "17"}, "CHAPTER 7-1", null, null], [6257, "美津叶", "『无论如何，如果那位山之子是性情大变之后变成了祟神，那也就有让他冷静下来的方法了』", "miz423_021.ogg", "学院_廊下a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "05"}, "CHAPTER 7-1", null, null], [6258, "将臣", "「哎！真的吗？」", null, "学院_廊下a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "05"}, "CHAPTER 7-1", null, null], [6259, "美津叶", "『喂喂，这才是我们驹川家的老本行啊』", "miz423_022.ogg", "学院_廊下a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "04"}, "CHAPTER 7-1", null, null], [6260, "美津叶", "『不过，还是等了解了更多信息之后再行动吧』", "miz423_023.ogg", "学院_廊下a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "05"}, "CHAPTER 7-1", null, null], [6261, "", "也就是说，驹川大夫也希望我和蕾娜能继续探索梦境的后续。", null, "学院_廊下a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "05"}, "CHAPTER 7-1", null, null], [6262, "美津叶", "『要是我们弄错了方法，可能会让他更加愤怒』", "miz423_024.ogg", "学院_廊下a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "09"}, "CHAPTER 7-1", null, null], [6263, "美津叶", "『目前能采取的方法，也就只有诚心诚意地把他供奉起来，让他息怒』", "miz423_025.ogg", "学院_廊下a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "30"}, "CHAPTER 7-1", null, null], [6264, "美津叶", "『但如果用这个方法，可能会花上好几年时间』", "miz423_026.ogg", "学院_廊下a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "31"}, "CHAPTER 7-1", null, null], [6265, "将臣", "「明白了，我们会尽量尝试再次进入梦境的」", null, "学院_廊下a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "31"}, "CHAPTER 7-1", null, null], [6266, "美津叶", "『我知道自己可能没资格说这种话』", "miz423_027.ogg", "学院_廊下a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "30"}, "CHAPTER 7-1", null, null], [6267, "美津叶", "『……你们真的没问题吗？』", "miz423_028.ogg", "学院_廊下a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "05"}, "CHAPTER 7-1", null, null], [6268, "将臣", "「蕾娜那边肯定没问题的！就算有什么万一，我也一定会保护她」", null, "学院_廊下a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "05"}, "CHAPTER 7-1", null, null], [6269, "将臣", "「虽然，如果你问我要怎么保护她，我一时半会儿可能也答不上来」", null, "学院_廊下a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "05"}, "CHAPTER 7-1", null, null], [6270, "美津叶", "『你也真是的，我不仅担心她，我也担心你啊』", "miz423_029.ogg", "学院_廊下a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "21"}, "CHAPTER 7-1", null, null], [6271, "将臣", "「啊、嗯，抱歉」", null, "学院_廊下a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "21"}, "CHAPTER 7-1", null, null], [6272, "美津叶", "『总之，目前我们也只能依靠你们』", "miz423_030.ogg", "学院_廊下a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "01"}, "CHAPTER 7-1", null, null], [6273, "美津叶", "『所以，期待你们后续的表现了，有地』", "miz423_031.ogg", "学院_廊下a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "18"}, "CHAPTER 7-1", null, null], [6274, "", "挂断电话后，我抬起了头。", null, "学院_廊下a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "18"}, "CHAPTER 7-1", null, null], [6275, "", "只见小雨正在半空中飘来飘去，看上去有些心神不宁。", null, "学院_廊下a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "18"}, "CHAPTER 7-1", null, null], [6276, "将臣", "「你在干什么呢，小雨」", null, "学院_廊下a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "18"}, "CHAPTER 7-1", null, null], [6277, "丛雨", "「没什么，毕竟各种事情都有了很大的进展，所以有点坐不住」", "mur423_028.ogg", "学院_廊下a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "22"}, "CHAPTER 7-1", null, null], [6278, "丛雨", "「一想到本座和祟神那长达４００年的恩怨……嗯？」", "mur423_029.ogg", "学院_廊下a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "38"}, "CHAPTER 7-1", null, null], [6279, "", "我也顺着小雨的视线望了过去。", null, "学院_廊下a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "38"}, "CHAPTER 7-1", null, null], [6280, "将臣", "「啊！朝武！？」", null, "学院_廊下a", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "01"}, "CHAPTER 7-1", null, null], [6281, "芳乃", "「没事，我没有听你们打电话」", "yos423_002.ogg", "学院_廊下a", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "16"}, "CHAPTER 7-1", null, null], [6282, "", "我还什么都没说，她就立马否定了。", null, "学院_廊下a", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "16"}, "CHAPTER 7-1", null, null], [6283, "将臣", "「呃，不是……我还以为你回去了呢，只是吓了一跳而已」", null, "学院_廊下a", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "16"}, "CHAPTER 7-1", null, null], [6284, "芳乃", "「是吗，我也只是想起来有东西忘拿了，所以回来了而已」", "yos423_003.ogg", "学院_廊下a", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "22"}, "CHAPTER 7-1", null, null], [6285, "将臣", "「喔，原来是这样啊」", null, "学院_廊下a", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "22"}, "CHAPTER 7-1", null, null], [6286, "芳乃", "「嗯，不过……我本以为你是想故意瞒着我」", "yos423_004.ogg", "学院_廊下a", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "48"}, "CHAPTER 7-1", null, null], [6287, "", "她好像心情不太好？", null, "学院_廊下a", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "48"}, "CHAPTER 7-1", null, null], [6288, "将臣", "「抱歉了，朝武。我也不是故意不告诉你，只是凑巧有了一些进展而已」", null, "学院_廊下a", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "48"}, "CHAPTER 7-1", null, null], [6289, "将臣", "「难道说，今天早上我们在神社说的话，你都听见了吗？」", null, "学院_廊下a", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "48"}, "CHAPTER 7-1", null, null], [6290, "将臣", "「我记得我好像没说什么不该说的吧……」", null, "学院_廊下a", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "48"}, "CHAPTER 7-1", null, null], [6291, "", "至少，我应该没有说什么惹朝武生气的话。", null, "学院_廊下a", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "48"}, "CHAPTER 7-1", null, null], [6292, "芳乃", "「你不要误会了！我只是…………」", "yos423_005.ogg", "学院_廊下a", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "24"}, "CHAPTER 7-1", null, null], [6293, "芳乃", "「……～」", "yos423_006.ogg", "学院_廊下a", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "31"}, "CHAPTER 7-1", null, null], [6294, "芳乃", "「…………～～～～」", "yos423_007.ogg", "学院_廊下a", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "07"}, "CHAPTER 7-1", null, null], [6295, "", "朝武的表情变来变去的，最后皱着个眉头跑开了。", null, "学院_廊下a", "bgm39.opus", null, "CHAPTER 7-1", null, null], [6296, "将臣", "「……那些事没告诉朝武，是不是不太好啊？」", null, "学院_廊下a", "bgm39.opus", null, "CHAPTER 7-1", null, null], [6297, "丛雨", "「毕竟芳乃的心情肯定是最复杂的」", "mur423_030.ogg", "学院_廊下a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "31"}, "CHAPTER 7-1", null, null], [6298, "", "既然如此，无论我们作何选择，可能都不是正确的", null, "学院_廊下a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "31"}, "CHAPTER 7-1", null, null], [6299, "", "不过，她刚才的态度……", null, "学院_廊下a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "31"}, "CHAPTER 7-1", null, null], [6300, "", "我不由得想起了之前和朝武关系没那么好的那段时间。想着想着，感觉心里挺不是滋味的。", null, "学院_廊下a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "31"}, "CHAPTER 7-1", null, null], [6301, "将臣", "「啊，她刚才不是说有东西忘拿了吗，不去教室拿没关系吗？」", null, "学院_廊下a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "31"}, "CHAPTER 7-1", null, null], [6302, "丛雨", "「谁知道呢，不管怎么说，你要是杵在这里，她恐怕也不方便回来吧？」", "mur423_031.ogg", "学院_廊下a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "20"}, "CHAPTER 7-1", null, null], [6303, "", "好吧，确实。", null, "学院_廊下a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "20"}, "CHAPTER 7-1", null, null], [6304, "", "我回到了教室，准备拿包走人。", null, "学院_教室a", "bgm39.opus", null, "CHAPTER 7-1", null, null], [6305, "蕾娜", "「啊，将臣！这么快就打完了吗」", "len423_076.ogg", "学院_教室a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 7-1", null, null], [6306, "将臣", "「蕾娜？你还没回去吗？」", null, "学院_教室a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 7-1", null, null], [6307, "蕾娜", "「嗯，反正晚点回去也来得及，所以我就想多等你一会儿」", "len423_077.ogg", "学院_教室a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 7-1", null, null], [6308, "将臣", "「来不来得及也不好说吧，万一晚了呢」", null, "学院_教室a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 7-1", null, null], [6309, "将臣", "「也有可能你等了半天我也不来，最后只能一个人回去」", null, "学院_教室a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 7-1", null, null], [6310, "蕾娜", "「那种事到时候再说嘛」", "len423_078.ogg", "学院_教室a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "21"}, "CHAPTER 7-1", null, null], [6311, "蕾娜", "「到时候我再老老实实回去就行了」", "len423_079.ogg", "学院_教室a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 7-1", null, null], [6312, "将臣", "「蕾娜……」", null, "学院_教室a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 7-1", null, null], [6313, "蕾娜", "「而且，今天这不是很值嘛，多亏我等了你一会儿，才能这样跟你一起回去」", "len423_080.ogg", "学院_教室a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 7-1", null, null], [6314, "蕾娜", "「你说是吧，将臣」", "len423_081.ogg", "学院_教室a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 7-1", null, null], [6315, "", "蕾娜就像往常一样把手牵了过来。", null, "学院_教室a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 7-1", null, null], [6316, "", "我也紧紧握住了她的手。", null, "学院_教室a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 7-1", null, null], [6317, "蕾娜", "「嘿嘿，虽然回去的路可能得走快点了」", "len423_082.ogg", "学院_教室a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 7-1", null, null], [6318, "蕾娜", "「但我觉得，这样回去的话，我工作起来会更有热情」", "len423_083.ogg", "学院_教室a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "03"}, "CHAPTER 7-1", null, null], [6319, "将臣", "「嗯，接下来我也要去接受外公的洗礼了」", null, "学院_教室a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "03"}, "CHAPTER 7-1", null, null], [6320, "", "确实，这样一来我训练的时候也会更有力气。", null, "学院_教室a", "bgm37.opus", null, "CHAPTER 7-1", null, null], [6321, "", "训练完后，我小跑着来到了志那都庄。", null, "旅館_旅館前c", "bgm35.opus", null, "CHAPTER 7-1", null, null], [6322, "将臣", "「糟了糟了，竟然练到这么晚」", null, "旅館_旅館前c", "bgm35.opus", null, "CHAPTER 7-1", null, null], [6323, "", "这都是因为外公见我今天干劲十足，所以突然给我增加了好几组训练。", null, "旅館_旅館前c", "bgm35.opus", null, "CHAPTER 7-1", null, null], [6324, "", "真是服了，干劲太足也是个问题。", null, "旅館_旅館前c", "bgm35.opus", null, "CHAPTER 7-1", null, null], [6325, "", "不过，我的确能够体会到，我们正在一步一步地逼近真相。", null, "旅館_廊下d", "bgm35.opus", null, "CHAPTER 7-1", null, null], [6326, "", "谁也不知道接下来究竟会发生什么，所以我的训练决不能偷懒。", null, "旅館_廊下d", "bgm35.opus", null, "CHAPTER 7-1", null, null], [6327, "", "就像那位武士说的一样，如果要确保自己随时能够上战场，就必须每天坚持锻炼。", null, "旅館_廊下d", "bgm35.opus", null, "CHAPTER 7-1", null, null], [6328, "将臣", "「在这样的情况下，蕾娜的心态却依然能够像往常一样，她真的很厉害」", null, "旅館_廊下d", "bgm35.opus", null, "CHAPTER 7-1", null, null], [6329, "", "她始终都那么泰然自若，也从来不会轻易受到别人的影响。", null, "旅館_廊下d", "bgm35.opus", null, "CHAPTER 7-1", null, null], [6330, "", "不仅能清晰地理解现状，还能尽力确保我们的二人时间，这并不是一般人能够做到的。", null, "旅館_廊下d", "bgm35.opus", null, "CHAPTER 7-1", null, null], [6331, "", "我以后也要尽量不迟到才行。", null, "旅館_廊下d", "bgm35.opus", null, "CHAPTER 7-1", null, null], [6332, "将臣", "「赶快去蕾娜的房间……啊」", null, "旅館_廊下d", "bgm35.opus", null, "CHAPTER 7-1", null, null], [6333, "心子", "「将臣少爷，真巧啊」", "mot423_001.ogg", "旅館_廊下d", "bgm35.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "03"}, "CHAPTER 7-1", null, null], [6334, "将臣", "「晚上好，猪谷阿姨。您找我有什么事吗？」", null, "旅館_廊下d", "bgm35.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "03"}, "CHAPTER 7-1", null, null], [6335, "心子", "「是的，这里有个寄给列支敦瑙尔小姐的包裹」", "mot423_002.ogg", "旅館_廊下d", "bgm35.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "01"}, "CHAPTER 7-1", null, null], [6336, "", "难道又是她老家给她寄东西了吗？", null, "旅館_廊下d", "bgm35.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "01"}, "CHAPTER 7-1", null, null], [6337, "", "……说起来，外公到底是怎么跟旅馆的员工们解释我和蕾娜的关系的啊？", null, "旅館_廊下d", "bgm35.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "01"}, "CHAPTER 7-1", null, null], [6338, "", "猪谷阿姨把这个包裹交给我，说明她知道我正准备去蕾娜的房间。", null, "旅館_廊下d", "bgm35.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "01"}, "CHAPTER 7-1", null, null], [6339, "", "虽然挺好奇的，但我有点不敢问。", null, "旅館_廊下d", "bgm35.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "01"}, "CHAPTER 7-1", null, null], [6340, "心子", "「那就拜托你交给她了」", "mot423_003.ogg", "旅館_廊下d", "bgm35.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "02"}, "CHAPTER 7-1", null, null], [6341, "将臣", "「好的……嗯？」", null, "旅館_廊下d", "bgm35.opus", null, "CHAPTER 7-1", null, null], [6342, "", "蕾娜的包裹是一个纸箱。抱在手里，感觉不像是食品之类的东西。", null, "旅館_廊下d", "bgm35.opus", null, "CHAPTER 7-1", null, null], [6343, "", "而且，这箱子怎么看怎么眼熟……", null, "旅館_廊下d", "bgm35.opus", null, "CHAPTER 7-1", null, null], [6344, "将臣", "「……亚马逊？」", null, "旅館_廊下d", "bgm35.opus", null, "CHAPTER 7-1", null, null], [6345, "蕾娜", "「啊，将臣！你怎么这么晚才回来」", "len423_084.ogg", "旅館_レナの部屋d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "07"}, "CHAPTER 7-1", null, null], [6346, "将臣", "「抱歉，快过来吧」", null, "旅館_レナの部屋d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "07"}, "CHAPTER 7-1", null, null], [6347, "", "我把纸箱放在了一旁，先跟蕾娜来了个爱的拥抱。", null, "旅館_レナの部屋d", "bgm05.opus", null, "CHAPTER 7-1", "ev403a", null], [6348, "蕾娜", "「Ｍｕａ♪嘿嘿……等你等得我可寂寞了」", "len423_085.ogg", "旅館_レナの部屋d", "bgm05.opus", null, "CHAPTER 7-1", "ev403a", null], [6349, "将臣", "「没办法，训练拖了一会儿时间。我也很想你，刚练完就跑回来了」", null, "旅館_レナの部屋d", "bgm05.opus", null, "CHAPTER 7-1", "ev403a", null], [6350, "蕾娜", "「……真的吗？有那么想我吗？」", "len423_086.ogg", "旅館_レナの部屋d", "bgm05.opus", null, "CHAPTER 7-1", "ev403a", null], [6351, "将臣", "「当然了，我甚至想要超越光速，瞬间来到你身边」", null, "旅館_レナの部屋d", "bgm05.opus", null, "CHAPTER 7-1", "ev403a", null], [6352, "", "等等，我在说什么啊。", null, "旅館_レナの部屋d", "bgm05.opus", null, "CHAPTER 7-1", "ev403a", null], [6353, "蕾娜", "「嘿嘿，真拿你没办法」", "len423_087.ogg", "旅館_レナの部屋d", "bgm05.opus", null, "CHAPTER 7-1", "ev403a", null], [6354, "蕾娜", "「你愿意超越光速来见我，我超级开心。将臣，我爱你哦，Ｍｕａ♪」", "len423_088.ogg", "旅館_レナの部屋d", "bgm05.opus", null, "CHAPTER 7-1", "ev403a", null], [6355, "", "天天面对我这些令人头皮发麻的言行，蕾娜竟然招架得住。", null, "旅館_レナの部屋d", "bgm05.opus", null, "CHAPTER 7-1", "ev403a", null], [6356, "", "白天还说要尽量克制自己的……哎算了，就当没发生过。", null, "旅館_レナの部屋d", "bgm05.opus", null, "CHAPTER 7-1", "ev403a", null], [6357, "", "那种事并没有发生过！", null, "旅館_レナの部屋d", "bgm05.opus", null, "CHAPTER 7-1", "ev403a", null], [6358, "蕾娜", "「话说将臣，那个箱子是什么？」", "len423_089.ogg", "旅館_レナの部屋d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "26"}, "CHAPTER 7-1", null, null], [6359, "将臣", "「我也不知道，是猪谷阿姨拿来的，你应该是在网上买了什么东西吧？」", null, "旅館_レナの部屋d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "26"}, "CHAPTER 7-1", null, null], [6360, "蕾娜", "「哇！终于送到了啊」", "len423_090.ogg", "旅館_レナの部屋d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "22"}, "CHAPTER 7-1", null, null], [6361, "", "蕾娜立刻打开了纸箱。", null, "旅館_レナの部屋d", "bgm05.opus", null, "CHAPTER 7-1", null, null], [6362, "", "箱子里装的是一台笔记本电脑。当然，是搭载了摄像头和ＷｉＦｉ的型号。", null, "旅館_レナの部屋d", "bgm05.opus", null, "CHAPTER 7-1", null, null], [6363, "蕾娜", "「我一直都没有自己的个人电脑，所以我拜托掌柜的帮我订了一台」", "len423_091.ogg", "旅館_レナの部屋d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 7-1", null, null], [6364, "将臣", "「确实，现在这个时代没有个人电脑还是不太方便」", null, "旅館_レナの部屋d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 7-1", null, null], [6365, "将臣", "「你之前一直都没买吗？」", null, "旅館_レナの部屋d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 7-1", null, null], [6366, "蕾娜", "「哈哈，我一直在攒工资，最近才终于攒够」", "len423_092.ogg", "旅館_レナの部屋d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "12"}, "CHAPTER 7-1", null, null], [6367, "蕾娜", "「将臣，一会儿设置的时候你能帮帮我吗」", "len423_093.ogg", "旅館_レナの部屋d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 7-1", null, null], [6368, "将臣", "「当然了，不过我对这方面也不太懂」", null, "旅館_レナの部屋d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 7-1", null, null], [6369, "蕾娜", "「设置的时候，总会出现一堆很难的日语」", "len423_094.ogg", "旅館_レナの部屋d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "16"}, "CHAPTER 7-1", null, null], [6370, "将臣", "「你这么一说，好像确实」", null, "旅館_レナの部屋d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "16"}, "CHAPTER 7-1", null, null], [6371, "蕾娜", "「只要我仔细读，倒也能读懂，但是我一个人的话肯定会很花时间」", "len423_095.ogg", "旅館_レナの部屋d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27"}, "CHAPTER 7-1", null, null], [6372, "", "这种设置，其实就算读不懂，也基本上能搞定。", null, "旅館_レナの部屋d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27"}, "CHAPTER 7-1", null, null], [6373, "", "不过既然有我在，那当然是不用废话，直接帮忙了。", null, "旅館_レナの部屋d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27"}, "CHAPTER 7-1", null, null], [6374, "蕾娜", "「那就拜托你啦，将臣」", "len423_096.ogg", "旅館_レナの部屋d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27"}, "CHAPTER 7-1", null, null], [6375, "", "说实话，像这样紧紧地靠在一起盯着电脑屏幕，还是挺开心的。", null, "旅館_レナの部屋d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27"}, "CHAPTER 7-1", null, null], [6376, "将臣", "「嗯？等等，这里没有路由器吗？」", null, "旅館_レナの部屋d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27"}, "CHAPTER 7-1", null, null], [6377, "将臣", "「话说，这里开通宽带服务了吗？……说到底，这里允许拉网线吗」", null, "旅館_レナの部屋d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27"}, "CHAPTER 7-1", null, null], [6378, "蕾娜", "「你在说什么呢，将臣」", "len423_097.ogg", "旅館_レナの部屋d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "26"}, "CHAPTER 7-1", null, null], [6379, "蕾娜", "「志那都庄不是有免费的吗」", "len423_098.ogg", "旅館_レナの部屋d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "01"}, "CHAPTER 7-1", null, null], [6380, "将臣", "「免费的？你是说这里也有车站里面那种免费ＷｉＦｉ吗？」", null, "旅館_レナの部屋d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "01"}, "CHAPTER 7-1", null, null], [6381, "蕾娜", "「是的！手机用户也可以免费不限量上网」", "len423_099.ogg", "旅館_レナの部屋d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "24"}, "CHAPTER 7-1", null, null], [6382, "", "现在的温泉旅馆都这么厉害的吗！！", null, "旅館_レナの部屋d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "24"}, "CHAPTER 7-1", null, null], [6383, "", "幸好有免费无线网。虽然稍微费了点事，但最终还是轻松地连上了网络。", null, "旅館_レナの部屋d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "24"}, "CHAPTER 7-1", null, null], [6384, "将臣", "「好了，视频聊天用的软件也装好了……还有什么其他需要的吗？」", null, "旅館_レナの部屋d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "24"}, "CHAPTER 7-1", null, null], [6385, "蕾娜", "「谢谢你，将臣！现在应该……」", "len423_100.ogg", "旅館_レナの部屋d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "19"}, "CHAPTER 7-1", null, null], [6386, "蕾娜", "「哇，已经这个点了啊」", "len423_101.ogg", "旅館_レナの部屋d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27"}, "CHAPTER 7-1", null, null], [6387, "", "蕾娜慌慌张张地打开了刚刚安装的聊天软件。", null, "旅館_レナの部屋d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27"}, "CHAPTER 7-1", null, null], [6388, "将臣", "「你是跟别人约了电话吗？」", null, "旅館_レナの部屋d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27"}, "CHAPTER 7-1", null, null], [6389, "蕾娜", "「将臣，你忘记我今天午休时说的话了吗？」", "len423_102.ogg", "旅館_レナの部屋d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02"}, "CHAPTER 7-1", null, null], [6390, "蕾娜", "「接下来，我要教你怎么辨认星星！」", "len423_103.ogg", "旅館_レナの部屋d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "18"}, "CHAPTER 7-1", null, null], [6391, "将臣", "「……哎？」", null, "旅館_レナの部屋d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "18"}, "CHAPTER 7-1", null, null], [6392, "", "随后，蕾娜收到了一条视频聊天的邀请。", null, "旅館_レナの部屋d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "18"}, "CHAPTER 7-1", null, null], [6393, "蕾娜", "「哇，这么快就来了！这是我家里人打来的」", "len423_104.ogg", "旅館_レナの部屋d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "17"}, "CHAPTER 7-1", null, null], [6394, "蕾娜", "「我爸爸和妈妈，还有爷爷都在」", "len423_105.ogg", "旅館_レナの部屋d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02"}, "CHAPTER 7-1", null, null], [6395, "将臣", "「等、等等，这是什么情况？辨认星星的方法，要先问你家里人吗？」", null, "旅館_レナの部屋d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02"}, "CHAPTER 7-1", null, null], [6396, "蕾娜", "「别急别急，我打算过一会儿再把你介绍给他们，所以你先站在摄像头外面吧」", "len423_106.ogg", "旅館_レナの部屋d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 7-1", null, null], [6397, "", "好吧，要是一上来就把我介绍给她家人，感觉也挺不好意思的。", null, "旅館_レナの部屋d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 7-1", null, null], [6398, "蕾娜", "「Ｍｏｉ！」", "len423_107.ogg", "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "24"}, "CHAPTER 7-1", null, null], [6399, "", "我依然是一脸问号，而蕾娜已经开始了视频聊天。", null, "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "24"}, "CHAPTER 7-1", null, null], [6400, "", "屏幕上一共显示了三个视频窗口，看来她的家人现在也是在不同的地方居住。", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6401, "", "不过话说回来，欧美人到底是厉害。", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6402, "", "虽然我听不懂他们在说什么，但怎么说呢，他们每个人……", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6403, "", "＂Ｍｏｉ！＂＂Ｍｏｏｏｉ！！＂＂Ｍｏｏｏｏｏｏｏｏｉ！！！＂——基本都是这么兴奋。", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6404, "", "这仅仅只是一句问好而已吧？", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6405, "", "为什么一句问好就能兴奋成这样啊？我站在一旁听他们说话，听得我感觉自己完全跟不上他们的节奏。", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6406, "", "而且，那位看上去像她爷爷的老人身后，有一头体型庞大的鹿正一边咀嚼一边路过。", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6407, "", "另外还有一群村民正红着脸一边喝酒一边唱歌。", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6408, "", "但是没有任何人在意这些细节。", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6409, "", "现在，他们似乎正在用外语相互汇报最近的情况。刚才那一番混沌的景象真是吓了我一跳。", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6410, "", "突然，我发现他们那边的窗外还是亮着的。", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6411, "将臣", "「（毕竟有时差，那边现在应该是大白天吧？不对，这个季节，他们那里应该是极昼）」", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6412, "", "不管怎么说，他们肯定是为了女儿特意腾出了这么一段时间。", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6413, "", "想在这个时间段腾出时间，对他们来说肯定不那么容易。", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6414, "蕾娜", "「将臣！将臣！我要给家人介绍你了，你快过来吧」", "len423_108.ogg", "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "15"}, "CHAPTER 7-1", null, null], [6415, "将臣", "「啊，嗯，好的」", null, "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "15"}, "CHAPTER 7-1", null, null], [6416, "", "说实话，我完全不觉得自己能跟上他们的节奏，但跟她家人打个招呼还是应该的。", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6417, "", "毕竟是他们把我最爱的人带到了这个世界上，并且养育了她。", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6418, "将臣", "「大、大家好，也不知道各位听不听得懂日语……初次见面，请多……」", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6419, "", "就在我进入摄像头画面的那一瞬间——", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6420, "", "“武士！”“武士男孩！”“哇噢噢噢噢噢！！！”——如此尖叫突然响起，直接把我的说话声盖住了。", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6421, "将臣", "「啊？什么情况！？」", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6422, "蕾娜", "「很正常」", "len423_109.ogg", "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02"}, "CHAPTER 7-1", null, null], [6423, "将臣", "「不是吧！？蕾娜，你是怎么跟你家人描述我的啊？」", null, "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02"}, "CHAPTER 7-1", null, null], [6424, "蕾娜", "「……嗯，我已经在电话里告诉他们了」", "len423_110.ogg", "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "01"}, "CHAPTER 7-1", null, null], [6425, "将臣", "「所以你到底是怎么描述的？他们好像在说什么武士之类的啊？」", null, "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "01"}, "CHAPTER 7-1", null, null], [6426, "蕾娜", "「将臣！我爷爷说他想看你挥刀的样子」", "len423_111.ogg", "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "18"}, "CHAPTER 7-1", null, null], [6427, "将臣", "「不是吧，一上来就要挥刀啊……喔」", null, "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "18"}, "CHAPTER 7-1", null, null], [6428, "", "她爷爷大概是通过摄像头看见了靠在墙上的竹刀。", null, "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "18"}, "CHAPTER 7-1", null, null], [6429, "将臣", "「素振的话可以给他们看看，但是应该没什么意思吧？」", null, "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "18"}, "CHAPTER 7-1", null, null], [6430, "蕾娜", "「没事没事，我也想看！」", "len423_112.ogg", "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "12"}, "CHAPTER 7-1", null, null], [6431, "", "蕾娜都这么说了，我也不好拒绝。", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6432, "", "但如果他们发现这不是真刀，会不会很失望呢？", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6433, "", "我一边担心，一边拿出了竹刀。", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6434, "", "“竹刀！”“竹刀！！”“哇噢噢噢噢噢！！！”", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6435, "", "他们的反应太过激烈，音量大得连扬声器都破音了。", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6436, "", "……他们到底在兴奋什么？", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6437, "", "我记得以前和蕾娜一起看电影ＤＶＤ时，她一个人的反应抵得上我们四个人。", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6438, "", "但是现在明显比那个时候更夸张。", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6439, "", "当我实际挥刀演示时，他们就已经闹腾得像开派对一样了。", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6440, "", "她爷爷一边抱着刚才那头巨大的鹿——大概是驯鹿吧——的脖子，一边挥舞着手臂。", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6441, "", "她妈妈则是在摄像头对面不停地用手机拍照。", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6442, "", "至于她爸爸，已经随便拿了一根棍子，开始学着我做素振了。", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6443, "蕾娜", "「他问你，这样挥对不对」", "len423_113.ogg", "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 7-1", null, null], [6444, "将臣", "「啊，我看看，他现在有点像是在握棒球棍，正确的方法应该是两手间隔一定距离握住刀柄」", null, "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 7-1", null, null], [6445, "", "蕾娜一边听我说，一边给她爸爸翻译，大家听了之后连连点头。", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6446, "", "“大师！”“大师！！”\\n“哇噢噢噢噢噢！！！”", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6447, "", "这是要羞死我啊！！", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6448, "", "什么大师啊！肯定是那种电影看多了吧！", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6449, "", "不过一般来说，一听到女儿交男朋友了，做父母的不是应该首先提高警惕吗？", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6450, "", "但是蕾娜的父母却一上来就接受了我，这让我挺欣慰的。", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6451, "", "就在这时，蕾娜爸爸的语气突然严肃了起来。", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6452, "将臣", "「嗯？你爸爸怎么说的？」", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6453, "蕾娜", "「啊、啊，你不用在意的」", "len423_114.ogg", "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "28"}, "CHAPTER 7-1", null, null], [6454, "将臣", "「呃，听上去也不像是英语，我真的是一丁点都听不懂」", null, "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "28"}, "CHAPTER 7-1", null, null], [6455, "将臣", "「能不能也给我翻译一下啊……」", null, "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "28"}, "CHAPTER 7-1", null, null], [6456, "蕾娜", "「……唔唔，爸爸你真是的，说这些也不害臊」", "len423_115.ogg", "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "10"}, "CHAPTER 7-1", null, null], [6457, "将臣", "「哎？」", null, "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "10"}, "CHAPTER 7-1", null, null], [6458, "蕾娜", "「反、反正，你不用在意我们说了什么」", "len423_116.ogg", "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "16"}, "CHAPTER 7-1", null, null], [6459, "", "蕾娜竟然直接把她爸的语音关掉了。", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6460, "", "下一秒，其他人都开始爆笑了起来。", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6461, "", "看上去应该不是在说我坏话……也罢，她们家人之间应该就是这种气氛吧。", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6462, "蕾娜", "「那么，将臣，差不多该教你怎么辨认星星了」", "len423_117.ogg", "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "01"}, "CHAPTER 7-1", null, null], [6463, "将臣", "「对哦，差点都忘记正题了！」", null, "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "01"}, "CHAPTER 7-1", null, null], [6464, "将臣", "「但我又听不懂你们说话，你们要怎么教我呢？」", null, "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "01"}, "CHAPTER 7-1", null, null], [6465, "蕾娜", "「不需要语言的啦」", "len423_118.ogg", "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "03"}, "CHAPTER 7-1", null, null], [6466, "蕾娜", "「我只是希望你，能和我还有我的家人们……一同仰望这片星空而已」", "len423_119.ogg", "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "19"}, "CHAPTER 7-1", null, null], [6467, "", "那到底要怎么看呢？北极圈现在应该是极昼状态吧。", null, "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "19"}, "CHAPTER 7-1", null, null], [6468, "", "蕾娜似乎正在跟她爷爷拜托什么事。", null, "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 7-1", null, null], [6469, "", "随后，屏幕上弹出了一个共享视频画面的确认弹窗。", null, "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 7-1", null, null], [6470, "蕾娜", "「这应该是爷爷去年拍的视频」", "len423_120.ogg", "旅館_レナの部屋d", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 7-1", null, null], [6471, "", "片刻之后，视频载入完毕，开始播放。", null, "旅館_レナの部屋d", "bgm44.opus", null, "CHAPTER 7-1", null, null], [6472, "将臣", "「……啊！」", null, "旅館_レナの部屋d", "bgm03.opus", null, "CHAPTER 7-1", null, null], [6473, "", "我不禁叫出了声。", null, "旅館_レナの部屋d", "bgm03.opus", null, "CHAPTER 7-1", null, null], [6474, "", "是极光。", null, "旅館_レナの部屋d", "bgm03.opus", null, "CHAPTER 7-1", null, null], [6475, "", "屏幕上一片夜色，拍摄地点似乎是某个被白雪覆盖的牧场。", null, "旅館_レナの部屋d", "bgm03.opus", null, "CHAPTER 7-1", null, null], [6476, "", "牧场之上，那笼罩了整个天穹的巨大的光幕，一边呈现着千变万化的色彩，一边在夜空中随风飘舞。", null, "旅館_レナの部屋d", "bgm03.opus", null, "CHAPTER 7-1", null, null], [6477, "", "尽管笔记本电脑的屏幕很小，但那份壮美依然直击人心。", null, "旅館_レナの部屋d", "bgm03.opus", null, "CHAPTER 7-1", null, null], [6478, "", "自然之美永远都是那么宏伟。", null, "旅館_レナの部屋d", "bgm03.opus", null, "CHAPTER 7-1", null, null], [6479, "蕾娜", "「这里是我们住的村庄，视频是在我爷爷家的牧场里拍的」", "len423_121.ogg", "旅館_レナの部屋d", "bgm03.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27"}, "CHAPTER 7-1", null, null], [6480, "蕾娜", "「冬天的时候，只要天气好就很容易看到极光，但是这么大而且这么清晰的极光，就算在我们国家也算很罕见的」", "len423_122.ogg", "旅館_レナの部屋d", "bgm03.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02"}, "CHAPTER 7-1", null, null], [6481, "将臣", "「嗯……」", null, "旅館_レナの部屋d", "bgm03.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02"}, "CHAPTER 7-1", null, null], [6482, "", "我已经看呆了。", null, "旅館_レナの部屋d", "bgm03.opus", null, "CHAPTER 7-1", null, null], [6483, "", "大家刚才还那么闹腾，现在似乎也都看入了神。", null, "旅館_レナの部屋d", "bgm03.opus", null, "CHAPTER 7-1", null, null], [6484, "", "虽然我早就知道，和万里之外的人共享视频并不是什么难事。", null, "旅館_レナの部屋d", "bgm03.opus", null, "CHAPTER 7-1", null, null], [6485, "", "但是实际体验一番之后……我竟感动得说不出话了。", null, "旅館_レナの部屋d", "bgm03.opus", null, "CHAPTER 7-1", null, null], [6486, "", "我现在正在和地球另一端的人观赏着同一片景色！", null, "旅館_レナの部屋d", "bgm03.opus", null, "CHAPTER 7-1", null, null], [6487, "将臣", "「……好厉害」", null, "旅館_レナの部屋d", "bgm03.opus", null, "CHAPTER 7-1", null, null], [6488, "", "我已经不知道该说什么了。", null, "旅館_レナの部屋d", "bgm03.opus", null, "CHAPTER 7-1", null, null], [6489, "蕾娜", "「在我们国家有个说法：只要能看见极光，就可以获得好运」", "len423_123.ogg", "旅館_レナの部屋d", "bgm03.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "01"}, "CHAPTER 7-1", null, null], [6490, "蕾娜", "「还有传言说，极光会实现你的任何愿望」", "len423_124.ogg", "旅館_レナの部屋d", "bgm03.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "17"}, "CHAPTER 7-1", null, null], [6491, "蕾娜", "「所以，我们肯定也能遇上好事的！」", "len423_125.ogg", "旅館_レナの部屋d", "bgm03.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 7-1", null, null], [6492, "将臣", "「……蕾娜？」", null, "旅館_レナの部屋d", "bgm03.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 7-1", null, null], [6493, "", "看来，蕾娜心里十分清楚。", null, "旅館_レナの部屋d", "bgm03.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 7-1", null, null], [6494, "", "她明白，我们接下来可能就要以身犯险了。", null, "旅館_レナの部屋d", "bgm03.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 7-1", null, null], [6495, "", "她是以此为前提，说出了这些话。", null, "旅館_レナの部屋d", "bgm03.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 7-1", null, null], [6496, "蕾娜", "「将臣，辨认星星的方法，你学会了吗？」", "len423_126.ogg", "旅館_レナの部屋d", "bgm03.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "19"}, "CHAPTER 7-1", null, null], [6497, "将臣", "「嗯，我现在完全懂了……」", null, "旅館_レナの部屋d", "bgm03.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "19"}, "CHAPTER 7-1", null, null], [6498, "蕾娜", "「我觉得，真正重要的东西，或许只需要知道它存在就足够了」", "len423_127.ogg", "旅館_レナの部屋d", "bgm03.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "03"}, "CHAPTER 7-1", null, null], [6499, "蕾娜", "「无论何时，我们都可以观赏同样的事物，收获同样的感动」", "len423_128.ogg", "旅館_レナの部屋d", "bgm03.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02"}, "CHAPTER 7-1", null, null], [6500, "", "我们并不是孤身一人。", null, "旅館_レナの部屋d", "bgm03.opus", null, "CHAPTER 7-1", null, null], [6501, "", "我们生活在同一片天空之下，我们心醉于大自然之美，我们可以用文明的利器随时找到对方。", null, "旅館_レナの部屋d", "bgm03.opus", null, "CHAPTER 7-1", null, null], [6502, "", "冥冥之中，似乎有这么一股宏大的力量。", null, "旅館_レナの部屋d", "bgm03.opus", null, "CHAPTER 7-1", null, null], [6503, "", "它对我们予以肯定，包容了我们的一切，就连那璀璨星空，相较之下也不过是沧海一粟……", null, "旅館_レナの部屋d", "bgm03.opus", null, "CHAPTER 7-1", null, null], [6504, "", "一份难以言说的安全感，渐渐填满了我的内心。", null, "旅館_レナの部屋d", "bgm03.opus", null, "CHAPTER 7-1", null, null], [6505, "", "不知不觉，我和蕾娜已经相互依偎在一起，静静地看入了神。", null, "旅館_レナの部屋d", "bgm03.opus", null, "CHAPTER 7-1", null, null], [6506, "", "过了一会儿，视频聊天终于结束，我们再次回到了二人世界。", null, "旅館_レナの部屋d", "bgm54.opus", null, "CHAPTER 7-1", null, null], [6507, "将臣", "「谢谢你，蕾娜」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 7-1", null, null], [6508, "蕾娜", "「我可什么都没做哦」", "len423_129.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "01"}, "CHAPTER 7-1", null, null], [6509, "将臣", "「你不是把我介绍给你家人了嘛，还教会了我怎么辨认星星」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "01"}, "CHAPTER 7-1", null, null], [6510, "将臣", "「感觉现在心情好多了」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "01"}, "CHAPTER 7-1", null, null], [6511, "蕾娜", "「哈哈，只要你觉得开心，我就满足了」", "len423_130.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27"}, "CHAPTER 7-1", null, null], [6512, "蕾娜", "「而且我也很久没和家里人打这种不用担心话费的电话了，能聊这么久我超开心」", "len423_131.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02"}, "CHAPTER 7-1", null, null], [6513, "将臣", "「唉，我是不是也应该给家里打个电话了啊，已经好久没打了」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02"}, "CHAPTER 7-1", null, null], [6514, "蕾娜", "「你还是没打电话吗？偶尔也应该跟父母联系一下嘛」", "len423_132.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "21"}, "CHAPTER 7-1", null, null], [6515, "将臣", "「哈哈，我家没有那种定期联系的习惯」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "21"}, "CHAPTER 7-1", null, null], [6516, "", "这么一想，我们可能确实没有外国人那么重视家庭。", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "21"}, "CHAPTER 7-1", null, null], [6517, "将臣", "「话说回来，网络真是厉害啊」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "21"}, "CHAPTER 7-1", null, null], [6518, "蕾娜", "「将臣，你怎么突然改变话题了啊」", "len423_133.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "10"}, "CHAPTER 7-1", null, null], [6519, "将臣", "「不是……你想啊，在１０年前，共享视频之类的操作根本就办不到吧」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "10"}, "CHAPTER 7-1", null, null], [6520, "将臣", "「而且新闻节目天天都在强调网络的坏处，所以这么一对比，真的是感慨万千」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "10"}, "CHAPTER 7-1", null, null], [6521, "将臣", "「怎么说呢，我就是深深体会到，人类的智慧并不是只会产生不好的影响」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "10"}, "CHAPTER 7-1", null, null], [6522, "蕾娜", "「是啊，人类……也并不是只有缺点……」", "len423_134.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "19"}, "CHAPTER 7-1", null, null], [6523, "蕾娜", "「唉……要是能通过网络跟神仙们打电话就好了」", "len423_135.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27"}, "CHAPTER 7-1", null, null], [6524, "", "啊？", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27"}, "CHAPTER 7-1", null, null], [6525, "将臣", "「你是说，你想跟祟神或者土地神视频聊天？」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27"}, "CHAPTER 7-1", null, null], [6526, "蕾娜", "「是的，要是能实现的话，说不定就能让他们教教我们怎么处理眼前这些麻烦事了吧？」", "len423_136.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "01"}, "CHAPTER 7-1", null, null], [6527, "", "你还打算在神仙面前当伸手党！？", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "01"}, "CHAPTER 7-1", null, null], [6528, "", "这我还真没想过！", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "01"}, "CHAPTER 7-1", null, null], [6529, "", "然而，蕾娜的眼神是认真的。", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "01"}, "CHAPTER 7-1", null, null], [6530, "蕾娜", "「而且，说不定还能把我们的想法告诉他们呢！」", "len423_137.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02"}, "CHAPTER 7-1", null, null], [6531, "将臣", "「啊……嗯」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02"}, "CHAPTER 7-1", null, null], [6532, "蕾娜", "「虽然还不清楚应该怎么说……但我觉得，祟神和人类之间肯定也只是有什么误会而已吧？」", "len423_138.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 7-1", null, null], [6533, "蕾娜", "「我的直觉是这么告诉我的」", "len423_139.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27"}, "CHAPTER 7-1", null, null], [6534, "", "我已经知道，女神大人的恋情最终将是一场悲剧。", null, "山_川沿いa", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "女神", "face": "07"}, "CHAPTER 7-1", null, null], [6535, "", "想和祟神沟通，真的有那么容易吗？", null, "山_川沿いa", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "女神", "face": "07"}, "CHAPTER 7-1", null, null], [6536, "", "说实话，我从来没想过要和祟神坐下来聊聊。", null, "旅館_レナの部屋d", "bgm54.opus", null, "CHAPTER 7-1", null, null], [6537, "", "蕾娜的想法对我来说确实很新鲜，虽然也远超我的常识。", null, "旅館_レナの部屋d", "bgm54.opus", null, "CHAPTER 7-1", null, null], [6538, "蕾娜", "「……将臣，你不这么认为吗？」", "len423_140.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "01"}, "CHAPTER 7-1", null, null], [6539, "将臣", "「唔，我也说不清」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "01"}, "CHAPTER 7-1", null, null], [6540, "将臣", "「反正也没有违背以信息收集为先的方针，我觉得没什么问题」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "01"}, "CHAPTER 7-1", null, null], [6541, "", "但我们和祟神，真的能够相互妥协吗？", null, "山_山道c", "bgm54.opus", null, "CHAPTER 7-1", null, null], [6542, "", "之前我一直以为最终只能一战……", null, "山_山道c", "bgm54.opus", null, "CHAPTER 7-1", null, null], [6543, "蕾娜", "「也对，之前都商量过了……首先我们得了解更多的信息才行……」", "len423_141.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 7-1", null, null], [6544, "将臣", "「嗯，是的……？」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 7-1", null, null], [6545, "蕾娜", "「……既然如此，那今晚……也一起睡吧？」", "len423_142.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "19h"}, "CHAPTER 7-1", null, null], [6546, "", "好吧，其实我心里也是这么期待的。", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "19h"}, "CHAPTER 7-1", null, null], [6547, "", "事到如今也没什么好害羞的了。", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "19h"}, "CHAPTER 7-1", null, null], [6548, "将臣", "「当然了，只要你愿意」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "19h"}, "CHAPTER 7-1", null, null], [6549, "蕾娜", "「嘿嘿，我就知道」", "len423_143.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "25"}, "CHAPTER 7-1", null, null], [6550, "蕾娜", "「其实……我预约了这个时间段的露天浴池，而且是包场的」", "len423_144.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "03"}, "CHAPTER 7-1", null, null], [6551, "将臣", "「啊……喔，好像是叫家族浴池来着？」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "03"}, "CHAPTER 7-1", null, null], [6552, "", "马上就要跟蕾娜一起泡澡了。", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "03"}, "CHAPTER 7-1", null, null], [6553, "", "真是越想越期待。", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "03"}, "CHAPTER 7-1", null, null], [6554, "将臣", "「不过，等等，这种浴池，员工不是不能预约的吗？」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "03"}, "CHAPTER 7-1", null, null], [6555, "蕾娜", "「是的……但是，大当家说……我们是特殊情况，所以就允许我预约了」", "len423_145.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27"}, "CHAPTER 7-1", null, null], [6556, "将臣", "「……哎？」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27"}, "CHAPTER 7-1", null, null], [6557, "", "我们都已经被公认到这个份上了吗！", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27"}, "CHAPTER 7-1", null, null], [6558, "", "外公到底是怎么跟大家说明我们的关系的啊？", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27"}, "CHAPTER 7-1", null, null], [6559, "", "虽然也没什么大不了的，毕竟他的说明恐怕跟实际情况相差无几。", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "27"}, "CHAPTER 7-1", null, null], [6560, "蕾娜", "「将臣？将臣……你不愿意一起泡澡吗？」", "len423_146.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "30"}, "CHAPTER 7-1", null, null], [6561, "将臣", "「怎么会呢！没有不愿意」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "30"}, "CHAPTER 7-1", null, null], [6562, "将臣", "「说实话，我还是非常开心的」", null, "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "30"}, "CHAPTER 7-1", null, null], [6563, "蕾娜", "「哈哈……那就好」", "len423_147.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "02"}, "CHAPTER 7-1", null, null], [6564, "蕾娜", "「我也很开心……今晚，我想让你好好尝尝甜头」", "len423_148.ogg", "旅館_レナの部屋d", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "仲居服", "face": "19h"}, "CHAPTER 7-1", null, null], [6565, "", "尝尝甜头？进了浴池之后，我到底会被怎样啊？", null, "旅館_レナの部屋d", "bgm54.opus", null, "CHAPTER 7-1", null, null], [6566, "", "当然了，比起那一丝丝不安，我的内心早就被期待填满了。", null, "旅館_レナの部屋d", "bgm54.opus", null, "CHAPTER 7-1", null, null], [6567, "蕾娜", "「来吧，将臣……先一起洗干净吧」", "len423_149.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6568, "", "不知为何，我正枕在蕾娜的大腿上。明明都还没泡多久。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6569, "", "而且，她就像是在哄小孩一样，一边跟我说话，一边摩擦着我的阴茎。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6570, "蕾娜", "「嗯……嗯……哎呀，将臣，我只是在帮你擦洗而已……怎么越来越大了呀？哈哈」", "len423_150.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6571, "将臣", "「那、那什么，我们不是已经洗完了吗，为什么现在搞得我像个小孩一样……唔！？」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6572, "", "我的嘴巴突然被乳房堵住了。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6573, "", "那尺寸大到几乎快要盖住我的脸，压得我几乎快要窒息。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6574, "蕾娜", "「嘿嘿，将臣……你不是一直都很想体验下这种感觉的吗？」", "len423_151.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6575, "蕾娜", "「喜欢吃奶的……都是小孩……嗯……嗯啊」", "len423_152.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6576, "将臣", "「虽、虽然你说的没错，但是这样是不是太变态了啊」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6577, "蕾娜", "「嗯？这种喂奶玩法，在日本难道不是最常见的吗？」", "len423_153.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6578, "", "错误的变态知识正在侵犯我的全身！", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6579, "", "但是最让人头疼的是，我对此并没有那么反感。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6580, "蕾娜", "「这种玩法在欧洲可有名了……难道说，将臣……你不喜欢这种吗？」", "len423_154.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6581, "将臣", "「不，并不是不喜欢，只是害怕自己一玩起来就上瘾了」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6582, "蕾娜", "「哈哈，是嘛……不用担心，你就尽管上瘾吧。嗯……嗯、啊」", "len423_155.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6583, "", "蕾娜的手握成了一个环，套在我的阴茎上慢慢地上下抚弄。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6584, "", "跟我自己操作的时候比起来，蕾娜的动作显得有些不太熟练。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6585, "", "但是能让女孩子为自己做这些，也确实能给我一种平时体验不到的新鲜感，使得我格外兴奋。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6586, "蕾娜", "「嗯……嗯……我听说日本的男性，嗯啊……不会接受割礼……啊、啊……」", "len423_156.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6587, "蕾娜", "「……所以小弟弟的皮，才能像这样……一伸，一缩……吗」", "len423_157.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6588, "将臣", "「哎？这个，应该本来就是这样的吧」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6589, "蕾娜", "「啊……是、这样吗？嗯……嗯……能体验到各种各样的触感，还挺好玩的」", "len423_158.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6590, "将臣", "「好玩吗？」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6591, "蕾娜", "「是的……本体明明那么粗壮而坚硬……可是外皮却是如此柔韧」", "len423_159.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6592, "蕾娜", "「顶端则是光溜溜的，还这么富有弹性，就像软糖一样……真想一直捏在手里把玩」", "len423_160.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6593, "", "蕾娜轻轻握住了充血而膨胀的龟头。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6594, "", "那一瞬间，我感到整个脊骨都为之一颤。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6595, "蕾娜", "「嘿嘿，顶端很敏感吧？嗯、嗯……是不是再激烈点才会更舒服？」", "len423_161.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6596, "将臣", "「蕾、蕾娜，你不要老是抚弄龟头」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6597, "蕾娜", "「原来这个地方叫做龟头呀？啊、嗯……将臣，龟头应该就是你的弱点了吧，嗯、嗯」", "len423_162.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6598, "", "蕾娜用五根手指一边拨弄着阴茎颈部，一遍抚摸着龟头。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6599, "", "我自娱自乐的时候，一般是握住根干部分来达到高潮。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6600, "", "所以像这样被人抚弄龟头部位还是第一次，面对这种不熟悉的刺激感，我觉得自己就像蕾娜手中的玩物一样。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6601, "", "明明仅仅只是被手抚弄而已，我却如此舒服。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6602, "蕾娜", "「啊……啊、嗯！来吧，将臣……你也快来尝尝……巨乳的味道吧……嗯嗯」", "len423_163.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6603, "将臣", "「蕾、蕾娜……唔！？」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6604, "", "她再次用乳房堵住了我的嘴。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6605, "", "我们明明是在做大人的事情，我却感觉自己现在这样很像个小孩子。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6606, "", "感觉自己突然返老还童，正在让母亲哄着自己一样。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6607, "蕾娜", "「啊！哈哈，将臣……你、你真的像个婴儿一样……吸得真是用力啊、啊啊！」", "len423_164.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6608, "", "怎么可能有这么好色的婴儿呢。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6609, "", "要知道，我已经……我已经……", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6610, "蕾娜", "「哦？将臣，你的小弟弟在我手里……好像又变大了呀，嗯、嗯！」", "len423_165.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6611, "蕾娜", "「这到底是、嗯……嗯……怎么回事呢？啊啊……啊」", "len423_166.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6612, "将臣", "「这、这是因为……我快射了」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6613, "将臣", "「蕾娜、你、你再用力一点吧」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6614, "蕾娜", "「嘿嘿，你这射奶的速度……嗯、嗯……怎么比妈妈我还要快呀、啊、啊」", "len423_167.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6615, "", "虽然听着像是开玩笑，但蕾娜的呼吸也变得非常急促了。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6616, "", "她在抚弄我的时候，自己也兴奋起来了吗？\u000e", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6617, "蕾娜", "「啊、嗯……可以的，将臣！嗯、嗯……今晚，我也会……让你欲仙欲死的」", "len423_168.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6618, "", "蕾娜的手速越来越快。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6619, "", "用手摩擦，对我来说本是一种早就习惯了的触感。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6620, "", "但是这柔然的触感和男人的手明显不同。仅仅只是摩擦几下，就带给了我无上的新鲜感。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6621, "", "我……我已经，不行了……", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6622, "蕾娜", "「嗯、嗯……啊！将臣……将臣、你的小弟弟……不用再憋着了……嗯、嗯！」", "len423_169.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6623, "将臣", "「嗯、我、我马上……就要射了，蕾娜！」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6624, "蕾娜", "「啊、啊……嗯、好、好的……尽情、射出来吧，将臣」", "len423_170.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6625, "蕾娜", "「我希望……你能把精液、嗯、嗯……全部都射到我的手上……唔啊！？」", "len423_171.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6626, "蕾娜", "「啊……！已经射出来了吗，将臣」", "len423_172.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6627, "", "最终，我将自己的精液全部喷射到了蕾娜手中。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6628, "蕾娜", "「哈哈，射的时候……我也继续……嗯、嗯……给你摩擦吧」", "len423_173.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6629, "蕾娜", "「啊、啊……你真的、射了好多呢……啊！啊啊……」", "len423_174.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6630, "", "射出的白浊液，不断地冲向新的高度，然后又啪嗒啪嗒地落在地面上，激起阵阵水声。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6631, "", "蕾娜正如她刚才说的一样，依然在摩擦着我的阴茎，试图榨干我的最后一滴精液。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6632, "蕾娜", "「啊……啊、嗯、今天……你也射了好多」", "len423_175.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6633, "蕾娜", "「……真是个好孩子，好孩子」", "len423_176.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6634, "", "蕾娜抚摸着被白浊液濡湿的龟头，就像是在哄小孩睡觉一样。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6635, "", "刚射完精的龟头十分敏感，仅仅只是被摸了几下，就会条件反射般地抽搐起来。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6636, "蕾娜", "「哈哈，将臣……你的小弟弟正在回应我哦」", "len423_177.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6637, "将臣", "「哎，仅仅只是被手抚弄了几下……就变成这样了」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6638, "蕾娜", "「真是的，嗯嗯……明明已经射了这么多了……啊、啊……你的小弟弟还是这么坚挺」", "len423_178.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6639, "", "蕾娜再一次握住了敏感状态的阴茎。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6640, "", "随后，我的阴茎在她手掌中震颤了起来，就像是在狂喜一样。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6641, "蕾娜", "「哇哦，明明都射了一次了……现在却比刚才还要硬哦，嗯、嗯」", "len423_179.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6642, "蕾娜", "「手的触感有那么舒服吗？还是说……嗯、啊……你更喜欢我的胸器？」", "len423_180.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6643, "", "由于我正躺在蕾娜的大腿上，她只要身体前倾，那巨大的双乳就会直接压住我的脸。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6644, "", "于是，我就像条件反射一样吸住了她的乳头。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6645, "蕾娜", "「啊啊、啊啊！？将……将臣、啊、啊啊！你、你要是吸得这么用力，我就要……唔唔」", "len423_181.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6646, "", "但是，我不能总是让蕾娜来服侍我。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6647, "", "我吸住乳晕，将乳头含在嘴里，用舌尖把玩。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6648, "蕾娜", "「嗯、啊啊！啊……你这种吸法太色情了……嗯、我快受不了了……啊、啊」", "len423_182.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6649, "蕾娜", "「啊啊……嗯！我、我也觉得好舒服……啊啊啊、嗯！」", "len423_183.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6650, "将臣", "「嗯……我也想让你更舒服些」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6651, "蕾娜", "「嗯～！啊啊、既然如此……啊、啊、那我也不能输……嗯、啊啊」", "len423_184.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6652, "", "蕾娜的手将我的阴茎紧紧包住，带着包皮再次开始激烈地上下摩擦。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6653, "", "我也不甘示弱，开始更加用力地吮吸着她的乳头。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6654, "蕾娜", "「啊、啊啊……嗯、嗯……将臣……将臣，啊、啊啊！嗯、嗯嗯！」", "len423_185.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6655, "将臣", "「……蕾娜、嗯……感觉有一股牛奶的味道」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6656, "蕾娜", "「啊啊！是、是吗？嗯嗯、我自己……倒是闻不出来……嗯、啊啊！」", "len423_186.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6657, "蕾娜", "「能让我的身体变得能产生乳汁的人……嗯、啊啊……嗯、嗯嗯」", "len423_187.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6658, "蕾娜", "「只有你一个人哦，将臣……嗯嗯……今后……永远只有你……啊啊、啊啊」", "len423_188.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6659, "将臣", "「蕾娜……我也……永远只有你、蕾娜！」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6660, "", "我越来越无法克制自己了。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6661, "", "我已经无法控制住再一次涌起的快感了！", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6662, "蕾娜", "「嗯、啊！将臣，你的小弟弟，又在抽动了……是不是……又要喷出一堆牛奶了？啊啊、嗯」", "len423_189.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6663, "将臣", "「蕾娜……你的乳头也越来越硬了，是越来越有感觉了吗？」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6664, "蕾娜", "「……是的……在我生出你的孩子之前，嗯、啊啊……啊啊！」", "len423_190.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6665, "蕾娜", "「我的双乳……就一直是你的……啊、啊啊……将臣、将臣、啊啊！」", "len423_191.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6666, "", "蕾娜的手速变得更快了。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6667, "", "我的下腹部越来越热，已经热到无法忍受了！", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6668, "蕾娜", "「啊啊、啊……啊啊嗯！将臣、将臣……快射出来，不要客气，射出来……再射很多出来吧」", "len423_192.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6669, "将臣", "「嗯、我……我也快撑不住了！蕾娜、蕾娜！」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6670, "蕾娜", "「将臣……将臣、嗯！你的小弟弟变得好热……啊啊啊」", "len423_193.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6671, "蕾娜", "「你现在是不是非常……非常舒服？将臣、将臣……啊啊！？」", "len423_194.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6672, "蕾娜", "「嗯、啊啊……啊啊啊！？」", "len423_195.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6673, "", "射精的那一瞬间，我轻轻地咬了咬乳头。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6674, "", "蕾娜发出了一阵小小的娇声。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6675, "蕾娜", "「啊啊、啊啊！将臣……你……在射精的同时……嗯嗯」", "len423_196.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6676, "蕾娜", "「竟然还在……吸着乳头……啊……啊啊啊……将臣、啊啊啊……」", "len423_197.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6677, "", "蕾娜嘴上这么说，实际上她也还在摩擦着我的阴茎。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6678, "", "随着一阵阵白浊液的涌动，她一次又一次地扒起我的包皮。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6679, "蕾娜", "「啊啊……啊啊……将臣，你真的好厉害」", "len423_198.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6680, "将臣", "「哎？为、为什么这么说」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6681, "蕾娜", "「嘿嘿，你心里应该很清楚吧？你看……嗯、嗯……」", "len423_199.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6682, "", "蕾娜的手慢慢地抚弄着我的阴茎。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6683, "蕾娜", "「竟然还是这么热……这么硬……和将臣结婚的女孩子……嗯嗯」", "len423_200.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6684, "蕾娜", "「肯定，会生很多小宝宝……」", "len423_201.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6685, "将臣", "「哈哈……那也要看……对方愿不愿意生那么多了啊？」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6686, "蕾娜", "「这个问题的答案……你心里应该十分清楚吧，将臣？」", "len423_202.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6687, "", "蕾娜那炽热的视线紧紧地铐住了我。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6688, "将臣", "「我爱你，蕾娜……」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6689, "蕾娜", "「我也爱你哦，将臣。但是现在……」", "len423_203.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6690, "蕾娜", "「我还是希望你用行动表现出来」", "len423_204.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6691, "", "当然了，我没有理由拒绝。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6692, "", "我也想……和蕾娜合为一体。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev413a", null], [6693, "蕾娜", "「嗯啊……啊啊、啊啊啊！？」", "len423_205.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6694, "", "刚来到浴池，我就迫不及待地从身后插入了。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6695, "", "但令人意外的是，蕾娜的私处早已湿润得十分彻底。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6696, "蕾娜", "「将、将臣……嗯嗯……你、你不用这么慌张的……我又不会逃跑」", "len423_206.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6697, "将臣", "「抱……抱歉……我有点等不及了」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6698, "蕾娜", "「啊、啊……哈哈，你愿意这么说，我很开心……」", "len423_207.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6699, "蕾娜", "「……还是，你还是得一步一步来嘛……啊啊」", "len423_208.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6700, "", "蕾娜回过头，将双唇靠了过来。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6701, "", "我从背后紧紧地抱住了她，轻轻地……温柔地吻了下去。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6702, "蕾娜", "「唔……啊……仅此而已吗？」", "len423_209.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6703, "将臣", "「不，还没结束呢」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6704, "蕾娜", "「嘿嘿……我期待你的表现哦，将臣。啊啊……嗯……嗯……啊唔……啊啊！」", "len423_210.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6705, "", "这一次，我将舌头深入双唇之间，开始了激烈的深吻。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6706, "", "仅仅只是舌尖交织在一起，我们的感官就已经受到了剧烈的刺激，我的阴茎甚至在蕾娜的阴道里跃动了起来。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6707, "蕾娜", "「唔啊！？啊啊……啊啊……将臣，你真的……太有精神了……嗯啊、嗯！」", "len423_211.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6708, "", "我一边吮吸着蕾娜的嘴唇，一边慢慢地开始了活塞运动。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6709, "", "我用抱住蕾娜双肩的手抚摸着她的身躯，并顺势将她的双乳紧紧握在手中。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6710, "蕾娜", "「啊、啊啊！唔……啊……将臣、嗯……今晚的你，简直就像一头饿狼呢……啊、啊啊！」", "len423_212.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6711, "将臣", "「也许吧……我现在想要你……想要你……想得不得了」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6712, "蕾娜", "「啊啊、啊啊！啊、嗯……太激烈了……将臣、将臣！啊啊、啊啊！」", "len423_213.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6713, "", "这次和初夜时并不一样。蕾娜从最开始就已经有了良好的状态。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6714, "", "但她的的阴道和处女时无异，依旧是那么紧，就像是准备毫不留情地掏空我的身躯一样。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6715, "蕾娜", "「嗯、啊……啊啊！将臣、不停地撞击着我的屁股……啊、啊啊……洗澡水，都荡起了阵阵涟漪……！」", "len423_214.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6716, "", "我和蕾娜结合得越深，溅起的水花就越来越激烈。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6717, "", "臀部撞击下腹部的弹力实在是令人着迷。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6718, "蕾娜", "「啊、啊啊！将、将臣……要是再这么激烈……啊啊、嗯嗯！」", "len423_215.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6719, "蕾娜", "「你会不会……又要马上射出来啊……啊啊、啊啊啊！」", "len423_216.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6720, "将臣", "「说、说的也是……还是得休息一会儿」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6721, "", "如果可以的话，我想让蕾娜也跟我一起舒服。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6722, "", "但就算我想停下来，真的要完全停下来还是相当困难。我将腰部紧紧地贴着蕾娜的臀部，试图将龟头插入至她的的最深处。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6723, "蕾娜", "「嗯嗯……这、这种感觉……啊、啊啊！这是直击子宫的感觉啊……啊啊啊啊！」", "len423_217.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6724, "将臣", "「我听说……女性只要插入就会产生快感，这是真的吗？」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6725, "蕾娜", "「谁……谁知道呢，我也不清楚……嗯嗯！啊、啊……啊啊啊！」", "len423_218.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6726, "蕾娜", "「……我、我个人的话……啊啊！很喜欢……用子宫来体验你的触感……啊啊啊！」", "len423_219.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6727, "", "这话说得真是可爱。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6728, "", "说得我一股爱意猛然涌上心头。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6729, "蕾娜", "「啊啊啊！将、将臣……嗯嗯、我的后颈……啊啊！你要是吸得这么用力……会吸出吻痕的，啊、啊啊！」", "len423_220.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6730, "", "我一边将脸颊压在蕾娜的后颈上，一边从下往上托着她的双乳，在手中把玩。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6731, "", "我不停地用双指夹着她的乳头，痛快了体验了一番这无与伦比的重量感。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6732, "蕾娜", "「嗯嗯、嗯嗯嗯……看来，你是真的……很喜欢我的双乳」", "len423_221.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6733, "将臣", "「……我喜欢你身体的每一个角落」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6734, "", "当然，胸部当然是更加喜欢了，这个无法否认。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6735, "", "蕾娜的乳房，柔软得仿佛能够将手指吸进去一样，但与此同时，也保持着紧致的弹力，无论怎么揉都不会腻。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6736, "蕾娜", "「啊……啊、将、将臣……将臣、啊！啊啊……啊啊、啊！」", "len423_222.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6737, "", "我保持着插入到最深处的状态，开始转动腰部。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6738, "", "仅仅如此，就足以保证充阴茎的硬度了。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6739, "蕾娜", "「哎，将臣？我感觉……啊、啊……我快受不了了……啊啊」", "len423_223.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6740, "将臣", "「……蕾娜？」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6741, "", "蕾娜自己也开始转动腰部了。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6742, "", "转动的方向刚好跟我相反，阴道内壁直接摩擦着我的阴茎。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6743, "蕾娜", "「嗯、嗯……啊！我的腰、我的腰……已经不听使唤了……将臣……将臣！」", "len423_224.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6744, "蕾娜", "「将臣，我希望你也动起来……啊啊、啊啊……啊啊啊！」", "len423_225.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6745, "将臣", "「好、好吧……蕾娜！蕾娜！」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6746, "蕾娜", "「啊啊！啊啊、啊啊……将臣、将臣……！啊啊、啊啊！啊啊啊！」", "len423_226.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6747, "", "我们相互撞击着对方的腰部，渴求着对方的一切。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6748, "", "只要我们同时动起来，就会有一股远超初夜时的快感从脊骨深处涌起。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6749, "蕾娜", "「啊啊、啊啊！啊、啊……好、好厉害！我……我已经有点迷糊了、嗯嗯……」", "len423_227.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6750, "蕾娜", "「太舒服了，将臣！将臣、啊、啊啊啊！？」", "len423_228.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6751, "", "我已经快忍不住了。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6752, "", "大脑的中枢似乎已经麻痹，我已经不知道自己的腰还受不受自己的控制了。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6753, "蕾娜", "「啊啊啊、要去了！要去了！将臣……你呢？将臣，你舒服吗、啊啊、啊啊！」", "len423_229.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6754, "将臣", "「我也……我也要射了，蕾娜，蕾娜！」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6755, "蕾娜", "「我们、要一起高潮了吗？将臣……我们一起……啊啊！啊啊……啊、一起、痛快地高潮吧」", "len423_230.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6756, "", "当然了，我当然痛快，太痛快了！正因为是跟蕾娜在一起，所以才会这么痛快。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6757, "", "就是这样，就是这样，我想就这样将囤积在腰部的一团烈火尽情释放出来！", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6758, "蕾娜", "「啊啊！啊啊、啊啊、啊……啊、嗯嗯！我喜欢你、喜欢你……将臣、我最喜欢你了，将臣」", "len423_231.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6759, "将臣", "「我也是……我爱你，蕾娜，蕾娜！」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6760, "蕾娜", "「我也是……我们都爱对方……没错吧？将臣、将臣！啊、啊啊……让我们一起、一起高潮吧、啊啊！」", "len423_232.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6761, "蕾娜", "「啊啊、啊啊！啊啊、啊……嗯嗯、将臣！将臣……我要去了、要去了！要去了！」", "len423_233.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6762, "蕾娜", "「啊啊、啊啊！我要忍不住了、嗯、啊啊啊！？」", "len423_234.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6763, "蕾娜", "「啊啊啊啊啊啊啊啊！！」", "len423_235.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6764, "", "就在蕾娜高潮的那一瞬间。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6765, "", "我的阴茎终于挣脱了阴道内壁的吸附，奋力向蕾娜的身体射出了大量的精液。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6766, "蕾娜", "「啊……哎？将臣……你怎么拔出来了……我浑身上下，都黏黏的……」", "len423_236.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6767, "", "随着阴茎的阵阵胀动，蕾娜也渐渐被染成了白色。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6768, "", "白浊液混着温泉的飞沫，拉出了无数丝线，落在了地面上。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6769, "蕾娜", "「啊……啊啊、其实今天……就算射在里面……也没问题的」", "len423_237.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6770, "将臣", "「是吗？可是……」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6771, "蕾娜", "「嗯……不过，将臣……你好像依然很坚挺啊」", "len423_238.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6772, "", "蕾娜用大腿夹住了我将刚拔出的阴茎，来回摩擦。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6773, "蕾娜", "「啊啊、嗯……你还是不够满足吧？」", "len423_239.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6774, "蕾娜", "「接下来……你可以随便射在你喜欢的地方……嗯、嗯嗯……要不要再来一次呢？」", "len423_240.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6775, "将臣", "「……嗯」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6776, "将臣", "「只要是和你，来几次都没问题！」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6777, "蕾娜", "「嗯……啊啊！将臣的小弟弟……又直接进入最深处了！啊啊」", "len423_241.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6778, "", "插入的同时，我立刻开始了活塞运动。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6779, "", "蕾娜的阴道内壁比刚才更加凶猛了。难道是因为迎来高潮时没能得到精液的滋养吗？", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6780, "蕾娜", "「啊啊、啊！啊啊……啊、将臣？嗯嗯……来吻我吧……啊啊！」", "len423_242.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6781, "将臣", "「当然可以……嗯」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6782, "蕾娜", "「唔……啊！唔……啊……嗯……啊啊啊！嗯……将臣、将臣！啊、啊！」", "len423_243.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6783, "", "我们一边深吻，一边激烈地撞击着腰部。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6784, "", "快感伴随着爱意，让人一不留神就会堕入疯狂。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6785, "蕾娜", "「啊啊、嗯……唔啊、啊！啊啊、啊！啊……啊啊啊！」", "len423_244.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6786, "", "我想要蕾娜。我喜欢蕾娜。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6787, "蕾娜", "「将、将臣！我想要你……我喜欢你、喜欢你……将臣、将臣！」", "len423_245.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6788, "", "连我们的思绪也交织在了一起。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6789, "", "我们就像一只合体的野兽一样，永无止境地渴求着对方。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6790, "蕾娜", "「我还想要、还想要！啊、啊啊、啊……啊啊啊、将臣、我还想要更多、更多！」", "len423_246.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6791, "将臣", "「啊、我也是……我也还想要、还想要更多！蕾娜、蕾娜！」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6792, "蕾娜", "「一起……我们又可以一起高潮了吧？啊啊、啊啊！啊、啊啊……啊啊啊啊！？」", "len423_247.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6793, "", "我们谁都没有手下留情。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6794, "", "再这样下去，我肯定又要轻易射精了。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6795, "蕾娜", "「你不要忍耐……将臣，不用忍耐的，啊、啊啊！」", "len423_248.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6796, "蕾娜", "「再来一次吧……再来射更多吧！我希望……我能让你快乐到欲仙欲死、啊啊！」", "len423_249.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6797, "", "我……", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6798, "蕾娜", "「将臣、将臣！我的子宫都要落下来了，它要来亲自捕捉你了……啊啊！」", "len423_250.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6799, "", "我也是一样的，我想射在蕾娜身体里面！", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6800, "", "尽管明白这是禁忌之举，但我也无法克制自己。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6801, "蕾娜", "「啊啊！啊啊！啊、啊……我不行了、不行了，要去了……我又要去了……！」", "len423_251.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6802, "将臣", "「我也是……这次，我就射在你的身体里……」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6803, "蕾娜", "「将臣……啊、啊！你愿意……射在我的子宫里吗？啊、啊、啊啊、将臣！」", "len423_252.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6804, "", "我想射出来！想射出来，我忍不住了！", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6805, "", "我想将我的一切注入蕾娜的身体里。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6806, "蕾娜", "「啊啊、啊啊！将臣，你的小弟弟在我的身体里……越胀越大！」", "len423_253.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6807, "将臣", "「就这样……这次我要就这样……射在里面！」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6808, "蕾娜", "「来吧，来吧！将臣……射在里面、射在我的小穴里，尽情地射吧！」", "len423_254.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6809, "蕾娜", "「只有你……才能射在这里哦？啊啊啊、啊啊！我的婴儿房……只属于你……啊啊！」", "len423_255.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6810, "蕾娜", "「……这是你专属的、啊啊！来吧！来吧、射出来吧……全部射出来……啊啊啊！？」", "len423_256.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6811, "蕾娜", "「啊啊啊啊啊啊呜呜啊！！！！」", "len423_257.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6812, "", "到达极限的那一刻，我将整个阴茎都插入了最底端。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6813, "", "我就这样顶着子宫的入口，将精液的洪流注入其中。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6814, "蕾娜", "「啊、啊啊……射出来了、嗯嗯！将臣的精子……正在疯狂地涌入我的子宫中……啊啊」", "len423_258.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6815, "蕾娜", "「子宫里……全都是……全都是你的一部分……啊啊啊……」", "len423_259.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6816, "", "配合着阴茎的阵阵胀动，阴道也开始渐渐收缩，高效地将精子尽收囊中。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6817, "", "一眨眼的工夫，蕾娜的胎内已经被我填得满满的……如此巨大的量，如果不是安全期，恐怕是难免妊娠了。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6818, "蕾娜", "「嗯、嗯……啊、啊……你都射了四次了，没想到还是有这么多……将臣，你真是厉害……」", "len423_260.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6819, "将臣", "「如果你让我自己做，我肯定是射不了这么多次，也射不出这么多量的」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6820, "蕾娜", "「哈哈，你是想说……这都多亏了爱情的力量吗？」", "len423_261.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6821, "将臣", "「嗯……说实话，我觉得就是这个道理」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6822, "", "我紧紧地抱住蕾娜，贴着她的脸颊。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6823, "将臣", "「因为……」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6824, "将臣", "「我最爱你了」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6825, "蕾娜", "「这都是因为你爱我吗？」", "len423_262.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6826, "蕾娜", "「啊啊、啊！我喜欢、喜欢你……将臣、我希望你也尽情地爱我、啊啊啊！」", "len423_263.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6827, "", "爱意渐渐填满了内心，满到几乎快要溢出来。与此同时，欲望也进一步加深。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6828, "", "但这对我们来说是极其自然的事。相互渴求对方，并没有什么问题。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6829, "蕾娜", "「将臣、将臣！我……我已经……我已经……要被你弄高潮了！」", "len423_264.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6830, "将臣", "「我也，我也快要射了！蕾娜、蕾娜！」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6831, "蕾娜", "「啊、我喜欢你……喜欢你，将臣！让我们再次一起、一起……啊啊啊！？啊啊」", "len423_265.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6832, "", "我们相互渴求的爱意是如此炽热，几乎快要将我们溶化！", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6833, "", "在如此炽烈的缠绵之下，我们竟然还能保持原形！", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6834, "蕾娜", "「啊啊、啊啊！我喜欢你、将臣……将臣、我喜欢你！喜欢、喜欢、最喜欢、最喜欢了！」", "len423_266.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6835, "将臣", "「我也是，我喜欢你，喜欢你，蕾娜！」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6836, "蕾娜", "「啊啊！啊啊、啊啊、啊啊啊……我好开心，我非常开心，将臣！将臣！」", "len423_267.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6837, "蕾娜", "「你也要尽兴地、痛快地……用我的身体、射出你的全部哦……将臣、将臣！」", "len423_268.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6838, "蕾娜", "「啊啊、啊啊！啊啊、啊啊啊！嗯、嗯、啊啊……嗯、啊啊啊啊！？」", "len423_269.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6839, "蕾娜", "「啊啊啊啊啊啊啊啊啊啊啊！！！！」", "len423_270.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6840, "", "蕾娜就像一只打哈欠的猫一样，将脊背挺了起来。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6841, "", "紧接着，我立刻拔出了阴茎。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6842, "蕾娜", "「啊啊！啊……好厉害，这气势好猛……啊啊，这都是将臣的精液……我又被染成白色了，嗯嗯……」", "len423_271.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6843, "", "我的阴茎依旧在阴道口上摩擦着，一波又一波的白浊液向蕾娜喷射而去。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6844, "", "直到蕾娜彻底被染成了我的颜色，我的阴茎才终于平息下来。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6845, "蕾娜", "「啊……啊……嗯啊，我又被你射了一身……啊、啊」", "len423_272.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6846, "将臣", "「哈哈，难道不乐意吗？」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6847, "蕾娜", "「……怎么会呢……只要是你的精液，我还是很开心的」", "len423_273.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6848, "将臣", "「是吗？」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6849, "", "我静静地从背后抱住了蕾娜。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6850, "蕾娜", "「嗯，因为我……」", "len423_274.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6851, "蕾娜", "「最爱的人就是你」\\n「最爱的人就是我？」", "len423_275.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6852, "", "我们的二人的声音，在“最爱”两字上重合了。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6853, "", "这么听着，还是有些难为情，我不禁露出了苦笑。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6854, "", "但尽管如此，我依然紧紧地抱着蕾娜。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6855, "蕾娜", "「就这样抱一会儿吧……先不要分开哦」", "len423_276.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6856, "将臣", "「当然了……今晚，我们就牵着手入眠吧？」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6857, "蕾娜", "「嘿嘿……没问题♪我最喜欢你了，将臣」", "len423_277.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 7-1", "ev414a", null], [6858, "", "——看起来今晚也顺利进到梦里来了。", null, "空_青空", "bgm36.opus", null, "CHAPTER 7-2", null, null], [6859, "", "上一次，我们了解到那位武士就是女神大人的心爱之人。在那之后，他也在不停地立功受赏。", null, "空_青空", "bgm36.opus", null, "CHAPTER 7-2", null, null], [6860, "", "他家主公为了扩大势力，一次又一次地向北方进军，这也相应地让他的地位节节攀升。", null, "空_青空", "bgm36.opus", null, "CHAPTER 7-2", null, null], [6861, "", "当然，这都是多亏了神刀的保佑。", null, "空_青空", "bgm36.opus", null, "CHAPTER 7-2", null, null], [6862, "", "只不过这次我从一开始就和这位武士合为一体了，并没有感觉到蕾娜在我附近。", null, "空_青空", "bgm36.opus", null, "CHAPTER 7-2", null, null], [6863, "", "我想蕾娜应该是和女神大人合为一体了。", null, "空_青空", "bgm36.opus", null, "CHAPTER 7-2", null, null], [6864, "将臣", "「（按照剧情发展……接下来应该会让我们会合吧？）」", null, "空_青空", "bgm36.opus", null, "CHAPTER 7-2", null, null], [6865, "", "然而战乱旷日持久，武士也实在找不到机会回乡。", null, "空_青空", "bgm36.opus", null, "CHAPTER 7-2", null, null], [6866, "", "就在他好不容易回到家乡的时候，他的上官突然又把他叫过去谈话。", null, "特殊_武家屋敷d", "bgm36.opus", null, "CHAPTER 7-2", null, null], [6867, "将臣", "「什么？您是说要给在下介绍一门亲事？」", null, "特殊_武家屋敷d", "bgm36.opus", null, "CHAPTER 7-2", null, null], [6868, "将臣", "「（这个……接下来的发展，是不是就跟驹川大夫说的一样了啊？）」", null, "特殊_武家屋敷d", "bgm36.opus", null, "CHAPTER 7-2", null, null], [6869, "", "这位上官家里没有男孩，正想招个入赘女婿。", null, "特殊_武家屋敷d", "bgm36.opus", null, "CHAPTER 7-2", null, null], [6870, "", "似乎是从很久之前开始，上官就很欣赏他在战场上的表现。", null, "特殊_武家屋敷d", "bgm36.opus", null, "CHAPTER 7-2", null, null], [6871, "", "而且他的那位上官还是他家主公的兄弟。", null, "特殊_武家屋敷d", "bgm36.opus", null, "CHAPTER 7-2", null, null], [6872, "", "只要答应这门亲事，以后等待他的必定是更加辉煌的前途。", null, "特殊_武家屋敷d", "bgm36.opus", null, "CHAPTER 7-2", null, null], [6873, "将臣", "「……能让在下考虑几日吗？」", null, "特殊_武家屋敷d", "bgm36.opus", null, "CHAPTER 7-2", null, null], [6874, "", "尽管他明白这一切，但还是没有立刻给出答复。", null, "特殊_武家屋敷d", "bgm36.opus", null, "CHAPTER 7-2", null, null], [6875, "", "他心里自然还是放不下那位女神大人。", null, "特殊_武家屋敷d", "bgm36.opus", null, "CHAPTER 7-2", null, null], [6876, "", "在那之后，等他久违地走到曾经常去的那片河边空地的时候，他已经下定了决心。", null, "山_川沿いa", "bgm36.opus", null, "CHAPTER 7-2", null, null], [6877, "将臣", "「丛云小姐，可否请您与在下结为夫妻！」", null, "山_川沿いa", "bgm36.opus", null, "CHAPTER 7-2", null, null], [6878, "将臣", "「（哇哦！）」", null, "山_川沿いa", "bgm36.opus", null, "CHAPTER 7-2", null, null], [6879, "", "由于我的意识在他身体里，所以搞得我也有些难为情。", null, "山_川沿いa", "bgm36.opus", null, "CHAPTER 7-2", null, null], [6880, "", "不过他这样确实很有男子气概，古代人到底还是不一样。", null, "山_川沿いa", "bgm36.opus", null, "CHAPTER 7-2", null, null], [6881, "蕾娜", "「（……啊）」", "len424_001.ogg", "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "06"}, "CHAPTER 7-2", null, null], [6882, "将臣", "「（哎，蕾娜？）」", null, "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "06"}, "CHAPTER 7-2", null, null], [6883, "", "她果然在这里。", null, "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "06"}, "CHAPTER 7-2", null, null], [6884, "", "但她为什么会唉声叹气……？", null, "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "06"}, "CHAPTER 7-2", null, null], [6885, "丛云", "「呵，啊哈哈哈哈！蠢男人，你究竟误会了什么？」", "lem424_001.ogg", "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "08"}, "CHAPTER 7-2", null, null], [6886, "将臣", "「……丛云姑娘？」", null, "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "08"}, "CHAPTER 7-2", null, null], [6887, "丛云", "「你该不会真以为我对你有意？」", "lem424_002.ogg", "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "21"}, "CHAPTER 7-2", null, null], [6888, "丛云", "「对于你这样出身下贱的男人，我岂会动真情」", "lem424_003.ogg", "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "23"}, "CHAPTER 7-2", null, null], [6889, "将臣", "「（蕾娜，这到底是是怎么回事？）」", null, "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 7-2", null, null], [6890, "蕾娜", "「（……武士要当人家的乘龙快婿的事……女神大人已经听说了）」", "len424_002.ogg", "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "29"}, "CHAPTER 7-2", null, null], [6891, "蕾娜", "「（她听说武士好不容易要回来了，就专程跑去见他，然后就听到了……）」", "len424_003.ogg", "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "29"}, "CHAPTER 7-2", null, null], [6892, "", "哎？我完全没注意到。", null, "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "29"}, "CHAPTER 7-2", null, null], [6893, "将臣", "「您在说谎」", null, "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "23"}, "CHAPTER 7-2", null, null], [6894, "将臣", "「丛云小姐，您以为在下看不出来吗？您并不是那种会玩弄人心的人」", null, "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "23"}, "CHAPTER 7-2", null, null], [6895, "丛云", "「不……不要说得你好像很了解我一样！」", "lem424_004.ogg", "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "16"}, "CHAPTER 7-2", null, null], [6896, "丛云", "「这么久不回来，刚回来就说这些，你以为你是谁？我这边也是有人来提亲的」", "lem424_005.ogg", "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "23"}, "CHAPTER 7-2", null, null], [6897, "将臣", "「…………丛云小姐也有亲事？」", null, "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "23"}, "CHAPTER 7-2", null, null], [6898, "丛云", "「没错，是家父定下的亲事」", "lem424_006.ogg", "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "33"}, "CHAPTER 7-2", null, null], [6899, "丛云", "「人、人家可是比你要好不知道多少倍的贵族公子」", "lem424_007.ogg", "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "14"}, "CHAPTER 7-2", null, null], [6900, "", "这肯定也是骗人的吧。", null, "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "14"}, "CHAPTER 7-2", null, null], [6901, "将臣", "「（可是，她也没必要说得这么过分吧……）」", null, "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "12"}, "CHAPTER 7-2", null, null], [6902, "蕾娜", "「（不用这种方式的话……实在是没法斩断这段感情）」", "len424_004.ogg", "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "30"}, "CHAPTER 7-2", null, null], [6903, "蕾娜", "「（白狛也为这事和她吵了一次又一次……说凡人和神是不可能结合的……）」", "len424_005.ogg", "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "23"}, "CHAPTER 7-2", null, null], [6904, "蕾娜", "「（……最后……她不得不承认……）」", "len424_006.ogg", "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "07"}, "CHAPTER 7-2", null, null], [6905, "蕾娜", "「（人神有别，她无法为自己最爱的人带来人类的幸福……）」", "len424_007.ogg", "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "06"}, "CHAPTER 7-2", null, null], [6906, "", "这……！也许在他们那个时代，这确实是没办法的事情。", null, "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "06"}, "CHAPTER 7-2", null, null], [6907, "", "但是对于生活在现代社会的我们来说，心里总觉得他们应该对自己更诚实一些。", null, "山_川沿いa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "06"}, "CHAPTER 7-2", null, null], [6908, "将臣", "「原来如此……这真是件喜事，在下先向您道贺了」", null, "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "15"}, "CHAPTER 7-2", null, null], [6909, "将臣", "「抱歉借了您的东西这么长时间，在下也觉得差不多该把丛雨还给您了」", null, "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "15"}, "CHAPTER 7-2", null, null], [6910, "丛云", "「区区一把刀，送给你就是了」", "lem424_008.ogg", "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "32"}, "CHAPTER 7-2", null, null], [6911, "丛云", "「对我来说，那、那本来就不是什么大不了的东西」", "lem424_009.ogg", "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "31"}, "CHAPTER 7-2", null, null], [6912, "将臣", "「是吗。但是对于在下来说，此刀有如毕生之珍宝」", null, "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "31"}, "CHAPTER 7-2", null, null], [6913, "将臣", "「既然姑娘愿意相赠，在下就恭敬不如从命，拜领厚赐了」", null, "山_川沿いa", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "31"}, "CHAPTER 7-2", null, null], [6914, "", "男人就像对待陌生人一样，恭恭敬敬地鞠了个躬。礼毕，他直接转过身子，就像是不愿再和女神对视一样。", null, "山_川沿いa", "bgm36.opus", null, "CHAPTER 7-2", null, null], [6915, "", "我仿佛能感觉到女神大人一时间忘了呼吸。", null, "山_川沿いa", "bgm36.opus", null, "CHAPTER 7-2", null, null], [6916, "", "但是在那之后，他们还是没有再次交谈。不仅如此，他们甚至都没有再看对方一眼。", null, "山_川沿いa", "bgm36.opus", null, "CHAPTER 7-2", null, null], [6917, "", "不久之后，他和上官的女儿举行了婚礼。", null, "特殊_武家屋敷a", "bgm36.opus", null, "CHAPTER 7-2", null, null], [6918, "", "主公觉得，既然入赘，那当然是传宗接代为先，于是暂时给他安排了个留守城内的工作，他对此稍稍有点不满。", null, "特殊_武家屋敷a", "bgm36.opus", null, "CHAPTER 7-2", null, null], [6919, "", "但这份工作也确实在一定程度上帮助他治愈了失恋的创伤。", null, "特殊_武家屋敷a", "bgm36.opus", null, "CHAPTER 7-2", null, null], [6920, "蕾娜", "「（…………）」", "len424_008.ogg", "特殊_武家屋敷a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 7-2", null, null], [6921, "", "换成平时，蕾娜应该会做出各种夸张的反应，但现在她却异常安静。", null, "特殊_武家屋敷a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 7-2", null, null], [6922, "将臣", "「（蕾娜？你在附近吗？）」", null, "特殊_武家屋敷a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 7-2", null, null], [6923, "蕾娜", "「（……呜…………呜～）」", "len424_009.ogg", "特殊_武家屋敷a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25n"}, "CHAPTER 7-2", null, null], [6924, "", "什么，她在哭？", null, "特殊_武家屋敷a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25n"}, "CHAPTER 7-2", null, null], [6925, "蕾娜", "「（现在……女神大人也悄悄过来了……就为了看他一眼……）」", "len424_010.ogg", "特殊_武家屋敷a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 7-2", null, null], [6926, "蕾娜", "「（但是，你看……）」", "len424_011.ogg", "特殊_武家屋敷a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "30"}, "CHAPTER 7-2", null, null], [6927, "", "婚礼中，男人太过紧张，居然把杯子弄掉了。", null, "特殊_武家屋敷a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "30"}, "CHAPTER 7-2", null, null], [6928, "", "身边的新娘为了避免他的衣服被弄脏，竟然伸出手接住了洒出来的酒水。", null, "特殊_武家屋敷a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "30"}, "CHAPTER 7-2", null, null], [6929, "将臣", "「啊，这可真是……！」", null, "特殊_武家屋敷a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "30"}, "CHAPTER 7-2", null, null], [6930, "女儿", "「……～」", "msm424_001.ogg", "特殊_武家屋敷a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "30"}, "CHAPTER 7-2", null, null], [6931, "", "在那一瞬间，新娘和武士眼神交汇，但马上又害羞地垂下了眼帘。", null, "特殊_武家屋敷a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "30"}, "CHAPTER 7-2", null, null], [6932, "", "从这细微的动作之中，我似乎能感受到她的心意。", null, "特殊_武家屋敷a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "30"}, "CHAPTER 7-2", null, null], [6933, "", "毕竟这门亲事，她自己也是答应了的。", null, "特殊_武家屋敷a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "30"}, "CHAPTER 7-2", null, null], [6934, "", "看见这一幕，女神大人已经无法平静地待在这里了。", null, "山_山道b", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "30"}, "CHAPTER 7-2", null, null], [6935, "丛云", "「这样就好，因为……那女孩也喜欢他……」", "lem424_010.ogg", "山_山道b", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "30"}, "CHAPTER 7-2", null, null], [6936, "丛云", "「……所以，这样……这样是最好的」", "lem424_011.ogg", "山_山道b", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "06"}, "CHAPTER 7-2", null, null], [6937, "", "逃出婚礼现场，逃回山中之后，她一直在心里如此告诫着自己。", null, "山_山道b", "bgm36.opus", null, "CHAPTER 7-2", null, null], [6938, "", "没想到这段恋情的结局竟是如此凄苦。", null, "山_山道b", "bgm36.opus", null, "CHAPTER 7-2", null, null], [6939, "白狛", "「姐姐大人……」", "srk424_001.ogg", "山_山道b", "bgm36.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 7-2", null, null], [6940, "", "白狛只能用心痛的眼神看着她。", null, "山_山道b", "bgm36.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 7-2", null, null], [6941, "将臣", "「（……嗯？）」", null, "山_山道b", "bgm36.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 7-2", null, null], [6942, "", "就在这个时候。", null, "山_山道b", "bgm27.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 7-2", null, null], [6943, "", "白狛的眼神突然从劝慰和同情变成了充满执念的样子。", null, "山_山道b", "bgm27.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 7-2", null, null], [6944, "", "……难道说，这才是它的本性？", null, "山_山道b", "bgm27.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 7-2", null, null], [6945, "", "不，我并不这样认为。", null, "山_山道b", "bgm27.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 7-2", null, null], [6946, "", "我是通过那位武士的眼睛来窥探宿体的记忆，而蕾娜则是通过丛云的眼睛。", null, "山_山道b", "bgm27.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 7-2", null, null], [6947, "", "那么，是不是也有谁正通过白狛的眼睛窥视着一切呢？", null, "山_山道b", "bgm27.opus", null, "CHAPTER 7-2", null, null], [6948, "", "这些仅仅只是我的猜测。", null, "山_山道b", "bgm27.opus", null, "CHAPTER 7-2", null, null], [6949, "", "那个窥视者……该不会就是祟神自己的意识吧？", null, "山_山道b", "bgm27.opus", null, "CHAPTER 7-2", null, null], [6950, "", "今天早上的锻炼还是和往常一样，从跑步开始。", null, "学院_学院前a", "bgm34.opus", null, "CHAPTER 7-2", null, null], [6951, "将臣", "「……哈啊……哈啊」", null, "学院_学院前a", "bgm34.opus", null, "CHAPTER 7-2", null, null], [6952, "蕾娜", "「哇哦！速度比以前更快了」", "len424_012.ogg", "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "01"}, "CHAPTER 7-2", null, null], [6953, "蕾娜", "「加油哦，将臣！」", "len424_013.ogg", "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "12"}, "CHAPTER 7-2", null, null], [6954, "", "时隔许久，蕾娜又来给我加油鼓劲了。", null, "学院_学院前a", "bgm34.opus", null, "CHAPTER 7-2", null, null], [6955, "", "虽然跑的节奏有点过快，但我还是坚持到了最后。", null, "学院_学院前a", "bgm34.opus", null, "CHAPTER 7-2", null, null], [6956, "玄十郎", "「跑了这么久，耐力总算是练出来了」", "gen424_001.ogg", "学院_学院前a", "bgm34.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "剣道", "face": "02"}, "CHAPTER 7-2", null, null], [6957, "玄十郎", "「不过，剩下这么点时间也不知道做什么好」", "gen424_002.ogg", "学院_学院前a", "bgm34.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "剣道", "face": "01"}, "CHAPTER 7-2", null, null], [6958, "将臣", "「哈……哈，要不我再去跑一圈？」", null, "学院_学院前a", "bgm34.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "剣道", "face": "01"}, "CHAPTER 7-2", null, null], [6959, "玄十郎", "「哟，你居然自己主动提出来，今天劲头很足嘛」", "gen424_003.ogg", "学院_学院前a", "bgm34.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "剣道", "face": "16"}, "CHAPTER 7-2", null, null], [6960, "蕾娜", "「将臣，你不要太勉强自己哦」", "len424_014.ogg", "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "27"}, "CHAPTER 7-2", null, null], [6961, "将臣", "「没事的，正好我也想跑个痛快」", null, "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "27"}, "CHAPTER 7-2", null, null], [6962, "", "我一边说着，一边接过了蕾娜递给我的饮料。", null, "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "27"}, "CHAPTER 7-2", null, null], [6963, "蕾娜", "「是嘛，其实我的心情也和你一样」", "len424_015.ogg", "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "15"}, "CHAPTER 7-2", null, null], [6964, "蕾娜", "「我今早干活也比平时快了不少」", "len424_016.ogg", "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "19"}, "CHAPTER 7-2", null, null], [6965, "", "原来如此，所以她才有时间来陪我。", null, "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "19"}, "CHAPTER 7-2", null, null], [6966, "玄十郎", "「你们怎么了，是发生了什么事吗？」", "gen424_004.ogg", "学院_学院前a", "bgm34.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "剣道", "face": "06"}, "CHAPTER 7-2", null, null], [6967, "将臣", "「嗯，有种放不下心的感觉」", null, "学院_学院前a", "bgm34.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "剣道", "face": "06"}, "CHAPTER 7-2", null, null], [6968, "蕾娜", "「是的，这都是因为今早做的那个梦……我不想让它就那样以悲剧告终」", "len424_017.ogg", "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "30"}, "CHAPTER 7-2", null, null], [6969, "蕾娜", "「只要有我能做的，我什么都愿意做」", "len424_018.ogg", "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "25"}, "CHAPTER 7-2", null, null], [6970, "蕾娜", "「所以我才准备尝试一下我之前的那个想法」", "len424_019.ogg", "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "01"}, "CHAPTER 7-2", null, null], [6971, "", "她暂时还没有告诉我那到底是个什么想法。", null, "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "01"}, "CHAPTER 7-2", null, null], [6972, "", "不过我大致能猜到蕾娜到底想做什么。", null, "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "01"}, "CHAPTER 7-2", null, null], [6973, "玄十郎", "「我听说，你们最近又了解到了不少新的情况」", "gen424_005.ogg", "学院_学院前a", "bgm34.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "剣道", "face": "01"}, "CHAPTER 7-2", null, null], [6974, "将臣", "「嗯，驹川大夫差不多下午就该回来了，到时候我们打算把所有知道的都说出来」", null, "学院_学院前a", "bgm34.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "剣道", "face": "01"}, "CHAPTER 7-2", null, null], [6975, "将臣", "「我有种预感……大概再过几天，一切就能见分晓了」", null, "学院_学院前a", "bgm34.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "剣道", "face": "01"}, "CHAPTER 7-2", null, null], [6976, "将臣", "「下一场梦里，我们应该就能获取最关键的信息了吧？」", null, "学院_学院前a", "bgm34.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "剣道", "face": "01"}, "CHAPTER 7-2", null, null], [6977, "", "女神大人、白狛、还有那位武士之间的关系，和我们掌握的事实相差甚远。", null, "学院_学院前a", "bgm34.opus", null, "CHAPTER 7-2", null, null], [6978, "", "也就是说，接下来会发生一件决定性的大事，他们的关系也会因此改变。", null, "学院_学院前a", "bgm34.opus", null, "CHAPTER 7-2", null, null], [6979, "", "感觉我们马上就要迎来重大的转折点了。", null, "学院_学院前a", "bgm34.opus", null, "CHAPTER 7-2", null, null], [6980, "将臣", "「好了！休息这么久也差不多了」", null, "学院_学院前a", "bgm34.opus", null, "CHAPTER 7-2", null, null], [6981, "将臣", "「接下来再跑几圈？」", null, "学院_学院前a", "bgm34.opus", null, "CHAPTER 7-2", null, null], [6982, "玄十郎", "「不，你已经没必要再跑了」", "gen424_006.ogg", "学院_学院前a", "bgm34.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "剣道", "face": "16"}, "CHAPTER 7-2", null, null], [6983, "玄十郎", "「我似乎已经没有什么东西可以继续教你了」", "gen424_007.ogg", "学院_学院前a", "bgm34.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "剣道", "face": "15"}, "CHAPTER 7-2", null, null], [6984, "将臣", "「哎？」", null, "学院_学院前a", "bgm34.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "剣道", "face": "15"}, "CHAPTER 7-2", null, null], [6985, "蕾娜", "「难道说这就是所谓的“免许皆传”！？」", "len424_020.ogg", "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "11"}, "CHAPTER 7-2", null, null], [6986, "", "不不，那怎么可能呢。", null, "学院_学院前a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "11"}, "CHAPTER 7-2", null, null], [6987, "将臣", "「等等！跟你比试的时候，我还从来没有打出过有效攻击呢」", null, "学院_学院前a", "bgm34.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "剣道", "face": "01"}, "CHAPTER 7-2", null, null], [6988, "将臣", "「而且我刚才只是在跑步而已，不存在什么没有东西可教了吧」", null, "学院_学院前a", "bgm34.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "剣道", "face": "01"}, "CHAPTER 7-2", null, null], [6989, "玄十郎", "「当然，一时半会儿你是不可能打败我的」", "gen424_008.ogg", "学院_学院前a", "bgm09.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "剣道", "face": "07"}, "CHAPTER 7-2", null, null], [6990, "玄十郎", "「但是，我看你已经做好思想准备了」", "gen424_009.ogg", "学院_学院前a", "bgm09.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "剣道", "face": "15"}, "CHAPTER 7-2", null, null], [6991, "将臣", "「思想准备？」", null, "学院_学院前a", "bgm09.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "剣道", "face": "15"}, "CHAPTER 7-2", null, null], [6992, "玄十郎", "「跟古代武将比起来，你的思想准备肯定是差远了」", "gen424_010.ogg", "学院_学院前a", "bgm09.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "剣道", "face": "17"}, "CHAPTER 7-2", null, null], [6993, "玄十郎", "「但现在的你，看上去也算是一个能随时奔赴战场的男人了」", "gen424_011.ogg", "学院_学院前a", "bgm09.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "剣道", "face": "15"}, "CHAPTER 7-2", null, null], [6994, "", "我记得那位武士好像也说过类似的话。", null, "学院_学院前a", "bgm09.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "剣道", "face": "15"}, "CHAPTER 7-2", null, null], [6995, "", "虽然那只是个梦，但我多次进入他的内心，也许这样确实会受到他的影响。", null, "学院_学院前a", "bgm09.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "剣道", "face": "15"}, "CHAPTER 7-2", null, null], [6996, "玄十郎", "「列支敦瑙尔小姐，你也可以暂时先不用上班了」", "gen424_012.ogg", "学院_学院前a", "bgm09.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "剣道", "face": "15"}, "CHAPTER 7-2", null, null], [6997, "蕾娜", "「真的可以吗！？」", "len424_021.ogg", "学院_学院前a", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "05"}, "CHAPTER 7-2", null, null], [6998, "玄十郎", "「但是，我希望你能陪在将臣身边支持他。可以吗？」", "gen424_013.ogg", "学院_学院前a", "bgm09.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "剣道", "face": "19"}, "CHAPTER 7-2", null, null], [6999, "蕾娜", "「大当家……我明白了，您就放心吧！」", "len424_022.ogg", "学院_学院前a", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "02"}, "CHAPTER 7-2", null, null], [7000, "将臣", "「外公，抱歉了。感觉我好像一直在给你添麻烦」", null, "学院_学院前a", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "02"}, "CHAPTER 7-2", null, null], [7001, "玄十郎", "「你在说什么话，我这边还轮不到你来操心」", "gen424_014.ogg", "学院_学院前a", "bgm09.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "剣道", "face": "04"}, "CHAPTER 7-2", null, null], [7002, "将臣", "「主要是，我感觉志那都庄的人都对我们格外关照」", null, "学院_学院前a", "bgm09.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "剣道", "face": "04"}, "CHAPTER 7-2", null, null], [7003, "将臣", "「所以就有点好奇，你到底是怎么跟他们解释的呢」", null, "学院_学院前a", "bgm09.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "剣道", "face": "04"}, "CHAPTER 7-2", null, null], [7004, "玄十郎", "「那种事情，根本没法向别人解释吧？」", "gen424_015.ogg", "学院_学院前a", "bgm09.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "剣道", "face": "09"}, "CHAPTER 7-2", null, null], [7005, "玄十郎", "「无论是诅咒还是丛雨丸的事情，大家都以为是骗小孩的」", "gen424_016.ogg", "学院_学院前a", "bgm09.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "剣道", "face": "17"}, "CHAPTER 7-2", null, null], [7006, "将臣", "「确实……那你到底是怎么说明的呢？」", null, "学院_学院前a", "bgm09.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "剣道", "face": "17"}, "CHAPTER 7-2", null, null], [7007, "玄十郎", "「没什么，我就是提了几个不情之请罢了」", "gen424_017.ogg", "学院_学院前a", "bgm09.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "剣道", "face": "02"}, "CHAPTER 7-2", null, null], [7008, "玄十郎", "「我拜托他们这段时间尽量满足你们的要求，出了事我来负责」", "gen424_018.ogg", "学院_学院前a", "bgm09.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "剣道", "face": "03"}, "CHAPTER 7-2", null, null], [7009, "将臣", "「外公……」", null, "学院_学院前a", "bgm09.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "剣道", "face": "03"}, "CHAPTER 7-2", null, null], [7010, "", "真的没想到，外公居然会为我们做到这个地步。", null, "学院_学院前a", "bgm09.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "剣道", "face": "03"}, "CHAPTER 7-2", null, null], [7011, "玄十郎", "「将臣，你听好了，你一定要时刻明确自己的目标」", "gen424_019.ogg", "学院_学院前a", "bgm09.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "剣道", "face": "05"}, "CHAPTER 7-2", null, null], [7012, "玄十郎", "「这样你就不会迷茫」", "gen424_020.ogg", "学院_学院前a", "bgm09.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "剣道", "face": "15"}, "CHAPTER 7-2", null, null], [7013, "玄十郎", "「我相信，只要你不迷茫，就一定不会犯下错误」", "gen424_021.ogg", "学院_学院前a", "bgm09.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "剣道", "face": "15"}, "CHAPTER 7-2", null, null], [7014, "将臣", "「……谢谢外公」", null, "学院_学院前a", "bgm09.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "剣道", "face": "15"}, "CHAPTER 7-2", null, null], [7015, "将臣", "「当然了，如果能够不拔出丛雨丸就解决问题，那肯定是最好的」", null, "学院_学院前a", "bgm09.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "剣道", "face": "15"}, "CHAPTER 7-2", null, null], [7016, "玄十郎", "「那当然。只要你能做好面对突发情况的思想准备，武器都是次要的」", "gen424_022.ogg", "学院_学院前a", "bgm09.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "剣道", "face": "07"}, "CHAPTER 7-2", null, null], [7017, "玄十郎", "「在多数情况下，敌人都在你自己心里」", "gen424_023.ogg", "学院_学院前a", "bgm09.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "剣道", "face": "05"}, "CHAPTER 7-2", null, null], [7018, "玄十郎", "「能战胜自己的，只有自己的心。连自己都不能战胜的话，就更不可能发挥出真正的实力」", "gen424_024.ogg", "学院_学院前a", "bgm09.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "剣道", "face": "09"}, "CHAPTER 7-2", null, null], [7019, "", "我觉得外公说得非常对。", null, "学院_学院前a", "bgm09.opus", null, "CHAPTER 7-2", null, null], [7020, "", "但是我真的有那么坚定的思想准备吗？", null, "学院_学院前a", "bgm09.opus", null, "CHAPTER 7-2", null, null], [7021, "", "不，我应该相信自己。", null, "学院_学院前a", "bgm09.opus", null, "CHAPTER 7-2", null, null], [7022, "", "就像外公和蕾娜相信我一样。", null, "学院_学院前a", "bgm09.opus", null, "CHAPTER 7-2", null, null], [7023, "", "如果不相信自己，我根本不可能做好思想准备。", null, "学院_学院前a", "bgm09.opus", null, "CHAPTER 7-2", null, null], [7024, "", "看样子，感觉到终局将至的人并不只有我和蕾娜。", null, "学院_教室休憩a", "bgm39.opus", null, "CHAPTER 7-2", null, null], [7025, "芳乃", "「…………」", "yos424_001.ogg", "学院_教室休憩a", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "22"}, "CHAPTER 7-2", null, null], [7026, "", "我一走进教室，就能从朝武身上感觉到一股精神压力。", null, "学院_教室休憩a", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "22"}, "CHAPTER 7-2", null, null], [7027, "", "就连和她在一起的常陆也一言不发，大概也是被那气氛感染了。", null, "学院_教室休憩a", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "22"}, "CHAPTER 7-2", null, null], [7028, "廉太郎", "「我说啊，你们难不成是跟巫女大人吵架了？」", "ren424_001.ogg", "学院_教室休憩a", "bgm39.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "34"}, "CHAPTER 7-2", null, null], [7029, "将臣", "「应该没有吧」", null, "学院_教室休憩a", "bgm39.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "34"}, "CHAPTER 7-2", null, null], [7030, "廉太郎", "「我就说，看起来也不像是吵架」", "ren424_002.ogg", "学院_教室休憩a", "bgm39.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "29"}, "CHAPTER 7-2", null, null], [7031, "廉太郎", "「怎么说呢，这气氛有点像比赛前的休息室？」", "ren424_003.ogg", "学院_教室休憩a", "bgm39.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "01"}, "CHAPTER 7-2", null, null], [7032, "将臣", "「什么意思，你是说社团活动那种？」", null, "学院_教室休憩a", "bgm39.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "01"}, "CHAPTER 7-2", null, null], [7033, "", "不过在前些日子，我们几个在一起确实有一种类似社团活动的气氛。", null, "学院_教室休憩a", "bgm39.opus", null, "CHAPTER 7-2", null, null], [7034, "", "诅咒，使命，责任感，这些词与我们息息相关。", null, "学院_教室休憩a", "bgm39.opus", null, "CHAPTER 7-2", null, null], [7035, "", "和祟神战斗的时候，我绝对不会抱着好玩的心态。", null, "学院_教室休憩a", "bgm39.opus", null, "CHAPTER 7-2", null, null], [7036, "", "但是，深夜进入森林，悄悄地和妖孽对抗……", null, "学院_教室休憩a", "bgm39.opus", null, "CHAPTER 7-2", null, null], [7037, "", "如果说这些事情没有任何乐趣，那肯定是骗人的。", null, "学院_教室休憩a", "bgm39.opus", null, "CHAPTER 7-2", null, null], [7038, "", "正因为我们在一起，所以就算是危急情况，我也能乐在其中。", null, "学院_教室休憩a", "bgm39.opus", null, "CHAPTER 7-2", null, null], [7039, "蕾娜", "「我们当然没有在吵架」", "len424_023.ogg", "学院_教室休憩a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 7-2", null, null], [7040, "蕾娜", "「大概是因为，我们都在想同样的事情吧？」", "len424_024.ogg", "学院_教室休憩a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "03"}, "CHAPTER 7-2", null, null], [7041, "将臣", "「……嗯，我也这么觉得」", null, "学院_教室休憩a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "03"}, "CHAPTER 7-2", null, null], [7042, "", "我还没有把详细情况告诉朝武她们。", null, "学院_教室休憩a", "bgm39.opus", null, "CHAPTER 7-2", null, null], [7043, "", "说实话，我们最近的关系有点尴尬。", null, "学院_教室休憩a", "bgm39.opus", null, "CHAPTER 7-2", null, null], [7044, "", "但尽管如此，她们是不是依然察觉到了一些情况呢？就像我们现在看懂了她们的情绪一样。", null, "学院_教室休憩a", "bgm39.opus", null, "CHAPTER 7-2", null, null], [7045, "", "她们两人——", null, "学院_教室休憩a", "bgm39.opus", null, "CHAPTER 7-2", null, null], [7046, "", "已经做好了突发情况下和我们一起战斗的心理准备。", null, "学院_教室休憩a", "bgm39.opus", null, "CHAPTER 7-2", null, null], [7047, "", "我能清晰地感受到她们的思想准备。", null, "学院_教室休憩a", "bgm39.opus", null, "CHAPTER 7-2", null, null], [7048, "廉太郎", "「怎么搞的嘛？果然是发生了什么事吧？」", "ren424_004.ogg", "学院_教室休憩a", "bgm39.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "01"}, "CHAPTER 7-2", null, null], [7049, "将臣", "「等到能说的时候，我会告诉你的」", null, "学院_教室休憩a", "bgm39.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "01"}, "CHAPTER 7-2", null, null], [7050, "", "但愿有朝一日，我们能一边说笑一边聊起这些天的经历。", null, "学院_教室休憩a", "bgm39.opus", null, "CHAPTER 7-2", null, null], [7051, "", "就像聊起青春时代的一幕幕回忆一样。", null, "学院_教室休憩a", "bgm39.opus", null, "CHAPTER 7-2", null, null], [7052, "", "午休刚结束，驹川大夫就联系我了。", null, "空_青空", "bgm39.opus", null, "CHAPTER 7-2", null, null], [7053, "", "虽然课还没上完，但我还是得优先这边的事。", null, "空_青空", "bgm39.opus", null, "CHAPTER 7-2", null, null], [7054, "将臣", "「走吧，蕾娜！」", null, "学院_廊下a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 7-2", null, null], [7055, "蕾娜", "「好的，将臣！」", "len424_025.ogg", "学院_廊下a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 7-2", null, null], [7056, "芳乃", "「……」", "yos424_002.ogg", "学院_廊下a", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "22"}, "CHAPTER 7-2", null, null], [7057, "", "等我们赶到驹川大夫的诊所时，安晴叔叔和小雨已经到了。", null, "街_診療所a", "bgm39.opus", null, "CHAPTER 7-2", null, null], [7058, "", "我们立刻向他们说了梦里的事情。", null, "街_診療所a", "bgm39.opus", null, "CHAPTER 7-2", null, null], [7059, "美津叶", "「看来童话终究只是童话」", "miz424_001.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "21"}, "CHAPTER 7-2", null, null], [7060, "美津叶", "「原来并不是男人背叛了女人，而是女人自己退出了……」", "miz424_002.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "24"}, "CHAPTER 7-2", null, null], [7061, "安晴", "「但既然如此，白狛身为山之子，为什么要参与诅咒呢？」", "yas424_001.ogg", "街_診療所a", "bgm39.opus", {"char": "安晴", "file": "安晴.stand", "dress": "私服", "face": "12"}, "CHAPTER 7-2", null, null], [7062, "将臣", "「现在还不知道他究竟有没有主动参与」", null, "街_診療所a", "bgm39.opus", {"char": "安晴", "file": "安晴.stand", "dress": "私服", "face": "12"}, "CHAPTER 7-2", null, null], [7063, "蕾娜", "「再过不久应该就能弄清楚了」", "len424_026.ogg", "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "08"}, "CHAPTER 7-2", null, null], [7064, "美津叶", "「确实，事已至此，比起我们自己瞎猜，还是等你们做梦更加明智」", "miz424_003.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "29"}, "CHAPTER 7-2", null, null], [7065, "安晴", "「没错……现在急着得出结论也没用」", "yas424_002.ogg", "街_診療所a", "bgm39.opus", {"char": "安晴", "file": "安晴.stand", "dress": "私服", "face": "13"}, "CHAPTER 7-2", null, null], [7066, "", "还差一点。", null, "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "29"}, "CHAPTER 7-2", null, null], [7067, "", "正因为就差一点了，所以我才焦急。", null, "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "29"}, "CHAPTER 7-2", null, null], [7068, "", "看到安晴叔叔也那么焦急，我反而松了一口气。", null, "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "29"}, "CHAPTER 7-2", null, null], [7069, "将臣", "「对了，有一件事我挺在意的」", null, "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "29"}, "CHAPTER 7-2", null, null], [7070, "美津叶", "「什么事？」", "miz424_004.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "06"}, "CHAPTER 7-2", null, null], [7071, "将臣", "「虽然大部分都是我的猜测——」", null, "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "06"}, "CHAPTER 7-2", null, null], [7072, "", "在梦境快结束的时候，我感觉祟神可能也在跟我们一同观看梦境。", null, "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "06"}, "CHAPTER 7-2", null, null], [7073, "", "为慎重起见，我把这件事也告诉大家了。", null, "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "06"}, "CHAPTER 7-2", null, null], [7074, "将臣", "「当然，这也可能只是我的错觉」", null, "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "06"}, "CHAPTER 7-2", null, null], [7075, "蕾娜", "「这样啊，我都没有注意到」", "len424_027.ogg", "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "20"}, "CHAPTER 7-2", null, null], [7076, "", "因为那个时候我的意识已经从武士的身体里离开了，但蕾娜还在女神大人里面。", null, "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "20"}, "CHAPTER 7-2", null, null], [7077, "将臣", "「不过既然蕾娜都没注意到，那可能只是我想太多了？」", null, "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "20"}, "CHAPTER 7-2", null, null], [7078, "丛雨", "「不！主人，确实有这种可能」", "mur424_001.ogg", "街_診療所a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "11"}, "CHAPTER 7-2", null, null], [7079, "将臣", "「小雨？」", null, "街_診療所a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "11"}, "CHAPTER 7-2", null, null], [7080, "美津叶", "「列支敦瑙尔小姐，我记得你最开始被它操控的时候」", "miz424_005.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "05"}, "CHAPTER 7-2", null, null], [7081, "美津叶", "「它是不是让你做了个梦到你家人的梦？」", "miz424_006.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "01"}, "CHAPTER 7-2", null, null], [7082, "蕾娜", "「是的」", "len424_028.ogg", "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "30"}, "CHAPTER 7-2", null, null], [7083, "美津叶", "「这说明祟神也拥有让别人做梦的能力」", "miz424_007.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "05"}, "CHAPTER 7-2", null, null], [7084, "美津叶", "「既然如此，它能侵入宿体的梦境之中，也没有什么奇怪的」", "miz424_008.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "29"}, "CHAPTER 7-2", null, null], [7085, "丛雨", "「驹川说的没错。它万一在关键时刻出来捣乱，那可就麻烦了」", "mur424_002.ogg", "街_診療所a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "16"}, "CHAPTER 7-2", null, null], [7086, "安晴", "「但是这么说的话，也可能是祟神自己把宿体的记忆展现给他们看的」", "yas424_003.ogg", "街_診療所a", "bgm39.opus", {"char": "安晴", "file": "安晴.stand", "dress": "私服", "face": "06"}, "CHAPTER 7-2", null, null], [7087, "美津叶", "「是的，这点我也考虑到了……」", "miz424_009.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "33"}, "CHAPTER 7-2", null, null], [7088, "将臣", "「问题是，它为什么要这么做对吧？」", null, "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "33"}, "CHAPTER 7-2", null, null], [7089, "", "必须先搞清楚这一点，才能知道它会不会出来捣乱，以及我们应该采取什么对策。", null, "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "33"}, "CHAPTER 7-2", null, null], [7090, "蕾娜", "「它会不会是……有什么事情想要告诉我们呢？」", "len424_029.ogg", "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "23"}, "CHAPTER 7-2", null, null], [7091, "将臣", "「你的意思是……？」", null, "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "23"}, "CHAPTER 7-2", null, null], [7092, "美津叶", "「自古以来，神佛经常会通过梦境向凡人传递信息」", "miz424_010.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "16"}, "CHAPTER 7-2", null, null], [7093, "美津叶", "「但也可能单纯是因为你们的关系有了进展，所以才能成功读取到人神恋的记忆片段」", "miz424_011.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "05"}, "CHAPTER 7-2", null, null], [7094, "丛雨", "「但本座不认为祟神会把蕾娜祖上的记忆也拿出来给你们看」", "mur424_003.ogg", "街_診療所a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "40"}, "CHAPTER 7-2", null, null], [7095, "丛雨", "「至少，这一切并非全都是祟神计划的」", "mur424_004.ogg", "街_診療所a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "11"}, "CHAPTER 7-2", null, null], [7096, "蕾娜", "「喔，可是……」", "len424_030.ogg", "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 7-2", null, null], [7097, "将臣", "「我认为蕾娜说的有道理，虽然大部分是偶然，但祟神自己应该也有想要向我们传达的事情」", null, "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 7-2", null, null], [7098, "蕾娜", "「将臣……你也这么觉得啊！」", "len424_031.ogg", "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 7-2", null, null], [7099, "安晴", "「各位，现在应该还不用急着下结论吧？」", "yas424_004.ogg", "街_診療所a", "bgm39.opus", {"char": "安晴", "file": "安晴.stand", "dress": "私服", "face": "10"}, "CHAPTER 7-2", null, null], [7100, "安晴", "「虽然我说这种话可能不太合适」", "yas424_005.ogg", "街_診療所a", "bgm39.opus", {"char": "安晴", "file": "安晴.stand", "dress": "私服", "face": "14"}, "CHAPTER 7-2", null, null], [7101, "美津叶", "「不，您说得很对」", "miz424_012.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "22"}, "CHAPTER 7-2", null, null], [7102, "美津叶", "「我也觉得，与其思考不知道的事情，还不如商量些力所能及的应对方法」", "miz424_013.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "29"}, "CHAPTER 7-2", null, null], [7103, "将臣", "「我记得您之前说，是有办法平息祟神的怒火的？」", null, "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "29"}, "CHAPTER 7-2", null, null], [7104, "美津叶", "「嗯，荒魂是通过宿体来发挥力量的」", "miz424_014.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "01"}, "CHAPTER 7-2", null, null], [7105, "美津叶", "「那么只要有办法消除留在宿体上的愤怒和憎恶就行了」", "miz424_015.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "29"}, "CHAPTER 7-2", null, null], [7106, "", "消除愤怒和憎恶。这么一说，确实感觉很简单。", null, "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "29"}, "CHAPTER 7-2", null, null], [7107, "蕾娜", "「也就是说……只要跟它和好就行了吧？」", "len424_032.ogg", "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "34"}, "CHAPTER 7-2", null, null], [7108, "美津叶", "「也可以这么说」", "miz424_016.ogg", "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "34"}, "CHAPTER 7-2", null, null], [7109, "美津叶", "「但是，我刚才也说了，还是要先等你们做梦才行」", "miz424_017.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "21"}, "CHAPTER 7-2", null, null], [7110, "将臣", "「啊，确实」", null, "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "21"}, "CHAPTER 7-2", null, null], [7111, "美津叶", "「我说的应对方法，指的是你们没办法从梦境中返回时的应急方案」", "miz424_018.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "28"}, "CHAPTER 7-2", null, null], [7112, "丛雨", "「如果你们入梦太深，是完全有可能无法返回的」", "mur424_005.ogg", "街_診療所a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "16"}, "CHAPTER 7-2", null, null], [7113, "丛雨", "「之前本座应该也跟你们说过，如果吃了梦里的食物，就再也回不来了」", "mur424_006.ogg", "街_診療所a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "39"}, "CHAPTER 7-2", null, null], [7114, "将臣", "「哈哈，我做梦做习惯了，都忘了还有这事」", null, "街_診療所a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "39"}, "CHAPTER 7-2", null, null], [7115, "蕾娜", "「没事啦，将臣，其实我也忘记了！」", "len424_033.ogg", "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "16"}, "CHAPTER 7-2", null, null], [7116, "丛雨", "「你们这样可不行啊」", "mur424_007.ogg", "街_診療所a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "30"}, "CHAPTER 7-2", null, null], [7117, "", "真是无言以对。", null, "街_診療所a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "30"}, "CHAPTER 7-2", null, null], [7118, "", "外公说我已经做好了思想准备，这是不是太高估我了啊？", null, "街_診療所a", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "30"}, "CHAPTER 7-2", null, null], [7119, "美津叶", "「总之，我会给你们准备个救生索，以备不时之需」", "miz424_019.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "05"}, "CHAPTER 7-2", null, null], [7120, "美津叶", "「不过应该会花上一些时间」", "miz424_020.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "26"}, "CHAPTER 7-2", null, null], [7121, "安晴", "「啊，这件事你放心，我也会帮忙的」", "yas424_006.ogg", "街_診療所a", "bgm39.opus", {"char": "安晴", "file": "安晴.stand", "dress": "私服", "face": "01"}, "CHAPTER 7-2", null, null], [7122, "将臣", "「安晴叔叔也要帮忙吗？」", null, "街_診療所a", "bgm39.opus", {"char": "安晴", "file": "安晴.stand", "dress": "私服", "face": "01"}, "CHAPTER 7-2", null, null], [7123, "安晴", "「因为真的很缺人，所以连我这种三脚猫功夫的人也得来帮帮忙才行」", "yas424_007.ogg", "街_診療所a", "bgm39.opus", {"char": "安晴", "file": "安晴.stand", "dress": "私服", "face": "14"}, "CHAPTER 7-2", null, null], [7124, "美津叶", "「您说笑了，我感谢您还来不及呢」", "miz424_021.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "02"}, "CHAPTER 7-2", null, null], [7125, "美津叶", "「毕竟现在最重要的是尽快完成，要是晚了可就没意义了」", "miz424_022.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "23"}, "CHAPTER 7-2", null, null], [7126, "", "驹川大夫在山中跑来跑去寻找传说就已经够辛苦了。", null, "街_診療所a", "bgm39.opus", null, "CHAPTER 7-2", null, null], [7127, "", "但她还打算继续为我们做更多的事。", null, "街_診療所a", "bgm39.opus", null, "CHAPTER 7-2", null, null], [7128, "", "一想到这里，就特别感谢这些热心肠的大人们。", null, "街_診療所a", "bgm39.opus", null, "CHAPTER 7-2", null, null], [7129, "蕾娜", "「那个，驹川大夫，我知道您很忙，但可以跟您说一些事吗？」", "len424_034.ogg", "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "30"}, "CHAPTER 7-2", null, null], [7130, "美津叶", "「怎么了？有什么事要商量的话，就先说说看吧，我或许能帮上忙」", "miz424_023.ogg", "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "30"}, "CHAPTER 7-2", null, null], [7131, "蕾娜", "「嗯，谢谢您……是这样的，我想拜托您一件事！」", "len424_035.ogg", "街_診療所a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "15"}, "CHAPTER 7-2", null, null], [7132, "美津叶", "「……嗯？」", "miz424_024.ogg", "街_診療所a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "06"}, "CHAPTER 7-2", null, null], [7133, "", "在那之后，她们聊了许久。", null, "街_診療所a", "bgm39.opus", null, "CHAPTER 7-2", null, null], [7134, "", "看样子，蕾娜说的应该是她之前就有的那个想法。今早在外公面前她也提到了。", null, "街_診療所a", "bgm39.opus", null, "CHAPTER 7-2", null, null], [7135, "", "等她们说完的时候，太阳已经下山了。", null, "街_雰囲気b", "bgm35.opus", null, "CHAPTER 7-2", null, null], [7136, "蕾娜", "「抱歉，我说得太久，让你们久等了」", "len424_036.ogg", "街_雰囲気b", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "21"}, "CHAPTER 7-2", null, null], [7137, "将臣", "「没事，反正我现在除了做梦之外也没别的事可做了」", null, "街_雰囲気b", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "21"}, "CHAPTER 7-2", null, null], [7138, "丛雨", "「蕾娜，本座真的是佩服你啊」", "mur424_008.ogg", "街_雰囲気b", "bgm35.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "29"}, "CHAPTER 7-2", null, null], [7139, "丛雨", "「也许正因为你之前没有参加战斗，所以才能想出这种方法」", "mur424_009.ogg", "街_雰囲気b", "bgm35.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "03"}, "CHAPTER 7-2", null, null], [7140, "蕾娜", "「哈哈，现在还不知道能不能成功呢」", "len424_037.ogg", "街_雰囲気b", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 7-2", null, null], [7141, "", "这时，我的手机响了。", null, "街_雰囲気b", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 7-2", null, null], [7142, "将臣", "「咦？是常陆打来的」", null, "街_雰囲気b", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 7-2", null, null], [7143, "蕾娜", "「是茉子吗？发生什么事情了吗？」", "len424_038.ogg", "街_雰囲気b", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "24"}, "CHAPTER 7-2", null, null], [7144, "", "她现在应该和朝武在一起吧？", null, "街_雰囲気b", "bgm35.opus", null, "CHAPTER 7-2", null, null], [7145, "", "也正因此，这几天我都没怎么跟常陆说上话。总之，先接电话吧。", null, "街_雰囲気b", "bgm35.opus", null, "CHAPTER 7-2", null, null], [7146, "茉子", "『是有地吗？你的事情已经办完了吗？』", "mak424_001.ogg", "街_雰囲気b", "bgm35.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "26"}, "CHAPTER 7-2", null, null], [7147, "将臣", "「嗯，都办完了……怎么了，说话那么小声？」", null, "街_雰囲気b", "bgm35.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "26"}, "CHAPTER 7-2", null, null], [7148, "茉子", "『嗯，是这样的，我希望你现在来一个地方』", "mak424_002.ogg", "街_雰囲気b", "bgm35.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "34"}, "CHAPTER 7-2", null, null], [7149, "将臣", "「就这点事？没问题啊」", null, "街_雰囲気b", "bgm35.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "34"}, "CHAPTER 7-2", null, null], [7150, "茉子", "『噗，那你来的时候注意尽量保持安静，不要发出声音哦』", "mak424_003.ogg", "街_雰囲気b", "bgm35.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "48"}, "CHAPTER 7-2", null, null], [7151, "茉子", "『有些东西想悄悄给你看一看』", "mak424_004.ogg", "街_雰囲気b", "bgm35.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "26"}, "CHAPTER 7-2", null, null], [7152, "", "我差不多能想到是怎么一回事了……不过真的是我想的那样吗？", null, "街_雰囲気b", "bgm35.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "26"}, "CHAPTER 7-2", null, null], [7153, "", "我按照常陆的指示，蹑手蹑脚地穿过了神社院内。", null, "神社_境内b", "bgm35.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "26"}, "CHAPTER 7-2", null, null], [7154, "丛雨", "「蕾娜，注意别踩到碎石地」", "mur424_010.ogg", "神社_境内b", "bgm35.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "01"}, "CHAPTER 7-2", null, null], [7155, "蕾娜", "「好的，是不是要像忍者那样呀，小雨？」", "len424_039.ogg", "神社_境内b", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "12"}, "CHAPTER 7-2", null, null], [7156, "将臣", "「……你们还是跟过来了啊」", null, "神社_境内b", "bgm35.opus", null, "CHAPTER 7-2", null, null], [7157, "", "也罢，反正茉子也同意了。", null, "神社_境内b", "bgm35.opus", null, "CHAPTER 7-2", null, null], [7158, "蕾娜", "「将臣，里面好像有人在说话」", "len424_040.ogg", "神社_境内b", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "09"}, "CHAPTER 7-2", null, null], [7159, "将臣", "「嗯，好像是的」", null, "神社_境内b", "bgm35.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "09"}, "CHAPTER 7-2", null, null], [7160, "", "常陆和朝武果然在屋子里。", null, "空_夕空", "bgm35.opus", null, "CHAPTER 7-2", null, null], [7161, "", "常陆大概是一开始就把百叶门拉开了一部分。", null, "空_夕空", "bgm35.opus", null, "CHAPTER 7-2", null, null], [7162, "", "我刚要往里偷看，另外两个人也把头架在了我的脑袋上。", null, "空_夕空", "bgm35.opus", null, "CHAPTER 7-2", null, null], [7163, "", "朝武似乎是刚刚跳完神乐舞。", null, "神社_神社内b", "bgm39.opus", null, "CHAPTER 7-2", null, null], [7164, "", "我记得之前有人跟我说过，这神乐舞也可以起到祓除污秽的作用。", null, "神社_神社内b", "bgm39.opus", null, "CHAPTER 7-2", null, null], [7165, "", "虽然不能消灭祟神，但是控制祟神现身的频率还是没问题的。", null, "神社_神社内b", "bgm39.opus", null, "CHAPTER 7-2", null, null], [7166, "", "虽然从那以后祟神没有再出现过，但朝武依然在坚持每天献舞。", null, "神社_神社内b", "bgm39.opus", null, "CHAPTER 7-2", null, null], [7167, "芳乃", "「呼…………好」", "yos424_003.ogg", "神社_神社内b", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "16"}, "CHAPTER 7-2", null, null], [7168, "将臣", "「（哎？）」", null, "神社_神社内b", "bgm39.opus", null, "CHAPTER 7-2", null, null], [7169, "丛雨", "「（怪了，她打算再跳一次吗？）」", "mur424_011.ogg", "神社_神社内b", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "17"}, "CHAPTER 7-2", null, null], [7170, "", "只见朝武摆正了鉾铃，看上去好像是真的打算再跳一次。", null, "神社_神社内b", "bgm39.opus", null, "CHAPTER 7-2", null, null], [7171, "将臣", "「（难道刚才只是练习吗？）」", null, "神社_神社内b", "bgm39.opus", null, "CHAPTER 7-2", null, null], [7172, "蕾娜", "「（可是……芳乃好像已经满头大汗了啊？）」", "len424_041.ogg", "神社_神社内b", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 7-2", null, null], [7173, "", "确实，她就像是刚结束了疯狂的训练一样，被汗水濡湿的头发都粘在了额头上。", null, "神社_神社内b", "bgm39.opus", null, "CHAPTER 7-2", null, null], [7174, "", "事到如今还做到这个地步，确实稍微有点奇怪。", null, "神社_神社内b", "bgm39.opus", null, "CHAPTER 7-2", null, null], [7175, "茉子", "「芳乃大人，我觉得差不多可以了吧」", "mak424_005.ogg", "神社_神社内b", "bgm39.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "29"}, "CHAPTER 7-2", null, null], [7176, "茉子", "「您今天献舞的次数已经是平时的三倍了」", "mak424_006.ogg", "神社_神社内b", "bgm39.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "01"}, "CHAPTER 7-2", null, null], [7177, "", "什么，三倍！？", null, "神社_神社内b", "bgm39.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "01"}, "CHAPTER 7-2", null, null], [7178, "", "身边的蕾娜和小雨都吓了一跳。", null, "神社_神社内b", "bgm39.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "01"}, "CHAPTER 7-2", null, null], [7179, "芳乃", "「……没事，是我自己想要跳舞」", "yos424_004.ogg", "神社_神社内b", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "22"}, "CHAPTER 7-2", null, null], [7180, "茉子", "「但是，这和单纯跳舞不一样，您这样是很消耗精力的吧？」", "mak424_007.ogg", "神社_神社内b", "bgm39.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "18"}, "CHAPTER 7-2", null, null], [7181, "茉子", "「说实话，献舞也不是次数越多越好，我觉得继续献舞也没有什么意义了」", "mak424_008.ogg", "神社_神社内b", "bgm39.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "34"}, "CHAPTER 7-2", null, null], [7182, "芳乃", "「就算没有太大的意义，但只要有那么一点点意义，我就愿意跳」", "yos424_005.ogg", "神社_神社内b", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "07"}, "CHAPTER 7-2", null, null], [7183, "茉子", "「您这到底是为了什么？」", "mak424_009.ogg", "神社_神社内b", "bgm39.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "01"}, "CHAPTER 7-2", null, null], [7184, "芳乃", "「……？茉子，我之前应该是跟你说过的吧？」", "yos424_006.ogg", "神社_神社内b", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "41"}, "CHAPTER 7-2", null, null], [7185, "茉子", "「是的，但是我想再确认一次」", "mak424_010.ogg", "神社_神社内b", "bgm39.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "01"}, "CHAPTER 7-2", null, null], [7186, "", "常陆难道是为了让我们听这些？", null, "神社_神社内b", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "41"}, "CHAPTER 7-2", null, null], [7187, "芳乃", "「不要让我说那么多次啊」", "yos424_007.ogg", "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "16"}, "CHAPTER 7-2", null, null], [7188, "芳乃", "「……本来这个诅咒就是针对我的」", "yos424_008.ogg", "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "13"}, "CHAPTER 7-2", null, null], [7189, "芳乃", "「但我却把蕾娜和有地也牵连了进来，给他们添了麻烦……而且现在的我还什么都做不到」", "yos424_009.ogg", "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "05"}, "CHAPTER 7-2", null, null], [7190, "芳乃", "「他们有事情不告诉我，可能也是理所当然的……」", "yos424_010.ogg", "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "43"}, "CHAPTER 7-2", null, null], [7191, "", "没想到朝武居然会这么自责。", null, "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "43"}, "CHAPTER 7-2", null, null], [7192, "茉子", "「我明白您的心情，但您最近是不是对他们有点太冷淡了？」", "mak424_011.ogg", "神社_神社内b", "bgm09.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "34"}, "CHAPTER 7-2", null, null], [7193, "芳乃", "「……我也无奈啊」", "yos424_011.ogg", "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "31"}, "CHAPTER 7-2", null, null], [7194, "茉子", "「嗯」", "mak424_012.ogg", "神社_神社内b", "bgm09.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "01"}, "CHAPTER 7-2", null, null], [7195, "芳乃", "「你让我用什么表情面对他们？」", "yos424_012.ogg", "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "25"}, "CHAPTER 7-2", null, null], [7196, "芳乃", "「有地明明是被我牵连进来的，却每天从早到晚都拼命练习剑道，就为了帮我」", "yos424_013.ogg", "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "36"}, "CHAPTER 7-2", null, null], [7197, "芳乃", "「还有谁能做到他这个地步？」", "yos424_014.ogg", "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "30"}, "CHAPTER 7-2", null, null], [7198, "茉子", "「这个，还真不好说。恐怕是没有其他人了吧」", "mak424_013.ogg", "神社_神社内b", "bgm09.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "44"}, "CHAPTER 7-2", null, null], [7199, "芳乃", "「蕾娜……是从我出生到现在第一个邀请我参加睡衣派对的人」", "yos424_015.ogg", "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "45"}, "CHAPTER 7-2", null, null], [7200, "芳乃", "「虽然我玩到一半就不得不回来了」", "yos424_016.ogg", "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "29"}, "CHAPTER 7-2", null, null], [7201, "芳乃", "「不过那一天真的很开心，很快乐……我可能从来没体验过那么幸福的一天」", "yos424_017.ogg", "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "22"}, "CHAPTER 7-2", null, null], [7202, "蕾娜", "「（芳乃……）」", "len424_042.ogg", "神社_神社内b", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "29"}, "CHAPTER 7-2", null, null], [7203, "", "睡衣派对那天，我记得她是为了履行每日献舞的职责，玩到一半就回去了。", null, "神社_神社内b", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "29"}, "CHAPTER 7-2", null, null], [7204, "芳乃", "「可是，昨天早上……我听到了」", "yos424_018.ogg", "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "46"}, "CHAPTER 7-2", null, null], [7205, "茉子", "「嗯，我记得」", "mak424_014.ogg", "神社_神社内b", "bgm09.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "01"}, "CHAPTER 7-2", null, null], [7206, "茉子", "「您是听到安晴大人说到“根本不敢告诉女儿”，才停下脚步的吧？」", "mak424_015.ogg", "神社_神社内b", "bgm09.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "03"}, "CHAPTER 7-2", null, null], [7207, "芳乃", "「…………嗯」", "yos424_019.ogg", "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "01"}, "CHAPTER 7-2", null, null], [7208, "", "果然那个时候她也在。", null, "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "01"}, "CHAPTER 7-2", null, null], [7209, "芳乃", "「蕾娜她说得就像理所当然的事情一样」", "yos424_020.ogg", "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "13"}, "CHAPTER 7-2", null, null], [7210, "芳乃", "「她说不要担心自己，只要是为了朋友，这点危险不算什么」", "yos424_021.ogg", "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "13"}, "CHAPTER 7-2", null, null], [7211, "芳乃", "「……照理说，我应该好好感谢她才对」", "yos424_022.ogg", "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "07"}, "CHAPTER 7-2", null, null], [7212, "芳乃", "「可我却什么都做不到……！」", "yos424_023.ogg", "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "19"}, "CHAPTER 7-2", null, null], [7213, "茉子", "「所以您就来这里献舞吗？」", "mak424_016.ogg", "神社_神社内b", "bgm09.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "26"}, "CHAPTER 7-2", null, null], [7214, "芳乃", "「就是这样」", "yos424_024.ogg", "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "23"}, "CHAPTER 7-2", null, null], [7215, "芳乃", "「污秽变强的话，祟神的力量也会增强的吧？」", "yos424_025.ogg", "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "33"}, "CHAPTER 7-2", null, null], [7216, "茉子", "「但是不管您献多少次舞，只靠献舞也是没法祓除所有污秽的」", "mak424_017.ogg", "神社_神社内b", "bgm09.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "41"}, "CHAPTER 7-2", null, null], [7217, "芳乃", "「……这我当然知道」", "yos424_026.ogg", "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "37"}, "CHAPTER 7-2", null, null], [7218, "芳乃", "「但是，哪怕根本不知道有没有效果，哪怕效果非常非常小」", "yos424_027.ogg", "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "22"}, "CHAPTER 7-2", null, null], [7219, "芳乃", "「只要我能做到，我就愿意尽自己的一份力量！」", "yos424_028.ogg", "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "25"}, "CHAPTER 7-2", null, null], [7220, "茉子", "「为什么您要做到这个地步？」", "mak424_018.ogg", "神社_神社内b", "bgm09.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "01"}, "CHAPTER 7-2", null, null], [7221, "芳乃", "「……这种事，还需要问吗」", "yos424_029.ogg", "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "22"}, "CHAPTER 7-2", null, null], [7222, "茉子", "「我明白，但我还是想听听您的决心」", "mak424_019.ogg", "神社_神社内b", "bgm09.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "44"}, "CHAPTER 7-2", null, null], [7223, "芳乃", "「真是的……其实有的时候，我也不知道应该怎么跟大家相处比较好」", "yos424_030.ogg", "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "28"}, "CHAPTER 7-2", null, null], [7224, "芳乃", "「也不知道这么说你能不能理解……你想想，我们毕竟是朋友啊」", "yos424_031.ogg", "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "25"}, "CHAPTER 7-2", null, null], [7225, "茉子", "「嗯」", "mak424_020.ogg", "神社_神社内b", "bgm09.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "01"}, "CHAPTER 7-2", null, null], [7226, "芳乃", "「他们居然背着我偷偷聚在一起说事，我心里肯定有点不是滋味」", "yos424_032.ogg", "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "11"}, "CHAPTER 7-2", null, null], [7227, "芳乃", "「可我也想给大家帮忙啊！因为……」", "yos424_033.ogg", "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "09"}, "CHAPTER 7-2", null, null], [7228, "芳乃", "「因为我们是朋友啊」", "yos424_034.ogg", "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "06"}, "CHAPTER 7-2", null, null], [7229, "", "蕾娜终究没能忍住。她一把推开百叶门，冲到了芳乃跟前。", null, "神社_神社内b", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "23"}, "CHAPTER 7-2", null, null], [7230, "芳乃", "「哎！？蕾娜？有地和丛雨大人怎么也在……\\n呀！？」", "yos424_035.ogg", "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "25"}, "CHAPTER 7-2", null, null], [7231, "蕾娜", "「芳乃！」", "len424_043.ogg", "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "05"}, "CHAPTER 7-2", null, null], [7232, "", "蕾娜使出了全身的力气，紧紧地抱住了朝武。", null, "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "05"}, "CHAPTER 7-2", null, null], [7233, "", "我本来以为自己明白朝武的决心。", null, "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "05"}, "CHAPTER 7-2", null, null], [7234, "", "但是……但是，尽管如此，我心里还是非常感动。", null, "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "05"}, "CHAPTER 7-2", null, null], [7235, "蕾娜", "「谢谢你，芳乃……最难受的人明明是你……真的谢谢你」", "len424_044.ogg", "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "05"}, "CHAPTER 7-2", null, null], [7236, "芳乃", "「哪、哪里的话，受苦的明明是你！都是我连累了你……」", "yos424_036.ogg", "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "07"}, "CHAPTER 7-2", null, null], [7237, "芳乃", "「不过，你们怎么都来了？难道是茉子……！？」", "yos424_037.ogg", "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "25"}, "CHAPTER 7-2", null, null], [7238, "茉子", "「哈哈，我也不知道是怎么回事」", "mak424_021.ogg", "神社_神社内b", "bgm09.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "27"}, "CHAPTER 7-2", null, null], [7239, "丛雨", "「现在装傻也没用了，茉子」", "mur424_012.ogg", "神社_神社内b", "bgm09.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "28"}, "CHAPTER 7-2", null, null], [7240, "茉子", "「我知道，但还是要姑且装一装呀」", "mak424_022.ogg", "神社_神社内b", "bgm09.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "01"}, "CHAPTER 7-2", null, null], [7241, "茉子", "「要不然芳乃大人刚才一个人在那说了那么多，岂不是特别没面子」", "mak424_023.ogg", "神社_神社内b", "bgm09.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "44"}, "CHAPTER 7-2", null, null], [7242, "芳乃", "「茉、茉子！如果你真的在意我的面子，那你为什么要……」", "yos424_038.ogg", "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "08h"}, "CHAPTER 7-2", null, null], [7243, "蕾娜", "「没关系的，芳乃」", "len424_045.ogg", "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "08h"}, "CHAPTER 7-2", null, null], [7244, "将臣", "「你一直都在悄悄增加献舞次数吗？」", null, "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "08h"}, "CHAPTER 7-2", null, null], [7245, "将臣", "「难道是自从碎片被蕾娜吸收之后，你就开始了？」", null, "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "08h"}, "CHAPTER 7-2", null, null], [7246, "", "这是我的猜测，毕竟睡衣派对时她也提前回来了。", null, "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "08h"}, "CHAPTER 7-2", null, null], [7247, "芳乃", "「这个……献舞是我一直在做的事情，我只不过是把量增加了一点而已」", "yos424_039.ogg", "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "16"}, "CHAPTER 7-2", null, null], [7248, "芳乃", "「而且，你们不是也有事瞒着我吗？」", "yos424_040.ogg", "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "20"}, "CHAPTER 7-2", null, null], [7249, "芳乃", "「刚来的时候，你连特训的事都瞒着我们呢」", "yos424_041.ogg", "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "17"}, "CHAPTER 7-2", null, null], [7250, "蕾娜", "「噗，将臣确实没资格说芳乃」", "len424_046.ogg", "神社_神社内b", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 7-2", null, null], [7251, "将臣", "「算我输了」", null, "神社_神社内b", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 7-2", null, null], [7252, "", "真的是无法反驳。", null, "神社_神社内b", "bgm09.opus", null, "CHAPTER 7-2", null, null], [7253, "将臣", "「不过，我确实应该跟你道歉」", null, "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "22"}, "CHAPTER 7-2", null, null], [7254, "芳乃", "「什么？」", "yos424_042.ogg", "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "26"}, "CHAPTER 7-2", null, null], [7255, "将臣", "「这段时间我们每次商量事情都没叫上你们，还是挺过意不去的」", null, "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "26"}, "CHAPTER 7-2", null, null], [7256, "蕾娜", "「是的……其实我们并不是打算把你们排除在外」", "len424_047.ogg", "神社_神社内b", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "22"}, "CHAPTER 7-2", null, null], [7257, "将臣", "「主要是因为有很多事情还不确定，就怕告诉你们之后反而让你们心烦」", null, "神社_神社内b", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "22"}, "CHAPTER 7-2", null, null], [7258, "丛雨", "「不，这不是他们的错」", "mur424_013.ogg", "神社_神社内b", "bgm09.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "22"}, "CHAPTER 7-2", null, null], [7259, "丛雨", "「本座也是觉得瞒着你比较好，你不要怪他们」", "mur424_014.ogg", "神社_神社内b", "bgm09.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "30"}, "CHAPTER 7-2", null, null], [7260, "芳乃", "「你们不要这么说，我怎么会怪你们呢！」", "yos424_043.ogg", "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "25"}, "CHAPTER 7-2", null, null], [7261, "芳乃", "「我还怕你们生我的气呢，我自己都觉得我这几天态度太差了」", "yos424_044.ogg", "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "36"}, "CHAPTER 7-2", null, null], [7262, "将臣", "「放心啦，我们没生气」", null, "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "36"}, "CHAPTER 7-2", null, null], [7263, "蕾娜", "「将臣，小雨，现在我们应该可以把情况告诉她们了吧？」", "len424_048.ogg", "神社_神社内b", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 7-2", null, null], [7264, "蕾娜", "「我们下次做梦的时候，大概就能明白真相了」", "len424_049.ogg", "神社_神社内b", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "17"}, "CHAPTER 7-2", null, null], [7265, "丛雨", "「说的也是」", "mur424_015.ogg", "神社_神社内b", "bgm09.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "03"}, "CHAPTER 7-2", null, null], [7266, "芳乃", "「不用了！事到如今，就等事情全部弄明白之后再一起告诉我们吧」", "yos424_045.ogg", "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "42"}, "CHAPTER 7-2", null, null], [7267, "将臣", "「朝武，这样没关系吗？」", null, "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "42"}, "CHAPTER 7-2", null, null], [7268, "芳乃", "「怎么说呢，我觉得我也应该尊重大家的想法」", "yos424_046.ogg", "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "28"}, "CHAPTER 7-2", null, null], [7269, "芳乃", "「既然最关键的信息现在还不知道，那就还是等你们全部弄清了再告诉我吧」", "yos424_047.ogg", "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "29"}, "CHAPTER 7-2", null, null], [7270, "芳乃", "「要是现在就告诉我，我也只会干着急」", "yos424_048.ogg", "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "23"}, "CHAPTER 7-2", null, null], [7271, "茉子", "「嗯，毕竟你们都对我们保密到现在了」", "mak424_024.ogg", "神社_神社内b", "bgm09.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "29"}, "CHAPTER 7-2", null, null], [7272, "茉子", "「我也希望你们能把谜底留到最后」", "mak424_025.ogg", "神社_神社内b", "bgm09.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "26"}, "CHAPTER 7-2", null, null], [7273, "蕾娜", "「芳乃，茉子，谢谢你们」", "len424_050.ogg", "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "02"}, "CHAPTER 7-2", null, null], [7274, "芳乃", "「没关系的啦」", "yos424_049.ogg", "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "28"}, "CHAPTER 7-2", null, null], [7275, "芳乃", "「但是你们也不要忘记了，为了朋友，我们也是愿意两肋插刀的」", "yos424_050.ogg", "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "02"}, "CHAPTER 7-2", null, null], [7276, "", "没想到竟然能听到朋友对自己说出这些话。", null, "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "02"}, "CHAPTER 7-2", null, null], [7277, "", "还有比这更让人备受鼓舞的话语吗。", null, "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "02"}, "CHAPTER 7-2", null, null], [7278, "蕾娜", "「……嗯，我明白了」", "len424_051.ogg", "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "02"}, "CHAPTER 7-2", null, null], [7279, "蕾娜", "「那我希望你们以后就不要跟我们客气了，有什么困难尽管找我们就是！」", "len424_052.ogg", "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "02"}, "CHAPTER 7-2", null, null], [7280, "芳乃", "「嗯……明白了」", "yos424_051.ogg", "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "03"}, "CHAPTER 7-2", null, null], [7281, "芳乃", "「蕾娜，有地，我知道这话我早就该说了，我也知道我在拜托你们一件很危险的事」", "yos424_052.ogg", "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "16"}, "CHAPTER 7-2", null, null], [7282, "芳乃", "「但是为了终结诅咒，我需要你们，请助我们一臂之力吧」", "yos424_053.ogg", "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "35"}, "CHAPTER 7-2", null, null], [7283, "蕾娜", "「你就放心吧！」", "len424_053.ogg", "神社_神社内b", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "18"}, "CHAPTER 7-2", null, null], [7284, "", "蕾娜一把握住朝武的手。", null, "神社_神社内b", "bgm09.opus", null, "CHAPTER 7-2", null, null], [7285, "", "我也把手盖在了她们的手上。", null, "神社_神社内b", "bgm09.opus", null, "CHAPTER 7-2", null, null], [7286, "将臣", "「没错，这些话你确实早就该说了」", null, "神社_神社内b", "bgm09.opus", null, "CHAPTER 7-2", null, null], [7287, "茉子", "「是呀，别忘了还有我在」", "mak424_026.ogg", "神社_神社内b", "bgm09.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "24"}, "CHAPTER 7-2", null, null], [7288, "丛雨", "「当然了，本座也和你们在一起」", "mur424_016.ogg", "神社_神社内b", "bgm09.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "29"}, "CHAPTER 7-2", null, null], [7289, "", "常陆和小雨也把手盖了上来。", null, "神社_神社内b", "bgm09.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "29"}, "CHAPTER 7-2", null, null], [7290, "丛雨", "「虽然本座的手只能象征性地盖上来……」", "mur424_017.ogg", "神社_神社内b", "bgm09.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "22"}, "CHAPTER 7-2", null, null], [7291, "蕾娜", "「小雨你在说什么呢！来吧，你把手放在我和将臣的手之间」", "len424_054.ogg", "神社_神社内b", "bgm09.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "22"}, "CHAPTER 7-2", null, null], [7292, "", "蕾娜将另一只手盖在了大家的手上。", null, "神社_神社内b", "bgm09.opus", null, "CHAPTER 7-2", null, null], [7293, "", "紧接着，我也握着小雨的手盖在了蕾娜的手上。见状，朝武和常陆也伸出了另一只手。", null, "神社_神社内b", "bgm09.opus", null, "CHAPTER 7-2", null, null], [7294, "", "我们五个人紧紧地把手握在了一起。", null, "神社_神社内b", "bgm09.opus", null, "CHAPTER 7-2", null, null], [7295, "丛雨", "「喔，喔！能……能感觉到有人握着本座的手」", "mur424_018.ogg", "神社_神社内b", "bgm09.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "28"}, "CHAPTER 7-2", null, null], [7296, "丛雨", "「大家都握着本座的手……」", "mur424_019.ogg", "神社_神社内b", "bgm09.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "20"}, "CHAPTER 7-2", null, null], [7297, "将臣", "「这不是当然的吗？你也是我们最重要的朋友」", null, "神社_神社内b", "bgm09.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "20"}, "CHAPTER 7-2", null, null], [7298, "芳乃", "「是的，要是丛雨大人不在，根本无法想象要怎么跟诅咒对决」", "yos424_054.ogg", "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "25"}, "CHAPTER 7-2", null, null], [7299, "蕾娜", "「没错！」", "len424_055.ogg", "神社_神社内b", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "25"}, "CHAPTER 7-2", null, null], [7300, "丛雨", "「……嗯，最后一场大战马上就要来临了」", "mur424_020.ogg", "神社_神社内b", "bgm09.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "22"}, "CHAPTER 7-2", null, null], [7301, "茉子", "「嗯，只要别到最后让我们大跌眼镜就行」", "mak424_027.ogg", "神社_神社内b", "bgm09.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "35"}, "CHAPTER 7-2", null, null], [7302, "将臣", "「哈哈，要是真那样，还请多多包涵」", null, "神社_神社内b", "bgm09.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "35"}, "CHAPTER 7-2", null, null], [7303, "", "大家都轻声笑了起来。", null, "神社_神社内b", "bgm09.opus", null, "CHAPTER 7-2", null, null], [7304, "", "尽管大战将至，我们也能相互调笑。", null, "神社_神社内b", "bgm09.opus", null, "CHAPTER 7-2", null, null], [7305, "", "因为我们并不孤单。", null, "神社_神社内b", "bgm09.opus", null, "CHAPTER 7-2", null, null], [7306, "", "我想守护在场的每一个人。大家心里也都有着同样的想法。", null, "神社_神社内b", "bgm09.opus", null, "CHAPTER 7-2", null, null], [7307, "", "已经没有什么好怕的了。", null, "神社_神社内b", "bgm09.opus", null, "CHAPTER 7-2", null, null], [7308, "", "由于外公给蕾娜放了假，所以我决定今晚让蕾娜在我房间过夜。", null, "朝武_自室d", "bgm40.opus", null, "CHAPTER 7-2", null, null], [7309, "蕾娜", "「今晚我们就要在你的房间里进入梦乡了吗」", "len424_056.ogg", "朝武_自室d", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "25"}, "CHAPTER 7-2", null, null], [7310, "将臣", "「嗯，在这里就算出了什么事，大家也能立刻赶来帮忙」", null, "朝武_自室d", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "25"}, "CHAPTER 7-2", null, null], [7311, "", "所以我们应该可以放心地进入梦境。", null, "朝武_自室d", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "25"}, "CHAPTER 7-2", null, null], [7312, "蕾娜", "「是的……虽然也会感觉有点压力」", "len424_057.ogg", "朝武_自室d", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "27"}, "CHAPTER 7-2", null, null], [7313, "蕾娜", "「你觉得我们今晚能顺利地引出宿体的记忆吗？」", "len424_058.ogg", "朝武_自室d", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "29"}, "CHAPTER 7-2", null, null], [7314, "将臣", "「放心吧，有我在呢」", null, "朝武_自室d", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "29"}, "CHAPTER 7-2", null, null], [7315, "", "我静静地抱住蕾娜的肩膀。", null, "朝武_自室d", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "20"}, "CHAPTER 7-2", null, null], [7316, "", "轻轻地吻了吻她。", null, "朝武_自室d", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "20"}, "CHAPTER 7-2", null, null], [7317, "蕾娜", "「哈哈……将臣，你一直都是我的武士」", "len424_059.ogg", "朝武_自室d", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "27"}, "CHAPTER 7-2", null, null], [7318, "将臣", "「哎？怎么突然说这个？」", null, "朝武_自室d", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "27"}, "CHAPTER 7-2", null, null], [7319, "蕾娜", "「……你刚才的吻，告诉我你一点都不害怕」", "len424_060.ogg", "朝武_自室d", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "03"}, "CHAPTER 7-2", null, null], [7320, "将臣", "「确实，我现在感觉什么都不怕」", null, "朝武_自室d", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "03"}, "CHAPTER 7-2", null, null], [7321, "将臣", "「多亏了大家，我深受鼓舞」", null, "朝武_自室d", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "03"}, "CHAPTER 7-2", null, null], [7322, "蕾娜", "「嗯，但我其实很早之前就觉得你是我的武士了」", "len424_061.ogg", "朝武_自室d", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "02"}, "CHAPTER 7-2", null, null], [7323, "蕾娜", "「之前我被祟神操控的时候，你也毫不犹豫地来救我了」", "len424_062.ogg", "朝武_自室d", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "01"}, "CHAPTER 7-2", null, null], [7324, "将臣", "「当时主要是情况紧急，顾不上那么多了」", null, "朝武_自室d", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "01"}, "CHAPTER 7-2", null, null], [7325, "", "说实话，当时我其实吓得要死。", null, "朝武_自室d", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "01"}, "CHAPTER 7-2", null, null], [7326, "将臣", "「如果你真的觉得我是你的武士」", null, "朝武_自室d", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "01"}, "CHAPTER 7-2", null, null], [7327, "将臣", "「那一定是因为你每天都那么积极向上，所以才给了我勇气」", null, "朝武_自室d", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "01"}, "CHAPTER 7-2", null, null], [7328, "蕾娜", "「……是我给了你勇气？」", "len424_063.ogg", "朝武_自室d", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "20"}, "CHAPTER 7-2", null, null], [7329, "蕾娜", "「但我也从你那里获得了不少勇气」", "len424_064.ogg", "朝武_自室d", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "01"}, "CHAPTER 7-2", null, null], [7330, "蕾娜", "「正因为你一直在我身边，我才能这么有安全感」", "len424_065.ogg", "朝武_自室d", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "02"}, "CHAPTER 7-2", null, null], [7331, "蕾娜", "「虽然有时候也会感到不安……但你始终都陪在我身边」", "len424_066.ogg", "朝武_自室d", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "25"}, "CHAPTER 7-2", null, null], [7332, "将臣", "「蕾娜……嗯」", null, "朝武_自室d", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "25"}, "CHAPTER 7-2", null, null], [7333, "将臣", "「正因为我们在一起，所以我们才会变强」", null, "朝武_自室d", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "25"}, "CHAPTER 7-2", null, null], [7334, "蕾娜", "「是的，将臣……我也这么觉得」", "len424_067.ogg", "朝武_自室d", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "19"}, "CHAPTER 7-2", null, null], [7335, "", "蕾娜紧紧地抱住了我。", null, "朝武_自室d", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "19"}, "CHAPTER 7-2", null, null], [7336, "将臣", "「今晚我们就抱在一起睡吧」", null, "朝武_自室d", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "19"}, "CHAPTER 7-2", null, null], [7337, "蕾娜", "「噗……你不会突然色性大发吧？」", "len424_068.ogg", "朝武_自室d", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "25"}, "CHAPTER 7-2", null, null], [7338, "将臣", "「我、我会忍耐的」", null, "朝武_自室d", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "25"}, "CHAPTER 7-2", null, null], [7339, "蕾娜", "「开玩笑啦，就算色性大发也没关系的」", "len424_069.ogg", "朝武_自室d", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "19"}, "CHAPTER 7-2", null, null], [7340, "蕾娜", "「这样挺好的……我也想和你抱在一起睡一晚」", "len424_070.ogg", "朝武_自室d", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "03"}, "CHAPTER 7-2", null, null], [7341, "将臣", "「嗯……」", null, "朝武_自室d", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "03"}, "CHAPTER 7-2", null, null], [7342, "", "说罢，我和蕾娜钻进了同一床被子里。", null, "朝武_自室c", "bgm40.opus", null, "CHAPTER 7-2", null, null], [7343, "", "我们相互感受着彼此的温暖，直到坠入深深的梦乡……。", null, "朝武_自室c", "bgm40.opus", null, "CHAPTER 7-2", null, null], [7344, "", "——不久后，武士和他的妻子就孕育了新的生命。", null, "特殊_武家屋敷a", "bgm36.opus", null, "CHAPTER 7-3", null, null], [7345, "", "望着那渐渐鼓起的肚子，他们每一天都过得十分幸福。", null, "特殊_武家屋敷a", "bgm36.opus", null, "CHAPTER 7-3", null, null], [7346, "", "现在的武士看上去就像是完全忘记了女神大人一样。", null, "特殊_武家屋敷a", "bgm36.opus", null, "CHAPTER 7-3", null, null], [7347, "", "而女神大人也只是在远处静静地看着他们。只要能看到他幸福，她就满足了。", null, "山_山の中２a", "bgm36.opus", null, "CHAPTER 7-3", null, null], [7348, "白狛", "「您这样，未免太过无欲无求了」", "srk425_001.ogg", "山_山の中２a", "bgm36.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 7-3", null, null], [7349, "丛云", "「说来也真是不可思议。一旦知道那不属于自己……欲望也会随之消失」", "lem425_001.ogg", "山_山の中２a", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "27"}, "CHAPTER 7-3", null, null], [7350, "丛云", "「欲望消失后，也就不必再意气用事了」", "lem425_002.ogg", "山_山の中２a", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "03"}, "CHAPTER 7-3", null, null], [7351, "丛云", "「现在望着身在远处的他……反而会觉得心里暖暖的，真是不可思议」", "lem425_003.ogg", "山_山の中２a", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "19"}, "CHAPTER 7-3", null, null], [7352, "丛云", "「只要能看到所爱之人获得幸福，我就满足了」", "lem425_004.ogg", "山_山の中２a", "bgm36.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "25"}, "CHAPTER 7-3", null, null], [7353, "白狛", "「是吗……」", "srk425_002.ogg", "山_山の中２a", "bgm36.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 7-3", null, null], [7354, "", "尽管如此，白狛心里还是觉得女神大人可能是在勉强自己。", null, "山_山の中２a", "bgm36.opus", null, "CHAPTER 7-3", null, null], [7355, "", "但现在的女神大人，已经完全不在乎这些了。", null, "山_山の中２a", "bgm36.opus", null, "CHAPTER 7-3", null, null], [7356, "", "只可惜，好日子并不长久。", null, "特殊_武家屋敷d", "bgm27.opus", null, "CHAPTER 7-3", null, null], [7357, "", "好不容易等来了分娩前的阵痛，最终却变成了非常严重的难产。", null, "特殊_武家屋敷d", "bgm27.opus", null, "CHAPTER 7-3", null, null], [7358, "将臣", "「什么，还没有生出来！？到底是怎么回事！」", null, "特殊_武家屋敷d", "bgm27.opus", null, "CHAPTER 7-3", null, null], [7359, "产婆", "「这个……孩子怎么也不出来」", "snb425_001.ogg", "特殊_武家屋敷d", "bgm27.opus", null, "CHAPTER 7-3", null, null], [7360, "将臣", "「怎么会这样……！」", null, "特殊_武家屋敷d", "bgm27.opus", null, "CHAPTER 7-3", null, null], [7361, "", "就这样，一夜过去，一夜又来。", null, "空_青空", "bgm27.opus", null, "CHAPTER 7-3", null, null], [7362, "", "孩子依然没有从母亲的肚子里生出来。", null, "空_夜空", "bgm27.opus", null, "CHAPTER 7-3", null, null], [7363, "", "如果是现代，还能用剖腹产之类的方法。", null, "空_夜空", "bgm27.opus", null, "CHAPTER 7-3", null, null], [7364, "", "但是在那个时代，每十位女性中就有一位因不孕而烦恼。", null, "空_夜空", "bgm27.opus", null, "CHAPTER 7-3", null, null], [7365, "", "每十位女性中……就有一位会死于难产。", null, "空_夜空", "bgm27.opus", null, "CHAPTER 7-3", null, null], [7366, "", "被剧烈的阵痛连续折磨两天的母亲，已经快要不行了。", null, "山_山の中２c", "bgm27.opus", null, "CHAPTER 7-3", null, null], [7367, "", "肚子里的孩子自然也是有危险的。", null, "山_山の中２c", "bgm27.opus", null, "CHAPTER 7-3", null, null], [7368, "", "再这样下去，很可能会母子一同丧命。", null, "山_山の中２c", "bgm27.opus", null, "CHAPTER 7-3", null, null], [7369, "白狛", "「两天都没生出来，这多半是活不成了」", "srk425_003.ogg", "山_山の中２c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 7-3", null, null], [7370, "白狛", "「她孩子的魂魄恐怕是被魑魅魍魉勾住了」", "srk425_004.ogg", "山_山の中２c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 7-3", null, null], [7371, "丛云", "「……果然如此」", "lem425_005.ogg", "山_山の中２c", "bgm08.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "14"}, "CHAPTER 7-3", null, null], [7372, "", "这个国家之所以有七五三，也是由于人们都认为幼儿七岁之前都归神灵所有。", null, "山_山の中２c", "bgm08.opus", null, "CHAPTER 7-3", null, null], [7373, "", "但是神灵之中也有住在黄泉之国的恶神，他们会把中意的孩子勾去自己的世界里。", null, "山_山の中２c", "bgm08.opus", null, "CHAPTER 7-3", null, null], [7374, "", "现在，武士的孩子之所以无法降临人间，多半也是因为魂魄被困在了阴间。", null, "山_山の中２c", "bgm08.opus", null, "CHAPTER 7-3", null, null], [7375, "丛云", "「只要将禁锢魂魄的枷锁斩断，孩子就能从黄泉来到人间了」", "lem425_006.ogg", "山_山の中２c", "bgm08.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "23"}, "CHAPTER 7-3", null, null], [7376, "丛云", "「我要去给他托梦，告诉他方法，这样说不定就有救了」", "lem425_007.ogg", "山_山の中２c", "bgm08.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "08"}, "CHAPTER 7-3", null, null], [7377, "白狛", "「什么，姐姐大人！？您在开什么玩笑」", "srk425_005.ogg", "山_山の中２c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 7-3", null, null], [7378, "", "白狛的叫声，听上去就像悲痛的呐喊。", null, "山_山の中２c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 7-3", null, null], [7379, "白狛", "「尚未出世的孩子，那可是黄泉之神的所有物！」", "srk425_006.ogg", "山_山の中２c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 7-3", null, null], [7380, "白狛", "「而且黄泉之神的地位比我们更高，您若是出手相救，必定会遭天罚！」", "srk425_007.ogg", "山_山の中２c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 7-3", null, null], [7381, "丛云", "「谢谢你，小狛……」", "lem425_008.ogg", "山_山の中２c", "bgm08.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "19"}, "CHAPTER 7-3", null, null], [7382, "", "女神露出了温柔的笑容，摸了摸白狛的头。", null, "山_山の中２c", "bgm08.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "19"}, "CHAPTER 7-3", null, null], [7383, "", "她的神情，已经说明了她的决心。", null, "山_山の中２c", "bgm08.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "19"}, "CHAPTER 7-3", null, null], [7384, "白狛", "「姐姐大人……万万不可！此事真的万万不可」", "srk425_008.ogg", "山_山の中２c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 7-3", null, null], [7385, "白狛", "「我等身为一方神灵，要是侵犯了诸神的天理，就再也……」", "srk425_009.ogg", "山_山の中２c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 7-3", null, null], [7386, "丛云", "「我明白」", "lem425_009.ogg", "山_山の中２c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 7-3", null, null], [7387, "丛云", "「对不起，我总是让你担心」", "lem425_010.ogg", "山_山の中２c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 7-3", null, null], [7388, "白狛", "「请不要这么做……区区凡人，区区凡人的命运随他去就是了！」", "srk425_010.ogg", "山_山の中２c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 7-3", null, null], [7389, "白狛", "「而且，那个男人还背叛了姐姐大人」", "srk425_011.ogg", "山_山の中２c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 7-3", null, null], [7390, "白狛", "「可姐姐大人……你却要为他做到这个地步，我……！我真的无法理解……」", "srk425_012.ogg", "山_山の中２c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 7-3", null, null], [7391, "丛云", "「白山狛男神」", "lem425_011.ogg", "山_山の中２c", "bgm08.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "14"}, "CHAPTER 7-3", null, null], [7392, "", "这是白狛正式的神名。", null, "山_山の中２c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 7-3", null, null], [7393, "", "在此之前，姐姐觉得他不成熟，只会用乳名叫他。这一天，是姐姐第一次这样称呼他。", null, "山_山の中２c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 7-3", null, null], [7394, "", "仿佛是在说，你已经能够独当一面了。", null, "山_山の中２c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 7-3", null, null], [7395, "", "就算没有我在，你也能活得好好的。", null, "山_山の中２c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 7-3", null, null], [7396, "丛云", "「如果有朝一日你也有了喜欢的人，你就会明白的」", "lem425_012.ogg", "山_山の中２c", "bgm08.opus", {"char": "レナ叢雲", "file": "レナ.stand", "dress": "女神", "face": "19"}, "CHAPTER 7-3", null, null], [7397, "将臣", "「生出来了……？生出来了吗！？」", null, "特殊_武家屋敷a", "bgm08.opus", null, "CHAPTER 7-3", null, null], [7398, "", "武士遵照女神大人在梦中的建议，举行了一场祈祷仪式。", null, "特殊_武家屋敷a", "bgm08.opus", null, "CHAPTER 7-3", null, null], [7399, "", "祈祷结束后，孩子就顺利地生了出来。", null, "特殊_武家屋敷a", "bgm08.opus", null, "CHAPTER 7-3", null, null], [7400, "", "孩子的母亲虽然精疲力竭，但性命并无大碍。", null, "特殊_武家屋敷a", "bgm08.opus", null, "CHAPTER 7-3", null, null], [7401, "将臣", "「太好了……这都是多亏了丛云小姐……」", null, "特殊_武家屋敷a", "bgm08.opus", null, "CHAPTER 7-3", null, null], [7402, "将臣", "「不过，没想到丛云小姐居然不是凡人……」", null, "特殊_武家屋敷a", "bgm08.opus", null, "CHAPTER 7-3", null, null], [7403, "", "这时武士才终于明白，她原来是一位神灵。", null, "特殊_武家屋敷a", "bgm08.opus", null, "CHAPTER 7-3", null, null], [7404, "将臣", "「那位大人成了我的妻子和孩子的守护神」", null, "特殊_武家屋敷a", "bgm08.opus", null, "CHAPTER 7-3", null, null], [7405, "将臣", "「这把丛雨，是否应该还给她……不」", null, "特殊_武家屋敷a", "bgm08.opus", null, "CHAPTER 7-3", null, null], [7406, "将臣", "「从今日起，它就是这片土地所有母亲和孩子的守护神，应该把它郑重地供奉起来才是」", null, "特殊_武家屋敷a", "bgm08.opus", null, "CHAPTER 7-3", null, null], [7407, "", "在那之后，丛雨就被奉为神刀，成了司掌妊娠和出产的守护神。", null, "空_青空", "bgm08.opus", null, "CHAPTER 7-3", null, null], [7408, "", "人们都称它为安产之神。", null, "空_青空", "bgm08.opus", null, "CHAPTER 7-3", null, null], [7409, "", "但是那位女神大人，却变成了一块被磨成球形的普通石头。", null, "山_山の中２b", "bgm36.opus", null, "CHAPTER 7-3", null, null], [7410, "", "她夺走了其他神的所有物，甚至还扭转了死亡的命运——她触犯了神界的天理，遭受了相应的惩罚。", null, "山_山の中２b", "bgm36.opus", null, "CHAPTER 7-3", null, null], [7411, "", "诞生自玉石的女神，又变回了玉石。", null, "山_山の中２b", "bgm36.opus", null, "CHAPTER 7-3", null, null], [7412, "白狛", "「我可怜的姐姐大人……」", "srk425_013.ogg", "山_山の中２b", "bgm36.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 7-3", null, null], [7413, "白狛", "「但是，就算改变了模样，失去了力量，姐姐大人也依然是我的姐姐大人」", "srk425_014.ogg", "山_山の中２b", "bgm36.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 7-3", null, null], [7414, "", "白狛——白山狛男神小心翼翼地叼起了那块石头。", null, "山_山の中２b", "bgm36.opus", null, "CHAPTER 7-3", null, null], [7415, "", "那块石头，对我们来说十分眼熟。", null, "山_山の中２b", "bgm36.opus", null, "CHAPTER 7-3", null, null], [7416, "", "没错，那石头和宿体的碎片几乎一模一样。", null, "山_山の中２b", "bgm36.opus", null, "CHAPTER 7-3", null, null], [7417, "", "也就是说，产生祟神的宿体，和祓除祟神的丛雨丸，都是来自于同一位神灵的遗物。", null, "山_山の中２b", "bgm36.opus", null, "CHAPTER 7-3", null, null], [7418, "白狛", "「姐姐大人，您的未了之愿，我一定会替您完成的」", "srk425_015.ogg", "山_山の中２b", "bgm36.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 7-3", null, null], [7419, "白狛", "「您拯救的这一族血脉，由我来守护」", "srk425_016.ogg", "山_山の中２b", "bgm36.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 7-3", null, null], [7420, "白狛", "「只要我永远守护下去……或许有一天，这一族人中会诞生出您的转世」", "srk425_017.ogg", "山_山の中２b", "bgm36.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 7-3", null, null], [7421, "", "许多年后，当年的婴儿已经长大成人。", null, "特殊_武家屋敷a", "bgm36.opus", null, "CHAPTER 7-3", null, null], [7422, "", "成年后的他德高望重，武艺过人，在当地的名声也越来越响。", null, "特殊_武家屋敷a", "bgm36.opus", null, "CHAPTER 7-3", null, null], [7423, "", "其实在那之后，武士的主公在远征期间不幸阵亡，武士身为守城大将，也就直接继承了主公的家业。", null, "特殊_武家屋敷a", "bgm36.opus", null, "CHAPTER 7-3", null, null], [7424, "", "但当时他并没有得到中央的认可，也没有正式的职位。", null, "特殊_武家屋敷a", "bgm36.opus", null, "CHAPTER 7-3", null, null], [7425, "", "直到他的孩子当家做主，镰仓幕府才正式将其任命为穗织地区的地头。任命时，还赐了他们一个姓氏。", null, "特殊_武家屋敷a", "bgm36.opus", null, "CHAPTER 7-3", null, null], [7426, "", "也就是“朝武”。", null, "特殊_武家屋敷a", "bgm36.opus", null, "CHAPTER 7-3", null, null], [7427, "将臣", "「（那个武士和我长得那么像，我本来还以为他是鞍马家的祖先）」", null, "特殊_武家屋敷a", "bgm36.opus", null, "CHAPTER 7-3", null, null], [7428, "将臣", "「（现在才知道，原来他是朝武家的始祖啊！？）」", null, "特殊_武家屋敷a", "bgm36.opus", null, "CHAPTER 7-3", null, null], [7429, "蕾娜", "「（芳乃家之所以只有女孩出生，都是因为诅咒吧？）」", "len425_001.ogg", "特殊_武家屋敷a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "23"}, "CHAPTER 7-3", null, null], [7430, "蕾娜", "「（我在想，这会不会是白狛的意愿啊？）」", "len425_002.ogg", "特殊_武家屋敷a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "20"}, "CHAPTER 7-3", null, null], [7431, "", "……它在等待女神的转世出现吗？", null, "特殊_武家屋敷a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "20"}, "CHAPTER 7-3", null, null], [7432, "蕾娜", "「（而且……我记得芳乃家从来没有人因为难产而死吧？）」", "len425_003.ogg", "特殊_武家屋敷a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "23"}, "CHAPTER 7-3", null, null], [7433, "将臣", "「（……嗯，几百年之间一个人都没有）」", null, "特殊_武家屋敷a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "23"}, "CHAPTER 7-3", null, null], [7434, "", "丛云的保佑似乎直到现在都还有效。", null, "特殊_武家屋敷a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "23"}, "CHAPTER 7-3", null, null], [7435, "", "穗织并不仅仅只是受到了诅咒。", null, "特殊_武家屋敷a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "23"}, "CHAPTER 7-3", null, null], [7436, "", "就算被人们彻底遗忘，她这么多年来……也一直守护着这片土地……", null, "特殊_武家屋敷a", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "23"}, "CHAPTER 7-3", null, null], [7437, "将臣", "「……差不多就是这么一回事吧」", null, "朝武_リビングa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "23"}, "CHAPTER 7-3", null, null], [7438, "蕾娜", "「是的，我也没有什么要补充的」", "len425_004.ogg", "朝武_リビングa", "bgm36.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "25"}, "CHAPTER 7-3", null, null], [7439, "", "等我们说完梦的内容之后，整个房间都彻底安静了下来。", null, "朝武_リビングa", "bgm36.opus", null, "CHAPTER 7-3", null, null], [7440, "", "由于我和蕾娜的视角不一样，为了通俗易懂，我们把故事重新整理了一遍。", null, "朝武_リビングa", "bgm36.opus", null, "CHAPTER 7-3", null, null], [7441, "", "但是应该没有漏掉什么重要的信息。", null, "朝武_リビングa", "bgm36.opus", null, "CHAPTER 7-3", null, null], [7442, "安晴", "「……确实，我从来没听说过朝武家发生过难产之类的意外」", "yas425_001.ogg", "朝武_リビングa", "bgm08.opus", {"char": "安晴", "file": "安晴.stand", "dress": "私服", "face": "06"}, "CHAPTER 7-3", null, null], [7443, "安晴", "「但是，真的没想到…………这么长时间我们竟然都没发现……」", "yas425_002.ogg", "朝武_リビングa", "bgm08.opus", {"char": "安晴", "file": "安晴.stand", "dress": "私服", "face": "08"}, "CHAPTER 7-3", null, null], [7444, "美津叶", "「我也一直以为……我们是被迫走在一条没有终点的钢丝上」", "miz425_001.ogg", "朝武_リビングa", "bgm08.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "05"}, "CHAPTER 7-3", null, null], [7445, "美津叶", "「本以为能撑到今天，都是奇迹」", "miz425_002.ogg", "朝武_リビングa", "bgm08.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "26"}, "CHAPTER 7-3", null, null], [7446, "丛雨", "「因为她始终保佑着你们」", "mur425_001.ogg", "朝武_リビングa", "bgm08.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "29"}, "CHAPTER 7-3", null, null], [7447, "丛雨", "「所以，你们才能让这个奇迹持续了这么多年」", "mur425_002.ogg", "朝武_リビングa", "bgm08.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "03"}, "CHAPTER 7-3", null, null], [7448, "芳乃", "「……～～」", "yos425_001.ogg", "朝武_リビングa", "bgm08.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "16"}, "CHAPTER 7-3", null, null], [7449, "蕾娜", "「哎！芳乃！？」", "len425_005.ogg", "朝武_リビングa", "bgm08.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "03"}, "CHAPTER 7-3", null, null], [7450, "", "突然，朝武站了起来，跑到了走廊上去。", null, "朝武_リビングa", "bgm08.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "03"}, "CHAPTER 7-3", null, null], [7451, "将臣", "「到底是怎么……回事！？」", null, "朝武_リビングa", "bgm08.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "03"}, "CHAPTER 7-3", null, null], [7452, "茉子", "「…………呜……呜～」", "mak425_001.ogg", "朝武_リビングa", "bgm08.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "07n"}, "CHAPTER 7-3", null, null], [7453, "", "我突然发现，就连我身边的常陆也开始潸然泪下，看得我不知道该说什么好了。", null, "朝武_リビングa", "bgm08.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "07n"}, "CHAPTER 7-3", null, null], [7454, "", "平时那么洒脱的常陆，现在却……！", null, "朝武_リビングa", "bgm08.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "07n"}, "CHAPTER 7-3", null, null], [7455, "蕾娜", "「……茉子？你没事吧，茉子？」", "len425_006.ogg", "朝武_リビングa", "bgm08.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "07"}, "CHAPTER 7-3", null, null], [7456, "茉子", "「嗯……我只是在想，我们的努力并不是没有意义的……」", "mak425_002.ogg", "朝武_リビングa", "bgm08.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "39n"}, "CHAPTER 7-3", null, null], [7457, "将臣", "「没有意义？」", null, "朝武_リビングa", "bgm08.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "39n"}, "CHAPTER 7-3", null, null], [7458, "茉子", "「我们家族的使命……就是保护朝武家的巫女不受诅咒侵害」", "mak425_003.ogg", "朝武_リビングa", "bgm08.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "41"}, "CHAPTER 7-3", null, null], [7459, "茉子", "「我的父母，祖父，曾祖父，还有更早的祖先们……他们把这份使命一代代传承了下来」", "mak425_004.ogg", "朝武_リビングa", "bgm08.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "10"}, "CHAPTER 7-3", null, null], [7460, "茉子", "「但是，每一次的结局……似乎都在否定我们的努力，嘲笑我们的愚蠢」", "mak425_005.ogg", "朝武_リビングa", "bgm08.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "07"}, "CHAPTER 7-3", null, null], [7461, "茉子", "「诅咒……终究会让巫女的寿命难以长久……」", "mak425_006.ogg", "朝武_リビングa", "bgm08.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "34"}, "CHAPTER 7-3", null, null], [7462, "茉子", "「无论我们多么努力地去守护……也都拗不过现实」", "mak425_007.ogg", "朝武_リビングa", "bgm08.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "45"}, "CHAPTER 7-3", null, null], [7463, "茉子", "「夜里，有时候我甚至会觉得，这样的使命或许是对我们一族的惩罚」", "mak425_008.ogg", "朝武_リビングa", "bgm08.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "36"}, "CHAPTER 7-3", null, null], [7464, "茉子", "「那既然如此，憎恨我们不就行了吗，为什么要憎恨芳乃大人和朝武家的人呢」", "mak425_009.ogg", "朝武_リビングa", "bgm08.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "32"}, "CHAPTER 7-3", null, null], [7465, "芳乃", "「你在说什么呢！茉子，我对你只有感激啊」", "yos425_002.ogg", "朝武_リビングa", "bgm08.opus", null, "CHAPTER 7-3", null, null], [7466, "", "朝武的声音也哽咽了起来。", null, "朝武_リビングa", "bgm08.opus", null, "CHAPTER 7-3", null, null], [7467, "茉子", "「我明白……我明白，但我还是……」", "mak425_010.ogg", "朝武_リビングa", "bgm08.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "39"}, "CHAPTER 7-3", null, null], [7468, "茉子", "「那位女神，是保佑了朝武后人代代平安的吧？」", "mak425_011.ogg", "朝武_リビングa", "bgm08.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "41"}, "CHAPTER 7-3", null, null], [7469, "茉子", "「也就是说，我们这么多年的赎罪……并不是没有意义的……」", "mak425_012.ogg", "朝武_リビングa", "bgm08.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "46n"}, "CHAPTER 7-3", null, null], [7470, "茉子", "「我的族人们……为了保护朝武家，遏制诅咒奋战至今，决不是什么无用功」", "mak425_013.ogg", "朝武_リビングa", "bgm08.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "43n"}, "CHAPTER 7-3", null, null], [7471, "", "常陆已经泣不成声了。", null, "朝武_リビングa", "bgm08.opus", null, "CHAPTER 7-3", null, null], [7472, "", "没想到常陆竟然有着这么深重的心结。", null, "朝武_リビングa", "bgm08.opus", null, "CHAPTER 7-3", null, null], [7473, "", "从小到大，她恐怕有一大半的时间都是在忍术训练中度过的。", null, "朝武_リビングa", "bgm08.opus", null, "CHAPTER 7-3", null, null], [7474, "", "她积压在心里的这些不安和恐惧，对大家来说可能并不陌生。", null, "朝武_リビングa", "bgm08.opus", null, "CHAPTER 7-3", null, null], [7475, "", "在场的每一个人，内心可能都有过这样的感觉。", null, "朝武_リビングa", "bgm08.opus", null, "CHAPTER 7-3", null, null], [7476, "", "诅咒并不仅仅是制造怪物，然后让怪物袭击朝武家的巫女。", null, "朝武_リビングa", "bgm08.opus", null, "CHAPTER 7-3", null, null], [7477, "", "诅咒一直都在穗织这片土地上蔓延，并侵蚀着人们的内心。", null, "朝武_リビングa", "bgm08.opus", null, "CHAPTER 7-3", null, null], [7478, "蕾娜", "「……～」", "len425_007.ogg", "朝武_リビングa", "bgm08.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "15"}, "CHAPTER 7-3", null, null], [7479, "", "这时，蕾娜用力握住了我的手。", null, "朝武_リビングa", "bgm08.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "15"}, "CHAPTER 7-3", null, null], [7480, "", "就算她不说话，我也能明白她的想法。", null, "朝武_リビングa", "bgm08.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "15"}, "CHAPTER 7-3", null, null], [7481, "", "……是的，我也是这么想的。", null, "朝武_リビングa", "bgm08.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "15"}, "CHAPTER 7-3", null, null], [7482, "将臣", "「我们必须终结这个诅咒」", null, "朝武_リビングa", "bgm08.opus", null, "CHAPTER 7-3", null, null], [7483, "", "大家都默默表示同意。", null, "朝武_リビングa", "bgm08.opus", null, "CHAPTER 7-3", null, null], [7484, "蕾娜", "「但白狛不应该是这里的守护神吗，为什么变成了祟神呢？」", "len425_008.ogg", "朝武_リビングa", "bgm08.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "30"}, "CHAPTER 7-3", null, null], [7485, "将臣", "「哦对了，这件事还没告诉你」", null, "朝武_リビングa", "bgm08.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "30"}, "CHAPTER 7-3", null, null], [7486, "", "除了蕾娜之外，大家都很清楚故事的后续。", null, "朝武_リビングa", "bgm08.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "30"}, "CHAPTER 7-3", null, null], [7487, "美津叶", "「因为朝武家内部出了一些问题」", "miz425_003.ogg", "朝武_リビングa", "bgm08.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "30"}, "CHAPTER 7-3", null, null], [7488, "美津叶", "「他们为了发动诅咒，竟然把那颗玉石，也就是丛云的遗体拿来当做宿体，并且献祭了白狛」", "miz425_004.ogg", "朝武_リビングa", "bgm08.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "09"}, "CHAPTER 7-3", null, null], [7489, "安晴", "「竟然用自己的守护神诅咒了自己……」", "yas425_003.ogg", "朝武_リビングa", "bgm08.opus", {"char": "安晴", "file": "安晴.stand", "dress": "私服", "face": "11"}, "CHAPTER 7-3", null, null], [7490, "安晴", "「真是忘恩负义，愚不可及」", "yas425_004.ogg", "朝武_リビングa", "bgm08.opus", {"char": "安晴", "file": "安晴.stand", "dress": "私服", "face": "05"}, "CHAPTER 7-3", null, null], [7491, "", "守护神的愤怒和悲痛，任谁都可以想象。", null, "朝武_リビングa", "bgm08.opus", null, "CHAPTER 7-3", null, null], [7492, "", "白狛会变成祟神，确实一点都不奇怪。", null, "朝武_リビングa", "bgm08.opus", null, "CHAPTER 7-3", null, null], [7493, "芳乃", "「……不好意思」", "yos425_003.ogg", "朝武_リビングa", "bgm08.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "46"}, "CHAPTER 7-3", null, null], [7494, "芳乃", "「能不能给我一点时间，我想冷静一会儿」", "yos425_004.ogg", "朝武_リビングa", "bgm08.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "13"}, "CHAPTER 7-3", null, null], [7495, "将臣", "「没问题」", null, "朝武_リビングa", "bgm08.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "13"}, "CHAPTER 7-3", null, null], [7496, "", "我拿出自己最柔和的语气，回应刚刚回来的朝武。", null, "朝武_リビングa", "bgm08.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "13"}, "CHAPTER 7-3", null, null], [7497, "蕾娜", "「当然没问题，这样最好」", "len425_009.ogg", "朝武_リビングa", "bgm08.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "31"}, "CHAPTER 7-3", null, null], [7498, "芳乃", "「谢谢」", "yos425_005.ogg", "朝武_リビングa", "bgm08.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "42"}, "CHAPTER 7-3", null, null], [7499, "芳乃", "「下一步该怎么办，先等我冷静下来之后再讨论吧」", "yos425_006.ogg", "朝武_リビングa", "bgm08.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "36"}, "CHAPTER 7-3", null, null], [7500, "", "就这样，我们暂时散会了。", null, "朝武_リビングa", "bgm08.opus", null, "CHAPTER 7-3", null, null], [7501, "蕾娜", "「嗯嗯唔唔～～～」", "len425_010.ogg", "朝武_自室b", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "31"}, "CHAPTER 7-3", null, null], [7502, "", "回房后，蕾娜一直在看一本似乎很古老的书卷，一边看一边抱着脑袋叫苦。", null, "朝武_自室b", "bgm39.opus", null, "CHAPTER 7-3", null, null], [7503, "", "这是昨天她向驹川大夫征求意见时借来的东西。", null, "朝武_自室b", "bgm39.opus", null, "CHAPTER 7-3", null, null], [7504, "将臣", "「这个对你来说是不是有点太难了啊？这本书就连我这个日本人都几乎看不懂」", null, "朝武_自室b", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "18"}, "CHAPTER 7-3", null, null], [7505, "蕾娜", "「可是，我们好不容易才知道了丛云的结局，以及祟神愤怒的原因」", "len425_011.ogg", "朝武_自室b", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "23"}, "CHAPTER 7-3", null, null], [7506, "蕾娜", "「现在我终于知道，我想对神说些什么了」", "len425_012.ogg", "朝武_自室b", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "15"}, "CHAPTER 7-3", null, null], [7507, "", "蕾娜的想法，果然是和神坐下来沟通。", null, "朝武_自室b", "bgm39.opus", null, "CHAPTER 7-3", null, null], [7508, "", "问题就在于沟通的方法。", null, "朝武_自室b", "bgm39.opus", null, "CHAPTER 7-3", null, null], [7509, "", "到底要说什么，怎么说，这些就只能交给蕾娜来判断了。", null, "朝武_自室b", "bgm39.opus", null, "CHAPTER 7-3", null, null], [7510, "", "总不可能真的用网络来沟通吧。", null, "朝武_自室b", "bgm39.opus", null, "CHAPTER 7-3", null, null], [7511, "蕾娜", "「他肯定是一位认真又善良的神……」", "len425_013.ogg", "朝武_自室b", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "06"}, "CHAPTER 7-3", null, null], [7512, "蕾娜", "「如果他是那种随性又懒惰的神，肯定是不会有这种结果的」", "len425_014.ogg", "朝武_自室b", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "12"}, "CHAPTER 7-3", null, null], [7513, "将臣", "「确实……」", null, "朝武_自室b", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "12"}, "CHAPTER 7-3", null, null], [7514, "", "像蕾娜这样，心情放松的同时又保持着积极向上的态度，应该是最难能可贵的。", null, "朝武_自室b", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "12"}, "CHAPTER 7-3", null, null], [7515, "", "但是这不仅对日本人来说很困难，对日本的神灵来说恐怕一样困难。", null, "朝武_自室b", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "12"}, "CHAPTER 7-3", null, null], [7516, "", "但只要蕾娜愿意出面沟通，那应该就是有意义的。", null, "朝武_自室b", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "12"}, "CHAPTER 7-3", null, null], [7517, "将臣", "「你一直在梦里扮演丛云，这样的经历应该也会助你一臂之力」", null, "朝武_自室b", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "12"}, "CHAPTER 7-3", null, null], [7518, "将臣", "「虽然你不会想着偷懒，但你是个天生的乐天派」", null, "朝武_自室b", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "12"}, "CHAPTER 7-3", null, null], [7519, "将臣", "「你的话语，说不定可以打动他的内心」", null, "朝武_自室b", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "12"}, "CHAPTER 7-3", null, null], [7520, "蕾娜", "「……唔～可是现在的问题在于，我连这本书都看不懂」", "len425_015.ogg", "朝武_自室b", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "07"}, "CHAPTER 7-3", null, null], [7521, "蕾娜", "「得继续学习才行啊」", "len425_016.ogg", "朝武_自室b", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "15"}, "CHAPTER 7-3", null, null], [7522, "将臣", "「加油。我觉得你肯定没问题的」", null, "朝武_自室b", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "15"}, "CHAPTER 7-3", null, null], [7523, "将臣", "「只要你把你的心意传达到了，就肯定有办法说服他」", null, "朝武_自室b", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "15"}, "CHAPTER 7-3", null, null], [7524, "", "我为了鼓励蕾娜，轻轻地摸了摸她的头。", null, "朝武_自室b", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "15"}, "CHAPTER 7-3", null, null], [7525, "蕾娜", "「谢谢你，将臣」", "len425_017.ogg", "朝武_自室b", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "19"}, "CHAPTER 7-3", null, null], [7526, "蕾娜", "「我是天生的乐天派，那你就是天生的好男人」", "len425_018.ogg", "朝武_自室b", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "02"}, "CHAPTER 7-3", null, null], [7527, "将臣", "「哈哈，这可就不好说了」", null, "朝武_自室b", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "02"}, "CHAPTER 7-3", null, null], [7528, "", "我拿起搁在一旁的竹刀。", null, "朝武_自室b", "bgm39.opus", null, "CHAPTER 7-3", null, null], [7529, "将臣", "「我先出去一会儿，不打扰你了」", null, "朝武_自室b", "bgm39.opus", null, "CHAPTER 7-3", null, null], [7530, "蕾娜", "「嗯，你也加油呀，将臣」", "len425_019.ogg", "朝武_自室b", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "19"}, "CHAPTER 7-3", null, null], [7531, "将臣", "「呼……呼……！」", null, "空_夕空", "bgm39.opus", null, "CHAPTER 7-3", null, null], [7532, "", "我来到院子里，开始做素振。", null, "空_夕空", "bgm39.opus", null, "CHAPTER 7-3", null, null], [7533, "", "虽然在蕾娜面前没有表现出来，但其实我也一直按捺着激动的心情。", null, "空_夕空", "bgm39.opus", null, "CHAPTER 7-3", null, null], [7534, "", "现在还不知道大家打算采取怎样的对策。", null, "空_夕空", "bgm39.opus", null, "CHAPTER 7-3", null, null], [7535, "", "但我觉得，兵刃相向恐怕是不太合适了。", null, "空_夕空", "bgm39.opus", null, "CHAPTER 7-3", null, null], [7536, "", "所以我必须告诫自己，我现在的训练无非只是为了坚定自己的决心而已。", null, "空_夕空", "bgm39.opus", null, "CHAPTER 7-3", null, null], [7537, "", "不管怎么说，现在的我只想多活动活动身体。", null, "空_夕空", "bgm39.opus", null, "CHAPTER 7-3", null, null], [7538, "", "朝武过来找我时，太阳已经落山了。", null, "神社_神社内d", "bgm09.opus", null, "CHAPTER 7-3", null, null], [7539, "芳乃", "「大家都来了吧」", "yos425_007.ogg", "神社_神社内d", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "01"}, "CHAPTER 7-3", null, null], [7540, "芳乃", "「那么，可以让我先说几句吗？」", "yos425_008.ogg", "神社_神社内d", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "16"}, "CHAPTER 7-3", null, null], [7541, "", "没有一个人插嘴。", null, "神社_神社内d", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "16"}, "CHAPTER 7-3", null, null], [7542, "芳乃", "「我一直认为，与祟神战斗，是我身为朝武家巫女的使命」", "yos425_009.ogg", "神社_神社内d", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "17"}, "CHAPTER 7-3", null, null], [7543, "芳乃", "「但不可否认的是，我也曾怨恨过，为什么会有这种天杀的诅咒」", "yos425_010.ogg", "神社_神社内d", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "23"}, "CHAPTER 7-3", null, null], [7544, "芳乃", "「……可怎料，诅咒产生的祟神，原本竟是我们的守护神，我们竟然一直被蒙在鼓里」", "yos425_011.ogg", "神社_神社内d", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "29"}, "CHAPTER 7-3", null, null], [7545, "芳乃", "「在对方看来，我们或许就是一群忘恩负义的凡人」", "yos425_012.ogg", "神社_神社内d", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "07"}, "CHAPTER 7-3", null, null], [7546, "芳乃", "「神灵震怒，或许也是理所当然的」", "yos425_013.ogg", "神社_神社内d", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "43"}, "CHAPTER 7-3", null, null], [7547, "芳乃", "「但是，尽管如此，我也不想把这些归咎于某一个人」", "yos425_014.ogg", "神社_神社内d", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "07"}, "CHAPTER 7-3", null, null], [7548, "茉子", "「……芳乃大人」", "mak425_014.ogg", "神社_神社内d", "bgm09.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "39"}, "CHAPTER 7-3", null, null], [7549, "芳乃", "「继承权之争，在凡人的世界里是很常见的事」", "yos425_015.ogg", "神社_神社内d", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "43"}, "CHAPTER 7-3", null, null], [7550, "芳乃", "「任何时代的任何人，都有可能会犯下这样的过错」", "yos425_016.ogg", "神社_神社内d", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "36"}, "CHAPTER 7-3", null, null], [7551, "芳乃", "「这个诅咒，归根结底是凡人的罪过」", "yos425_017.ogg", "神社_神社内d", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "07"}, "CHAPTER 7-3", null, null], [7552, "芳乃", "「那么，自然应该由我们凡人来解决！」", "yos425_018.ogg", "神社_神社内d", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "35"}, "CHAPTER 7-3", null, null], [7553, "丛雨", "「土地神大人恐怕也是这么认为的。他始终都没有直接伸出援手，而是让我们靠自己的力量来解决」", "mur425_003.ogg", "神社_神社内d", "bgm09.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "31"}, "CHAPTER 7-3", null, null], [7554, "", "靠自己的力量。", null, "神社_神社内d", "bgm09.opus", null, "CHAPTER 7-3", null, null], [7555, "", "靠自己的力量，解开诅咒。大家心里都明白，这是我们应该做的。", null, "神社_神社内d", "bgm09.opus", null, "CHAPTER 7-3", null, null], [7556, "芳乃", "「只要解开了诅咒，春日祭的含义大概也会有所变化」", "yos425_019.ogg", "神社_神社内d", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "42"}, "CHAPTER 7-3", null, null], [7557, "芳乃", "「以后的春日祭，不仅仅是一场祓除污秽的庆典，更应该是一场知恩图报的庆典」", "yos425_020.ogg", "神社_神社内d", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "04"}, "CHAPTER 7-3", null, null], [7558, "安晴", "「这方面可以交给我来处理吗」", "yas425_005.ogg", "神社_神社内d", "bgm09.opus", {"char": "安晴", "file": "安晴.stand", "dress": "私服", "face": "02"}, "CHAPTER 7-3", null, null], [7559, "安晴", "「反正丛雨丸已经被将臣拔出来了，以后的春日祭肯定不可能像往年那样了」", "yas425_006.ogg", "神社_神社内d", "bgm09.opus", {"char": "安晴", "file": "安晴.stand", "dress": "私服", "face": "13"}, "CHAPTER 7-3", null, null], [7560, "安晴", "「我也想尽自己的一份努力，争取得到氏子们的理解」", "yas425_007.ogg", "神社_神社内d", "bgm09.opus", {"char": "安晴", "file": "安晴.stand", "dress": "私服", "face": "02"}, "CHAPTER 7-3", null, null], [7561, "芳乃", "「当然了，这种事我也只能拜托爸爸了」", "yos425_021.ogg", "神社_神社内d", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "02"}, "CHAPTER 7-3", null, null], [7562, "芳乃", "「还有一件事，美津叶大夫」", "yos425_022.ogg", "神社_神社内d", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "41"}, "CHAPTER 7-3", null, null], [7563, "美津叶", "「什么事？」", "miz425_005.ogg", "神社_神社内d", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "41"}, "CHAPTER 7-3", null, null], [7564, "芳乃", "「今后，我想把我们的感恩之心传达给神灵……」", "yos425_023.ogg", "神社_神社内d", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "25"}, "CHAPTER 7-3", null, null], [7565, "芳乃", "「具体要怎么传达，能麻烦您研究一下吗？」", "yos425_024.ogg", "神社_神社内d", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "04"}, "CHAPTER 7-3", null, null], [7566, "美津叶", "「原来如此，这样挺好的……如果要赶在明年春季之前把方案定下来，接下来可能就会很忙了」", "miz425_006.ogg", "神社_神社内d", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "04"}, "CHAPTER 7-3", null, null], [7567, "美津叶", "「这类研究我真是现在就想立刻开始」", "miz425_007.ogg", "神社_神社内d", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "04"}, "CHAPTER 7-3", null, null], [7568, "芳乃", "「感谢您的支持」", "yos425_025.ogg", "神社_神社内d", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "20"}, "CHAPTER 7-3", null, null], [7569, "芳乃", "「毕竟……就算我们接下来解除了诅咒，也不可能废除多年来的春日祭传统」", "yos425_026.ogg", "神社_神社内d", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "28"}, "CHAPTER 7-3", null, null], [7570, "芳乃", "「虽然不废除，但我也不想仅仅只是维持一个形式」", "yos425_027.ogg", "神社_神社内d", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "46"}, "CHAPTER 7-3", null, null], [7571, "芳乃", "「因为诅咒是凡人的罪孽，与神灵无关」", "yos425_028.ogg", "神社_神社内d", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "22"}, "CHAPTER 7-3", null, null], [7572, "", "不过，这些都是未来的事了。", null, "神社_神社内d", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "22"}, "CHAPTER 7-3", null, null], [7573, "", "为了实现这个目标，接下来我们还有很多事要做。", null, "神社_神社内d", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "22"}, "CHAPTER 7-3", null, null], [7574, "芳乃", "「蕾娜」", "yos425_029.ogg", "神社_神社内d", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "28"}, "CHAPTER 7-3", null, null], [7575, "蕾娜", "「嗯，你说」", "len425_020.ogg", "神社_神社内d", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "28"}, "CHAPTER 7-3", null, null], [7576, "芳乃", "「我刚才说的，无非都是我的心愿而已。但我是真心希望它们都能实现」", "yos425_030.ogg", "神社_神社内d", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "22"}, "CHAPTER 7-3", null, null], [7577, "芳乃", "「为了让荒魂息怒，为了解除诅咒，我希望你能助我们一臂之力」", "yos425_031.ogg", "神社_神社内d", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "04"}, "CHAPTER 7-3", null, null], [7578, "蕾娜", "「芳乃，你说的我都明白。我也想要帮上你的忙」", "len425_021.ogg", "神社_神社内d", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "04"}, "CHAPTER 7-3", null, null], [7579, "将臣", "「蕾娜，难不成你……？」", null, "神社_神社内d", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "04"}, "CHAPTER 7-3", null, null], [7580, "蕾娜", "「是的，将臣，我希望你能取出自己体内的碎片，放进我的身体里」", "len425_022.ogg", "神社_神社内d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "08"}, "CHAPTER 7-3", null, null], [7581, "蕾娜", "「这样一来，宿体就完整了」", "len425_023.ogg", "神社_神社内d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "15"}, "CHAPTER 7-3", null, null], [7582, "丛雨", "「但是祟神的力量肯定也会变得更强」", "mur425_004.ogg", "神社_神社内d", "bgm09.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "10"}, "CHAPTER 7-3", null, null], [7583, "丛雨", "「我们至今为止之所以没有把碎片从你们体内取出来，就是害怕这一点」", "mur425_005.ogg", "神社_神社内d", "bgm09.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "11"}, "CHAPTER 7-3", null, null], [7584, "", "完整状态下的宿体究竟会引发怎样的变化，谁也无法预料。", null, "神社_神社内d", "bgm09.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "11"}, "CHAPTER 7-3", null, null], [7585, "", "但蕾娜说的也有道理。", null, "神社_神社内d", "bgm09.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "11"}, "CHAPTER 7-3", null, null], [7586, "蕾娜", "「如果要跟白狛对话，就必须让他恢复到能够对话的状态」", "len425_024.ogg", "神社_神社内d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "27"}, "CHAPTER 7-3", null, null], [7587, "蕾娜", "「为此，我只想到了这一个方法」", "len425_025.ogg", "神社_神社内d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "35"}, "CHAPTER 7-3", null, null], [7588, "", "如果仅仅只是对话，我们不可能压制住诅咒的力量。", null, "神社_神社内d", "bgm09.opus", null, "CHAPTER 7-3", null, null], [7589, "", "但如果先让白狛恢复理性，那说不定就有机会了。", null, "神社_神社内d", "bgm09.opus", null, "CHAPTER 7-3", null, null], [7590, "", "所以，我们才需要特意让宿体复原。", null, "神社_神社内d", "bgm09.opus", null, "CHAPTER 7-3", null, null], [7591, "芳乃", "「真没想到你会抢在我之前说出这些。但你真的不介意吗？」", "yos425_032.ogg", "神社_神社内d", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "22"}, "CHAPTER 7-3", null, null], [7592, "蕾娜", "「芳乃，咱们是朋友嘛」", "len425_026.ogg", "神社_神社内d", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "22"}, "CHAPTER 7-3", null, null], [7593, "蕾娜", "「朋友找我帮忙，我当然很开心了！」", "len425_027.ogg", "神社_神社内d", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "22"}, "CHAPTER 7-3", null, null], [7594, "芳乃", "「……也是」", "yos425_033.ogg", "神社_神社内d", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "04"}, "CHAPTER 7-3", null, null], [7595, "芳乃", "「谢谢你，蕾娜！我会尽我所能帮你减少风险的」", "yos425_034.ogg", "神社_神社内d", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "02"}, "CHAPTER 7-3", null, null], [7596, "蕾娜", "「嗯，我相信你，芳乃！」", "len425_028.ogg", "神社_神社内d", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "02"}, "CHAPTER 7-3", null, null], [7597, "将臣", "「啊，抱歉！先等等」", null, "神社_神社内d", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "02"}, "CHAPTER 7-3", null, null], [7598, "蕾娜", "「将臣，难道你不同意吗？」", "len425_029.ogg", "神社_神社内d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "30"}, "CHAPTER 7-3", null, null], [7599, "将臣", "「不是，事到如今还担心危险不危险的也没意思，我只是在想，从我体内取出碎片之后」", null, "神社_神社内d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "30"}, "CHAPTER 7-3", null, null], [7600, "将臣", "「我应该就没办法和你进入同一个梦境了吧？」", null, "神社_神社内d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "30"}, "CHAPTER 7-3", null, null], [7601, "蕾娜", "「喔……这么一说，好像确实是这个道理」", "len425_030.ogg", "神社_神社内d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "28"}, "CHAPTER 7-3", null, null], [7602, "丛雨", "「主人，你不必担心，还有本座在呢」", "mur425_006.ogg", "神社_神社内d", "bgm09.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "27"}, "CHAPTER 7-3", null, null], [7603, "将臣", "「小雨？难道，你知道什么好的方法吗？」", null, "神社_神社内d", "bgm09.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "27"}, "CHAPTER 7-3", null, null], [7604, "丛雨", "「你忘了吗，主人，祟神的宿体，和丛雨丸都是同一位神灵的遗物」", "mur425_007.ogg", "神社_神社内d", "bgm09.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "01"}, "CHAPTER 7-3", null, null], [7605, "将臣", "「我当然记得……啊，对哦！」", null, "神社_神社内d", "bgm09.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "01"}, "CHAPTER 7-3", null, null], [7606, "丛雨", "「正如你想的那样」", "mur425_008.ogg", "神社_神社内d", "bgm09.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "29"}, "CHAPTER 7-3", null, null], [7607, "丛雨", "「你只要将丛雨丸当做媒介，应该就可以进入蕾娜的梦境了」", "mur425_009.ogg", "神社_神社内d", "bgm09.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "19"}, "CHAPTER 7-3", null, null], [7608, "蕾娜", "「啊！对哦，差点忘了」", "len425_031.ogg", "神社_神社内d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "25"}, "CHAPTER 7-3", null, null], [7609, "蕾娜", "「我第一次被操控的时候，梦里突然出现了丛雨丸，然后我就醒了！」", "len425_032.ogg", "神社_神社内d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "01"}, "CHAPTER 7-3", null, null], [7610, "将臣", "「也就是说，当初能把你唤醒，都是多亏了丛雨丸的力量？」", null, "神社_神社内d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "01"}, "CHAPTER 7-3", null, null], [7611, "", "至今为止我一直把这含糊地解释为“不可思议的力量”，现在才终于明白原因所在！", null, "神社_神社内d", "bgm09.opus", null, "CHAPTER 7-3", null, null], [7612, "", "啊……真的是冥冥之中自有安排。", null, "神社_神社内d", "bgm09.opus", null, "CHAPTER 7-3", null, null], [7613, "", "我甚至怀疑，这一切的因果，都是某个人在背后操纵的结果。", null, "神社_神社内d", "bgm09.opus", null, "CHAPTER 7-3", null, null], [7614, "芳乃", "「当然了，我并不打算从头到尾都依赖丛雨丸」", "yos425_035.ogg", "神社_神社内d", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "02"}, "CHAPTER 7-3", null, null], [7615, "将臣", "「你是说还有其他方法吗？」", null, "神社_神社内d", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "02"}, "CHAPTER 7-3", null, null], [7616, "美津叶", "「我之前不是说了吗，为了防止你们无法从梦境中出来，我准备了一个应急方案」", "miz425_008.ogg", "神社_神社内d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "34"}, "CHAPTER 7-3", null, null], [7617, "蕾娜", "「我记得您好像说，要给我们准备一条救生索来着？」", "len425_033.ogg", "神社_神社内d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "34"}, "CHAPTER 7-3", null, null], [7618, "蕾娜", "「也就是说，一旦出现意外，您就可以直接把我们拉回来吗」", "len425_034.ogg", "神社_神社内d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "18"}, "CHAPTER 7-3", null, null], [7619, "美津叶", "「没错」", "miz425_009.ogg", "神社_神社内d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "18"}, "CHAPTER 7-3", null, null], [7620, "安晴", "「但是，要把救生索准备好，最起码还要再花上一天」", "yas425_008.ogg", "神社_神社内d", "bgm09.opus", {"char": "安晴", "file": "安晴.stand", "dress": "私服", "face": "15"}, "CHAPTER 7-3", null, null], [7621, "茉子", "「我和芳乃大人也会去帮忙的」", "mak425_015.ogg", "神社_神社内d", "bgm09.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "01"}, "CHAPTER 7-3", null, null], [7622, "将臣", "「是吗，那我们也……」", null, "神社_神社内d", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "02"}, "CHAPTER 7-3", null, null], [7623, "芳乃", "「不，你们不要来帮忙」", "yos425_036.ogg", "神社_神社内d", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "01"}, "CHAPTER 7-3", null, null], [7624, "蕾娜", "「为……为什么啊！？」", "len425_035.ogg", "神社_神社内d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "06"}, "CHAPTER 7-3", null, null], [7625, "茉子", "「哈哈，你们本来就任务艰巨，要替我们奋斗到最后一刻才行」", "mak425_016.ogg", "神社_神社内d", "bgm09.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "41"}, "CHAPTER 7-3", null, null], [7626, "茉子", "「所以这些准备工作就交给我们，你们尽管去养精蓄锐吧」", "mak425_017.ogg", "神社_神社内d", "bgm09.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "29"}, "CHAPTER 7-3", null, null], [7627, "芳乃", "「是的，在我们完成之前，你们就自由活动吧」", "yos425_037.ogg", "神社_神社内d", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "20"}, "CHAPTER 7-3", null, null], [7628, "", "我和蕾娜不由得对视了一眼。", null, "神社_神社内d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "30"}, "CHAPTER 7-3", null, null], [7629, "", "在这种情况下，让我们在一旁你侬我侬，那肯定是做不到的。", null, "神社_神社内d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "27"}, "CHAPTER 7-3", null, null], [7630, "将臣", "「真的可以吗？」", null, "神社_神社内d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "27"}, "CHAPTER 7-3", null, null], [7631, "蕾娜", "「你们不用跟我们客气的」", "len425_036.ogg", "神社_神社内d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "21"}, "CHAPTER 7-3", null, null], [7632, "芳乃", "「你们听我说。至今为止，你们已经无数次为我们赴汤蹈火了」", "yos425_038.ogg", "神社_神社内d", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "46"}, "CHAPTER 7-3", null, null], [7633, "芳乃", "「要是这种事都依赖你们，那就太说不过去了」", "yos425_039.ogg", "神社_神社内d", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "22"}, "CHAPTER 7-3", null, null], [7634, "茉子", "「也要让我们体验下为朋友两肋插刀的感觉才行嘛，您说是不是，芳乃大人」", "mak425_018.ogg", "神社_神社内d", "bgm09.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "01"}, "CHAPTER 7-3", null, null], [7635, "芳乃", "「没错」", "yos425_040.ogg", "神社_神社内d", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "03"}, "CHAPTER 7-3", null, null], [7636, "芳乃", "「所以，这些事就交给我们吧！」", "yos425_041.ogg", "神社_神社内d", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "20"}, "CHAPTER 7-3", null, null], [7637, "蕾娜", "「芳乃，茉子……」", "len425_037.ogg", "神社_神社内d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "27"}, "CHAPTER 7-3", null, null], [7638, "", "哎，还有比这更让人感动的话语吗。", null, "神社_神社内d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "27"}, "CHAPTER 7-3", null, null], [7639, "蕾娜", "「嗯……好吧，这里就拜托各位了！」", "len425_038.ogg", "神社_神社内d", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "18"}, "CHAPTER 7-3", null, null], [7640, "将臣", "「但毕竟还要上学，总不能跑出去玩」", null, "街_通学路a", "bgm34.opus", null, "CHAPTER 8-1", null, null], [7641, "蕾娜", "「我还想抽一些时间来学习」", "len426_001.ogg", "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 8-1", null, null], [7642, "", "说的也是。", null, "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 8-1", null, null], [7643, "", "蕾娜昨晚一直在研究那本古书，研究到很晚才睡。", null, "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 8-1", null, null], [7644, "蕾娜", "「好不容易有一天自由时间……我还挺想跟你好好亲热亲热的」", "len426_002.ogg", "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "30"}, "CHAPTER 8-1", null, null], [7645, "将臣", "「哈哈，还是等正事办完之后再说吧」", null, "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "30"}, "CHAPTER 8-1", null, null], [7646, "将臣", "「当务之急是解除诅咒，为一切画上一个完美的句号」", null, "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "30"}, "CHAPTER 8-1", null, null], [7647, "将臣", "「这样我们才能毫无顾虑地在一起做想做的事」", null, "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "30"}, "CHAPTER 8-1", null, null], [7648, "蕾娜", "「嗯……嘿嘿，说的也是」", "len426_003.ogg", "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 8-1", null, null], [7649, "蕾娜", "「那我就去学习啦，先失陪一会儿」", "len426_004.ogg", "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "17"}, "CHAPTER 8-1", null, null], [7650, "将臣", "「有什么我能帮忙的就尽管说」", null, "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "17"}, "CHAPTER 8-1", null, null], [7651, "", "昨晚我也是跟蕾娜一起睡的，但是并没有进入那个梦境。", null, "街_通学路a", "bgm34.opus", null, "CHAPTER 8-1", null, null], [7652, "", "驹川大夫和小雨都说，如果想看梦境的后续，恐怕得等到宿体复原之后。", null, "街_通学路a", "bgm34.opus", null, "CHAPTER 8-1", null, null], [7653, "美津叶", "『宿体分裂成许多个碎片之后，宿体中的记忆可能也碎得七零八落了』", "miz426_001.ogg", "神社_神社内d", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "05"}, "CHAPTER 8-1", null, null], [7654, "美津叶", "『只要宿体能够复原，其中的记忆或许也就能完整地再现了』", "miz426_002.ogg", "神社_神社内d", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "29"}, "CHAPTER 8-1", null, null], [7655, "丛雨", "『也就是说，剩下的记忆可能并不是在蕾娜的那块碎片里，而是在主人那里』", "mur426_001.ogg", "神社_神社内d", "bgm39.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "16"}, "CHAPTER 8-1", null, null], [7656, "", "重要的信息应该已经全部获取到了。", null, "街_通学路a", "bgm34.opus", null, "CHAPTER 8-1", null, null], [7657, "", "无论我们的猜想是对的还是错的，我们要做的事也不会有什么变化。", null, "街_通学路a", "bgm34.opus", null, "CHAPTER 8-1", null, null], [7658, "将臣", "「也就是说，目前不用做什么特别的事，跟平常一样就行了」", null, "街_通学路a", "bgm34.opus", null, "CHAPTER 8-1", null, null], [7659, "蕾娜", "「是呀！所以……将臣」", "len426_005.ogg", "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 8-1", null, null], [7660, "", "蕾娜靠了过来，紧紧地挽住了我的胳膊。", null, "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 8-1", null, null], [7661, "将臣", "「哎……哎？跟平常一样的话，不是只用牵手就行了吗？」", null, "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 8-1", null, null], [7662, "蕾娜", "「到了学校之后，我得专心学习」", "len426_006.ogg", "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "26"}, "CHAPTER 8-1", null, null], [7663, "蕾娜", "「所以，到学校之前，我想再多感受下你的体温……不行吗？」", "len426_007.ogg", "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "04"}, "CHAPTER 8-1", null, null], [7664, "将臣", "「怎么会不行呢，就、就是有点不好走路」", null, "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "04"}, "CHAPTER 8-1", null, null], [7665, "蕾娜", "「慢慢走就行啦。反正学校也不会逃走」", "len426_008.ogg", "街_通学路a", "bgm34.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 8-1", null, null], [7666, "", "也罢，这点小事不算什么。", null, "街_通学路a", "bgm34.opus", null, "CHAPTER 8-1", null, null], [7667, "", "明天，蕾娜就要去执行最重要的任务了。", null, "街_通学路a", "bgm34.opus", null, "CHAPTER 8-1", null, null], [7668, "", "所以今天就满足下她的小心愿吧。", null, "街_通学路a", "bgm34.opus", null, "CHAPTER 8-1", null, null], [7669, "廉太郎", "「怎么了，今天巫女大人她们都请假了吗？」", "ren426_001.ogg", "学院_教室休憩a", "bgm37.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "32"}, "CHAPTER 8-1", null, null], [7670, "将臣", "「嗯，她们家里有点事」", null, "学院_教室休憩a", "bgm37.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "32"}, "CHAPTER 8-1", null, null], [7671, "", "到了中午，廉太郎来到了我的座位上。", null, "学院_教室休憩a", "bgm37.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "32"}, "CHAPTER 8-1", null, null], [7672, "", "今天大家都留在神社，忙着做最后的准备。", null, "学院_教室休憩a", "bgm37.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "32"}, "CHAPTER 8-1", null, null], [7673, "", "毕竟昨天说好了把接下来的准备都交给她们，所以我也不好多问，到现在都完全不知道她们在干什么。", null, "学院_教室休憩a", "bgm37.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "32"}, "CHAPTER 8-1", null, null], [7674, "廉太郎", "「之前你跟蕾娜也早退了」", "ren426_002.ogg", "学院_教室休憩a", "bgm37.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "34"}, "CHAPTER 8-1", null, null], [7675, "廉太郎", "「而且蕾娜现在还在读一本看上去超难的书」", "ren426_003.ogg", "学院_教室休憩a", "bgm37.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "29"}, "CHAPTER 8-1", null, null], [7676, "蕾娜", "「唔～～～～这里是这样，所以那里就是这个意思，唔……」", "len426_009.ogg", "学院_教室休憩a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "11"}, "CHAPTER 8-1", null, null], [7677, "廉太郎", "「她刚才还去找古文老师问问题了吧」", "ren426_004.ogg", "学院_教室休憩a", "bgm37.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "07"}, "CHAPTER 8-1", null, null], [7678, "将臣", "「好像是的」", null, "学院_教室休憩a", "bgm37.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "07"}, "CHAPTER 8-1", null, null], [7679, "", "我一边说着，一边夹起一块藕夹，递到蕾娜嘴边。", null, "学院_教室休憩a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "20"}, "CHAPTER 8-1", null, null], [7680, "蕾娜", "「啊～嗯，唔」", "len426_010.ogg", "学院_教室休憩a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 8-1", null, null], [7681, "廉太郎", "「……你这家伙，在朋友面前也敢公然秀恩爱啊」", "ren426_005.ogg", "学院_教室休憩a", "bgm37.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "15"}, "CHAPTER 8-1", null, null], [7682, "将臣", "「哎？我这只是在协助她学习而已啊」", null, "学院_教室休憩a", "bgm37.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "15"}, "CHAPTER 8-1", null, null], [7683, "将臣", "「她说她连吃饭的时间都想利用起来」", null, "学院_教室休憩a", "bgm37.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "15"}, "CHAPTER 8-1", null, null], [7684, "廉太郎", "「是吗？」", "ren426_006.ogg", "学院_教室休憩a", "bgm37.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "37"}, "CHAPTER 8-1", null, null], [7685, "蕾娜", "「将臣，给我葡萄糖！我的大脑在渴求葡萄糖」", "len426_011.ogg", "学院_教室休憩a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "11"}, "CHAPTER 8-1", null, null], [7686, "将臣", "「ＯＫ，想吃甜食的话，这里刚好有大学芋，来，张嘴～」", null, "学院_教室休憩a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "11"}, "CHAPTER 8-1", null, null], [7687, "蕾娜", "「啊～唔～～～真好吃啊」", "len426_012.ogg", "学院_教室休憩a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "12"}, "CHAPTER 8-1", null, null], [7688, "蕾娜", "「有你喂我吃，这甜味都比平时浓郁了两倍～」", "len426_013.ogg", "学院_教室休憩a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 8-1", null, null], [7689, "将臣", "「哈哈，可能是因为我喂你的时候，在心里念了美味加倍的咒语」", null, "学院_教室休憩a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 8-1", null, null], [7690, "蕾娜", "「嘿嘿，难怪这么好吃！」", "len426_014.ogg", "学院_教室休憩a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "24"}, "CHAPTER 8-1", null, null], [7691, "廉太郎", "「这不是秀恩爱是什么啊！」", "ren426_007.ogg", "学院_教室休憩a", "bgm37.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "09"}, "CHAPTER 8-1", null, null], [7692, "将臣", "「啊？我们这不是跟平时一样吗？」", null, "学院_教室休憩a", "bgm37.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "09"}, "CHAPTER 8-1", null, null], [7693, "", "……大概。", null, "学院_教室休憩a", "bgm37.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "09"}, "CHAPTER 8-1", null, null], [7694, "", "不过，今天情况特殊，还是希望廉太郎不要见怪。", null, "学院_教室休憩a", "bgm37.opus", null, "CHAPTER 8-1", null, null], [7695, "", "毕竟蕾娜上课的时候连教科书都没工夫看，一直在研究那本古书。", null, "学院_教室休憩a", "bgm37.opus", null, "CHAPTER 8-1", null, null], [7696, "", "尽管这会影响到她的成绩，但也是没办法的事。", null, "学院_教室休憩a", "bgm37.opus", null, "CHAPTER 8-1", null, null], [7697, "", "所以比平时多慰劳她一下，也是应该的。", null, "学院_教室休憩a", "bgm37.opus", null, "CHAPTER 8-1", null, null], [7698, "廉太郎", "「我觉得你的常识已经混乱了。不过，好吧」", "ren426_008.ogg", "学院_教室休憩a", "bgm37.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "29"}, "CHAPTER 8-1", null, null], [7699, "廉太郎", "「我就不打扰你们了」", "ren426_009.ogg", "学院_教室休憩a", "bgm37.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "30"}, "CHAPTER 8-1", null, null], [7700, "将臣", "「抱歉啦」", null, "学院_教室休憩a", "bgm37.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "30"}, "CHAPTER 8-1", null, null], [7701, "将臣", "「最近都没怎么陪你玩」", null, "学院_教室休憩a", "bgm37.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "30"}, "CHAPTER 8-1", null, null], [7702, "廉太郎", "「没事啦，你跟一大老爷们说这干什么」", "ren426_010.ogg", "学院_教室休憩a", "bgm37.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "01"}, "CHAPTER 8-1", null, null], [7703, "廉太郎", "「怎么说呢，我也知道你最近很忙」", "ren426_011.ogg", "学院_教室休憩a", "bgm37.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "27"}, "CHAPTER 8-1", null, null], [7704, "廉太郎", "「而且你之前也说过吧，等到能说的时候，会全部告诉我们的」", "ren426_012.ogg", "学院_教室休憩a", "bgm37.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "26"}, "CHAPTER 8-1", null, null], [7705, "廉太郎", "「也不想想咱俩谁跟谁，这些我都理解」", "ren426_013.ogg", "学院_教室休憩a", "bgm37.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "01"}, "CHAPTER 8-1", null, null], [7706, "将臣", "「嗯，谢谢你，廉太郎」", null, "学院_教室休憩a", "bgm37.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "01"}, "CHAPTER 8-1", null, null], [7707, "将臣", "「等我这边忙完了，咱们再重温下友情？」", null, "学院_教室休憩a", "bgm37.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "01"}, "CHAPTER 8-1", null, null], [7708, "廉太郎", "「哈哈哈！不用跟我搞这些」", "ren426_014.ogg", "学院_教室休憩a", "bgm37.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "28"}, "CHAPTER 8-1", null, null], [7709, "廉太郎", "「要是哪天我有新女朋友了，肯定也会把你晾在一边，优先陪女朋友」", "ren426_015.ogg", "学院_教室休憩a", "bgm37.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "06"}, "CHAPTER 8-1", null, null], [7710, "将臣", "「哈哈，那咱们就扯平了啊」", null, "学院_教室休憩a", "bgm37.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "06"}, "CHAPTER 8-1", null, null], [7711, "廉太郎", "「那还用说」", "ren426_016.ogg", "学院_教室休憩a", "bgm37.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "27"}, "CHAPTER 8-1", null, null], [7712, "蕾娜", "「将——臣！唔……我的大脑又缺葡萄糖了……」", "len426_015.ogg", "学院_教室休憩a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "18"}, "CHAPTER 8-1", null, null], [7713, "将臣", "「啊，抱歉抱歉……给，张开嘴巴～」", null, "学院_教室休憩a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "18"}, "CHAPTER 8-1", null, null], [7714, "蕾娜", "「啊～唔……唔，嗯，真好吃♪」", "len426_016.ogg", "学院_教室休憩a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 8-1", null, null], [7715, "", "回过头来，发现廉太郎已经去了别处。", null, "学院_教室休憩a", "bgm37.opus", null, "CHAPTER 8-1", null, null], [7716, "", "虽然他有些方面很轻浮，但也正因如此，我们交流起来才可以这么随性。", null, "学院_教室休憩a", "bgm37.opus", null, "CHAPTER 8-1", null, null], [7717, "", "新的女朋友……", null, "学院_教室休憩a", "bgm37.opus", null, "CHAPTER 8-1", null, null], [7718, "", "有朝一日，廉太郎应该也能找到理解他优点的女生……", null, "学院_教室休憩a", "bgm37.opus", null, "CHAPTER 8-1", null, null], [7719, "廉太郎", "「嘿，你有ＬＩＮＥ吗？加一个嘛」", "ren426_017.ogg", "学院_教室休憩a", "bgm37.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "28"}, "CHAPTER 8-1", null, null], [7720, "廉太郎", "「来加个ＬＩＮＥ呗，哎？别这么说嘛，加一下加一下」", "ren426_018.ogg", "学院_教室休憩a", "bgm37.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "25"}, "CHAPTER 8-1", null, null], [7721, "将臣", "「……」", null, "学院_教室休憩a", "bgm37.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "25"}, "CHAPTER 8-1", null, null], [7722, "", "这家伙，竟然在学校里面勾搭女生！！", null, "学院_教室休憩a", "bgm37.opus", null, "CHAPTER 8-1", null, null], [7723, "小春", "「廉哥，你在干什么啊！？人渣，人渣！你真是个人渣！！」", "koh426_001.ogg", "学院_教室休憩a", "bgm37.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "14"}, "CHAPTER 8-1", null, null], [7724, "廉太郎", "「呃，小春！？好疼，好疼啊！不是你想的那样啊」", "ren426_019.ogg", "学院_教室休憩a", "bgm37.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "14"}, "CHAPTER 8-1", null, null], [7725, "廉太郎", "「我只是反思了下自己，觉得在学校里面也应该表现得积极一点……唔啊！？」", "ren426_020.ogg", "学院_教室休憩a", "bgm37.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "14"}, "CHAPTER 8-1", null, null], [7726, "", "廉太郎找到女朋友的日子，恐怕还很遥远。", null, "学院_教室休憩a", "bgm37.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "14"}, "CHAPTER 8-1", null, null], [7727, "蕾娜", "「……抱歉，将臣」", "len426_017.ogg", "学院_教室休憩a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "29"}, "CHAPTER 8-1", null, null], [7728, "将臣", "「嗯？怎么了」", null, "学院_教室休憩a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "29"}, "CHAPTER 8-1", null, null], [7729, "蕾娜", "「一直让你陪我感觉也不太好，你可以去陪他玩一会儿的」", "len426_018.ogg", "学院_教室休憩a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "10"}, "CHAPTER 8-1", null, null], [7730, "将臣", "「不不不，你没看见他刚才在干什么吗！」", null, "学院_教室休憩a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "10"}, "CHAPTER 8-1", null, null], [7731, "蕾娜", "「当然了，你要是跟廉太郎一起玩的话，我肯定希望你们玩点别的……」", "len426_019.ogg", "学院_教室休憩a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "31"}, "CHAPTER 8-1", null, null], [7732, "将臣", "「你不用在意的，我现在这样也挺开心」", null, "学院_教室休憩a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "31"}, "CHAPTER 8-1", null, null], [7733, "蕾娜", "「唔……可是我感觉，我还需要很久」", "len426_020.ogg", "学院_教室休憩a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "30"}, "CHAPTER 8-1", null, null], [7734, "将臣", "「没事，多久我都ＯＫ！」", null, "学院_教室休憩a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "30"}, "CHAPTER 8-1", null, null], [7735, "将臣", "「毕竟你看书的时候，我可以一直陪着你嘛」", null, "学院_教室休憩a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "30"}, "CHAPTER 8-1", null, null], [7736, "蕾娜", "「将臣……」", "len426_021.ogg", "学院_教室休憩a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "24"}, "CHAPTER 8-1", null, null], [7737, "将臣", "「不过，我在身边你会不会很难集中注意力？」", null, "学院_教室休憩a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "24"}, "CHAPTER 8-1", null, null], [7738, "蕾娜", "「……不会的」", "len426_022.ogg", "学院_教室休憩a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 8-1", null, null], [7739, "蕾娜", "「我也希望……你能陪在我身边」", "len426_023.ogg", "学院_教室休憩a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 8-1", null, null], [7740, "蕾娜", "「只有跟你在一起，我才能拿出全部的实力」", "len426_024.ogg", "学院_教室休憩a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "24"}, "CHAPTER 8-1", null, null], [7741, "将臣", "「那就太好了」", null, "学院_教室休憩a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "24"}, "CHAPTER 8-1", null, null], [7742, "", "我摸了摸蕾娜的头。", null, "学院_教室休憩a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "24"}, "CHAPTER 8-1", null, null], [7743, "", "她的头发实在是太柔顺了。", null, "学院_教室休憩a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "24"}, "CHAPTER 8-1", null, null], [7744, "蕾娜", "「不过，等我看完之后，我会安排一段二人时间的」", "len426_025.ogg", "学院_教室休憩a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "15"}, "CHAPTER 8-1", null, null], [7745, "蕾娜", "「在那之前你就稍微等等吧」", "len426_026.ogg", "学院_教室休憩a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 8-1", null, null], [7746, "将臣", "「真的吗？那我就先期待着吧，你加油啊」", null, "学院_教室休憩a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 8-1", null, null], [7747, "蕾娜", "「好的！嘿嘿，你就好好期待吧」", "len426_027.ogg", "学院_教室休憩a", "bgm37.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "25"}, "CHAPTER 8-1", null, null], [7748, "蕾娜", "「唔唔唔……好了，应该是搞定了！」", "len426_028.ogg", "学院_教室b", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "18"}, "CHAPTER 8-1", null, null], [7749, "", "蕾娜攥着稿纸，高兴地站了起来。", null, "学院_教室b", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "18"}, "CHAPTER 8-1", null, null], [7750, "", "窗外已近日暮，斜阳渐浓。", null, "学院_教室b", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "18"}, "CHAPTER 8-1", null, null], [7751, "将臣", "「辛苦了！感觉你也是相当用功啊」", null, "学院_教室b", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 8-1", null, null], [7752, "蕾娜", "「将臣！让你久等了」", "len426_029.ogg", "学院_教室b", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 8-1", null, null], [7753, "", "我来了个热烈的拥抱，又摸了摸她的头，以示慰劳。", null, "学院_教室b", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 8-1", null, null], [7754, "", "她也面带羞色，紧紧地抱住了我。", null, "学院_教室b", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19"}, "CHAPTER 8-1", null, null], [7755, "蕾娜", "「嘿嘿。今天我可用功了，你可要好好夸奖下我才行哦」", "len426_030.ogg", "学院_教室b", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 8-1", null, null], [7756, "将臣", "「可以呀……真棒真棒」", null, "学院_教室b", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 8-1", null, null], [7757, "蕾娜", "「嘻嘻嘻，每到这时你都会特别温柔，我最喜欢这样了」", "len426_031.ogg", "学院_教室b", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 8-1", null, null], [7758, "蕾娜", "「继续，继续啦～～我真想永远保持这样」", "len426_032.ogg", "学院_教室b", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 8-1", null, null], [7759, "将臣", "「哈哈，但你手里的稿子，还要全部背下来才行吧？」", null, "学院_教室b", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 8-1", null, null], [7760, "蕾娜", "「……嗯～～～～」", "len426_033.ogg", "学院_教室b", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "18"}, "CHAPTER 8-1", null, null], [7761, "", "蕾娜看上去有点伤脑筋。", null, "学院_教室b", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "18"}, "CHAPTER 8-1", null, null], [7762, "蕾娜", "「我觉得，等到晚上再背应该也没问题」", "len426_034.ogg", "学院_教室b", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "02"}, "CHAPTER 8-1", null, null], [7763, "蕾娜", "「而且，这些内容基本都是跟驹川大夫一边商量一边定下来的，仔细一看，其实也就这一点」", "len426_035.ogg", "学院_教室b", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 8-1", null, null], [7764, "", "确实，一张稿纸就已经写下了所有的内容。", null, "学院_教室b", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 8-1", null, null], [7765, "", "但是上面写着很多难懂的汉字，一想到这些全都是蕾娜写的，就知道她写得多么辛苦了。", null, "学院_教室b", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 8-1", null, null], [7766, "", "而且我知道，蕾娜从前天就开始写了，整整两天半的时间，她都在准备这个东西。", null, "学院_教室b", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 8-1", null, null], [7767, "蕾娜", "「真的是，累得不行……不过也很有成就感」", "len426_036.ogg", "学院_教室b", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 8-1", null, null], [7768, "蕾娜", "「而且，现在都傍晚了吧」", "len426_037.ogg", "学院_教室b", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 8-1", null, null], [7769, "将臣", "「嗯？啊，确实」", null, "学院_教室b", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27"}, "CHAPTER 8-1", null, null], [7770, "蕾娜", "「毕竟让你等了那么久，现在不好好亲热下可不行」", "len426_038.ogg", "学院_教室b", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "15"}, "CHAPTER 8-1", null, null], [7771, "将臣", "「你不用在意啦」", null, "学院_教室b", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "15"}, "CHAPTER 8-1", null, null], [7772, "将臣", "「我能一整天陪在你身边，就已经很满足了」", null, "学院_教室b", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "15"}, "CHAPTER 8-1", null, null], [7773, "蕾娜", "「那——可——不——行！咱们的二人时光，也是非～～常宝贵的」", "len426_039.ogg", "学院_教室b", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "23"}, "CHAPTER 8-1", null, null], [7774, "蕾娜", "「就算很忙，就算有什么事情……我也不愿意将就」", "len426_040.ogg", "学院_教室b", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "21"}, "CHAPTER 8-1", null, null], [7775, "将臣", "「……蕾娜」", null, "学院_教室b", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "21"}, "CHAPTER 8-1", null, null], [7776, "蕾娜", "「难道……你不这么觉得吗？」", "len426_041.ogg", "学院_教室b", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "07"}, "CHAPTER 8-1", null, null], [7777, "将臣", "「怎么会呢」", null, "学院_教室b", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "07"}, "CHAPTER 8-1", null, null], [7778, "", "我也紧紧地抱住了蕾娜。", null, "学院_教室b", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "07"}, "CHAPTER 8-1", null, null], [7779, "蕾娜", "「呜啊～！嘿嘿……从你的举动中，我感受到了你的心情」", "len426_042.ogg", "学院_教室b", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "17h"}, "CHAPTER 8-1", null, null], [7780, "蕾娜", "「不过，现在还是希望你能明确地说出来」", "len426_043.ogg", "学院_教室b", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "15"}, "CHAPTER 8-1", null, null], [7781, "将臣", "「嗯……我爱你，蕾娜」", null, "学院_教室b", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "15"}, "CHAPTER 8-1", null, null], [7782, "蕾娜", "「我随时都可以向上帝发誓，我也爱着你～」", "len426_044.ogg", "学院_教室b", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 8-1", null, null], [7783, "", "轻轻地，我们双唇相接……不过——", null, "学院_教室b", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "01"}, "CHAPTER 8-1", null, null], [7784, "蕾娜", "「唔……啊，嗯……唔……」", "len426_045.ogg", "学院_教室b", "bgm54.opus", null, "CHAPTER 8-1", "ev403a", null], [7785, "蕾娜", "「哈啊，将臣……将臣……唔……嗯～」", "len426_046.ogg", "学院_教室b", "bgm54.opus", null, "CHAPTER 8-1", "ev403a", null], [7786, "", "她直接把舌头伸了进来。", null, "学院_教室b", "bgm54.opus", null, "CHAPTER 8-1", "ev403a", null], [7787, "", "也罢。", null, "学院_教室b", "bgm54.opus", null, "CHAPTER 8-1", "ev403a", null], [7788, "", "反正现在其他学生都回去了。", null, "学院_教室b", "bgm54.opus", null, "CHAPTER 8-1", "ev403a", null], [7789, "", "说不定，现在学校里面只剩我们俩了。", null, "学院_教室b", "bgm54.opus", null, "CHAPTER 8-1", "ev403a", null], [7790, "蕾娜", "「唔……嗯……将臣，你也把舌头伸进来了呀，唔！嗯……」", "len426_047.ogg", "学院_教室b", "bgm54.opus", null, "CHAPTER 8-1", "ev403a", null], [7791, "将臣", "「嗯，蕾娜……蕾娜，我爱你，嗯……」", null, "学院_教室b", "bgm54.opus", null, "CHAPTER 8-1", "ev403a", null], [7792, "蕾娜", "「啊……唔……现在，我们可以尽情地……亲热了」", "len426_048.ogg", "学院_教室b", "bgm54.opus", null, "CHAPTER 8-1", "ev403a", null], [7793, "将臣", "「当然了，尽情亲热吧……嗯？」", null, "学院_教室b", "bgm54.opus", null, "CHAPTER 8-1", "ev403a", null], [7794, "", "突然，我感觉哪里不对劲。", null, "学院_教室b", "bgm54.opus", null, "CHAPTER 8-1", "ev403a", null], [7795, "", "但下一秒，蕾娜就按着我的肩膀，让我坐在了椅子上。", null, "学院_教室b", "bgm54.opus", null, "CHAPTER 8-1", null, null], [7796, "蕾娜", "「呃、那个……将臣，我们可以进入下一步吗？」", "len426_049.ogg", "学院_教室b", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27h"}, "CHAPTER 8-1", null, null], [7797, "将臣", "「等、等等，你的意思是……」", null, "学院_教室b", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27h"}, "CHAPTER 8-1", null, null], [7798, "蕾娜", "「…………大概就是你想的那样」", "len426_050.ogg", "学院_教室b", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "10h"}, "CHAPTER 8-1", null, null], [7799, "蕾娜", "「你、你想呀，在芳乃家，大家都在……而且今晚我还有别的事……」", "len426_051.ogg", "学院_教室b", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "12h"}, "CHAPTER 8-1", null, null], [7800, "蕾娜", "「所以，我想趁现在……补充一下你的温暖」", "len426_052.ogg", "学院_教室b", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "23h"}, "CHAPTER 8-1", null, null], [7801, "将臣", "「啊，这个……好吧」", null, "学院_教室b", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "23h"}, "CHAPTER 8-1", null, null], [7802, "", "一想到明天的事，我也能理解她的心情。", null, "学院_教室b", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "23h"}, "CHAPTER 8-1", null, null], [7803, "", "说实话，我其实也很渴望她的温暖。", null, "学院_教室b", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "23h"}, "CHAPTER 8-1", null, null], [7804, "", "我就是觉得现在这个情况下，可能有点不合适。", null, "学院_教室b", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "23h"}, "CHAPTER 8-1", null, null], [7805, "", "但既然她都这么主动了，那我身为男人肯定也该表示下才行。", null, "学院_教室b", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "23h"}, "CHAPTER 8-1", null, null], [7806, "将臣", "「来吧，蕾娜。我也想补充一下你的温暖」", null, "学院_教室b", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "23h"}, "CHAPTER 8-1", null, null], [7807, "蕾娜", "「…………好的，将臣」", "len426_053.ogg", "学院_教室b", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "27h"}, "CHAPTER 8-1", null, null], [7808, "蕾娜", "「今天……我也会让你尽情感受的」", "len426_054.ogg", "学院_教室b", "bgm54.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "制服", "face": "19h"}, "CHAPTER 8-1", null, null], [7809, "蕾娜", "「嗯……将臣的大●鸡，已经变得这么硬了……」", "len426_055.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7810, "将臣", "「呜啊！？……蕾娜？」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7811, "", "蕾娜再次用她的爆乳夹住了我的阴茎。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7812, "", "龟头从双峰之间探出头来，蕾娜上去就是一阵热吻。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7813, "蕾娜", "「呀！？将臣……我只是轻轻地吻了一下而已，啊、啊……嗯」", "len426_056.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7814, "蕾娜", "「你的大●鸡在我的山谷之间蠢蠢欲动……嘿嘿，是不是很舒服？」", "len426_057.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7815, "", "蕾娜愈发来劲，再一次冲着我的阴茎吻了上去。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7816, "", "我那敏感的龟头，就这样被她的湿润双唇包裹在内。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7817, "蕾娜", "「唔……嗯！哈啊……啊啊……将臣，你的大●鸡又开始跳动了」", "len426_058.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7818, "将臣", "「蕾娜……我、我快不行了……！」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7819, "蕾娜", "「啊……啊……想射就射吧……我希望你能尽情感受我的爱意……将臣，唔……嗯……」", "len426_059.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7820, "", "她的双乳紧紧地顶住了我的阴茎。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7821, "", "从根部到冠状沟，全都被那一对酥胸紧紧包裹着，我已经快要不能自已了。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7822, "蕾娜", "「哈啊、哈啊……嗯……嗯！将臣……你的大●鸡，好热……」", "len426_060.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7823, "蕾娜", "「啊、嗯……我的胸，还有舌头……热得都快烧起来了……嗯！唔……！」", "len426_061.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7824, "将臣", "「蕾娜……这可是学校，你的声音太大了」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7825, "蕾娜", "「确实……那么……嗯……我就安静一点吧」", "len426_062.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7826, "", "她用舌尖来回把玩着我的龟头。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7827, "", "同时，还上下挺动身体，用双乳摩挲着我的下体。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7828, "蕾娜", "「嗯……嗯……唔……哈啊……啊……！唔……啊……嗯……！」", "len426_063.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7829, "", "我十分清楚，蕾娜的巨乳仅仅只是摩擦几下，就能给我带来无上的快感。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7830, "", "她明知道我的龟头已经被前列腺液濡湿，却紧接着又发动了舌尖之刑。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7831, "蕾娜", "「滋溜滋溜……啊……嗯……！唔……有好多……透明的前列腺液……流了出来……唔……」", "len426_064.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7832, "蕾娜", "「啊……稍微有点苦……有一股色色的味道……啊，嗯……这味道有点奇怪呀」", "len426_065.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7833, "将臣", "「呃，抱歉……你不用全部舔掉的」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7834, "蕾娜", "「嗯……那可不行……这都是你的……嗯……」", "len426_066.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7835, "蕾娜", "「这说明……你现在非常舒服……所以，我才不会停下来呢……」", "len426_067.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7836, "将臣", "「蕾、蕾娜……啊！？」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7837, "", "她那榨汁机一般的双乳继续摩挲着我的下体，透明的前列腺液也被她吮吸殆尽。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7838, "", "我的大脑已经彻底放空，再这么下去恐怕精液都要被直接吸出来。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7839, "蕾娜", "「唔……唔……将臣，你要是想射了……嗯……啊……就不要忍耐，尽情射出来就行，啊！」", "len426_068.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7840, "", "我下体发力，想尽量抵住精门。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7841, "", "但蕾娜却丝毫没有手下留情的意思。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7842, "蕾娜", "「啊啊、啊！嗯……又流出了一些，很苦的东西……啊，唔……！」", "len426_069.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7843, "蕾娜", "「将臣……将臣……啊、啊！我想要更多……更浓……再来一点，再来一点吧……嗯！」", "len426_070.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7844, "将臣", "「再、再等我一会儿……！」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7845, "蕾娜", "「嗯……唔！那可不行……这里可是学校……我们得……速战速决才行……唔！」", "len426_071.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7846, "", "我差点就觉得她说的有道理了。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7847, "", "但正因为这里是学校，所以在这里射精是不对的……", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7848, "蕾娜", "「没事的，没事的……将臣……将臣……唔……啊啊、啊啊！」", "len426_072.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7849, "", "一股快感从我的脊椎窜入大脑。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7850, "", "直接击垮了我的理性。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7851, "蕾娜", "「哈啊！啊、啊啊……嗯……快射出来……射在我的奶子上……射在我的嘴里……」", "len426_073.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7852, "蕾娜", "「将臣……唔……啊！哈啊……嗯……」", "len426_074.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7853, "将臣", "「可、可是……蕾娜……啊啊！」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7854, "", "我想射，我想射！我必须忍耐，必须忍耐！", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7855, "", "这快感让我的血液都为之沸腾，我的大脑几乎已经被冲动所占据。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7856, "蕾娜", "「唔！？将臣，你的大●鸡……你的龟头，越胀越大……嗯……啊啊！？」", "len426_075.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7857, "将臣", "「蕾、蕾娜……我、我要射了，你快让开，啊啊！？」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7858, "蕾娜", "「唔……！啊啊……将臣，你不要管我，就这样……就这样，射出来吧……啊！」", "len426_076.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7859, "蕾娜", "「嗯、嗯！哈、啊啊……唔……啊啊！将臣，将臣……啊……唔！」", "len426_077.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7860, "蕾娜", "「哈啊……啊啊！？要……要射出来了……！？」", "len426_078.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7861, "", "我终于忍不住了。喷涌而出的精液向蕾娜射了过去。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7862, "", "被乳房紧紧包裹住的阴茎，开始了疯狂的咆哮。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7863, "蕾娜", "「啊啊……哈啊、啊啊，嗯……！好多，好粘……哈啊……啊」", "len426_079.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7864, "蕾娜", "「唔……将臣的精液，今天也是这么多……我舔」", "len426_080.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7865, "将臣", "「唔！蕾、蕾娜……我才刚射出来呢，你不要刺激我」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7866, "蕾娜", "「嗯？是嘛，唔……嗯……」", "len426_081.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7867, "", "蕾娜的身体上下抽动着，她的双乳依旧紧紧夹着我刚射完精的阴茎。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7868, "", "被精液和唾液濡湿的双乳再一次贴了上来。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7869, "蕾娜", "「你看……果然不出我所料。嘿嘿……你的大●鸡，还是这么硬……嗯……」", "len426_082.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7870, "将臣", "「这里是学校，不是说要速战速决的吗？」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7871, "蕾娜", "「是的，不过……刚才不是说好了嘛……你要尽情地感受我的温暖才行……嗯……嗯～」", "len426_083.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7872, "蕾娜", "「将臣……将臣……唔、嗯……嗯……！啊、啊啊！」", "len426_084.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7873, "", "蕾娜再一次亲吻我的阴茎。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7874, "", "尽管它沾满了精液，看上去很不雅观，但蕾娜依旧舔得津津有味。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7875, "蕾娜", "「唔……嗯……让我来……帮你舔干净吧……嗯！唔……包在我身上吧……嗯……嗯……啊！」", "len426_085.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7876, "", "就这样，她把我残留在尿道中的精液也全部吸了出来。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7877, "", "在她的舌尖攻势下，我的腰身不禁为之一颤。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7878, "蕾娜", "「唔……！？将臣……你的精液实在是太浓厚……嗯……舔得我满嘴都是……嗯～」", "len426_086.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7879, "蕾娜", "「我的嘴里……嗯嗯！嗯！全都是……你的精液……啊呜……嗯！唔……！」", "len426_087.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7880, "将臣", "「蕾、蕾娜……这味道应该不太好吧？」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7881, "蕾娜", "「唔……没事的啦。这些……都是你的子孙……啊啊……啊呜……啊！」", "len426_088.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7882, "", "她就像是上瘾了一样，尽情地吮吸着我的龟头。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7883, "", "并且用她那柔软的双乳反复搋和着我的阴茎。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7884, "蕾娜", "「啊、嗯！这触感，滑滑的……啊啊！我也越来越舒服了……啊呜！？嗯……嗯嗯～！」", "len426_089.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7885, "将臣", "「蕾娜……你也兴奋起来了吗？」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7886, "蕾娜", "「是的、是的……所以……唔……你也不要忍耐……再来……再来一次……」", "len426_090.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7887, "蕾娜", "「再多多射出来吧……唔……啊啊……」", "len426_091.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7888, "", "我……", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7889, "蕾娜", "「嗯？将臣……哈啊……啊啊……嗯……唔！哈啊……啊！？」", "len426_092.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7890, "", "我微微坐起，直接将龟头塞进了蕾娜口中。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7891, "", "尽管蕾娜的声音听上去有些难受，我也没有停下来。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7892, "蕾娜", "「唔……唔！哈啊……你的龟头，又开始胀起来了……将臣……你又开始有感觉了吗？」", "len426_093.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7893, "将臣", "「是的……我不忍了……不，我是根本忍不住了！我要就这样……就这样……再来一次！」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7894, "蕾娜", "「将臣、将臣……没问题的。你就尽情射吧……我想让你……多多射出来……啊啊！？」", "len426_094.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7895, "", "被乳房包裹的阴茎，仅仅只有前端插入了她的嘴里。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7896, "", "好舒服！太舒服、太舒服了，我已经忍不住了！", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7897, "蕾娜", "「啊呜、唔……！哈啊、唔……将臣，快射……快射出来……将臣！唔啊……！」", "len426_095.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7898, "将臣", "「我、我要射了、蕾娜，我可以……就这样射在你嘴里吗……？」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7899, "蕾娜", "「可以的……你就这样……就这样……射在我嘴里吧……唔！」", "len426_096.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7900, "蕾娜", "「一边享受快感，一边射吧……将臣！射很多很多出来……唔！？」", "len426_097.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7901, "蕾娜", "「唔～～～～～～～～～！！？」", "len426_098.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7902, "", "最后的那一瞬间，我微微抬起身子，将龟头塞进了蕾娜嘴里。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7903, "蕾娜", "「唔……啊啊……哈啊、啊啊！又射了……射了好多……嘴里全都是……啊啊……！」", "len426_099.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7904, "蕾娜", "「看来……你真的是忍耐了很久啊……唔……嗯嗯～」", "len426_100.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7905, "", "我的龟头在她嘴里一边感受着她的体温，一边持续喷射着精液。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7906, "", "精液渐渐从她嘴边溢出，拉成一条粘稠的白丝，落在地面。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7907, "蕾娜", "「哈啊、唔……嗯！直接射在嘴里……这味道，确实有点冲人，唔！」", "len426_101.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7908, "将臣", "「蕾娜，你不要勉强自己，全部吐出来吧」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7909, "", "但是蕾娜却摇了摇头。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7910, "蕾娜", "「没事的……嗯……唔……啊啊……唔……咕咚」", "len426_102.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7911, "", "她竟然直接把精液吞了下去。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7912, "蕾娜", "「哈啊……哈啊……嘿嘿，我把你的子孙全部吞下去了……」", "len426_103.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7913, "蕾娜", "「啊、啊啊！将臣、你……你动得太激烈了，我、我都吻不到了……啊啊……！」", "len426_104.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7914, "", "我终于忍不了。我将阴茎直接插入了蕾娜的双乳之中。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7915, "", "抽动腰身的同时，我尽量在她的山谷间摩擦。因为我也想给她带来快感。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7916, "蕾娜", "「啊啊、啊！将臣、将臣……你这样……就好像把我的奶子当小穴用……好激烈……啊啊啊！？」", "len426_105.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7917, "将臣", "「我要射了，要射了！蕾娜，你也尽情享受吧」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7918, "蕾娜", "「啊啊、啊！明明是我，是我要让你享受的……啊啊、啊啊！」", "len426_106.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7919, "", "我的小腹撞击着她的乳房，不停地发出啪啪啪的声响。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7920, "", "我的阴茎在她的山谷之中搅动着各种体液。我已经快到极限了。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7921, "蕾娜", "「啊啊、啊啊！嗯……啊啊……明明只是在晃动双乳而已……没想到……乳头却这么舒服……啊啊！」", "len426_107.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7922, "将臣", "「我也是，我也非常舒服，蕾娜！蕾娜！」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7923, "蕾娜", "「将臣，将臣！你也很有感觉嘛……啊啊啊」", "len426_108.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7924, "蕾娜", "「我也……我也非常有感觉……啊啊、啊啊！？」", "len426_109.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7925, "蕾娜", "「啊啊啊、啊啊！？啊……啊啊啊啊啊！！？」", "len426_110.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7926, "", "我的精液再一次喷涌而出，将蕾娜的山谷染成了白色。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7927, "蕾娜", "「啊啊、啊啊！你又、又射了好多出来……将臣，将臣……啊啊～」", "len426_111.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7928, "蕾娜", "「啊、啊啊啊……我的脸好热……脸上……全都是……啊啊……」", "len426_112.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7929, "", "断断续续射出的白浊液，一股接一股击中了蕾娜的脸颊。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7930, "", "白色的粘液沿着她的脸颊滴了下来。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7931, "蕾娜", "「哈啊……啊啊……嗯……这都是第二次了，可是这量……跟刚才比丝毫不逊色……」", "len426_113.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7932, "将臣", "「抱歉，竟然全部射在了你的脸上」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7933, "蕾娜", "「嘿嘿，不用在意啦……你的精液，我一点都不讨厌。而且……」", "len426_114.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7934, "", "蕾娜用力捧起乳房，将山谷挤得越来越深。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7935, "将臣", "「……蕾、蕾娜？」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7936, "蕾娜", "「你应该……还能继续吧？嗯……嗯……快看，现在比刚才还要硬呢」", "len426_115.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7937, "蕾娜", "「你的大●鸡，在我的山谷里……又硬起来了……嗯……嗯嗯……」", "len426_116.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7938, "将臣", "「蕾娜……蕾娜！」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7939, "", "我已经忍不住了。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7940, "", "我抱着蕾娜的肩膀，挺起下体，几乎快要把她按倒在地。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7941, "蕾娜", "「啊、啊啊，你别慌，我可不想躺在地上」", "len426_117.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7942, "将臣", "「是、是吗，那就……」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev415a", null], [7943, "", "我将桌子并在一起，让蕾娜躺在上面，然后一口气插了进去。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [7944, "蕾娜", "「唔、啊啊啊～～！你的大●鸡……一下子就进来了……而且进得这么深……」", "len426_118.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [7945, "将臣", "「啊、啊啊……但你的小穴还是这么紧！」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [7946, "", "她的小穴已经开始适应我的下体了吗？", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [7947, "", "这紧致的触感和初体验时完全一样，她的小穴就这样轻易地接受了我的阴茎。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [7948, "蕾娜", "「嘿嘿……我能感觉到……你的大●鸡，在我的肚子里……」", "len426_119.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [7949, "将臣", "「嗯，明明这么紧……你的小穴也毫不退缩……」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [7950, "将臣", "「这比初体验的时候，还要舒服」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [7951, "蕾娜", "「因为……这是你的大●鸡吗……嗯……我的小穴，早就记住它的形状了……啊啊！」", "len426_120.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [7952, "蕾娜", "「……我的小穴……是只属于你的东西」", "len426_121.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [7953, "将臣", "「啊、蕾娜……我爱你」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [7954, "蕾娜", "「嗯，我也爱你……我也爱你……啊啊……啊啊……我还要更多……更多……」", "len426_122.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [7955, "蕾娜", "「你就尽情地……更加彻底地……爱我吧……将臣、将臣……哈啊、啊啊啊！？」", "len426_123.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [7956, "", "我不记得自己是什么时候开始抽动的。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [7957, "", "本能和爱意已经完全支配了我的大脑，让我激烈地渴求着蕾娜。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [7958, "蕾娜", "「啊、啊啊！一上来……就这么激烈啊……啊、啊啊！哈啊……啊啊！？」", "len426_124.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [7959, "", "桌子发出了吧嗒吧嗒的响声，我的腰身一次又一次撞击着她的臀部。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [7960, "", "这些声音我已经完全不在意了。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [7961, "", "这些都不重要了……我只想渴求蕾娜！", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [7962, "蕾娜", "「嗯！啊啊……将臣……将臣……吻我……吻我……啊啊……啊♪」", "len426_125.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [7963, "将臣", "「蕾娜，蕾娜！我会尽情吻你的……」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [7964, "蕾娜", "「好的、将臣、唔……嗯……啊啊！哈啊、啊……唔……！」", "len426_126.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [7965, "", "我们的舌尖贪婪地交融在一起。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [7966, "", "下半身也不甘示弱，龟头和子宫也开始了激烈的深吻。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [7967, "蕾娜", "「啊！啊啊、啊……唔……啊……啊……好深，将臣，好深……啊啊、啊啊！」", "len426_127.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [7968, "", "蕾娜的一切都是这么动人。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [7969, "", "我渴望爱她的一切。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [7970, "蕾娜", "「啊啊！？将……将臣？啊、连奶子你也不放过……啊啊！」", "len426_128.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [7971, "将臣", "「蕾娜，你的胸这么大，也这么敏感……」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [7972, "蕾娜", "「那当然了……啊啊、啊！这都是因为……你在揉啊……」", "len426_129.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [7973, "", "蕾娜似乎打算任我摆布。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [7974, "", "她毫不遮挡自己的乳房，反而挺起了胸膛，就像是在鼓励我继续发力一样。所以，我也毫不客气地吸了上去。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [7975, "蕾娜", "「啊、啊啊！将臣……啊、啊……你又像小宝宝一样……吸了上来……啊！」", "len426_130.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [7976, "蕾娜", "「你就使劲吸……尽情地吸吧……将臣、将臣！啊啊……啊啊！」", "len426_131.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [7977, "", "蕾娜抱住了我的脖子。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [7978, "", "我的脸埋进了那一对天然缓冲物之中……这份幸福，几乎快要让我窒息。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [7979, "蕾娜", "「哈啊、啊啊……一想到你像个小宝宝……我就……啊啊……」", "len426_132.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [7980, "蕾娜", "「我就非常……非常……兴奋……啊啊、啊啊！啊啊啊！？」", "len426_133.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [7981, "将臣", "「啊啊、我也是……我浑身都是……你带来的快感……！」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [7982, "蕾娜", "「啊啊！我、我懂……啊……你的大●鸡……啊啊、啊啊！」", "len426_134.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [7983, "蕾娜", "「在我的小穴里……越来越硬……龟头……也胀得越来越大……啊啊！……」", "len426_135.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [7984, "", "没错……我已经快到极限了。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [7985, "", "虽然已经射了好几次，但只要进入了蕾娜体内，我就再也无法克制自己的射精冲动。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [7986, "蕾娜", "「将臣、将臣！好舒服……我也好舒服啊，将臣、将臣！」", "len426_136.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [7987, "", "小腹内部就像燃起了一团火一样，让我无法抗拒。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [7988, "", "我已经无法克制自己了。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [7989, "蕾娜", "「啊、啊！哈啊、哈啊……我也、我也快……高潮了……啊啊！」", "len426_137.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [7990, "将臣", "「我也是……蕾娜！蕾娜！」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [7991, "蕾娜", "「嗯、没事的……就这样……就这样一起……一起高潮吧……我感觉快要和你融为一体了」", "len426_138.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [7992, "", "融为一体！", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [7993, "", "我们就这样紧紧地连接在一起，放任快感支配着我们的全身。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [7994, "蕾娜", "「我爱你、我爱你……将臣，我爱你……将臣！啊、啊啊！啊啊啊！」", "len426_139.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [7995, "将臣", "「我也爱你，我也爱你，蕾娜，我爱你！」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [7996, "蕾娜", "「嘿嘿……我最喜欢你了……最喜欢你了……将臣！将臣，啊啊、啊啊啊！」", "len426_140.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [7997, "蕾娜", "「让我们一起、一起高潮吧！一起、一起高潮！啊啊、啊啊！啊啊……啊啊啊！」", "len426_141.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [7998, "蕾娜", "「啊、啊啊！快来，快来……将臣也快来吧！啊啊、啊啊……啊啊啊！？」", "len426_142.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [7999, "蕾娜", "「啊啊啊啊啊啊啊啊啊啊啊～～～！！」", "len426_143.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8000, "", "我就着抽动腰身的势头，用阴茎紧紧地抵住了子宫的大门口。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8001, "蕾娜", "「啊、啊啊！将臣、你、射出来了……啊啊、在我的子宫里、射出来了……」", "len426_144.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8002, "蕾娜", "「哈啊！啊啊……你的大●鸡，还在继续……啊啊！」", "len426_145.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8003, "", "没错，我一边射精，一边抽动着腰身。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8004, "", "还不够，还远远不够。我和蕾娜还完全没有满足。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8005, "蕾娜", "「哈啊、啊啊！啊、啊……才、才刚射完呢，你还是这么凶猛……哈哈……」", "len426_146.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8006, "将臣", "「你还说我呢……仅仅这一次你肯定是不够的吧」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8007, "蕾娜", "「这个嘛……哈啊……啊啊……将臣……嗯嗯！这还不是因为……啊啊！」", "len426_147.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8008, "蕾娜", "「你每次……每次……都这么满足我……啊啊……啊！」", "len426_148.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8009, "", "她就像是在撒娇一样，用指尖拨弄着我的胸膛。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8010, "", "我也紧紧地抱住了她，用甜蜜的亲吻作为回应。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8011, "蕾娜", "「哈啊……啊啊……嗯！啊、啊啊……真是拿你没办法……啊、啊」", "len426_149.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8012, "蕾娜", "「……谁让你……啊啊……不愿意放开我呢……啊、啊啊……」", "len426_150.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8013, "", "当然放不开了！我再一次用力顶开了子宫的大门。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8014, "", "紧接着，精液和爱液的混合物从小穴里流了出来。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8015, "蕾娜", "「啊、啊啊！真是的……我现在还很敏感的啦……啊、啊啊～啊啊！」", "len426_151.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8016, "将臣", "「抱歉，不过……我已经停不下来了」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8017, "蕾娜", "「嘿嘿……我明白的……啊、啊！我也……停不下来了……啊啊啊！？」", "len426_152.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8018, "蕾娜", "「将臣、将臣！我不想放开你、啊啊！啊啊，啊啊！」", "len426_153.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8019, "", "我的腰身进一步加速。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8020, "", "我的精液正渴求着蕾娜。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8021, "蕾娜", "「哈啊、啊啊！啊、啊啊！将臣、将臣……啊、啊啊！啊、啊啊！」", "len426_154.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8022, "", "我的大脑似乎已经煮成了一锅浓汤，欲望、理性，还有爱意，全部都混杂在了一起。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8023, "", "我只是一味地渴求着蕾娜！", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8024, "蕾娜", "「嗯嗯嗯！我、我好像……又要高潮了……要去了、要去了……啊啊！？」", "len426_155.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8025, "将臣", "「我也是……蕾娜，我们一起高潮吧」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8026, "蕾娜", "「嗯……嗯！我要、我要跟将臣一起……啊、啊啊！嗯……啊啊！」", "len426_156.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8027, "", "我……", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8028, "蕾娜", "「哈啊！？将臣、你又激烈起来了……啊啊！好厉害、好厉害，将臣！将臣！」", "len426_157.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8029, "", "我已经无法思考了。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8030, "", "我只是一个劲地抽动着腰身，只想冲向蕾娜体内的婴儿房……", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8031, "蕾娜", "「要去了，要去了！我要去了，将臣！用你的大●鸡，让我升天吧！啊啊啊！」", "len426_158.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8032, "将臣", "「啊啊、啊啊！就这样、就这样，再一次！」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8033, "蕾娜", "「啊啊！嗯……射出来吧……射出来吧……把你的子孙，全部灌进我的小穴里……！」", "len426_159.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8034, "", "脊背传来一股触电般的快感，体内燃起了欲望的火焰。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8035, "", "传宗接代的本能……即将在蕾娜体内爆发！", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8036, "蕾娜", "「将臣、将臣！好热、好热……快射出来、射出来！将臣，啊啊！」", "len426_160.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8037, "将臣", "「马上、马上就射了！你做好准备，做好准备，蕾娜！」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8038, "蕾娜", "「嗯嗯嗯嗯～你的大●鸡，大●鸡……在我的身体里，膨胀起来了……啊啊啊！」", "len426_161.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8039, "蕾娜", "「你的精子……我会好好接住的……用我的小穴……啊啊！」", "len426_162.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8040, "蕾娜", "「啊啊、啊啊！要去了，要去了！要去了要去了，我要去了，将臣！」", "len426_163.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8041, "蕾娜", "「哈啊、啊啊啊啊啊啊啊啊啊啊啊～～～！！！」", "len426_164.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8042, "", "我在蕾娜的体内尽情地射了出来。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8043, "蕾娜", "「啊……啊，你的大●鸡，在我小穴里……一跳一跳的……啊啊」", "len426_165.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8044, "蕾娜", "「你的精液……嗯、嗯嗯……好多、好多……全部都注入了子宫的深处」", "len426_166.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8045, "", "伴随着阴茎的脉动，蕾娜的阴道也随之蠕动，温柔地……榨干了我最后一滴精液。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8046, "", "我静静地将阴茎放在她体内，玩味着最后的快感。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8047, "蕾娜", "「哈啊、啊啊啊！……将臣、将臣！」", "len426_167.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8048, "", "我放任着自己的本能，将脸埋进了她的胸部。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8049, "", "就这样，我开始了最后的总攻击。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8050, "蕾娜", "「啊啊、啊啊！啊啊啊啊，你这样……激烈地吮吸着我的奶子……我就要升天了……」", "len426_168.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8051, "将臣", "「唔……还不够，还要更激烈点，你就好好享受吧，蕾娜！蕾娜！」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8052, "蕾娜", "「啊啊、这实在是、实在是……太舒服了，啊啊啊！我要提前高潮了，啊啊啊！」", "len426_169.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8053, "", "她的小穴越来越紧，就像是要榨干我的一切。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8054, "", "我也沉溺在快感之中，加快了腰身的抽动。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8055, "蕾娜", "「啊啊、啊啊！要去了，要去了，要去了要去了！将臣、将臣！」", "len426_170.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8056, "将臣", "「还差一点……还差一点了！」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8057, "蕾娜", "「好慢，太慢了！啊、啊啊！快点，快点射出来……射出来，将臣！」", "len426_171.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8058, "蕾娜", "「啊啊！啊啊！啊啊啊啊！一起、我想跟你一起高潮……我、我要……！？」", "len426_172.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8059, "蕾娜", "「啊啊、啊啊！啊、哈啊……啊啊啊，将臣！？啊啊啊！？」", "len426_173.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8060, "蕾娜", "「啊啊啊啊啊啊啊啊啊啊啊啊～～～～～！！！」", "len426_174.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8061, "", "在最后一刻，我挣脱了小穴的吸附，将阴茎拔了出来。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8062, "蕾娜", "「啊啊……拔出来了……啊啊！这势头真是激烈……啊啊！」", "len426_175.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8063, "蕾娜", "「将臣……你的大●鸡……势如泉涌……射了好多好多……我都看见了……啊啊」", "len426_176.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8064, "", "随着阴茎的脉动，一条条白色的抛物线从我的下腹部射向蕾娜的乳房。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8065, "", "所爱之人，正在沐浴着我的精液。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8066, "蕾娜", "「哈啊、啊啊……呼、呼……哈……将臣，你的大●鸡，哪怕是在学校里，也是这么有精神」", "len426_177.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8067, "将臣", "「你也是呀，做到一半的时候，你几乎都要失神了吧」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8068, "蕾娜", "「那都是因为你的攻势太激烈，让我忘记了自我……」", "len426_178.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8069, "", "其实我也一样。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8070, "", "我用亲吻传达了我的心意。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8071, "蕾娜", "「唔……嘻嘻，我爱你，将臣」", "len426_179.ogg", "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8072, "将臣", "「我也爱你，蕾娜」", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8073, "", "我们再一次亲吻对方。", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8074, "", "就这样，我们紧紧地抱在一起……", null, "画面_黒", "bgm14.opus", null, "CHAPTER 8-1", "ev416a", null], [8075, "", "是因为太过紧张，导致睡眠太浅？还是因为明天事关重大，今晚睡得太早？", null, "朝武_自室c", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8076, "", "半夜，我突然醒了过来。", null, "朝武_自室c", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8077, "蕾娜", "「呼……嗯……呼……」", "len426_180.ogg", "朝武_自室c", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8078, "将臣", "「……蕾娜好像还睡得很香」", null, "朝武_自室c", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8079, "", "她这几天一直在努力写稿子，大脑肯定很累了。", null, "朝武_自室c", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8080, "", "不管怎么说，蕾娜确实了不起。", null, "朝武_自室c", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8081, "", "我就很不中用了，大晚上的一点睡意都没有。", null, "朝武_自室c", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8082, "", "院子那边似乎还亮着灯。大家应该还在干活。", null, "朝武_自室c", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8083, "", "要不要去帮帮忙呢？", null, "朝武_自室c", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8084, "", "感觉他们肯定会赶我走。", null, "朝武_自室c", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8085, "将臣", "「啊，对了」", null, "朝武_自室c", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8086, "", "我突然想起了一件事。那是之前一直想做，却一直没做的事。", null, "朝武_自室c", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8087, "", "这个时间……应该还醒着吧。", null, "朝武_自室c", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8088, "", "我悄悄爬出了被窝，拿起了手机。为了不吵醒蕾娜，我尽量压低了一切声音。", null, "朝武_自室c", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8089, "蕾娜", "「…………？」", "len426_181.ogg", "朝武_自室c", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8090, "", "来到客厅后，我打开通讯录，找到了家里的座机号码。", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8091, "", "跟蕾娜的家人视频通话过之后，我也一直都想给家里打个电话。", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8092, "", "但由于我没事很少给家里打电话，所以不知不觉就拖到了今天。", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8093, "将臣", "「……嗯，趁现在打一个吧」", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8094, "", "仔细想想，多亏了我妈那句话，我才会来到穗织。", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8095, "", "既然现在要迎来终结了，再一次听听她的声音也挺好的。", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8096, "", "我鼓起勇气，按下了通话键。", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8097, "", "要是她已经睡了，那就下次再打吧。", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8098, "都子", "『你这是怎么了，大半夜打电话过来』", "myk426_001.ogg", "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8099, "都子", "『难不成是出什么事了？大半夜的你可别吓我啊』", "myk426_002.ogg", "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8100, "将臣", "「怎么一上来就说这个」", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8101, "", "我刚听见我妈的声音，就有点后悔了。", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8102, "", "她离这里很远，不清楚这里的状况是理所当然的。但这声音未免也太悠闲了吧。", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8103, "都子", "『没办法啊，你主动打电话过来，真的是太稀罕了』", "myk426_003.ogg", "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8104, "将臣", "「啊，嗯，抱歉……我就是想偶尔联系一下」", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8105, "将臣", "「最近还好吗？」", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8106, "都子", "『我这边不用你担心，你在那儿过得怎么样啊？』", "myk426_004.ogg", "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8107, "将臣", "「啊，这个……」", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8108, "都子", "『有没有好好吃饭？功课没落下吧？』", "myk426_005.ogg", "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8109, "都子", "『没给你外公添麻烦吧？有没有好好给他们帮忙？』", "myk426_006.ogg", "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8110, "都子", "『真是的，越说我越担心』", "myk426_007.ogg", "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8111, "将臣", "「嗯，没问题的……嗯」", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8112, "", "她连珠炮弹似的抛来这么多问题，说实话，搞得我有点心烦。", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8113, "", "每当看到别人家父母对孩子的关爱，我还是会很感动的。", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8114, "", "可为什么面对自己的爹妈时，就会感觉很麻烦呢？我都有点想马上挂断了。", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8115, "将臣", "「没什么大不了的，就是偶尔打个电话联系下」", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8116, "都子", "『呵，自己打来还嫌麻烦』", "myk426_008.ogg", "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8117, "", "这都被听出来了。", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8118, "", "但我刚才说话的时候你不是也没仔细听吗。", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8119, "都子", "『行吧，不说这个了。下次要是再打，就挑白天打』", "myk426_009.ogg", "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8120, "都子", "『刚才看到来电人是你，大半夜的真是吓死我了』", "myk426_010.ogg", "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8121, "将臣", "「我知道了我知道了，那我就……」", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8122, "", "我刚把手指伸出去，又突然改变了主意。", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8123, "都子", "『怎么了？还有什么事吗？』", "myk426_011.ogg", "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8124, "将臣", "「不是，呃，那个……」", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8125, "将臣", "「妈，谢谢你」", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8126, "都子", "『……你怎么了？吃坏肚子了还是吃坏脑子了？』", "myk426_012.ogg", "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8127, "将臣", "「不是啊，我就是感觉，小时候天天惹你们心烦……也没什么别的意思」", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8128, "都子", "『啊？怎么突然说这个？这是死亡Ｆｌａｇ？』", "myk426_013.ogg", "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8129, "", "至于说得这么恐怖吗。", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8130, "", "早知道就不说了。", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8131, "将臣", "「是我错了行吧，那先挂了！」", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8132, "", "这次我终于将手指伸向了挂断按钮。", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8133, "都子", "『瞧你说得……』", "myk426_014.ogg", "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8134, "", "挂断之前又听见了我妈的声音，我到底还是没能按下去。", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8135, "都子", "『瞧你说得，我们怎么可能心烦呢』", "myk426_015.ogg", "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8136, "将臣", "「……哎？」", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8137, "都子", "『确实，你小时候总是让我们担心，但嫌你烦是不可能的』", "myk426_016.ogg", "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8138, "都子", "『不过，现在你也长大了，就算不打电话过来，我们也不至于整天忧心忡忡的』", "myk426_017.ogg", "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8139, "都子", "『你不在身边，我们倒也过得悠闲自在』", "myk426_018.ogg", "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8140, "将臣", "「我不在，你跟我爸就能尽情做各种爱做的事了？」", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8141, "都子", "『哈哈哈哈哈哈哈哈！！』", "myk426_019.ogg", "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8142, "", "她突然爆笑了起来，吓得我赶紧把手机拿开。", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8143, "都子", "『确实，也有这方面的原因』", "myk426_020.ogg", "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8144, "将臣", "「天下还有这么诚实的爹妈啊」", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8145, "", "服了，我爸妈的脑回路就是不一般。", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8146, "", "不过，事到如今我也想明白了一些事情。", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8147, "", "新婚时的夫妻一旦当了父母，哪怕再怎么想过二人时光，也不得不优先自己的孩子。", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8148, "", "现在我不在，若是能让他们找回年轻时的感觉，倒也不失为一件好事。", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8149, "都子", "『我猜你那边肯定是有了什么事吧』", "myk426_021.ogg", "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8150, "将臣", "「哎？为什么这么说？」", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8151, "都子", "『你突然打电话过来，突然说这么严肃的事，那我肯定会这么想啊』", "myk426_022.ogg", "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8152, "将臣", "「啊、啊……」", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8153, "", "说的也是。我有点太小看我妈了。", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8154, "将臣", "「其实，我交到女朋友了」", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8155, "都子", "『ｙｕｋｊｇｎｖｊｎｙｌｉｌｍｏｐ！！？』", "myk426_023.ogg", "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8156, "将臣", "「哇啊！？」", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8157, "", "我赶忙把手机从耳边拿开。", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8158, "", "都喊出乱码来了，这情绪变化也太诡异了吧。", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8159, "都子", "『孩子他爸！孩子他爸～～～！将臣说他有女朋友了！……什么？』", "myk426_024.ogg", "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8160, "都子", "『你现在喝什么酒啊！……喝酒庆祝？对哦，我怎么没想到！？你赶快去买啤酒，买一打回来！』", "myk426_025.ogg", "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8161, "都子", "『对，放车后备箱里！……哎？你问我去哪买，我怎么知道！反正不开车肯定搬不了，放后备箱里！全放后备箱里！！』", "myk426_026.ogg", "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8162, "", "看来，并不只有蕾娜的家人会那样。", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8163, "", "日本的家庭也差不多。", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8164, "将臣", "「你别这么激动行吗！大半夜的也不嫌吵……你在听吗？」", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8165, "都子", "『你快说说，你女朋友是个什么样的女孩？话说明天我要不要去趟发廊！？』", "myk426_027.ogg", "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8166, "将臣", "「明天？等等，我可没说明天要带她去见你们啊」", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8167, "都子", "『哎？不来啊？哎？……孩子他爸，不用去了』", "myk426_028.ogg", "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8168, "都子", "『车钥匙？不用找了，你就继续喝你的啤酒吧』", "myk426_029.ogg", "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8169, "将臣", "「啊，真是的，反正，她是个很重视家人的女孩」", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8170, "将臣", "「所以，受她影响……我觉得我也该好好孝敬下父母才行，就是这样」", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8171, "都子", "『你怎么这么喜欢立死亡Ｆｌａｇ啊』", "myk426_030.ogg", "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8172, "将臣", "「啊？唉，哪有你这样当妈的，亏我一片好心」", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8173, "", "无论我再怎么努力，我家爹妈估计也就这样了。", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8174, "", "哪怕即将面临最终决战，他们也并不会给我加油鼓劲什么的。", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8175, "都子", "『我说啊，你不用考虑什么孝敬父母之类的问题』", "myk426_031.ogg", "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8176, "将臣", "「不，这不行的吧」", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8177, "都子", "『没事，你能健康长大，我们就已经感恩戴德了』", "myk426_032.ogg", "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8178, "将臣", "「感恩戴德？对谁，对神仙？」", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8179, "都子", "『傻孩子，肯定是对你啊』", "myk426_033.ogg", "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8180, "", "啊。", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8181, "都子", "『下次有空了，记得把女朋友带来介绍下啊。可以直接带家里来』", "myk426_034.ogg", "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8182, "将臣", "「啊……嗯，我到时候问下她」", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8183, "将臣", "「我也想给你们好好介绍下」", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8184, "都子", "『那我就好好期待那一天了』", "myk426_035.ogg", "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8185, "将臣", "「嗯，那我先挂了」", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8186, "", "话说回来，仅仅只是知道儿子有女朋友了，就兴奋成那样。", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8187, "", "等他们知道女朋友是外国人，那岂不是要上天了？", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8188, "蕾娜", "「……将臣」", "len426_182.ogg", "朝武_リビングc", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "25"}, "CHAPTER 8-1", null, null], [8189, "将臣", "「蕾娜！是我把你吵醒了吗？」", null, "朝武_リビングc", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "25"}, "CHAPTER 8-1", null, null], [8190, "蕾娜", "「不是，你一直没回来，我就过来看下是怎么回事」", "len426_183.ogg", "朝武_リビングc", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "25"}, "CHAPTER 8-1", null, null], [8191, "将臣", "「抱歉，我马上就回去……嗯？」", null, "朝武_リビングc", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "25"}, "CHAPTER 8-1", null, null], [8192, "", "蕾娜轻轻地抓着我的袖子。", null, "朝武_リビングc", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "25"}, "CHAPTER 8-1", null, null], [8193, "蕾娜", "「将臣，你也打算……带我去见你父母吗？」", "len426_184.ogg", "朝武_リビングc", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "17"}, "CHAPTER 8-1", null, null], [8194, "将臣", "「嗯……那当然了」", null, "朝武_リビングc", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "17"}, "CHAPTER 8-1", null, null], [8195, "将臣", "「只要你愿意的话」", null, "朝武_リビングc", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "17"}, "CHAPTER 8-1", null, null], [8196, "蕾娜", "「我当然愿意啦！」", "len426_185.ogg", "朝武_リビングc", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "01"}, "CHAPTER 8-1", null, null], [8197, "", "蕾娜紧紧地抱了上来。", null, "朝武_リビングc", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "01"}, "CHAPTER 8-1", null, null], [8198, "蕾娜", "「明天我必须得加油了呀」", "len426_186.ogg", "朝武_リビングc", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "15"}, "CHAPTER 8-1", null, null], [8199, "将臣", "「见父母之前，得先给诅咒画上一个完美的句号才行」", null, "朝武_リビングc", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "15"}, "CHAPTER 8-1", null, null], [8200, "蕾娜", "「嗯…………我说，将臣」", "len426_187.ogg", "朝武_リビングc", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "01"}, "CHAPTER 8-1", null, null], [8201, "将臣", "「怎么了，蕾娜？」", null, "朝武_リビングc", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "01"}, "CHAPTER 8-1", null, null], [8202, "蕾娜", "「那个……我在想……」", "len426_188.ogg", "朝武_リビングc", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "25"}, "CHAPTER 8-1", null, null], [8203, "蕾娜", "「你之所以会把我介绍给你父母，都是因为我们成为了恋人，是吧？」", "len426_189.ogg", "朝武_リビングc", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "03"}, "CHAPTER 8-1", null, null], [8204, "将臣", "「嗯，你把我介绍给你父母，也是因为这个吧？」", null, "朝武_リビングc", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "03"}, "CHAPTER 8-1", null, null], [8205, "蕾娜", "「是的。我们相识之后，也会进一步认识各自的家人」", "len426_190.ogg", "朝武_リビングc", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "27"}, "CHAPTER 8-1", null, null], [8206, "蕾娜", "「就这样，我们又构成了一个更大的家庭」", "len426_191.ogg", "朝武_リビングc", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "19"}, "CHAPTER 8-1", null, null], [8207, "将臣", "「……嗯，说的也是」", null, "朝武_リビングc", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "19"}, "CHAPTER 8-1", null, null], [8208, "蕾娜", "「虽然，我和我的家人……还有你和你的家人」", "len426_192.ogg", "朝武_リビングc", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "25"}, "CHAPTER 8-1", null, null], [8209, "蕾娜", "「大家并不是生活在一起」", "len426_193.ogg", "朝武_リビングc", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "03"}, "CHAPTER 8-1", null, null], [8210, "蕾娜", "「但是……尽管住在不同的地方，也依然有一条纽带连接着我们」", "len426_194.ogg", "朝武_リビングc", "bgm40.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "18"}, "CHAPTER 8-1", null, null], [8211, "", "或许正如蕾娜所说。", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8212, "", "只要我们的交往顺利进行下去，就很有可能建立起那样的关系。", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8213, "", "哪怕各自住在地球的两端，那条纽带也不会被切断。", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8214, "", "比起真正意义上的结合，这样的精神纽带或许才更接近奇迹吧。", null, "朝武_リビングc", "bgm40.opus", null, "CHAPTER 8-1", null, null], [8215, "", "次日清晨，大家在正殿集合。", null, "神社_神社内a", "bgm39.opus", null, "CHAPTER 8-2", null, null], [8216, "", "我手持丛雨丸，与蕾娜一同登殿。", null, "神社_神社内a", "bgm39.opus", null, "CHAPTER 8-2", null, null], [8217, "", "朝武和常陆也是一身正装。", null, "神社_神社内a", "bgm39.opus", null, "CHAPTER 8-2", null, null], [8218, "", "考虑到接下来即将发生的事情，正装可谓是最合适不过的。", null, "神社_神社内a", "bgm39.opus", null, "CHAPTER 8-2", null, null], [8219, "芳乃", "「各位到齐了吧。都休息好了吗？」", "yos427_001.ogg", "神社_神社内a", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "25"}, "CHAPTER 8-2", null, null], [8220, "蕾娜", "「休息好了！芳乃，你准备好了吗」", "len427_001.ogg", "神社_神社内a", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "02"}, "CHAPTER 8-2", null, null], [8221, "芳乃", "「那当然，为了你们俩，我们认真得不能再认真了」", "yos427_002.ogg", "神社_神社内a", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "02"}, "CHAPTER 8-2", null, null], [8222, "将臣", "「……哎，外公也来了啊？」", null, "神社_神社内a", "bgm39.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "17"}, "CHAPTER 8-2", null, null], [8223, "玄十郎", "「因为我听说人越多越好」", "gen427_001.ogg", "神社_神社内a", "bgm39.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "01"}, "CHAPTER 8-2", null, null], [8224, "玄十郎", "「我本来还想把廉太郎和小春叫过来的，只是……」", "gen427_002.ogg", "神社_神社内a", "bgm39.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "18"}, "CHAPTER 8-2", null, null], [8225, "美津叶", "「不行的，就算我们现在跟他们解释情况，他们一时半会恐怕也很难接受这种超自然现象」", "miz427_001.ogg", "神社_神社内a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "05"}, "CHAPTER 8-2", null, null], [8226, "美津叶", "「这就意味着他们不可能充分地认识到仪式的危险，所以不能让他们参加」", "miz427_002.ogg", "神社_神社内a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "29"}, "CHAPTER 8-2", null, null], [8227, "玄十郎", "「就是这么回事」", "gen427_003.ogg", "神社_神社内a", "bgm39.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "07"}, "CHAPTER 8-2", null, null], [8228, "", "原来如此。", null, "神社_神社内a", "bgm39.opus", null, "CHAPTER 8-2", null, null], [8229, "", "不过话说回来，我甚至还不清楚到底要举行什么样的仪式。", null, "神社_神社内a", "bgm39.opus", null, "CHAPTER 8-2", null, null], [8230, "将臣", "「你们之前一直准备的东西是什么来着？」", null, "神社_神社内a", "bgm39.opus", null, "CHAPTER 8-2", null, null], [8231, "芳乃", "「这个……美津叶大夫，麻烦您说明一下吧」", "yos427_003.ogg", "神社_神社内a", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "22"}, "CHAPTER 8-2", null, null], [8232, "美津叶", "「你应该已经看到了，这个就是我们要在仪式中使用的东西」", "miz427_003.ogg", "神社_神社内a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "29"}, "CHAPTER 8-2", null, null], [8233, "", "地板上放着一根非常粗的绳子，上面绑着御币，似乎是注连绳。", null, "神社_神社内a", "bgm39.opus", null, "CHAPTER 8-2", null, null], [8234, "", "神社院子里的树上经常会绑着这种绳子。", null, "神社_神社内a", "bgm39.opus", null, "CHAPTER 8-2", null, null], [8235, "", "但是，我们这注连绳实在太粗，简直无法想象是手工编织的。大家一起做的就是这个吗？", null, "神社_神社内a", "bgm39.opus", null, "CHAPTER 8-2", null, null], [8236, "将臣", "「您之前说要准备一条救生索，原来还真的是一条绳索啊」", null, "神社_神社内a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "05"}, "CHAPTER 8-2", null, null], [8237, "美津叶", "「是的，这种仪式就是要把意图体现到形式上」", "miz427_004.ogg", "神社_神社内a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "06"}, "CHAPTER 8-2", null, null], [8238, "美津叶", "「这样大家才更容易想象这个东西」", "miz427_005.ogg", "神社_神社内a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "02"}, "CHAPTER 8-2", null, null], [8239, "美津叶", "「到了关键时刻，如果大家的心象不统一，那就很难齐心协力了」", "miz427_006.ogg", "神社_神社内a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "05"}, "CHAPTER 8-2", null, null], [8240, "蕾娜", "「原来是这样啊」", "len427_002.ogg", "神社_神社内a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "20"}, "CHAPTER 8-2", null, null], [8241, "", "嗯，这种情况下还是得服从专业人士的安排。", null, "神社_神社内a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "20"}, "CHAPTER 8-2", null, null], [8242, "安晴", "「这根注连绳拉开之后可以围成一个圈」", "yas427_001.ogg", "神社_神社内a", "bgm39.opus", {"char": "安晴", "file": "安晴.stand", "dress": "神主", "face": "06"}, "CHAPTER 8-2", null, null], [8243, "安晴", "「一会儿列支敦瑙尔小姐和将臣要先进入圈内，然后我们就紧紧抱着绳子，围着你们」", "yas427_002.ogg", "神社_神社内a", "bgm39.opus", {"char": "安晴", "file": "安晴.stand", "dress": "神主", "face": "05"}, "CHAPTER 8-2", null, null], [8244, "美津叶", "「只要大家的精神牵绊足够牢固，就算你们陷入意识的深渊之中，也不用害怕」", "miz427_007.ogg", "神社_神社内a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "30"}, "CHAPTER 8-2", null, null], [8245, "美津叶", "「我们可以把你们拉回来」", "miz427_008.ogg", "神社_神社内a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "28"}, "CHAPTER 8-2", null, null], [8246, "将臣", "「也就是说，大家的精神牵绊越牢固，将我们拉回来的力量也会越强？」", null, "神社_神社内a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "28"}, "CHAPTER 8-2", null, null], [8247, "玄十郎", "「是不是再叫几个年轻人过来比较好？」", "gen427_004.ogg", "神社_神社内a", "bgm39.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "07"}, "CHAPTER 8-2", null, null], [8248, "美津叶", "「不，如果人太多，又可能会导致心象难以统一」", "miz427_009.ogg", "神社_神社内a", "bgm39.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "07"}, "CHAPTER 8-2", null, null], [8249, "美津叶", "「要想统一心象，恐怕必须先让他们正确地了解穗织的诅咒」", "miz427_010.ogg", "神社_神社内a", "bgm39.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "07"}, "CHAPTER 8-2", null, null], [8250, "玄十郎", "「唔，那就没办法了」", "gen427_005.ogg", "神社_神社内a", "bgm39.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "01"}, "CHAPTER 8-2", null, null], [8251, "蕾娜", "「没事的，大当家，我相信各位！」", "len427_003.ogg", "神社_神社内a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "17"}, "CHAPTER 8-2", null, null], [8252, "芳乃", "「嗯，这种信任就是我们的精神牵绊」", "yos427_004.ogg", "神社_神社内a", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "21"}, "CHAPTER 8-2", null, null], [8253, "茉子", "「我也相信蕾娜和有地」", "mak427_001.ogg", "神社_神社内a", "bgm39.opus", {"char": "茉子", "file": "茉子.stand", "dress": "忍者口", "face": "29"}, "CHAPTER 8-2", null, null], [8254, "将臣", "「确实，这么一想，就算人少也不怕了」", null, "神社_神社内a", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "21"}, "CHAPTER 8-2", null, null], [8255, "", "仅仅只是目光对视，我们就能从各自的眼神中感受到信任。", null, "神社_神社内a", "bgm39.opus", null, "CHAPTER 8-2", null, null], [8256, "", "在穗织度过的这些日子，我和大家风雨同舟，苦乐同享。", null, "神社_神社内a", "bgm39.opus", null, "CHAPTER 8-2", null, null], [8257, "", "回首这段时光，我愈发觉得这份情谊对我来说有着不同寻常的意义。", null, "神社_神社内a", "bgm39.opus", null, "CHAPTER 8-2", null, null], [8258, "美津叶", "「你们的心态非常好，我也不想扫大家的兴」", "miz427_011.ogg", "神社_神社内a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "21"}, "CHAPTER 8-2", null, null], [8259, "美津叶", "「但是有一点，我必须提前说清楚」", "miz427_012.ogg", "神社_神社内a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "09"}, "CHAPTER 8-2", null, null], [8260, "美津叶", "「这么正式的仪式，我以前从来没布置过。不，应该说就算找遍全日本，恐怕也找不到有过这种经验的人」", "miz427_013.ogg", "神社_神社内a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "09"}, "CHAPTER 8-2", null, null], [8261, "将臣", "「嗯……」", null, "神社_神社内a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "09"}, "CHAPTER 8-2", null, null], [8262, "美津叶", "「驹川家的人，多年来一直专注于如何祓除诅咒」", "miz427_014.ogg", "神社_神社内a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "30"}, "CHAPTER 8-2", null, null], [8263, "美津叶", "「所以那些跟诅咒没什么关系的术式已经荒废得差不多了」", "miz427_015.ogg", "神社_神社内a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "32"}, "CHAPTER 8-2", null, null], [8264, "美津叶", "「恐怕到了我下一辈，我们接下来要举行的这种仪式将会彻底失传」", "miz427_016.ogg", "神社_神社内a", "bgm39.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "33"}, "CHAPTER 8-2", null, null], [8265, "蕾娜", "「也就是说，我们是第一批，同时也是最后一批能够解除诅咒的人吗？」", "len427_004.ogg", "神社_神社内a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "23"}, "CHAPTER 8-2", null, null], [8266, "将臣", "「这责任相当重啊」", null, "神社_神社内a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "23"}, "CHAPTER 8-2", null, null], [8267, "美津叶", "「没错」", "miz427_017.ogg", "神社_神社内a", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "23"}, "CHAPTER 8-2", null, null], [8268, "美津叶", "「但我还是愿意相信这是奇迹！这是我们千辛万苦遇到的唯一一次机会，以前没有，以后也不会有了」", "miz427_018.ogg", "神社_神社内a", "bgm09.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "14"}, "CHAPTER 8-2", null, null], [8269, "蕾娜", "「嗯！只要我们抓住机会，就能在我们这一代解除诅咒了！」", "len427_005.ogg", "神社_神社内a", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "17"}, "CHAPTER 8-2", null, null], [8270, "将臣", "「我觉得，我们真的挺幸运的」", null, "神社_神社内a", "bgm09.opus", null, "CHAPTER 8-2", null, null], [8271, "将臣", "「但这并不是单纯的幸运」", null, "神社_神社内a", "bgm09.opus", null, "CHAPTER 8-2", null, null], [8272, "蕾娜", "「是的。几百年来……数不清的人们流下了数不尽的汗水，我们才能有今天的幸运」", "len427_006.ogg", "神社_神社内a", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "01"}, "CHAPTER 8-2", null, null], [8273, "芳乃", "「……」", "yos427_005.ogg", "神社_神社内a", "bgm09.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "17"}, "CHAPTER 8-2", null, null], [8274, "茉子", "「你说的没错」", "mak427_002.ogg", "神社_神社内a", "bgm09.opus", {"char": "茉子", "file": "茉子.stand", "dress": "忍者口", "face": "34"}, "CHAPTER 8-2", null, null], [8275, "", "不只是丛云。", null, "神社_神社内a", "bgm09.opus", null, "CHAPTER 8-2", null, null], [8276, "", "朝武的先祖，常陆的先祖，以及那些在背后出力的故人们……", null, "神社_神社内a", "bgm09.opus", null, "CHAPTER 8-2", null, null], [8277, "", "大家从不停歇，从不放弃，这份希望才能延续到我们这一代，我们才会有今天。", null, "神社_神社内a", "bgm09.opus", null, "CHAPTER 8-2", null, null], [8278, "", "正因如此，肩上的担子才会如此沉重。", null, "神社_神社内a", "bgm09.opus", null, "CHAPTER 8-2", null, null], [8279, "", "但不可思议的是，我心里没有半点迷茫。", null, "神社_神社内a", "bgm09.opus", null, "CHAPTER 8-2", null, null], [8280, "", "全力以赴吧。用自己的最佳状态，去迎接这一切。", null, "神社_神社内a", "bgm09.opus", null, "CHAPTER 8-2", null, null], [8281, "丛雨", "「那开始吧！首先，要把碎片从主人体内取出来」", "mur427_001.ogg", "神社_神社内a", "bgm09.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "22"}, "CHAPTER 8-2", null, null], [8282, "丛雨", "「然后把它移到蕾娜身体里」", "mur427_002.ogg", "神社_神社内a", "bgm09.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "16"}, "CHAPTER 8-2", null, null], [8283, "蕾娜", "「好的！」\\n「嗯！」", "len427_007.ogg", "神社_神社内a", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 8-2", null, null], [8284, "", "我们走进注连绳圈内后，大家围坐在圈外，紧紧地按着绳子。", null, "神社_神社内a", "bgm09.opus", null, "CHAPTER 8-2", null, null], [8285, "玄十郎", "「只要把这个按着就行了吧？」", "gen427_006.ogg", "神社_神社内a", "bgm09.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "05"}, "CHAPTER 8-2", null, null], [8286, "安晴", "「嗯，拜托你了，玄十郎先生」", "yas427_003.ogg", "神社_神社内a", "bgm09.opus", {"char": "安晴", "file": "安晴.stand", "dress": "神主", "face": "05"}, "CHAPTER 8-2", null, null], [8287, "美津叶", "「其他人也千万不要大意！祟神随时都有可能使出最后的力量殊死抵抗」", "miz427_019.ogg", "神社_神社内a", "bgm09.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "05"}, "CHAPTER 8-2", null, null], [8288, "", "在场的每个人都是一脸紧张。", null, "神社_神社内a", "bgm09.opus", null, "CHAPTER 8-2", null, null], [8289, "蕾娜", "「小雨，我们要怎么把碎片从将臣体内取出来呢？」", "len427_008.ogg", "神社_神社内a", "bgm09.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "08"}, "CHAPTER 8-2", null, null], [8290, "将臣", "「你之前说，是有方法的吧」", null, "神社_神社内a", "bgm09.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "24"}, "CHAPTER 8-2", null, null], [8291, "丛雨", "「嗯，主人之所以睡着时会被吸引到蕾娜的房间」", "mur427_003.ogg", "神社_神社内a", "bgm09.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "22"}, "CHAPTER 8-2", null, null], [8292, "丛雨", "「都是因为主人的碎片，被蕾娜的碎片吸引过去了」", "mur427_004.ogg", "神社_神社内a", "bgm09.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "11"}, "CHAPTER 8-2", null, null], [8293, "丛雨", "「只要主人心里的愿望足够强烈，碎片自然而然就会脱离你的身体，进入蕾娜体内」", "mur427_005.ogg", "神社_神社内a", "bgm09.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "17"}, "CHAPTER 8-2", null, null], [8294, "将臣", "「愿望足够强烈……那我只用祈祷它们快点复原就行了吗？」", null, "神社_神社内a", "bgm09.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "17"}, "CHAPTER 8-2", null, null], [8295, "丛雨", "「嗯。你先试着用心感受自己体内的碎片吧」", "mur427_006.ogg", "神社_神社内a", "bgm09.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "01"}, "CHAPTER 8-2", null, null], [8296, "将臣", "「好的……」", null, "神社_神社内a", "bgm09.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "01"}, "CHAPTER 8-2", null, null], [8297, "", "我闭上了眼睛。", null, "画面_黒", "bgm36.opus", null, "CHAPTER 8-2", null, null], [8298, "", "我体内有一块碎片。", null, "画面_黒", "bgm36.opus", null, "CHAPTER 8-2", null, null], [8299, "", "虽然小雨一直这么说，但我还没有见到过实物。", null, "画面_黒", "bgm36.opus", null, "CHAPTER 8-2", null, null], [8300, "", "所以，之前我心里总是有点半信半疑。", null, "画面_黒", "bgm36.opus", null, "CHAPTER 8-2", null, null], [8301, "", "但是现在，我内心相当振奋。因为我已经知道了许多人心中的思念。", null, "画面_黒", "bgm36.opus", null, "CHAPTER 8-2", null, null], [8302, "", "其中还包括那位白狛，也就是祟神的原形。", null, "画面_黒", "bgm36.opus", null, "CHAPTER 8-2", null, null], [8303, "", "我想为你做点什么。", null, "画面_黒", "bgm36.opus", null, "CHAPTER 8-2", null, null], [8304, "", "如今这一切，应该并不是你真心希望的吧？", null, "画面_黒", "bgm36.opus", null, "CHAPTER 8-2", null, null], [8305, "", "如果不是，就请你做出回应。", null, "画面_黒", "bgm36.opus", null, "CHAPTER 8-2", null, null], [8306, "", "为了终结这一切，请助我们一臂之力！", null, "画面_黒", "bgm36.opus", null, "CHAPTER 8-2", null, null], [8307, "丛雨", "「喔！」", "mur427_007.ogg", "神社_神社内a", "bgm26.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "04"}, "CHAPTER 8-2", null, null], [8308, "将臣", "「碎……碎片真的出来了！？」", null, "神社_神社内a", "bgm26.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "04"}, "CHAPTER 8-2", null, null], [8309, "", "不知不觉，碎片已经躺在我手心，散发着淡淡的光辉。", null, "神社_神社内a", "bgm26.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "04"}, "CHAPTER 8-2", null, null], [8310, "蕾娜", "「将臣，碎片真的出来了！」", "len427_009.ogg", "神社_神社内a", "bgm26.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "24"}, "CHAPTER 8-2", null, null], [8311, "将臣", "「嗯，然后把这个给你就……哎？」", null, "神社_神社内a", "bgm26.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "24"}, "CHAPTER 8-2", null, null], [8312, "", "碎片竟然浮了起来。", null, "神社_神社内a", "bgm12.opus", null, "CHAPTER 8-2", null, null], [8313, "", "浮起来之后，直接朝蕾娜的身体飞了过去。", null, "神社_神社内a", "bgm12.opus", null, "CHAPTER 8-2", null, null], [8314, "", "简直就像石子被投进水池一样，碎片轻而易举地被吸了进去。", null, "神社_神社内a", "bgm12.opus", null, "CHAPTER 8-2", null, null], [8315, "蕾娜", "「喔，喔喔，真的进到我身体里来了……」", "len427_010.ogg", "神社_神社内a", "bgm12.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "12"}, "CHAPTER 8-2", null, null], [8316, "将臣", "「蕾娜！？你没事吧，蕾娜！」", null, "神社_神社内a", "bgm12.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "12"}, "CHAPTER 8-2", null, null], [8317, "", "蕾娜的神情突然变得有些奇怪。", null, "神社_神社内a", "bgm12.opus", null, "CHAPTER 8-2", null, null], [8318, "", "她两眼空洞无神，简直就像被谁操控了一样，我们叫她，她也没反应。", null, "神社_神社内a", "bgm12.opus", null, "CHAPTER 8-2", null, null], [8319, "丛雨", "「糟了，要来了！」", "mur427_008.ogg", "神社_神社内a", "bgm12.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "11"}, "CHAPTER 8-2", null, null], [8320, "蕾娜？", "「唔啊啊啊啊啊啊啊啊！！」", "srk427_001.ogg", "神社_神社内a", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8321, "", "从蕾娜口中传出一阵咆哮，这声音完全不像是蕾娜发出来的。", null, "神社_神社内a", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8322, "", "这是祟神的咆哮！？", null, "神社_神社内a", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8323, "", "由５个人按住的注连绳突然被震得腾空而起，几米高的波浪上下起伏。", null, "神社_神社内a", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8324, "安晴", "「啊！？」", "yas427_004.ogg", "神社_神社内a", "bgm30.opus", {"char": "安晴", "file": "安晴.stand", "dress": "神主", "face": "07"}, "CHAPTER 8-2", null, null], [8325, "芳乃", "「……哎？」", "yos427_006.ogg", "神社_神社内a", "bgm30.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "32"}, "CHAPTER 8-2", null, null], [8326, "", "不是吧！？三个大人的身体，竟然就像甩布片一样，被轻而易举地震飞了。", null, "神社_神社内a", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8327, "美津叶", "「绝、绝对不能松手……唔啊！？」", "miz427_020.ogg", "神社_神社内a", "bgm30.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "15"}, "CHAPTER 8-2", null, null], [8328, "", "多亏了驹川大夫的喊叫，在场没有一个人松开手。", null, "神社_神社内a", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8329, "", "但她自己却因为分神而落地不稳，不小心撞到了头。", null, "神社_神社内a", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8330, "将臣", "「驹川大夫！驹川大夫！」", null, "神社_神社内a", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8331, "美津叶", "「…………」", "miz427_021.ogg", "神社_神社内a", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8332, "", "还有反应。", null, "神社_神社内a", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8333, "", "但她似乎无法回答我的问题，可能是意识有些朦胧。", null, "神社_神社内a", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8334, "芳乃", "「爸爸！爸爸，你没事吧」", "yos427_007.ogg", "神社_神社内a", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8335, "安晴", "「呃……唔」", "yas427_005.ogg", "神社_神社内a", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8336, "", "安晴叔叔也是一样。", null, "神社_神社内a", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8337, "", "尽管意识有些朦胧，但他们都像豁出了性命一样，牢牢地抓着注连绳。", null, "神社_神社内a", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8338, "", "然而，注连绳依然像一条蛇一样不停地打着波浪，没人知道大家能坚持到什么时候。", null, "神社_神社内a", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8339, "丛雨", "「保持冷静！你们忘记驹川说的话了吗？不要拼膂力，要依靠大家的精神牵绊来压制它」", "mur427_009.ogg", "神社_神社内a", "bgm30.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "14"}, "CHAPTER 8-2", null, null], [8340, "丛雨", "「芳乃，你的牵绊是最牢固的！无论如何你也不能松手」", "mur427_010.ogg", "神社_神社内a", "bgm30.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "28"}, "CHAPTER 8-2", null, null], [8341, "芳乃", "「好、好的！」", "yos427_008.ogg", "神社_神社内a", "bgm30.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "35"}, "CHAPTER 8-2", null, null], [8342, "", "朝武用双臂抱紧了注连绳。", null, "神社_神社内a", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8343, "丛雨", "「其他人，你们必须尽量帮芳乃减轻负担！听好了，本座知道这很难」", "mur427_011.ogg", "神社_神社内a", "bgm30.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "10"}, "CHAPTER 8-2", null, null], [8344, "丛雨", "「但你们一定要死死按住啊！茉子，把本座说的话告诉大家」", "mur427_012.ogg", "神社_神社内a", "bgm30.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "14"}, "CHAPTER 8-2", null, null], [8345, "茉子", "「明白……这仪式真的是相当辛苦啊」", "mak427_003.ogg", "神社_神社内a", "bgm30.opus", {"char": "茉子", "file": "茉子.stand", "dress": "忍者口", "face": "45"}, "CHAPTER 8-2", null, null], [8346, "", "武艺过人的常陆，额头上也是挂满了汗珠。", null, "神社_神社内a", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8347, "", "真没想到，竟会遭到如此激烈的抵抗……本以为碎片回应了我的心愿，看来并不是。", null, "神社_神社内a", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8348, "将臣", "「小雨！我是不是也帮忙按着注连绳比较好？」", null, "神社_神社内a", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8349, "将臣", "「论精神牵绊，没人比得上我」", null, "神社_神社内a", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8350, "玄十郎", "「……说什么傻话」", "gen427_007.ogg", "神社_神社内a", "bgm30.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "01"}, "CHAPTER 8-2", null, null], [8351, "将臣", "「外公！你没事吧？」", null, "神社_神社内a", "bgm30.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "01"}, "CHAPTER 8-2", null, null], [8352, "", "外公似乎是三位大人中第一个恢复过来的。", null, "神社_神社内a", "bgm30.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "01"}, "CHAPTER 8-2", null, null], [8353, "玄十郎", "「我这身功夫可不是白练的，还轮不到你来操心」", "gen427_008.ogg", "神社_神社内a", "bgm30.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "18"}, "CHAPTER 8-2", null, null], [8354, "玄十郎", "「先别管这个，你别忘了你的目的」", "gen427_009.ogg", "神社_神社内a", "bgm30.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "04"}, "CHAPTER 8-2", null, null], [8355, "将臣", "「这个……」", null, "神社_神社内a", "bgm30.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "04"}, "CHAPTER 8-2", null, null], [8356, "茉子", "「没错，这是我们的任务，你就交给我们吧」", "mak427_004.ogg", "神社_神社内a", "bgm30.opus", {"char": "茉子", "file": "茉子.stand", "dress": "忍者口", "face": "41"}, "CHAPTER 8-2", null, null], [8357, "丛雨", "「蕾娜现在的状态，大概跟她第一次被祟神操控时是一样的」", "mur427_013.ogg", "神社_神社内a", "bgm30.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "11"}, "CHAPTER 8-2", null, null], [8358, "丛雨", "「也就是说，她现在身处梦境之中！」", "mur427_014.ogg", "神社_神社内a", "bgm30.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "28"}, "CHAPTER 8-2", null, null], [8359, "芳乃", "「是的，有地的任务就是进入梦境，把她带回来！」", "yos427_009.ogg", "神社_神社内a", "bgm30.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "07"}, "CHAPTER 8-2", null, null], [8360, "将臣", "「可是……现在这个情况下，我真的能睡着吗」", null, "神社_神社内a", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8361, "丛雨", "「不必担心！丛雨丸应该是知道方法的」", "mur427_015.ogg", "神社_神社内a", "bgm30.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "22"}, "CHAPTER 8-2", null, null], [8362, "丛雨", "「虽然本座不能陪你一起去，但可以送你过去」", "mur427_016.ogg", "神社_神社内a", "bgm30.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "22"}, "CHAPTER 8-2", null, null], [8363, "将臣", "「那就太好了……」", null, "神社_神社内a", "bgm30.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "22"}, "CHAPTER 8-2", null, null], [8364, "", "不过，现在这个状况，大家真的能坚持下去吗？", null, "神社_神社内a", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8365, "", "毕竟我有可能一去就是几个小时。", null, "神社_神社内a", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8366, "美津叶", "「唔……你就放心去吧……」", "miz427_022.ogg", "神社_神社内a", "bgm30.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "10"}, "CHAPTER 8-2", null, null], [8367, "美津叶", "「只要我们都不松手，哪怕是祟神，也不可能把列支敦瑙尔小姐带出这个圈」", "miz427_023.ogg", "神社_神社内a", "bgm30.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "14"}, "CHAPTER 8-2", null, null], [8368, "将臣", "「驹川大夫，您没事吧！」", null, "神社_神社内a", "bgm30.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "14"}, "CHAPTER 8-2", null, null], [8369, "美津叶", "「就算我说没事，大概也没什么说服力」", "miz427_024.ogg", "神社_神社内a", "bgm30.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "23"}, "CHAPTER 8-2", null, null], [8370, "美津叶", "「唉……有时候我一想到自己是个大人，心里就很烦」", "miz427_025.ogg", "神社_神社内a", "bgm30.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "26"}, "CHAPTER 8-2", null, null], [8371, "美津叶", "「本来，我最不想成为的……就是那种一到关键时刻就拖后腿的大人」", "miz427_026.ogg", "神社_神社内a", "bgm30.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "32"}, "CHAPTER 8-2", null, null], [8372, "安晴", "「您说笑了……我才应该反省，真不该摆成年人的架子，说什么交给年轻人……」", "yas427_006.ogg", "神社_神社内a", "bgm30.opus", {"char": "安晴", "file": "安晴.stand", "dress": "神主", "face": "10"}, "CHAPTER 8-2", null, null], [8373, "安晴", "「我当初……就应该多跟大家加深下感情才是」", "yas427_007.ogg", "神社_神社内a", "bgm30.opus", {"char": "安晴", "file": "安晴.stand", "dress": "神主", "face": "09"}, "CHAPTER 8-2", null, null], [8374, "玄十郎", "「能这么想，就说明二位还很年轻」", "gen427_010.ogg", "神社_神社内a", "bgm30.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "03"}, "CHAPTER 8-2", null, null], [8375, "玄十郎", "「将臣！」", "gen427_011.ogg", "神社_神社内a", "bgm30.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "14"}, "CHAPTER 8-2", null, null], [8376, "玄十郎", "「快去吧」", "gen427_012.ogg", "神社_神社内a", "bgm30.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "15"}, "CHAPTER 8-2", null, null], [8377, "将臣", "「外公……」", null, "神社_神社内a", "bgm30.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "15"}, "CHAPTER 8-2", null, null], [8378, "", "外公选择了相信我。", null, "神社_神社内a", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8379, "", "是啊，我到底在犹豫什么。正因为那些大人们一直坚持到今天，我们才终于有了机会，这些我岂会忘记！", null, "神社_神社内a", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8380, "", "想必祖先们也是这样一路奋战至今。即便危险近在咫尺，稍有差池便是灭顶之灾，他们也从未放弃。", null, "神社_神社内a", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8381, "", "百年夙愿是成是败，就看我的表现了。", null, "神社_神社内a", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8382, "", "不必慌张，大人们已经把需要的都教给我了，没有什么我做不到的。", null, "神社_神社内a", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8383, "将臣", "「好的，你们放心吧！」", null, "神社_神社内a", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8384, "将臣", "「小雨，开始吧！」", null, "神社_神社内a", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8385, "丛雨", "「嗯！你先紧握丛雨丸，然后集中注意力」", "mur427_017.ogg", "神社_神社内a", "bgm30.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "11"}, "CHAPTER 8-2", null, null], [8386, "", "我闭上眼睛，照着小雨说的做。", null, "神社_神社内a", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8387, "芳乃", "「有地」", "yos427_010.ogg", "神社_神社内a", "bgm30.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "33"}, "CHAPTER 8-2", null, null], [8388, "芳乃", "「请务必把我们的好朋友带回来，拜托了」", "yos427_011.ogg", "神社_神社内a", "bgm30.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "25"}, "CHAPTER 8-2", null, null], [8389, "", "诅咒的事，朝武一个字都没提。", null, "神社_神社内a", "bgm30.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "25"}, "CHAPTER 8-2", null, null], [8390, "", "对我们来说，这场战斗是为了恋人，也是为了朋友。", null, "神社_神社内a", "bgm30.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "25"}, "CHAPTER 8-2", null, null], [8391, "将臣", "「嗯，等我们回来了，大家再办一场睡衣派对！」", null, "神社_神社内a", "bgm30.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "25"}, "CHAPTER 8-2", null, null], [8392, "将臣", "「这次再办，我希望你能陪我们到最后」", null, "神社_神社内a", "bgm30.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "25"}, "CHAPTER 8-2", null, null], [8393, "芳乃", "「嗯，我很期待那一天」", "yos427_012.ogg", "神社_神社内a", "bgm30.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "巫女服", "face": "02"}, "CHAPTER 8-2", null, null], [8394, "丛雨", "「要传送了，主人！本座这长达４００多年的战斗，终该有个了断」", "mur427_018.ogg", "神社_神社内a", "bgm30.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "34"}, "CHAPTER 8-2", null, null], [8395, "丛雨", "「此事也拜托你了！」", "mur427_019.ogg", "神社_神社内a", "bgm30.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "10"}, "CHAPTER 8-2", null, null], [8396, "将臣", "「嗯！」", null, "神社_神社内a", "bgm30.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "10"}, "CHAPTER 8-2", null, null], [8397, "", "刚说罢，我的身体就浮了起来。紧接着，一股飞向远方的感觉穿过全身。", null, "空_青空", "bgm36.opus", null, "CHAPTER 8-2", null, null], [8398, "", "我仿佛坠入了记忆的旋涡，数不尽的记忆片段开始在我脑中闪回。", null, "空_青空", "bgm36.opus", null, "CHAPTER 8-2", null, null], [8399, "", "——战国时代", null, "空_青空", "bgm36.opus", null, "CHAPTER 8-2", null, null], [8400, "", "本是兄弟之争——最终却演变为燎原战火。", null, "空_青空", "bgm36.opus", null, "CHAPTER 8-2", null, null], [8401, "白狛", "『住手，快住手！』", "srk427_002.ogg", "山_川沿いa", "bgm27.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8402, "", "是一阵拼命劝阻的声音。", null, "山_川沿いa", "bgm27.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8403, "男性", "「闭嘴！你这狗崽子整天进我梦里，真是晦气！！」", "onn427_001.ogg", "山_川沿いa", "bgm27.opus", null, "CHAPTER 8-2", null, null], [8404, "", "一位全身穿着盔甲的武士正拿着刀乱挥。", null, "山_川沿いa", "bgm27.opus", null, "CHAPTER 8-2", null, null], [8405, "", "我记得之前也在梦中见过他。", null, "山_川沿いa", "bgm27.opus", null, "CHAPTER 8-2", null, null], [8406, "", "难道他就是引起家族内讧的那个人？", null, "山_川沿いa", "bgm27.opus", null, "CHAPTER 8-2", null, null], [8407, "白狛", "「（这可不妙……既要阻止他，又不得伤他，我该如何是好？」", "srk427_003.ogg", "山_川沿いa", "bgm27.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8408, "", "白狛到底还是丛云的弟弟。", null, "山_川沿いa", "bgm27.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8409, "男性", "「你这死狗，这点本事还想跟我斗！」", "onn427_002.ogg", "山_川沿いa", "bgm27.opus", null, "CHAPTER 8-2", null, null], [8410, "白狛", "『什么！？』", "srk427_004.ogg", "山_川沿いa", "bgm27.opus", null, "CHAPTER 8-2", null, null], [8411, "", "一个不留神，白狛挂在颈部的绳子被武士斩落——那根绳子上，串着他一直贴身携带的玉石。", null, "山_川沿いa", "bgm27.opus", null, "CHAPTER 8-2", null, null], [8412, "", "武士见白狛想取回玉石，就知道这玉石对他意义非凡。", null, "山_川沿いa", "bgm27.opus", null, "CHAPTER 8-2", null, null], [8413, "", "于是，他就像利用人质一样，卑鄙地利用这一点要挟白狛。", null, "山_川沿いa", "bgm27.opus", null, "CHAPTER 8-2", null, null], [8414, "", "就这样，直到白狛身首异处……他都没能对朝武家的人动手。", null, "山_川沿いa", "bgm27.opus", null, "CHAPTER 8-2", null, null], [8415, "", "然而接下来发生的一切，让他对自己的仁慈懊悔不已。", null, "山_川沿いa", "bgm27.opus", null, "CHAPTER 8-2", null, null], [8416, "白狛", "『你们在干什么！住手……不要利用姐姐大人做这种事！』", "srk427_005.ogg", "山_川沿いa", "bgm27.opus", {"char": "白狛", "file": "白狛.stand", "dress": "犬", "face": "03"}, "CHAPTER 8-2", null, null], [8417, "白狛", "『你们竟敢以我为祭品，以姐姐大人为宿体，发动诅咒……啊啊啊、啊啊啊啊啊！！！』", "srk427_006.ogg", "山_川沿いa", "bgm27.opus", {"char": "白狛", "file": "白狛.stand", "dress": "犬", "face": "03"}, "CHAPTER 8-2", null, null], [8418, "白狛", "『要杀我随你……但是不要把姐姐大人……不要把姐姐大人……你这混蛋！』", "srk427_007.ogg", "山_川沿いa", "bgm27.opus", {"char": "白狛", "file": "白狛.stand", "dress": "犬", "face": "03"}, "CHAPTER 8-2", null, null], [8419, "白狛", "『姐姐大人守护你们这么多年，你们考虑过她的感受吗！我决不饶你们，决不饶你们，决不饶你们！！』", "srk427_008.ogg", "山_川沿いa", "bgm27.opus", {"char": "白狛", "file": "白狛.stand", "dress": "犬", "face": "03"}, "CHAPTER 8-2", null, null], [8420, "白狛", "『才过了区区数百年，你们就如此忘恩负义……甚至对我们做出此等不肖之事』", "srk427_009.ogg", "山_川沿いa", "bgm27.opus", {"char": "白狛", "file": "白狛.stand", "dress": "犬", "face": "02"}, "CHAPTER 8-2", null, null], [8421, "白狛", "『简直天理难容！！我发誓永远、永远都不会原谅你们！！！』", "srk427_010.ogg", "山_川沿いa", "bgm27.opus", {"char": "白狛", "file": "白狛.stand", "dress": "犬", "face": "03"}, "CHAPTER 8-2", null, null], [8422, "", "最终，他看得比自己性命还要宝贵的玉石被打得粉碎。下手的依然是朝武家的人。", null, "山_山の中２b", "bgm27.opus", {"char": "白狛", "file": "白狛.stand", "dress": "犬", "face": "03"}, "CHAPTER 8-2", null, null], [8423, "", "玉石的碎片全部都被撒在了穗织的后山上。", null, "山_山の中２b", "bgm27.opus", {"char": "白狛", "file": "白狛.stand", "dress": "犬", "face": "03"}, "CHAPTER 8-2", null, null], [8424, "", "至此，白狛已经无法正常思考了。", null, "山_山の中２b", "bgm27.opus", {"char": "白狛", "file": "白狛.stand", "dress": "犬", "face": "03"}, "CHAPTER 8-2", null, null], [8425, "", "就连怨恨和失望，恩情和关爱都碎成了一抔尘土。", null, "山_山の中２b", "bgm27.opus", {"char": "白狛", "file": "白狛.stand", "dress": "犬", "face": "03"}, "CHAPTER 8-2", null, null], [8426, "", "一颗颗意识的碎片并不具备抵抗现实的能力，强大的诅咒几乎抹掉了他的一切。", null, "山_山の中２b", "bgm27.opus", {"char": "白狛", "file": "白狛.stand", "dress": "犬", "face": "03"}, "CHAPTER 8-2", null, null], [8427, "侍女", "「呜……呜……您这么年轻就去世了……您的孩子，还这么小呢……」", "jij427_001.ogg", "特殊_武家屋敷d", "bgm27.opus", {"char": "白狛", "file": "白狛.stand", "dress": "犬", "face": "03"}, "CHAPTER 8-2", null, null], [8428, "朝武氏", "「我知道这是命运……我早就知道了，但是为什么？为什么偏偏只有朝武家的人要忍受这般命运……」", "tmt427_001.ogg", "特殊_武家屋敷d", "bgm27.opus", {"char": "白狛", "file": "白狛.stand", "dress": "犬", "face": "03"}, "CHAPTER 8-2", null, null], [8429, "", "成为祟神之后，白狛一次又一次地目睹一个又一个短命的朝武家人。", null, "特殊_武家屋敷d", "bgm27.opus", {"char": "白狛", "file": "白狛.stand", "dress": "犬", "face": "03"}, "CHAPTER 8-2", null, null], [8430, "", "每一次，他都能看见朝武的家臣们泣不成声，但他却体会不到任何成就感。", null, "特殊_武家屋敷d", "bgm27.opus", {"char": "白狛", "file": "白狛.stand", "dress": "犬", "face": "03"}, "CHAPTER 8-2", null, null], [8431, "", "因此，哪怕他的诅咒夺走再多人的性命，他的怨恨也从未平息。", null, "特殊_武家屋敷d", "bgm27.opus", {"char": "白狛", "file": "白狛.stand", "dress": "犬", "face": "03"}, "CHAPTER 8-2", null, null], [8432, "", "只是偶尔，他那四分五裂的思绪之中会传来这样一句话——", null, "特殊_武家屋敷d", "bgm27.opus", {"char": "白狛", "file": "白狛.stand", "dress": "犬", "face": "03"}, "CHAPTER 8-2", null, null], [8433, "", "「不可过分憎恶人类」", null, "特殊_武家屋敷d", "bgm27.opus", {"char": "白狛", "file": "白狛.stand", "dress": "犬", "face": "03"}, "CHAPTER 8-2", null, null], [8434, "", "这个世上，已经没有谁能劝阻他了。再也找不到这样的人了……心中留下的，仅仅只剩一抹空虚。", null, "特殊_武家屋敷d", "bgm27.opus", {"char": "白狛", "file": "白狛.stand", "dress": "犬", "face": "03"}, "CHAPTER 8-2", null, null], [8435, "", "过去，祟神之所以闯进城镇，伤及居民，恐怕也是因为这番心境。", null, "特殊_武家屋敷d", "bgm27.opus", {"char": "白狛", "file": "白狛.stand", "dress": "犬", "face": "03"}, "CHAPTER 8-2", null, null], [8436, "将臣", "「（呃……唔，蕾娜？）」", null, "特殊_武家屋敷d", "bgm27.opus", {"char": "白狛", "file": "白狛.stand", "dress": "犬", "face": "03"}, "CHAPTER 8-2", null, null], [8437, "", "我终于恢复了意识。", null, "特殊_武家屋敷d", "bgm27.opus", {"char": "白狛", "file": "白狛.stand", "dress": "犬", "face": "03"}, "CHAPTER 8-2", null, null], [8438, "", "也许是由于小雨送我过来的方式有些勉强，我刚才就像置身于快进的录像带之中一样。", null, "特殊_武家屋敷d", "bgm27.opus", {"char": "白狛", "file": "白狛.stand", "dress": "犬", "face": "03"}, "CHAPTER 8-2", null, null], [8439, "", "内容倒是跟我想象中的差不多，但我始终没能找到蕾娜。", null, "特殊_武家屋敷d", "bgm27.opus", {"char": "白狛", "file": "白狛.stand", "dress": "犬", "face": "03"}, "CHAPTER 8-2", null, null], [8440, "将臣", "「（蕾娜！你在哪啊，蕾娜！？）」", null, "特殊_武家屋敷d", "bgm27.opus", {"char": "白狛", "file": "白狛.stand", "dress": "犬", "face": "03"}, "CHAPTER 8-2", null, null], [8441, "", "没人回答我。难道她不在附近？", null, "特殊_武家屋敷d", "bgm27.opus", {"char": "白狛", "file": "白狛.stand", "dress": "犬", "face": "03"}, "CHAPTER 8-2", null, null], [8442, "", "每当我们来到梦境，她的意识一般都会进入丛云的身体里。", null, "特殊_武家屋敷d", "bgm27.opus", {"char": "白狛", "file": "白狛.stand", "dress": "犬", "face": "03"}, "CHAPTER 8-2", null, null], [8443, "", "但是现在，丛云已经……不，等等。", null, "特殊_武家屋敷d", "bgm27.opus", {"char": "白狛", "file": "白狛.stand", "dress": "犬", "face": "03"}, "CHAPTER 8-2", null, null], [8444, "将臣", "「（难道，蕾娜在宿体里面？）」", null, "特殊_武家屋敷d", "bgm27.opus", {"char": "白狛", "file": "白狛.stand", "dress": "犬", "face": "03"}, "CHAPTER 8-2", null, null], [8445, "", "要真是如此，她的意识也会跟着碎成无数个碎片，被撒在山上！", null, "特殊_武家屋敷d", "bgm27.opus", {"char": "白狛", "file": "白狛.stand", "dress": "犬", "face": "03"}, "CHAPTER 8-2", null, null], [8446, "将臣", "「（蕾娜！蕾娜！）」", null, "山_山道c", "bgm28.opus", {"char": "白狛", "file": "白狛.stand", "dress": "犬", "face": "03"}, "CHAPTER 8-2", null, null], [8447, "", "我急忙赶到山上。", null, "山_山道c", "bgm28.opus", {"char": "白狛", "file": "白狛.stand", "dress": "犬", "face": "03"}, "CHAPTER 8-2", null, null], [8448, "", "最开始，我感觉自己就像单凭意识在天上飞一样。", null, "山_山道c", "bgm28.opus", {"char": "白狛", "file": "白狛.stand", "dress": "犬", "face": "03"}, "CHAPTER 8-2", null, null], [8449, "", "但是随后，我渐渐有了两脚落地，血液流淌的感觉。", null, "山_山道c", "bgm28.opus", {"char": "白狛", "file": "白狛.stand", "dress": "犬", "face": "03"}, "CHAPTER 8-2", null, null], [8450, "", "不知不觉，我已经开始在地上奔跑，手中也握着丛雨丸。", null, "山_山道c", "bgm28.opus", {"char": "白狛", "file": "白狛.stand", "dress": "犬", "face": "03"}, "CHAPTER 8-2", null, null], [8451, "", "至今为止，除了和梦中的人物合体的时候，我们一直都是意识浮在半空中，俯瞰这个世界。", null, "山_山道c", "bgm28.opus", {"char": "白狛", "file": "白狛.stand", "dress": "犬", "face": "03"}, "CHAPTER 8-2", null, null], [8452, "", "当时的我们，仅仅就是个阅览他人记忆的旁观者而已。", null, "山_山道c", "bgm28.opus", {"char": "白狛", "file": "白狛.stand", "dress": "犬", "face": "03"}, "CHAPTER 8-2", null, null], [8453, "", "但是，这次我也有了自己的身体。", null, "山_山道c", "bgm28.opus", {"char": "白狛", "file": "白狛.stand", "dress": "犬", "face": "03"}, "CHAPTER 8-2", null, null], [8454, "", "这种变化……到底意味着什么？", null, "山_山道c", "bgm28.opus", {"char": "白狛", "file": "白狛.stand", "dress": "犬", "face": "03"}, "CHAPTER 8-2", null, null], [8455, "", "这时，我突然感觉背后有危险。", null, "山_山道c", "bgm28.opus", {"char": "白狛", "file": "白狛.stand", "dress": "犬", "face": "03"}, "CHAPTER 8-2", null, null], [8456, "将臣", "「什么！那黑漆漆的泥团……！？」", null, "山_山道c", "bgm28.opus", {"char": "白狛", "file": "白狛.stand", "dress": "犬", "face": "03"}, "CHAPTER 8-2", null, null], [8457, "", "是祟神！难道它们在追我？", null, "山_山道c", "bgm28.opus", {"char": "白狛", "file": "白狛.stand", "dress": "犬", "face": "03"}, "CHAPTER 8-2", null, null], [8458, "", "而且就连祟神也似乎有了实体。", null, "山_山道c", "bgm28.opus", {"char": "白狛", "file": "白狛.stand", "dress": "犬", "face": "03"}, "CHAPTER 8-2", null, null], [8459, "", "果然，在这场由记忆编织的梦境中，他自己也参与了进来。", null, "山_山道c", "bgm28.opus", {"char": "白狛", "file": "白狛.stand", "dress": "犬", "face": "03"}, "CHAPTER 8-2", null, null], [8460, "", "我们为了和祟神做个了断，故意让他取回了自己的全部力量。", null, "山_山道c", "bgm28.opus", {"char": "白狛", "file": "白狛.stand", "dress": "犬", "face": "03"}, "CHAPTER 8-2", null, null], [8461, "", "但是现在，我还不打算和他兵刃相见。", null, "山_山道c", "bgm28.opus", {"char": "白狛", "file": "白狛.stand", "dress": "犬", "face": "03"}, "CHAPTER 8-2", null, null], [8462, "", "如果要让神灵的荒魂息怒，这是最合适的选择。", null, "山_山道c", "bgm28.opus", {"char": "白狛", "file": "白狛.stand", "dress": "犬", "face": "03"}, "CHAPTER 8-2", null, null], [8463, "将臣", "「为了我们的目的，我必须首先找到蕾娜！」", null, "山_山道c", "bgm28.opus", {"char": "白狛", "file": "白狛.stand", "dress": "犬", "face": "03"}, "CHAPTER 8-2", null, null], [8464, "", "如果这次的情况和蕾娜之前被操控时一样，那她恐怕也在那个地方。", null, "山_山道c", "bgm28.opus", {"char": "白狛", "file": "白狛.stand", "dress": "犬", "face": "03"}, "CHAPTER 8-2", null, null], [8465, "蕾娜", "「…………」", "len427_011.ogg", "山_山の中１c", "bgm28.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "33"}, "CHAPTER 8-2", null, null], [8466, "将臣", "「找到了！」", null, "山_山の中１c", "bgm28.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "33"}, "CHAPTER 8-2", null, null], [8467, "", "蕾娜也跟我一样，有自己的实体。", null, "山_山の中１c", "bgm28.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "33"}, "CHAPTER 8-2", null, null], [8468, "", "但是她的神情有些不对劲。", null, "山_山の中１c", "bgm28.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "33"}, "CHAPTER 8-2", null, null], [8469, "", "难不成，她虽然有实体，但意识却跟宿体一起碎得四分五裂了？", null, "山_山の中１c", "bgm28.opus", null, "CHAPTER 8-2", null, null], [8470, "", "我身后应该有很多祟神在步步紧逼。", null, "山_山の中１c", "bgm28.opus", null, "CHAPTER 8-2", null, null], [8471, "", "而且我们上一次追赶被祟神操控的蕾娜时，最终也是来到了这里。", null, "山_山の中１c", "bgm28.opus", null, "CHAPTER 8-2", null, null], [8472, "", "也就是说，接下来……", null, "山_山の中１c", "bgm28.opus", null, "CHAPTER 8-2", null, null], [8473, "", "突然，整座山都震了起来。", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8474, "将臣", "「果然！」", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8475, "", "虽然距离很远，但我依然能清楚地看见大批祟神出现在各个地方，并且一齐向我们这边涌了过来。", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8476, "", "也就是说，刚才追我的祟神也仅仅只是在朝蕾娜这边集合而已？", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8477, "", "但是祟神为什么会这样死死追着蕾娜不放？", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8478, "", "宿体已经复原，白狛的意识应该也完整了。他应该能明白，蕾娜并不是丛云，只是金发有点像而已。", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8479, "", "不，现在先不考虑这些了。", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8480, "将臣", "「蕾娜！蕾娜！！」", null, "山_山の中１c", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "33"}, "CHAPTER 8-2", null, null], [8481, "蕾娜", "「…………」", "len427_012.ogg", "山_山の中１c", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "33"}, "CHAPTER 8-2", null, null], [8482, "", "不行，她根本没反应！既然如此，就只能扛着她逃跑了吗？", null, "山_山の中１c", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "33"}, "CHAPTER 8-2", null, null], [8483, "", "然而祟神渐渐围起了圆阵，挡住了我们的去路。", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8484, "", "它们竟然不攻过来？不，感觉它们就像是在避免上次的失误一样。", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8485, "", "它们的行动非常有秩序。", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8486, "", "但也正因如此，我们只能这样对峙。必须赶快想想办法。", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8487, "将臣", "「唔，万一蕾娜的意识真的是跟宿体一起四散……对了！」", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8488, "将臣", "「蕾娜！你能听见吗？」", null, "山_山の中１c", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "33"}, "CHAPTER 8-2", null, null], [8489, "将臣", "「宿体已经复原了！也就是说，宿体就在你体内」", null, "山_山の中１c", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "33"}, "CHAPTER 8-2", null, null], [8490, "", "之前哪怕我们身处梦境，我的身体也依然能感受到蕾娜的体温。", null, "山_山の中１c", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "33"}, "CHAPTER 8-2", null, null], [8491, "", "当然了，梦境和现实是不一样的。", null, "山_山の中１c", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "33"}, "CHAPTER 8-2", null, null], [8492, "将臣", "「就像我刚才让碎片离开身体一样，你也可以用同样的方法。你快想想小雨说的那些话吧！」", null, "山_山の中１c", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "33"}, "CHAPTER 8-2", null, null], [8493, "将臣", "「集中注意力，感受自己体内的碎片，然后对它祈愿！」", null, "山_山の中１c", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "33"}, "CHAPTER 8-2", null, null], [8494, "蕾娜", "「…………」", "len427_013.ogg", "山_山の中１c", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "33"}, "CHAPTER 8-2", null, null], [8495, "将臣", "「你不是还有很多话要对祟神……要对白狛说的吗！」", null, "山_山の中１c", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "33"}, "CHAPTER 8-2", null, null], [8496, "蕾娜", "「……」", "len427_014.ogg", "山_山の中１c", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "12"}, "CHAPTER 8-2", null, null], [8497, "", "蕾娜终于有了反应。", null, "山_山の中１c", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "12"}, "CHAPTER 8-2", null, null], [8498, "", "她的眼瞳中恢复了理性的色彩。", null, "山_山の中１c", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "12"}, "CHAPTER 8-2", null, null], [8499, "蕾娜", "「将、将臣……啊！？」", "len427_015.ogg", "山_山の中１c", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "04"}, "CHAPTER 8-2", null, null], [8500, "", "她刚一睁开眼，宿体便出现在她手中。", null, "山_山の中１c", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "04"}, "CHAPTER 8-2", null, null], [8501, "", "而且已经恢复成了一颗完整的球体。", null, "山_山の中１c", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "04"}, "CHAPTER 8-2", null, null], [8502, "将臣", "「成功了，终于成……」", null, "山_山の中１c", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "04"}, "CHAPTER 8-2", null, null], [8503, "蕾娜", "「危险！快走开！」", "len427_016.ogg", "山_山の中１c", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "13"}, "CHAPTER 8-2", null, null], [8504, "", "蕾娜突然把我推开。", null, "山_山の中１c", "bgm13.opus", null, "CHAPTER 8-2", null, null], [8505, "", "就在这时，宿体高高地浮了起来。", null, "山_山の中１c", "bgm13.opus", null, "CHAPTER 8-2", null, null], [8506, "", "紧接着，森林中刮起了大风，四周的祟神都被宿体气势汹汹地吸了进去。", null, "山_山の中１c", "bgm13.opus", null, "CHAPTER 8-2", null, null], [8507, "", "我差点忘了，那并不是一般的石头。", null, "山_山の中１c", "bgm13.opus", null, "CHAPTER 8-2", null, null], [8508, "", "它们并不是想包围我们！它们只是在等待这一刻的到来而已。", null, "山_山の中１c", "bgm13.opus", null, "CHAPTER 8-2", null, null], [8509, "将臣", "「糟、糟了，这是！？」", null, "山_山の中１c", "bgm13.opus", null, "CHAPTER 8-2", null, null], [8510, "祟神", "「咕——————」", "srk427_011.ogg", "山_山の中１c", "bgm13.opus", null, "CHAPTER 8-2", null, null], [8511, "祟神", "「唔啊啊啊啊啊啊啊啊！！！」", "srk427_012.ogg", "山_山の中１c", "bgm13.opus", null, "CHAPTER 8-2", null, null], [8512, "", "庞大的身躯降临在我们刚才站立的地方。", null, "山_山の中１c", "bgm13.opus", null, "CHAPTER 8-2", null, null], [8513, "", "大地被撕裂，震耳欲聋的轰鸣声响彻四野，一阵阵冲击波将我们推得老远。", null, "山_山の中１c", "bgm13.opus", null, "CHAPTER 8-2", null, null], [8514, "将臣", "「蕾娜！！」", null, "山_山の中１c", "bgm13.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "06"}, "CHAPTER 8-2", null, null], [8515, "蕾娜", "「将臣！？」", "len427_017.ogg", "山_山の中１c", "bgm13.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 8-2", null, null], [8516, "", "我们勉强稳住了姿势。祟神死死地盯着蕾娜，丝毫不给我们任何逃跑的机会。", null, "山_山の中１c", "bgm13.opus", null, "CHAPTER 8-2", null, null], [8517, "", "一时间，我的身体完全动弹不得。", null, "山_山の中１c", "bgm13.opus", null, "CHAPTER 8-2", null, null], [8518, "", "不仅是被吓到了，同时我也明白了一件事。", null, "山_山の中１c", "bgm13.opus", null, "CHAPTER 8-2", null, null], [8519, "", "现在的祟神……比以前强得多。", null, "山_山の中１c", "bgm13.opus", null, "CHAPTER 8-2", null, null], [8520, "", "一团团不祥的黑气朝四周扩散开来，一股沉重的压力正束缚着我的身体。", null, "山_山の中１c", "bgm13.opus", null, "CHAPTER 8-2", null, null], [8521, "", "……他活着。", null, "山_山の中１c", "bgm13.opus", null, "CHAPTER 8-2", null, null], [8522, "", "我能从他身上感受到那种怒放的生命力。这种感觉以前从来没有过。", null, "山_山の中１c", "bgm13.opus", null, "CHAPTER 8-2", null, null], [8523, "祟神", "「少年，还不速速离开此地」", "srk427_013.ogg", "山_山の中１c", "bgm13.opus", null, "CHAPTER 8-2", null, null], [8524, "", "祟神说话了！？竟然对我说了一句有实际含义的话？", null, "山_山の中１c", "bgm12.opus", null, "CHAPTER 8-2", null, null], [8525, "", "不，这句话……是白狛说的。", null, "山_山の中１c", "bgm12.opus", null, "CHAPTER 8-2", null, null], [8526, "蕾娜", "「快停下来！你的姐姐已经恢复原状了！」", "len427_018.ogg", "山_山の中１c", "bgm12.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 8-2", null, null], [8527, "祟神", "「姐姐大人的身体确实复原了，此事我该谢谢你们」", "srk427_014.ogg", "山_山の中１c", "bgm12.opus", null, "CHAPTER 8-2", null, null], [8528, "祟神", "「但是，我已经累了，无论是守护，还是诅咒」", "srk427_015.ogg", "山_山の中１c", "bgm12.opus", null, "CHAPTER 8-2", null, null], [8529, "将臣", "「这、这是什么意思？」", null, "山_山の中１c", "bgm12.opus", null, "CHAPTER 8-2", null, null], [8530, "祟神", "「姐姐大人的身体虽已复原，但是她的灵魂已经永远离我而去了」", "srk427_016.ogg", "山_山の中１c", "bgm12.opus", null, "CHAPTER 8-2", null, null], [8531, "祟神", "「所以，我想找一个替身」", "srk427_017.ogg", "山_山の中１c", "bgm12.opus", null, "CHAPTER 8-2", null, null], [8532, "蕾娜", "「……哎？」", "len427_019.ogg", "山_山の中１c", "bgm12.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "24"}, "CHAPTER 8-2", null, null], [8533, "祟神", "「我为你展示宿体的记忆，让你扮演姐姐大人，都是为了把姐姐大人的记忆灌进你脑子里」", "srk427_018.ogg", "山_山の中１c", "bgm12.opus", null, "CHAPTER 8-2", null, null], [8534, "祟神", "「这样一来，你好歹能成为一个供我解闷的人偶」", "srk427_019.ogg", "山_山の中１c", "bgm12.opus", null, "CHAPTER 8-2", null, null], [8535, "将臣", "「你说什么！？」", null, "山_山の中１c", "bgm12.opus", null, "CHAPTER 8-2", null, null], [8536, "", "确实，我们之前就猜测，那些梦境中的记忆是祟神故意让我们看的。", null, "山_山の中１c", "bgm12.opus", null, "CHAPTER 8-2", null, null], [8537, "", "但是，万万没想到……！", null, "山_山の中１c", "bgm12.opus", null, "CHAPTER 8-2", null, null], [8538, "蕾娜", "「难道……你一直都是为了让我做你姐姐的替身？」", "len427_020.ogg", "山_山の中１c", "bgm12.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "06"}, "CHAPTER 8-2", null, null], [8539, "祟神", "「虽然你不足以取代她，但也不是不能忍」", "srk427_020.ogg", "山_山の中１c", "bgm12.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "06"}, "CHAPTER 8-2", null, null], [8540, "祟神", "「咱们就一起隐居幻世，静静地休养生息吧」", "srk427_021.ogg", "山_山の中１c", "bgm12.opus", null, "CHAPTER 8-2", null, null], [8541, "将臣", "「不……不要这样！难道你想成为真正的祟神吗！」", null, "山_山の中１c", "bgm12.opus", null, "CHAPTER 8-2", null, null], [8542, "将臣", "「你明知道她不是你姐姐！」", null, "山_山の中１c", "bgm12.opus", null, "CHAPTER 8-2", null, null], [8543, "祟神", "「区区凡人，给我闭嘴！没人能取代姐姐大人，那又如何？」", "srk427_022.ogg", "山_山の中１c", "bgm12.opus", null, "CHAPTER 8-2", null, null], [8544, "祟神", "「等这丫头死了，或是让我腻烦了，我再去找其他活人祭品就是了」", "srk427_023.ogg", "山_山の中１c", "bgm12.opus", null, "CHAPTER 8-2", null, null], [8545, "祟神", "「从古至今，人类和神灵的关系一直如此，不是么」", "srk427_024.ogg", "山_山の中１c", "bgm12.opus", null, "CHAPTER 8-2", null, null], [8546, "", "岂有此理！", null, "山_山の中１c", "bgm12.opus", null, "CHAPTER 8-2", null, null], [8547, "", "本来还以为能和他好好沟通，现在看来这都是我们的痴心妄想吗？", null, "山_山の中１c", "bgm12.opus", null, "CHAPTER 8-2", null, null], [8548, "祟神", "「你若想抵抗，我随时奉陪」", "srk427_025.ogg", "山_山の中１c", "bgm12.opus", null, "CHAPTER 8-2", null, null], [8549, "", "他的尾巴挥出一阵撕裂空气的响声。", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8550, "将臣", "「哎？……唔啊！？」", null, "画面_黒", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8551, "", "回过神来，我已经被抛到了半空中。", null, "空_夜空", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8552, "", "那粗壮的尾巴如同一颗活着的巨木，像鞭子一样击中了我的身体。", null, "空_夜空", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8553, "", "要不是我勉强用丛雨丸的刀鞘挡住了这一击，我现在就已经死了。", null, "空_夜空", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8554, "", "我并非是有意做出了这样的动作，而是身体自己反应了过来。这都是多亏了每天的训练。", null, "空_夜空", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8555, "", "我就这样坠落在地面。", null, "空_夜空", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8556, "蕾娜", "「将臣————！你、你在干什么啊！快住手！」", "len427_021.ogg", "山_山の中１c", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "16"}, "CHAPTER 8-2", null, null], [8557, "祟神", "「哼，还活着啊」", "srk427_026.ogg", "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8558, "将臣", "「唔……」", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8559, "", "我四肢用力，准备站起来。", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8560, "", "没问题。冷静点……我还能站起来！", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8561, "", "这里是梦境。就算我受伤，伤的也不是现实中的身体。", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8562, "将臣", "「呼……呼……还没完呢！我可不打算把蕾娜交给你」", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8563, "蕾娜", "「将臣……」", "len427_022.ogg", "山_山の中１c", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "06"}, "CHAPTER 8-2", null, null], [8564, "祟神", "「是么，区区凡人，倒还有点气魄」", "srk427_027.ogg", "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8565, "祟神", "「莫非是哪个知名武士的后代么」", "srk427_028.ogg", "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8566, "将臣", "「我不知道自己的祖先是不是很有名」", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8567, "将臣", "「我只知道，我身后有许许多多普通人在帮我！」", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8568, "", "我握住了丛雨丸的刀鞘口。", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8569, "", "但我还是忍不住反问自己。用武力一决胜负，真的是正确的吗？", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8570, "", "尽管诅咒将我们折磨至今，但如果我们也做了同样的事，这诅咒将永无止境。", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8571, "", "用新仇恨解决旧仇恨，这真的算是解决了问题吗，我能在大家面前抬起头吗？", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8572, "祟神", "「既然如此，就快从我眼前消失吧，无名少年」", "srk427_029.ogg", "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8573, "将臣", "「……唔！」", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8574, "", "祟神的尾巴再一次攻了过来。", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8575, "", "尽管我勉强躲了过去，但仅仅是风压就足以吹起我的身体。", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8576, "", "尾巴击中地面。在这爆炸一般的冲击力之下，尘土就像霰弹一样四散开来。", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8577, "祟神", "「哈哈哈哈，让我看看你能躲到什么时候」", "srk427_030.ogg", "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8578, "将臣", "「呃啊！？唔……！」", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8579, "", "这并不是什么必杀技，仅仅就只是随便甩了甩尾巴而已。", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8580, "", "可恶，这实力太过悬殊，人类根本不可能战胜他。", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8581, "", "但也正因如此……我明白了一件重要的事。", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8582, "蕾娜", "「你为什么不拔刀？至少要保护好自己啊」", "len427_023.ogg", "山_山の中１c", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 8-2", null, null], [8583, "将臣", "「蕾娜！咱们不是说好了吗，要争取完美结局」", null, "山_山の中１c", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 8-2", null, null], [8584, "祟神", "「……什么？」", "srk427_031.ogg", "山_山の中１c", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 8-2", null, null], [8585, "蕾娜", "「将臣……」", "len427_024.ogg", "山_山の中１c", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "12"}, "CHAPTER 8-2", null, null], [8586, "将臣", "「这家伙，为了守护丛云……守护他最珍视的人留下的石头，最终被人斩首」", null, "山_山の中１c", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "12"}, "CHAPTER 8-2", null, null], [8587, "祟神", "「！！」", "srk427_032.ogg", "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8588, "将臣", "「白狛和丛云，还有穗织的人们都有着各自的心愿」", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8589, "将臣", "「慢慢地了解了大家心中所想之后，我觉得自己必须做点什么！」", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8590, "将臣", "「但是知道的越多，我越觉得用武力解决问题是不对的」", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8591, "祟神", "「你小子，区区凡人竟然还对我手下留情么」", "srk427_033.ogg", "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8592, "将臣", "「不是的」", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8593, "将臣", "「我只是不想以怨报怨而已！」", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8594, "", "祟神脸色骤变。", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8595, "", "他八成是觉得自己的自尊心受到了打击。", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8596, "", "毕竟，企图把蕾娜带走并不能解决任何问题，只是闹脾气而已。", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8597, "", "我心里知道，他其实并不是那么自私的神灵。", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8598, "将臣", "「你最开始，也守护过朝武家的人」", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8599, "将臣", "「所以你最终都没能伤害他们，不是吗？」", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8600, "祟神", "「闭嘴！我以后不可能再守护凡人了！！」", "srk427_034.ogg", "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8601, "将臣", "「别胡说了！你甚至都无法让自己成为真正的恶神！」", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8602, "将臣", "「你的实力远远凌驾于我，但你却一直都没有使出全力攻击我！」", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8603, "将臣", "「你明明随时可以取我性命，却没有那么做，究竟是谁在手下留情！？」", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8604, "祟神", "「！！」", "srk427_035.ogg", "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8605, "", "没错，刚才挨了那么重的一击之后，我反而意识到了这个问题。", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8606, "祟神", "「闭嘴！闭嘴，我岂会对你手下留情！！」", "srk427_036.ogg", "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8607, "", "祟神的尾巴再一次挥了过来。", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8608, "", "我立刻向一旁躲闪，但这冲击力比刚才要强得多。", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8609, "将臣", "「唔啊啊啊啊啊啊！！」", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8610, "祟神", "「哈哈哈哈哈哈！我稍微拿出点真本事，你就这样了？」", "srk427_037.ogg", "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8611, "祟神", "「对付你，我根本不用使出全力！」", "srk427_038.ogg", "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8612, "将臣", "「……稍微拿出点真本事？也就是说你承认自己手下留情了吗！」", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8613, "祟神", "「你这臭小子！！」", "srk427_039.ogg", "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8614, "", "下一秒，我便迎来了祟神的扫尾连击。", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8615, "", "四周的地形已经被打得没了形状，简直就像地震后的废墟一样。", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8616, "", "这真的会死……", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8617, "", "但我还能坚持！我告诉自己，这里是梦，不会有事。", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8618, "蕾娜", "「快住手啊，小狛！将臣，你不要乱来啊」", "len427_025.ogg", "山_山の中１c", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "06"}, "CHAPTER 8-2", null, null], [8619, "将臣", "「蕾……蕾娜！你不要光担心我……你可别忘了自己过来的目的」", null, "山_山の中１c", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "06"}, "CHAPTER 8-2", null, null], [8620, "蕾娜", "「可、可是，现在这个情况下……」", "len427_026.ogg", "山_山の中１c", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "06"}, "CHAPTER 8-2", null, null], [8621, "", "确实，这个状态下没法心平气和地说话。", null, "山_山の中１c", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "06"}, "CHAPTER 8-2", null, null], [8622, "祟神", "「也不知你们在打什么算盘，但一切到此为止了」", "srk427_040.ogg", "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8623, "将臣", "「唔……啊啊啊啊啊啊啊啊啊啊！！！」", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8624, "", "我还没来得及起身，祟神的尾巴就直接压在了我的后背上。", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8625, "", "本以为自己能挺住，但还是忍不住发出了惨叫。", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8626, "", "巨大的压力之下，我的背骨和肋骨几乎快要贴在一起。再这么下去，我将被压成一片肉饼。", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8627, "", "感觉自己就像变成了一条小虫子，正在被人践踏。", null, "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8628, "蕾娜", "「将……将臣！你没事吧，将臣！？」", "len427_027.ogg", "山_山の中１c", "bgm30.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 8-2", null, null], [8629, "祟神", "「你想救他？那就选吧」", "srk427_041.ogg", "山_山の中１c", "bgm30.opus", null, "CHAPTER 8-2", null, null], [8630, "蕾娜", "「哎？志那都庄……难道，跟上次一样！？」", "len427_028.ogg", "旅館_客室d", "bgm27.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "19"}, "CHAPTER 8-2", null, null], [8631, "", "森林中突然冒出来一间旅馆的客房，简直就像摄影棚一样。", null, "旅館_客室d", "bgm27.opus", null, "CHAPTER 8-2", null, null], [8632, "", "但是，客房的边缘却十分模糊，就像时空扭曲了一样。", null, "旅館_客室d", "bgm27.opus", null, "CHAPTER 8-2", null, null], [8633, "", "也不知这究竟是祟神的能力，还是梦境中的现象。他究竟想让蕾娜做什么？", null, "旅館_客室d", "bgm27.opus", null, "CHAPTER 8-2", null, null], [8634, "祟神", "「吃一口这里的饭菜」", "srk427_042.ogg", "旅館_客室d", "bgm27.opus", null, "CHAPTER 8-2", null, null], [8635, "蕾娜", "「这、这是……！」", "len427_029.ogg", "旅館_客室d", "bgm27.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "15"}, "CHAPTER 8-2", null, null], [8636, "", "桌子正中间摆着一座泡芙塔，周围摆着肉丸、香煎鲱鱼排之类的料理。", null, "旅館_客室d", "bgm27.opus", null, "CHAPTER 8-2", null, null], [8637, "", "房内还放着零食、扑克牌，以及电影ＤＶＤ。", null, "旅館_客室d", "bgm27.opus", null, "CHAPTER 8-2", null, null], [8638, "", "每个都是我们非常眼熟的物品。", null, "旅館_客室d", "bgm27.opus", null, "CHAPTER 8-2", null, null], [8639, "蕾娜", "「这些……跟我们办睡衣派对时一模一样」", "len427_030.ogg", "旅館_客室d", "bgm27.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "30"}, "CHAPTER 8-2", null, null], [8640, "芳乃", "「就是呀，蕾娜！咱们不是说好了，要再办一场睡衣派对的嘛」", "yos427_013.ogg", "旅館_客室d", "bgm27.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "21"}, "CHAPTER 8-2", null, null], [8641, "茉子", "「哈哈，你都忘记了吗？」", "mak427_005.ogg", "旅館_客室d", "bgm27.opus", {"char": "茉子", "file": "茉子.stand", "dress": "私服", "face": "41"}, "CHAPTER 8-2", null, null], [8642, "蕾娜", "「芳乃，茉子！？」", "len427_031.ogg", "旅館_客室d", "bgm27.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 8-2", null, null], [8643, "", "就连小雨、廉太郎和小春也都是一脸诡异的微笑，站在那里。", null, "旅館_客室d", "bgm27.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "01"}, "CHAPTER 8-2", null, null], [8644, "蕾娜", "「你们也……」", "len427_032.ogg", "旅館_客室d", "bgm27.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "30"}, "CHAPTER 8-2", null, null], [8645, "芳乃", "「来吧，蕾娜！快跟大家一起吃吧」", "yos427_014.ogg", "旅館_客室d", "bgm27.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "03"}, "CHAPTER 8-2", null, null], [8646, "蕾娜", "「这难道是……？」", "len427_033.ogg", "旅館_客室d", "bgm27.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "03"}, "CHAPTER 8-2", null, null], [8647, "将臣", "「不、不要……不要让大家做这种事！」", null, "山_山の中１c", "bgm27.opus", null, "CHAPTER 8-2", null, null], [8648, "", "我用颤抖的手握住了丛雨丸的刀柄。", null, "山_山の中１c", "bgm27.opus", null, "CHAPTER 8-2", null, null], [8649, "", "事到如今，事到如今……已经没有别的办法了吗？", null, "山_山の中１c", "bgm27.opus", null, "CHAPTER 8-2", null, null], [8650, "祟神", "「现在拔刀，又有何用？」", "srk427_043.ogg", "山_山の中１c", "bgm27.opus", null, "CHAPTER 8-2", null, null], [8651, "将臣", "「唔啊……！！」", null, "山_山の中１c", "bgm27.opus", null, "CHAPTER 8-2", null, null], [8652, "", "我被祟神紧紧地按在地上，连惨叫都发不出了。", null, "山_山の中１c", "bgm27.opus", null, "CHAPTER 8-2", null, null], [8653, "", "肺部承受的重压，让我几乎无法呼吸。", null, "山_山の中１c", "bgm27.opus", null, "CHAPTER 8-2", null, null], [8654, "", "不……不能慌……这……都是梦……只要我做好思想准备，就不会……受伤……！", null, "山_山の中１c", "bgm27.opus", null, "CHAPTER 8-2", null, null], [8655, "蕾娜", "「将臣」", "len427_034.ogg", "山_山の中１c", "bgm27.opus", null, "CHAPTER 8-2", null, null], [8656, "", "……蕾娜？", null, "旅館_客室d", "bgm27.opus", null, "CHAPTER 8-2", null, null], [8657, "蕾娜", "「你不用拔刀了」", "len427_035.ogg", "旅館_客室d", "bgm27.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 8-2", null, null], [8658, "蕾娜", "「大家也不必费心了」", "len427_036.ogg", "旅館_客室d", "bgm27.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "17"}, "CHAPTER 8-2", null, null], [8659, "芳乃", "「……？」", "yos427_015.ogg", "旅館_客室d", "bgm27.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "私服", "face": "01"}, "CHAPTER 8-2", null, null], [8660, "", "朝武和常陆的幻象，正在逼迫蕾娜吃下这里的料理。", null, "旅館_客室d", "bgm39.opus", null, "CHAPTER 8-2", null, null], [8661, "", "绝对不能吃……", null, "旅館_客室d", "bgm39.opus", null, "CHAPTER 8-2", null, null], [8662, "", "……绝对不能。", null, "旅館_客室d", "bgm39.opus", null, "CHAPTER 8-2", null, null], [8663, "", "吃了之后，就会被神灵带走，永远也无法回到人间……", null, "旅館_客室d", "bgm39.opus", null, "CHAPTER 8-2", null, null], [8664, "", "但是蕾娜却毫不犹豫地吃了下去。", null, "旅館_客室d", "bgm39.opus", null, "CHAPTER 8-2", null, null], [8665, "祟神", "「哈……哈哈哈，这样就对了！」", "srk427_044.ogg", "旅館_客室d", "bgm39.opus", null, "CHAPTER 8-2", null, null], [8666, "祟神", "「现在，你已是幻世之人，再也无法回到人间了！」", "srk427_045.ogg", "旅館_客室d", "bgm39.opus", null, "CHAPTER 8-2", null, null], [8667, "", "蕾娜！你为了保护我，竟然……！？", null, "旅館_客室d", "bgm39.opus", null, "CHAPTER 8-2", null, null], [8668, "蕾娜", "「不，应该不会那样」", "len427_037.ogg", "旅館_客室d", "bgm39.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 8-2", null, null], [8669, "祟神", "「什、什么……？」", "srk427_046.ogg", "旅館_客室d", "bgm39.opus", null, "CHAPTER 8-2", null, null], [8670, "祟神", "「唔，这是！？」", "srk427_047.ogg", "旅館_客室d", "bgm39.opus", null, "CHAPTER 8-2", null, null], [8671, "", "背后的压力突然变小了。", null, "旅館_客室d", "bgm39.opus", null, "CHAPTER 8-2", null, null], [8672, "", "一眨眼的工夫，祟神竟变回了从前的模样。", null, "山_山の中１c", "bgm08.opus", null, "CHAPTER 8-2", null, null], [8673, "", "志那都庄的客房也消失了。", null, "山_山の中１c", "bgm08.opus", null, "CHAPTER 8-2", null, null], [8674, "蕾娜", "「你看，果然如此」", "len427_038.ogg", "山_山の中１c", "bgm08.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 8-2", null, null], [8675, "白狛", "「你……你难道……！」", "srk427_048.ogg", "山_山の中１c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8676, "将臣", "「这是怎么回事，蕾娜？」", null, "山_山の中１c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8677, "蕾娜", "「这里大概是我的梦境」", "len427_039.ogg", "山_山の中１c", "bgm08.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "34"}, "CHAPTER 8-2", null, null], [8678, "蕾娜", "「你是用我的记忆，制造了这样一个梦境吧？就像之前你将宿体的记忆以梦境的形式展现给我们一样」", "len427_040.ogg", "山_山の中１c", "bgm08.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "27"}, "CHAPTER 8-2", null, null], [8679, "", "喔！所以刚才出现的东西才会跟睡衣派对时一模一样啊。", null, "山_山の中１c", "bgm08.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "27"}, "CHAPTER 8-2", null, null], [8680, "", "上次蕾娜被操控时，梦境中之所以会有她的家人，也是因为祟神使用了她的记忆吧？", null, "山_山の中１c", "bgm08.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "27"}, "CHAPTER 8-2", null, null], [8681, "蕾娜", "「所以，只要我不觉得自己回不去了，那就不会有什么事」", "len427_041.ogg", "山_山の中１c", "bgm08.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "10"}, "CHAPTER 8-2", null, null], [8682, "蕾娜", "「这个梦境只是一场演出，目的就是让我把假象信以为真」", "len427_042.ogg", "山_山の中１c", "bgm08.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "22"}, "CHAPTER 8-2", null, null], [8683, "白狛", "「……」", "srk427_049.ogg", "山_山の中１c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8684, "", "白狛的沉默，已经说明了一切。", null, "山_山の中１c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8685, "蕾娜", "「我在梦中变成丛云时，目睹了她托梦给武士，告诉他如何救助那位难产的女孩」", "len427_043.ogg", "山_山の中１c", "bgm08.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "27"}, "CHAPTER 8-2", null, null], [8686, "将臣", "「原、原来如此，你是有十足的把握才这么做的吗？」", null, "山_山の中１c", "bgm08.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "27"}, "CHAPTER 8-2", null, null], [8687, "蕾娜", "「这个嘛……我觉得就算我失败了，芳乃她们也一定会把我拉回去的」", "len427_044.ogg", "山_山の中１c", "bgm08.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 8-2", null, null], [8688, "蕾娜", "「我相信大家，仅此而已」", "len427_045.ogg", "山_山の中１c", "bgm08.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "19"}, "CHAPTER 8-2", null, null], [8689, "将臣", "「蕾娜……」", null, "山_山の中１c", "bgm08.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "19"}, "CHAPTER 8-2", null, null], [8690, "蕾娜", "「而且，你说的确实没错」", "len427_046.ogg", "山_山の中１c", "bgm08.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "21"}, "CHAPTER 8-2", null, null], [8691, "", "蕾娜再一次将视线转向白狛。", null, "山_山の中１c", "bgm08.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "21"}, "CHAPTER 8-2", null, null], [8692, "蕾娜", "「你真的没有手下留情吗？如果你是真心想把我带走的话」", "len427_047.ogg", "山_山の中１c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8693, "蕾娜", "「这种方法未免太过随意了」", "len427_048.ogg", "山_山の中１c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8694, "白狛", "「闭……闭嘴，我……我只是想把你当做姐姐的替身……」", "srk427_050.ogg", "山_山の中１c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8695, "蕾娜", "「嗯，但我不是你的姐姐，你姐姐恐怕也不会希望你这么做」", "len427_049.ogg", "山_山の中１c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8696, "蕾娜", "「这些你都明白的吧？」", "len427_050.ogg", "山_山の中１c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8697, "白狛", "「不！即便如此，我还是……」", "srk427_051.ogg", "山_山の中１c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8698, "蕾娜", "「你错了，这么做你是不可能满足的」", "len427_051.ogg", "山_山の中１c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8699, "蕾娜", "「你姐姐之前说过的吧？」", "len427_052.ogg", "山_山の中１c", "bgm08.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 8-2", null, null], [8700, "", "——如果有朝一日你也有了喜欢的人，你就会明白的。", null, "山_山の中２c", "bgm08.opus", null, "CHAPTER 8-2", null, null], [8701, "白狛", "「那又如何！我和姐姐大人不一样，我憎恶人类，憎恶人类！」", "srk427_052.ogg", "山_山の中１c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8702, "蕾娜", "「你又在骗人！」", "len427_053.ogg", "山_山の中１c", "bgm08.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "16"}, "CHAPTER 8-2", null, null], [8703, "蕾娜", "「珍惜，关爱……这些感情，你应该已经明白了吧」", "len427_054.ogg", "山_山の中１c", "bgm08.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "21"}, "CHAPTER 8-2", null, null], [8704, "蕾娜", "「因为你最喜欢的人，就是丛云，我没说错吧」", "len427_055.ogg", "山_山の中１c", "bgm08.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 8-2", null, null], [8705, "白狛", "「……！？」", "srk427_053.ogg", "山_山の中１c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8706, "蕾娜", "「所以你最珍视的人曾经奋力守护的东西，你也想一直守护下去，难道不是吗？」", "len427_056.ogg", "山_山の中１c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8707, "蕾娜", "「你难道不是想继承你姐姐的遗志吗？」", "len427_057.ogg", "山_山の中１c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8708, "白狛", "「不……不要再说了」", "srk427_054.ogg", "山_山の中１c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8709, "蕾娜", "「没关系的！现在的你，只是被炽烈的怒火冲昏了头脑而已」", "len427_058.ogg", "山_山の中１c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8710, "蕾娜", "「仅仅只靠憎恨，你是不可能坚持到今天的」", "len427_059.ogg", "山_山の中１c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8711, "白狛", "「嘴上说得倒是好听！你也不想想，我……我诅咒了多少人，诅咒了多少年！？」", "srk427_055.ogg", "山_山の中１c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8712, "", "白狛冲我们露出了獠牙。", null, "山_山の中１c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8713, "", "但是，他看上去却像是在畏惧着什么一样。", null, "山_山の中１c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8714, "白狛", "「无论将多少人置于死地，我心中也不会有任何波动……」", "srk427_056.ogg", "山_山の中１c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8715, "白狛", "「憎恶始终留在我心里……我只是一介祟神……这世上，已经没有任何人能够阻挡我！」", "srk427_057.ogg", "山_山の中１c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8716, "蕾娜", "「小狛……」", "len427_060.ogg", "山_山の中１c", "bgm08.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "30"}, "CHAPTER 8-2", null, null], [8717, "白狛", "「就算我现在变成了这样，要杀你们几个凡人还是轻而易举的！」", "srk427_058.ogg", "山_山の中１c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8718, "", "我默默地拔出了丛雨丸。", null, "山_山の中１c", "bgm08.opus", null, "CHAPTER 8-2", null, null], [8719, "", "举着雪亮的刀刃，我来到了白狛身边。", null, "山_山の中１c", "bgm08.opus", null, "CHAPTER 8-2", null, null], [8720, "蕾娜", "「将臣？」", "len427_061.ogg", "山_山の中１c", "bgm08.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "24"}, "CHAPTER 8-2", null, null], [8721, "白狛", "「嚯，你终于准备大战一场了么」", "srk427_059.ogg", "山_山の中１c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8722, "", "我在白狛身前跪下，双手捧起了刀身。", null, "山_山の中１c", "bgm08.opus", null, "CHAPTER 8-2", null, null], [8723, "将臣", "「你真的这么认为吗？」", null, "山_山の中１c", "bgm08.opus", null, "CHAPTER 8-2", null, null], [8724, "白狛", "「什么？你想干什么？」", "srk427_060.ogg", "山_山の中１c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8725, "将臣", "「有一件事我无法确定，但是你说不定知道真相」", null, "山_山の中１c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8726, "将臣", "「这把刀，是会挑人的」", null, "山_山の中１c", "bgm08.opus", null, "CHAPTER 8-2", null, null], [8727, "将臣", "「也就是说，丛雨丸有它自己的意志，我没猜错吧？」", null, "山_山の中１c", "bgm08.opus", null, "CHAPTER 8-2", null, null], [8728, "", "发生了这么多事之后，有时候我会觉得，冥冥之中有某种庞大的意识在引导着我们。", null, "山_山の中１c", "bgm08.opus", null, "CHAPTER 8-2", null, null], [8729, "", "至少，单凭运气，朝武家在那之后很难延续５００年。", null, "山_山の中１c", "bgm08.opus", null, "CHAPTER 8-2", null, null], [8730, "", "这件事我们已经证明了。所以，现在我想再证明另外一件事。只有丛云的亲人，才知道真正的答案。", null, "山_山の中１c", "bgm08.opus", null, "CHAPTER 8-2", null, null], [8731, "将臣", "「能够劝阻你的人，真的已经不存在了吗？复仇真的不空虚吗？」", null, "山_山の中１c", "bgm08.opus", null, "CHAPTER 8-2", null, null], [8732, "将臣", "「这把刀究竟是用谁的身体造出来的，你不可能不知道吧？」", null, "山_山の中１c", "bgm08.opus", null, "CHAPTER 8-2", null, null], [8733, "将臣", "「我希望你睁大眼睛，仔细看一看！」", null, "山_山の中１c", "bgm08.opus", null, "CHAPTER 8-2", null, null], [8734, "白狛", "「什么……这，莫非是……？」", "srk427_061.ogg", "山_山の中１c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8735, "将臣", "「几百年来，她一直在劝阻你。从你变成祟神的那一刻起，直到现在。难道不是吗？」", null, "山_山の中１c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8736, "将臣", "「正因为有她相助，我们才能坚持到今天。我说的没错吧？」", null, "山_山の中１c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8737, "将臣", "「丛雨丸真的有自己的意志吗？它的意志究竟是何物？」", null, "山_山の中１c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8738, "将臣", "「请你告诉我！你是一方神灵，也是她的弟弟，你心里应该很清楚才对！」", null, "山_山の中１c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8739, "白狛", "「不……不要说了，不要说了不要说了！」", "srk427_062.ogg", "山_山の中１c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8740, "", "他一脸苦涩，似乎十分懊恼。", null, "山_山の中１c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8741, "", "看着他这副模样，我们也十分难受。", null, "山_山の中１c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8742, "白狛", "「不要……即便如此……我还是无法原谅，不想原谅」", "srk427_063.ogg", "山_山の中１c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8743, "白狛", "「也不能原谅……我、我不能就这么终结这一切！」", "srk427_064.ogg", "山_山の中１c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8744, "", "原来，它并非无法宽恕，只是不愿意去宽恕。", null, "山_山の中１c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8745, "蕾娜", "「你有自己的理由吗？」", "len427_062.ogg", "山_山の中１c", "bgm08.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "23"}, "CHAPTER 8-2", null, null], [8746, "白狛", "「一旦原谅了人类……他们马上就会忘记这一切！」", "srk427_065.ogg", "山_山の中１c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8747, "白狛", "「他们会忘了自己为何被憎恶，为何被诅咒，甚至连想都不会去想！」", "srk427_066.ogg", "山_山の中１c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8748, "白狛", "「姐姐大人的恩情，后世又有几个人还记得！？」", "srk427_067.ogg", "山_山の中１c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8749, "白狛", "「我别无选择……若不这么做，她将永远消逝……」", "srk427_068.ogg", "山_山の中１c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8750, "将臣", "「不必担心，我们已经回想起来了」", null, "山_山の中１c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8751, "蕾娜", "「是你让我们找回了过去的记忆」", "len427_063.ogg", "山_山の中１c", "bgm08.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "27"}, "CHAPTER 8-2", null, null], [8752, "", "为了让荒魂平息怒火，究竟怎么做才最合适？", null, "山_山の中１c", "bgm08.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "27"}, "CHAPTER 8-2", null, null], [8753, "", "很巧的是，朝武想的办法跟我们想的完全一样。", null, "山_山の中１c", "bgm08.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "27"}, "CHAPTER 8-2", null, null], [8754, "蕾娜", "「现在，大家都在为此出谋划策呢。我们准备办一场感谢神灵的庆典！」", "len427_064.ogg", "山_山の中１c", "bgm08.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "02"}, "CHAPTER 8-2", null, null], [8755, "将臣", "「嗯，从明年开始，春日祭的主题将变成传递感恩，而非祓除妖魔」", null, "山_山の中１c", "bgm08.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "02"}, "CHAPTER 8-2", null, null], [8756, "白狛", "「……春日祭，将迎来重生？」", "srk427_069.ogg", "山_山の中１c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8757, "将臣", "「没错！它一定会成为这里的传统，一直延续到几百年之后」", null, "山_山の中１c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8758, "蕾娜", "「传递感恩的庆典……一定会比以前更加好玩，更加欢乐」", "len427_065.ogg", "山_山の中１c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8759, "", "但愿能实现。不对，不能说得这么事不关己。", null, "山_山の中１c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8760, "", "我们要努力将其实现才行。", null, "山_山の中１c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8761, "白狛", "「感恩的庆典……为了姐姐大人？」", "srk427_070.ogg", "山_山の中１c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8762, "蕾娜", "「当然了」", "len427_066.ogg", "山_山の中１c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8763, "", "这时，蕾娜端正了自己的站姿。", null, "山_山の中１c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8764, "", "她准备了那么久的稿子，终于要念出来了。", null, "山_山の中１c", "bgm08.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8765, "蕾娜", "「白山狛男神，汝勤事于穗织，数百年不懈守护之责，诚当大义！」", "len427_067.ogg", "山_山の中１c", "bgm15.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "25"}, "CHAPTER 8-2", null, null], [8766, "蕾娜", "「但念汝曾受切肤之痛，个中劳苦绝非一言可表……」", "len427_068.ogg", "山_山の中１c", "bgm15.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "14"}, "CHAPTER 8-2", null, null], [8767, "", "最开始，蕾娜连现代日语都说得不那么标准。", null, "山_山の中１c", "bgm15.opus", null, "CHAPTER 8-2", null, null], [8768, "", "在和丛云共享意识之前，她甚至都不知道丛云说的那些话是什么意思，也没能解开自己的疑惑。", null, "山_山の中１c", "bgm15.opus", null, "CHAPTER 8-2", null, null], [8769, "", "但是她如今练得朗朗上口的这些句子，都来自于女神大人的那个时代。", null, "山_山の中１c", "bgm15.opus", null, "CHAPTER 8-2", null, null], [8770, "", "也就是山之子和山之女都平平安安，生活和睦的那个时代。", null, "山_山の中１c", "bgm15.opus", null, "CHAPTER 8-2", null, null], [8771, "蕾娜", "「汝之厚恩，皇天后土实所共鉴，然凡人不识，反以凶恶相报」", "len427_069.ogg", "山_山の中１c", "bgm15.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "32"}, "CHAPTER 8-2", null, null], [8772, "蕾娜", "「愤慨之至，犹不可遏，实为无奈」", "len427_070.ogg", "山_山の中１c", "bgm15.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "08"}, "CHAPTER 8-2", null, null], [8773, "蕾娜", "「盖汝素性仁厚，曾守护一方百姓，当受赞誉」", "len427_071.ogg", "山_山の中１c", "bgm15.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "08"}, "CHAPTER 8-2", null, null], [8774, "蕾娜", "「余非问罪之人」", "len427_072.ogg", "山_山の中１c", "bgm15.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "14"}, "CHAPTER 8-2", null, null], [8775, "蕾娜", "「仅代汝姊长告之矣」", "len427_073.ogg", "山_山の中１c", "bgm15.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "01"}, "CHAPTER 8-2", null, null], [8776, "蕾娜", "「你不必再诅咒了，也不必再守护了」", "len427_074.ogg", "山_山の中１c", "bgm15.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "21"}, "CHAPTER 8-2", null, null], [8777, "蕾娜", "「你和你姐姐的恩情，我们永远都不会忘记的」", "len427_075.ogg", "山_山の中１c", "bgm15.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "03"}, "CHAPTER 8-2", null, null], [8778, "蕾娜", "「我们希望你能放下包袱，去寻找自由」", "len427_076.ogg", "山_山の中１c", "bgm15.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "17"}, "CHAPTER 8-2", null, null], [8779, "白狛", "「……自由？」", "srk427_071.ogg", "山_山の中１c", "bgm15.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8780, "", "既不是承受诅咒的祟神，也不是宅心仁厚的守护神，而是自由之躯。", null, "山_山の中１c", "bgm15.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8781, "", "这也是刚才那些话的意义所在。", null, "山_山の中１c", "bgm15.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8782, "蕾娜", "「毕竟，你已经付出了几百年了」", "len427_077.ogg", "山_山の中１c", "bgm15.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "27"}, "CHAPTER 8-2", null, null], [8783, "蕾娜", "「你也不需要原谅人类。愤怒也好，憎恶也好，守护也好，关爱也好，这都是你的自由」", "len427_078.ogg", "山_山の中１c", "bgm15.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "02"}, "CHAPTER 8-2", null, null], [8784, "蕾娜", "「我希望我们可以暂时休战」", "len427_079.ogg", "山_山の中１c", "bgm15.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "23"}, "CHAPTER 8-2", null, null], [8785, "蕾娜", "「心中一直抱着憎恶，会很难受的吧？」", "len427_080.ogg", "山_山の中１c", "bgm15.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "21"}, "CHAPTER 8-2", null, null], [8786, "白狛", "「……」", "srk427_072.ogg", "山_山の中１c", "bgm15.opus", {"char": "白狛", "file": "白狛.stand", "dress": "", "face": ""}, "CHAPTER 8-2", null, null], [8787, "蕾娜", "「我觉得……你没必要用这种方式折磨自己」", "len427_081.ogg", "山_山の中１c", "bgm15.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "35"}, "CHAPTER 8-2", null, null], [8788, "", "蕾娜说的没错。不过，也许正因为她是个外国人，和诅咒没多少关系，她才能勇敢地说出这些。", null, "山_山の中１c", "bgm15.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "35"}, "CHAPTER 8-2", null, null], [8789, "", "憎恶他人，是很痛苦的。", null, "山_山の中１c", "bgm15.opus", null, "CHAPTER 8-2", null, null], [8790, "", "被诅咒折磨，然后憎恶诅咒。大家就这样，忍受了几百年的痛苦。", null, "山_山の中１c", "bgm15.opus", null, "CHAPTER 8-2", null, null], [8791, "", "然而，就连发动诅咒的人自己都那么痛苦，那为何不试着停下来呢？", null, "山_山の中１c", "bgm15.opus", null, "CHAPTER 8-2", null, null], [8792, "将臣", "「当然了，如果我们又忘记了你们的恩情」", null, "山_山の中１c", "bgm15.opus", null, "CHAPTER 8-2", null, null], [8793, "将臣", "「到时候你就好好地训斥我们吧。我觉得，这就是自由的意义所在」", null, "山_山の中１c", "bgm15.opus", null, "CHAPTER 8-2", null, null], [8794, "", "我相信，只要我们能相互尊重，远离憎恶带来的痛苦——", null, "山_山の中１c", "bgm15.opus", null, "CHAPTER 8-2", null, null], [8795, "", "我们最终一定能为过去的诅咒画上圆满的句号。", null, "山_山の中１c", "bgm15.opus", null, "CHAPTER 8-2", null, null], [8796, "蕾娜", "「啊……」", "len427_082.ogg", "山_山の中１c", "bgm15.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "04"}, "CHAPTER 8-2", null, null], [8797, "", "突然，白狛奔上了山道。", null, "山_山の中１c", "bgm15.opus", null, "CHAPTER 8-2", null, null], [8798, "", "他回头望了我们一眼，随即面向远方，高声长啸。", null, "山_山の中１c", "bgm15.opus", null, "CHAPTER 8-2", null, null], [8799, "", "悠远的叫声响彻天际，在树林中回响，在山谷间消逝。", null, "山_山の中１c", "bgm15.opus", null, "CHAPTER 8-2", null, null], [8800, "", "回过神来，白狛已经不在那里。", null, "山_山の中１c", "bgm15.opus", null, "CHAPTER 8-2", null, null], [8801, "将臣", "「……他……接受了吗？」", null, "山_山の中１c", "bgm15.opus", null, "CHAPTER 8-2", null, null], [8802, "蕾娜", "「不知道，但我相信他！」", "len427_083.ogg", "山_山の中１c", "bgm15.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "01"}, "CHAPTER 8-2", null, null], [8803, "", "蕾娜还是那个蕾娜。", null, "山_山の中１c", "bgm15.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "01"}, "CHAPTER 8-2", null, null], [8804, "", "不过现在的她，脸上挂满了成就感。", null, "山_山の中１c", "bgm15.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "01"}, "CHAPTER 8-2", null, null], [8805, "将臣", "「回去吧」", null, "山_山の中１c", "bgm15.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "01"}, "CHAPTER 8-2", null, null], [8806, "蕾娜", "「嗯，我们也该回到大家身边了！」", "len427_084.ogg", "山_山の中１c", "bgm15.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "和装", "face": "18"}, "CHAPTER 8-2", null, null], [8807, "", "就在这时，一道光芒将我们托了起来。", null, "画面_白", "bgm15.opus", null, "CHAPTER 8-2", null, null], [8808, "将臣", "「喔，这是……！」", null, "画面_白", "bgm15.opus", null, "CHAPTER 8-2", "ev409a", null], [8809, "蕾娜", "「大家都在叫我们呢」", "len427_085.ogg", "画面_白", "bgm15.opus", null, "CHAPTER 8-2", "ev409a", null], [8810, "将臣", "「应该是的」", null, "画面_白", "bgm15.opus", null, "CHAPTER 8-2", "ev409a", null], [8811, "", "我们正在缓缓地升上天空。", null, "画面_白", "bgm15.opus", null, "CHAPTER 8-2", "ev409a", null], [8812, "", "这道光芒暖暖的，却充满了力量。可以想象，大家都紧紧地抓着绳子，没人松开手。", null, "画面_白", "bgm15.opus", null, "CHAPTER 8-2", "ev409a", null], [8813, "", "闭上眼睛，我仿佛能听见每一个人的声音，体会到每一个人的心情。", null, "画面_白", "bgm15.opus", null, "CHAPTER 8-2", "ev409a", null], [8814, "蕾娜", "「啊……好想快点见到大家呀」", "len427_086.ogg", "画面_白", "bgm15.opus", null, "CHAPTER 8-2", "ev409a", null], [8815, "将臣", "「我也是这么想的」", null, "画面_白", "bgm15.opus", null, "CHAPTER 8-2", "ev409a", null], [8816, "", "和大家共同经历的事情，接下来想要一同体验的事情……", null, "画面_白", "bgm15.opus", null, "CHAPTER 8-2", "ev409a", null], [8817, "", "一个接一个在脑海中浮现出来。", null, "画面_白", "bgm15.opus", null, "CHAPTER 8-2", "ev409a", null], [8818, "", "好想快点跟大家汇报。", null, "画面_白", "bgm15.opus", null, "CHAPTER 8-2", "ev409a", null], [8819, "", "朝武，常陆，安晴叔叔，美津叶大夫，还有穗织镇所有被诅咒折磨的人们，都可以获得自由。", null, "画面_白", "bgm15.opus", null, "CHAPTER 8-2", "ev409a", null], [8820, "", "这都是多亏了蕾娜，我为她感到自豪。", null, "画面_白", "bgm15.opus", null, "CHAPTER 8-2", "ev409a", null], [8821, "蕾娜", "「将臣，谢谢你」", "len427_087.ogg", "画面_白", "bgm15.opus", null, "CHAPTER 8-2", "ev409a", null], [8822, "将臣", "「你在说什么呢？我才应该谢谢你」", null, "画面_白", "bgm15.opus", null, "CHAPTER 8-2", "ev409a", null], [8823, "蕾娜", "「不不！将臣，你真的是我的武士！」", "len427_088.ogg", "画面_白", "bgm15.opus", null, "CHAPTER 8-2", "ev409a", null], [8824, "蕾娜", "「来到日本，来到穗织，和你相遇……」", "len427_089.ogg", "画面_白", "bgm15.opus", null, "CHAPTER 8-2", "ev409a", null], [8825, "蕾娜", "「我觉得自己真的很幸运！」", "len427_090.ogg", "画面_白", "bgm15.opus", null, "CHAPTER 8-2", "ev409a", null], [8826, "蕾娜", "「不仅仅为我，你还为大家分享了幸福，我真的……」", "len427_091.ogg", "画面_白", "bgm15.opus", null, "CHAPTER 8-2", "ev409a", null], [8827, "蕾娜", "「真的是第一次觉得这么自豪，这么开心」", "len427_092.ogg", "画面_白", "bgm15.opus", null, "CHAPTER 8-2", "ev409a", null], [8828, "蕾娜", "「谢谢你，将臣！没有你就没有今天」", "len427_093.ogg", "画面_白", "bgm15.opus", null, "CHAPTER 8-2", "ev409a", null], [8829, "将臣", "「也谢谢你，蕾娜！」", null, "画面_白", "bgm15.opus", null, "CHAPTER 8-2", "ev409a", null], [8830, "将臣", "「你说的这些，跟我刚才想的简直一模一样」", null, "画面_白", "bgm15.opus", null, "CHAPTER 8-2", "ev409a", null], [8831, "将臣", "「如果这是我的功劳，那也是多亏了有你在我身边」", null, "画面_白", "bgm15.opus", null, "CHAPTER 8-2", "ev409a", null], [8832, "蕾娜", "「你要这么说的话，我的功劳也都是因为有你在！」", "len427_094.ogg", "画面_白", "bgm15.opus", null, "CHAPTER 8-2", "ev409a", null], [8833, "", "既然如此……", null, "画面_白", "bgm15.opus", null, "CHAPTER 8-2", "ev409a", null], [8834, "将臣", "「因为我们在一起」", null, "画面_白", "bgm15.opus", null, "CHAPTER 8-2", "ev409a", null], [8835, "蕾娜", "「所以才能取得成功」", "len427_095.ogg", "画面_白", "bgm15.opus", null, "CHAPTER 8-2", "ev409a", null], [8836, "", "我和她走过的这些路。", null, "画面_白", "bgm15.opus", null, "CHAPTER 8-2", "ev409a", null], [8837, "", "以及这一路上，我们收获的一切。", null, "画面_白", "bgm15.opus", null, "CHAPTER 8-2", "ev409a", null], [8838, "", "今后，都将是我的毕生之宝。", null, "画面_白", "bgm15.opus", null, "CHAPTER 8-2", "ev409a", null], [8839, "", "没有什么比这些更加重要。", null, "画面_白", "bgm15.opus", null, "CHAPTER 8-2", "ev409a", null], [8840, "", "愿我们能携手并进……在这条路上永远走下去。", null, "画面_白", "bgm15.opus", null, "CHAPTER 8-2", "ev409a", null], [8841, "", "——在那之后，半年过去了。", null, "空_青空", "bgm10.opus", null, "SEC-428", null, null], [8842, "", "在梦境中，我和蕾娜与白山狛男神对峙之后，大家齐心协力将我们平安地带回了现实。", null, "神社_神社内a", "bgm10.opus", null, "SEC-428", null, null], [8843, "", "不……倒也不能说平安。", null, "神社_神社内a", "bgm10.opus", null, "SEC-428", null, null], [8844, "", "我本以为哪怕在梦中受了伤，现实中的身体也不会受到影响，但事实并没有我想得那么美。", null, "神社_神社内a", "bgm10.opus", null, "SEC-428", null, null], [8845, "", "现实中的我，也是伤得不轻。", null, "神社_神社内a", "bgm10.opus", null, "SEC-428", null, null], [8846, "", "我比蕾娜晚了整整三天才苏醒。", null, "街_診療所a", "bgm10.opus", null, "SEC-428", null, null], [8847, "", "也就是说，指望梦中不受伤，才是真的做梦……", null, "街_診療所a", "bgm10.opus", null, "SEC-428", null, null], [8848, "蕾娜", "「将臣……你终于醒了」", "len428_001.ogg", "街_診療所a", "bgm10.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "29"}, "SEC-428", null, null], [8849, "将臣", "「蕾、蕾娜……？」", null, "街_診療所a", "bgm10.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "29"}, "SEC-428", null, null], [8850, "蕾娜", "「不是说好了要大家一起迎接完美结局的吗？」", "len428_002.ogg", "街_診療所a", "bgm10.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "08"}, "SEC-428", null, null], [8851, "蕾娜", "「你要是不在了……我也没法活了你知不知道」", "len428_003.ogg", "街_診療所a", "bgm10.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "30"}, "SEC-428", null, null], [8852, "", "你不也是以身犯险，做了那么多吓人的事情吗。", null, "街_診療所a", "bgm10.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "30"}, "SEC-428", null, null], [8853, "", "不过，我确实感到挺抱歉的。", null, "街_診療所a", "bgm10.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "30"}, "SEC-428", null, null], [8854, "", "毕竟让自己最重要的人担心成这样。", null, "街_診療所a", "bgm10.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "30"}, "SEC-428", null, null], [8855, "蕾娜", "「总之……你能苏醒过来，真是太好了」", "len428_004.ogg", "街_診療所a", "bgm10.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "01"}, "SEC-428", null, null], [8856, "蕾娜", "「欢迎回家，将臣」", "len428_005.ogg", "街_診療所a", "bgm10.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "17"}, "SEC-428", null, null], [8857, "将臣", "「嗯，我回来了，蕾娜」", null, "街_診療所a", "bgm10.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "17"}, "SEC-428", null, null], [8858, "", "当然了，一听说我醒了，其他朋友也立刻跑来看望我。", null, "街_診療所b", "bgm10.opus", null, "SEC-428", null, null], [8859, "芳乃", "「有地！你终于醒了啊」", "yos428_001.ogg", "街_診療所b", "bgm10.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "28"}, "SEC-428", null, null], [8860, "茉子", "「哈哈，我就知道你不会有什么事的，毕竟你之前也扛住了好几次大伤」", "mak428_001.ogg", "街_診療所b", "bgm10.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "41"}, "SEC-428", null, null], [8861, "芳乃", "「真是的，你就知道让别人担心」", "yos428_002.ogg", "街_診療所b", "bgm10.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "23"}, "SEC-428", null, null], [8862, "将臣", "「唔，抱……抱歉」", null, "街_診療所b", "bgm10.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "制服", "face": "23"}, "SEC-428", null, null], [8863, "茉子", "「哈哈，我想说的是，对我和芳乃大人来说，你是很重要的朋友」", "mak428_002.ogg", "街_診療所b", "bgm10.opus", {"char": "茉子", "file": "茉子.stand", "dress": "制服", "face": "02"}, "SEC-428", null, null], [8864, "丛雨", "「总之，这下可算是大团圆了」", "mur428_001.ogg", "街_診療所b", "bgm10.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "19"}, "SEC-428", null, null], [8865, "", "接下来的半年，她们三人的生活都发生了翻天覆地的变化。", null, "街_診療所b", "bgm10.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "19"}, "SEC-428", null, null], [8866, "", "变化最大的当属小雨。", null, "街_診療所b", "bgm10.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "19"}, "SEC-428", null, null], [8867, "", "不过，这就是题外话了。", null, "街_診療所b", "bgm10.opus", {"char": "丛雨", "file": "ムラサメ.stand", "dress": "私服", "face": "19"}, "SEC-428", null, null], [8868, "廉太郎", "「哟，将臣，我把刚收获的甜瓜拿来了」", "ren428_001.ogg", "街_診療所b", "bgm10.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "26"}, "SEC-428", null, null], [8869, "将臣", "「哎？真有你的啊，你是怎么弄到的？」", null, "街_診療所b", "bgm10.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "26"}, "SEC-428", null, null], [8870, "小春", "「这个……他突然跑到别人田里面去，不停地求人家分他一颗，真是不害臊，我看着都不好意思了」", "koh428_001.ogg", "街_診療所b", "bgm10.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "34"}, "SEC-428", null, null], [8871, "廉太郎", "「喂，小春！你说出来干嘛，我这还不是为了哥们着想！」", "ren428_002.ogg", "街_診療所b", "bgm10.opus", {"char": "廉太郎", "file": "廉太郎.stand", "dress": "制服", "face": "21"}, "SEC-428", null, null], [8872, "小春", "「你骗谁啊！我还不知道你那点心思，你肯定是自己想吃吧！」", "koh428_002.ogg", "街_診療所b", "bgm10.opus", {"char": "小春", "file": "小春.stand", "dress": "制服", "face": "06"}, "SEC-428", null, null], [8873, "美津叶", "「各位同学，这里好歹是医院啊」", "miz428_001.ogg", "街_診療所b", "bgm10.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "14"}, "SEC-428", null, null], [8874, "美津叶", "「希望大家安静点，不要大声喧哗」", "miz428_002.ogg", "街_診療所b", "bgm10.opus", {"char": "美津叶", "file": "みづは.stand", "dress": "白衣", "face": "23"}, "SEC-428", null, null], [8875, "", "反正在那之后，我那喧闹又和睦的日常生活总算是回来了。", null, "街_診療所b", "bgm10.opus", null, "SEC-428", null, null], [8876, "", "我真的是松了一口气。", null, "街_診療所b", "bgm10.opus", null, "SEC-428", null, null], [8877, "", "对了，在现实中，宿体也确实从蕾娜的体内分离了出来。", null, "神社_境内a", "bgm10.opus", null, "SEC-428", null, null], [8878, "安晴", "「我觉得，我必须用我能想到的最郑重的方式供奉他们」", "yas428_001.ogg", "神社_境内a", "bgm10.opus", {"char": "安晴", "file": "安晴.stand", "dress": "神主", "face": "01"}, "SEC-428", null, null], [8879, "玄十郎", "「我身为氏子总代表，也会尽力出资的」", "gen428_001.ogg", "神社_境内a", "bgm10.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "09"}, "SEC-428", null, null], [8880, "", "大人们似乎准备在供奉土地神的正殿旁边再建一座专门供奉从云和白狛的副殿。", null, "神社_境内a", "bgm10.opus", null, "SEC-428", null, null], [8881, "", "虽说是副殿，但建造神社可不是那么容易的事，不仅花时间，还非常花钱。", null, "神社_境内a", "bgm10.opus", null, "SEC-428", null, null], [8882, "", "据说要等到几年之后才能建好。", null, "神社_境内a", "bgm10.opus", null, "SEC-428", null, null], [8883, "安晴", "「毕竟，我们得把它建成一座一千年以后也会有人来参拜的神社，否则就没有意义」", "yas428_002.ogg", "神社_境内a", "bgm10.opus", {"char": "安晴", "file": "安晴.stand", "dress": "神主", "face": "04"}, "SEC-428", null, null], [8884, "玄十郎", "「虽然感恩并不能用钱来表示，但是为了留下一座能够永远延续下去的神社，必要的经费是少不了的」", "gen428_002.ogg", "神社_境内a", "bgm10.opus", {"char": "玄十郎", "file": "玄十郎.stand", "dress": "私服", "face": "02"}, "SEC-428", null, null], [8885, "", "这也算是对未来的一种投资了。", null, "神社_境内a", "bgm10.opus", null, "SEC-428", null, null], [8886, "", "而且我们的目的不仅仅是向神灵传达我们的感恩之情，我们更需要让后人了解心怀感恩的重要性。", null, "神社_境内a", "bgm10.opus", null, "SEC-428", null, null], [8887, "", "我真心期望，这样的传统能流传后世。", null, "神社_境内a", "bgm10.opus", null, "SEC-428", null, null], [8888, "", "至于全新的春日祭，也早就提上了议程。年底前能做什么？具体该怎么举办？", null, "神社_境内a", "bgm10.opus", null, "SEC-428", null, null], [8889, "", "大家早已开始了紧锣密鼓的准备。", null, "神社_境内a", "bgm10.opus", null, "SEC-428", null, null], [8890, "", "终于，半年之后的今天——我迎来了第二次春日祭。", null, "空_青空", "bgm10.opus", null, "SEC-428", null, null], [8891, "", "这次，有她陪在我身边。", null, "空_青空", "bgm10.opus", null, "SEC-428", null, null], [8892, "蕾娜", "「哇哦，将臣！那家店卖的什么呀！？」", "len428_006.ogg", "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8893, "将臣", "「应该是杏子糖吧？一般是用李子之类的水果裹上糖稀，放在最中皮上吃」", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8894, "将臣", "「哎，最近还有用菠萝和草莓做的杏子糖啊」", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8895, "蕾娜", "「我想尝尝！」", "len428_007.ogg", "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8896, "将臣", "「可以啊，但你还吃得下吗？」", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8897, "蕾娜", "「日本的庆典活动上有太多没见过的东西了，我全部都想要嘛，啊！」", "len428_008.ogg", "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8898, "蕾娜", "「快看！那里还有鱼，有个水槽里面全是鱼啊！这个是什么呀？」", "len428_009.ogg", "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8899, "将臣", "「你没听说过捞金鱼吗？……旁边竟然还有钓泥鳅，确实够稀罕」", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8900, "蕾娜", "「是吗？我听说今年的摊位比以前更多」", "len428_010.ogg", "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8901, "", "我们并排走在参道上，挨个逛着参道两旁的每一家摊位。", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8902, "", "蕾娜看着各种各样的摊位，两眼放光。", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8903, "", "但是对我来说，蕾娜身穿浴衣的模样才是最耀眼的。", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8904, "", "春日祭真是太棒了！", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8905, "蕾娜", "「嗯？怎么了，将臣？」", "len428_011.ogg", "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8906, "将臣", "「没什么，我就是觉得……你是这个世上最美的女神」", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8907, "", "蕾娜说我的说话方式越来越像个欧美人了。", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8908, "蕾娜", "「嘿嘿……那你就是日本第一武士了，可谓是“酷日本”的代言人呀」", "len428_012.ogg", "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8909, "将臣", "「蕾娜！」", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8910, "蕾娜", "「将臣！」", "len428_013.ogg", "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8911, "", "我们肩并肩，脸颊也紧紧地贴在一起，一秒都不愿意分开。", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8912, "", "虽然她这话说得让人搞不清到底是夸还是贬，但她的出发点一定是爱。", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8913, "蕾娜", "「对了，将臣，刚才买的章鱼烧就快凉了，你快喂我一个吧……啊～」", "len428_014.ogg", "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8914, "将臣", "「好啊，很烫的，你慢点吃啊」", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8915, "蕾娜", "「好烫好烫……呼呼」", "len428_015.ogg", "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8916, "蕾娜", "「太好吃了！」", "len428_016.ogg", "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8917, "", "我感觉我们天天都在干这些事。", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8918, "蕾娜", "「将臣？芳乃的舞蹈应该还没开始吧？」", "len428_017.ogg", "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8919, "将臣", "「还没呢，那可是重头戏，咱们哪能错过」", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8920, "将臣", "「不过，她给我们准备了内部人员专用席位，我们可以再逛一会儿的」", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8921, "蕾娜", "「好想快点看她跳舞啊，春日祭好玩的东西实在太多，我们根本逛不完，真是遗憾」", "len428_018.ogg", "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8922, "", "而且蕾娜一会儿还得回旅馆干活。", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8923, "", "最近是最忙的时期，但她还是挤出了一些时间，在去看舞蹈之前陪我逛了逛。", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8924, "将臣", "「嗯，从今年开始，神乐舞也不再是朝武一个人跳，而是她和孩子们一起跳吧」", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8925, "蕾娜", "「是的！穗织的孩子们练得可认真了！」", "len428_019.ogg", "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8926, "蕾娜", "「不过最遗憾的是……昨天的铠甲武士游行我只看了一点点」", "len428_020.ogg", "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8927, "将臣", "「哈哈，幸亏你只看了一点点。毕竟今年我也被迫参加了」", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8928, "蕾娜", "「你在说什么呢！你穿着那一身行头可帅气了」", "len428_021.ogg", "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8929, "蕾娜", "「当时我就想，你真的是日本第一武士……」", "len428_022.ogg", "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8930, "", "日本第一，对我来说还很遥远啊。", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8931, "", "但既然蕾娜愿意这么想，那倒也挺好。", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8932, "将臣", "「对了，我突然想起来，其实有一件事我一直想不通」", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8933, "蕾娜", "「是关于春日祭的事情吗？」", "len428_023.ogg", "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8934, "将臣", "「不是，是我在梦中体验宿体的记忆时留下的疑惑」", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8935, "蕾娜", "「怎么现在突然搬出那么早以前的事？我现在都只记得个大概了」", "len428_024.ogg", "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8936, "将臣", "「……确实」", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8937, "", "不过，也许正因为今天是春日祭，我才会把这件事拿出来说。", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8938, "", "毕竟一年就这一次机会，还是说出来看看吧。", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8939, "将臣", "「你还记得那个跟我合体的武士吗？」", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8940, "将臣", "「那个人，是真的长得像我吗？」", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8941, "蕾娜", "「是的，那个人的风貌和气质真的非常像你，这件事你想不通吗？」", "len428_025.ogg", "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8942, "将臣", "「怎么说呢，当时你说他像我，我还以为他是我家的祖先，或者是鞍马家的祖先」", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8943, "将臣", "「毕竟他最开始就是个普通家臣而已」", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8944, "将臣", "「所以我当时以为，他的主公是朝武家的祖先」", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8945, "将臣", "「但实际上，他本人才是朝武家的祖先」", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8946, "将臣", "「于是我就想，我跟那个武士真的仅仅只是脸长得像而已吗？虽然这件事真的非常无所谓」", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8947, "", "所以我才一直没说出口。", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8948, "", "但不知为何，蕾娜突然沉默了。而且看上去好像有点生气。", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8949, "蕾娜", "「…………哼～」", "len428_026.ogg", "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8950, "将臣", "「蕾娜？」", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8951, "蕾娜", "「哼哼～～」", "len428_027.ogg", "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8952, "", "明明皱着眉头，却看上去这么可爱，这太犯规了。", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8953, "将臣", "「呃，那个，你怎么了？」", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8954, "蕾娜", "「这件事你不需要知道答案」", "len428_028.ogg", "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8955, "将臣", "「等等，什么意思啊？？」", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8956, "将臣", "「我这只是随口一问而已，难道真的有什么含义在里面吗！」", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8957, "蕾娜", "「倒不是说有什么含义在里面……」", "len428_029.ogg", "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8958, "", "蕾娜还是不太愿意开口。", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8959, "", "不过，也不知是这节日气氛让她改变了想法，还是她觉得半年前的事情已经无所谓——", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8960, "", "她接下来说的这些，让我大吃一惊。", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8961, "蕾娜", "「我在丛云那边，看到了她的记忆」", "len428_030.ogg", "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8962, "将臣", "「……嗯」", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8963, "蕾娜", "「所以，我差不多能猜到」", "len428_031.ogg", "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8964, "蕾娜", "「丛雨丸在挑选主人的时候，会考察这个人跟丛云的初恋对象长得有几分相似」", "len428_032.ogg", "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8965, "蕾娜", "「至少，长得像的人可以放宽要求」", "len428_033.ogg", "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8966, "将臣", "「哎？为什么？」", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8967, "蕾娜", "「唔～将臣，你这么不懂女人心，我都不知道是该高兴还是该叹息」", "len428_034.ogg", "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8968, "蕾娜", "「简单来说，你的外表是丛云喜欢的类型啦」", "len428_035.ogg", "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8969, "将臣", "「……啊？」", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8970, "将臣", "「喔——」", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8971, "", "原来如此，如果她还有意识，那就确实有这种可能性！", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8972, "将臣", "「这点事，你怎么说得这么不情愿啊？」", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8973, "蕾娜", "「……将臣，你这情商有点说不过去了哦」", "len428_036.ogg", "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8974, "蕾娜", "「这么棒的男生，却连女孩子的小心思都看不出来，我好担心啊」", "len428_037.ogg", "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8975, "将臣", "「不不，没你想得那么严重啦……嗯？」", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8976, "", "难道蕾娜是在嫉妒吗？", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8977, "", "什么嘛，原来是这样。", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8978, "蕾娜", "「哎，你不要笑呀。也不要闭着嘴巴笑啊，将臣」", "len428_038.ogg", "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8979, "将臣", "「我忍不住呀」", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8980, "将臣", "「放心吧，我眼里只有你」", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8981, "", "也许正因如此，我才不会去想那些不必要的事情。", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8982, "", "因为我知道我根本不可能喜欢上其他女孩子。", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8983, "将臣", "「我的女神只有你一个」", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8984, "蕾娜", "「嗯……哼～哼……噗」", "len428_039.ogg", "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8985, "", "蕾娜还是没能维持住生气的表情。", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8986, "蕾娜", "「嘿嘿，真是拿你没办法」", "len428_040.ogg", "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8987, "蕾娜", "「毕竟我是全世界最爱你的人！」", "len428_041.ogg", "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8988, "", "在这片土地相遇后，她成了我最重要的人。", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8989, "", "本来居住在世界另一端的她，如今却在我身边。", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8990, "", "来到穗织之后，我体验了各式各样的伤痛。", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8991, "", "外公的特训，真是辛苦得要命。", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8992, "", "有时候我都感觉自己快要累死了。", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8993, "", "但是，这片土地确实为我带来了奇迹，让我邂逅了无可替代的她。", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8994, "", "所以，在这个万物复苏的季节，我想借此机会传达我的感恩。", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8995, "", "愿千年之恋，有朝一日能使万花怒放。", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8996, "", "愿我们的感情，也能枝繁叶茂。", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8997, "", "愿我们能成为懂得奉献，懂得互助的人。", null, "空_青空", "bgm54.opus", null, "SEC-428", "ev410a", null], [8998, "", "感谢你们。", null, "空_青空", "bgm54.opus", null, "SEC-428", null, null], [8999, "", "感谢让我们怀有如此心境的所有人，所有事物。", null, "空_青空", "bgm54.opus", null, "SEC-428", null, null], [9000, "", "愿春日祭，今后也能走过无数个春秋。", null, "空_青空", "bgm54.opus", null, "SEC-428", null, null], [9001, "", "我在心中默默地祈祷着。", null, "空_青空", "bgm54.opus", null, "SEC-428", null, null], [9002, "", "今天，我们跑出来度蜜月。", null, "旅館_旅館前a", "bgm54.opus", null, "SEC-429", null, null], [9003, "蕾娜", "「哇噢，将臣！这房间真棒」", "len429_001.ogg", "旅館_客室a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "02"}, "SEC-429", null, null], [9004, "将臣", "「啊，嗯，房间不错，虽然感觉好像在哪里见过」", null, "旅館_客室a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "02"}, "SEC-429", null, null], [9005, "", "但是，我们却跑来了志那都庄。", null, "旅館_客室a", "bgm44.opus", null, "SEC-429", null, null], [9006, "心子", "「感谢两位客人光临」", "mot429_001.ogg", "旅館_客室a", "bgm44.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "01"}, "SEC-429", null, null], [9007, "", "至少猪谷阿姨这位职业服务业从业者没有甩下一句“你们全都很熟悉吧”。", null, "旅館_客室a", "bgm44.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "01"}, "SEC-429", null, null], [9008, "", "只要正常付钱正常住宿，她就会以招待客人的礼节招待我们吧。", null, "旅館_客室a", "bgm44.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "01"}, "SEC-429", null, null], [9009, "", "所谓的度蜜月，实际上也只是我们自己制造的名义。", null, "旅館_客室a", "bgm44.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "01"}, "SEC-429", null, null], [9010, "", "简而言之，就跟玩角色扮演差不多。", null, "旅館_客室a", "bgm44.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "01"}, "SEC-429", null, null], [9011, "蕾娜", "「谢谢你给我们用房间啊，掌柜的！」", "len429_002.ogg", "旅館_客室a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "02"}, "SEC-429", null, null], [9012, "心子", "「没事的，反正不是旺季」", "mot429_002.ogg", "旅館_客室a", "bgm44.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "11"}, "SEC-429", null, null], [9013, "", "啊，恢复正常了。", null, "旅館_客室a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "02"}, "SEC-429", null, null], [9014, "心子", "「但是，既然都要出钱，还是去其他旅馆更有旅行的感觉吧？」", "mot429_003.ogg", "旅館_客室a", "bgm44.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "13"}, "SEC-429", null, null], [9015, "将臣", "「没事，蕾娜似乎特别中意志那都庄」", null, "旅館_客室a", "bgm44.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "13"}, "SEC-429", null, null], [9016, "蕾娜", "「是的，今天我就当自己失忆了，准备好好享受一番」", "len429_003.ogg", "旅館_客室a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "12"}, "SEC-429", null, null], [9017, "心子", "「嗯，你能这么说我很高兴……可是怎么说呢」", "mot429_004.ogg", "旅館_客室a", "bgm44.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "14"}, "SEC-429", null, null], [9018, "心子", "「你也经常住这里的吧，包括客房之外的房间」", "mot429_005.ogg", "旅館_客室a", "bgm44.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "12"}, "SEC-429", null, null], [9019, "", "是的，没错。", null, "旅館_客室a", "bgm44.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "12"}, "SEC-429", null, null], [9020, "", "感觉很不好意思啊！", null, "旅館_客室a", "bgm44.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "12"}, "SEC-429", null, null], [9021, "蕾娜", "「话是这么说……但我很想制造属于我们两个人的回忆」", "len429_004.ogg", "旅館_客室a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "07"}, "SEC-429", null, null], [9022, "蕾娜", "「因为我很快就要……」", "len429_005.ogg", "旅館_客室a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "07"}, "SEC-429", null, null], [9023, "蕾娜", "「……回到自己的国家去了」", "len429_006.ogg", "旅館_客室a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "30"}, "SEC-429", null, null], [9024, "心子", "「是啊，你要更新签证，需要回国两周，我也批准了你的假期了吧」", "mot429_006.ogg", "旅館_客室a", "bgm44.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "03"}, "SEC-429", null, null], [9025, "将臣", "「竟、竟然要回去两周！」", null, "旅館_客室a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "04"}, "SEC-429", null, null], [9026, "蕾娜", "「是的，竟然有两周」", "len429_007.ogg", "旅館_客室a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "25"}, "SEC-429", null, null], [9027, "心子", "「唉，可是我听说三天以后，巫女大人、小春和廉太郎要一道去毕业旅行」", "mot429_007.ogg", "旅館_客室a", "bgm44.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "04"}, "SEC-429", null, null], [9028, "心子", "「他们说要去你家暂住一段时间来着？」", "mot429_008.ogg", "旅館_客室a", "bgm44.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "12"}, "SEC-429", null, null], [9029, "", "是的，我们准备去蕾娜家住，还准备一起去圣诞老人村观光。", null, "旅館_客室a", "bgm44.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "12"}, "SEC-429", null, null], [9030, "", "终于到了兑现约定的日子……", null, "旅館_客室a", "bgm44.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "12"}, "SEC-429", null, null], [9031, "蕾娜", "「三天……」", "len429_008.ogg", "旅館_客室a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "07"}, "SEC-429", null, null], [9032, "将臣", "「……有三天不能见面，简直就是折磨」", null, "旅館_客室a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "07"}, "SEC-429", null, null], [9033, "蕾娜", "「我坐飞机的时候甚至不能跟将臣发邮件打电话！整整１１个小时啊」", "len429_009.ogg", "旅館_客室a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "22"}, "SEC-429", null, null], [9034, "将臣", "「蕾娜」", null, "旅館_客室a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "22"}, "SEC-429", null, null], [9035, "蕾娜", "「将臣！」", "len429_010.ogg", "旅館_客室a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "07"}, "SEC-429", null, null], [9036, "心子", "「……」", "mot429_009.ogg", "旅館_客室a", "bgm44.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "14"}, "SEC-429", null, null], [9037, "", "不管三七二十一，先拥抱一个再说。", null, "旅館_客室a", "bgm44.opus", null, "SEC-429", null, null], [9038, "蕾娜", "「所以……为了不让将臣在我离开的时候感到寂寞，我想为他制造一些回忆」", "len429_011.ogg", "旅館_客室a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "02"}, "SEC-429", null, null], [9039, "将臣", "「是啊，我也很难受，但这样就能忍耐一下了」", null, "旅館_客室a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "02"}, "SEC-429", null, null], [9040, "蕾娜", "「嘿嘿，今天一天我就是将臣的老婆了，是吧老公？」", "len429_012.ogg", "旅館_客室a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "27"}, "SEC-429", null, null], [9041, "将臣", "「哎呀，好期待啊♪」", null, "旅館_客室a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "27"}, "SEC-429", null, null], [9042, "", "最近大家都说我除了态度之外，情绪的变化也变得十分激烈，", null, "旅館_客室a", "bgm44.opus", null, "SEC-429", null, null], [9043, "", "我觉得那是他们想太多了。", null, "旅館_客室a", "bgm44.opus", null, "SEC-429", null, null], [9044, "", "要我说，三天不能见女朋友，换谁都得变成这样。", null, "旅館_客室a", "bgm44.opus", null, "SEC-429", null, null], [9045, "心子", "「那么，就请两位享受本旅店的新婚旅行套餐吧」", "mot429_010.ogg", "旅館_客室a", "bgm44.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "02"}, "SEC-429", null, null], [9046, "心子", "「餐饮方面也一定会让两位满意」", "mot429_011.ogg", "旅館_客室a", "bgm44.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "01"}, "SEC-429", null, null], [9047, "", "你看，猪谷阿姨面不改色的，这不是说明我们很正常吗。", null, "旅館_客室a", "bgm44.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "01"}, "SEC-429", null, null], [9048, "蕾娜", "「哇噢，代我向厨师长问好！」", "len429_013.ogg", "旅館_客室a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "01"}, "SEC-429", null, null], [9049, "心子", "「好的」", "mot429_012.ogg", "旅館_客室a", "bgm44.opus", {"char": "心子", "file": "心子.stand", "dress": "仕事着", "face": "03"}, "SEC-429", null, null], [9050, "", "猪谷阿姨略显拘谨地鞠了一躬就离开了房间。", null, "旅館_客室a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "01"}, "SEC-429", null, null], [9051, "", "房里只剩我们两个，我不禁伸手缠住了蕾娜的手指。", null, "旅館_客室a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "01"}, "SEC-429", null, null], [9052, "蕾娜", "「将臣……你就没有什么话要对你的新娘子说吗？」", "len429_014.ogg", "旅館_客室a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "15"}, "SEC-429", null, null], [9053, "将臣", "「有很多，太多了，我都不知道从哪里说起」", null, "旅館_客室a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "15"}, "SEC-429", null, null], [9054, "", "我将自己的额头贴了上去，蕾娜则将手搭在了我肩上。", null, "旅館_客室a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "15"}, "SEC-429", null, null], [9055, "蕾娜", "「没事，你可以慢慢考虑，我们有的是时间」", "len429_015.ogg", "旅館_客室a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "03"}, "SEC-429", null, null], [9056, "蕾娜", "「不过……在你想好之前，可别离开我哦」", "len429_016.ogg", "旅館_客室a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "19"}, "SEC-429", null, null], [9057, "将臣", "「哈哈哈，那我更愿意什么都不说，永远和你待在一起」", null, "旅館_客室a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "19"}, "SEC-429", null, null], [9058, "将臣", "「不过，也是」", null, "旅館_客室a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "19"}, "SEC-429", null, null], [9059, "将臣", "「最近我有个新发现」", null, "旅館_客室a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "19"}, "SEC-429", null, null], [9060, "蕾娜", "「告诉我吧」", "len429_017.ogg", "旅館_客室a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "26"}, "SEC-429", null, null], [9061, "将臣", "「我可以把老婆这个词读作“天使”」", null, "旅館_客室a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "26"}, "SEC-429", null, null], [9062, "蕾娜", "「哇噢，嘿嘿……我的老公真厉害，这可是全新的发现啊」", "len429_018.ogg", "旅館_客室a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "02"}, "SEC-429", null, null], [9063, "蕾娜", "「那这样的话，我也有一个新发现」", "len429_019.ogg", "旅館_客室a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "01"}, "SEC-429", null, null], [9064, "将臣", "「什么，告诉我」", null, "旅館_客室a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "01"}, "SEC-429", null, null], [9065, "蕾娜", "「我可以把老公这个词读作“快吻我”」", "len429_020.ogg", "旅館_客室a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "15"}, "SEC-429", null, null], [9066, "将臣", "「噗……哈哈」", null, "旅館_客室a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "15"}, "SEC-429", null, null], [9067, "蕾娜", "「嘿嘿」", "len429_021.ogg", "旅館_客室a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "16"}, "SEC-429", null, null], [9068, "将臣", "「太勉强了」", null, "旅館_客室a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "16"}, "SEC-429", null, null], [9069, "", "不过表达爱意还是越直白越好。", null, "旅館_客室a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "16"}, "SEC-429", null, null], [9070, "蕾娜", "「啾♪……嘻嘻」", "len429_022.ogg", "旅館_客室a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "27"}, "SEC-429", null, null], [9071, "蕾娜", "「老公，今天我们好好享受一下吧」", "len429_023.ogg", "旅館_客室a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "19"}, "SEC-429", null, null], [9072, "将臣", "「嗯」", null, "旅館_客室a", "bgm44.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "19"}, "SEC-429", null, null], [9073, "", "然而我并没有发现，蕾娜说的享受竟然有那么直白的意思。", null, "旅館_客室a", "bgm44.opus", null, "SEC-429", null, null], [9074, "", "在那之后，我们一起打了乒乓，打了桌球……", null, "空_夕空", "bgm44.opus", null, "SEC-429", null, null], [9075, "", "还在家庭浴池里一起洗了澡。", null, "空_夕空", "bgm44.opus", null, "SEC-429", null, null], [9076, "", "……没做该做的事，要说奇怪也是有点怪，不过反正已经洗完了。", null, "空_夕空", "bgm44.opus", null, "SEC-429", null, null], [9077, "", "甚至可以说，正因为没做该做的事，我们才能更纯粹地享受旅行。", null, "空_夕空", "bgm44.opus", null, "SEC-429", null, null], [9078, "蕾娜", "「不愧是厨师长，每道菜都很棒！」", "len429_024.ogg", "旅館_客室d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "02"}, "SEC-429", null, null], [9079, "将臣", "「是啊，不论什么时候吃，志那都庄的菜都是最棒的」", null, "旅館_客室d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "02"}, "SEC-429", null, null], [9080, "", "但是，端上来的菜是烤鳗鱼还有打成粉的山药……", null, "旅館_客室d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "01"}, "SEC-429", null, null], [9081, "", "牡蛎脆皮烙菜，甲鱼火锅……新婚旅行套餐都这样的吗？", null, "旅館_客室d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "01"}, "SEC-429", null, null], [9082, "", "我不禁这样想道。", null, "旅館_客室d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "01"}, "SEC-429", null, null], [9083, "", "甚至让我们在最后把甲鱼血和烧酒掺一起一饮而尽……", null, "旅館_客室d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "01"}, "SEC-429", null, null], [9084, "", "我照做之后，现在感觉浑身发热。", null, "旅館_客室d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "01"}, "SEC-429", null, null], [9085, "", "或者说，身体的某部分特别热。所以我应该不是醉了。", null, "旅館_客室d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "01"}, "SEC-429", null, null], [9086, "蕾娜", "「嘻嘻嘻，你怎么了，老公」", "len429_025.ogg", "旅館_客室d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "27"}, "SEC-429", null, null], [9087, "", "蕾娜贴在我肩上，向我撒娇。", null, "旅館_客室d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "27"}, "SEC-429", null, null], [9088, "将臣", "「你看不出来吗？而且，你应该已经知道了吧？」", null, "旅館_客室d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "27"}, "SEC-429", null, null], [9089, "蕾娜", "「真是的，老公，这是新婚旅行，那样的事情……当然都要……算在里面啦」", "len429_026.ogg", "旅館_客室d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "27h"}, "SEC-429", null, null], [9090, "将臣", "「是啊」", null, "旅館_客室d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "27h"}, "SEC-429", null, null], [9091, "", "我本来也打算做那种事。", null, "旅館_客室d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "27h"}, "SEC-429", null, null], [9092, "", "而且这么多次了，我也没必要客气什么。", null, "旅館_客室d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "27h"}, "SEC-429", null, null], [9093, "", "所以我毫不客气地抱住了蕾娜的肩。", null, "旅館_客室d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "27h"}, "SEC-429", null, null], [9094, "蕾娜", "「啊，不行呀，代官大人」", "len429_027.ogg", "旅館_客室d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "06"}, "SEC-429", null, null], [9095, "将臣", "「哈哈哈，来嘛，来嘛」", null, "旅館_客室d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "06"}, "SEC-429", null, null], [9096, "", "感觉就像个好色的大叔，不过这种时候还是这样做更有趣。", null, "旅館_客室d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "06"}, "SEC-429", null, null], [9097, "", "嗯，我应该还是有点醉了！", null, "旅館_客室d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "06"}, "SEC-429", null, null], [9098, "", "可蕾娜的巨乳压过来之后，我一下就冷静不下来了。", null, "旅館_客室d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "06"}, "SEC-429", null, null], [9099, "将臣", "「……嗯！？」", null, "旅館_客室d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "06"}, "SEC-429", null, null], [9100, "蕾娜", "「哎呀，你怎么了，将臣？」", "len429_028.ogg", "旅館_客室d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "25"}, "SEC-429", null, null], [9101, "将臣", "「没，这点肢体接触……我还以为自己早就习惯了」", null, "旅館_客室d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "25"}, "SEC-429", null, null], [9102, "蕾娜", "「噢，噢……」", "len429_029.ogg", "旅館_客室d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "03"}, "SEC-429", null, null], [9103, "", "看来蕾娜已经注意到了我双腿之间的情况。", null, "旅館_客室d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "03"}, "SEC-429", null, null], [9104, "蕾娜", "「喝了甲鱼血，变成这样很正常啊」", "len429_030.ogg", "旅館_客室d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "10"}, "SEC-429", null, null], [9105, "将臣", "「还真是因为那个啊」", null, "旅館_客室d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "10"}, "SEC-429", null, null], [9106, "蕾娜", "「是的……就算什么也不做，也会变成这样的，很正常」", "len429_031.ogg", "旅館_客室d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "25"}, "SEC-429", null, null], [9107, "将臣", "「唔，嗯，可是……」", null, "旅館_客室d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "25"}, "SEC-429", null, null], [9108, "", "感觉蕾娜比平时可爱了两分。", null, "旅館_客室d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "25"}, "SEC-429", null, null], [9109, "", "当然，她一直是全世界最可爱的，可现在竟然看上去更可爱了……", null, "旅館_客室d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "25"}, "SEC-429", null, null], [9110, "将臣", "「我的老婆真是个天使啊」", null, "旅館_客室d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "25"}, "SEC-429", null, null], [9111, "蕾娜", "「你的眼神都变成大灰狼了」", "len429_032.ogg", "旅館_客室d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "03"}, "SEC-429", null, null], [9112, "", "嗯，说实话，我自己也有自知之明。", null, "旅館_客室d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "03"}, "SEC-429", null, null], [9113, "", "可蕾娜却挑逗着我，在我胸口画圈圈。", null, "旅館_客室d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "03"}, "SEC-429", null, null], [9114, "蕾娜", "「我呢……觉得被大灰狼吃掉，也没什么不好的」", "len429_033.ogg", "旅館_客室d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "17"}, "SEC-429", null, null], [9115, "将臣", "「这、这样的话，蕾娜，我……」", null, "旅館_客室d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "17"}, "SEC-429", null, null], [9116, "蕾娜", "「嘻嘻，还是算了」", "len429_034.ogg", "旅館_客室d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "15"}, "SEC-429", null, null], [9117, "", "简直是折磨啊！", null, "旅館_客室d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "15"}, "SEC-429", null, null], [9118, "蕾娜", "「说不定不是大灰狼吃掉天使」", "len429_035.ogg", "旅館_客室d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "26"}, "SEC-429", null, null], [9119, "蕾娜", "「其实……天使或许更想吃掉大灰狼哦」", "len429_036.ogg", "旅館_客室d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "19"}, "SEC-429", null, null], [9120, "将臣", "「……什么意思？」", null, "旅館_客室d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "19"}, "SEC-429", null, null], [9121, "蕾娜", "「嘻嘻嘻，老公……今晚让我们好好疼爱彼此吧♪」", "len429_037.ogg", "旅館_客室d", "bgm05.opus", {"char": "蕾娜", "file": "レナ.stand", "dress": "私服", "face": "24h"}, "SEC-429", null, null], [9122, "蕾娜", "「啾……嗯……老公的……大●鸡……这就变得这么大啊……啾」", "len429_038.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9123, "将臣", "「还不是因为你……」", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9124, "", "我正想着她怎么把脑袋垂了下去，结果下体就传来嘴唇的触感。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9125, "", "被这样一个湿润温暖的舌头裹着，我的那话儿这就开始按捺不住颤抖起来了。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9126, "蕾娜", "「嘻嘻嘻，你……已经变得这么硬了……啾，啾……好像很想制造我们俩的小孩一样，啾」", "len429_039.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9127, "蕾娜", "「一跳一跳的，很有精神……啾，啾，啾」", "len429_040.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9128, "将臣", "「一方面是因为刚才吃的菜」", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9129, "将臣", "「而你……你的技术也越来越精湛了」", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9130, "蕾娜", "「这是……啾，嗯……因为，啾，啾……我们练习了……那么多次啊，啾」", "len429_041.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9131, "", "蕾娜一开始就很熟练了。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9132, "", "但这次她没有用手，只用嘴唇支撑住我那话儿，将它深深含在喉咙深处。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9133, "蕾娜", "「嗯噗……啾！啾……嗯，啾，嗯，啾！啾」", "len429_042.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9134, "将臣", "「呃……唔！」", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9135, "", "这堪称完美的深喉让我不禁叫出了声来。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9136, "蕾娜", "「啾……将臣的大●鸡……啾！好可爱啊，啾」", "len429_043.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9137, "蕾娜", "「再……多叫两声，多叫两声……好可爱的。啾，啾……」", "len429_044.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9138, "", "蕾娜加快了速度。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9139, "", "她没有把我吐出来，也没有用牙齿碰到我，我只感受到一波一波的强烈快感。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9140, "蕾娜", "「啾，嗯……嗯……唔，好苦……啾……嗯，啾，嗯，啾，有什么漏出来了」", "len429_045.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9141, "蕾娜", "「啾，啾……唔，你越来越舒服了呀，嘻嘻嘻……啾，啾，唔，啊」", "len429_046.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9142, "将臣", "「是、是你太厉害了」", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9143, "蕾娜", "「嘻嘻……那就……啾，啾……当是这样的吧，啾♪」", "len429_047.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9144, "", "当然，我并不打算束手就擒。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9145, "", "我弯过身子，将手从蕾娜腋下插进去，一把抓住了她的巨乳。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9146, "蕾娜", "「啊！唔，啊……老公，啊……啾，唔……啾，啊，啊！」", "len429_048.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9147, "", "我也不再慌慌张张地一顿乱揉了。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9148, "", "这回我慢慢地在她胸前画圆。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9149, "", "她的胸那么大，光是这样摸上去就很舒服了。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9150, "蕾娜", "「啊，啊！啾，唔……你揉得……啊，好温柔……啾，啊！哇！？」", "len429_049.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9151, "", "接着我立刻出其不意地掐了掐她的乳头。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9152, "", "蕾娜肩膀一颤，乳房也随之抖了一抖。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9153, "蕾娜", "「呀，唔！将、将臣，你、你太奸诈了……啊！」", "len429_050.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9154, "蕾娜", "「这样我……啾，嗯……还怎么好好舔嘛……啾，啊，啊！」", "len429_051.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9155, "将臣", "「我一个人舒服多对不起亲爱的老婆啊」", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9156, "蕾娜", "「哇，啊！嗯……那么，啾……做老婆的也不能……轻易认输啦，啾！」", "len429_052.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9157, "", "蕾娜的肩膀时不时会颤抖，但她依然努力地含着我的下体。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9158, "", "我的龟头顶在她的喉咙里，有种被咽下去的感觉。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9159, "蕾娜", "「嗯……唔，啾！嗯……哇，看我，嗯，啾啾！」", "len429_053.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9160, "蕾娜", "「啾，嗯，用喉咙把你榨出来。啾，啾，啾！」", "len429_054.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9161, "将臣", "「哇！蕾、蕾娜，你……再这样我要忍不住了！」", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9162, "蕾娜", "「嘻嘻，没事的……啾，唔！啾……不要忍耐啦，啾，啾！」", "len429_055.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9163, "", "她的舌头抵在我的包皮系带上，脸颊的肉也挤压着我。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9164, "", "而我的冠状沟恰好卡在她喉咙的入口处，进出几次，能忍住的也会忍不住。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9165, "蕾娜", "「唔，唔！啾，啾……唔，唔，啾！啾！」", "len429_056.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9166, "", "但是，她依然毫不留情地用力刺激着我。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9167, "", "越是去抵抗越是去忍耐，我越会感受到火热的快感。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9168, "蕾娜", "「嗯，啾！嗯，啾，将臣……老公，嗯，啾……射吧，射出来吧」", "len429_057.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9169, "蕾娜", "「老公的大●鸡……快点舒服起来吧，嗯……啾！」", "len429_058.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9170, "", "我的下腹越来越烫。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9171, "", "不管怎么发力去忍耐，我都忍不住了！", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9172, "蕾娜", "「啾，唔！射吧，射吧……越多越好，老公，啾！」", "len429_059.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9173, "将臣", "「要、要射了！让我射你脸上」", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9174, "蕾娜", "「啾，唔！好……老公，随你……射在哪里，嗯，啾！」", "len429_060.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9175, "蕾娜", "「老公，老公！将臣……将臣，嗯，啾！？」", "len429_061.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9176, "蕾娜", "「嗯！哇……呀，射吧……啊」", "len429_062.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9177, "", "伴随着一股难以忍耐的快感，我将小兄弟拔了出来。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9178, "蕾娜", "「唔，啊♪嘻嘻，将臣的精液……射在了脸上……嗯，嗯」", "len429_063.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9179, "蕾娜", "「黏糊糊的，粘在脸上……啊，哇……」", "len429_064.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9180, "", "白色的岩浆奔涌出来，射得蕾娜一阵迷糊。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9181, "", "她那日本人不会有的透明而洁白的肌肤，被染上了另一种泛黄的白色。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9182, "蕾娜", "「呼……呼，然后呢？你……一次……是满足不了的吧，啾」", "len429_065.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9183, "", "蕾娜轻轻吻了吻依然渗着精液的龟头。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9184, "", "我的那话儿不禁抖了抖。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9185, "蕾娜", "「啊♪……果然还很精神嘛，啾……嗯，我说，老公」", "len429_066.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9186, "将臣", "「这是因为甲鱼吗？」", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9187, "蕾娜", "「嘻嘻嘻，你本来……就有这么厉害的嘛」", "len429_067.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9188, "", "或许吧。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9189, "", "但我也感受到了超乎寻常的冲动。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9190, "将臣", "「我……也想多让老婆侍奉侍奉我啊」", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9191, "蕾娜", "「嘿嘿，好的……交给我吧。啾，唔……」", "len429_068.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9192, "", "即使满脸精液，蕾娜也没有表现出丝毫不情愿，又将我的家伙吞了进去。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9193, "", "接着她又开始深喉。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9194, "蕾娜", "「嗯，啾！嗯，啾，老公……老公，唔，啾！啾！」", "len429_069.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9195, "将臣", "「呃，这……」", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9196, "", "刚射完，很敏感啊。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9197, "", "这样我根本撑不了多久！", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9198, "蕾娜", "「嗯？嘻嘻……老婆……啾，啾……\\n充满了爱意地侍奉……啾」", "len429_070.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9199, "蕾娜", "「老公……你的大●鸡，唔，啾！在我嘴里……抖得可厉害啦」", "len429_071.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9200, "将臣", "「啊，嗯，蕾娜……你越来越厉害了」", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9201, "蕾娜", "「做老婆的……啾，啾！老公哪里更舒服，啾，啾」", "len429_072.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9202, "蕾娜", "「当然，啾……唔……全都知道啊，啾……啾，唔，啊！", "len429_073.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9203, "", "没多久，我就被逼进了死路。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9204, "", "快感再次燃烧起来。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9205, "蕾娜", "「啾！啾……不必忍耐……这次也别忍耐啦，啾啾！」", "len429_074.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9206, "蕾娜", "「跟老婆，啾，忍耐什么呢……啾，啊！」", "len429_075.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9207, "", "啊，我、我……", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9208, "蕾娜", "「唔！？唔，将臣……唔，啾！老公，你怎么开始晃腰了……唔！？」", "len429_076.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9209, "", "我忍耐不住了。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9210, "", "忍耐不住了，开始不由自主地晃动起腰部！", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9211, "蕾娜", "「唔，唔！真、真是的，有这么……舒服吗？啾，嘻嘻，真是……拿你没办法呀，啾」", "len429_077.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9212, "将臣", "「抱歉，抱歉！但是，我已经……」", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9213, "蕾娜", "「好的……好的，老公！唔，继续……继续在我嘴里……啾，啾！」", "len429_078.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9214, "蕾娜", "「在我的嘴逼里射出来吧，老公……老公，唔！？」", "len429_079.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9215, "", "好想射，好想射！干脆射……", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9216, "", "干脆射她嘴里吧！！", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9217, "蕾娜", "「嗯，唔！龟头在嘴里……又变大了……唔！啊……射吧，射吧，老公！」", "len429_080.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9218, "将臣", "「嗯，马上射，蕾娜！全都喝下去吧」", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9219, "蕾娜", "「好的，好的……给我吧，给我吧，老公！啊呜，啾……嗯，啾，唔！」", "len429_081.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9220, "蕾娜", "「大●鸡里面，啾……的精子，全都……射在我嘴里吧！！唔……唔，唔！？」", "len429_082.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9221, "蕾娜", "「唔！？唔！！？」", "len429_083.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9222, "", "就这样，我在蕾娜嘴里释放了自己的欲望。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9223, "蕾娜", "「嗯，唔……呼，唔，还是……这么多啊……嗯，嗯」", "len429_084.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9224, "蕾娜", "「呼，啾……唔，唔……唔，唔……太多了，喝不完呀，啊……」", "len429_085.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9225, "", "阳具每次跳动，都会往她嘴里射出更多的精液。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9226, "", "一些没能被喝完的从她嘴边滴了下来，蕾娜用手指接住，喝了下去。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9227, "蕾娜", "「啾，啾……嘻嘻，我要把……里面剩下来的，啾，啾……也吸出来，啾」", "len429_086.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9228, "蕾娜", "「看我……清扫干净。啾，唔」", "len429_087.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9229, "将臣", "「呃，啊……蕾娜，你这样吸，我……」", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9230, "蕾娜", "「……我知道的……唔，呼……呼……哈」", "len429_088.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9231, "蕾娜", "「唔，啊……啾！老公……老公，舒服起来吧……啾，啾！」", "len429_089.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9232, "", "我任凭快感在体内激荡，任凭蕾娜摆布着我的身体。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9233, "", "一股黏糊糊的热量冲上了我的大脑！", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9234, "蕾娜", "「嗯，啾！嗯，啾……老公你好可爱……我的老公，啾，啾！」", "len429_090.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9235, "蕾娜", "「啾，大●鸡……抖得这么厉害……啾！啾！」", "len429_091.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9236, "将臣", "「啊，啊，我……我又要射了，蕾娜！」", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9237, "蕾娜", "「好的……你可以再舒服点，再舒服点！老公，老公！」", "len429_092.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9238, "", "她舔得那么惬意，我也越来越按捺不住自己的狼情。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9239, "", "我要疼爱蕾娜！一股冲动伴随着爱意奔上心头。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9240, "蕾娜", "「唔，啾！啊呜……呼，啊，射吧，射吧！啾，啾……啾！」", "len429_093.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9241, "将臣", "「嗯，我要射了……可以再射你脸上吗？」", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9242, "蕾娜", "「好的……射脸上！我想用身体……去感受你的温度……唔，啾！」", "len429_094.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9243, "蕾娜", "「所以，所以……啾，啾！来吧，来吧，越多越好……啾，啾！？」", "len429_095.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9244, "蕾娜", "「啊……呼，呀，哇！？」", "len429_096.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9245, "", "最后一瞬，我又将那话儿从她嘴里拔了出来。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9246, "蕾娜", "「啊，啊！又，唔……这么凶猛……嗯，一跳一跳地……啊……」", "len429_097.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9247, "蕾娜", "「将臣的精液……又射在脸上这么多」", "len429_098.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9248, "", "我将奔涌上来的冲动射在了蕾娜脸上。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9249, "", "连续两次接下我的精液，蕾娜的笑容都变得黏糊糊的了。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9250, "蕾娜", "「啊，嗯……呼，将臣……你还有精神吧」", "len429_099.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9251, "将臣", "「嗯……平时这样都完全不够的嘛」", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9252, "将臣", "「话说回来，跟你做，为什么就……做多少次都还生龙活虎的呢？」", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9253, "蕾娜", "「嘻嘻嘻，这一定是因为……你爱我嘛，老公」", "len429_100.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9254, "蕾娜", "「我说……下次能和我一起舒服起来了吧？」", "len429_101.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9255, "将臣", "「……嗯，当然了」", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9256, "", "我弯腰吻了吻蕾娜的额头。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9257, "", "她开心地微笑起来，抱住了我的肩。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9258, "将臣", "「蕾娜？」", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9259, "蕾娜", "「来吧……哈啊、哈啊……我跟你吃了……一样的东西呀」", "len429_102.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9260, "蕾娜", "「所以，我也……唔……已经忍不住了」", "len429_103.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev417a", null], [9261, "蕾娜", "「嗯，我这就……自己把你的大●鸡……塞进来……嗯，啊！！」", "len429_104.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9262, "", "蕾娜抓住我那话儿顶住她自己，然后慢慢把腰沉了下去。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9263, "", "她似乎已经湿透了，一下就把我吞了进去。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9264, "蕾娜", "「唔……能感觉到吗？你的……已经整个沉进来了哦……嗯」", "len429_105.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9265, "将臣", "「天哪，比平时更热，而且……」", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9266, "将臣", "「你已经完全变成了我的形状，跟我紧紧贴在一起啊，蕾娜」", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9267, "蕾娜", "「当然了。嗯，唔！因为……我下面已经……啊，唔」", "len429_106.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9268, "蕾娜", "「一辈子……都只给你一个人用啦。将臣，嗯……吻我，啊」", "len429_107.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9269, "", "我抚摸着蕾娜的脸颊，然后用大拇指按住了她的下巴。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9270, "", "见她迷离的眼神已经做好准备，我就吻了上去。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9271, "蕾娜", "「唔，啾……将臣，啊，唔，啾，唔……啾，啊，啊！」", "len429_108.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9272, "将臣", "「蕾娜，我爱你……」", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9273, "蕾娜", "「我也是……我爱你一辈子，一辈子……啾，啊……啊，啊……啊！」", "len429_109.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9274, "", "我们同时开始了运动。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9275, "", "就像老夫老妻一样，动作步调完全一致。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9276, "蕾娜", "「啾，唔！哇……啊，老公！老公，啊……再用力抱紧我，啊」", "len429_110.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9277, "将臣", "「好的……我不会放开你的」", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9278, "", "我用力抱住她的后背。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9279, "", "接着，蕾娜也穿过我的腋下抱住我的后背，和我紧紧相拥。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9280, "蕾娜", "「啊，将臣！啊，啊……我能感觉到……你的体温，啊！」", "len429_111.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9281, "", "我拥抱着她，一次一次敲打着她的子宫。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9282, "", "里面的褶皱紧紧地贴着我，也有种被拥抱的感觉。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9283, "蕾娜", "「啊，啊！啊，啊……啊，唔，啊！啊……嗯！」", "len429_112.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9284, "", "跟她抱在一起做爱，她那硕大的双乳会紧紧挤压着我。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9285, "", "那弹性刺激着我的本能，让我想和她贴得更紧更紧。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9286, "", "我想要蕾娜！！", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9287, "蕾娜", "「里面，里面顶着！啊，啊，身体的中央……都能感觉到你！」", "len429_113.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9288, "将臣", "「我也一样，全身都能感觉到你啊」", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9289, "蕾娜", "「是啊……是啊，里面都是你……都是老公，啊……啊！啾，嗯」", "len429_114.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9290, "", "我再次用吻塞住了她的嘴，伸出舌头与她的舌头缠绕在一起。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9291, "", "我将那话儿顶在子宫入口处转了转圈，褶皱又紧紧地缠了上来。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9292, "蕾娜", "「啊，啾！唔……嘻嘻，大●鸡和小穴……也在激烈地接吻呀，唔」", "len429_115.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9293, "", "我们在接吻中交换唾液，在性爱中交换爱液和精前液。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9294, "", "简直让人欲罢不能。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9295, "", "不论是上面还是下面，我们都连在一起，速度也越来越快。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9296, "蕾娜", "「啊，啊！哇，啾……老公，老公的东西顶上变大了……哇，啊！」", "len429_116.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9297, "蕾娜", "「这是要……这是要……啊，啊！嗯，啊……啊，啊！」", "len429_117.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9298, "将臣", "「你的子宫……好像也往下沉了些啊」", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9299, "蕾娜", "「我可是你的老婆啊……啊，啊！老公的精华……快点，想要，啊，啊」", "len429_118.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9300, "蕾娜", "「嘻嘻……将臣，今天你可以射在里面吧？嗯，啊」", "len429_119.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9301, "", "我没有理由拒绝她的这般诱惑。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9302, "", "她渴望着和最爱的人上最爱的床，那我为什么不回应她的索求！", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9303, "", "她想要我！我也想要她！", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9304, "蕾娜", "「啊，啊！啊，啊，老公，我说，老公……可以的吧，我亲爱的老公」", "len429_120.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9305, "将臣", "「嗯，当然了！我要射你里面」", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9306, "蕾娜", "「好的……多一点……再多一点！啊，啊……多射一点！啊，啊！」", "len429_121.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9307, "", "我停不下来，也没必要停下来！", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9308, "", "只要继续向着终点冲刺就行了！", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9309, "蕾娜", "「将臣，将臣！我爱你，我爱你！啊，啊，啊！嗯……啊！？」", "len429_122.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9310, "将臣", "「我也是，蕾娜！我爱你，我爱你」", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9311, "蕾娜", "「好的，老公……用我……舒服起来吧，啊，啊！」", "len429_123.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9312, "蕾娜", "「……去了，要去了！我、我也、我也要……啊，啊……啊，啊！」", "len429_124.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9313, "蕾娜", "「爱你，爱你……啊，啊！啊，爱你，爱你爱你爱你，啊！？」", "len429_125.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9314, "蕾娜", "「啊！！！」", "len429_126.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9315, "", "蕾娜用力挺直了背。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9316, "", "同时，她下半身用力一吸，将我的精华尽数榨去。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9317, "蕾娜", "「啊，射了……射了，嗯！在肚子里面……肚子里面都……啊，啊！」", "len429_127.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9318, "蕾娜", "「一次又一次，一次又一次……咻咻的……一直在射，啊……」", "len429_128.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9319, "", "我将龟头塞进子宫口，直接朝着子宫里面不断地发射。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9320, "", "蕾娜则兴奋地颤抖着，用身体的最深处接纳着我。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9321, "蕾娜", "「哈啊，嗯……哈啊，哈啊，你还是……嗯，都第三次了……你的精液……还这么多」", "len429_129.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9322, "将臣", "「嗯……我自己都吃惊」", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9323, "将臣", "「还没完呢。跟你做，我多少次都行」", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9324, "蕾娜", "「……哇噢，真的吗？一般来说……即使吃了特殊的菜品……也做不了四次的吧」", "len429_130.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9325, "将臣", "「你还不知道我？你觉得四次就能结束？」", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9326, "蕾娜", "「嘻嘻嘻，那……就证明给我看吧，将臣。嗯……啊！？」", "len429_131.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9327, "", "我挺了挺腰，表示自己依然坚硬。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9328, "", "接着，我立刻开始继续活动下半身。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9329, "蕾娜", "「啊，啊！啊……嗯，老公真厉害，啊，啊！」", "len429_132.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9330, "", "蕾娜的娇喘也越来越夸张。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9331, "", "同时她紧紧抓着我，贴在我胸口的乳房又是一个挤压。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9332, "蕾娜", "「啊，啊！舒服，好舒服……好想一直做……做多少次都行！」", "len429_133.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9333, "将臣", "「我也是……我都想真的跟你结婚了」", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9334, "蕾娜", "「嘻嘻！嗯……啊，我……不介意啊，啊，啊……老公，啊」", "len429_134.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9335, "", "我们腰撞腰，呼吸叠着呼吸。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9336, "", "两个人一起活动，快感也变得更加强烈。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9337, "蕾娜", "「老公，老公！好舒服……舒服的感觉又要来了！变大了，变大了……啊！」", "len429_135.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9338, "将臣", "「不必忍耐！我……我也和你一起」", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9339, "蕾娜", "「啊，啊！又……又是一起去吗？厉害……我的老公，啊！啊」", "len429_136.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9340, "", "我又开始逐渐被火热的快感支配。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9341, "", "但没关系。我们两个人正在感受同样的快乐。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9342, "蕾娜", "「啊！啊，啊，好烫……老公，好烫！\\n老公，啊，啊！」", "len429_137.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9343, "", "我脑子里一麻，热量一下就在腰部汇聚起来了。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9344, "", "那热量越来越强烈，以至于我几乎无法忍受。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9345, "蕾娜", "「啊！又要去了，又要去了，啊，去了……去了，要去了，啊！？」", "len429_138.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9346, "将臣", "「嗯，我也是……还能射在里面吗？」", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9347, "蕾娜", "「啊，里面！里面更好，老公的……射在里面更好。啊，啊，所以……」", "len429_139.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9348, "蕾娜", "「再来，再来！都射在小穴里面吧，啊！」", "len429_140.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9349, "", "滚烫的快感涌上来了！", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9350, "", "我没有忍耐，也无法忍耐，将它一口气释放出来！", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9351, "蕾娜", "「啊，啊，老公……老公，射吧！射吧，射里面，啊，啊！」", "len429_141.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9352, "将臣", "「要射了，我要射了，射在你的里面！」", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9353, "蕾娜", "「来吧，来吧，将臣！我也……我也要去了！啊，啊……啊！」", "len429_142.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9354, "蕾娜", "「啊，啊！啊，去了……去了，要去了，啊，啊，啊！啊」", "len429_143.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9355, "蕾娜", "「嗯，啊！啊，啊……去了！去了去了去了，啊……啊，啊，啊！？」", "len429_144.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9356, "蕾娜", "「啊！！！」", "len429_145.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9357, "", "蕾娜紧紧抱着我，身子开始猛地发颤。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9358, "", "我也紧紧抱住蕾娜，将精液射在了她的最深处。一边射还一边继续晃腰。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9359, "蕾娜", "「啊……射吧，老公，啊！都、都在射了，在射了……却还在动……啊！」", "len429_146.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9360, "将臣", "「再来一次！再来一次吧，蕾娜，蕾娜！」", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9361, "蕾娜", "「啊！将臣，将臣……可、可是，我还……很敏感，啊！」", "len429_147.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9362, "", "嘴上这么说，蕾娜的腰可没停。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9363, "", "她依然用最后冲刺的气势，激烈地索求着我。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9364, "蕾娜", "「啊，那么敏感，那么敏感，啊！啊，啊！太敏感啊……啊，啊！？」", "len429_148.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9365, "蕾娜", "「这，这……太舒服了！！啊！」", "len429_149.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9366, "", "我也是，我也是啊！下一次肯定很快就会结束。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9367, "", "所以，所以我更要射到最后一滴！", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9368, "蕾娜", "「啊，啊！啊，啊！又要去了，去了，要去了！啊，啊！」", "len429_150.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9369, "将臣", "「蕾娜，蕾娜！我也……我也要一口气……」", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9370, "蕾娜", "「啊，唔……好开心。今天……你为了我，为了我做了这么多次，啊！啊」", "len429_151.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9371, "蕾娜", "「嗯，老公，我的老公，最后一次……最后一次，你就射在喜欢的地方……啊！？」", "len429_152.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9372, "", "我决定……", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9373, "蕾娜", "「啊，啊！啊，老公，老公，啊……又这么激烈，啊！」", "len429_153.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9374, "", "今天要把所有的所有都射在她的里面！", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9375, "", "我要把全部精子都拿去填满她的子宫！", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9376, "蕾娜", "「里面，子宫……子宫……在被大●鸡吻着呢，啊，啊！」", "len429_154.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9377, "将臣", "「是啊，我再来填满你，再填满你一次！」", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9378, "蕾娜", "「好的，老公，老公……射吧，啊，啊！让老婆……怀孕吧，啊！」", "len429_155.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9379, "", "快感将我的视野染成一片白色。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9380, "", "好烫，好烫，我的身体都要溶化了！", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9381, "蕾娜", "「啊，啊！啊……啊，不行了！不行，要去了，去了去了去了！要去了！」", "len429_156.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9382, "将臣", "「嗯，来吧，来吧！这是最后一次了！」", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9383, "蕾娜", "「啊，啊！啊，好的……好的，老公，老公……最后一次，最后一次了」", "len429_157.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9384, "蕾娜", "「啊！一起……一起舒服吧……啊，啊！啊……啊！？」", "len429_158.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9385, "蕾娜", "「去了，去了！不行，不行，去了去了去了，啊！！」", "len429_159.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9386, "蕾娜", "「啊！！！」", "len429_160.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9387, "", "这就是最后一次了！最后一次我也要射在蕾娜的最深处。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9388, "蕾娜", "「啊，好烫！这么烫，啊……在里面，在里面……跳着呢，啊」", "len429_161.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9389, "蕾娜", "「小穴里面……被彻底、彻底填满了，啊……啊」", "len429_162.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9390, "", "蕾娜的下体用力箍着我，但我的下体也颤抖得毫不留情。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9391, "", "连射三次。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9392, "", "我将那可能让她怀孕的体液全部灌进了她的子宫。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9393, "蕾娜", "「呼……呼……将臣，嗯，嗯，肚子里……好暖」", "len429_163.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9394, "将臣", "「是啊，我一滴不剩都灌进老婆肚子里去了」", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9395, "蕾娜", "「嗯……所以……我感觉到了满满的……满满的幸福♪」", "len429_164.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9396, "蕾娜", "「唔，啾！啊……将臣，啾……最、最后一次，你打算一边吻一边射吗？唔，啾！」", "len429_165.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9397, "", "爱她，好爱她！我满脑子都只有这种想法。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9398, "", "我想让彼此的身体更紧密地牵系在一起！", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9399, "蕾娜", "「啾！啾……啊！脑袋里麻麻的，啾……嗯！感觉要溶化了，啊！」", "len429_166.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9400, "将臣", "「是啊，那就溶化掉吧，这样就能和你混合在一起了！」", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9401, "蕾娜", "「嗯，啊！好的，啾……和你一起，啾，啊……感觉也不错，啊！」", "len429_167.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9402, "", "继续，继续！用溶在一起的气势！", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9403, "", "我们紧紧抱在一起，一边接吻，一边迎接欲望的极限。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9404, "蕾娜", "「唔……啊！去了……要去了，要去了，唔，啊！啾，嗯！」", "len429_168.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9405, "将臣", "「蕾娜，蕾娜！我爱你，比任何人都爱你！」", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9406, "蕾娜", "「啾，啊……我也是，我也是，我是全世界最爱你的，啾……啊！」", "len429_169.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9407, "蕾娜", "「将臣，将臣！爱你，我爱你……我的所有……都属于你哦，啊」", "len429_170.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9408, "蕾娜", "「啾，唔！啊……啊啊啊，将臣，将臣，啊！？」", "len429_171.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9409, "蕾娜", "「啊！！！」", "len429_172.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9410, "", "最后一次……", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9411, "", "我用力抽开身体，将大量精液喷射在了她的身上。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9412, "蕾娜", "「啊……拔出去了！啊，啊……暖暖的……全都，全都……射出来了，啊！」", "len429_173.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9413, "蕾娜", "「里面也有，外面也有，嗯……全都染上了将臣的颜色，嘻嘻♪」", "len429_174.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9414, "", "我射得这么多，喷遍了蕾娜的全身，完全不像第五次。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9415, "", "蕾娜晃了晃她纤细的身体，用腰贴住了我的下体，直到我射干净。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9416, "蕾娜", "「啊，嗯……呼，啊……将臣……你满足了吗？」", "len429_175.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9417, "将臣", "「嗯……你的身体真是太棒了」", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9418, "蕾娜", "「嘿嘿，你的大●鸡也是……超舒服的，嗯」", "len429_176.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9419, "", "接着，蕾娜将身体靠了过来。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9420, "", "我帮她理了理满是汗水的刘海，然后再次温柔地吻了她一下。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9421, "蕾娜", "「啾……将臣，啾，啾」", "len429_177.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9422, "将臣", "「蕾娜……蕾娜……」", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9423, "蕾娜", "「嘻嘻，今天的新婚游戏……回忆起来是不是很棒？」", "len429_178.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9424, "将臣", "「……说实话，我感觉自己一辈子都不会忘」", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9425, "将臣", "「但是」", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9426, "蕾娜", "「……什么？」", "len429_179.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9427, "将臣", "「和你一同度过的任何一段回忆，我都毕生难忘」", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9428, "蕾娜", "「我觉得我应该也是」", "len429_180.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9429, "蕾娜", "「但是……我不在的这三天，你还是会寂寞的吧？」", "len429_181.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9430, "将臣", "「是啊」", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9431, "将臣", "「你之前才教过我，要怎么辨认星星……」", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9432, "", "那原本是让远在两地的人忍耐寂寞的办法。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9433, "将臣", "「可是，一想到要和你……」", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9434, "蕾娜", "「……我也是，一想到要和你……」", "len429_182.ogg", "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9435, "", "我们不想分别，哪怕只有片刻。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9436, "", "在我们俩必须考虑未来的事情时……", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null], [9437, "", "这种心情将会变得非常重要。", null, "画面_黒", "bgm14.opus", null, "SEC-429", "ev418a", null]];
